(function(){"use strict";var w=window.ScripturaJosephusTexts||(window.ScripturaJosephusTexts={});var a=w.antiguidades||(w.antiguidades={});a[9]={"book":9,"title":"Τάδε ἔνεστιν ἐν τῇ ἐνάτῃ τῶν Ἰωσήπου ἱστοριῶν τῆς Ἰουδαϊκῆς ἀρχαιολογίας.","argument":{"title":"","text":"α. Ὡς στρατευσάμενος ὁ Ἀχάβου παῖς Ἰώραμος ἐπὶ Μωαβίτας ἐκράτησεν αὐτῶν.\n\nβ. ὡς ὁ ὁμώνυμος αὐτῷ Ἰώραμος βασιλεύων τῶν Ἱεροσολυμιτῶν τὴν ἀρχὴν πᾶσαν λαβὼν τούς τε ἀδελφοὺς καὶ τοὺς πατρῴους φίλους ἀπέκτεινεν.\n\nγ. ὅτι τῆς Ἰδουμαίας ἀποστάσης καὶ στρατευσάντων ἐπ' αὐτὸν Ἀράβων ἥ τε δύναμις αὐτοῦ πᾶσα διεφθάρη καὶ οἱ παῖδες αὐτοῦ πάρεξ ἑνὸς ὄντος ἔτι νηπίου καὶ πρὸς τούτοις αὐτὸς ἀσεβὴς γενόμενος κακῶς τὸν βίον κατέστρεψεν.\n\nδ. στρατεία τοῦ Σύρων καὶ Δαμασκοῦ βασιλέως ἐπὶ τὸν τῶν Ἰσραηλιτῶν βασιλέα Ἰώραμον καὶ πῶς πολιορκηθεὶς οὗτος ἐν Σαμαρείᾳ παραδόξως τὸν κίνδυνον διέφυγεν.\n\nε. ὡς αὐτὸς Ἰώραμος ἀπέθανεν ὑπὸ Ἰηοῦ ἀναιρεθεὶς τοῦ ἱππάρχου καὶ ἡ γενεὰ αὐτοῦ καὶ ὁ τῶν Ἱεροσολύμων βασιλεὺς Ὀχοζίας.\n\nϛ. ὅτι μετὰ τὴν τούτου τελευτὴν ὁ Ἰηοῦς ἐβασίλευσε τῶν Ἰσραηλιτῶν ἐν Σαμαρείᾳ διατρίβων καὶ οἱ παῖδες αὐτοῦ ἐπὶ γενεὰς τέσσαρας.\n\nζ. ὡς γυνή τις Ὀθλία τοὔνομα τῶν Ἱεροσολυμιτῶν ἐβασίλευσεν ἐπὶ ἔτη πέντε καὶ ἀνελὼν αὐτὴν ὁ ἀρχιερεὺς Ἰώδας τὸν Ὀχοζίου παῖδα Ἰωάσην ἀπέδειξε βασιλέα.\n\nη. Ἀζαήλου τοῦ Δαμασκηνῶν βασιλέως ἐπὶ τοὺς Ἰσραηλίτας στρατεία καὶ ὡς πολλὰ κακὰ τήν τε χώραν αὐτῶν διαθεὶς καὶ τὴν Σαμαρέων πόλιν ὀλίγῳ πάλιν ὕστερον χρόνῳ στρατεύσας ἐπὶ τοὺς Ἱεροσολυμίτας καὶ πολλὰ χρήματα λαβὼν παρὰ τοῦ βασιλέως αὐτῶν εἰς Δαμασκὸν ἀνέζευξεν.\n\nθ. ὡς Ἀμασίας ὁ τῶν Ἱεροσολυμιτῶν βασιλεὺς στρατευσάμενος ἐπὶ Ἰδουμαίους καὶ Ἀμαληκίτας ἐνίκησεν.\n\nι. ὡς αὐτὸς οὗτος πολεμῶν πρὸς τὸν Ἰσραηλιτῶν βασιλέα Ἰώασον ἡττᾶται μέν, ληφθεὶς δὲ αἰχμάλωτος καὶ πολλὰ χρήματα δοὺς ἀπελύθη πάλιν εἰς τὴν ἑαυτοῦ βασιλείαν καὶ ὡς ὁ παῖς αὐτοῦ Ὀζίας τὰ πέριξ ἔθνη ἐχειρώσατο.\n\nια. στρατεία τοῦ τῶν Ἰσραηλιτῶν βασιλέως Ἱεροβάμου ἐπὶ Συρίαν καὶ νίκη.\n\nιβ. ὡς ὁ τῶν Ἀσσυρίων βασιλεὺς στρατευσάμενος ἐπὶ Σαμάρειαν καὶ πολλὰ χρήματα παρὰ Φακέα τοῦ βασιλέως αὐτῶν εἰσπραξάμενος εἰς τὴν οἰκείαν ὑπέστρεψεν.\n\nιγ . ὅτι στρατευσάμενος Ῥαασσεὶν ὁ Δαμασκοῦ βασιλεὺς ἐπὶ Ἱεροσολυμίτας ἠνάγκασεν Ἀχάζην τὸν βασιλέα πέμψαντα χρήματα πολλὰ πρὸς τὸν βασιλέα Ἀσσυρίων πεῖσαι τούτοις αὐτὸν ἐπὶ Δαμασκὸν στρατεύσασθαι.\n\nιδ. ὡς κατὰ κράτος εἷλεν ὁ τῶν Ἀσσυρίων βασιλεὺς Δαμασκὸν καὶ διέφθειρε μὲν αὐτῶν τὸν βασιλέα, τοὺς δὲ ἀνθρώπους ἀναστήσας εἰς Μηδίαν ἕτερα ἔθνη κατῴκισεν ἐν Δαμασκῷ.\n\nιε. ὡς Σαλμανάσαρ ὁ τῶν Ἀσσυρίων βασιλεὺς στρατευσάμενος ἐπὶ Σαμάρειαν καὶ πέντε πολιορκήσας ἔτεσιν ἐν αὐτῇ τὸν τῶν Ἰσραηλιτῶν βασιλέα Ὠσῆν παραστησάμενος τὴν πόλιν ἀπέκτεινεν,\n\nιϛ. καὶ ὡς ὁ Ἀσσύριος τὰς δέκα τῶν Ἰσραηλιτῶν φυλὰς εἰς τὴν Μηδίαν κατοικίσας ἐκ τῆς Περσίδος τὸ τῶν Χουθαίων ἔθνος εἰς τὴν ἐκείνων μετήγαγε χώραν, οὓς Ἕλληνες Σαμαρεῖς καλοῦσιν.\n\nπεριέχει ἡ βίβλος χρόνον ἐτῶν ἑκατὸν καὶ πεντήκοντα καὶ ζ μηνῶν."},"chapters":{"1":[{"number":1,"text":"Ἰωσαφάτῃ δὲ τῷ βασιλεῖ παραγενομένῳ εἰς Ἱεροσόλυμα ἀπὸ τῆς συμμαχίας τῆς πρὸς Ἄχαβον τὸν τῶν Ἰσραηλιτῶν βασιλέα, ἣν Ἄδερι τῷ Σύρων πολεμοῦντι βασιλεῖ παρασχὼν ἦν ὡς προειρήκαμεν, Ἰηοῦς ὁ προφήτης συντυχὼν ᾐτιᾶτο τῆς πρὸς Ἄχαβον συμμαχίας ἄνθρωπον ἀσεβῆ καὶ πονηρόν· τὸν γὰρ θεὸν ἀηδῶς μὲν ἐπὶ τούτῳ διατεθῆναι, ῥύσασθαι μέντοι καίπερ ἡμαρτηκότα διὰ τὴν ἰδίαν αὐτοῦ φύσιν οὖσαν ἀγαθὴν ἔλεγεν ἐκ τῶν πολεμίων."},{"number":2,"text":"καὶ τότε μὲν ἐπʼ εὐχαριστίας καὶ θυσίας ὁ βασιλεὺς τρέπεται τοῦ θεοῦ· μετὰ ταῦτα δὲ τὴν χώραν ὥρμησεν περιερχόμενος ἐν κύκλῳ πᾶσαν ὅσης αὐτὸς ἐπῆρχε τὸν λαὸν ἐκδιδάσκειν τά τε νόμιμα τὰ διὰ Μωσήους ὑπὸ θεοῦ δοθέντα καὶ τὴν εὐσέβειαν τὴν πρὸς αὐτόν."},{"number":3,"text":"καὶ δικαστὰς ἀποδείξας ἐν ἑκάστῃ πόλει τῶν βασιλευομένων ὑπʼ αὐτοῦ παρεκελεύσατο μηδενὸς οὕτως ὡς τοῦ δικαίου προνοουμένους κρίνειν τοῖς ὄχλοις μήτε δώρων μήτε ἀξιώματος τῶν ἐν ὑπεροχῇ διὰ πλοῦτον ἢ γένος εἶναι δοκούντων, βραβεύειν δὲ ἅπασι τὸ ἴσον ἐπισταμένους, ὅτι καὶ τῶν κρύφα πραττομένων ἕκαστον ὁ θεὸς βλέπει."},{"number":4,"text":"ταῦτα διδάξας κατὰ πόλιν ἑκάστην τῶν δύο φυλῶν ὑπέστρεψεν εἰς Ἱεροσόλυμα, κατέστησε δὲ καὶ ἐν τούτοις κριτὰς ἐκ τῶν ἱερέων καὶ τῶν Ληουιτῶν καὶ τῶν τὰ πρῶτα τοῦ πλήθους φερομένων παραινέσας ἐπιμελεῖς καὶ δικαίας ποιεῖσθαι πάσας τὰς κρίσεις·"},{"number":5,"text":"ἂν δὲ περὶ μειζόνων διαφορὰν ἔχοντες τῶν ὁμοφύλων τινὲς ἐκ τῶν ἄλλων πρὸς αὐτοὺς πέμψωσι πόλεων, τούτοις δὲ μετὰ πλείονος σπουδῆς ἀποφαίνεσθαι δικαίως περὶ τῶν πραγμάτων· μάλιστα γὰρ τὰς ἐν ταύτῃ τῇ πόλει κρίσεις, ἐν ᾗ τόν τε ναὸν εἶναι τοῦ θεοῦ συμβέβηκε καὶ δίαιταν ὁ βασιλεὺς ἔχει, προσῆκε σπουδαίας εἶναι καὶ δικαιοτάτας."},{"number":6,"text":"ἄρχοντας δʼ αὐτῶν ἀποδείκνυσιν Ἀμασίαν τὸν ἱερέα καὶ Ζαβαδίαν ἐκ τῆς Ἰούδα φυλῆς ἑκατέρους. καὶ ὁ μὲν βασιλεὺς τοῦτον τὸν τρόπον διέτασσε τὰ πράγματα."},{"number":7,"text":"Κατὰ δὲ τὸν αὐτὸν καιρὸν ἐστράτευον ἐπʼ αὐτὸν Μωαβῖται καὶ Ἀμμανῖται συμπαραλαβόντες καὶ Ἀράβων μεγάλην μοῖραν, καὶ καταστρατοπεδεύονται πρὸς Ἐγγάδῃ πόλει κειμένῃ πρὸς τῇ Ἀσφαλτίδι λίμνῃ τριακοσίους ἀπεχούσῃ σταδίους τῶν Ἱεροσολύμων· γεννᾶται δʼ ἐν αὐτῇ φοίνιξ ὁ κάλλιστος καὶ ὀποβάλσαμον."},{"number":8,"text":"ἀκούσας δʼ Ἰωσαφάτης, ὅτι τὴν λίμνην διαβάντες οἱ πολέμιοι ἐμβεβλήκασιν ἤδη εἰς τὴν βασιλευομένην ὑπʼ αὐτοῦ χώραν, δείσας εἰς ἐκκλησίαν συνάγει τὸν δῆμον τῶν Ἱεροσολυμιτῶν εἰς τὸ ἱερόν, καὶ στὰς κατὰ πρόσωπον τοῦ ναοῦ ηὔχετο καὶ ἐπεκαλεῖτο τὸν θεὸν παρασχεῖν αὐτῷ δύναμιν καὶ ἰσχύν, ὥστε τιμωρήσασθαι τοὺς ἐπιστρατεύσαντας·"},{"number":9,"text":"καὶ γὰρ τοῦτο δεηθῆναι τοὺς τὸ ἱερὸν κατασκευασαμένους αὐτοῦ, ὅπως ὑπερμάχηται τῆς πόλεως ἐκείνης καὶ τοὺς ἐπʼ αὐτὸ τολμήσαντας ἐλθεῖν ἀμύνηται, οἳ τὴν ὑπʼ αὐτοῦ δοθεῖσαν γῆν εἰς κατοίκησιν ἀφελέσθαι πάρεισιν αὐτούς. ταῦτʼ εὐχόμενος ἐδάκρυε καὶ σύμπαν δὲ τὸ πλῆθος γυναιξὶν ἅμα καὶ τέκνοις ἱκέτευεν."},{"number":10,"text":"Ἰαζίηλος δέ τις προφήτης παρελθὼν εἰς μέσην τὴν ἐκκλησίαν ἀνεβόησε τῷ τε πλήθει λέγων καὶ τῷ βασιλεῖ, τὸν θεὸν ἐπακοῦσαι τῶν εὐχῶν καὶ πολεμήσειν αὐτὸν τοῖς ἐχθροῖς ἐπαγγέλλεσθαι. προσέταξε δὲ τῇ ἐπιούσῃ τὴν στρατιὰν ἐξελάσαντα τοῖς πολεμίοις ὑπαντᾶν·"},{"number":11,"text":"εὑρήσειν γὰρ αὐτοὺς ἐπὶ τῆς μεταξὺ Ἱεροσολύμων καὶ Ἐγγάδης ἀναβάσεως λεγομένης δʼ Ἐξοχῆς· καὶ μὴ συμβαλεῖν μὲν αὐτοῖς, στάντας δὲ μόνον ὁρᾶν, πῶς αὐτοῖς μάχεται τὸ θεῖον. τοῦ δὲ προφήτου ταῦτʼ εἰπόντος ὁ μὲν βασιλεὺς καὶ τὸ πλῆθος πεσόντες ἐπὶ πρόσωπον ηὐχαρίστουν τῷ θεῷ καὶ προσεκύνουν, οἱ δὲ Ληουῖται τοῖς ὀργάνοις διετέλουν ὑμνοῦντες."},{"number":12,"text":"Ἅμα δʼ ἡμέρᾳ προελθὼν ὁ βασιλεὺς εἰς τὴν ἔρημον τὴν ὑποκάτω Θεκώας πόλεως ἔλεγε πρὸς τὸ πλῆθος, ὡς δεῖ πιστεύειν τοῖς ὑπὸ τοῦ προφήτου εἰρημένοις καὶ μὴ παρατάσσεσθαι μὲν αὐτοὺς εἰς μάχην, προστησαμένους δὲ τοὺς ἱερεῖς μετὰ τῶν σαλπίγγων καὶ Ληουιτῶν εὐχαριστεῖν ὡς ἤδη ῥυσαμένῳ τὴν χώραν ἡμῶν παρὰ τῶν πολεμίων."},{"number":13,"text":"ἤρεσε δὲ ἡ τοῦ βασιλέως γνώμη, καὶ ἅπερ συνεβούλευσε ταῦτʼ ἔπραττον. ὁ δὲ θεὸς εἰς φόβον ἐνέβαλε καὶ ταραχὴν τοὺς Ἀμμανίτας· οἱ δὲ δόξαντες ἀλλήλους πολεμίους ἀπέκτεινον, ὡς ἐκ τῆς τοσαύτης στρατιᾶς ἀνασωθῆναι μηδένα."},{"number":14,"text":"Ἰωσαφάτης δὲ ἀποβλέψας εἰς τὴν φάραγγα, ἐν ᾗ συνέβαινʼ ἐστρατοπεδευκέναι τοὺς πολεμίους, καὶ πλήρη νεκρῶν ἰδὼν ἥσθη μὲν ἐπὶ τῷ παραδόξῳ τῆς τοῦ θεοῦ βοηθείας, ὅτι μηδὲ πονήσασιν αὐτοῖς αὐτὸς διʼ αὑτοῦ τὴν νίκην ἔδωκεν, ἐπέτρεψε δὲ τῇ στρατιᾷ διαρπάσαι τὴν παρεμβολὴν τῶν ἐχθρῶν καὶ σκυλεῦσαι τοὺς νεκρούς."},{"number":15,"text":"καὶ οἱ μὲν ἐπὶ τρεῖς ἡμέρας σκυλεύοντες ἔκαμον· τοσοῦτον ἦν τὸ τῶν ἀνῃρημένων πλῆθος· τῇ τετάρτῃ δὲ συναθροισθεὶς πᾶς ὁ λαὸς εἴς τινα κοῖλον καὶ φαραγγώδη τόπον τὴν τοῦ θεοῦ δύναμιν καὶ τὴν συμμαχίαν εὐλόγησαν, ἀφʼ οὗ καὶ προσηγορίαν ἔσχεν ὁ τόπος κοιλὰς εὐλογίας."},{"number":16,"text":"Ἐκεῖθεν δὲ ἀναγαγὼν τὴν στρατιὰν ὁ βασιλεὺς εἰς Ἱεροσόλυμα τρέπεται πρὸς εὐωχίαν καὶ θυσίας ἐπὶ πολλὰς ἡμέρας. μετὰ μέντοι γε τὴν τῶν πολεμίων αὐτοῦ διαφθορὰν ἀκουσθεῖσαν τοῖς ἀλλοφύλοις ἔθνεσι πάντες οὗτοι κατεπλάγησαν αὐτόν, ὡς φανερῶς αὐτῷ τοῦ θεοῦ τὸ λοιπὸν συμμαχοῦντος. καὶ Ἰωσαφάτης μὲν ἔκτοτε μετὰ λαμπρᾶς δόξης ἐπί τε δικαιοσύνῃ καὶ τῇ πρὸς τὸ θεῖον εὐσεβείᾳ διῆγεν·"},{"number":17,"text":"ἦν δὲ φίλος καὶ τῷ τοῦ Ἀχάβου παιδὶ βασιλεύοντι τῶν Ἰσραηλιτῶν, πρὸς ὃν κοινωνήσας ἐπὶ κατασκευῇ νεῶν εἴς τε Πόντον πλεουσῶν καὶ τὰ ἐπὶ Θρᾴκης ἐμπόρια διήμαρτε τοῦ κτήματος· ὑπὸ γὰρ μεγέθους ἀπώλετο τὰ σκάφη· καὶ διὰ τοῦτο οὐκέτι περὶ ναῦς ἐφιλοτιμήσατο. τὰ μὲν οὖν περὶ τὸν Ἱεροσολύμων βασιλέα Ἰωσαφάτην οὕτως εἶχεν."}],"2":[{"number":18,"text":"Ὁ δʼ Ἀχάβου παῖς Ὀχοζίας ἐβασίλευε τῶν Ἰσραηλιτῶν ἐν Σαμαρείᾳ ποιούμενος τὴν δίαιταν, πονηρὸς ὢν καὶ πάντα ὅμοιος τοῖς γονεῦσιν ἀμφοτέροις καὶ Ἱεροβοάμῳ τῷ πρώτῳ παρανομήσαντι καὶ τὸν λαὸν ἀπατᾶν ἀρξαμένῳ."},{"number":19,"text":"τὴν δὲ βασιλείαν ἔτος ἤδη δεύτερον ἔχοντος ὁ τῶν Μωαβιτῶν ἀφίσταται βασιλεὺς αὐτοῦ καὶ τοὺς φόρους, οὓς ἔμπροσθεν ἐτέλει τῷ πατρὶ αὐτοῦ Ἀχάβῳ, χορηγῶν ἐπαύσατο. συνέβη δὲ τὸν Ὀχοζίαν καταβαίνοντα ἀπὸ τοῦ τέγους τῆς οἰκίας κατενεχθῆναι καὶ νοσήσαντα πέμψαι πρὸς τὴν Ἀκκάρων θεὸν Μυῖαν, τοῦτο γὰρ ἦν ὄνομα τῇ θεῷ, πυνθάνεσθαι περὶ τῆς σωτηρίας."},{"number":20,"text":"φανεὶς δὲ ὁ τῶν Ἑβραίων θεὸς Ἠλίᾳ τῷ προφήτῃ προσέταξεν αὐτῷ τοῖς πεμφθεῖσιν ἀγγέλοις ὑπαντήσαντι πυνθάνεσθαι αὐτῶν, εἰ θεὸν ὁ Ἰσραηλιτῶν λαὸς ἴδιον οὐκ ἔχει, ὅτι πέμπει πρὸς τὸν ἀλλότριον βασιλεὺς αὐτῶν περὶ τῆς σωτηρίας ἐρησομένους, κελεῦσαί τε αὐτοὺς ὑποστρέψαι καὶ φράσαι τῷ βασιλεῖ, ὅτι μὴ διαφεύξεται τὴν νόσον."},{"number":21,"text":"τοῦ δὲ Ἠλία ποιήσαντος ἃ προσέταξεν ὁ θεὸς ἀκούσαντες οἱ ἄγγελοι τὰ παρʼ αὐτοῦ παραχρῆμα ὑπέστρεψαν πρὸς τὸν βασιλέα. θαυμάζοντος δὲ τὸ τάχος τῆς ἐπανόδου καὶ τὴν αἰτίαν ἐρωτήσαντος ἔφασαν ἀπαντῆσαί τινα αὐτοῖς ἄνθρωπον καὶ κωλῦσαι μὲν προσωτέρω χωρεῖν, ἀναστρέψαντας δέ σοι λέγειν ἐξ ἐντολῆς τοῦ Ἰσραηλιτῶν θεοῦ, ὅτι κάκιον ἕξει ἡ νόσος."},{"number":22,"text":"τοῦ δὲ βασιλέως σημαίνειν αὐτῷ τὸν ταῦτʼ εἰρηκότα κελεύσαντος, ἄνθρωπον ἔλεγον δασὺν καὶ ζώνην περιειλημμένον δερματίνην. συνεὶς δὲ ἐκ τούτων Ἠλίαν εἶναι τὸν σημαινόμενον ὑπὸ τῶν ἀγγέλων πέμψας πρὸς αὐτὸν ταξίαρχον καὶ πεντήκοντα ὁπλίτας ἀχθῆναι αὐτὸν ἐκέλευσεν."},{"number":23,"text":"εὑρὼν δὲ τὸν Ἠλίαν ὁ πεμφθεὶς ταξίαρχος ἐπὶ τῆς κορυφῆς τοῦ ὄρους καθεζόμενον καταβάντα ἥκειν ἐκέλευε πρὸς τὸν βασιλέα· κελεύειν γὰρ τοῦτο ἐκεῖνον· εἰ δὲ μὴ θελήσειεν, ἄκοντα βιάσεσθαι. ὁ δὲ εἰπὼν πρὸς αὐτὸν ἐπὶ πείρᾳ τοῦ προφήτης ἀληθὴς ὑπάρχειν εὔξεσθαι πῦρ ἀπʼ οὐρανοῦ πεσὸν ἀπολέσαι τούς τε στρατιώτας καὶ αὐτὸν εὔχεται, καὶ πρηστὴρ κατενεχθεὶς διαφθείρει τόν τε ταξίαρχον καὶ τοὺς σὺν αὐτῷ."},{"number":24,"text":"τῆς δὲ ἀπωλείας τῆς τούτων δηλωθείσης τῷ βασιλεῖ παροξυνθεὶς ἄλλον ταξίαρχον πέμπει ἐπὶ τὸν Ἠλίαν σὺν ὁπλίταις τοσούτοις, ὅσοις καὶ τὸν πρότερον συναπέστειλεν. ἀπειλήσαντος δὲ καὶ τούτου τῷ προφήτῃ βίᾳ λαβόντα ἄξειν αὐτὸν εἰ μὴ κατέλθοι βουλόμενος, εὐξαμένου κατʼ αὐτοῦ πῦρ διεχρήσατο καθὼς καὶ τὸν πρὸ αὐτοῦ ταξίαρχον."},{"number":25,"text":"πυνθανόμενος δὲ καὶ τὰ περὶ τοῦτον ὁ βασιλεὺς τρίτον ἐξέπεμψεν. ὁ δὲ φρόνιμος ὢν καὶ λίαν ἐπιεικὴς τὸ ἦθος ἐλθὼν ἐπὶ τὸν τόπον, οὗ συνέβαινεν εἶναι τὸν Ἠλίαν, φιλοφρόνως προσεῖπεν αὐτόν· γινώσκειν δʼ ἔλεγεν, ὅτι μὴ βουλόμενος βασιλικῷ διακονῶν προστάγματι παρείη πρὸς αὐτόν, καὶ οἱ πρὸ αὐτοῦ πεμφθέντες οὐχ ἑκόντες ἀλλὰ κατὰ τὴν αὐτὴν αἰτίαν ἦλθον· ἐλεῆσαι τοιγαροῦν αὐτὸν ἠξίου τούς τε σὺν αὐτῷ παρόντας ὁπλίτας καὶ καταβάντα ἕπεσθαι πρὸς τὸν βασιλέα."},{"number":26,"text":"ἀποδεξάμενος δὲ τὴν δεξιότητα τῶν λόγων καὶ τὸ ἀστεῖον τοῦ ἤθους ὁ Ἠλίας καταβὰς ἠκολούθησε. παραγενόμενος δὲ πρὸς τὸν βασιλέα προεφήτευσεν αὐτῷ καὶ τὸν θεὸν ἐδήλου λέγειν· ἐπειδὴ κατέγνως μὲν αὐτοῦ ὡς οὐκ ὄντος θεοῦ καὶ περὶ τῆς νόσου οὐ τἀληθὲς προειπεῖν δυναμένου, πρὸς δὲ τὸν Ἀκκαρωνιτῶν ἔπεμπες παρʼ αὐτοῦ πυνθανόμενος ποδαπὸν ἔσται σοι τῆς νόσου τέλος, γίνωσκε ὅτι τεθνήξῃ."},{"number":27,"text":"Καὶ ὁ μὲν ὀλίγου σφόδρα χρόνου διελθόντος καθὼς προεῖπεν Ἠλίας ἀπέθανε, διαδέχεται δʼ αὐτοῦ τὴν βασιλείαν ὁ ἀδελφὸς Ἰώραμος· ἄπαις γὰρ κατέστρεψε τὸν βίον. ὁ δὲ Ἰώραμος οὗτος τῷ πατρὶ Ἀχάβῳ τὴν πονηρίαν παραπλήσιος γενόμενος ἐβασίλευσεν ἔτη δώδεκα πάσῃ παρανομίᾳ χρησάμενος καὶ ἀσεβείᾳ πρὸς τὸν θεόν· παρεὶς γὰρ τοῦτον θρησκεύειν τοὺς ξενικοὺς ἐσέβετο·"},{"number":28,"text":"ἦν δὲ τἆλλα δραστήριος. κατʼ ἐκεῖνον δὲ τὸν καιρὸν Ἠλίας ἐξ ἀνθρώπων ἠφανίσθη καὶ οὐδεὶς ἔγνω μέχρι τῆς σήμερον αὐτοῦ τὴν τελευτήν· μαθητὴν δὲ Ἐλισσαῖον κατέλιπεν, ὡς καὶ πρότερον ἐδηλώσαμεν. περὶ μέντοι γε Ἠλία καὶ Ἐνώχου τοῦ γενομένου πρὸ τῆς ἐπομβρίας ἐν ταῖς ἱεραῖς ἀναγέγραπται βίβλοις, ὅτι γεγόνασιν ἀφανεῖς, θάνατον δʼ αὐτῶν οὐδεὶς οἶδεν."}],"3":[{"number":29,"text":"Παραλαβὼν δὲ τὴν βασιλείαν Ἰώραμος ἐπὶ τὸν Μωαβιτῶν ἔγνω στρατεύειν βασιλέα Μεισὰν ὄνομα· τοῦ γὰρ ἀδελφοῦ αὐτοῦ, καθὼς προείπαμεν, ἔτυχεν ἀποστὰς φόρους τελῶν Ἀχάβῳ τῷ πατρὶ αὐτοῦ μυριάδας εἴκοσι προβάτων σὺν τοῖς πόκοις."},{"number":30,"text":"συναθροίσας οὖν τὴν οἰκείαν δύναμιν ἔπεμψε πρὸς Ἰωσαφάτην παρακαλῶν αὐτόν, ἐπεὶ φίλος ἀπʼ ἀρχῆς ὑπῆρχεν αὐτοῦ τῷ πατρί, συμμαχῆσαι πόλεμον ἐπὶ τοὺς Μωαβίτας ἐκφέρειν μέλλοντι ἀποστάντας αὐτοῦ τῆς βασιλείας. ὁ δʼ οὐ μόνον αὐτὸς βοηθήσειν ὑπέσχετο, ἀλλὰ καὶ τὸν Ἰδουμαίων βασιλέα συναναγκάσειν ὄντα ὑφʼ ἑαυτὸν συστρατεύσασθαι."},{"number":31,"text":"Ἰώραμος δὲ τοιούτων αὐτῷ τῶν παρὰ Ἰωσαφάτου περὶ τῆς συμμαχίας κομισθέντων ἀναλαβὼν αὑτοῦ τὴν στρατιὰν ἧκεν εἰς Ἱεροσόλυμα, καὶ ξενισθεὶς λαμπρῶς ὑπὸ τοῦ βασιλέως τῶν Ἱεροσολυμιτῶν, δόξαν αὐτοὺς διὰ τῆς ἐρήμου τῆς Ἰδουμαίας ποιήσασθαι τὴν πορείαν ἐπὶ τοὺς πολεμίους, οὐ γὰρ προσδοκήσειν αὐτοὺς ταύτῃ ποιήσεσθαι τὴν ἔφοδον, ὥρμησαν οἱ τρεῖς βασιλεῖς ἐκ τῶν Ἱεροσολύμων, ὅ τε τούτων αὐτῶν καὶ ὁ τῶν Ἰσραηλιτῶν καὶ ὁ τῆς Ἰδουμαίας,"},{"number":32,"text":"καὶ κυκλεύσαντες ἑπτὰ ἡμερῶν ὁδὸν εἰς ἀπορίαν ὕδατος τοῖς τε κτήνεσι καὶ τῇ στρατιᾷ περιέστησαν πλανηθέντων τὰς ὁδοὺς αὐτοῖς τῶν ἡγουμένων, ὡς ἀγωνιᾶν μὲν ἅπαντας, μάλιστα δὲ τὸν Ἰώραμον καὶ ὑπὸ λύπης ἐκβοῆσαι πρὸς τὸν θεόν, τί κακὸν αἰτιασάμενος ἀγάγοι τοὺς τρεῖς βασιλεῖς ἀμαχητὶ παραδώσοντας ἑαυτοὺς τῷ Μωαβιτῶν βασιλεῖ;"},{"number":33,"text":"παρεθάρρυνε δʼ αὐτὸν ὁ Ἰωσαφάτης δίκαιος ὢν καὶ πέμψαντα εἰς τὸ στρατόπεδον ἐκέλευσε γνῶναι, εἴ τις αὐτοῖς τοῦ θεοῦ προφήτης συνελήλυθεν, ἵνα διʼ αὐτοῦ μάθωμεν παρὰ τοῦ θεοῦ, τί ποιητέον ἡμῖν. οἰκέτου δέ τινος φήσαντος τῶν Ἰωράμου ἰδεῖν αὐτόθι τὸν Ἠλία μαθητὴν Ἐλισσαῖον Σαφάτου παῖδα πρὸς αὐτὸν ἀπίασιν οἱ τρεῖς βασιλεῖς Ἰωσαφάτου παραινέσαντος."},{"number":34,"text":"ἐλθόντες δʼ ἐπὶ τὴν σκηνὴν τοῦ προφήτου, ἔτυχε δʼ ἔξω τῆς παρεμβολῆς κατεσκηνωκώς, ἐπηρώτων τὸ μέλλον ἐπὶ τῆς στρατιᾶς, μάλιστα δὲ ὁ Ἰώραμος. τοῦ δὲ μὴ διοχλεῖν αὐτῷ φράσαντος ἀλλὰ πρὸς τοὺς τοῦ πατρὸς αὐτοῦ καὶ τῆς μητρὸς βαδίζειν προφήτας, εἶναι γὰρ ἐκείνους ἀληθεῖς, ἐδεῖτο προφητεύειν καὶ σώζειν αὐτούς."},{"number":35,"text":"ὁ δὲ ὀμόσας τὸν θεὸν οὐκ ἂν ἀποκριθῆναι αὐτῷ, εἰ μὴ διὰ Ἰωσαφάτην ὅσιον ὄντα καὶ δίκαιον, ἀχθέντος ἀνθρώπου τινὸς ψάλλειν εἰδότος, ἐπεζήτησε γὰρ αὐτός, πρὸς τὸν ψαλμὸν ἔνθεος γενόμενος προσέταξε τοῖς βασιλεῦσιν ἐν τῷ χειμάρρῳ πολλοὺς ὀρύξαι βόθρους·"},{"number":36,"text":"οὔτε γὰρ νέφους οὔτε πνεύματος γενομένου οὔτε ὑετοῦ καταρραγέντος ὄψεσθε πλήρη τὸν ποταμὸν ὕδατος, ὡς ἂν καὶ τὸν στρατὸν καὶ τὰ ὑποζύγια διασωθῆναι ὑμῖν ἀπὸ τοῦ ποτοῦ. ἔσται δὲ ὑμῖν οὐ τοῦτο μόνον παρὰ θεοῦ, ἀλλὰ καὶ κρατήσετε τῶν ἐχθρῶν καὶ καλλίστας καὶ ὀχυρωτάτας πόλεις λήψεσθε τῶν Μωαβιτῶν, καὶ δένδρα μὲν αὐτῶν ἥμερα κόψετε, τὴν δὲ χώραν δῃώσετε, πηγὰς δὲ καὶ ποταμοὺς ἐμφράξετε."},{"number":37,"text":"Ταῦτα εἰπόντος τοῦ προφήτου τῇ ἐπιούσῃ πρὶν ἥλιον ἀνασχεῖν ὁ χειμάρρους πολὺς ἐρρύη, σφοδρῶς γὰρ ἀπὸ τριῶν ἡμερῶν ὁδοῦ ἐν τῇ Ἰδουμαίᾳ τὸν θεὸν ὗσαι συνέπεσεν, ὥστε εὑρεῖν τὴν στρατιὰν καὶ τὰ ὑποζύγια ποτὸν ἄφθονον."},{"number":38,"text":"ὡς δὲ ἤκουσαν οἱ Μωαβῖται τοὺς τρεῖς βασιλέας ἐπʼ αὐτοὺς βαδίζοντας καὶ διὰ τῆς ἐρήμου ποιουμένους τὴν ἔφοδον, ὁ βασιλεὺς αὐτῶν εὐθὺς συλλέξας στρατιὰν ἐκέλευσεν ἐπὶ τῶν ὅρων βάλλεσθαι τὸ στρατόπεδον, ἵνα αὐτοὺς μὴ λάθωσιν εἰς τὴν χώραν ἐμβαλόντες οἱ πολέμιοι."},{"number":39,"text":"θεασάμενοι δὲ ὑπὸ τὴν ἀνατολὴν ἡλίου τὸ ἐν τῷ χειμάρρῳ ὕδωρ, καὶ γὰρ οὐδὲ μακρὰν ἦν τῆς Μωαβίτιδος, αἵματι τὴν χροὰν ὅμοιον, τότε γὰρ μάλιστα πρὸς τὴν αὐγὴν τὸ ὕδωρ ἐρυθραίνεται, ψευδῆ δόξαν περὶ τῶν πολεμίων ἐλάμβανον ὡς ἀπεκτονότων ἑαυτοὺς διὰ δίψος καὶ τοῦ ποταμοῦ αἷμα αὐτοῖς ῥέοντος."},{"number":40,"text":"τοῦτο τοίνυν οὕτως ἔχειν ὑπολαβόντες ἠξίωσαν αὐτοὺς ἐπὶ διαρπαγὴν τῶν πολεμίων ἐκπέμψαι τὸν βασιλέα καὶ πάντες ἐξορμήσαντες ὡς ἐπὶ ἑτοίμην ὠφέλειαν ἦλθον εἰς τὸ τῶν ἐχθρῶν στρατόπεδον ὡς ἀπολωλότων. καὶ διαψεύδεται μὲν αὐτοῖς ἡ ἐλπὶς αὕτη, περιστάντων δὲ τῶν πολεμίων οἱ μὲν αὐτῶν κατεκόπησαν οἱ δὲ διεσπάρησαν εἰς τὴν ἰδίαν χώραν φεύγοντες."},{"number":41,"text":"ἐμβαλόντες δὲ εἰς τὴν Μωαβιτῶν οἱ βασιλεῖς τάς τε πόλεις κατεστρέψαντο τὰς ἐν αὐτῇ καὶ τοὺς ἀγροὺς αὐτῶν διήρπασαν καὶ ἠφάνισαν πληροῦντες τῶν ἐκ τῶν χειμάρρων λίθων, καὶ τὰ κάλλιστα τῶν δένδρων ἔκοψαν, καὶ τὰς πηγὰς ἐνέφραξαν τῶν ὑδάτων, καὶ τὰ τείχη καθεῖλον ἕως ἐδάφους."},{"number":42,"text":"ὁ δὲ βασιλεὺς τῶν Μωαβιτῶν συνδιωκόμενος τῇ πολιορκίᾳ καὶ τὴν πόλιν ὁρῶν κινδυνεύουσαν αἱρεθῆναι κατὰ κράτος ὥρμησε μεθʼ ἑπτακοσίων ἐξελθὼν διὰ τοῦ τῶν πολεμίων ἐξιππάσασθαι στρατοπέδου, καθʼ ὃ μέρος ἐνόμιζεν αὐτοὺς τὰς φυλακὰς ἀνεῖσθαι. καὶ πειραθεὶς οὐκ ἠδυνήθη φυγεῖν· ἐπιτυγχάνει γὰρ ἐπιμελῶς φρουρουμένῳ τῷ τόπῳ."},{"number":43,"text":"ὑποστρέψας δὲ εἰς τὴν πόλιν ἔργον ἀπογνώσεως καὶ δεινῆς ἀνάγκης διεπράξατο· τῶν υἱῶν τὸν πρεσβύτατον, ὃς μετʼ αὐτὸν βασιλεύειν ἤμελλεν, ἀναγαγὼν ἐπὶ τὸ τεῖχος ὥστε ἅπασι φανερὸν γενέσθαι τοῖς πολεμίοις ἱερούργησεν εἰς ὁλοκαύτωσιν τῷ θεῷ. θεασάμενοι δʼ αὐτὸν οἱ βασιλεῖς κατῴκτειραν τῆς ἀνάγκης καὶ παθόντες ἀνθρώπινόν τι καὶ ἐλεεινὸν διέλυσαν τὴν πολιορκίαν καὶ ἕκαστος εἰς τὴν οἰκείαν ἀνέστρεψαν."},{"number":44,"text":"Ἰωσαφάτης δὲ παραγενόμενος εἰς Ἱεροσόλυμα καὶ μετʼ εἰρήνης διαγαγὼν ὀλίγον ἐπιβιώσας χρόνον μετὰ τὴν στρατείαν ἐκείνην ἀπέθανε, ζήσας μὲν ἐτῶν ἀριθμὸν ἑξήκοντα, βασιλεύσας δὲ ἐξ αὐτῶν πέντε καὶ εἴκοσι. ταφῆς δὲ ἔτυχε μεγαλοπρεποῦς ἐν Ἱεροσολύμοις· καὶ γὰρ ἦν μιμητὴς τῶν Δαυίδου ἔργων."}],"4":[{"number":45,"text":"Κατέλιπε δὲ καὶ παῖδας ἱκανούς, διάδοχον δʼ ἀπέδειξε τὸν πρεσβύτατον Ἰώραμον· ταὐτὸ γὰρ εἶχεν ὄνομα τῷ τῆς γυναικὸς ἀδελφῷ, βασιλεύοντι δὲ τῶν Ἰσραηλιτῶν, Ἀχάβου δὲ παιδί."},{"number":46,"text":"παραγενόμενος δʼ ἐκ τῆς Μωαβίτιδος ὁ τῶν Ἰσραηλιτῶν βασιλεὺς εἰς Σαμάρειαν εἶχε σὺν αὑτῷ τὸν προφήτην Ἐλισσαῖον, οὗ τὰς πράξεις βούλομαι διελθεῖν, λαμπραὶ γάρ εἰσι καὶ ἱστορίας ἄξιαι, καθὼς ἐν ταῖς ἱεραῖς βίβλοις ἐπεγνώκαμεν."},{"number":47,"text":"Προσελθοῦσαν γὰρ αὐτῷ φασι τὴν Ὠβεδίου τοῦ Ἀχάβου οἰκονόμου γυναῖκα εἰπεῖν, ὡς οὐκ ἀγνοεῖ πῶς ὁ ἀνὴρ αὐτῆς τοὺς προφήτας περιέσωσεν ὑπὸ τῆς Ἀχάβου γυναικὸς Ἰεζαβέλας ἀναιρουμένους· ἑκατὸν γὰρ ἔλεγεν ὑπʼ αὐτοῦ δανεισαμένου τραφῆναι κεκρυμμένους· καὶ μετὰ τὴν τἀνδρὸς τελευτὴν ἄγεσθαι νῦν ὑπὸ τῶν δανειστῶν αὐτήν τε καὶ τέκνα πρὸς δουλείαν, παρεκάλει τε διὰ ταύτην τὴν ἐργασίαν τἀνδρὸς ἐλεῆσαί τε καὶ παρασχεῖν τινα βοήθειαν."},{"number":48,"text":"πυθομένῳ δʼ αὐτῷ, τί ἔχει ἐπὶ τῆς οἰκίας, ἄλλο μὲν οὐδὲν ἔφη, ἔλαιον δὲ βραχὺ λίαν ἐν κεραμίῳ. ὁ δὲ προφήτης ἀπελθοῦσαν ἐκέλευσεν ἀγγεῖα χρήσασθαι πολλὰ παρὰ τῶν γειτόνων κενὰ καὶ τὰς θύρας ἀποκλείσασαν τοῦ δωματίου μεταχεῖν εἰς ἅπαντα τὸ ἔλαιον· τὸν γὰρ θεὸν πληρώσειν αὐτά."},{"number":49,"text":"τῆς δὲ γυναικὸς τὰ κελευσθέντα ποιούσης καὶ τοῖς τέκνοις προσφέρειν ἕκαστον τῶν ἀγγείων προσταττούσης, ἐπεὶ πάντα ἐπληρώθη καὶ μηδὲν ἦν κενόν, ἐλθοῦσα πρὸς τὸν προφήτην ταῦτα ἀπήγγειλεν."},{"number":50,"text":"ὁ δὲ συνεβούλευε τοὔλαιον ἀπελθούσῃ ἀποδόσθαι καὶ τοῖς δανεισταῖς ἀποδοῦναι τὰ ὀφειλόμενα· γενήσεσθαι δέ τι καὶ περισσὸν ἐκ τῆς τιμῆς τοῦ ἐλαίου, ᾧ πρὸς διατροφὴν τὴν τῶν τέκνων καταχρήσεται. καὶ Ἐλισσαῖος μὲν οὕτως ἀπήλλαξε τῶν χρεῶν τὴν γυναῖκα καὶ τῆς ἀπὸ τῶν δανειστῶν ὕβρεως ἠλευθέρωσεν."},{"number":51,"text":"Ἐλισσαῖος δὲ ταχέως πρὸς Ἰώραμον ἐξαπέστειλε φυλάττεσθαι τὸν τόπον ἐκεῖνον αὐτῷ παραινῶν· εἶναι γὰρ ἐν αὐτῷ Σύρους τινὰς τοὺς ἐκεῖ λοχῶντας αὐτὸν ἀνελεῖν. καὶ ὁ μὲν βασιλεὺς οὐκέτʼ ἐπὶ τὴν θήραν ἐξώρμησε τῷ προφήτῃ πειθόμενος·"},{"number":52,"text":"Ἄδερ δὲ τῆς ἐπιβουλῆς διαμαρτὼν ὡς τῶν ἰδίων αὐτοῦ καταμηνυσάντων πρὸς τὸν Ἰώραμον τὴν ἐνέδραν, ὠργίζετό τε καὶ μεταπεμψάμενος αὐτοὺς προδότας ἔλεγε τῶν ἀπορρήτων αὐτοῦ καὶ θάνατον ἠπείλει φανερᾶς τῆς ἐπιχειρήσεως, ἣν μόνοις ἐκείνοις ἐπίστευσε, τῷ πολεμίῳ γεγενημένης."},{"number":53,"text":"φήσαντος δέ τινος τῶν παρόντων ψευδοδοξεῖν αὐτόν, μηδὲ ὑπονοεῖν αὐτὸν ὡς πρὸς τὸν ἐχθρὸν αὐτοῦ κατειρηκότας τὴν ἔκπεμψιν τῶν ἀναιρησόντων αὐτούς, ἀλλὰ γινώσκειν ὅτι Ἐλισσαῖός ἐστιν ὁ προφήτης ὁ πάντα μηνύων αὐτῷ καὶ φανερὰ ποιῶν τὰ ὑπʼ αὐτοῦ βουλευόμενα, προσέταξε πέμψας μαθεῖν ἐν τίνι πόλει τυγχάνει διατρίβων Ἐλισσαῖος."},{"number":54,"text":"οἱ δὲ πεμφθέντες ἧκον ἀγγέλλοντες αὐτὸν ἐν Δωθαεὶν ὑπάρχοντα. πέμπει τοιγαροῦν Ἄδερ ἐπὶ τὴν πόλιν δύναμιν πολλὴν ἱππέων καὶ ἁρμάτων, ὅπως τὸν Ἐλισσαῖον λάβωσιν. οἱ δὲ νυκτὸς κύκλῳ τὴν πόλιν πᾶσαν περιλαβόντες εἶχον ἐν φρουρᾷ. ἅμα δὲ ἕῳ τοῦτο μαθὼν ὁ τοῦ προφήτου διάκονος καὶ ὅτι ζητοῦσιν οἱ πολέμιοι λαβεῖν Ἐλισσαῖον ἐδήλωσεν αὐτῷ μετὰ βοῆς καὶ ταραχῆς δραμὼν πρὸς αὐτόν."},{"number":55,"text":"ὁ δὲ τὸν θεράποντα μὴ δεδιέναι παρεθάρρυνε καὶ τὸν θεόν, ᾧ συμμάχῳ καταφρονῶν ἀδεὴς ἦν, παρεκάλει τῷ διακόνῳ πρὸς τὸ λαβεῖν αὐτὸν εὔελπι θάρσος ἐμφανίσαι τὴν αὑτοῦ δύναμιν καὶ παρουσίαν, ὡς δυνατόν. ὁ δὲ θεὸς ἐπήκοος τῶν εὐχῶν τοῦ προφήτου γενόμενος πλῆθος ἁρμάτων καὶ ἵππων τῷ θεράποντι περὶ τὸν Ἐλισσαῖον κεκυκλωμένον θεάσασθαι παρέσχεν, ὡς αὐτὸν ἀφιέναι μὲν τὸ δέος, ἀναθαρσῆσαι δὲ πρὸς τὴν ὄψιν τῆς νομιζομένης συμμαχίας."},{"number":56,"text":"Ἐλισσαῖος δὲ μετὰ ταῦτα καὶ τὰς τῶν πολεμίων ὄψεις ἀμαυρῶσαι τὸν θεὸν παρεκάλει ἀχλὺν αὐταῖς ἐπιβαλόντα ἀφʼ ἧς ἀγνοήσειν αὐτὸν ἔμελλον. γενομένου δὲ καὶ τούτου προελθὼν εἰς μέσους τοὺς ἐχθροὺς ἐπηρώτησε, τίνα ἐπιζητοῦντες ἦλθον· τῶν δὲ τὸν προφήτην Ἐλισσαῖον εἰπόντων παραδώσειν ὑπέσχετο, εἰ πρὸς τὴν πόλιν ἐν ᾗ τυγχάνει ὢν ἀκολουθήσειαν αὐτῷ."},{"number":57,"text":"καὶ οἱ μὲν ἡγουμένῳ τῷ προφήτῃ τὰς ὄψεις ὑπὸ θεοῦ καὶ τὴν διάνοιαν ἐπεσκοτημένοι σπουδάζοντες εἵποντο, ἀγαγὼν δὲ αὐτοὺς Ἐλισσαῖος εἰς Σαμάρειαν Ἰωράμῳ μὲν τῷ βασιλεῖ προσέταξε κλεῖσαι τὰς πύλας καὶ περιστῆσαι τοῖς Σύροις τὴν αὑτοῦ δύναμιν, τῷ θεῷ δὲ ηὔξατο καθᾶραι τὰς ὄψεις τῶν πολεμίων καὶ τὴν ἀχλὺν αὐτῶν ἀνελεῖν. οἱ δʼ ἐκ τῆς ἀμαυρώσεως ἐκείνης ἀφεθέντες ἑώρων αὑτοὺς ἐν μέσοις τοῖς ἐχθροῖς ὑπάρχοντας."},{"number":58,"text":"ἐν ἐκπλήξει δὲ δεινῇ καὶ ἀμηχανίᾳ τῶν Σύρων οἷον εἰκὸς ἐφʼ οὕτως θείῳ καὶ παραδόξῳ πράγματι κειμένων καὶ τοῦ βασιλέως Ἰωράμου πυθομένου τὸν προφήτην, εἰ κελεύσειεν αὐτοὺς κατακοντισθῆναι, τοῦτο μὲν ἐκώλυσε ποιεῖν Ἐλισσαῖος· τοὺς γὰρ νόμῳ πολέμου ληφθέντας ἀποκτείνειν εἶναι δίκαιον ἔλεγε, τούτους δὲ μηδὲν κακὸν ἐργάσασθαι τὴν ἐκείνου χώραν, θείᾳ δὲ δυνάμει πρὸς αὐτοὺς οὐκ εἰδότας ἐλθεῖν."},{"number":59,"text":"συνεβούλευέ τε ξενίων αὐτοῖς μεταδόντα καὶ τραπέζης ἀπολύειν ἀβλαβεῖς. Ἰώραμος μὲν οὖν τῷ προφήτῃ πειθόμενος ἑστιάσας λαμπρῶς πάνυ καὶ φιλοτίμως τοὺς Σύρους ἀπέλυσε πρὸς Ἄδερα τὸν αὑτῶν βασιλέα."},{"number":60,"text":"Τῶν δὲ ἀφικομένων καὶ δηλωσάντων αὐτῷ τὰ συμβεβηκότα θαυμάσας ὁ Ἄδερ τὸ παράδοξον καὶ τὴν τοῦ θεοῦ τῶν Ἰσραηλιτῶν ἐπιφάνειαν καὶ δύναμιν καὶ τὸν προφήτην, ᾧ τὸ θεῖον οὕτως ἐναργῶς παρῆν, κρύφα μὲν οὐκέτι διέγνω τῷ τῶν Ἰσραηλιτῶν ἐπιχειρεῖν βασιλεῖ τὸν Ἐλισσαῖον δεδοικώς, φανερῶς δὲ πολεμεῖν ἔκρινε τῷ πλήθει τῆς στρατιᾶς καὶ τῇ δυνάμει νομίζων περιέσεσθαι τῶν πολεμίων."},{"number":61,"text":"καὶ στρατεύει μετὰ μεγάλης δυνάμεως ἐπὶ τὸν Ἰώραμον, ὃς οὐχ ἡγούμενος αὑτὸν ἀξιόμαχον εἶναι τοῖς Σύροις ἐνέκλεισεν αὑτὸν εἰς τὴν Σαμάρειαν θαρρῶν τῇ τῶν τειχῶν ὀχυρότητι. Ἄδερ δὲ λογισάμενος αἱρήσειν τὴν πόλιν, εἰ καὶ μὴ τοῖς μηχανήμασι, λιμῷ μέντοι καὶ σπάνει τῶν ἐπιτηδείων παραστήσεσθαι τοὺς Σαμαρεῖς, προσβαλὼν ἐπολιόρκει τὴν πόλιν."},{"number":62,"text":"οὕτω δὲ ἐπέλιπε τὸν Ἰώραμον ἡ τῶν ἀναγκαίων εὐπορία, ὡς διʼ ὑπερβολὴν τῆς ἐνδείας ἐν τῇ Σαμαρείᾳ πραθῆναι ὀγδοήκοντα μὲν ἀργυρῶν νομίσματος κεφαλὴν ὄνου, πέντε δὲ ἀργυρῶν νομίσματος ξέστην κόπρου περιστερῶν ἀντὶ ἁλῶν ὠνεῖσθαι τοὺς Ἑβραίους."},{"number":63,"text":"ἦν δʼ ἐν φόβῳ μὴ διὰ τὸν λιμὸν προδῷ τις τοῖς ἐχθροῖς τὴν πόλιν ὁ Ἰώραμος καὶ καθʼ ἑκάστην ἡμέραν ἐκπεριήρχετο τὰ τείχη καὶ τοὺς φύλακας, μή τις ἔνδον εἴη παρʼ αὐτῶν σκεπτόμενος καὶ τῷ βλέπεσθαι καὶ φροντίζειν ἀφαιρούμενος καὶ τὸ βούλεσθαί τι τοιοῦτον καὶ τὸ ἔργον, εἰ ταύτην τις τὴν γνώμην ἤδη λαμβάνειν ἔφθασεν."},{"number":64,"text":"ἀνακραγούσης δέ τινος γυναικός δέσποτα ἐλέησον νομίσας αἰτεῖν τι μέλλειν αὐτὴν τῶν πρὸς τροφὴν ὀργισθεὶς ἐπηράσατο αὐτῇ τὸν θεὸν καὶ μήτε ἅλως αὐτῷ μήτε ληνοὺς ὑπάρχειν ἔλεγεν, ὅθεν τι καὶ παράσχοι ἂν αὐτῇ δεομένῃ."},{"number":65,"text":"τῆς δʼ οὐδενὸς μὲν τούτων χρῄζειν εἰπούσης οὐδʼ ἐνοχλεῖν τροφῆς ἕνεκα, κριθῆναι δὲ ἀξιούσης πρὸς ἄλλην γυναῖκα, κελεύσαντος λέγειν καὶ διδάσκειν περὶ ὧν ἐπιζητεῖ συνθήκας ἔφη ποιήσασθαι μετὰ τῆς ἑτέρας γυναικὸς γειτνιώσης καὶ φίλης αὐτῇ τυγχανούσης, ὅπως ἐπεὶ τὰ τοῦ λιμοῦ καὶ τῆς ἐνδείας ἦν ἀμήχανα διαχρησάμενοι τὰ τέκνα, ἦν δὲ ἄρρεν ἑκατέρᾳ παιδίον, ἀνὰ μίαν ἡμέραν θρέψωμεν ἀλλήλας."},{"number":66,"text":"κἀγὼ μέν, φησί, πρώτη τοὐμὸν κατέσφαξα καὶ τὴν παρελθοῦσαν ἡμέραν τοὐμὸν ἐτράφημεν ἀμφότεραι· νῦν δʼ οὐ βούλεται ταὐτὸ ποιεῖν, ἀλλὰ παραβαίνει τὴν συνθήκην καὶ τὸν υἱὸν ἀφανῆ πεποίηκε."},{"number":67,"text":"τοῦτʼ ἐλύπησε σφοδρῶς Ἰώραμον ἀκούσαντα, καὶ περιρρηξάμενος τὴν ἐσθῆτα καὶ δεινὸν ἐκβοήσας ἔπειτα ὀργῆς ἐπὶ τὸν προφήτην Ἐλισσαῖον πληρωθεὶς ἀνελεῖν αὐτὸν ὥρμησεν, ὅτι μὴ δεῖται τοῦ θεοῦ πόρον τʼ αὐτοῖς καὶ διαφυγὴν τῶν περιεχόντων κακῶν δοῦναι· τόν τε ἀποτεμοῦντα αὐτοῦ τὴν κεφαλὴν εὐθὺς ἐξέπεμψε."},{"number":68,"text":"καὶ ὁ μὲν ἐπὶ τὴν ἀναίρεσιν ἠπείγετο τοῦ προφήτου· τὸν δʼ Ἐλισσαῖον οὐκ ἔλαθεν ἡ τοῦ βασιλέως ὀργή, καθεζόμενος δὲ οἴκαδε παρʼ αὑτῷ σὺν τοῖς μαθηταῖς ἐμήνυσεν αὐτοῖς, ὅτι Ἰώραμος ὁ τοῦ φονέως υἱὸς πέμψειε τὸν ἀφαιρήσοντα αὐτοῦ τὴν κεφαλήν."},{"number":69,"text":"ἀλλʼ ὑμεῖς, φησίν, ὅταν ὁ τοῦτο προσταχθεὶς ἀφίκηται, παραφυλάξαντες εἰσιέναι μέλλοντα προσαποθλίψατε τῇ θύρᾳ καὶ κατάσχετε· ἀκολουθήσει γὰρ αὐτῷ πρός με παραγινόμενος ὁ βασιλεὺς μεταβεβουλευμένος. καὶ οἱ μὲν τὸ κελευσθὲν ὡς ἧκεν ὁ πεμφθεὶς ὑπὸ τοῦ βασιλέως ἐπὶ τὴν ἀναίρεσιν τὴν Ἐλισσαίου ἐποίησαν·"},{"number":70,"text":"Ἰώραμος δὲ καταγνοὺς τῆς ἐπὶ τὸν προφήτην ὀργῆς καὶ δείσας, μὴ φθάσῃ κτείνας αὐτὸν ὁ τοῦτο προσταχθείς, ἔσπευσε κωλῦσαι γενέσθαι τὸν φόνον καὶ διασῶσαι τὸν προφήτην. ἀφικόμενος δὲ πρὸς αὐτὸν ᾐτιᾶτο, ὅτι μὴ παρὰ τοῦ θεοῦ λύσιν αὐτοῖς τῶν παρόντων αἰτεῖται κακῶν, ἀλλʼ οὕτως ὑπʼ αὐτῶν φθειρομένους ὑπερορᾷ."},{"number":71,"text":"Ἐλισσαῖος δὲ εἰς τὴν ἐπιοῦσαν ἐπηγγέλλετο κατʼ ἐκείνην τὴν ὥραν, καθʼ ἣν ὁ βασιλεὺς ἀφίκετο πρὸς αὐτόν, ἔσεσθαι πολλὴν εὐπορίαν τροφῆς καὶ πραθήσεσθαι μὲν ἐν τῇ ἀγορᾷ σίκλου δύο κριθῆς σάτα, ὠνήσεσθαι δὲ σεμιδάλεως σάτον σίκλου."},{"number":72,"text":"ταῦτα τόν τε Ἰώραμον καὶ τοὺς παρόντας εἰς χαρὰν περιέτρεψε· πιστεύειν γὰρ τῷ προφήτῃ διὰ τὴν ἐπὶ τοῖς προπεπειραμένοις ἀλήθειαν οὐκ ὤκνουν, ἀλλὰ καὶ τὸ ἐπʼ ἐκείνης ἐνδεὲς τῆς ἡμέρας καὶ ταλαίπωρον ἡ προσδοκωμένη κοῦφον αὐτοῖς ἐποίει."},{"number":73,"text":"ὁ δὲ τῆς τρίτης μοίρας ἡγεμὼν τῷ βασιλεῖ φίλος ὢν καὶ τότε φέρων αὐτὸν ἐπερηρεισμένον ἄπιστα, εἶπε, λέγεις, ὦ προφῆτα· καὶ ὥσπερ ἀδύνατον ἐκχέαι τὸν θεὸν ἐξ οὐρανοῦ καταρράκτας κριθῆς ἢ σεμιδάλεως, οὕτως ἀμήχανον καὶ τὰ ὑπὸ σοῦ νῦν εἰρημένα γενέσθαι. καὶ ὁ προφήτης πρὸς αὐτόν ταῦτα μέν, εἶπεν, ὄψει τοῦτο λαμβάνοντα τὸ τέλος, οὐ μεταλήψῃ δʼ οὐδενὸς τῶν ὑπαρξόντων."},{"number":74,"text":"Ἐξέβη τοίνυν τοῦτον τὸν τρόπον τὰ ὑπὸ Ἐλισσαίου προειρημένα· νόμος ἦν ἐν Σαμαρείᾳ τοὺς λέπραν ἔχοντας καὶ μὴ καθαροὺς ἀπὸ τῶν τοιούτων τὰ σώματα μένειν ἔξω τῆς πόλεως. ἄνδρες οὖν τὸν ἀριθμὸν τέσσαρες διὰ ταύτην τὴν αἰτίαν πρὸ τῶν πυλῶν μένοντες μηκέτι μηδενὸς αὐτοῖς διὰ τὴν ὑπερβολὴν τοῦ λιμοῦ"},{"number":75,"text":"τροφὴν ἐκφέροντος εἰσελθεῖν μὲν εἰς τὴν πόλιν διὰ τὸν νόμον κεκωλυμένοι, κἂν ἐπιτραπῇ δʼ αὐτοῖς διαφθαρήσεσθαι κακῶς ὑπὸ τοῦ λιμοῦ λογισάμενοι, τοῦτο δὲ πείσεσθαι κἂν αὐτόθι μείνωσιν ἀπορίᾳ τροφῆς, παραδοῦναι τοῖς πολεμίοις αὑτοὺς ἔκριναν ὡς εἰ μὲν φείσαιντο αὐτῶν ζησόμενοι, εἰ δʼ ἀναιρεθεῖεν εὐθανατήσοντες."},{"number":76,"text":"ταύτην κυρώσαντες τὴν βουλὴν νυκτὸς ἧκον εἰς τὸ στρατόπεδον τῶν πολεμίων. ἤρχετο δʼ ἤδη τοὺς Σύρους ἐκφοβεῖν καὶ ταράττειν ὁ θεὸς καὶ κτύπον ἁρμάτων καὶ ἵππων ὡς ἐπερχομένης στρατιᾶς ταῖς ἀκοαῖς αὐτῶν ἐνηχεῖν καὶ ταύτην ἐγγυτέρω προσφέρειν αὐτοῖς τὴν ὑπόνοιαν."},{"number":77,"text":"ἀμέλει τοῦτον τὸν τρόπον ὑπʼ αὐτῆς διετέθησαν, ὥστε τὰς σκηνὰς ἐκλιπόντες συνέδραμον πρὸς τὸν Ἄδερα λέγοντες, ὡς Ἰώραμος ὁ τῶν Ἰσραηλιτῶν μισθωσάμενος συμμάχους τόν τε τῶν Αἰγυπτίων βασιλέα καὶ τὸν τῶν νήσων ἐπʼ αὐτοὺς ἄγει· προσιόντων γὰρ αὐτῶν ἐπακούειν τοῦ κτύπου."},{"number":78,"text":"ταῦτα λέγουσιν ὁ Ἄδερ, καὶ γὰρ αὐτὸς περιεψοφεῖτο ἤδη τὰς ἀκοὰς ὁμοίως τῷ πλήθει, προσέσχε καὶ μετὰ πολλῆς ἀταξίας καὶ θορύβου καταλιπόντες ἐν τῇ παρεμβολῇ τοὺς ἵππους καὶ τὰ ὑποζύγια καὶ πλοῦτον ἄφθονον εἰς φυγὴν ἐχώρησαν."},{"number":79,"text":"οἱ λεπροὶ δὲ οἱ ἐκ τῆς Σαμαρείας ἀναχωρήσαντες εἰς τὸ τῶν Σύρων στρατόπεδον, ὧν μικρὸν ἔμπροσθεν ἐπεμνήσθημεν, ὡς γενόμενοι πρὸς τῇ παρεμβολῇ πολλὴν ἡσυχίαν καὶ ἀφωνίαν ἔβλεπον οὖσαν καὶ παρελθόντες δὲ εἴσω καὶ ὁρμήσαντες εἰς μίαν σκηνὴν οὐδένα ἑώρων, ἐμφαγόντες καὶ πιόντες ἐβάστασαν ἐσθῆτα καὶ πολὺν χρυσὸν κομίσαντες ἔξω τῆς παρεμβολῆς ἔκρυψαν·"},{"number":80,"text":"ἔπειτʼ εἰς ἑτέραν σκηνὴν παρελθόντες ὁμοίως τὰ ἐν αὐτῇ πάλιν ἐξεκόμισαν, καὶ τοῦτʼ ἐποίησαν τετράκις μηδενὸς αὐτοῖς ὅλως ἐντυγχάνοντος. ὅθεν εἰκάσαντες ἀνακεχωρηκέναι τοὺς πολεμίους κατεγίνωσκον αὑτῶν μὴ ταῦτα δηλούντων τῷ Ἰωράμῳ καὶ τοῖς πολίταις."},{"number":81,"text":"καὶ οἱ μὲν ἐλθόντες πρὸς τὸ τῆς Σαμαρείας τεῖχος καὶ ἀναβοήσαντες πρὸς τοὺς φύλακας ἐμήνυον αὐτοῖς τὰ περὶ τοὺς πολεμίους, ἐκεῖνοι δὲ ταῦτʼ ἀπήγγειλαν τοῖς τοῦ βασιλέως φύλαξι, παρʼ ὧν μαθὼν Ἰώραμος μεταπέμπεται τοὺς φίλους καὶ τοὺς ἡγεμόνας."},{"number":82,"text":"πρὸς οὓς ἐλθόντας ἐνέδραν καὶ τέχνην ὑπονοεῖν ἔλεγε τὴν ἀναχώρησιν τοῦ τῶν Σύρων βασιλέως ἀπογνόντος ἡμᾶς τῷ λιμῷ διαφθαρήσεσθαι, ἵνα ὡς πεφευγότων εἰς διαρπαγὴν ἐξελθόντων τῆς παρεμβολῆς αἰφνιδίως ἐπιπέσῃ καὶ κτείνῃ μὲν αὐτούς, ἀμαχητὶ δὲ ἕλῃ τὴν πόλιν· ὅθεν ὑμῖν παραινῶ διὰ φυλακῆς ἔχειν αὐτὴν μὴ καταφρονήσαντας τῷ τοὺς πολεμίους ἀνακεχωρηκέναι·"},{"number":83,"text":"φήσαντος δέ τινος, ὡς ἄριστα μὲν καὶ συνετώτατα ὑπονοήσειε, πέμψαι γε μὴν συμβουλεύσαντος δύο τῶν ἱππέων τοὺς τὴν ἄχρι Ἰορδάνου πᾶσαν ἐξερευνήσοντας, ἵνʼ εἰ ληφθέντες ὑπὸ λοχώντων τῶν πολεμίων διαφθαρεῖεν φυλακὴ τῇ στρατιᾷ γένωνται τοῦ μηδὲν ὅμοιον παθεῖν αὐτὴν ἀνυπόπτως προελθοῦσαν· προσαριθμήσεις δέ, φησί, τοῖς ὑπὸ τοῦ λιμοῦ τεθνηκόσι τοὺς ἱππεῖς, κἂν ὑπὸ τῶν ἐχθρῶν ληφθέντες ἀπόλωνται."},{"number":84,"text":"ἀρεσθεὶς δὲ τῇ γνώμῃ τότε τοὺς κατοψομένους ἐξέπεμψεν· οἱ δὲ κενὴν μὲν πολεμίων τὴν ὁδὸν ἤνυσαν, μεστὴν δὲ σιτίων καὶ ὅπλων εὗρον, ἃ διὰ τὸ κοῦφοι πρὸς τὸ φεύγειν εἶναι ῥίπτοντες κατέλιπον. ταῦτʼ ἀκούσας ὁ βασιλεὺς ἐπὶ διαρπαγὴν τῶν ἐν τῷ στρατοπέδῳ τὸ πλῆθος ἐξαφῆκεν."},{"number":85,"text":"εὐτελὲς δὲ οὐδὲν οὐδʼ ὀλίγον ὠφελοῦντο, ἀλλὰ πολὺν μὲν χρυσόν, πολὺν δὲ ἄργυρον, ἀγέλας δὲ παντοδαπῶν κτηνῶν, ἔτι γε μὴν σίτου μυριάσι καὶ κριθῆς αἷς οὐδʼ ὄναρ ἤλπισαν ἐπιτυχόντες τῶν μὲν προτέρων κακῶν ἀπηλλάγησαν, ἀφθονίαν δʼ εἶχον, ὡς ὠνεῖσθαι δύο μὲν σάτα κριθῆς σίκλου σεμιδάλεως δὲ σάτον σίκλου κατὰ τὴν Ἐλισσαίου προφητείαν· ἰσχύει δὲ τὸ σάτον μόδιον καὶ ἥμισυ Ἰταλικόν."},{"number":86,"text":"μόνος δὲ τούτων οὐκ ὤνατο τῶν ἀγαθῶν ὁ τῆς τρίτης μοίρας ἡγεμών· κατασταθεὶς γὰρ ἐπὶ τῆς πύλης ὑπὸ τοῦ βασιλέως, ἵνα τὸ πλῆθος ἐπέχῃ τῆς πολλῆς ὁρμῆς καὶ μὴ κινδυνεύσωσιν ὑπʼ ἀλλήλων ὠθούμενοι συμπατηθέντες ἀπολέσθαι, τοῦτʼ αὐτὸς ἔπαθε καὶ τοῦτον ἀποθνήσκει τὸν τρόπον τὴν τελευτὴν αὐτῷ προφητεύσαντος Ἐλισσαίου, ὅτε τοῖς ὑπʼ αὐτοῦ περὶ τῆς ἐσομένης εὐπορίας τῶν ἐπιτηδείων λεγομένοις μόνος ἐξ ἁπάντων οὐκ ἐπίστευσεν."},{"number":87,"text":"Ὁ δὲ τῶν Σύρων βασιλεὺς Ἄδερος διασωθεὶς εἰς Δαμασκὸν καὶ μαθών, ὅτι τὸ θεῖον αὐτόν τε καὶ τὴν στρατιὰν αὐτοῦ πᾶσαν εἰς τὸ δέος καὶ τὴν ταραχὴν ἐκείνην ἐνέβαλεν, ἀλλʼ οὐκ ἐξ ἐφόδου πολεμίων ἐγένετο, σφόδρα τῷ δυσμενῆ τὸν θεὸν ἔχειν ἀθυμήσας εἰς νόσον κατέπεσεν."},{"number":88,"text":"ἐκδημήσαντος δὲ κατʼ ἐκεῖνον τὸν καιρὸν εἰς Δαμασκὸν Ἐλισσαίου τοῦ προφήτου γνοὺς ὁ Ἄδερ τὸν πιστότατον τῶν οἰκετῶν Ἀζάηλον ἔπεμψεν ὑπαντησόμενον αὐτῷ καὶ δῶρα κομίζοντα, κελεύσας ἔρεσθαι περὶ τῆς νόσου καὶ εἰ διαφεύξεται τὸν ἐξ αὐτῆς κίνδυνον."},{"number":89,"text":"Ἀζάηλος δὲ μετὰ καμήλων τεσσαράκοντα τὸν ἀριθμόν, αἳ τὰ κάλλιστα καὶ τιμιώτατα τῶν ἐν Δαμασκῷ γινομένων καὶ ὄντων ἐν τῷ βασιλείῳ ἔφερον δῶρα, συμβαλὼν τῷ Ἐλισσαίῳ προσαγορεύσας αὐτὸν φιλοφρόνως ἔλεγεν ὑπὸ Ἄδερος τοῦ βασιλέως πεμφθῆναι πρὸς αὐτὸν δῶρά τε κομίσαι καὶ πυθέσθαι περὶ τῆς νόσου καὶ εἰ ῥᾴων ἀπʼ αὐτῆς ἔσοιτο."},{"number":90,"text":"ὁ δὲ προφήτης τὸν μὲν Ἀζάηλον ἐκέλευε μηδὲν ἀπαγγέλλειν τῷ βασιλεῖ κακόν, ἔλεγε δʼ ὅτι τεθνήξεται. καὶ ὁ μὲν οἰκέτης τοῦ βασιλέως ἐλυπεῖτο ταῦτʼ ἀκούσας, ὁ δʼ Ἐλισσαῖος ἔκλαιε καὶ πολλοῖς ἐρρεῖτο δακρύοις προορώμενος ἃ πάσχειν ὁ λαὸς ἔμελλε κακὰ μετὰ τὴν Ἄδερος τελευτήν."},{"number":91,"text":"ἀνακρίναντος δʼ αὐτὸν Ἀζαήλου τὴν αἰτίαν τῆς συγχύσεως κλαίω, φησί, τὸ πλῆθος τῶν Ἰσραηλιτῶν ἐλεῶν, ὧν ἐκ σοῦ πείσεται δεινῶν· ἀποκτενεῖς γὰρ αὐτῶν τοὺς ἀρίστους καὶ τὰς ὀχυρωτάτας πόλεις ἐμπρήσεις, καὶ παιδία μὲν ἀπολεῖς προσρηγνὺς πέτραις τὰς δʼ ἐγκύους ἀναρρήξεις γυναῖκας."},{"number":92,"text":"τοῦ δὲ Ἀζαήλου λέγοντος· τίνα γὰρ ἰσχὺν ἐμοὶ τηλικαύτην εἶναι συμβέβηκεν, ὥστε ταῦτα ποιῆσαι; τὸν θεὸν ἔφησεν αὐτῷ δεδηλωκέναι τοῦθʼ, ὅτι τῆς Συρίας μέλλει βασιλεύειν. Ἀζάηλος μὲν οὖν παραγενόμενος πρὸς τὸν Ἄδερα τῷ μὲν τὰ βελτίω περὶ τῆς νόσου κατήγγελλε, τῇ δʼ ἐπιούσῃ δίκτυον ἐπιβαλὼν αὐτῷ διάβροχον τὸν μὲν στραγγάλῃ διέφθειρε,"},{"number":93,"text":"τὴν δʼ ἀρχὴν αὐτὸς παρέλαβε δραστήριός τε ὢν ἀνὴρ καὶ πολλὴν ἔχων παρὰ τῶν Σύρων εὔνοιαν καὶ τοῦ δήμου τῶν Δαμασκηνῶν, ὑφʼ οὗ μέχρι νῦν αὐτός τε ὁ Ἄδερ καὶ Ἀζάηλος ὁ μετʼ αὐτὸν ἄρξας ὡς θεοὶ τιμῶνται διὰ τὰς εὐεργεσίας καὶ τῶν ναῶν οἰκοδομίας, οἷς ἐκόσμησαν τὴν τῶν Δαμασκηνῶν πόλιν."},{"number":94,"text":"πομπεύουσι δʼ αὐτοὶ καθʼ ἑκάστην ἡμέραν ἐπὶ τῇ τιμῇ τῶν βασιλέων καὶ σεμνύνονται τὴν τούτων ἀρχαιότητα οὐκ εἰδότες, ὅτι νεώτεροί εἰσι καὶ οὐκ ἔχοντες οὗτοι οἱ βασιλεῖς ἔτη χίλια καὶ ἑκατόν. ὁ δὲ τῶν Ἰσραηλιτῶν βασιλεὺς Ἰώραμος ἀκούσας τὴν Ἄδερος τελευτὴν ἀνέπνευσεν ἐκ τῶν φόβων καὶ τοῦ δέους ὃ διʼ αὐτὸν εἶχεν ἀσμένως εἰρήνης λαμβανόμενος."}],"5":[{"number":95,"text":"Ἰώραμος δὲ ὁ τῶν Ἱεροσολύμων βασιλεύς, καὶ τούτῳ γὰρ ἦν ταὐτὸν καθὼς προειρήκαμεν ἔμπροσθεν ὄνομα, παραλαβὼν τὴν ἀρχὴν εὐθὺς ἐπὶ σφαγὴν τῶν ἀδελφῶν αὐτοῦ καὶ τῶν πατρῴων φίλων οἳ καὶ ἡγεμόνες ἦσαν ἐχώρησε, τὴν ἀρχὴν καὶ τὴν ἐπίδειξιν τῆς πονηρίας ἐντεῦθεν ποιησάμενος καὶ μηδὲν διενεγκὼν τῶν τοῦ λαοῦ βασιλέων, οἳ πρῶτοι παρηνόμησαν εἰς τὰ πάτρια τῶν Ἑβραίων ἔθη καὶ τὴν τοῦ θεοῦ θρησκείαν."},{"number":96,"text":"ἐδίδαξε δʼ αὐτὸν τά τʼ ἄλλα εἶναι κακὸν καὶ δὴ καὶ ξενικοὺς θεοὺς προσκυνεῖν Γοθολία θυγάτηρ μὲν Ἀχάβου συνοικοῦσα δʼ αὐτῷ. καὶ ὁ μὲν θεὸς διὰ τὴν πρὸς Δαυίδην ὁμολογίαν οὐκ ἐβούλετο τούτου τὸ γένος ἐξαφανίσαι, Ἰώραμος δʼ οὐ διέλειπεν ἑκάστης ἡμέρας καινουργῶν ἐπʼ ἀσεβείᾳ καὶ λύμῃ τῶν ἐπιχωρίων ἐθισμῶν."},{"number":97,"text":"ἀποστάντων δὲ αὐτοῦ κατʼ ἐκεῖνον τὸν καιρὸν τῶν Ἰδουμαίων καὶ τὸν μὲν πρότερον ἀποκτεινάντων βασιλέα, ὃς ὑπήκουεν αὐτοῦ τῷ πατρί, ὃν δʼ ἐβούλοντο αὐτοὶ καταστησάντων Ἰώραμος μετὰ τῶν περὶ αὐτὸν ἱππέων καὶ τῶν ἁρμάτων νυκτὸς εἰς τὴν Ἰδουμαίαν ἐνέβαλε, καὶ τοὺς μὲν πέριξ τῆς αὑτοῦ βασιλείας διέφθειρε, περαιτέρω δʼ οὐ προῆλθεν."},{"number":98,"text":"ὤνησε μέντοι τοῦτο ποιήσας οὐδὲ ἕν· πάντες γὰρ ἀπέστησαν αὐτοῦ καὶ οἱ τὴν χώραν τὴν καλουμένην Λαβίναν νεμόμενοι. ἦν δʼ οὕτως ἐμμανής, ὥστε τὸν λαὸν ἠνάγκαζεν ἐπὶ τὰ ὑψηλότατα τῶν ὀρῶν ἀναβαίνοντα προσκυνεῖν τοὺς ἀλλοτρίους θεούς."},{"number":99,"text":"Ταῦτα δʼ αὐτῷ πράττοντι καὶ τελέως ἐκβεβληκότι τῆς διανοίας τὰ πάτρια νόμιμα κομίζεται παρʼ Ἠλίου τοῦ προφήτου ἐπιστολή, ἣ τὸν θεὸν ἐδήλου μεγάλην παρʼ αὐτοῦ ληψόμενον δίκην, ὅτι τῶν μὲν ἰδίων πατέρων μιμητὴς οὐκ ἐγένετο, τοῖς δὲ τῶν Ἰσραηλιτῶν βασιλέων κατηκολούθησεν ἀσεβήμασι καὶ συνηνάγκασε τὴν Ἰούδα φυλὴν καὶ τοὺς πολίτας Ἱεροσολύμων ἀφέντας τὴν ὁσίαν τοῦ ἐπιχωρίου θεοῦ σέβειν τὰ εἴδωλα, καθὼς καὶ Ἄχαβος τοὺς Ἰσραηλίτας ἐβιάσατο,"},{"number":100,"text":"ὅτι τε τοὺς ἀδελφοὺς διεχρήσατο καὶ τοὺς ἀγαθοὺς ἄνδρας καὶ δικαίους ἀπέκτεινεν· τήν τε τιμωρίαν ἣν ἀντὶ τούτων ὑφέξειν ἔμελλεν ἐσήμαινε τοῖς γράμμασιν ὁ προφήτης, ὄλεθρον τοῦ λαοῦ καὶ φθορὰν γυναικῶν αὐτοῦ τοῦ βασιλέως καὶ τέκνων,"},{"number":101,"text":"καὶ ὅτι τεθνήξεται νόσῳ τῆς νηδύος ἐπὶ πολὺ βασανισθεὶς καὶ τῶν ἐντέρων αὐτοῦ διʼ ὑπερβολὴν τῆς τῶν ἐντὸς διαφθορᾶς ἐκρυέντων, ὥστʼ αὐτὸν ὁρῶντα τὴν αὑτοῦ συμφορὰν καὶ μηδὲν βοηθῆσαι δυνάμενον ἔπειθʼ οὕτως ἀποθανεῖν. ταῦτα μὲν ἐδήλου διὰ τῆς ἐπιστολῆς ὁ Ἠλίας."},{"number":102,"text":"Μετʼ οὐ πολὺ δὲ στρατὸς Ἀράβων τῶν ἔγγιστα τῆς Αἰθιοπίας κατοικούντων καὶ τῶν ἀλλοφύλων εἰς τὴν Ἰωράμου βασιλείαν ἐνέβαλε καὶ τήν τε χώραν διήρπασαν καὶ τὸν οἶκον τοῦ βασιλέως, ἔτι δὲ καὶ τοὺς υἱοὺς αὐτοῦ κατέσφαξαν καὶ τὰς γυναῖκας. εἷς δὲ αὐτῷ περιλείπεται τῶν παίδων διαφυγὼν τοὺς πολεμίους Ὀχοζίας ὄνομα."},{"number":103,"text":"μετὰ δὲ ταύτην τὴν συμφορὰν αὐτὸς τὴν προειρημένην ὑπὸ τοῦ προφήτου νόσον ἐπὶ πλεῖστον νοσήσας χρόνον, ἐπέσκηψε γὰρ εἰς τὴν γαστέρα τὸ θεῖον αὐτοῦ τὴν ὀργήν, ἐλεεινῶς ἀπέθανεν ἐπιδὼν αὐτοῦ τὰ ἐντὸς ἐκρυέντα. περιύβρισε δʼ αὐτοῦ καὶ τὸν νεκρὸν ὁ λαός·"},{"number":104,"text":"λογισάμενος γὰρ οἶμαι τὸν οὕτως ἀποθανόντα κατὰ μῆνιν θεοῦ μηδὲ κηδείας τῆς βασιλεῦσι πρεπούσης ἄξιον εἶναι τυχεῖν, οὔτε ταῖς πατρῴαις ἐνεκήδευσεν αὐτὸν θήκαις οὔτε ἄλλης τιμῆς ἠξίωσεν, ἀλλʼ ὡς ἰδιώτην ἔθαψε, βιώσαντα μὲν ἔτη τεσσαράκοντα, βασιλεύσαντα δὲ ὀκτώ. παραδίδωσι δὲ τὴν ἀρχὴν ὁ δῆμος ὁ τῶν Ἱεροσολυμιτῶν τῷ παιδὶ αὐτοῦ Ὀχοζίᾳ."}],"6":[{"number":105,"text":"Ἰώραμος δὲ ὁ τῶν Ἰσραηλιτῶν βασιλεὺς μετὰ τὴν Ἄδερος τελευτὴν ἐλπίσας Ἀραμώθα πόλιν τῆς Γαλαδίτιδος ἀφαιρήσεσθαι τοὺς Σύρους στρατεύει μὲν ἐπʼ αὐτὴν μετὰ μεγάλης παρασκευῆς, ἐν δὲ τῇ πολιορκίᾳ τοξευθεὶς ὑπό τινος τῶν Σύρων οὐ καιρίως ἀνεχώρησεν εἰς Ἱεζερήλην πόλιν ἰαθησόμενος ἐν αὐτῇ τὸ τραῦμα, καταλιπὼν ἐν τῇ Ἀραμώθα τὴν στρατιὰν ἅπασαν καὶ ἡγεμόνα τὸν Ἀμασῆ παῖδα Ἰηοῦν· ἤδη γὰρ αὐτὴν ᾑρήκει κατὰ κράτος."},{"number":106,"text":"προύκειτο δʼ αὐτῷ μετὰ τὴν θεραπείαν πολεμεῖν τοῖς Σύροις. Ἐλισσαῖος δʼ ὁ προφήτης ἕνα τῶν αὑτοῦ μαθητῶν δοὺς αὐτῷ τὸ ἅγιον ἔλαιον ἔπεμψεν εἰς Ἀραμώθα χρίσοντα τὸν Ἰηοῦν καὶ φράσοντα, ὅτι τὸ θεῖον αὐτὸν ᾕρηται βασιλέα· ἄλλα τε πρὸς τούτοις εἰπεῖν ἐπιστείλας ἐκέλευε τρόπῳ φυγῆς ποιήσασθαι τὴν πορείαν, ὅπως λάθῃ πάντας ἐκεῖθεν ἀπιών."},{"number":107,"text":"ὁ δὲ γενόμενος ἐν τῇ πόλει τὸν μὲν Ἰηοῦν εὑρίσκει καθεζόμενον μετὰ τῶν τῆς στρατιᾶς ἡγεμόνων μέσον αὐτῶν καθὼς Ἐλισσαῖος αὐτῷ προεῖπε, προσελθὼν δὲ ἔφη βούλεσθαι περί τινων αὐτῷ διαλεχθῆναι."},{"number":108,"text":"τοῦ δὲ ἀναστάντος καὶ ἀκολουθήσαντος εἰς τὸ ταμιεῖον λαβὼν ὁ νεανίσκος τὸ ἔλαιον κατέχεεν αὐτοῦ τῆς κεφαλῆς καὶ τὸν θεὸν ἔφη βασιλέα χειροτονεῖν αὐτὸν ἐπʼ ὀλέθρῳ τοῦ γένους τοῦ Ἀχάβου, καὶ ὅπως ἐκδικήσῃ τὸ αἷμα τῶν προφητῶν τῶν ὑπὸ Ἰεζαβέλας παρανόμως ἀποθανόντων,"},{"number":109,"text":"ἵνʼ ὁ τούτων οἶκος τὸν αὐτὸν τρόπον ὅνπερ Ἱεροβάμου τοῦ Ναβαταίου παιδὸς καὶ Βασὰ πρόρριζος διὰ τὴν ἀσέβειαν αὐτῶν ἀφανισθῇ καὶ μηδὲν ὑπολειφθῇ σπέρμα τῆς Ἀχάβου γενεᾶς. καὶ ὁ μὲν ταῦτʼ εἰπὼν ἐξεπήδησεν ἐκ τοῦ ταμιείου σπουδάζων μηδενὶ τῶν ἐπὶ τῆς στρατιᾶς ὁραθῆναι."},{"number":110,"text":"Ὁ δὲ Ἰηοῦς προελθὼν ἧκεν ἐπὶ τὸν τόπον ἔνθα μετὰ τῶν ἡγεμόνων ἐκαθέζετο. πυνθανομένων δὲ καὶ φράζειν αὐτοῖς παρακαλούντων τί πρὸς αὐτὸν ἀφίκοιτο ὁ νεανίσκος καὶ προσέτι μαίνεσθαι λεγόντων αὐτόν, ἀλλʼ ὀρθῶς γε εἰκάσατε, εἶπε, καὶ γὰρ τοὺς λόγους μεμηνότος ἐποιήσατο."},{"number":111,"text":"σπουδαζόντων δʼ ἀκοῦσαι καὶ δεομένων ἔφη τὸν θεὸν αὐτὸν ᾑρῆσθαι βασιλέα τοῦ πλήθους εἰρηκέναι. ταῦτʼ εἰπόντος ἕκαστος περιδύων αὑτὸν ὑπεστρώννυεν αὐτῷ τὸ ἱμάτιον καὶ σαλπίζοντες τοῖς κέρασιν ἐσήμαινον Ἰηοῦν εἶναι βασιλέα."},{"number":112,"text":"ὁ δὲ ἀθροίσας τὴν στρατιὰν ἔμελλεν ἐξορμᾶν ἐπὶ Ἰώραμον εἰς Ἰεζέρελαν πόλιν, ἐν ᾗ καθὼς προεῖπον ἐθεραπεύετο τὴν πληγήν, ἣν ἔλαβε πρὸς τῇ Ἀραμώθα πολιορκίᾳ. ἔτυχε δὲ καὶ ὁ τῶν Ἱεροσολυμιτῶν βασιλεὺς Ὀχοζίας ἀφιγμένος πρὸς τὸν Ἰώραμον· υἱὸς γὰρ ἦν αὐτοῦ τῆς ἀδελφῆς ὡς καὶ προειρήκαμεν· ἐπισκέψασθαι δὲ πῶς ἐκ τοῦ τραύματος ἔχοι διὰ τὴν συγγένειαν ἐληλύθει."},{"number":113,"text":"Ἰηοῦς δὲ βουλόμενος αἰφνιδίως τοῖς περὶ τὸν Ἰώραμον προσπεσεῖν ἠξίου μηδὲ τῶν στρατιωτῶν ἀποδράντα τινὰ μηνῦσαι ταῦτα τῷ Ἰωράμῳ· τοῦτο γὰρ ἔσεσθαι λαμπρὰν ἐπίδειξιν αὐτῷ τῆς εὐνοίας καὶ τοῦ διακειμένους οὕτως ἀποδεῖξαι αὐτὸν βασιλέα."},{"number":114,"text":"Οἱ δὲ τοῖς εἰρημένοις ἡσθέντες ἐφύλαττον τὰς ὁδούς, μή τις εἰς Ἱεζέρελαν διαλαθὼν μηνύσῃ αὐτὸν τοῖς ἐκεῖ. καὶ ὁ μὲν Ἰηοῦς τῶν ἱππέων τοὺς ἐπιλέκτους παραλαβὼν καὶ καθίσας ἐφʼ ἅρματος εἰς τὴν Ἱεζέρελαν ἐπορεύετο, γενομένου δὲ ἐγγὺς ὁ σκοπός, ὃν ὁ βασιλεὺς Ἰώραμος καθεστάκει τοὺς ἐρχομένους εἰς τὴν πόλιν ἀφορᾶν, ἰδὼν μετὰ πλήθους προσελαύνοντα τὸν Ἰηοῦν ἀπήγγειλεν Ἰωράμῳ προσελαύνουσαν ἱππέων ἴλην."},{"number":115,"text":"ὁ δʼ εὐθὺς ἐκέλευσεν ἐκπεμφθῆναί τινα τῶν ἱππέων ὑπαντησόμενον καὶ τίς ἐστιν ὁ προσιὼν γνωσόμενον. ἐλθὼν οὖν πρὸς τὸν Ἰηοῦν ὁ ἱππεὺς ἐπερωτᾷ περὶ τῶν ἐν τῷ στρατοπέδῳ· πυνθάνεσθαι γὰρ ταῦτα τὸν βασιλέα. ὁ δὲ μηδὲν μὲν περὶ τούτων πολυπραγμονεῖν ἐκέλευσεν, ἕπεσθαι δʼ αὐτῷ."},{"number":116,"text":"ταῦτα ὁ σκοπὸς ὁρῶν ἀπήγγειλεν Ἰωράμῳ τὸν ἱππέα συγκαταμιγέντα τῷ πλήθει τῶν προσιόντων σὺν ἐκείνοις παραγίνεσθαι. πέμψαντος δὲ καὶ δεύτερον τοῦ βασιλέως ταὐτὸ ποιεῖν προσέταξεν Ἰηοῦς."},{"number":117,"text":"ὡς δὲ καὶ τοῦτʼ ἐδήλωσεν ὁ σκοπὸς Ἰωράμῳ, τελευταῖον αὐτὸς ἐπιβὰς ἅρματος σὺν Ὀχοζίᾳ τῷ τῶν Ἱεροσολυμιτῶν βασιλεῖ, παρῆν γὰρ αὐτὸς ὡς ἔφην ἔμπροσθεν ὀψόμενος αὐτὸν πῶς ἐκ τοῦ τραύματος ἔχοι διὰ συγγένειαν, ἐξῆλθεν ὑπαντησόμενος."},{"number":118,"text":"σχολαίτερον δὲ καὶ μετʼ εὐταξίας ὥδευεν Ἰηοῦς. καταλαβὼν δὲ ἐν ἀγρῷ Ναβώθου τοῦτον Ἰώραμος ἐπυνθάνετο, εἰ πάντα ἔχοι καλῶς τὰ κατὰ τὸ στρατόπεδον· βλασφημήσαντος δὲ πικρῶς αὐτὸν Ἰηοῦ, ὡς καὶ τὴν μητέρα αὐτοῦ φαρμακὸν ἀποκαλέσαι, δείσας ὁ βασιλεὺς τὴν διάνοιαν αὐτοῦ καὶ μηδὲν ὑγιὲς φρονεῖν αὐτὸν ὑπονοήσας στρέψας ὡς εἶχε τὸ ἅρμα ἔφυγε, φήσας πρὸς Ὀχοζίαν ἐνέδρᾳ καὶ δόλῳ κατεστρατηγῆσθαι. Ἰηοῦς δὲ τοξεύσας αὐτὸν καταβάλλει τοῦ βέλους διὰ τῆς καρδίας ἐνεχθέντος."},{"number":119,"text":"καὶ Ἰώραμος μὲν εὐθὺς πεσὼν ἐπὶ γόνυ τὴν ψυχὴν ἀφῆκεν, Ἰηοῦς δὲ προσέταξε Βαδάκῳ τῷ τῆς τρίτης μοίρας ἡγεμόνι ῥῖψαι τὸν Ἰωράμου νεκρὸν εἰς τὸν ἀγρὸν τὸν Ναβώθου ἀναμνήσας αὐτὸν τῆς Ἠλία προφητείας, ἣν Ἀχάβῳ τῷ πατρὶ αὐτοῦ τὸν Νάβωθον ἀποκτείναντι προεφήτευσεν, ὡς ἀπολεῖται αὐτός τε καὶ τὸ γένος αὐτοῦ ἐν τῷ ἐκείνου χωρίῳ·"},{"number":120,"text":"ταῦτα γὰρ καθεζόμενος ὄπισθεν τοῦ ἅρματος Ἀχάβου λέγοντος ἀκοῦσαι τοῦ προφήτου. καὶ δὴ τοῦτο συνέβη γενέσθαι κατὰ τὴν πρόρρησιν τὴν ἐκείνου. πεσόντος δὲ Ἰωράμου δείσας περὶ τῆς αὑτοῦ σωτηρίας Ὀχοζίας τὸ ἅρμα εἰς ἑτέραν ὁδὸν ἐξένευσε λήσεσθαι τὸν Ἰηοῦν ὑπολαβών."},{"number":121,"text":"ὁ δʼ ἐπιδιώξας καὶ καταλαβὼν ἔν τινι προσβάσει τοξεύσας ἔτρωσε, καταλιπὼν δὲ τὸ ἅρμα καὶ ἀναβὰς ἵππῳ φεύγει τὸν Ἰηοῦν εἰς Μαγιαδδὼ κἀκεῖ θεραπευόμενος μετʼ ὀλίγον ἐκ τῆς πληγῆς τελευτᾷ. κομισθεὶς δʼ εἰς Ἱεροσόλυμα τῆς ἐκεῖ ταφῆς τυγχάνει βασιλεύσας μὲν ἐνιαυτὸν ἕνα, πονηρὸς δὲ καὶ χείρων τοῦ πατρὸς γενόμενος."},{"number":122,"text":"Τοῦ δὲ Ἰηοῦ εἰσελθόντος εἰς τὰ Ἱεζέρελα κοσμησαμένη Ἰεζαβέλα καὶ στᾶσα ἐπὶ τοῦ πύργου καλός, εἶπε, δοῦλος ὃς ἀποκτείνει τὸν δεσπότην. ὁ δὲ ἀναβλέψας πρὸς αὐτὴν ἐπυνθάνετο τίς εἴη καὶ καταβᾶσαν ἥκειν πρὸς αὑτὸν ἐκέλευσεν καὶ τέλος τοῖς εὐνούχοις προσέταξεν αὐτὴν ἀπὸ τοῦ πύργου βαλεῖν."},{"number":123,"text":"καταφερομένη δʼ ἤδη τό τε τεῖχος περιέρρανε τῷ αἵματι καὶ συμπατηθεῖσα ὑπὸ τῶν ἵππων οὕτως ἀπέθανε. τούτων δὴ γενομένων παρελθὼν Ἰηοῦς εἰς τὰ βασίλεια σὺν τοῖς φίλοις ἑαυτὸν ἐκ τῆς ὁδοῦ ἀνεκτᾶτο τοῖς τε ἄλλοις καὶ τραπέζῃ. προσέταξε δὲ τοῖς οἰκέταις ἀνελομένοις τὴν Ἰεζαβέλαν θάψαι διὰ τὸ γένος· ἦν γὰρ ἐκ βασιλέων."},{"number":124,"text":"εὗρον δʼ οὐδὲν τοῦ σώματος αὐτῆς οἱ προσταχθέντες τὴν κηδείαν ἢ μόνα τὰ ἀκρωτήρια, τὸ δὲ ἄλλο πᾶν ὑπὸ κυνῶν ἦν δεδαπανημένον. ταῦτʼ ἀκούσας Ἰηοῦς ἐθαύμαζε τὴν Ἠλίου προφητείαν· οὗτος γὰρ αὐτὴν ἐν Ἱεζερέλα προεῖπε τοῦτον ἀπολεῖσθαι τὸν τρόπον."},{"number":125,"text":"Ὄντων δʼ Ἀχάβῳ παίδων ἑβδομήκοντα τρεφομένων δʼ αὐτῶν ἐν Σαμαρείᾳ πέμπει δύο ἐπιστολὰς Ἰηοῦς τὴν μὲν τοῖς παιδαγωγοῖς τὴν ἑτέραν δὲ τοῖς ἄρχουσι τῶν Σαμαρέων, λέγων τὸν ἀνδρειότατον τῶν Ἀχάβου παίδων ἀποδεῖξαι βασιλέα· καὶ γὰρ ἁρμάτων αὐτῷ εἶναι πλῆθος καὶ ἵππων καὶ ὅπλων καὶ στρατιᾶς καὶ πόλεις ὀχυρὰς ἔχειν· καὶ τοῦτο ποιήσαντας εἰσπράττεσθαι δίκην ὑπὲρ τοῦ δεσπότου."},{"number":126,"text":"ταῦτα δὲ γράφει διάπειραν βουλόμενος λαβεῖν τῆς τῶν Σαμαρέων διανοίας. ἀναγνόντες δὲ τὰ γράμματα οἵ τε ἄρχοντες καὶ οἱ παιδαγωγοὶ κατέδεισαν, καὶ λογισάμενοι μηδὲν δύνασθαι ποιεῖν πρὸς τοῦτο, δύο γὰρ μεγίστων ἐκράτησε βασιλέων, ἀντέγραψαν ὁμολογοῦντες αὐτὸν ἔχειν δεσπότην καὶ ποιήσειν ὃ ἂν κελεύῃ."},{"number":127,"text":"ὁ δὲ πρὸς ταῦτα ἀντέγραψεν αὑτῷ τε ὑπακούειν κελεύων καὶ τῶν Ἀχάβου παίδων τὰς κεφαλὰς ἀποτεμόντας πέμψαι πρὸς αὐτόν. οἱ δὲ ἄρχοντες μεταπεμψάμενοι τοὺς τροφεῖς τῶν παίδων προσέταξαν ἀποκτείνασιν αὐτοὺς τὰς κεφαλὰς ἀποτεμεῖν καὶ πέμψαι πρὸς Ἰηοῦν. οἱ δʼ οὐδὲν ὅλως φεισάμενοι τοῦτο ἔπραξαν καὶ συνθέντες εἴς τινα πλεκτὰ ἀγγεῖα τὰς κεφαλὰς ἀπέπεμψαν εἰς Ἰεζέρελαν."},{"number":128,"text":"κομισθεισῶν δὲ τούτων ἀγγέλλεται μετὰ τῶν φίλων δειπνοῦντι τῷ Ἰηοῦ, ὅτι κομισθεῖεν αἱ τῶν Ἀχάβου παίδων κεφαλαί. ὁ δὲ πρὸ τῆς πύλης ἐξ ἑκατέρου μέρους ἐκέλευσεν ἐξ αὐτῶν ἀναστῆσαι βουνούς."},{"number":129,"text":"γενομένου δὲ τούτου ἅμα ἡμέρᾳ πρόεισιν ὀψόμενος καὶ θεασάμενος ἤρξατο πρὸς τὸν παρόντα λαὸν λέγειν, ὡς αὐτὸς μὲν ἐπὶ τὸν δεσπότην στρατεύσαιτο τὸν αὑτοῦ κἀκεῖνον ἀποκτείνειε, τούτους δὲ οὐκ αὐτὸς ἀνέλοι· γινώσκειν δὲ αὐτοὺς ἠξίου περὶ τῆς Ἀχάβου γενεᾶς, ὅτι πάντα κατὰ τὴν τοῦ θεοῦ προφητείαν γέγονε καὶ ὁ οἶκος αὐτοῦ, καθὼς καὶ Ἠλίας προεῖπεν, ἀπόλωλε."},{"number":130,"text":"προσδιαφθείρας δὲ καὶ τοὺς παρὰ τοῖς Ἰεζερελίταις εὑρεθέντας ἐκ τῆς Ἀχάβου συγγενείας ἱππεῖς εἰς Σαμάρειαν ἐπορεύετο. κατὰ δὲ τὴν ὁδὸν τοῖς Ὀχοζία συμβαλὼν οἰκείοις τοῦ βασιλέως τῶν Ἱεροσολυμιτῶν ἀνέκρινεν αὐτούς, τί δή ποτε παρεγένοντο."},{"number":131,"text":"οἱ δʼ ἀσπασόμενοί τε Ἰώραμον καὶ τὸν αὑτῶν βασιλέα Ὀχοζίαν ἥκειν ἔφασκον· οὐ γὰρ ᾔδεσαν αὐτοὺς ἀμφοτέρους ὑπʼ αὐτοῦ πεφονευμένους. Ἰηοῦς δὲ καὶ τούτους συλληφθέντας ἀναιρεθῆναι προσέταξεν ὄντας τὸν ἀριθμὸν τεσσαράκοντα καὶ δύο."},{"number":132,"text":"Συναντᾷ δʼ αὐτῷ μετὰ τούτους ἀνὴρ ἀγαθὸς καὶ δίκαιος Ἰωνάδαβος ὄνομα φίλος αὐτῷ πάλαι γεγονώς, ὃς ἀσπασάμενος αὐτὸν ἐπαινεῖν ἤρξατο τῷ πάντα κατὰ βούλησιν πεποιηκέναι τοῦ θεοῦ τὴν οἰκίαν ἐξαφανίσας τὴν Ἀχάβου."},{"number":133,"text":"Ἰηοῦς δὲ ἀναβάντα ἐπὶ τὸ ἅρμα συνεισελθεῖν αὐτὸν εἰς Σαμάρειαν παρεκάλει λέγων ἐπιδείξειν, πῶς οὐδενὸς φείσεται πονηροῦ, ἀλλὰ καὶ τοὺς ψευδοπροφήτας καὶ τοὺς ψευδιερεῖς καὶ τοὺς ἐξαπατήσαντας τὸ πλῆθος, ὡς τὴν μὲν τοῦ μεγίστου θεοῦ θρησκείαν ἐγκαταλιπεῖν τοὺς δὲ ξενικοὺς προσκυνεῖν, τιμωρήσεται· κάλλιστον δʼ εἶναι θεαμάτων καὶ ἥδιστον ἀνδρὶ χρηστῷ καὶ δικαίῳ κολαζομένους πονηρούς."},{"number":134,"text":"τούτοις πεισθεὶς ὁ Ἰωνάδαβος ἀναβὰς εἰς τὸ ἅρμα εἰς Σαμάρειαν παραγίνεται. ἀναζητήσας δὲ πάντας τοὺς Ἀχάβου συγγενεῖς Ἰηοῦς ἀποκτείνει. βουλόμενος δὲ μηδένα τῶν ψευδοπροφητῶν μηδʼ ἱερέων τῶν Ἀχάβου θεῶν τὴν τιμωρίαν διαφυγεῖν ἀπάτῃ καὶ δόλῳ πάντας αὐτοὺς συνέλαβεν·"},{"number":135,"text":"ἀθροίσας γὰρ τὸν λαὸν ἔφη βούλεσθαι διπλασίονας ὧν Ἄχαβος εἰσηγήσατο θεῶν προσκυνεῖν καὶ τοὺς ἐκείνων ἱερεῖς καὶ προφήτας ἠξίου καὶ δούλους αὐτῶν παρεῖναι· θυσίας γὰρ πολυτελεῖς καὶ μεγάλας ἐπιτελεῖν μέλλειν τοῖς Ἀχάβου θεοῖς· τὸν δʼ ἀπολειφθέντα τῶν ἱερέων θανάτῳ ζημιώσειν. ὁ δὲ θεὸς Ἀχάβου Βαὰλ ἐκαλεῖτο."},{"number":136,"text":"τάξας δὲ ἡμέραν, καθʼ ἣν ἔμελλε ποιήσειν τὰς θυσίας διέπεμπεν ἀνὰ πᾶσαν τὴν Ἰσραηλιτῶν χώραν τοὺς ἄξοντας πρὸς αὐτὸν τοὺς ἱερεῖς τοῦ Βαάλ. ἐκέλευσε δʼ Ἰηοῦς τῷ ἱερεῖ δοῦναι πᾶσιν ἐνδύματα· λαβόντων δὲ παρελθὼν εἰς τὸν οἶκον μετὰ τοῦ φίλου Ἰωναδάβου μή τις ἐν αὐτοῖς ἀλλόφυλος εἴη καὶ ξένος ἐρευνῆσαι προσέταξεν· οὐ βούλεσθαι γὰρ τοῖς ἱεροῖς αὐτῶν ἀλλότριον παρατυγχάνειν."},{"number":137,"text":"τῶν δὲ εἰπόντων μὲν οὐδένα παρεῖναι ξένον καταρξαμένων δὲ τῶν θυσιῶν περιέστησεν ὀγδοήκοντα τὸν ἀριθμὸν ἄνδρας, οὓς ᾔδει πιστοτάτους τῶν ὁπλιτῶν, κελεύσας αὐτοῖς ἀποκτεῖναι τοὺς ψευδοπροφήτας καὶ νῦν τοῖς πατρίοις ἔθεσι τιμωρεῖν πολὺν ἤδη χρόνον ὠλιγωρημένοις, ὑπὲρ τῶν διαφυγόντων τὰς ἐκείνων ἀφαιρεθήσεσθαι ψυχὰς ἀπειλήσας."},{"number":138,"text":"οἱ δὲ τούς τε ἄνδρας ἅπαντας κατέσφαξαν καὶ τὸν οἶκον τοῦ Βαὰλ ἐμπρήσαντες ἐκάθηραν οὕτως ἀπὸ τῶν ξενικῶν ἐθισμῶν τὴν Σαμάρειαν. οὗτος ὁ Βαὰλ Τυρίων ἦν θεός. Ἄχαβος δὲ τῷ πενθερῷ βουλόμενος χαρίσασθαι Εἰθωβάλῳ Τυρίων ὄντι βασιλεῖ καὶ Σιδωνίων ναόν τε αὐτῷ κατεσκεύασεν ἐν Σαμαρείᾳ καὶ προφήτας ἀπέδειξε καὶ πάσης θρησκείας ἠξίου."},{"number":139,"text":"ἀφανισθέντος δὲ τούτου τοῦ θεοῦ τὰς χρυσᾶς δαμάλεις προσκυνεῖν τοῖς Ἰσραηλίταις Ἰηοῦς ἐπέτρεψε. ταῦτα δὲ διαπραξαμένῳ καὶ προνοήσαντι τῆς κολάσεως τῶν ἀσεβῶν ὁ θεὸς διὰ τοῦ προφήτου προεῖπεν ἐπὶ τέσσαρας γενεὰς τοὺς παῖδας αὐτοῦ βασιλεύσειν τῶν Ἰσραηλιτῶν. καὶ τὰ μὲν περὶ Ἰηοῦν ἐν τούτοις ὑπῆρχεν."}],"7":[{"number":140,"text":"Ὀθλία δʼ ἡ Ἀχάβου θυγάτηρ ἀκούσασα τήν τʼ Ἰωράμου τἀδελφοῦ τελευτὴν καὶ τὴν Ὀχοζία τοῦ παιδὸς καὶ τοῦ γένους τῶν βασιλέων τὴν ἀπώλειαν ἐσπούδαζε μηδένα τῶν ἐκ τοῦ Δαυίδου καταλιπεῖν οἴκου, πᾶν δʼ ἐξαφανίσαι τὸ γένος, ὡς ἂν μηδὲ εἷς ἐξ αὐτοῦ βασιλεὺς ἔτι γένοιτο."},{"number":141,"text":"καὶ τοῦθʼ ὡς μὲν ᾤετο διεπράξατο, διεσώθη δὲ εἷς υἱὸς Ὀχοζίου, τρόπῳ δὲ τοιούτῳ τὴν τελευτὴν διέφυγεν· ἦν Ὀχοζίᾳ ὁμοπάτριος ἀδελφὴ Ὠσαβέθη ὄνομα· ταύτῃ συνῆν ὁ ἀρχιερεὺς Ἰώδας."},{"number":142,"text":"εἰσελθοῦσα δʼ εἰς τὸ βασίλειον καὶ τοῖς ἀπεσφαγμένοις τὸν Ἰώασον, τοῦτο γὰρ προσηγορεύετο τὸ παιδίον ἐνιαύσιον, ἐγκεκρυμμένον εὑροῦσα μετὰ τῆς τρεφούσης βαστάσασα μετʼ αὐτῆς εἰς τὸ ταμιεῖον ἀπέκλεισε τῶν κλινῶν καὶ λανθάνοντες ἀνέθρεψαν αὐτή τε καὶ ὁ ἀνὴρ αὐτῆς Ἰώδας ἐν τῷ ἱερῷ ἔτεσιν ἕξ, οἷς ἐβασίλευσεν Ὀθλία τῶν Ἱεροσολύμων καὶ τῶν δύο φυλῶν."},{"number":143,"text":"Τῷ δὲ ἑβδόμῳ κοινολογησάμενός τισιν Ἰώδας πέντε τὸν ἀριθμὸν ἑκατοντάρχαις καὶ πείσας αὐτοὺς συνεπιθέσθαι μὲν τοῖς κατὰ τῆς Ὀθλίας ἐγχειρουμένοις, τὴν δὲ βασιλείαν τῷ παιδὶ περιποιῆσαι, λαβὼν ὅρκους οἷς τὸ ἀδεὲς παρὰ τῶν συνεργούντων βεβαιοῦται τὸ λοιπὸν ἐθάρρει ταῖς κατὰ τῆς Ὀθλίας ἐλπίσιν."},{"number":144,"text":"οἱ δʼ ἄνδρες, οὓς ὁ ἱερεὺς Ἰώδας κοινωνοὺς τῆς πράξεως παρειλήφει, περιπορευθέντες ἅπασαν τὴν χώραν τοὺς ἱερεῖς καὶ τοὺς Ληουίτας ἐξ αὐτῆς ἀθροίσαντες καὶ τοὺς τῶν φυλῶν προεστηκότας ἧκον ἄγοντες εἰς Ἱεροσόλυμα πρὸς τὸν ἀρχιερέα."},{"number":145,"text":"ὁ δὲ πίστιν ᾔτησεν αὐτοὺς ἔνορκον, ἦ μὴν φυλάξειν ὅπερ ἂν μάθωσιν ἀπόρρητον παρʼ αὐτοῦ σιωπῆς ἅμα καὶ συμπράξεως δεόμενον. ὡς δʼ ἀσφαλὲς αὐτῷ λέγειν ὀμωμοκότων ἐγένετο παραγαγὼν ὃν ἐκ τοῦ Δαυίδου γένους ἔτρεφεν οὗτος ἡμῖν, εἶπε, βασιλεὺς ἐξ ἐκείνης τῆς οἰκίας, ἣν ἴστε τὸν θεὸν ἡμῖν προφητεύσαντα βασιλεύσειν ἄχρι τοῦ παντὸς χρόνου."},{"number":146,"text":"παραινῶ δὲ τὴν τρίτην ὑμῶν μοῖραν φυλάττειν αὐτὸν ἐν τῷ ἱερῷ, τὴν δὲ τρίτην ταῖς πύλαις ἐφεστάναι τοῦ τεμένους ἁπάσαις, ἡ δὲ μετὰ ταύτην ἐχέτω τὴν τῆς ἀνοιγομένης καὶ φερούσης εἰς τὸ βασίλειον πύλης φυλακήν· τὸ δὲ ἄλλο πλῆθος ἄοπλον ἐν τῷ ἱερῷ τυγχανέτω· μηδένα δʼ εἰσελθεῖν ὁπλίτην ἐάσητε ἢ μόνον ἱερέα."},{"number":147,"text":"προσδιέταξε δὲ τούτοις μέρος τι τῶν ἱερέων καὶ Ληουίτας περὶ αὐτὸν εἶναι τὸν βασιλέα ταῖς μαχαίραις ἐσπασμέναις αὐτὸν δορυφοροῦντας, τὸν δὲ τολμήσαντα παρελθεῖν εἰς τὸ ἱερὸν ὡπλισμένον ἀναιρεῖσθαι παραυτίκα·"},{"number":148,"text":"δείσαντας δὲ μηδὲν παραμεῖναι τῇ φυλακῇ τοῦ βασιλέως. καὶ οἱ μὲν οἷς ὁ ἀρχιερεὺς συνεβούλευσεν τούτοις πεισθέντες ἔργῳ τὴν προαίρεσιν ἐδήλουν. ἀνοίξας δὲ Ἰώδας τὴν ἐν τῷ ἱερῷ ὁπλοθήκην, ἣν Δαυίδης κατεσκεύασε, διεμέρισε τοῖς ἑκατοντάρχαις ἅμα καὶ ἱερεῦσι καὶ Ληουίταις ἅπανθʼ ὅσʼ εὗρεν ἐν αὐτῇ δόρατά τε καὶ φαρέτρας καὶ εἴ τι ἕτερον εἶδος ὅπλου κατέλαβε, καὶ καθωπλισμένους ἔστησεν ἐν κύκλῳ περὶ τὸ ἱερὸν συναψαμένους τὴν χεῖρα καὶ τὴν εἴσοδον τοῖς οὐ προσήκουσιν οὕτως ἀποτειχίσοντας."},{"number":149,"text":"συναγαγόντες δὲ τὸν παῖδα εἰς τὸ μέσον ἐπέθεσαν αὐτῷ τὸν στέφανον τὸν βασιλικὸν καὶ τῷ ἐλαίῳ χρίσας Ἰώδας ἀπέδειξε βασιλέα· τὸ δὲ πλῆθος χαῖρον καὶ κροταλίζον ἐβόα σώζεσθαι τὸν βασιλέα."},{"number":150,"text":"Τοῦ δὲ θορύβου καὶ τῶν ἐπαίνων Ὀθλία παρʼ ἐλπίδας ἀκούσασα τεταραγμένη σφόδρα τῇ διανοίᾳ μετὰ τῆς ἰδίας ἐξεπήδησε στρατιᾶς ἐκ τοῦ βασιλείου. καὶ παραγενομένην εἰς τὸ ἱερὸν αὐτὴν οἱ μὲν ἱερεῖς εἰσδέχονται, τοὺς δʼ ἑπομένους ὁπλίτας εἶρξαν εἰσελθεῖν οἱ περιεστῶτες ἐν κύκλῳ ὑπὸ τοῦ ἀρχιερέως τοῦτο προστεταγμένοι."},{"number":151,"text":"ἰδοῦσα δὲ Ὀθλία τὸν παῖδα ἐπὶ τῆς σκηνῆς ἑστῶτα καὶ τὸν βασίλειον ἐπικείμενον στέφανον περιρρηξαμένη καὶ δεινὸν ἀνακραγοῦσα φονεύειν ἐκέλευε τὸν ἐπιβουλεύσαντα αὐτῇ καὶ τὴν ἀρχὴν ἀφελέσθαι σπουδάσαντα. Ἰώδας δὲ καλέσας τοὺς ἑκατοντάρχας ἐκέλευσεν αὐτοὺς ἀπαγαγόντας τὴν Ὀθλίαν εἰς τὴν φάραγγα τὴν Κεδρῶνος ἀνελεῖν αὐτὴν ἐκεῖ· μὴ γὰρ βούλεσθαι μιᾶναι τὸ ἱερὸν αὐτόθι τὴν ἀλιτήριον τιμωρησάμενον."},{"number":152,"text":"προσέταξε δὲ κἂν βοηθῶν τις προσέλθῃ κἀκεῖνον ἀνελεῖν. ἐλλαβόμενοι τοίνυν τῆς Ὀθλίας οἱ προστεταγμένοι τὴν ἀναίρεσιν αὐτῆς ἐπὶ τὴν πύλην τῶν ἡμιόνων τοῦ βασιλέως ἤγαγον κἀκεῖ διεχρήσαντο."},{"number":153,"text":"Ὡς δὲ τὰ περὶ τὴν Ὀθλίαν τοῦτον ἐστρατηγήθη τὸν τρόπον συγκαλέσας τόν τε δῆμον καὶ τοὺς ὁπλίτας ὁ Ἰώδας εἰς τὸ ἱερὸν ἐξώρκωσεν εὐνοεῖν τῷ βασιλεῖ καὶ προνοεῖν αὐτοῦ τῆς σωτηρίας καὶ τῆς ἐπὶ πλεῖον ἀρχῆς· ἔπειτʼ αὐτὸν τὸν βασιλέα τιμήσειν τὸν θεὸν καὶ μὴ παραβῆναι τοὺς Μωσήους νόμους δοῦναι πίστιν ἠνάγκασε."},{"number":154,"text":"καὶ μετὰ ταῦτʼ εἰσδραμόντες τὸν τοῦ Βαὰλ οἶκον, ὃν Ὀθλία τε καὶ ὁ ἀνὴρ αὐτῆς Ἰώραμος κατεσκεύασεν ἐφʼ ὕβρει μὲν τοῦ πατρίου θεοῦ τιμῇ δὲ Ἀχάβου κατέσκαψαν καὶ τὸν ἔχοντα τὴν ἱερωσύνην αὐτοῦ Μάθαν ἀπέκτειναν."},{"number":155,"text":"τὴν δʼ ἐπιμέλειαν καὶ φυλακὴν τοῦ ἱεροῦ τοῖς ἱερεῦσι καὶ Ληουίταις ἐπέτρεψεν Ἰώδας κατὰ τὴν Δαυίδου τοῦ βασιλέως διάταξιν κελεύσας αὐτοὺς δὶς τῆς ἡμέρας ἐπιφέρειν τὰς νενομισμένας τῶν ὁλοκαυτώσεων θυσίας καὶ θυμιᾶν ἀκολούθως τῷ νόμῳ. ἀπέδειξε δέ τινας τῶν Ληουιτῶν καὶ πυλωροὺς ἐπὶ φυλακῇ τοῦ τεμένους, ὡς μηδένα μεμιασμένον παριέναι λανθάνοντα."},{"number":156,"text":"Τούτων δʼ ἕκαστα διατάξας μετὰ τῶν ἑκατοντάρχων καὶ ἡγεμόνων καὶ τοῦ λαοῦ παντὸς ἐκ τοῦ ἱεροῦ παραλαβὼν ἄγει τὸν Ἰώασον εἰς τὸ βασίλειον, καὶ καθίσαντος ἐπὶ τὸν βασιλικὸν θρόνον ἐπευφήμησέ τε τὸ πλῆθος καὶ πρὸς εὐωχίαν τραπέντες ἐπὶ πολλὰς ἑώρτασαν ἡμέρας· ἡ μέντοι γε πόλις ἐπὶ τῷ τὴν Ὀθλίαν ἀποθανεῖν ἡσυχίαν ἤγαγεν."},{"number":157,"text":"ἦν δὲ Ἰώασος ὅτε τὴν βασιλείαν παρέλαβεν ἐτῶν ἑπτά, μήτηρ δὲ ἦν αὐτῷ τὸ μὲν ὄνομα Σαβιὰ πατρίδος δὲ Βηρσαβεέ. πολλὴν δʼ ἐποιήσατο τῶν νομίμων φυλακὴν καὶ περὶ τὴν τοῦ θεοῦ θρησκείαν φιλοτιμίαν παρὰ πάντα τὸν χρόνον ὃν Ἰώδας ἐβίωσεν."},{"number":158,"text":"ἔγημε δὲ καὶ γυναῖκας δύο παρελθὼν εἰς ἡλικίαν δόντος τοῦ ἀρχιερέως, ἐξ ὧν καὶ ἄρρενες αὐτῷ καὶ θήλειαι παῖδες ἐγένοντο. τὰ μὲν οὖν περὶ τοῦ βασιλέως Ἰωάσου, ὡς τὴν τῆς Ὀθλίας ἐπιβουλὴν διέφυγε καὶ τὴν βασιλείαν παρέλαβεν, ἐν τούτοις δεδηλώκαμεν."}],"8":[{"number":159,"text":"Ἀζάηλος δʼ ὁ τῶν Σύρων βασιλεὺς πολεμῶν τοῖς Ἰσραηλίταις καὶ τῷ βασιλεῖ αὐτῶν Ἰηοῦ διέφθειρε τῆς πέραν Ἰορδάνου χώρας τὰ πρὸς τὴν ἀνατολὴν τῶν Ῥουβηνιτῶν καὶ Γαδιτῶν καὶ Μανασσιτῶν ἔτι δὲ καὶ τὴν Γαλαδῖτιν καὶ Βαταναίαν πυρπολῶν πάντα καὶ διαρπάζων καὶ τοῖς εἰς χεῖρας ἀπαντῶσι βίαν προσφέρων."},{"number":160,"text":"οὐ γὰρ ἔφθη αὐτὸν Ἰηοῦς ἀμύνασθαι κακοῦντα τὴν χώραν, ἀλλὰ καὶ τῶν εἰς τὸ θεῖον ὑπερόπτης γενόμενος καὶ καταφρονήσας τῆς ὁσίας καὶ τῶν νόμων ἀπέθανε βασιλεύσας ἔτη τῶν Ἰσραηλιτῶν ἑπτὰ καὶ εἴκοσι. ἐτάφη δὲ ἐν Σαμαρείᾳ τῆς ἀρχῆς διάδοχον Ἰώαζον τὸν υἱὸν καταλιπών."},{"number":161,"text":"Τὸν δὲ τῶν Ἱεροσολυμιτῶν βασιλέα Ἰώασον ὁρμή τις ἔλαβε τὸν ναὸν ἀνακαινίσαι τοῦ θεοῦ, καὶ τὸν ἀρχιερέα καλέσας Ἰώδαν εἰς ἅπασαν ἐκέλευσε πέμψαι τὴν χώραν τοὺς Ληουίτας καὶ ἱερέας αἰτήσοντας ὑπὲρ ἑκάστης κεφαλῆς ἡμίσικλον ἀργύρου εἰς ἐπισκευὴν καὶ ἀνανέωσιν τοῦ ναοῦ καταλυθέντος ὑπὸ Ἰωράμου καὶ Ὀθλίας καὶ τῶν παίδων αὐτῆς."},{"number":162,"text":"ὁ δʼ ἀρχιερεὺς τοῦτο μὲν οὐκ ἐποίησε συνεὶς ὡς οὐδεὶς προεῖται τἀργύριον, τρίτῳ δὲ καὶ εἰκοστῷ τῆς βασιλείας ἔτει μεταπεμψαμένου τοῦ βασιλέως αὐτόν τε καὶ Ληουίτας καὶ ὡς παρακούσαντας ὧν προσέταξεν αἰτιωμένου καὶ κελεύσαντος εἰς τὸ μέλλον προνοεῖσθαι τῆς ἐπισκευῆς τοῦ ναοῦ, στρατηγήματι χρῆται πρὸς τὴν συλλογὴν τῶν χρημάτων ὁ ἀρχιερεὺς ᾧ τὸ πλῆθος ἡδέως ἔσχε τοιούτῳ·"},{"number":163,"text":"ξύλινον κατασκευάσας θησαυρὸν καὶ κλείσας πανταχόθεν ὀπὴν αὐτῷ μίαν ἤνοιξεν. ἔπειτα θεὶς εἰς τὸ ἱερὸν παρὰ τὸν βωμὸν ἐκέλευσεν ἕκαστον ὅσον βούλεται βάλλειν εἰς αὐτὸν διὰ τῆς ὀπῆς εἰς τὴν ἐπισκευὴν τοῦ ναοῦ. πρὸς τοῦτο πᾶς ὁ λαὸς εὖ διετέθη καὶ πολὺν ἄργυρον καὶ χρυσὸν φιλοτιμούμενοι καὶ συνεισφέροντες ἤθροισαν."},{"number":164,"text":"κενοῦντες δὲ τὸν θησαυρὸν καὶ παρόντος τοῦ βασιλέως ἀριθμοῦντες τὸ συνειλεγμένον ὅ τε γραμματεὺς καὶ ἱερεὺς τῶν γαζοφυλακίων ἔπειτʼ εἰς τὸν αὐτὸν ἐτίθεσαν τόπον. καὶ τοῦτʼ ἐποίουν ἑκάστης ἡμέρας. ὡς δʼ ἀποχρῶν τὸ πλῆθος ἐδόκει τῶν χρημάτων ἔπεμψαν μισθούμενοι λατόμους καὶ οἰκοδόμους ὁ ἀρχιερεὺς Ἰώδας καὶ ὁ βασιλεὺς Ἰώασος καὶ ἐπὶ ξύλα μεγάλα καὶ τῆς καλλίστης ὕλης."},{"number":165,"text":"ἐπισκευασθέντος δὲ τοῦ ναοῦ τὸν ὑπολειφθέντα χρυσὸν καὶ ἄργυρον, οὐκ ὀλίγος δὲ ἦν, εἴς τε κρατῆρας καὶ οἰνοχόας καὶ ἐκπώματα καὶ τὰ λοιπὰ σκεύη κατεχρήσαντο θυσίαις τε πολυτελέσιν ὁσημέραι τὸν βωμὸν πιαίνοντες διετέλουν. καὶ ταῦτα μὲν ἐφʼ ὅσον Ἰώδας χρόνον ἔζη τῆς προσηκούσης ἐτύγχανε σπουδῆς."},{"number":166,"text":"Ὡς δʼ ἐτελεύτησεν οὗτος ἔτη μὲν βιώσας ἑκατὸν καὶ τριάκοντα δίκαιος δὲ καὶ πάντα χρηστὸς γενόμενος, ἐτάφη δʼ ἐν ταῖς βασιλικαῖς θήκαις ἐν Ἱεροσολύμοις, ὅτι τῷ Δαυίδου γένει τὴν βασιλείαν ἀνεκτήσατο, προέδωκεν ὁ βασιλεὺς τὴν ἐπιμέλειαν τὴν πρὸς τὸν θεόν."},{"number":167,"text":"συνδιεφθάρησαν δʼ αὐτῷ καὶ οἱ τοῦ πλήθους πρωτεύοντες, ὥστε πλημμελεῖν εἰς τὰ δίκαια καὶ νενομισμένα παρʼ αὐτοῖς ἄριστα εἶναι. δυσχεράνας δὲ ὁ θεὸς ἐπὶ τῇ μεταβολῇ τοῦ βασιλέως καὶ τῶν ἄλλων πέμπει τοὺς προφήτας διαμαρτυρησομένους τε τὰ πραττόμενα καὶ παύσοντας τῆς πονηρίας αὐτούς."},{"number":168,"text":"οἱ δʼ ἰσχυρὸν ἔρωτα καὶ δεινὴν ἐπιθυμίαν ἄρα ταύτης εἶχον, ὡς μήτε οἷς οἱ πρὸ αὐτῶν ἐξυβρίσαντες εἰς τὰ νόμιμα πανοικὶ κολασθέντες ἔπαθον, μήθʼ οἷς οἱ προφῆται προύλεγον πεισθέντες μετανοῆσαι καὶ μετελθεῖν ἐξ ὧν εἰς ἐκεῖνα παρανομήσαντες ἐτράπησαν· ἀλλὰ καὶ Ζαχαρίαν υἱὸν τοῦ ἀρχιερέως Ἰώδα λίθοις ὁ βασιλεὺς ἐκέλευσε βληθέντα ἀποθανεῖν ἐν τῷ ἱερῷ τῶν τοῦ πατρὸς εὐεργεσιῶν αὐτοῦ λαθόμενος,"},{"number":169,"text":"ὅτι τοῦ θεοῦ προφητεύειν αὐτὸν ἀποδείξαντος στὰς ἐν μέσῳ τῷ πλήθει συνεβούλευεν αὐτῷ τε καὶ τῷ βασιλεῖ τὰ δίκαια πράττειν καὶ τιμωρίαν ὅτι μεγάλην ὑφέξουσι μὴ πειθόμενοι προύλεγε. τελευτῶν μέντοι Ζαχαρίας μάρτυρα καὶ δικαστὴν ὧν ἔπασχε τὸν θεὸν ἐποιεῖτο ἀντὶ χρηστῆς συμβουλίας καὶ ὧν ὁ πατὴρ αὐτοῦ παρέσχεν Ἰωάσῳ πικρῶς καὶ βιαίως ἀπολλύμενος."},{"number":170,"text":"Ἔδωκε μέντοι γε οὐκ εἰς μακρὰν ὁ βασιλεὺς δίκην ὧν παρηνόμησεν· ἐμβαλόντος γὰρ Ἀζαήλου τοῦ Σύρων βασιλέως εἰς τὴν χώραν αὐτοῦ καὶ τὴν Γίτταν καταστρεψαμένου καὶ λεηλατήσαντος ἐπʼ αὐτὸν στρατεύειν εἰς Ἱεροσόλυμα φοβηθεὶς ὁ Ἰώασος πάντας ἐκκενώσας τοὺς τοῦ θεοῦ θησαυροὺς καὶ τοὺς τῶν βασιλείων καὶ τὰ ἀναθήματα καθελών, ἔπεμψε τῷ Σύρῳ τούτοις ὠνούμενος τὸ μὴ πολιορκηθῆναι μηδὲ κινδυνεύειν περὶ τῶν ὅλων."},{"number":171,"text":"ὁ δὲ πεισθεὶς τῇ τῶν χρημάτων ὑπερβολῇ τὴν στρατιὰν οὐκέτʼ ἤγαγεν ἐπὶ τὰ Ἱεροσόλυμα. νόσῳ μέντοι χαλεπῇ περιπεσὼν ὁ Ἰώασος ἐπιθεμένων αὐτῷ τῶν φίλων, οἳ τὸν Ζαχαρίου θάνατον ἐκδικοῦντες τοῦ Ἰώδα παιδὸς ἐπεβούλευσαν τῷ βασιλεῖ, διεφθάρη πρὸς αὐτῶν·"},{"number":172,"text":"καὶ θάπτεται μὲν ἐν Ἱεροσολύμοις, οὐκ ἐν ταῖς θήκαις δὲ τῶν προγόνων ἀσεβὴς γενόμενος. ἐβίωσε δὲ ἔτη ἑπτὰ καὶ τεσσαράκοντα, τὴν δὲ βασιλείαν αὐτοῦ διαδέχεται Ἀμασίας ὁ παῖς."},{"number":173,"text":"Εἰκοστῷ δὲ καὶ πρώτῳ τῆς Ἰωάσου βασιλείας παρέλαβε τὴν τῶν Ἰσραηλιτῶν ἡγεμονίαν Ἰώαζος ὁ τοῦ Ἰηοῦδος υἱὸς ἐν Σαμαρείᾳ καὶ κατέσχεν αὐτὴν ἔτεσιν ἑπτὰ καὶ δέκα τοῦ μὲν πατρὸς οὐδʼ αὐτὸς μιμητὴς γενόμενος, ἀσεβήσας δʼ ὅσα καὶ οἱ πρῶτοι τοῦ θεοῦ καταφρονήσαντες."},{"number":174,"text":"ἐταπείνωσε δʼ αὐτὸν καὶ συνέστειλεν ἐκ τῆς τοσαύτης δυνάμεως ὁ τῶν Σύρων βασιλεὺς εἰς ὁπλίτας μυρίους καὶ πεντήκοντα ἱππεῖς στρατεύσας ἐπʼ αὐτὸν καὶ πόλεις τε μεγάλας καὶ πολλὰς αὐτοῦ ἀφελόμενος καὶ τὴν στρατιὰν αὐτοῦ διαφθείρας."},{"number":175,"text":"ταῦτα δʼ ἔπαθεν ὁ τῶν Ἰσραηλιτῶν λαὸς κατὰ τὴν Ἐλισσαίου προφητείαν, ὅτε Ἀζάηλον βασιλεύσειν προεῖπε τῶν Σύρων καὶ Δαμασκηνῶν ἀποκτείναντα τὸν δεσπότην. ὢν δὲ ἐν οὕτως ἀπόροις κακοῖς Ἰώαζος ἐπὶ δέησιν καὶ ἱκετείαν τοῦ θεοῦ κατέφυγε ῥύσασθαι τῶν Ἀζαήλου χειρῶν αὐτὸν παρακαλῶν καὶ μὴ περιϊδεῖν ὑπʼ ἐκείνῳ γενόμενον."},{"number":176,"text":"ὁ δὲ θεὸς καὶ τὴν μετάνοιαν ὡς ἀρετὴν ἀποδεχόμενος καὶ νουθετεῖν μᾶλλον τοὺς δυναμένους τελέως μὴ ἀπολλύειν δοκοῦν αὐτῷ, δίδωσιν αὐτῷ τὴν ἐκ τοῦ πολέμου καὶ τῶν κινδύνων ἄδειαν. εἰρήνης δʼ ἡ χώρα λαβομένη ἀνέδραμέ τε πάλιν εἰς τὴν προτέραν κατάστασιν καὶ εὐθήνησε."},{"number":177,"text":"Μετὰ δὲ τὴν Ἰωάζου τελευτὴν ἐκδέχεται τὴν ἀρχὴν ὁ υἱὸς αὐτοῦ Ἰώασος. ἕβδομον ἤδη καὶ τριακοστὸν ἔτος βασιλεύοντος Ἰωάσου τῆς Ἰούδα φυλῆς παρέλαβε τὴν ἀρχὴν οὗτος ὁ Ἰώασος ἐν Σαμαρείᾳ τῶν Ἰσραηλιτῶν· καὶ γὰρ αὐτὸς τὴν αὐτὴν εἶχε προσηγορίαν τῷ τῶν Ἱεροσολυμιτῶν βασιλεῖ· καὶ κατέσχεν αὐτὴν ἔτεσιν ἑκκαίδεκα."},{"number":178,"text":"ἀγαθὸς δʼ ἦν καὶ οὐδὲν ὅμοιος τῷ πατρὶ τὴν φύσιν. κατʼ ἐκεῖνον δὲ τὸν καιρὸν Ἐλισσαίου τοῦ προφήτου γηραιοῦ μὲν ἤδη τυγχάνοντος εἰς δὲ νόσον ἐμπεπτωκότος ἧκεν ὁ τῶν Ἰσραηλιτῶν βασιλεὺς πρὸς αὐτὸν ἐπισκεψόμενος."},{"number":179,"text":"καταλαβὼν δὲ αὐτὸν ἐν ἐσχάτοις ὄντα κλαίειν ἤρξατο βλέποντος αὐτοῦ καὶ ποτνιᾶσθαι καὶ πατέρα τε ἀποκαλεῖν καὶ ὅπλον· διʼ αὐτὸν γὰρ μηδέποτε χρήσασθαι πρὸς τοὺς ἐχθροὺς ὅπλοις, ἀλλὰ ταῖς ἐκείνου προφητείαις ἀμαχητὶ κρατεῖν τῶν πολεμίων· νῦν δʼ ἀπιέναι μὲν αὐτὸν ἐκ τοῦ ζῆν, καταλείπειν δʼ ἐξωπλισμένον τοῖς Σύροις καὶ τοῖς ἀπʼ αὐτῶν πολεμίοις."},{"number":180,"text":"οὐδʼ αὐτῷ τοίνυν ζῆν ἔτι ἀσφαλὲς ἔλεγεν, ἀλλὰ καλῶς ἔχειν συνεξορμᾶν αὐτῷ καὶ συναπαίρειν ἐκ τοῦ βίου. ταῦτʼ ὀδυρόμενον Ἐλισσαῖος παρεμυθεῖτο τὸν βασιλέα καὶ τόξον ἐκέλευσεν αὐτῷ κομισθὲν ἐντεῖναι τοῦτο. ποιήσαντος οὖν εὐτρεπὲς τοῦ βασιλέως τὸ τόξον, ἐπιλαβόμενον τῶν χειρῶν αὐτοῦ ἐκέλευσεν αὐτὸν τοξεύειν. τρία βέλη δʼ αὐτοῦ προεμένου εἶτα δʼ ἀναπαυσαμένου πλείω μέν"},{"number":181,"text":", εἶπεν, ἀφεὶς ἐκ ῥιζῶν ἂν τὴν τῶν Σύρων βασιλείαν ἐξεῖλες, ἐπεὶ δὲ τρισὶν ἠρκέσθης μόνοις, τοσαύταις καὶ μάχαις κρατήσεις συμβαλὼν τοῖς Σύροις, ἵνα τὴν χώραν ἣν ἀπετέμοντο τοῦ σοῦ πατρὸς ἀνακτήσῃ· καὶ ὁ μὲν βασιλεὺς τοῦτʼ ἀκούσας ἀπηλλάγη."},{"number":182,"text":"μετʼ οὐ πολὺ δὲ καὶ ὁ προφήτης ἀπέθανεν ἀνὴρ ἐπὶ δικαιοσύνῃ διαβόητος καὶ φανερῶς σπουδασθεὶς ὑπὸ τοῦ θεοῦ· θαυμαστὰ γὰρ καὶ παράδοξα διὰ τῆς προφητείας ἐπεδείξατο ἔργα καὶ μνήμης λαμπρᾶς παρὰ τοῖς Ἑβραίοις ἀξιωθέντα. ἔτυχε δὲ καὶ ταφῆς μεγαλοπρεποῦς καὶ οἵας εἰκὸς ἦν τὸν οὕτω θεοφιλῆ μεταλαβεῖν."},{"number":183,"text":"συνέβη δὲ καὶ τότε, λῃστῶν τινων ῥιψάντων εἰς τὸν Ἐλισσαίου τάφον ὃν ἦσαν ἀνῃρηκότες, τὸν νεκρὸν τῷ σώματι αὐτοῦ προσκολληθέντα ἀναζωπυρῆσαι. καὶ τὰ μὲν περὶ Ἐλισσαίου τοῦ προφήτου, ζῶν τε ὅσα προεῖπε καὶ ὡς μετὰ τὴν τελευτὴν ἔτι δύναμιν εἶχε θείαν, ἤδη δεδηλώκαμεν."},{"number":184,"text":"Τελευτήσαντος δὲ τοῦ Σύρων βασιλέως Ἀζαήλου εἰς Ἀδδὰν τὸν υἱὸν αὐτοῦ ἡ βασιλεία παραγίνεται· πρὸς τοῦτον συνάπτει πόλεμον Ἰώασος ὁ τῶν Ἰσραηλιτῶν βασιλεὺς καὶ τρισὶ μάχαις νικήσας αὐτὸν ἀφείλετο τὴν χώραν ἅπασαν καὶ ὅσας ὁ πατὴρ αὐτοῦ Ἀζάηλος πόλεις καὶ κώμας τῆς Ἰσραηλιτῶν βασιλείας παρέλαβε."},{"number":185,"text":"τοῦτο μέντοι κατὰ τὴν Ἐλισσαίου προφητείαν ἐγένετο. ἐπεὶ δὲ συνέβη καὶ Ἰώασον ἀποθανεῖν, ὁ μὲν ἐν Σαμαρείᾳ κηδεύεται, καθῆκε δὲ εἰς Ἰώασον ἡ ἀρχὴ τὸν υἱὸν αὐτοῦ."}],"9":[{"number":186,"text":"Δευτέρῳ δʼ ἔτει τῆς Ἰωάσου βασιλείας τῶν Ἰσραηλιτῶν ἐβασίλευσεν Ἀμασίας τῆς Ἰούδα φυλῆς ἐν Ἱεροσολύμοις μητρὸς ὢν Ἰωάδη τοὔνομα πολίτιδος δὲ τὸ γένος· θαυμαστῶς δὲ τοῦ δικαίου προυνόει καὶ ταῦτα νέος ὤν. παρελθὼν δʼ ἐπὶ τὰ πράγματα καὶ τὴν ἀρχὴν ἔγνω δεῖν πρῶτον Ἰωάσῳ τιμωρῆσαι τῷ πατρὶ καὶ τοὺς ἐπιθεμένους αὐτῷ φίλους κολάσαι."},{"number":187,"text":"καὶ τούτους μὲν συλλαβὼν ἅπαντας ἐφόνευσε, τοὺς δὲ παῖδας αὐτῶν οὐδὲν εἰργάσατο δεινὸν ἀκόλουθα ποιῶν τοῖς Μωσήους νόμοις, ὃς οὐκ ἐδικαίωσε διὰ πατέρων ἁμαρτίας τέκνα κολάζειν."},{"number":188,"text":"ἔπειτα στρατιὰν ἐπιλέξας ἐκ τῆς Ἰούδα φυλῆς καὶ Βενιαμίδος τῶν ἐν ἀκμῇ καὶ περὶ εἴκοσι ἔτη γεγονότων καὶ συναθροίσας ὡς τριάκοντα μυριάδας τούτων μὲν ἑκατοντάρχους κατέστησε, πέμψας δὲ καὶ πρὸς τὸν Ἰσραηλιτῶν βασιλέα μισθοῦται δέκα μυριάδας ὁπλιτῶν ἑκατὸν ἀργυρίου ταλάντων· διεγνώκει γὰρ τοῖς Ἀμαληκιτῶν ἔθνεσι καὶ Ἰδουμαίων καὶ Γαβαλιτῶν ἐπιστρατεύσασθαι."},{"number":189,"text":"παρασκευασαμένου δὲ πρὸς τὴν στρατείαν καὶ μέλλοντος ἐξορμᾶν ὁ προφήτης τὸν τῶν Ἰσραηλιτῶν στρατὸν ἀπολῦσαι συνεβούλευσεν· εἶναι γὰρ ἀσεβῆ καὶ τὸν θεὸν ἧτταν αὐτῷ προλέγειν χρησαμένῳ τούτοις συμμάχοις· περιέσεσθαι δὲ τῶν πολεμίων καὶ μετʼ ὀλίγων αὐτοῖς ἀγωνιζόμενον βουλομένου τοῦ θεοῦ."},{"number":190,"text":"δυσφοροῦντος δὲ τοῦ βασιλέως ἐπὶ τῷ φθῆναι τὸν μισθὸν δεδωκέναι τοῖς Ἰσραηλίταις παρῄνει ποιεῖν ὁ προφήτης ὅ τι τῷ θεῷ δοκεῖ, χρήματα δʼ αὐτῷ πολλὰ παρʼ αὐτοῦ γενήσεσθαι. καὶ τοὺς μὲν ἀπολύει χαρίζεσθαι τὸν μισθὸν εἰπών, αὐτὸς δὲ μετὰ τῆς οἰκείας δυνάμεως ἐπὶ τὰ προειρημένα τῶν ἐθνῶν ἐστράτευσε·"},{"number":191,"text":"καὶ κρατήσας αὐτῶν τῇ μάχῃ μυρίους μὲν ἀπέκτεινε, τοσούτους δὲ ζῶντας ἔλαβεν, οὓς ἐπὶ τὴν μεγάλην ἀγαγὼν πέτραν, ἥπερ ἐστὶ κατὰ τὴν Ἀραβίαν, ἀπʼ αὐτῆς κατεκρήμνισεν, ἀπήγαγέ τε λείαν πολλὴν καὶ πλοῦτον ἄφθονον ἐκ τῶν ἐθνῶν."},{"number":192,"text":"Ἀμασίου δʼ ἐν τούτοις ὑπάρχοντος οἱ τῶν Ἰσραηλιτῶν οὓς ἀπέλυσε μισθωσάμενος ἀγανακτήσαντες ἐπὶ τούτῳ καὶ νομίσαντες ὕβριν εἶναι τὴν ἀπόλυσιν, οὐ γὰρ ἂν τοῦτο παθεῖν μὴ κατεγνωσμένους, ἐπῆλθον αὐτοῦ τῇ βασιλείᾳ καὶ μέχρι Βηθσεμήρων προελθόντες διήρπασαν τὴν χώραν καὶ πολλὰ μὲν ἔλαβον ὑποζύγια, τρισχιλίους δὲ ἀνθρώπους ἀπέκτειναν."},{"number":193,"text":"Ἀμασίας δὲ τῇ νίκῃ καὶ τοῖς κατορθώμασιν ἐπαρθεὶς τὸν μὲν τούτων αἴτιον θεὸν αὐτῷ γενόμενον ὑπερορᾶν ἤρξατο, οὓς δʼ ἐκ τῆς Ἀμαληκιτῶν χώρας ἐκόμισεν, τούτους σεβόμενος διετέλει."},{"number":194,"text":"προσελθὼν δὲ ὁ προφήτης αὐτῷ θαυμάζειν ἔλεγεν, εἰ τούτους ἡγεῖται θεούς, οἳ τοὺς ἰδίους παρʼ οἷς ἐτιμῶντο μηδὲν ὤνησαν μηδʼ ἐκ χειρῶν ἐρρύσαντο τῶν ἐκείνου, ἀλλʼ ὑπερεῖδον πολλούς τε αὐτῶν ἀπολλυμένους καὶ αὑτοὺς αἰχμαλωτισθέντας· κεκομίσθαι γὰρ εἰς Ἱεροσόλυμα τούτῳ τῷ τρόπῳ, καθὼς ἄν τις τῶν πολεμίων τινὰ ζωγρήσας ἤγαγεν."},{"number":195,"text":"τῷ δὲ βασιλεῖ ταῦτʼ ὀργὴν ἐκίνησε καὶ προσέταξεν ἡσυχίαν ἄγειν τὸν προφήτην ἀπειλήσας αὐτὸν κολάσειν, ἂν πολυπραγμονῇ. καὶ ὁ μὲν ἡσυχάζειν εἶπεν, οὐκ ἀμελήσειν δὲ ὧν ἐπικεχείρηκε νεωτερίζων τὸν θεὸν προύλεγεν."},{"number":196,"text":"Ἀμασίας δὲ κατέχειν ἑαυτὸν ἐπὶ ταῖς εὐπραγίαις οὐ δυνάμενος, ἃς παρὰ τοῦ θεοῦ λαβὼν εἰς αὐτὸν ἐξύβριζεν, ἀλλὰ φρονηματισθεὶς ἔγραψεν Ἰωάσῳ τῷ τῶν Ἰσραηλιτῶν βασιλεῖ κελεύων ὑπακούειν αὐτῷ σὺν ἅπαντι τῷ λαῷ, ὡς καὶ πρότερον ὑπήκουσε τοῖς προγόνοις αὐτοῦ Δαυίδῃ καὶ Σολόμωνι, ἢ μὴ βουλόμενον εὐγνωμονεῖν εἰδέναι πολέμῳ περὶ τῆς ἀρχῆς διακριθησόμενον."},{"number":197,"text":"ἀντέγραψε δʼ ὁ Ἰώασος τάδε· βασιλεὺς Ἰώασος βασιλεῖ Ἀμασίᾳ. ἦν ἐν τῷ Λιβάνῳ ὄρει κυπάρισσος παμμεγέθης καὶ ἄκανος. αὕτη πρὸς τὴν κυπάρισσον ἔπεμψε μνηστευομένη τὴν θυγατέρα αὐτῆς πρὸς γάμον τῷ παιδί. μεταξὺ ταῦτα λέγουσαν θηρίον τι παρερχόμενον κατεπάτησε τὴν ἄκανον."},{"number":198,"text":"τοῦτο οὖν ἔσται σοι παράδειγμα τοῦ μὴ μειζόνων ἐφίεσθαι, μηδʼ ὅτι τὴν πρὸς Ἀμαληκίτας μάχην εὐτύχησας ἐπὶ ταύτῃ γαυρούμενος σαυτῷ καὶ τῇ βασιλείᾳ σου κινδύνους ἐπισπῶ."},{"number":199,"text":"Ταῦτα δὲ ἀναγνοὺς Ἀμασίας ἔτι μᾶλλον ἐπὶ τὴν στρατείαν παρωξύνθη τοῦ θεοῦ παρορμῶντος αὐτὸν οἶμαι πρὸς αὐτήν, ἵνα τῶν παρανομηθέντων εἰς αὐτὸν δίκην ἀπολάβῃ. ὡς δʼ ἐξήγαγε μετὰ τῆς δυνάμεως ἐπὶ τὸν Ἰώασον καὶ συνάπτειν μάχην ἔμελλον, τὸ Ἀμασίου στράτευμα φόβος αἰφνίδιος καὶ κατάπληξις οἵαν θεὸς οὐκ εὐμενὴς ἐντίθησιν εἰς φυγὴν ἔτρεψε,"},{"number":200,"text":"καὶ πρὶν εἰς χεῖρας ἐλθεῖν διασπαρέντων ὑπὸ τοῦ δέους αὐτῶν μονωθέντα τὸν Ἀμασίαν ληφθῆναι συνέβη πρὸς τῶν πολεμίων αἰχμάλωτον· ἠπείλησε δʼ αὐτῷ θάνατον Ἰώασος, εἰ μὴ πείσειε τοὺς Ἱεροσολυμίτας ἀνοίξαντας αὐτῷ τὰς πύλας δέξασθαι μετὰ τῆς στρατιᾶς εἰς τὴν πόλιν."},{"number":201,"text":"καὶ Ἀμασίας μὲν ὑπὸ ἀνάγκης καὶ τοῦ περὶ τὸ ζῆν δέους ἐποίησεν εἰσδεχθῆναι τὸν πολέμιον· ὁ δὲ διακόψας τι τοῦ τείχους ὡς τετρακοσίων πηχῶν ἐφʼ ἅρματος εἰσήλασε διὰ τῆς διακοπῆς εἰς Ἱεροσόλυμα τὸν Ἀμασίαν ἄγων αἰχμάλωτον."},{"number":202,"text":"κύριος δὲ τούτῳ τῷ τρόπῳ γενόμενος τῶν Ἱεροσολυμιτῶν τούς τε τοῦ θεοῦ θησαυροὺς ἀνείλετο καὶ ὅσος ἦν τῷ Ἀμασίᾳ χρυσὸς καὶ ἄργυρος ἐν τοῖς βασιλείοις ἐξεφόρησε, καὶ οὕτως αὐτὸν ἀπολύσας τῆς αἰχμαλωσίας ἀνέζευξεν εἰς Σαμάρειαν."},{"number":203,"text":"ταῦτα δʼ ἐγένετο περὶ τοὺς Ἱεροσολυμίτας ἔτει τετάρτῳ καὶ δεκάτῳ τῆς Ἀμασία βασιλείας, ὃς μετὰ ταῦτα ἐπιβουλευθεὶς ὑπὸ τῶν φίλων φεύγει μὲν εἰς Λάχισαν πόλιν, ἀναιρεῖται δὲ ὑπὸ τῶν ἐπιβούλων πεμψάντων ἐκεῖ τοὺς ἀποκτενοῦντας αὐτόν. καὶ τὸ μὲν σῶμα κομίσαντες εἰς Ἱεροσόλυμα βασιλικῶς ἐκήδευσαν·"},{"number":204,"text":"κατέστρεψε δὲ οὕτως Ἀμασίας τὸν βίον καὶ διὰ τὸν νεωτερισμὸν τῆς πρὸς τὸν θεὸν ὀλιγωρίας, βιώσας μὲν ἔτη τέσσαρα καὶ πεντήκοντα βασιλεύσας δὲ ἐννέα καὶ εἴκοσι. διαδέχεται δʼ αὐτὸν ὁ παῖς Ὀζίας τοὔνομα."}],"10":[{"number":205,"text":"Πεντεκαιδεκάτῳ ἔτει τῆς Ἀμασία βασιλείας ἐβασίλευσε τῶν Ἰσραηλιτῶν ὁ Ἰωάσου υἱὸς Ἱερόβαμος ἐν Σαμαρείᾳ ἔτη τεσσαράκοντα. οὗτος ὁ βασιλεὺς τὰ μὲν εἰς τὸν θεὸν ὑβριστὴς καὶ παράνομος δεινῶς ἐγένετο εἴδωλά τε σεβόμενος καὶ πολλοῖς ἀτόποις καὶ ξένοις ἐγχειρῶν ἔργοις, τῷ δὲ λαῷ τῶν Ἰσραηλιτῶν μυρίων ἀγαθῶν αἴτιος ὑπῆρχε."},{"number":206,"text":"τούτῳ προεφήτευσέ τις Ἰωνᾶς, ὡς δεῖ πολεμήσαντα τοῖς Σύροις αὐτὸν κρατῆσαι τῆς ἐκείνων δυνάμεως καὶ πλατῦναι τὴν αὑτοῦ βασιλείαν τοῖς μὲν κατὰ τὴν ἄρκτον μέρεσιν ἕως Ἀμάθου πόλεως, τοῖς δὲ κατὰ τὴν μεσημβρίαν ἕως τῆς Ἀσφαλτίδος λίμνης·"},{"number":207,"text":"τὸ γὰρ ἀρχαῖον οἱ ὅροι τῆς Χαναναίας ἦσαν οὗτοι, καθὼς ὁ στρατηγὸς Ἰησοῦς περιώρισε. στρατεύσας οὖν ἐπὶ τοὺς Σύρους ὁ Ἱερόβαμος καταστρέφεται πᾶσαν αὐτῶν τὴν χώραν, ὡς προεφήτευσεν Ἰωνᾶς."},{"number":208,"text":"Ἀναγκαῖον δὲ ἡγησάμην τὴν ἀκρίβειαν τῶν πραγμάτων παραδώσειν ὑπεσχημένος ὅσα καὶ περὶ τούτου τοῦ προφήτου εὗρον ἐν ταῖς Ἑβραϊκαῖς βίβλοις ἀναγεγραμμένα διεξελθεῖν· κελευσθεὶς γὰρ οὗτος ὑπὸ τοῦ θεοῦ πορευθῆναι μὲν εἰς τὴν Νινύου βασιλείαν κηρῦξαι δʼ ἐκεῖ γενόμενον ἐν τῇ πόλει ὅτι τὴν ἀρχὴν ἀπολέσει, δείσας οὐκ ἀπῆλθεν, ἀλλʼ ἀποδιδράσκει τὸν θεὸν εἰς Ἰόπην πόλιν καὶ πλοῖον εὑρὼν ἐμβὰς εἰς Ταρσὸν ἔπλει τῆς Κιλικίας."},{"number":209,"text":"ἐπιγενομένου δὲ χειμῶνος σφοδροτάτου καὶ κινδυνεύοντος καταδῦναι τοῦ σκάφους οἱ μὲν ναῦται καὶ οἱ κυβερνῆται καὶ αὐτὸς ὁ ναύκληρος εὐχὰς ἐποιοῦντο χαριστηρίους, εἰ διαφύγοιεν τὴν θάλασσαν, ὁ δὲ Ἰωνᾶς συγκαλύψας αὑτὸν ἐβέβλητο μηδὲν ὧν τοὺς ἄλλους ἑώρα ποιοῦντας μιμούμενος."},{"number":210,"text":"αὔξοντος δʼ ἔτι μᾶλλον τοῦ κλύδωνος καὶ βιαιοτέρας γενομένης ὑπὸ τῶν πνευμάτων τῆς θαλάσσης ὑπονοήσαντες, ὡς ἐνδέχεταί τινα τῶν ἐμπλεόντων αἴτιον αὐτοῖς εἶναι τοῦ χειμῶνος, συνέθεντο κλήρῳ τοῦτον ὅστις ποτὲ ἦν μαθεῖν."},{"number":211,"text":"κληρωσαμένων οὖν ὁ προφήτης λαγχάνει πυνθανομένων τε πόθεν τε εἴη καὶ τί μετέρχεται τὸ μὲν γένος ἔλεγεν Ἑβραῖος εἶναι προφήτης τοῦ μεγίστου θεοῦ· συνεβούλευσεν οὖν αὐτοῖς, εἰ θέλουσιν ἀποδράναι τὸν παρόντα κίνδυνον, ἐκβαλεῖν αὐτὸν εἰς τὸ πέλαγος· αἴτιον γὰρ αὐτοῖς εἶναι τοῦ χειμῶνος."},{"number":212,"text":"οἱ δὲ τὸ μὲν πρῶτον οὐκ ἐτόλμων κρίναντες ἀσέβημα ξένον ἄνθρωπον καὶ πεπιστευκότα αὐτοῖς τὸ ζῆν εἰς φανερὰν αὐτοὺς ἀπώλειαν ἐκρῖψαι, τελευταῖον δʼ ὑπερβιαζομένου τοῦ κακοῦ καὶ ὅσον οὔπω μέλλοντος βαπτίζεσθαι τοῦ σκάφους, ὑπό τε τοῦ προφήτου παρορμηθέντες αὐτοῦ καὶ ὑπὸ τοῦ δέους τοῦ περὶ τῆς αὑτῶν σωτηρίας ῥίπτουσιν αὐτὸν εἰς τὴν θάλασσαν."},{"number":213,"text":"καὶ ὁ μὲν χειμὼν ἐστάλη, τὸν δὲ λόγος ὑπὸ τοῦ κήτους καταποθέντα τρεῖς ἡμέρας καὶ τοσαύτας νύκτας εἰς τὸν Εὔξεινον ἐκβρασθῆναι πόντον ζῶντα καὶ μηδὲν τοῦ σώματος λελωβημένον."},{"number":214,"text":"ἔνθα τοῦ θεοῦ δεηθεὶς συγγνώμην αὐτῷ παρασχεῖν τῶν ἡμαρτημένων ἀπῆλθεν εἰς τὴν Νίνου πόλιν καὶ σταθεὶς εἰς ἐπήκοον ἐκήρυσσεν, ὡς μετʼ ὀλίγον πάλιν ἀποβαλοῦσι τὴν ἀρχὴν τῆς Ἀσίας, καὶ ταῦτα δηλώσας ὑπέστρεψε. διεξῆλθον δὲ τὴν περὶ αὐτοῦ διήγησιν, ὡς εὗρον ἀναγεγραμμένην."},{"number":215,"text":"Ἱερόβαμος δʼ ὁ βασιλεὺς μετὰ πάσης εὐδαιμονίας τὸν βίον διαγαγὼν καὶ ἄρξας ἔτη τεσσαράκοντα ἐτελεύτησε καὶ θάπτεται μὲν ἐν Σαμαρείᾳ, διαδέχεται δὲ αὐτοῦ τὴν βασιλείαν υἱὸς Ζαχαρίας. τὸν αὐτὸν δὲ τρόπον καὶ Ὀζίας ὁ τοῦ Ἀμασία υἱός,"},{"number":216,"text":"ἔτος ἤδη τέταρτον πρὸς τοῖς δέκα βασιλεύοντος Ἱεροβοάμου, τῶν δύο φυλῶν ἐβασίλευσεν ἐν Ἱεροσολύμοις μητρὸς ὢν Ἀχίας μὲν τοὔνομα ἀστῆς δὲ τὸ γένος. ἀγαθὸς δὲ ἦν καὶ δίκαιος τὴν φύσιν καὶ μεγαλόφρων καὶ προνοῆσαι τῶν πραγμάτων φιλοπονώτατος."},{"number":217,"text":"στρατευσάμενος δὲ καὶ ἐπὶ Παλαιστίνους καὶ νικήσας μάχῃ πόλεις αὐτῶν ἔλαβε κατὰ κράτος Γίτταν καὶ Ἰάμνειαν καὶ κατέσκαψεν αὐτῶν τὰ τείχη. μετὰ δὲ ταύτην τὴν στρατείαν ἐπῆλθε τοῖς τῇ Αἰγύπτῳ γειτνιῶσιν Ἄραψι καὶ πόλιν κτίσας ἐπὶ τῆς Ἐρυθρᾶς θαλάσσης ἐγκατέστησεν αὐτῇ φρουράν."},{"number":218,"text":"ἔπειτα τοὺς Ἀμμανίτας καταστρεψάμενος καὶ φόρους αὐτοῖς ὁρίσας τελεῖν καὶ πάντα τὰ μέχρι τῶν Αἰγυπτίων ὅρων χειρωσάμενος τῶν Ἱεροσολύμων ἤρχετο ποιεῖσθαι τὸ λοιπὸν τὴν ἐπιμέλειαν· ὅσα γὰρ τῶν τειχῶν ἢ ὑπὸ τοῦ χρόνου καταβέβλητο ἢ ὑπὸ τῆς ὀλιγωρίας τῶν πρὸ αὐτοῦ βασιλέων, ταῦτά τε ἀνῳκοδόμει καὶ κατεσκεύαζεν, ὅσα τε ἦν καταβεβλημένα ὑπὸ τοῦ τῶν Ἰσραηλιτῶν βασιλέως, ὅτε τὸν πατέρα αὐτοῦ λαβὼν αἰχμάλωτον τὸν Ἀμασίαν εἰσῆλθεν εἰς τὴν πόλιν."},{"number":219,"text":"προσῳκοδόμησε δὲ καὶ πύργους πολλοὺς πεντήκοντα πηχῶν ἕκαστον. καὶ φρουροὺς δὲ ἐνετείχισε τοῖς ἐρήμοις χωρίοις καὶ πολλοὺς ὀχετοὺς ὤρυξεν ὑδάτων. ἦν δʼ αὐτῷ καὶ ὑποζυγίων καὶ τῶν ἄλλων θρεμμάτων ἄπειρόν τι πλῆθος· εὐφυὴς γὰρ ἦν ἡ χώρα πρὸς νομάς."},{"number":220,"text":"γεωργικὸς δὲ ὢν σφόδρα τῆς γῆς ἐπεμελεῖτο φυτοῖς αὐτὴν καὶ παντοδαποῖς τιθηνῶν σπέρμασι. στρατιᾶς δʼ εἶχεν ἐπιλέκτου περὶ αὑτὸν μυριάδας ἑπτὰ καὶ τριάκοντα, ἧς ἡγεμόνες ἦσαν καὶ ταξίαρχοι καὶ χιλίαρχοι γενναῖοι καὶ τὴν ἀλκὴν ἀνυπόστατοι τὸν ἀριθμὸν δισχίλιοι."},{"number":221,"text":"διέταξε δʼ εἰς φάλαγγας τὴν ὅλην στρατιὰν καὶ ὥπλισε ῥομφαίαν δοὺς ἑκάστῳ καὶ θυρεοὺς καὶ θώρακας χαλκέους καὶ τόξα καὶ σφενδόνας. ἔτι δὲ πρὸς τούτοις μηχανήματα πολλὰ πρὸς πολιορκίας κατεσκεύασε πετρόβολά τε καὶ δορύβολα καὶ ἅρπαγας καὶ ἀρτῆρας καὶ ὅσα τούτοις ὅμοια."},{"number":222,"text":"Γενόμενος δʼ ἐν ταύτῃ τῇ συντάξει καὶ παρασκευῇ διεφθάρη τὴν διάνοιαν ὑπὸ τύφου καὶ χαυνωθεὶς θνητῇ περιουσίᾳ τῆς ἀθανάτου καὶ πρὸς ἅπαντα διαρκοῦς τὸν χρόνον ἰσχύος ὠλιγώρησεν· αὕτη δὲ ἦν ἡ πρὸς τὸν θεὸν εὐσέβεια καὶ τὸ τηρεῖν τὰ νόμιμα."},{"number":223,"text":"ὤλισθε δὲ ὑπʼ εὐπραξίας καὶ κατηνέχθη πρὸς τὰ τοῦ πατρὸς ἁμαρτήματα, πρὸς ἃ κἀκεῖνον ἡ τῶν ἀγαθῶν λαμπρότης καὶ τὸ μέγεθος τῶν πραγμάτων οὐ δυνηθέντα προστῆναι καλῶς αὐτῶν ἤγαγεν. ἐνστάσης δʼ ἡμέρας ἐπισήμου καὶ πάνδημον ἑορτὴν ἐχούσης ἐνδὺς ἱερατικὴν στολὴν εἰσῆλθεν εἰς τὸ τέμενος θυσιάσων ἐπὶ τοῦ χρυσοῦ βωμοῦ τῷ θεῷ."},{"number":224,"text":"τοῦ δʼ ἀρχιερέως Ἀζαρία ὄντων σὺν αὐτῷ ἱερέων ὀγδοήκοντα κωλύοντος αὐτόν, οὐ γὰρ ἐξὸν ἐπιθύειν εἶπον, μόνοις δʼ ἐφεῖσθαι τοῦτο ποιεῖν τοῖς ἐκ τοῦ Ἀαρῶνος γένους, καταβοώντων δʼ ἐξιέναι καὶ μὴ παρανομεῖν εἰς τὸν θεόν, ὀργισθεὶς ἠπείλησεν αὐτοῖς θάνατον, εἰ μὴ τὴν ἡσυχίαν ἄξουσι."},{"number":225,"text":"μεταξὺ δὲ σεισμὸς ἐκλόνησε τὴν γῆν μέγας καὶ διαστάντος τοῦ ναοῦ φέγγος ἡλίου λαμπρὸν ἐξέλαμψε καὶ τῇ τοῦ βασιλέως ὄψει προσέπεσεν, ὡς τῷ μὲν εὐθέως λέπραν ἐπιδραμεῖν, πρὸ δὲ τῆς πόλεως πρὸς τῇ καλουμένῃ Ἐρωγῇ τοῦ ὄρους ἀπορραγῆναι τὸ ἥμισυ τοῦ κατὰ τὴν δύσιν καὶ κυλισθὲν τέσσαρας σταδίους ἐπὶ τὸ ἀνατολικὸν ὄρος στῆναι, ὡς τάς τε παρόδους ἐμφραγῆναι καὶ τοὺς παραδείσους τοὺς βασιλικούς."},{"number":226,"text":"ἐπεὶ δὲ κατειλημμένην τὴν ὄψιν τοῦ βασιλέως ὑπὸ τῆς λέπρας εἶδον οἱ ἱερεῖς, ἔφραζόν τε αὐτῷ τὴν συμφορὰν καὶ ἐκέλευον ἐξιέναι τῆς πόλεως ὡς ἐναγῆ. ὁ δʼ ὑπʼ αἰσχύνης τε τοῦ συμβεβηκότος δεινοῦ καὶ τοῦ μηκέτʼ αὐτῷ παρρησίαν εἶναι τὸ κελευόμενον ἐποίει, τῆς ὑπὲρ ἄνθρωπον διανοίας καὶ τῶν διὰ τοῦτο εἰς τὸν θεὸν ἀσεβημάτων ταλαίπωρον οὕτως καὶ οἰκτρὰν ὑπομείνας δίκην."},{"number":227,"text":"καὶ χρόνον μέν τινα διῆγεν ἔξω τῆς πόλεως ἰδιώτην ἀποζῶν βίον τοῦ παιδὸς αὐτῷ Ἰωθάμου τὴν ἀρχὴν παραλαβόντος, ἔπειτα ὑπὸ λύπης καὶ ἀθυμίας τῆς ἐπὶ τοῖς γεγενημένοις ἀπέθανεν, ἔτη μὲν βιώσας ὀκτὼ καὶ ἑξήκοντα, τούτων δὲ βασιλεύσας πεντηκονταδύο. ἐκηδεύθη δὲ μόνος ἐν τοῖς ἑαυτοῦ κήποις."}],"11":[{"number":228,"text":"Ὁ δὲ τοῦ Ἱεροβάμου παῖς Ζαχαρίας ἓξ μῆνας βασιλεύσας τῶν Ἰσραηλιτῶν δολοφονηθεὶς ἀπέθανεν ὑπὸ φίλου τινὸς Σελλήμου μὲν τοὔνομα Ἰαβήσου δὲ υἱοῦ, ὃς καὶ τὴν βασιλείαν μετʼ αὐτὸν παραλαβὼν οὐ πλείονα χρόνον ἡμερῶν αὐτὴν κατέσχε τριάκοντα."},{"number":229,"text":"ὁ γὰρ στρατηγὸς Μαναῆμος κατʼ ἐκεῖνον τὸν καιρὸν ὢν ἐν Θάρσῃ πόλει καὶ τὰ περὶ τὸν Ζαχαρίαν ἀκούσας ἄρας μετὰ πάσης τῆς στρατιᾶς ἧκεν εἰς τὴν Σαμάρειαν, καὶ συμβαλὼν εἰς μάχην ἀναιρεῖ τὸν Σέλλημον καὶ βασιλέα καταστήσας ἑαυτὸν ἐκεῖθεν εἰς Θαψὰν παραγίνεται πόλιν."},{"number":230,"text":"οἱ δʼ ἐν αὐτῇ τὰς πύλας μοχλῷ κλείσαντες οὐκ εἰσεδέξαντο τὸν βασιλέα. ὁ δὲ ἀμυνόμενος αὐτοὺς τὴν πέριξ ἐδῄου χώραν καὶ τὴν πόλιν κατὰ κράτος λαμβάνει πολιορκίᾳ."},{"number":231,"text":"φέρων δὲ χαλεπῶς ἐπὶ τοῖς ὑπὸ τῶν Θαψίων πραχθεῖσι πάντας αὐτοὺς διεχρήσατο μηδὲ νηπίων φεισάμενος ὠμότητος ὑπερβολὴν οὐ καταλιπὼν οὐδὲ ἀγριότητος· ἃ γὰρ οὐδὲ τῶν ἀλλοφύλων τινὰς συγγνωστὸν διαθεῖναι γενομένους ὑποχειρίους, ταῦτα τοὺς ὁμοφύλους οὗτος εἰργάσατο."},{"number":232,"text":"βασιλεύσας οὖν τῷ τρόπῳ τούτῳ ὁ Μαναῆμος ἐπʼ ἔτη μὲν δέκα σκαιὸς καὶ πάντων ὠμότατος διέμενεν ὤν, στρατεύσαντος δʼ ἐπʼ αὐτὸν Φούλου τοῦ Ἀσσυρίων βασιλέως εἰς μὲν ἀγῶνα καὶ μάχην οὐκ ἀπαντᾷ τοῖς Ἀσσυρίοις, πείσας δὲ χίλια τάλαντα ἀργυρίου λαβόντα ἀναχωρῆσαι διαλύεται τὸν πόλεμον."},{"number":233,"text":"τὸ δὲ κεφάλαιον τοῦτο συνήνεγκε τὸ πλῆθος Μαναήμῳ πραχθὲν κατὰ κεφαλὴν δραχμὰς πεντήκοντα. τελευτήσας δὲ μετὰ ταῦτα κηδεύεται μὲν ἐν Σαμαρείᾳ, καταλείπει δὲ τῆς βασιλείας τὸν υἱὸν Φακέαν διάδοχον, ὃς τῇ τοῦ πατρὸς κατακολουθήσας ὠμότητι δυσὶν ἔτεσι μόνοις ἦρξεν."},{"number":234,"text":"ἔπειτα δολοφονηθεὶς ἐν συμποσίῳ μετὰ φίλων ἀπέθανε Φακέου τινός, ὃς ἦν χιλίαρχος, ἐπιβουλεύσαντος αὐτῷ, παιδὸς δὲ Ῥομελία. κατασχὼν δὲ καὶ οὗτος ὁ Φακέας τὴν ἀρχὴν ἔτεσιν εἴκοσιν ἀσεβής τε ἦν καὶ παράνομος."},{"number":235,"text":"ὁ δὲ τῶν Ἀσσυρίων βασιλεὺς Θαγλαθφαλλάσαρ τοὔνομα ἐπιστρατευσάμενος τοῖς Ἰσραηλίταις καὶ τήν τε Γαλαδηνὴν ἅπασαν καταστρεψάμενος καὶ τὴν πέραν τοῦ Ἰορδάνου χώραν καὶ τὴν πρὸς αὐτῇ τὴν Γαλιλαίαν καλουμένην καὶ Κύδισσα καὶ Ἄσωρα τοὺς οἰκήτορας αἰχμαλωτίσας μετέστησεν εἰς τὴν αὑτοῦ βασιλείαν. καὶ τὰ μὲν περὶ τοῦ Ἀσσυρίων βασιλέως ἐν τούτοις ἡμῖν δεδηλώσθω."},{"number":236,"text":"Ἰωσᾶς δὲ Ὀζία παῖς ἐβασίλευσε τῆς Ἰούδα φυλῆς ἐν Ἱεροσολύμοις ἐκ μητρὸς μὲν ἀστῆς γεγονὼς καλουμένης δὲ Ἰεράσης. οὗτος ὁ βασιλεὺς οὐδεμιᾶς ἀρετῆς ἀπελείπετο, ἀλλʼ εὐσεβὴς μὲν τὰ πρὸς τὸν θεόν, δίκαιος δὲ τὰ πρὸς ἀνθρώπους ὑπῆρχεν, ἐπιμελὴς δὲ τῶν κατὰ πόλιν·"},{"number":237,"text":"ὅσα γὰρ ἐπισκευῆς ἐδεῖτο καὶ κόσμου ταῦτα φιλοτίμως ἐξειργάσατο, στοὰς μὲν τὰς ἐν τῷ ναῷ ἱδρύσας καὶ προπύλαια, τὰ δὲ καταπεπτωκότα τῶν τειχῶν ἀνέστησε πύργους παμμεγέθεις καὶ δυσαλώτους οἰκοδομήσας, καὶ τῶν ἄλλων εἴ τι κατὰ τὴν βασιλείαν ἠμέλητο πολλὴν ἐπιστροφὴν ἐποιεῖτο."},{"number":238,"text":"στρατευσάμενος δὲ καὶ ἐπὶ τοὺς Ἀμμανίτας καὶ κρατήσας αὐτῶν τῇ μάχῃ προσέταξεν αὐτοῖς φόρους κατὰ πᾶν ἔτος αὐτῷ τελεῖν ἑκατὸν τάλαντα καὶ σίτου κόρους μυρίους, τοσούτους δὲ καὶ κριθῆς. ηὔξησε δʼ οὕτω τὴν βασιλείαν, ὥστε ἀκαταφρόνητον μὲν αὐτὴν ἐκ τῶν πολεμίων εἶναι, τοῖς δʼ οἰκείοις εὐδαίμονα."},{"number":239,"text":"Ἦν δέ τις κατὰ τοῦτον τὸν καιρὸν προφήτης Ναοῦμος ὄνομα, ὃς περὶ τῆς Ἀσσυρίων καταστροφῆς καὶ τῆς Νίνου προφητεύων ἔλεγεν, ὡς ἔσται Νινύας κολυμβήθρα ὕδατος κινουμένη· οὕτως καὶ ὁ δῆμος ἅπας ταρασσόμενος καὶ κλυδωνιζόμενος οἰχήσεται φεύγων λεγόντων πρὸς ἀλλήλους στῆτε καὶ μείνατε καὶ χρυσὸν αὑτοῖς καὶ ἄργυρον ἁρπάσατε. ἔσται δʼ οὐδεὶς βουλησόμενος·"},{"number":240,"text":"σώζειν γὰρ αὑτῶν ἐθελήσουσι τὰς ψυχὰς μᾶλλον ἢ τὰ κτήματα· δεινὴ γὰρ αὐτοὺς ἐν ἀλλήλοις ἔρις ἕξει καὶ θρῆνος πάρεσίς τε τῶν μελῶν, αἵ τε ὄψεις ὑπὸ τοῦ φόβου μέλαιναι τελέως αὐτοῖς γενήσονται."},{"number":241,"text":"ποῦ δὲ ἔσται τὸ κατοικητήριον τῶν λεόντων καὶ ἡ μήτηρ σκύμνων; λέγει δέ σοι ὁ θεός, Νινύα, ὅτι ἀφανιῶ σε καὶ οὐκέτι λέοντες ἐκ σοῦ πορευόμενοι ἐπιτάξουσι τῷ κόσμῳ."},{"number":242,"text":"καὶ ἄλλα δὲ πολλὰ πρὸς τούτοις ἐπροφήτευσεν οὗτος ὁ προφήτης περὶ Νινύης, ἃ λέγειν οὐκ ἀναγκαῖον ἡγησάμην, ἵνα δὲ μὴ τοῖς ἐντυγχάνουσιν ὀχληρὸς δοκῶ παρέλιπον. συνέβη δὲ πάντα τὰ προειρημένα περὶ Νινύης μετὰ ἔτη ἑκατὸν καὶ πεντεκαίδεκα. περὶ μὲν τούτων ἀποχρώντως ἡμῖν δεδήλωται."}],"12":[{"number":243,"text":"Ὁ δὲ Ἰώθαμος μετήλλαξεν ἔτη βιώσας ἓν καὶ τεσσαράκοντα βασιλεύσας δʼ ἐξ αὐτῶν ἑκκαίδεκα, θάπτεται δὲ ἐν ταῖς βασιλικαῖς θήκαις. ἔρχεται δʼ εἰς τὸν υἱὸν αὐτοῦ Ἄχαζον ἡ βασιλεία, ὃς ἀσεβέστατος εἰς τὸν θεὸν γενόμενος καὶ τοὺς πατρίους παραβὰς νόμους τοὺς Ἰσραηλιτῶν βασιλέας ἐμιμήσατο βωμοὺς ἐν Ἱεροσολύμοις ἀναστήσας καὶ θύων ἐπʼ αὐτῶν τοῖς εἰδώλοις, οἷς καὶ ἴδιον ὡλοκαύτωσε παῖδα κατὰ τὰ Χαναναίων ἔθη, καὶ τούτοις ἄλλα παραπλήσια διεπράττετο."},{"number":244,"text":"ἔχοντος δʼ οὕτως καὶ μεμηνότος ἐστράτευσεν ἐπʼ αὐτὸν ὁ τῶν Σύρων καὶ Δαμασκηνῶν βασιλεὺς Ῥαασὴς καὶ Φακέας ὁ τῶν Ἰσραηλιτῶν· φίλοι γὰρ ἦσαν· καὶ συνελάσαντες αὐτὸν εἰς τὰ Ἱεροσόλυμα ἐπὶ πολὺν ἐπολιόρκουν χρόνον διὰ τὴν τῶν τειχῶν ὀχυρότητα μηδὲν ἀνύοντες."},{"number":245,"text":"ὁ δὲ τῶν Σύρων βασιλεὺς λαβὼν τὴν πρὸς τῇ Ἐρυθρᾷ θαλάσσῃ πόλιν Ἠλαθοὺς καὶ τοὺς ἐνοικοῦντας ἀποκτείνας ἐγκατῴκισεν αὐτῇ Σύρους. τοὺς δʼ ἐντοῖς φρουρίοις ὁμοίως καὶ τοὺς πέριξ Ἰουδαίους διαφθείρας καὶ λείαν πολλὴν ἀπελάσας εἰς Δαμασκὸν μετὰ τῆς στρατιᾶς ἀνέζευξεν."},{"number":246,"text":"ὁ δὲ τῶν Ἱεροσολυμιτῶν βασιλεὺς γνοὺς τοὺς Σύρους ἐπʼ οἴκου κεχωρηκότας καὶ νομίσας ἀξιόμαχος εἶναι τῷ τῶν Ἰσραηλιτῶν βασιλεῖ τὴν δύναμιν ἐπʼ αὐτὸν ἐξήγαγε, καὶ συμβαλὼν ἐνικήθη κατὰ μῆνιν τοῦ θεοῦ, ἣν ἐπὶ τοῖς ἀσεβήμασιν αὐτοῦ πολλοῖς ἅμα καὶ μεγάλοις εἶχεν·"},{"number":247,"text":"δώδεκα γὰρ μυριάδες κατʼ ἐκείνην αὐτοῦ τὴν ἡμέραν ὑπὸ τῶν Ἰσραηλιτῶν ἀνῃρέθησαν, ὧν ὁ στρατηγὸς Ζαχάριν τὸν υἱὸν ἀπέκτεινεν ἐν τῇ συμβολῇ τοῦ βασιλέως Ἀχάζου Ἀμασίας ὄνομα, καὶ τὸν ἐπίτροπον τῆς βασιλείας ἁπάσης Ἐρκὰμ καὶ τὸν τῆς Ἰούδα φυλῆς στρατηγὸν Ἐλικὰν αἰχμάλωτον ἔλαβον, καὶ ἐκ τῆς Βενιαμίτιδος φυλῆς γυναῖκας καὶ παῖδας ἀπήγαγον, καὶ πολλὴν λείαν διαρπάσαντες ἀνεχώρησαν εἰς Σαμάρειαν."},{"number":248,"text":"Ὠδηδὰς δέ τις, ὃς κατʼ ἐκεῖνο καιροῦ προφήτης ὑπῆρχεν ἐν Σαμαρείᾳ, τῷ στρατῷ πρὸ τῶν τειχῶν ἀπαντήσας μεγάλῃ βοῇ τὴν νίκην αὐτοῖς οὐ διὰ τὴν οἰκείαν ἰσχὺν αὐτῶν ἐδήλου γενέσθαι, διὰ δὲ τὸν τοῦ θεοῦ χόλον, ὃν εἶχεν ἐπʼ Ἄχαζον τὸν βασιλέα."},{"number":249,"text":"καὶ κατεμέμφετο τῇ μὲν εὐπραγίᾳ τῇ κατʼ αὐτοῦ μὴ ἀρκεσθέντας, ἀλλὰ τολμήσαντας τοὺς ἐκ τῆς Ἰούδα φυλῆς καὶ Βενιαμίτιδος συγγενεῖς ὄντας αἰχμαλωτίσαι. συνεβούλευέ τε αὐτοῖς ἀπολῦσαι τούτους εἰς τὴν οἰκείαν ἀπαθεῖς· ἀπειθήσαντας γὰρ τῷ θεῷ δίκην ὑφέξειν."},{"number":250,"text":"ὁ δὲ τῶν Ἰσραηλιτῶν λαὸς εἰς ἐκκλησίαν συνελθὼν ἐπεσκέπτετο περὶ τούτων. ἀναστὰς δέ τις Βαραχίας ὄνομα τῶν εὐδοκιμούντων ἐν τῇ πολιτείᾳ καὶ ἄλλοι μετʼ αὐτοῦ τρεῖς ἔλεγον οὐκ ἐπιτρέψειν τοῖς ὁπλίταις εἰσαγαγεῖν εἰς τὴν πόλιν, ἵνα μὴ πάντες ἀπολώμεθα ὑπὸ τοῦ θεοῦ· μόνον γὰρ ἀπόχρη τὸ πρὸς αὐτὸν ἡμᾶς ἐξαμαρτεῖν, ὡς οἱ προφῆται λέγουσιν, ἀλλὰ μὴ καινότερα τούτων ἀσεβήματα δρᾶν."},{"number":251,"text":"ταῦτʼ ἀκούσαντες οἱ στρατιῶται συνεχώρησαν ἐκείνοις ποιεῖν ὃ ἐδόκει συμφέρειν. παραλαβόντες οὖν οἱ προειρημένοι ἄνδρες τοὺς αἰχμαλώτους ἔλυσάν τε καὶ ἐπιμελείας ἠξίωσαν καὶ δόντες ἐφόδια εἰς τὴν οἰκείαν ἀπέλυσαν ἀβλαβεῖς, οὐδὲν δʼ ἧττον καὶ τέσσαρες αὐτοῖς συνῆλθον καὶ μέχρις Ἱεριχοῦντος προπέμψαντες οὐκ ἄπωθεν τῶν Ἱεροσολύμων ἀνέστρεψαν εἰς Σαμάρειαν."},{"number":252,"text":"Ἄχαζος δʼ ὁ βασιλεὺς ταῦτα παθὼν ὑπὸ τῶν Ἰσραηλιτῶν πέμψας πρὸς τὸν τῶν Ἀσσυρίων βασιλέα Θαγλαθφαλλασάρην συμμαχίαν αὐτὸν παρασχεῖν παρεκάλει πρὸς τὸν πόλεμον τὸν πρὸς τοὺς Ἰσραηλίτας καὶ Σύρους καὶ Δαμασκηνοὺς χρήματα πολλὰ δώσειν ὑπισχνούμενος, ἔπεμψε δʼ αὐτῷ καὶ λαμπρὰς δωρεάς."},{"number":253,"text":"ὁ δὲ τῶν πρέσβεων ἀφικομένων ὡς αὐτὸν ἧκε σύμμαχος Ἀχάζῳ, καὶ στρατεύσας ἐπὶ τοὺς Σύρους τήν τε χώραν αὐτῶν ἐπόρθησε καὶ τὴν Δαμασκὸν κατὰ κράτος εἷλε καὶ τὸν βασιλέα Ἀρασὴν ἀπέκτεινε. τοὺς δὲ Δαμασκηνοὺς ἀπῴκισεν εἰς τὴν ἄνω Μηδίαν καὶ ἐκ τῶν ἐθνῶν τῶν Ἀσσυρίων μεταστήσας τινὰς εἰς τὴν Δαμασκὸν κατῴκισε."},{"number":254,"text":"τὴν δὲ τῶν Ἰσραηλιτῶν γῆν κακώσας πολλοὺς ἐξ αὐτῆς αἰχμαλώτους συνέλαβε. ταῦτʼ αὐτοῦ διαπραξαμένου τοὺς Σύρους ὁ βασιλεὺς ἄρας τὸν χρυσὸν ὃς ἦν ἐν τοῖς βασιλικοῖς θησαυροῖς καὶ τὸν ἄργυρον τὸν ἐν τῷ ναῷ τοῦ θεοῦ καὶ εἴ τι κάλλιστον ἀνάθημα, τοῦτο βαστάσας ἧκεν ἔχων εἰς Δαμασκὸν καὶ ἔδωκε τῷ τῶν Ἀσσυρίων βασιλεῖ κατὰ τὰς ὁμολογίας· καὶ πάντων αὐτῷ χάριν ἔχειν ὁμολογήσας ὑπέστρεψεν εἰς Ἱεροσόλυμα."},{"number":255,"text":"ἦν δʼ οὕτως ἀνόητος καὶ τοῦ συμφέροντος ἀσυλλόγιστος ὁ βασιλεὺς, ὥστε οὐδὲ πολεμούμενος ὑπὸ τῶν Σύρων ἐπαύσατο τοὺς θεοὺς αὐτῶν προσκυνῶν, ἀλλὰ διετέλει τούτους σεβόμενος ὡς παρεξομένους αὐτῷ τὴν νίκην."},{"number":256,"text":"ἡττηθεὶς δὲ πάλιν τοὺς Ἀσσυρίων ἤρξατο τιμᾶν θεοὺς καὶ πάντας ἐῴκει μᾶλλον τιμήσων ἢ τὸν πατρῷον καὶ ἀληθῶς θεόν, ὃς αὐτῷ καὶ τῆς ἥττης ὀργιζόμενος ἦν αἴτιος."},{"number":257,"text":"ἐπὶ τοσοῦτον δʼ ὀλιγωρίας καὶ καταφρονήσεως ἦλθεν, ὡς καὶ τέλεον ἀποκλεῖσαι τὸν ναὸν καὶ τὰς νενομισμένας ἀπαγορεῦσαι θυσίας ἐπιφέρειν καὶ περιδῦσαι τῶν ἀναθημάτων αὐτόν. ταῦθʼ ὑβρίσας τὸν θεὸν ἐτελεύτησεν ἔτη μὲν βιώσας ἓξ καὶ τριάκοντα, βασιλεύσας δʼ ἐξ αὐτῶν ἑκκαίδεκα, τὸν δʼ υἱὸν Ἐζεκίαν διάδοχον καταλιπών."}],"13":[{"number":258,"text":"Ἀπέθανε δʼ ὑπὸ τὸν αὐτὸν καιρὸν καὶ ὁ τῶν Ἰσραηλιτῶν βασιλεὺς Φακέας ἐπιβουλεύσαντος αὐτῷ φίλου τινὸς Ὠσήου ὄνομα, ὃς κατασχὼν τὴν βασιλείαν ἐπʼ ἔτη ἐννέα πονηρός τε ἦν καὶ τῶν πρὸς τὸν θεὸν ὀλίγωρος."},{"number":259,"text":"στρατεύει δʼ ἐπʼ αὐτὸν ὁ τῶν Ἀσσυρίων βασιλεὺς Σαλμανάσσας καὶ κρατήσας αὐτοῦ, τὸν γὰρ θεὸν οὐκ εἶχεν Ὠσῆος εὐμενῆ, καὶ σύμμαχον ἐποιήσατο καὶ φόρους ἐπέταξεν αὐτῷ τελεῖν ὡρισμένους."},{"number":260,"text":"ἔτει δὲ τετάρτῳ Ὠσήου τῆς βασιλείας ἐβασίλευσεν Ἐζεκίας ἐν Ἱεροσολύμοις Ἀχάζου υἱὸς καὶ Ἀβίας ἀστῆς τὸ γένος. φύσις δʼ ἦν αὐτῷ χρηστὴ καὶ δικαία καὶ εὐσεβής· οὐδὲν γὰρ ἄλλο πρῶτον εἰς τὴν βασιλείαν παρελθὼν οὐδʼ ἀναγκαιότερον οὐδὲ συμφορώτερον αὑτῷ τε καὶ τοῖς ἀρχομένοις ὑπέλαβε τοῦ θρησκεύειν τὸν θεόν, ἀλλὰ συγκαλέσας τὸν λαὸν καὶ τοὺς ἱερεῖς καὶ τοὺς Ληουίτας ἐδημηγόρησεν ἐν αὐτοῖς λέγων·"},{"number":261,"text":"οὐκ ἀγνοεῖτε μέν, ὡς διὰ τὰς τοῦ πατρὸς ἁμαρτίας τοὐμοῦ παραβάντος τὴν πρὸς θεὸν ὁσίαν καὶ τιμὴν πολλῶν ἐπειράθητε καὶ μεγάλων κακῶν, διαφθαρέντες ὑπʼ αὐτοῦ τὴν διάνοιαν καὶ ἀναπεισθέντες οὓς αὐτὸς ἐδοκίμαζεν εἶναι θεοὺς τούτοις προσκυνεῖν·"},{"number":262,"text":"παραινῶ δὲ ὑμῖν ἔργῳ μεμαθηκότας, ὡς ἔστι δεινὸν τὸ ἀσεβεῖν, τούτου μὲν ἤδη λήθην ποιήσασθαι, καθᾶραι δʼ αὑτοὺς ἐκ τῶν προτέρων μιασμάτων τούς τε ἱερεῖς καὶ Ληουίτας καὶ συνελθόντας οὕτως ἀνοῖξαι τὸ ἱερόν, καὶ καθάραντας αὐτὸ ταῖς ἐξ ἔθους θυσίαις εἰς τὴν ἀρχαίαν καὶ πάτριον ἀνακαλέσασθαι τιμήν. οὕτως γὰρ τὸν θεὸν εὐμενῆ ποιήσαιμεν ἀφέντα τὴν ὀργήν."},{"number":263,"text":"Ταῦτʼ εἰπόντος τοῦ βασιλέως οἱ ἱερεῖς ἀνοίγουσί τε τὸ ἱερὸν καὶ ἀνοίξαντες τὰ σκεύη τοῦ θεοῦ καὶ τὰ μιάσματα ἐκβαλόντες τὰς ἐξ ἔθους τῷ βωμῷ θυσίας ἐπέφερον. διαπέμψας δʼ ὁ βασιλεὺς εἰς τὴν ὑπʼ αὐτὸν χώραν ἐκάλει τὸν λαὸν εἰς Ἱεροσόλυμα τὴν τῶν ἀζύμων ἑορτὴν ἄξοντα· πολὺν γὰρ ἐκλελοίπει χρόνον διὰ τὰς τῶν προειρημένων βασιλέων παρανομίας."},{"number":264,"text":"ἐξαπέστειλε δὲ καὶ πρὸς τοὺς Ἰσραηλίτας προτρεπόμενος αὐτοὺς ἀφέντας τὸν ἄρτι βίον εἰς τὴν ἀρχαίαν ἐπανελθεῖν συνήθειαν καὶ σέβειν τὸν θεόν· καὶ γὰρ ἐπιτρέπειν αὐτοῖς παραγενομένοις εἰς Ἱεροσόλυμα τὴν τῶν ἀζύμων ἑορτὴν ἄγειν καὶ συμπανηγυρίζειν αὐτοῖς. ταῦτα δʼ ἔλεγε παραινεῖν, οὐχ ὅπως ὑπακούσωσιν αὐτοῦ εἰ μὴ θέλουσι, τοῦ δʼ ἐκείνοις συμφέροντος ἕνεκα· μακαρίους γὰρ ἔσεσθαι."},{"number":265,"text":"οἱ δὲ Ἰσραηλῖται παραγενομένων τῶν πρέσβεων καὶ δηλωσάντων αὐτοῖς τὰ παρὰ τοῦ ἰδίου βασιλέως οὐ μόνον οὐκ ἐπείσθησαν, ἀλλὰ καὶ τοὺς πρέσβεις ὡς ἀνοήτους ἐχλεύασαν, καὶ τοὺς προφήτας δὲ ὁμοίως ταῦτα παραινοῦντας καὶ προλέγοντας ἃ πείσονται μὴ μεταθέμενοι πρὸς τὴν εὐσέβειαν τοῦ θεοῦ διέπτυον καὶ τελευταῖον συλλαβόντες αὐτοὺς ἀπέκτειναν."},{"number":266,"text":"καὶ οὐδὲ μέχρι τούτων αὐτοῖς ἤρκεσε παρανομοῦσιν, ἀλλὰ χείρω τῶν προειρημένων ἐπενοοῦντο καὶ οὐ πρότερον ἐπαύσαντο, πρὶν ἢ τοῖς πολεμίοις αὐτοὺς ἀμυνόμενος τῆς ἀσεβείας ὁ θεὸς ἐποίησεν ὑποχειρίους. καὶ περὶ μὲν τούτων αὖθις δηλώσομεν."},{"number":267,"text":"πολλοὶ μέντοι τῆς Μανασσίτιδος φυλῆς καὶ Ζαβούλου καὶ Ἰσσαχάρου πεισθέντες οἷς οἱ προφῆται παρῄνεσαν εἰς εὐσέβειαν μετεβάλοντο. καὶ οὗτοι πάντες εἰς Ἱεροσόλυμα πρὸς Ἐζεκίαν συνέδραμον, ὅπως τῷ θεῷ προσκυνήσωσιν."},{"number":268,"text":"Ἀφικομένων δὲ τούτων ὁ βασιλεὺς Ἐζεκίας ἀναβὰς εἰς τὸ ἱερὸν μετὰ τῶν ἡγεμόνων καὶ τοῦ λαοῦ παντὸς ἔθυσεν ὑπὲρ αὑτοῦ ταύρους ἑπτὰ καὶ κριοὺς τοσούτους καὶ ἄρνας ἑπτὰ καὶ ἐρίφους τοσούτους. ἐπιθέντες δὲ τὰς χεῖρας ταῖς κεφαλαῖς τῶν ἱερείων αὐτός τε ὁ βασιλεὺς καὶ οἱ ἡγεμόνες τοῖς ἱερεῦσι καλλιερεῖν ἐφῆκαν."},{"number":269,"text":"καὶ οἱ μὲν ἔθυόν τε καὶ ὡλοκαύτουν, οἱ δὲ Λευῖται περιεστῶτες ἐν κύκλῳ μετὰ τῶν μουσικῶν ὀργάνων ᾖδον ὕμνους εἰς τὸν θεὸν καὶ ἔψαλλον ὡς ἐδιδάχθησαν ὑπὸ Δαυίδου, οἱ δὲ λοιποὶ ἱερεῖς βυκάνας ἔχοντες ἐπεσάλπιζον τοῖς ὑμνῳδοῦσι. τούτων δὲ γινομένων ἐπὶ πρόσωπον ῥίψαντες αὑτοὺς ὅ τε βασιλεὺς καὶ τὸ πλῆθος προσεκύνουν τὸν θεόν."},{"number":270,"text":"ἔπειτα θύει μὲν βοῦς ἑβδομήκοντα κριοὺς ἑκατὸν ἄρνας διακοσίους, τῷ πλήθει δὲ πρὸς εὐωχίαν ἐχαρίσατο βοῦς μὲν ἑξακοσίους τὰ δὲ λοιπὰ θρέμματα τρισχίλια· καὶ πάντα μὲν οἱ ἱερεῖς ἀκολούθως ἐποίησαν τῷ νόμῳ. τούτοις δʼ ὁ βασιλεὺς ἡδόμενος εὐωχεῖτο μετὰ τοῦ λαοῦ τῷ θεῷ χάριν ἔχειν ὁμολογῶν."},{"number":271,"text":"ἐνστάσης δὲ τῆς τῶν ἀζύμων ἑορτῆς θύσαντες τὴν λεγομένην φάσκα τὰς ἄλλας τὸ λοιπὸν θυσίας ἐπετέλουν ἐπὶ ἡμέρας ἑπτά. τῷ δὲ πλήθει πάρεξ ὧν ἐκαλλιέρησαν αὐτοὶ ταύρους μὲν δισχιλίους θρέμματα δὲ ἑπτακισχίλια ὁ βασιλεὺς ἐχαρίσατο. τὸ δʼ αὐτὸ καὶ οἱ ἡγεμόνες ἐποίησαν· χιλίους μὲν γὰρ ταύρους ἔδοσαν αὐτοῖς θρέμματα δὲ χίλια καὶ τεσσαράκοντα."},{"number":272,"text":"καὶ τοῦτον τὸν τρόπον ἀπὸ Σολόμωνος τοῦ βασιλέως οὐκ ἀχθεῖσα ἡ ἑορτὴ τότε πρῶτον λαμπρῶς καὶ φιλοτίμως ἐπετελέσθη. ὡς δὲ τὰ περὶ τὴν ἑορτὴν αὐτοῖς πέρας εἶχεν, ἐξελθόντες εἰς τὴν χώραν ἥγνισαν αὐτήν·"},{"number":273,"text":"καὶ τὴν πόλιν δὲ παντὸς ἐκάθηραν μιάσματος εἰδώλων, τάς τε καθημερινὰς θυσίας ὁ βασιλεὺς ἐκ τῶν ἰδίων ἐπιτελεῖσθαι διέταξε κατὰ τὸν νόμον, καὶ τοῖς ἱερεῦσι καὶ Ληουίταις τὰς δεκάτας ὥρισε παρὰ τοῦ πλήθους δίδοσθαι καὶ τὰς ἀπαρχὰς τῶν καρπῶν, ἵνʼ ἀεὶ τῇ θρησκείᾳ παραμένωσι καὶ τῆς θεραπείας ὦσιν ἀχώριστοι τοῦ θεοῦ."},{"number":274,"text":"καὶ τὸ μὲν πλῆθος συνεισέφερε παντοδαπὸν καρπὸν τοῖς ἱερεῦσι καὶ Λευίταις, ἀποθήκας δὲ καὶ ταμιεῖα τούτων ὁ βασιλεὺς κατασκευάσας ἑκάστῳ διένειμε τῶν ἱερέων καὶ Ληουιτῶν καὶ παισὶν αὐτῶν καὶ γυναιξί·"},{"number":275,"text":"καὶ οὕτω πάλιν εἰς τὴν ἀρχαίαν θρησκείαν ἐπανῆλθον. ταῦτα δὲ τὸν προειρημένον τρόπον ὁ βασιλεὺς καταστησάμενος πόλεμον ἐξήνεγκε πρὸς τοὺς Παλαιστίνους καὶ νικήσας κατέσχεν ἁπάσας ἀπὸ Γάζης μέχρι Γίττης πόλεις τῶν πολεμίων. ὁ δὲ τῶν Ἀσσυρίων βασιλεὺς πέμψας ἠπείλει πᾶσαν αὐτοῦ καταστρέψεσθαι τὴν ἀρχήν, εἰ μὴ τοὺς φόρους, οὓς ὁ πατὴρ αὐτοῦ τὸ πρῶτον ἐτέλει, τούτους ἀποδώσει."},{"number":276,"text":"Ἐζεκίας δὲ τῶν μὲν ἀπειλῶν οὐκ ἐφρόντισʼ, ἐθάρρει δὲ ἐπὶ τῇ πρὸς τὸ θεῖον εὐσεβείᾳ καὶ τῷ προφήτῃ Ἡσαΐᾳ, παρʼ οὗ πάντʼ ἀκριβῶς τὰ μέλλοντα ἐπυνθάνετο. καὶ ὧδε μὲν ἡμῖν ἐπὶ τοῦ παρόντος ἐχέτω τὰ περὶ τούτου τοῦ βασιλέως."}],"14":[{"number":277,"text":"Σαλμανάσσης δὲ ὁ τῶν Ἀσσυρίων βασιλεύς, ἐπεὶ ἠγγέλη αὐτῷ ὁ τῶν Ἰσραηλιτῶν βασιλεὺς Ὠσείης πέμψας κρύφα πρὸς Σώαν τὸν τῶν Αἰγυπτίων βασιλέα παρακαλῶν αὐτὸν ἐπὶ συμμαχίαν τὴν κατʼ αὐτοῦ, παροξυνθεὶς ἐστράτευσεν ἐπὶ τὴν Σαμάρειαν ἔτει ἑβδόμῳ τῆς Ὠσήου βασιλείας."},{"number":278,"text":"οὐ δεξαμένου δʼ αὐτὸν τοῦ βασιλέως ἔτεσι πολιορκήσας τρισὶν εἷλε κατὰ κράτος τὴν Σαμάρειαν, ἔνατον μὲν ἔτος Ὠσήου βασιλεύοντος ἕβδομον δὲ Ἐζεκίου τοῦ τῶν Ἱεροσολυμιτῶν βασιλέως, καὶ τὴν τῶν Ἰσραηλιτῶν ἡγεμονίαν ἄρδην ἠφάνισε καὶ πάντα τὸν λαὸν μετῴκισεν εἰς τὴν Μηδίαν καὶ Περσίδα, ἐν οἷς καὶ τὸν βασιλέα Ὠσῆν ζῶντα ἔλαβε."},{"number":279,"text":"καὶ μεταστήσας ἄλλα ἔθνη ἀπὸ Χούθου τόπου τινός, ἔστι γὰρ ἐν τῇ Περσίδι ποταμὸς τοῦτʼ ἔχων τοὔνομα, κατῴκισεν εἰς τὴν Σαμάρειαν καὶ τὴν τῶν Ἰσραηλιτῶν χώραν."},{"number":280,"text":"μετῴκησαν οὖν αἱ δέκα φυλαὶ τῶν Ἰσραηλιτῶν ἐκ τῆς Ἰουδαίας μετὰ ἐτῶν ἀριθμὸν ἐνακοσίων τεσσαρακονταεπτά, ἀφʼ οὗ χρόνου τὴν Αἴγυπτον ἐξῆλθον αὐτῶν οἱ πρόγονοι, ὃν δὲ κατέσχον τὴν χώραν ταύτην στρατηγοῦντος Ἰησοῦ ἔστιν ἐτῶν ὀκτακοσίων· ἀφʼ οὗ δʼ ἀποστάντες ἀπὸ Ῥοβοάμου τοῦ Δαυίδου υἱωνοῦ τὴν βασιλείαν Ἱεροβοάμῳ παρέδοσαν, ὥς μοι καὶ πρότερον δεδήλωται, ἔτη ἐστὶ διακόσια τεσσαράκοντα μῆνες ἑπτὰ ἡμέραι ἑπτά."},{"number":281,"text":"καὶ τέλος μὲν τοὺς Ἰσραηλίτας τοιοῦτο κατέλαβε παραβάντας τοὺς νόμους καὶ παρακούσαντας τῶν προφητῶν, οἳ προύλεγον ταύτην αὐτοῖς τὴν συμφορὰν μὴ παυσαμένοις τῶν ἀσεβημάτων."},{"number":282,"text":"ἦρξε δʼ αὐτοῖς τῶν κακῶν ἡ στάσις, ἣν ἐστασίασαν πρὸς Ῥοβόαμον τὸν Δαυίδου υἱωνὸν Ἱερόβαμον τὸν τούτου δοῦλον αὑτῶν ἀποδείξαντες βασιλέα, ὃς εἰς τὸ θεῖον ἐξαμαρτὼν ἐχθρὸν αὐτοῖς τοῦτο ἐποίησε μιμησαμένοις τὴν ἐκείνου παρανομίαν. ἀλλʼ ὁ μὲν ἧς ἦν ἄξιος δίκης ταύτην ὑπέσχεν."},{"number":283,"text":"Ὁ δὲ τῶν Ἀσσυρίων βασιλεὺς ἐπῆλθε πολεμῶν τήν τε Συρίαν πᾶσαν τήν τε Φοινίκην, τό τε ὄνομα τούτου τοῦ βασιλέως ἐν τοῖς Τυρίων ἀρχείοις ἀναγέγραπται· ἐστράτευσε γὰρ ἐπὶ Τύρον βασιλεύοντος αὐτῆς Ἐλουλαίου. μαρτυρεῖ δὲ καὶ τούτοις Μένανδρος ὁ τῶν χρονικῶν ποιησάμενος τὴν ἀναγραφὴν καὶ τὰ τῶν Τυρίων ἀρχεῖα μεταφράσας εἰς τὴν Ἑλληνικὴν γλῶτταν, ὃς οὕτως ἐδήλωσε·"},{"number":284,"text":"καὶ Ἐλουλαῖος θεμένων αὐτῷ Πύας ὄνομα ἐβασίλευσεν ἔτη τριακονταέξ. οὗτος ἀποστάντων Κιτταίων ἀναπλεύσας προσηγάγετο αὐτοὺς πάλιν. ἐπὶ τούτου Σελάμψας ὁ τῶν Ἀσσυρίων βασιλεὺς ἐπῆλθε Φοινίκην πολεμῶν ἅπασαν, ὅστις σπεισάμενος εἰρήνην μετὰ πάντων ἀνεχώρησεν ὀπίσω·"},{"number":285,"text":"ἀπέστη τε Τυρίων Σιδὼν καὶ Ἄρκη καὶ ἡ πάλαι Τύρος καὶ πολλαὶ ἄλλαι πόλεις, αἳ τῷ Ἀσσυρίων ἑαυτὰς βασιλεῖ παρέδοσαν. διʼ ἃ Τυρίων οὐχ ὑποταγέντων πάλιν ὁ βασιλεὺς ἐπʼ αὐτοὺς ὑπέστρεψε Φοινίκων συμπληρωσάντων αὐτῷ ναῦς ἑξήκοντα καὶ ἐπικώπους ὀκτακοσίους."},{"number":286,"text":"αἷς ἐπιπλεύσαντες οἱ Τύριοι ναυσὶ δεκαδύο τῶν νεῶν τῶν ἀντιπάλων διασπαρεισῶν λαμβάνουσιν αἰχμαλώτους ἄνδρας εἰς πεντακοσίους· ἐπετάθη δὴ πάντων ἐν Τύρῳ τιμή."},{"number":287,"text":"διὰ ταῦτʼ ἀναζεύξας ὁ τῶν Ἀσσυρίων βασιλεὺς κατέστησε φύλακας ἐπὶ τοῦ ποταμοῦ καὶ τῶν ὑδραγωγείων, οἳ διακωλύσουσι Τυρίους ἀρύεσθαι, καὶ τοῦτο ἔτεσι πέντε γενόμενον ἐκαρτέρησαν πίνοντες ἐκ φρεάτων ὀρυκτῶν. καὶ τὰ μὲν ἐν τοῖς Τυρίων ἀρχείοις γεγραμμένα κατὰ Σαλμανάσσου τοῦ Ἀσσυρίων βασιλέως ταῦτʼ ἐστίν."},{"number":288,"text":"Οἱ δὲ μετοικισθέντες εἰς τὴν Σαμάρειαν Χουθαῖοι, ταύτῃ γὰρ ἐχρῶντο μέχρι δεῦρο τῇ προσηγορίᾳ διὰ τὸ ἐκ τῆς Χουθᾶ καλουμένης χώρας μεταχθῆναι, αὕτη δʼ ἐστὶν ἐν τῇ Περσίδι καὶ ποταμὸς τοῦτʼ ἔχων ὄνομα, ἕκαστοι κατὰ ἔθνος ἴδιον θεὸν εἰς τὴν Σαμάρειαν κομίσαντες, πέντε δʼ ἦσαν, καὶ τούτους καθὼς ἦν πάτριον αὐτοῖς σεβόμενοι παροξύνουσι τὸν μέγιστον θεὸν εἰς ὀργὴν καὶ χόλον."},{"number":289,"text":"λοιμὸν γὰρ αὐτοῖς ἐνέσκηψεν, ὑφʼ οὗ φθειρόμενοι οὐδεμίαν τῶν κακῶν θεραπείαν ἐπινοοῦντες χρησμῷ θρησκεύειν τὸν μέγιστον θεόν, ὡς τοῦτο σωτήριον αὐτοῖς ὄν, ἔμαθον. πέμψαντες οὖν πρὸς τὸν Ἀσσυρίων βασιλέα πρέσβεις ἐδέοντο ἱερεῖς αὐτοῖς ὧν ἔλαβεν αἰχμαλώτων τοὺς Ἰσραηλίτας πολεμήσας ἀποστεῖλαι."},{"number":290,"text":"πέμψαντός τε τὰ νόμιμα καὶ τὴν περὶ τὸν θεὸν τοῦτον ὁσίαν διδαχθέντες ἐθρήσκευον αὐτὸν φιλοτίμως καὶ τοῦ λοιμοῦ παραχρῆμα ἐπαύσαντο. χρώμενοί τε τοῖς αὐτοῖς ἔτι καὶ νῦν ἔθεσι διατελοῦσιν οἱ κατὰ μὲν τὴν Ἑβραίων γλῶτταν Χουθαῖοι, κατὰ δὲ τὴν Ἑλλήνων Σαμαρεῖται,"},{"number":291,"text":"οἳ πρὸς μεταβολὴν συγγενεῖς μὲν ὅταν εὖ πράττοντας βλέπωσι τοὺς Ἰουδαίους ἀποκαλοῦσιν ὡς ἐξ Ἰωσήπου φύντες καὶ τὴν ἀρχὴν ἐκεῖθεν τῆς πρὸς αὐτοὺς ἔχοντες οἰκειότητος, ὅταν δὲ πταίσαντας ἴδωσιν, οὐδαμόθεν αὐτοῖς προσήκειν λέγουσιν οὐδʼ εἶναι δίκαιον οὐδὲν αὐτοῖς εὐνοίας ἢ γένους, ἀλλὰ μετοίκους ἀλλοεθνεῖς ἀποφαίνουσιν αὑτούς. περὶ μὲν τούτων ἕξομεν εὐκαιρότερον εἰπεῖν."}]},"count":291};a[10]={"book":10,"title":"Τάδε ἔνεστιν ἐν τῇ δεκάτῃ βίβλῳ τῶν Ἰωσήπου ἱστοριῶν τῆς Ἰουδαϊκῆς ἀρχαιολογίας.","argument":{"title":"","text":"α. Στρατεία τοῦ Ἀσσυρίων βασιλέως Σεναχειρίβου ἐπὶ Ἱεροσόλυμα καὶ πολιορκία τοῦ βασιλέως αὐτῶν Ἐζεκίου.\n\nβ. ὡς ἐφθάρη τὸ τῶν Ἀσσυρίων στράτευμα λοιμικῶς ἐν μιᾷ νυκτὶ καὶ ὁ βασιλεὺς αὐτῶν ἀναζεύξας οἴκαδε ἐξ ἐπιβουλῆς τῶν τέκνων ἀπέθανεν.\n\nγ. ὡς τὸν μεταξὺ χρόνον μετ' εἰρήνης Ἐζεκίας διαγαγὼν ἐτελεύτησε διάδοχον τῆς βασιλείας Μανασσῆν καταλιπών.\n\nδ. ὅτι στρατεύσαντες ἐπ' αὐτὸν οἱ Χαλδαίων καὶ Βαβυλωνίων βασιλεῖς καὶ νικήσαντες αὐτὸν αἰχμάλωτον λαβόντες ἤγαγον εἰς Βαβυλῶνα, καὶ κατασχόντες αὐτόθι πολὺν χρόνον εἰς τὴν αὐτὴν βασιλείαν πάλιν ἀπέλυσαν.\n\nε. ὡς τὸν Αἰγυπτίων βασιλέα Νεχαῶνα στρατευσάμενον ἐπὶ Βαβυλωνίους καὶ ποιούμενον διὰ τῆς Ἰουδαίας τὴν ὁδὸν κωλύων ὁ βασιλεὺς Ἰωσίας ὑπαντᾷ· μάχης δὲ γενομένης τραυματίας κομισθεὶς εἰς Ἱεροσόλυμα τελευτᾷ καὶ τὸν υἱὸν αὐτοῦ Ἰωάζην ἀπέδειξαν οἱ Ἱεροσολυμῖται βασιλέα.\n\nϛ. ὡς συμβαλὼν ὁ Νεχαὼς τῷ τῶν Βαβυλωνίων βασιλεῖ κατὰ τὸν Εὐφράτην ποταμὸν καὶ ὑποστρέφων εἰς Αἴγυπτον ἧκεν εἰς Ἱεροσόλυμα καὶ τὸν μὲν Ἰωάζην ἤγαγεν εἰς Αἴγυπτον, τὸν δ' ἀδελφὸν αὐτοῦ Ἰωάκειμον ἀνέδειξε βασιλέα τῶν Ἱεροσολυμιτῶν.\n\nζ. Ναβουχοδονοσάρου τοῦ τῶν Βαβυλωνίων βασιλέως στρατεία εἰς Συρίαν, καὶ ὡς πᾶσαν αὐτὴν καταστρεψάμενος ἄχρι τῶν ὅρων τῶν Αἰγυπτίων ἀνέβη εἰς Ἱεροσόλυμα καὶ τὸν βασιλέα αὐτῶν Ἰωάκειμον φίλον ἠνάγκασεν εἶναι καὶ σύμμαχον.\n\nη. ὡς μετὰ τὴν ἀναχώρησιν τὴν τοῦ Βαβυλωνίου πάλιν ὁ Ἰωάκειμος ἐφρόνησε τὰ τῶν Αἰγυπτίων καὶ στρατεύσας ἐπ' αὐτὸν ὁ Ναβουχοδονόσαρος καὶ πολιορκήσας τῆς πόλεως παραδούσης ἑαυτὴν μετὰ χρόνον τὸν μὲν Ἰωάκειμον ἀπέκτεινεν, Ἰωάκειμον δὲ τὸν υἱὸν αὐτοῦ κατέστησε βασιλέα· καὶ ὡς πολλὰ χρήματα λαβὼν ἐκ τῶν Ἱεροσολύμων εὐθέως εἰς Συρίαν ὑπέστρεψεν.\n\nθ. ὅτι μετανοήσας ἐπὶ τῷ τὸν Ἰωάκειμον ποιῆσαι βασιλέα καὶ στρατεύσας ἐπὶ Ἱεροσόλυμα ἐγκρατὴς τοῦ Ἰωακείμου γίνεται παραδόντος αὑτὸν μετὰ τῆς μητρὸς καὶ τῶν φίλων, ὅπως τ' ἔλαβε πολλοὺς αἰχμαλώτους ὁ Βαβυλώνιος καὶ ἀναθήματα βαστάσας ἐκ τοῦ ἱεροῦ ἀνέστρεψεν εἰς Βαβυλῶνα τὸν Ἰεχονίου θεῖον Σαχχίαν τῶν Ἱεροσολυμιτῶν βασιλέα καταστήσας.\n\nι. ὡς καὶ τοῦτον ἀκούσας βούλεσθαι πρὸς τοὺς Αἰγυπτίους συμμαχίαν ποιήσασθαι καὶ φιλίαν στρατεύσας ἐπὶ τὰ Ἱεροσόλυμα κατὰ κράτος αἱρεῖ τῇ πολιορκίᾳ καὶ τὸν ναὸν ἐμπρήσας τὸν τῶν Ἱεροσολυμιτῶν δῆμον καὶ Σεδεκίαν μετῴκισεν εἰς Βαβυλῶνα.\n\nια. ὡς Ναβουχοδονόσαρος τελευτήσας διάδοχον καταλείπει τῆς βασιλείας τὸν υἱόν, καὶ ὡς καταλύεται ἡ τούτων ἀρχὴ ὑπὸ Κύρου τοῦ τῶν Περσῶν βασιλέως.\n\nιβ. ὅσα συνέβη τοῖς Ἰουδαίοις κατὰ τοῦτον τὸν καιρὸν παρὰ τοῖς Βαβυλωνίοις.\n\nπεριέχει ἡ βίβλος χρόνον ἐτῶν ρπβ μῆνας ϛ ἡμέρας ι."},"chapters":{"1":[{"number":1,"text":"Ἐζεκίου δὲ τοῦ τῶν δύο φυλῶν βασιλέως τέταρτον ἤδη καὶ δέκατον ἔτος τῆς ἡγεμονίας ἔχοντος ὁ τῶν Βαβυλωνίων βασιλεὺς Σεναχείριμος ὄνομα στρατεύει μετὰ πολλῆς παρασκευῆς ἐπʼ αὐτὸν κατὰ κράτος τε ἁπάσας αἱρεῖ τὰς πόλεις τὰς τῆς Ἰούδα φυλῆς καὶ Βενιαμίτιδος."},{"number":2,"text":"μέλλοντος δʼ ἄγειν τὴν δύναμιν καὶ ἐπὶ Ἱεροσόλυμα φθάνει πρεσβευσάμενος πρὸς αὐτὸν καὶ ὑπακούσεσθαι καὶ φόρον ὃν ἂν τάξῃ τελέσειν ὑπισχνούμενος. Σεναχείριμος δὲ μαθὼν τὰ παρὰ τῶν πρέσβεων ἔγνω μὴ πολεμεῖν, ἀλλὰ τὴν ἀξίωσιν προσδέχεται καὶ ἀργυρίου μὲν τάλαντα τριακόσια χρυσίου δὲ τριάκοντα λαβὼν φίλος ἀναχωρήσειν ὡμολόγει πίστεις δοὺς τοῖς πρεσβευταῖς ἐνόρκους, ἦ μὴν ἀδικήσας μηδὲν αὐτὸν οὕτως ἀναστρέψειν."},{"number":3,"text":"ὁ δʼ Ἐζεκίας πεισθεὶς καὶ κενώσας τοὺς θησαυροὺς πέμπει τὰ χρήματα νομίζων ἀπαλλαγήσεσθαι τοῦ πολέμου καὶ τοῦ περὶ τῆς βασιλείας ἀγῶνος."},{"number":4,"text":"ὁ δὲ Ἀσσύριος λαβὼν ταῦτα τῶν μὲν ὡμολογημένων οὐδὲν ἐφρόντισεν, ἀλλʼ αὐτὸς μὲν ἐστράτευσεν ἐπʼ Αἰγυπτίους καὶ Αἰθίοπας, τὸν δὲ στρατηγὸν Ῥαψάκην μετὰ πολλῆς ἰσχύος σὺν καὶ δυσὶν ἄλλοις τῶν ἐν τέλει κατέλιπε πορθήσοντας τὰ Ἱεροσόλυμα. τούτων δὲ τὰ ὀνόματα Θαρατὰ καὶ Ἀράχαρις ἦν."},{"number":5,"text":"Ὡς δʼ ἐλθόντες πρὸ τῶν τειχῶν ἐστρατοπεδεύσαντο, πέμψαντες πρὸς τὸν Ἐζεκίαν ἠξίουν αὐτὸν ἐλθεῖν εἰς λόγους. ὁ δὲ αὐτὸς μὲν ὑπὸ δειλίας οὐ πρόεισι, τρεῖς δὲ τοὺς ἀναγκαιοτάτους φίλους αὐτῷ ἐξέπεμψε, τὸν τῆς βασιλείας ἐπίτροπον Ἐλιακίαν ὄνομα καὶ Σουβαναῖον καὶ Ἰώανον τὸν ἐπὶ τῶν ὑπομνημάτων."},{"number":6,"text":"οὗτοι μὲν οὖν προελθόντες ἀντικρὺ τῶν ἡγεμόνων τῆς στρατιᾶς τῶν Ἀσσυρίων ἔστησαν, θεασάμενος δʼ αὐτοὺς ὁ στρατηγὸς Ῥαψάκης ἐκέλευσεν ἀπελθόντας Ἐζεκίᾳ λέγειν, ὅτι βασιλεὺς μέγας Σεναχείριμος πυνθάνεται αὐτοῦ, τίνι θαρρῶν καὶ πεποιθὼς φεύγει δεσπότην αὐτοῦ καὶ ἀκροάσασθαι μὴ θέλει καὶ τὴν στρατιὰν οὐ δέχεται τῇ πόλει; ἦ διὰ τοὺς Αἰγυπτίους τὴν αὐτοῦ στρατιὰν ἐλπίζων ὑπʼ ἐκείνων αὐτῶν καταγωνίσασθαι;"},{"number":7,"text":"εἰ δὲ τοῦτο προσδοκᾷ, δηλοῦν αὐτῷ, ὅτι ἀνόητός ἐστι καὶ ὅμοιος ἀνθρώπῳ, ὃς καλάμῳ ἐπερειδόμενος τεθλασμένῳ πρὸς τῷ καταπεσεῖν ἔτι καὶ τὴν χεῖρα διαπαρεὶς ᾔσθετο τῆς βλάβης. εἰδέναι δʼ ὅτι καὶ βουλήσει θεοῦ τὴν ἐπʼ αὐτὸν στρατείαν πεποίηται, ὃς αὐτῷ καταστρέψασθαι καὶ τὴν τῶν Ἰσραηλιτῶν βασιλείαν δέδωκεν, ἵνα τὸν αὐτὸν τρόπον καὶ τοὺς ἀρχομένους ὑπʼ αὐτοῦ διαφθείρῃ."},{"number":8,"text":"ταῦτα δὲ τὸν Ῥαψάκην ἑβραϊστὶ λέγοντα, τῆς γὰρ γλώττης εἶχεν ἐμπείρως, ὁ Ἐλιάκειμος φοβούμενος, μὴ τὸ πλῆθος ἐπακοῦσαν εἰς ταραχὴν ἐμπέσῃ, συριστὶ φράζειν ἠξίου. συνεὶς δʼ ὁ στρατηγὸς τὴν ὑπόνοιαν αὐτοῦ καὶ τὸ ἐπʼ αὐτῷ δέος μείζονι καὶ διατόρῳ τῇ φωνῇ χρώμενος ἀπεκρίνατο αὐτῷ ἑβραϊστὶ λέγειν, ὅπως ἀκούσαντες τὰ τοῦ βασιλέως προστάγματα πάντες τὸ συμφέρον ἕλωνται παραδόντες αὑτοὺς ἡμῖν·"},{"number":9,"text":"δῆλον γὰρ ὡς τὸν λαὸν ὑμεῖς τε καὶ ὁ βασιλεὺς ἐλπίσι παρακρουόμενοι ματαίαις ἀντέχειν πείθετε. εἰ δὲ θαρρεῖτε καὶ τὴν δύναμιν ἡμῶν ἀπώσεσθαι νομίζετε, δισχιλίους ἐκ τῆς ἐμοὶ παρούσης ἵππους ἕτοιμός εἰμι ὑμῖν παρέχειν, οἷς ἰσαρίθμους ἐπιβάτας δόντες ἐμφανίσατε τὴν αὑτῶν δύναμιν· ἀλλʼ οὐκ ἂν οὕς γε μὴ ἔχετε τούτους δῴητε."},{"number":10,"text":"τί τοιγαροῦν βραδύνετε παραδιδόναι σφᾶς αὐτοὺς τοῖς κρείττοσι καὶ ληψομένοις ὑμᾶς καὶ μὴ θέλοντας; καίτοι τὸ μὲν ἑκούσιον τῆς παραδόσεως ἀσφαλὲς ὑμῖν, τὸ δὲ ἀκούσιον πολεμουμένοις ἐπικίνδυνον καὶ συμφορῶν αἴτιον φανεῖται."},{"number":11,"text":"Ταῦτʼ ἀκούσαντες ὅ τε δῆμος καὶ οἱ πρέσβεις τοῦ στρατηγοῦ τῶν Ἀσσυρίων λέγοντος ἀπήγγειλαν Ἐζεκίᾳ. ὁ δὲ πρὸς ταῦτα τὴν βασιλικὴν ἀποδὺς ἐσθῆτα, ἀμφιασάμενος δὲ σάκκους καὶ σχῆμα ταπεινὸν ἀναλαβὼν τῷ πατρίῳ νόμῳ πεσὼν ἐπὶ πρόσωπον τὸν θεὸν ἱκέτευε καὶ βοηθῆσαι τῷ μηδεμίαν ἄλλην ἐλπίδα ἔχοντι σωτηρίας ἠντιβόλει."},{"number":12,"text":"πέμψας δὲ καὶ τῶν φίλων τινὰς καὶ τῶν ἱερέων πρὸς Ἡσαΐαν τὸν προφήτην ἠξίου δεηθῆναι τοῦ θεοῦ καὶ ποιησάμενον θυσίας ὑπὲρ τῆς κοινῆς σωτηρίας παρακαλεῖν αὐτὸν νεμεσῆσαι μὲν ταῖς τῶν πολεμίων ἐλπίσιν, ἐλεῆσαι δὲ τὸν αὐτοῦ λαόν."},{"number":13,"text":"ὁ δὲ προφήτης ταῦτα ποιήσας χρηματίσαντος αὐτῷ τοῦ θεοῦ παρεθάρρυνεν αὐτόν τε τὸν βασιλέα καὶ τοὺς περὶ αὐτὸν φίλους προλέγων ἀμαχητὶ τοὺς πολεμίους ἡττηθέντας ἀναχωρήσειν αἰσχρῶς καὶ οὐχὶ μεθʼ οἵου νῦν εἰσι θράσους·"},{"number":14,"text":"τὸν γὰρ θεὸν προνοεῖν ὅπως διαφθαρῶσι· καὶ αὐτὸν δὲ τὸν βασιλέα τῶν Ἀσσυρίων Σεναχείριμον διαμαρτόντα τῶν ἐπὶ τὴν Αἴγυπτον πραγμάτων καὶ ἐπανερχόμενον εἰς τὴν οἰκείαν ἀπολεῖσθαι σιδήρῳ προύλεγεν."},{"number":15,"text":"Ἔτυχε δʼ ὑπὸ τὸν αὐτὸν καιρὸν καὶ γεγραφὼς τῷ Ἐζεκίᾳ ὁ Ἀσσύριος ἐπιστολάς, ἐν αἷς ἀνόητον μὲν αὐτὸν ἔλεγεν ὑπολαμβάνοντα τὴν ὑπʼ αὐτῷ διαφεύξεσθαι δουλείαν ἔθνη πολλὰ καὶ μεγάλα κεχειρωμένῳ, ἠπείλει δὲ πανωλεθρίᾳ διαφθερεῖν αὐτὸν παραλαβών, εἰ μὴ τὰς πύλας ἀνοίξας ἑκὼν αὐτοῦ δέξεται τὴν στρατιὰν εἰς τὰ Ἱεροσόλυμα."},{"number":16,"text":"ταῦτʼ ἀναγνοὺς καταφρονεῖ διὰ τὴν ἀπὸ τοῦ θεοῦ πεποίθησιν, τὰς δʼ ἐπιστολὰς πτύξας εἰς τὸν ναὸν ἔσω κατέθετο. πάλιν δὲ τῷ θεῷ τὰς εὐχὰς αὐτοῦ ποιησαμένου περὶ τῆς πόλεως καὶ τῆς ἁπάντων σωτηρίας Ἡσαΐας ὁ προφήτης ἐπήκοον αὐτὸν ἔφασκε γεγονέναι καὶ κατὰ τὸν παρόντα καιρὸν μὴ πολιορκηθήσεσθαι ὑπὸ τοῦ Σύρου, μέλλοντι πάντων ἀδεεῖς τῶν ὑπʼ αὐτοῦ γενομένων γεωργήσειν μετʼ εἰρήνης καὶ τῶν ἰδίων ἐπιμελήσεσθαι κτημάτων οὐδὲν φοβουμένους."},{"number":17,"text":"ὀλίγου δὲ χρόνου διελθόντος καὶ ὁ τῶν Ἀσσυρίων βασιλεὺς διαμαρτὼν τῆς ἐπὶ τοὺς Αἰγυπτίους ἐπιβολῆς ἄπρακτος ἀνεχώρησεν ἐπʼ οἴκου διʼ αἰτίαν τοιαύτην· πολὺς αὐτῷ χρόνος ἐτρίβετο πρὸς τὴν Πηλουσίου πολιορκίαν, καὶ τῶν χωμάτων ἤδη μετεώρων ὄντων, ἃ πρὸς τοῖς τείχεσιν ἤγειρε, καὶ ὅσον οὔπω μέλλοντος προσβαλεῖν αὐτοῖς, ἀκούει τὸν τῶν Αἰθιόπων βασιλέα Θαρσικὴν πολλὴν ἄγοντα δύναμιν ἐπὶ συμμαχίᾳ τοῖς Αἰγυπτίοις ἥκειν διεγνωκότα ποιήσασθαι τὴν πορείαν διὰ τῆς ἐρήμου καὶ ἐξαίφνης εἰς τὴν τῶν Ἀσσυρίων ἐμβαλεῖν."},{"number":18,"text":"ταραχθεὶς οὖν ὑπὸ τούτων ὁ βασιλεὺς Σεναχείριμος ἐπὶ τὸν ἱερέα τὸν Ἡφαίστου στρατεῦσαι ἔλεγεν ὡς οὗτος ὁ βασιλεὺς ἐπὶ τὸν τῶν Αἰγυπτίων ἔλθοι βασιλέα ἱερέα ὄντα τοῦ Ἡφαίστου, πολιορκῶν δὲ τὸ Πηλούσιον ἔλυσε τὴν πολιορκίαν ἐξ αἰτίας τοιαύτης· ηὔξατο ὁ βασιλεὺς τῶν Αἰγυπτίων τῷ θεῷ, ᾧ γενόμενος ἐπήκοος ὁ θεὸς πληγὴν ἐνσκήπτει τῷ Ἄραβι·"},{"number":19,"text":"πλανᾶται γὰρ κἀν τούτῳ οὐκ Ἀσσυρίων λέγων τὸν βασιλέα ἀλλʼ Ἀράβων· μυῶν γὰρ πλῆθός φησι μιᾷ νυκτὶ τὰ τόξα καὶ τὰ λοιπὰ ὅπλα διαφαγεῖν τῶν Ἀσσυρίων, καὶ διὰ τοῦτο μὴ ἔχοντα τόξα τὸν βασιλέα τὴν στρατιὰν ἀπάγειν ἀπὸ τοῦ Πηλουσίου."},{"number":20,"text":"καὶ Ἡρόδοτος μὲν οὕτως ἱστορεῖ, Βηρωσὸς δὲ ὁ τὰ Χαλδαϊκὰ συγγραψάμενος μνημονεύει τοῦ βασιλέως τοῦ Σεναχειρίμου, καὶ ὅτι τῶν Ἀσσυρίων ἦρχε καὶ ὅτι πάσῃ ἐπεστρατεύσατο τῇ Ἀσίᾳ καὶ τῇ Αἰγύπτῳ λέγων οὕτως·"},{"number":21,"text":"Ὑποστρέψας δʼ ὁ Σεναχείριμος ἀπὸ τῶν Αἰγυπτίων πολέμων εἰς τὰ Ἱεροσόλυμα, καταλαβὼν ἐκεῖ τὴν ὑπὸ τῷ στρατηγῷ Ῥαψάκῃ δύναμιν τοῦ θεοῦ λοιμικὴν ἐνσκήψαντος αὐτοῦ τῷ στρατῷ νόσον κατὰ τὴν πρώτην νύκτα τῆς πολιορκίας διαφθείρονται μυριάδες ὀκτωκαίδεκα καὶ πεντακισχίλιοι σὺν ἡγεμόσι καὶ ταξιάρχαις."},{"number":22,"text":"ὑπὸ ταύτης δὲ τῆς συμφορᾶς εἰς φόβον καὶ δεινὴν ἀγωνίαν καταστὰς καὶ δείσας περὶ τῷ στρατῷ παντὶ φεύγει μετὰ τῆς λοιπῆς δυνάμεως εἰς τὴν αὑτοῦ βασιλείαν τὴν Νίνου προσαγορευθεῖσαν."},{"number":23,"text":"καὶ διατρίψας ἐν αὐτῇ ὀλίγον χρόνον δολοφονηθεὶς ὑπὸ τῶν πρεσβυτέρων παίδων Ἀνδρομάχου καὶ Σελευκάρου τελευτᾷ τὸν βίον καὶ ἀνετέθη τῷ ἰδίῳ ναῷ Ἀράσκῃ λεγομένῳ. καὶ οἱ μὲν φυγαδευθέντες ἐπὶ τῷ φόνῳ τοῦ πατρὸς ὑπὸ τῶν πολιτῶν εἰς τὴν Ἀρμενίαν ἀπῆραν, διαδέχεται δὲ τὴν βασιλείαν τῶν μετʼ αὐτοὺς καταφρονῶν τοῦ Σεναχειρίμου Ἀσαραχόδδας. καὶ τὸ μὲν τῆς Ἀσσυρίων στρατείας τῆς ἐπὶ τοὺς Ἱεροσολυμίτας τέλος τοιοῦτο συνέβη γενέσθαι."}],"2":[{"number":24,"text":"Ἐζεκίας δʼ ὁ βασιλεὺς παραδόξως ἀπαλλαγεὶς τῶν φόβων χαριστηρίους σὺν ἅπαντι τῷ λαῷ θυσίας ἐπετέλεσε τῷ θεῷ, μηδεμιᾶς ἄλλης αἰτίας τῶν πολεμίων τοὺς μὲν διαφθειράσης τοὺς δὲ φόβῳ τῆς ὁμοίας τελευτῆς ἀπαλλαξάσης ἀπὸ τῶν Ἱεροσολυμιτῶν ἢ τῆς συμμαχίας τῆς ἀπὸ τοῦ θεοῦ."},{"number":25,"text":"πάσῃ δὲ χρησάμενος σπουδῇ καὶ φιλοτιμίᾳ περὶ τὸν θεὸν μετʼ οὐ πολὺ νόσῳ χαλεπῇ περιπεσὼν ἀπέγνωστο μὲν ὑπὸ τῶν ἰατρῶν, χρηστὸν δὲ περὶ αὑτοῦ οὐδὲν προσδοκῶν, οὐδὲ γὰρ οἱ φίλοι. τῇ δὲ νόσῳ προσετίθετο καὶ ἀθυμία δεινὴ ὑπὸ τοῦ βασιλέως αὐτοῦ τὴν ἀπαιδίαν λογιζομένου, καὶ ὅτι μέλλοι τελευτᾶν ἔρημον καταλιπὼν τὸν οἶκον καὶ τὴν ἀρχὴν γνησίας διαδοχῆς."},{"number":26,"text":"κάμνων οὖν ὑπʼ αὐτῆς τῆς ἐννοίας μάλιστα καὶ ὀδυρόμενος ἱκέτευε τὸν θεὸν αὐτῷ ζωῆς ὀλίγον χρόνον προσεπιδοῦναι μέχρι τέκνων γονῆς, καὶ μὴ πρότερον ἢ πατὴρ γένηται τὴν ψυχὴν αὐτὸν ἐᾶσαι καταλιπεῖν."},{"number":27,"text":"ἐλεήσας δὲ αὐτὸν ὁ θεὸς καὶ τῆς αἰτήσεως ἀποδεξάμενος, ὅτι μὴ διὰ τὸ μέλλειν στέρεσθαι τῶν ἐκ τῆς βασιλείας ἀγαθῶν ὠδύρετο τὴν ὑπονοηθεῖσαν τελευτὴν ἔτι τε χρόνον ζωῆς αὐτῷ δεηθείη παρασχεῖν, ἀλλὰ τοῦ παῖδας αὐτῷ γενέσθαι τοὺς ὑποδεξομένους τὴν ἡγεμονίαν ἐκείνου, πέμψας Ἡσαΐαν τὸν προφήτην ἐκέλευσε δηλοῦν αὐτῷ, ὅτι καὶ διαφεύξεται τὴν νόσον μετὰ τρίτην ἡμέραν καὶ βιώσεται μετʼ αὐτὴν ἔτη πεντεκαίδεκα καὶ παῖδες αὐτῷ γενήσονται."},{"number":28,"text":"ταῦτα τοῦ προφήτου φήσαντος κατʼ ἐντολὴν τοῦ θεοῦ διὰ τὴν ὑπερβολὴν τῆς νόσου καὶ τὸ παράδοξον τῶν ἀπηγγελμένων ἀπιστῶν σημεῖόν τι καὶ τεράστιον ἠξίου ποιῆσαι τὸν Ἡσαΐαν, ἵνα αὐτῷ πιστεύσῃ λέγοντι ταῦτα ἥκοντι παρὰ τοῦ θεοῦ· τὰ γὰρ παράλογα καὶ μείζω τῆς ἐλπίδος τοῖς ὁμοίοις πιστοῦται πράγμασιν."},{"number":29,"text":"ἐρωτήσαντος δʼ αὐτὸν τί βούλεται σημεῖον γενέσθαι, τὸν ἥλιον ἠξίωσεν, ἐπειδὴ σκιὰν ἐπὶ δέκα βαθμοὺς ἀποκλίνας ἤδη πεποίηκεν ἐν τῇ οἰκίᾳ, ἐπὶ τὸν αὐτὸν ἀναστρέψαι τόπον ποιήσας αὐτὴν πάλιν παρασχεῖν. τοῦ δὲ προφήτου τὸν θεὸν παρακαλέσαντος, ὥστε τὸ σημεῖον τοῦτʼ ἐπιδεῖξαι τῷ βασιλεῖ, ἰδὼν ὅπερ ἤθελεν εὐθὺς λυθεὶς τῆς νόσου ἄνεισιν εἰς τὸ ἱερὸν καὶ τῷ θεῷ προσκυνήσας εὐχὰς ἐποιήσατο."},{"number":30,"text":"Ἐν τούτῳ δὲ τῷ χρόνῳ συνέβη τὴν τῶν Ἀσσυρίων ἀρχὴν ὑπὸ Μήδων καταλυθῆναι· δηλώσω δὲ περὶ τούτων ἐν ἑτέροις. ὁ δὲ τῶν Βαβυλωνίων βασιλεὺς Βαλάδας ὄνομα πέμψας πρὸς τὸν Ἐζεκίαν πρέσβεις δῶρα κομίζοντας σύμμαχόν τε αὐτὸν εἶναι παρεκάλει καὶ φίλον."},{"number":31,"text":"ὁ δὲ τοὺς πρεσβευτὰς ἡδέως ἀποδεξάμενος ἑστιασάμενός τε καὶ τοὺς θησαυροὺς ἐπιδείξας αὐτοῖς καὶ τὴν τῶν ὅπλων παρασκευὴν καὶ τὴν ἄλλην πολυτέλειαν, ὅσην ἐν λίθοις εἶχε καὶ χρυσῷ, δῶρά τε δοὺς κομίζειν τῷ Βαλάδῳ πρὸς αὐτὸν ἀπέλυσεν."},{"number":32,"text":"Ἡσαΐου δὲ τοῦ προφήτου πρὸς αὐτὸν ἀφικομένου καὶ πυνθανομένου πόθεν εἶεν οἱ παρόντες, ἐκ Βαβυλῶνος ἔλεγε παρὰ τοῦ θεοῦ ἐλθεῖν αὐτούς· ἐπιδεῖξαι δὲ πάντʼ αὐτοῖς, ὅπως ἰδόντες τὸν πλοῦτον καὶ τὴν δύναμιν ἐκ τούτου στοχαζόμενοι σημαίνειν ἔχωσι τῷ βασιλεῖ. ὁ δὲ προφήτης ὑποτυχών ἴσθι"},{"number":33,"text":", φησίν, οὐ μετʼ ὀλίγον χρόνον εἰς Βαβυλῶνά σου τοῦτον μετατεθησόμενον τὸν πλοῦτον καὶ τοὺς ἐκγόνους εὐνουχισθησομένους καὶ ἀπολέσαντας τὸ ἄνδρας εἶναι τῷ Βαβυλωνίῳ δουλεύσοντας βασιλεῖ· ταῦτα γὰρ προλέγειν τὸν θεόν."},{"number":34,"text":"ὁ δʼ Ἐζεκίας λυπηθεὶς ἐπὶ τοῖς εἰρημένοις ἔφη μὲν οὐκ ἂν βούλεσθαι τοιαύταις συμφοραῖς τὸ ἔθνος αὐτοῦ περιπεσεῖν, ἐπεὶ δʼ οὐκ εἶναι δυνατὸν τὰ τῷ θεῷ δεδογμένα μεταβαλεῖν, ηὔχετο μέχρι τῆς αὐτοῦ ζωῆς εἰρήνην ὑπάρξαι. μνημονεύει δὲ τοῦ τῶν Βαβυλωνίων βασιλέως Βαλαδᾶ Βηρωσός."},{"number":35,"text":"ὢν δʼ οὗτος ὁ προφήτης θεῖος ὁμολογουμένως καὶ θαυμάσιος τὴν ἀλήθειαν, πεποιθὼς τῷ μηδὲν ὅλως ψευδὲς εἰπεῖν ἅπανθʼ ὅσα προεφήτευσεν ἐγγράψας βίβλοις κατέλιπεν ἐκ τοῦ τέλους γνωρισθησόμενα τοῖς αὖθις ἀνθρώποις. καὶ οὐχ οὗτος μόνος ὁ προφήτης, ἀλλὰ καὶ ἄλλοι δώδεκα τὸν ἀριθμὸν τὸ αὐτὸ ἐποίησαν, καὶ πᾶν εἴ τι φαῦλον γίνεται παρʼ ἡμῖν κατὰ τὴν ἐκείνων ἀποβαίνει προφητείαν. ἀλλὰ τούτων μὲν αὖθις ἐξαγγελοῦμεν ἕκαστον."}],"3":[{"number":36,"text":"Ἐπιβιοὺς δʼ ὃν προειρήκαμεν χρόνον ὁ βασιλεὺς Ἐζεκίας καὶ πάντα τοῦτον ἐν εἰρήνῃ διαγαγὼν τελευτᾷ πεντηκοστὸν μὲν καὶ τέταρτον ἔτος τῆς ζωῆς διανύσας, εἴκοσι δὲ βασιλεύσας καὶ ἐννέα."},{"number":37,"text":"διαδεξάμενος δὲ τὴν βασιλείαν ὁ παῖς αὐτοῦ Μανασσῆς ἐκ μητρὸς μὲν Ἐχίβας τοὔνομα πολίτιδος γεγονώς, ἀπέρρηξεν ἑαυτὸν τῶν τοῦ πατρὸς ἐπιτηδευμάτων καὶ τὴν ἐναντίαν ἐτράπετο πᾶν εἶδος πονηρίας ἐπιδειξάμενος ἐν τῷ τρόπῳ καὶ μηδὲν ἀσεβὲς παραλιπών, ἀλλὰ μιμούμενος τὰς τῶν Ἰσραηλιτῶν παρανομίας, οἳ εἰς τὸν θεὸν ἁμαρτόντες ἀπώλοντο· μιᾶναι δὲ καὶ τὸν ναὸν ἐτόλμησε τοῦ θεοῦ καὶ τὴν πόλιν καὶ τὴν χώραν ἅπασαν."},{"number":38,"text":"ἀπὸ γὰρ τῆς εἰς τὸν θεὸν καταφρονήσεως ὁρμώμενος πάντας τοὺς δικαίους τοὺς ἐν τοῖς Ἑβραίοις ἀπέκτεινεν, ἀλλʼ οὐδὲ τῶν προφητῶν ἔσχε φειδὼ καὶ τούτων δέ τινας καθʼ ἡμέραν ἀπέσφαζεν, ὥστε αἵματι ῥεῖσθαι τὰ Ἱεροσόλυμα."},{"number":39,"text":"λαβὼν οὖν ὀργὴν ἐπὶ τούτοις ὁ θεὸς πέμπει προφήτας πρὸς τὸν βασιλέα καὶ τὸ πλῆθος, διʼ ὧν αὐτοῖς ἠπείλησε τὰς αὐτὰς συμφοράς, αἷς συνέβη περιπεσεῖν τοὺς ἀδελφοὺς αὐτῶν Ἰσραηλίτας εἰς αὐτὸν ἐξυβρίζοντας. οἱ δὲ τοῖς μὲν λόγοις οὐκ ἐπίστευον, παρʼ ὧν ἠδύναντο κερδῆσαι τὸ μηδενὸς πειραθῆναι κακοῦ, τοῖς δʼ ἔργοις ἔμαθον ἀληθῆ τὰ παρὰ τῶν προφητῶν."},{"number":40,"text":"Ὡς γὰρ τοῖς αὐτοῖς ἐπέμενον, πόλεμον ἐπʼ αὐτοὺς ἐκίνει παρά τε τοῦ τῶν Βαβυλωνίων καὶ Χαλδαίων βασιλέως, ὃς στρατιὰν πέμψας εἰς τὴν Ἰουδαίαν τήν τε χώραν αὐτῶν ἐλεηλάτησε καὶ τὸν βασιλέα Μανασσῆν δόλῳ ληφθέντα καὶ πρὸς αὐτὸν ἀχθέντα πρὸς ἣν ἠβούλετο τιμωρίαν εἶχεν ὑποχείριον."},{"number":41,"text":"ὁ δὲ Μανασσῆς τότε συνεὶς ἐν οἵοις κακοῖς ἐστι καὶ πάντων ἑαυτὸν αἴτιον νομίζων ἐδεῖτο τοῦ θεοῦ παρέχειν αὐτῷ φιλάνθρωπον καὶ ἐλεήμονα τὸν πολέμιον. χαρίζεται τοῦτο τῆς ἱκεσίας ἐπακούσας ὁ θεὸς αὐτῷ καὶ πάλιν εἰς τὴν οἰκείαν ὁ Μανασσῆς ἀπολυθεὶς ὑπὸ τοῦ τῶν Βαβυλωνίων βασιλέως ἀνασώζεται."},{"number":42,"text":"γενόμενος δʼ εἰς τὰ Ἱεροσόλυμα τῶν μὲν προτέρων ἁμαρτημάτων περὶ τὸν θεὸν καὶ τὴν μνήμην ἐσπούδαζεν, εἰ δυνατὸν αὐτῷ γένοιτο, τῆς ψυχῆς ἐκβαλεῖν, ὧν ἐπιβουλεύειν ὥρμησε καὶ πάσῃ χρῆσθαι περὶ αὐτὸν δεισιδαιμονίᾳ· καὶ τὸν ναὸν ἥγνισε καὶ τὴν πόλιν ἐκάθηρε καὶ πρὸς μόνῳ τὸ λοιπὸν ἦν τῷ χάριν τε τῆς σωτηρίας ἐκτείνειν τῷ θεῷ καὶ διατηρεῖν αὐτὸν εὐμενῆ παρʼ ὅλον τὸν βίον."},{"number":43,"text":"τὰ δὲ αὐτὰ πράττειν καὶ τὸ πλῆθος ἐδίδασκε μεμαθηκώς, οἵᾳ παρὰ μικρὸν ἐχρήσατο συμφορᾷ διὰ τὴν ἐναντίαν πολιτείαν. ἐπισκευάσας δὲ καὶ τὸν βωμὸν τὰς νομίμους θυσίας ἐπετέλει, καθὼς διέταξε Μωυσῆς."},{"number":44,"text":"διοικησάμενος δὲ τὰ περὶ τὴν θρησκείαν ὃν δεῖ τρόπον καὶ τῆς τῶν Ἱεροσολύμων ἀσφαλείας προενόησεν, ὥστε τὰ παλαιὰ τείχη μετὰ πολλῆς ἐπισκευάσας σπουδῆς καὶ ἕτερον αὐτοῖς ἐπιβαλεῖν, ἀναστῆσαί τε καὶ πύργους ὑψηλοτάτους τά τε πρὸ τῆς πόλεως φρούρια τοῖς τʼ ἄλλοις καὶ δὴ καὶ σιτίων πάντων τῶν εἰς αὐτὰ χρησίμων ὀχυρώτερα ποιῆσαι."},{"number":45,"text":"ἀμέλει δὲ τῇ πρὸς ταῦτα μεταβολῇ χρησάμενος οὕτω τὸν μεταξὺ διῆγε βίον, ὡς μακαριστὸς εἶναι καὶ ζηλωτὸς ἐκείνου τοῦ χρόνου λογιζομένου, ἀφʼ οὗ τὸν θεὸν εὐσεβεῖν ἤρξατο."},{"number":46,"text":"ζήσας οὖν ἔτη ἑξήκοντα ἑπτὰ κατέστρεψε τὸν βίον βασιλεύσας ἔτη πέντε καὶ πεντήκοντα. καὶ θάπτεται μὲν αὐτὸς ἐν τοῖς αὐτοῦ παραδείσοις, ἡ βασιλεία δὲ εἰς τὸν υἱὸν αὐτοῦ παραγίνεται Ἀμμῶνα μητρὸς Ἐμασέλμης μὲν ὄνομα τετυχηκότα, ἐκ δὲ πόλεως Ἰαζαβάτης ὑπαρχούσης."}],"4":[{"number":47,"text":"Οὗτος μιμησάμενος τὰ τοῦ πατρὸς ἔργα, ἃ νέος ὢν ἐκεῖνος ἐτόλμησεν, ἐπιβουλευθεὶς ὑπὸ τῶν ἰδίων οἰκετῶν ἀπέθανεν ἐπὶ τῆς οἰκίας τῆς αὑτοῦ βιώσας ἔτη τέσσαρα καὶ εἴκοσι, βασιλεύσας δʼ ἐξ αὐτῶν δύο."},{"number":48,"text":"μετῆλθε δʼ αὐτοῦ τὸ πλῆθος τοὺς φονεῖς καὶ τῷ πατρὶ συνθάπτουσι τὸν Ἀμμῶνα, τὴν δὲ βασιλείαν τῷ παιδὶ αὐτοῦ Ἰωσίᾳ παραδιδοῦσιν ὀκταετεῖ τὴν ἡλικίαν ὄντι, ᾧ μήτηρ ἐκ πόλεως μὲν ἦν Βοσκέθ, Ἰέδις δὲ τοὔνομα."},{"number":49,"text":"τὴν δὲ φύσιν αὐτὸς ἄριστος ὑπῆρχε καὶ πρὸς ἀρετὴν εὖ γεγονὼς Δαυίδου τοῦ βασιλέως ἐπιτηδευμάτων καὶ σκοπῷ καὶ κανόνι τῆς ὅλης περὶ τὸν βίον ἐπιτηδεύσεως ἐκείνῳ κεχρημένος."},{"number":50,"text":"γενόμενος δὲ ἐτῶν δυοκαίδεκα τὴν εὐσέβειαν καὶ τὴν δικαιοσύνην ἐπεδείξατο· τὸν γὰρ λαὸν ἐσωφρόνιζε καὶ παρῄνει τῆς περὶ τῶν εἰδώλων δόξης ὡς οὐχὶ θεῶν ὄντων ἀποστάντας σέβειν τὸν πάτριον θεόν, τά τε τῶν προγόνων ἐπισκοπῶν ἔργα τὰ μὲν ἁμαρτηθέντα διώρθου συνετῶς ὡς ἂν πρεσβύτατος καὶ νοῆσαι τὸ δέον ἱκανώτατος, ὅσα δʼ εὕρισκεν εὖ γεγονότα κατὰ χώραν ἐφύλαττέ τε καὶ ἐμιμεῖτο."},{"number":51,"text":"ταῦτα δʼ ἔπραττε σοφίᾳ καὶ ἐπινοίᾳ τῆς φύσεως χρώμενος καὶ τῇ τῶν πρεσβυτέρων πειθόμενος συμβουλίᾳ καὶ παραδόσει· τοῖς γὰρ νόμοις κατακολουθῶν ὡς περὶ τὴν τάξιν τῆς πόλεως καὶ περὶ τὸ θεῖον εὐσεβείας εὐοδεῖν τε συνέβαινε διὰ τὴν τῶν πρώτων παρανομίαν μὴ τυγχάνειν ἀλλʼ ἐξηφανίσθαι·"},{"number":52,"text":"περιιὼν γὰρ ὁ βασιλεὺς καὶ τὴν πόλιν καὶ τὴν χώραν ἅπασαν τά τε ἄλση τὰ τοῖς ξενικοῖς ἀνειμένα θεοῖς ἐξέκοψε καὶ τοὺς βωμοὺς αὐτῶν κατέσκαψεν, εἴ τι δʼ ἀνάθημα τούτοις ὑπὸ τῶν προγόνων ἀνέκειτο περιυβρίζων κατέσπα."},{"number":53,"text":"καὶ τούτῳ τῷ τρόπῳ τὸν λαὸν ἀπὸ τῆς περὶ αὐτοὺς δόξης εἰς τὴν τοῦ θεοῦ θρησκείαν ἐπέστρεψε καὶ τὰς συνήθεις ἐπέφερε θυσίας αὐτοῦ τῷ βωμῷ καὶ τὰς ὁλοκαυτώσεις. ἀπέδειξε δέ τινας κριτὰς καὶ ἐπισκόπους, ὡς ἂν διοικοῖεν τὰ παρʼ ἑκάστοις πράγματα περὶ παντὸς τὸ δίκαιον ποιούμενοι καὶ τῆς ψυχῆς οὐκ ἔλασσον αὐτὸ περιέποντες."},{"number":54,"text":"διαπέμψας δὲ κατὰ πᾶσαν τὴν χώραν χρυσὸν καὶ ἄργυρον τοὺς βουλομένους ἐκέλευε κομίζειν εἰς ἐπισκευὴν τοῦ ναοῦ, ὅσον τις ἢ προαιρέσεως ἢ δυνάμεως ἔχει."},{"number":55,"text":"κομισθέντων δὲ τῶν χρημάτων τῆς ἐπιμελείας τοῦ ναοῦ καὶ τῆς εἰς τοῦτο δαπάνης προύστησε τόν τʼ ἐπὶ τῆς πόλεως Ἀμασίαν καὶ τὸν γραμματέα Σαφᾶν καὶ τὸν γραφέα τῶν ὑπομνημάτων Ἰωάτην καὶ τὸν ἀρχιερέα Ἐλιακίαν,"},{"number":56,"text":"οἳ μηδὲν ὑπερθέσει μηδὲ ἀναβολῇ δόντες ἀρχιτέκτονας καὶ πάνθʼ ὅσα πρὸς τὴν ἐπισκευὴν χρήσιμα παρασκευάσαντες εἴχοντο τῶν ἔργων. καὶ ὁ μὲν ναὸς οὕτως ἐπισκευασθεὶς τὴν τοῦ βασιλέως εὐσέβειαν φανερὰν ἐποίησεν."},{"number":57,"text":"Ὄγδοον δʼ ἤδη καὶ δέκατον τῆς βασιλείας ἔτος ἔχων πέμπει πρὸς Ἐλιακίαν τὸν ἀρχιερέα κελεύων τὸ περισσὸν χωνεύσαντα ποιῆσαι κρατῆρας καὶ σπονδεῖα καὶ φιάλας εἰς τὴν διακονίαν, ἔτι δὲ καὶ ὅσος ἂν ᾖ χρυσὸς ἐν τοῖς θησαυροῖς καὶ ἄργυρος καὶ τοῦτον προκομίσαντας εἰς τοὺς κρατῆρας ὁμοίως καὶ τὰ τοιαῦτα σκεύη δαπανῆσαι."},{"number":58,"text":"προκομίζων δὲ τὸν χρυσὸν ὁ ἀρχιερεὺς Ἐλιακίας ἐντυγχάνει ταῖς ἱεραῖς βίβλοις ταῖς Μωυσέος ἐν τῷ ναῷ κειμέναις καὶ προκομίσας δίδωσι τῷ γραμματεῖ Σαφᾷ. ὁ δὲ ἀναγνοὺς παραγίνεται πρὸς τὸν βασιλέα καὶ πάντα ὅσα κελεύει γενέσθαι τέλος ἔχοντα ἐδήλου, παρανέγνω δʼ αὐτῷ καὶ τὰς βίβλους αὐτῶν."},{"number":59,"text":"ἀκούσας δὲ καὶ περιρρηξάμενος τὴν ἐσθῆτα τὸν ἀρχιερέα καλέσας Ἐλιακίαν καὶ αὐτὸν τὸν γραμματέα καὶ τῶν ἀναγκαιοτάτων φίλων τινὰς ἔπεμψε πρὸς τὴν προφῆτιν Ὀολδά, γυναῖκα δὲ Σαλλούμου τῶν ἐν δόξῃ τινὸς καὶ διʼ εὐγένειαν ἐπιφανοῦς, καὶ προσελθόντας ἐκέλευε λέγειν ἱλάσκεσθαι τὸν θεὸν καὶ πειρᾶσθαι ποιεῖν εὐμενῆ· δέος γὰρ εἶναι, μὴ παραβάντων τοὺς Μωυσέος νόμους τῶν προγόνων αὐτῶν κινδυνεύσωσιν ἀνάστατοι γενέσθαι καὶ τῆς οἰκείας ἐκπεσόντες ἐπʼ ἀλλοτρίας ἔρημοι πάντων καταστρέψωσιν οἰκτρῶς τὸν βίον."},{"number":60,"text":"ἀκούσασα δʼ ἡ προφῆτις παρὰ τῶν πεμφθέντων ταῦτα διʼ αὐτῶν ὧν ἐπέστειλεν ὁ βασιλεὺς ἐκέλευσεν αὐτοὺς ἀπελθόντας πρὸς τὸν βασιλέα λέγειν, ὅτι τὸ μὲν θεῖον ἤδη κατʼ αὐτῶν ψῆφον ἤνεγκεν, ἣν οὐχ ἱκεσίαις ἄν τις ἄκυρον ποιήσειεν, ἀπολέσαι τὸν λαὸν καὶ τῆς χώρας ἐκβαλεῖν καὶ πάντων ἀφελέσθαι τῶν νῦν παρόντων ἀγαθῶν παραβάντας τοὺς νόμους καὶ τοσούτῳ μεταξὺ χρόνῳ μὴ μετανοήσαντας, τῶν τε προφητῶν τοῦτο παραινούντων σωφρονεῖν καὶ τὴν ἐπὶ τοῖς ἀσεβήμασι τιμωρίαν προλεγόντων·"},{"number":61,"text":"ἥν, ἵνα πεισθῶσιν, ὅτι θεός ἐστι καὶ οὐδὲν ἐψεύδετο τούτων ὧν αὐτοῖς διὰ τῶν προφητῶν κατήγγειλε, πάντως αὐτοῖς ποιήσειν. διʼ αὐτὸν μέντοι δίκαιον γενόμενον ἐφέξειν ἔτι τὰς συμφοράς, μετὰ δὲ τὴν ἐκείνου τελευτὴν τὰ κατεψηφισμένα πάθη τοῖς ὄχλοις ἐπιπέμψειν."},{"number":62,"text":"Οἱ μὲν οὖν τῆς γυναικὸς προφητευσάσης ἐλθόντες ἀπήγγειλαν τῷ βασιλεῖ. ὁ δὲ περιπέμψας πανταχοῦ τὸν λαὸν ἐκέλευε συνελθεῖν εἰς Ἱεροσόλυμα τούς θʼ ἱερεῖς καὶ τοὺς Λευίτας, πᾶσαν ἡλικίαν παρεῖναι προστάξας."},{"number":63,"text":"ἀθροισθέντων δὲ αὐτῶν πρῶτον μὲν αὐτοῖς ἀνέγνω τὰς ἱερὰς βίβλους, ἔπειτα στὰς ἐπὶ τοῦ βήματος ἐν μέσῳ τῷ πλήθει ὅρκους ποιήσασθαι καὶ πίστεις ἠνάγκασεν, ἦ μὴν θρησκεύσειν τὸν θεὸν καὶ φυλάξειν τοὺς Μωυσέος νόμους."},{"number":64,"text":"οἱ δὲ προθύμως τʼ ἐπῄνεσαν καὶ τὰ παραινεθέντα ὑπὸ τοῦ βασιλέως ποιήσειν ὑπέστησαν θύοντές τε παραχρῆμα καὶ καλλιεροῦντες ἤδη τὸν θεὸν ἱκέτευον εὐμενῆ καὶ ἵλεων αὐτοῖς ὑπάρχειν."},{"number":65,"text":"τὸν δὲ ἀρχιερέα προσέταξεν εἴ τι περισσὸν ὑπὸ τῶν προγόνων σκεῦος τοῖς εἰδώλοις καὶ ξενικοῖς θεοῖς κατασταθὲν ἦν ἐν τῷ ναῷ, τοῦτο ἐκβαλεῖν. συναθροισθέντων δὲ πολλῶν καταπρήσας αὐτὰ τὴν σποδὸν αὐτῶν διέσπειρε καὶ τοὺς ἱερεῖς τῶν εἰδώλων οὐκ ὄντας ἐκ τοῦ Ἀαρῶνος γένους ἀπέκτεινε."},{"number":66,"text":"Ταῦτα δὲ ἐν τοῖς Ἱεροσολύμοις διαπραξάμενος ἧκεν εἰς τὴν χώραν καὶ τὰ κατασκευασθέντα ἐν αὐτῇ ὑπὸ Ἱεροβοάμου τοῦ βασιλέως εἰς τιμὴν τῶν ξενικῶν θεῶν ἠφάνισε καὶ τὰ ὀστᾶ τῶν ψευδοπροφητῶν ἐπὶ τοῦ βωμοῦ, ὃν κατεσκεύασε πρῶτος Ἱερόβαμος, κατέκαυσε."},{"number":67,"text":"ταῦτα δὲ προφήτην κατελθόντα πρὸς Ἱερόβαμον θυσιάζοντος αὐτοῦ καὶ παντὸς ἀκούοντος τοῦ λαοῦ προκαταγγεῖλαι τὰ γενησόμενα, ὅτι τις ἐκ τοῦ Δαυίδου γένους Ἰωσίας τοὔνομα ποιήσει τὰ προειρημένα. συνέβη δὲ ταῦτα λαβεῖν τέλος μετὰ ἔτη τριακόσια καὶ ἑξηκονταέν."},{"number":68,"text":"Μετὰ δὲ ταῦτα ὁ βασιλεὺς Ἰωσίας πορευθεὶς καὶ πρὸς τοὺς ἄλλους τῶν Ἰσραηλιτῶν, ὅσοι τὴν αἰχμαλωσίαν καὶ τὴν δουλείαν τὴν ὑπὸ τῶν Ἀσσυρίων διέφυγον, ἀφεῖναι μὲν τὰς ἀσεβεῖς πράξεις καὶ τὰς τιμὰς τὰς πρὸς τοὺς ἀλλοτρίους θεοὺς ἐγκαταλιπεῖν ἔπεισε, τὸν δὲ πάτριον καὶ μέγιστον θεὸν εὐσεβεῖν καὶ τούτῳ προσανέχειν·"},{"number":69,"text":"τὰς οἰκίας τε καὶ τὰς κώμας ἠρεύνησε καὶ τὰς πόλεις, μή τις ἔνδον ἔχοι τι τῶν εἰδώλων ὑπονοῶν. οὐ μὴν ἀλλὰ καὶ τὰ τοῖς βασιλευομένοις ἐφεστῶτα ἅρματα, ἃ κατεσκεύασαν οἱ πρόγονοι, καὶ εἴ τι ἄλλο τοιοῦτον ἦν ᾧ προσεκύνουν ὡς θεῷ ἐβάστασε·"},{"number":70,"text":"καὶ καθαρίσας οὕτω τὴν χώραν ἅπασαν εἰς Ἱεροσόλυμα τὸν λαὸν συνεκάλεσε κἀκεῖ τὴν ἀζύμων ἑορτὴν καὶ τὴν πάσχα λεγομένην ἤγαγεν· ἐδωρήσατό τε τῷ λαῷ τὸ πάσχα νεογνοὺς ἐρίφους καὶ ἄρνας δισμυρίους, βοῦς δʼ εἰς ὁλοκαυτώματα τρισχιλίους."},{"number":71,"text":"παρεῖχον δὲ καὶ τῶν ἱερέων οἱ πρῶτοι διὰ τὸ πάσχα τοῖς ἱερεῦσιν ἄρνας δισχιλίους ἑξακοσίους καὶ τοῖς Λευίταις πεντακισχιλίους ἄρνας ἔδοσαν οἱ προεστῶτες αὐτῶν, βοῦς δὲ πεντακοσίους."},{"number":72,"text":"καὶ γενομένης οὕτως ἀφθόνου τῆς τῶν ἱερείων εὐπορίας τὰς θυσίας ἐπετέλουν τοῖς Μωυσέος νόμοις, ἑκάστῳ τῶν ἱερέων ἐξηγουμένων καὶ διακονουμένων τοῖς ὄχλοις, καὶ τοῦ μηδεμίαν ἄλλην οὕτως ἀχθῆναι τοῖς Ἑβραίοις ἑορτὴν ἀπὸ τῶν Σαμουήλου τοῦ προφήτου χρόνων αἴτιον ἦν τὸ πάντα κατὰ νόμους καὶ κατὰ τὴν ἀρχαίαν παρατήρησιν τῆς πατρίου συνηθείας ἐπιτελεσθῆναι."},{"number":73,"text":"ζήσας δʼ ἐν εἰρήνῃ μετὰ ταῦτα ὁ Ἰωσίας ἔτι δὲ καὶ πλούτῳ καὶ τῇ παρὰ πᾶσιν εὐδοξίᾳ κατέστρεψε τούτῳ τῷ τρόπῳ τὸν βίον·"}],"5":[{"number":74,"text":"Νεχαῦς ὁ τῶν Αἰγυπτίων βασιλεὺς ἐγείρας στρατιὰν ἐπὶ τὸν Εὐφράτην ἤλασε ποταμὸν Μήδους πολεμήσων καὶ τοὺς Βαβυλωνίους, οἳ τὴν Ἀσσυρίων κατέλυσαν ἀρχήν· τῆς γὰρ Ἀσίας βασιλεῦσαι πόθον εἶχε."},{"number":75,"text":"γενομένου δʼ αὐτοῦ κατὰ Μένδην πόλιν, ἦν δʼ αὕτη τῆς Ἰωσίου βασιλείας, μετὰ δυνάμεως εἶργεν αὐτὸν διὰ τῆς ἰδίας ποιεῖσθαι χώρας τὴν ἐπὶ τοὺς Μήδους ἔλασιν. πέμψας δὲ κήρυκα πρὸς αὐτὸν Νεχαῦς οὐκ ἐπʼ αὐτὸν στρατεύειν ἔλεγεν, ἀλλʼ ἐπὶ τὸν Εὐφράτην ὡρμηκέναι· μὴ παροξύνειν δʼ αὐτὸν ἐκέλευεν, ὥστε πολεμεῖν αὐτῷ κωλύοντι βαδίζειν ἐφʼ οὗ διέγνωκεν."},{"number":76,"text":"Ἰωσίας δὲ οὐ προσίετο τὰ παρὰ τοῦ Νεχαῦ, ἀλλʼ οὕτως εἶχεν ὡς μὴ συγχωρεῖν αὐτῷ τὴν οἰκείαν διέρχεσθαι, τῆς πεπρωμένης οἶμαι εἰς τοῦτʼ αὐτὸν παρορμησάσης, ἵνα λάβῃ πρόφασιν κατʼ αὐτοῦ."},{"number":77,"text":"διατάσσοντος γὰρ αὐτοῦ τὴν δύναμιν καὶ ἐφʼ ἅρματος ἀπὸ κέρως ἐπὶ κέρας ὀχουμένου τοξεύσας τις αὐτὸν τῶν Αἰγυπτίων ἔπαυσε τῆς πρὸς τὴν μάχην σπουδῆς· τῷ τραύματι γὰρ περιαλγὴς ὢν ἐκέλευσεν ἀνακληθῆναι τὸ στράτευμα καὶ ὑπέστρεψεν εἰς τὰ Ἱεροσόλυμα. τελευτᾷ δʼ ἐκ τῆς πληγῆς ἐκεῖ τὸν βίον καὶ κηδεύεται ἐν ταῖς πατρῴαις θήκαις μεγαλοπρεπῶς βιώσας μὲν ἔτη τριακονταεννέα, βασιλεύσας δὲ τούτων ἓν καὶ τριάκοντα."},{"number":78,"text":"πένθος δʼ ἐπʼ αὐτῷ μέγα τοῦ λαοῦ παντὸς ἤχθη πολλαῖς ἡμέραις ὀδυρομένου καὶ κατηφοῦντος· Ἱερεμίας δὲ ὁ προφήτης ἐπικήδειον αὐτοῦ συνέταξε μέλος θρηνητικόν, ὃ καὶ μέχρι νῦν διαμένει."},{"number":79,"text":"οὗτος ὁ προφήτης καὶ τὰ μέλλοντα τῇ πόλει δεινὰ προεκήρυξεν ἐν γράμμασι καταλιπὼν καὶ τὴν νῦν ἐφʼ ἡμῶν γενομένην ἅλωσιν τήν τε Βαβυλῶνος αἵρεσιν. οὐ μόνον δὲ οὗτος προεθέσπισε ταῦτα τοῖς ὄχλοις, ἀλλὰ καὶ ὁ προφήτης Ἰεζεκίηλος, ὃς πρῶτος περὶ τούτων δύο βίβλους γράψας κατέλιπεν."},{"number":80,"text":"ἦσαν δὲ οἱ δύο τῷ γένει ἱερεῖς, ἀλλʼ ὁ μὲν Ἱερεμίας ἐν Ἱεροσολύμοις διῆγεν ἀπὸ τρισκαιδεκάτου ἔτους τῆς Ἰωσίου βασιλείας ἕως οὗ κατεσκάφη ἡ πόλις καὶ ὁ ναός. τὰ μέντοι γε συμβάντα περὶ τοῦτον τὸν προφήτην κατὰ χώραν δηλώσομεν."},{"number":81,"text":"Τελευτήσαντος δὲ Ἰωσίου, καθὼς προειρήκαμεν, τὴν βασιλείαν ὁ παῖς αὐτοῦ διαδέχεται Ἰώαζος τοὔνομα τρίτον καὶ εἰκοστὸν ἤδη ἔτος γεγονώς. καὶ οὗτος μὲν ἐν Ἱεροσολύμοις ἐβασίλευσε μητρὸς Ἀμιτάλης καὶ πόλεως Τομάνης ἀσεβὴς δὲ καὶ μιαρὸς τὸν τρόπον·"},{"number":82,"text":"ὁ δὲ τῶν Αἰγυπτίων βασιλεὺς ὑποστρέψας ἀπὸ τῆς μάχης μεταπέμπεται τὸν Ἰώαζον πρὸς αὑτὸν εἰς Ἀμαθὰ καλουμένην πόλιν, ἥτις ἐστὶ τῆς Συρίας, καὶ τὸν μὲν ἐλθόντα ἔδησε, τῷ δὲ πρεσβυτέρῳ αὐτοῦ ἀδελφῷ ὁμοπατρίῳ ὄντι Ἐλιακείμῳ τοὔνομα τὴν βασιλείαν παραδίδωσι μετονομάσας αὐτὸν Ἰωάκειμον· τῇ δὲ χώρᾳ ἐπέταξεν ἑκατὸν ἀργυρίου τάλαντα, ἓν δὲ χρυσίου."},{"number":83,"text":"καὶ τοῦτο μὲν ἐτέλει ὁ Ἰωάκειμος τὸ πλῆθος τῶν χρημάτων, τὸν δὲ Ἰώαζον ἀπήγαγεν εἰς Αἴγυπτον, ὃς καὶ ἐτελεύτησεν ἐν αὐτῇ βασιλεύσας μῆνας τρεῖς ἡμέρας δέκα. ἡ δὲ τοῦ Ἰωακείμου μήτηρ ἐκαλεῖτο Ζαβουδᾶ, ἐκ πόλεως δʼ ἦν Ἀβουμᾶς. ἐτύγχανε δʼ ὢν τὴν φύσιν ἄδικος καὶ κακοῦργος καὶ μήτε πρὸς θεὸν ὅσιος μήτε πρὸς ἀνθρώπους ἐπιεικής."}],"6":[{"number":84,"text":"Ἔτος δʼ αὐτοῦ τῆς βασιλείας τέταρτον ἤδη ἔχοντος τὴν Βαβυλωνίων ἀρχὴν παραλαμβάνει Ναβουχοδονόσορος ὄνομα, ὃς ὑπὸ τὸν αὐτὸν καιρὸν μετὰ μεγάλης παρασκευῆς ἐπὶ Καρχάμισσαν ἀναβαίνει πόλιν, ἔστι δʼ αὕτη πρὸς τῷ Εὐφράτῃ ποταμῷ, διεγνωκὼς πολεμεῖν τῷ τῶν Αἰγυπτίων Νεχαῦ· ὑπὸ τούτῳ γὰρ ἦν ἅπασα ἡ Συρία."},{"number":85,"text":"μαθὼν δὲ τὴν τοῦ Βαβυλωνίου προαίρεσιν καὶ τὴν ἐπʼ αὐτὸν στρατείαν ὁ Νεχαῦς οὐδὲ αὐτὸς ὠλιγώρησεν, ἀλλὰ σὺν πολλῇ χειρὶ τὸν Ναβουχοδονόσορον ἀμυνούμενος ὥρμησεν ἐπὶ τὸν Εὐφράτην."},{"number":86,"text":"συμβολῆς δὲ γενομένης ἡττήθη καὶ πολλὰς ἀπέβαλε μυριάδας ἐν τῇ μάχῃ. διαβὰς δὲ τὸν Εὐφράτην ὁ Βαβυλώνιος τὴν ἄχρι Πηλουσίου παραλαμβάνει Συρίαν πάρεξ τῆς Ἰουδαίας."},{"number":87,"text":"τέσσαρα δʼ ἔτη βασιλεύοντος ἤδη τοῦ Ναβουχοδονοσόρου ὄγδοον ἦν τῷ Ἰωακείμῳ τῷ τῶν Ἑβραίων ἔχοντι τὴν ἀρχήν, καὶ στρατεύει μετὰ πολλῆς δυνάμεως ἐπὶ τοὺς Ἰουδαίους ὁ Βαβυλώνιος φόρους αἰτῶν τὸν Ἰωάκειμον ἢ πολεμήσειν ἀπειλῶν. ὁ δὲ δείσας τὴν ἀπειλὴν καὶ τὴν εἰρήνην ἀντικαταλλαξάμενος τῶν χρημάτων ἤνεγκεν αὐτῷ φόρους οὓς ἔταξεν ἐπὶ ἔτη τρία."},{"number":88,"text":"Τῷ δὲ τρίτῳ στρατεύειν τοὺς Αἰγυπτίους ἀκούσας ἐπὶ τὸν Βαβυλώνιον καὶ τοὺς φόρους αὐτῷ μὴ δοὺς διεψεύσθη τῆς ἐλπίδος·"},{"number":89,"text":"οἱ γὰρ Αἰγύπτιοι ποιήσασθαι τὴν στρατείαν οὐκ ἐθάρρησαν. ταῦτα δὲ ὁ προφήτης Ἱερεμίας κατὰ πᾶσαν ἡμέραν προύλεγεν, ὡς μάτην ταῖς παρὰ τῶν Αἰγυπτίων ἐλπίσι προσανέχουσι, καὶ ὡς δεῖ τὴν πόλιν ὑπὸ τοῦ Βαβυλωνίων βασιλέως ἀνάστατον γενέσθαι, καὶ Ἰωακείμῳ τῷ βασιλεῖ χειρωθῆναι ὑπʼ αὐτοῦ."},{"number":90,"text":"ἀλλὰ ταῦτʼ οὐδὲν χρήσιμον οὐκ ὄντων τῶν σωθησομένων ἐλέγετο· καὶ γὰρ τὸ πλῆθος καὶ οἱ ἄρχοντες ἀκούοντες παρημέλουν, καὶ πρὸς ὀργὴν λαμβάνοντες τὰ λεγόμενα ὡς οἰωνιζομένου κατὰ τοῦ βασιλέως τοῦ προφήτου τὸν Ἱερεμίαν ᾐτιῶντο, καὶ ὑπάγοντες δίκῃ καταψηφισθῆναι πρὸς τιμωρίαν ἠξίουν."},{"number":91,"text":"καὶ οἱ μὲν ἄλλοι πάντες ἤνεγκαν τὰς ψήφους κατʼ αὐτοῦ οἳ καὶ ἀπέγνωσαν τῶν πρεσβυτέρων, οἱ δὲ σοφῆς ὄντες διανοίας ἀπέλυσαν τὸν προφήτην ἀπὸ τῆς αὐλῆς καὶ τοῖς ἄλλοις συνεβούλευσαν μηδὲν διαθεῖναι κακὸν τὸν Ἱερεμίαν."},{"number":92,"text":"ἔλεγον γὰρ οὐ μόνον τοῦτον προλέγειν τῇ πόλει τὰ μέλλοντα, ἀλλὰ καὶ Μιχαίαν πρὸ αὐτοῦ ταῦτα κατηγγελκέναι καὶ πολλοὺς ἄλλους, ὧν οὐδεὶς ὑπὸ τῶν τότε βασιλέων οὐδὲν ἔπαθεν, ἀλλʼ ὡς προφήτης τοῦ θεοῦ τιμῆς ἔτυχε."},{"number":93,"text":"τούτοις καταπραΰναντες τὸ πλῆθος τοῖς λόγοις ἐρρύσαντο τῆς κατεψηφισμένης αὐτοῦ κολάσεως τὸν Ἱερεμίαν, ὃς ἁπάσας αὑτοῦ τὰς προφητείας συγγραψάμενος νηστεύοντος τοῦ δήμου καὶ ἐκκλησιάζοντος ἐν τῷ ἱερῷ μηνὶ ἐνάτῳ τοῦ πέμπτου ἔτους τῆς Ἰωακείμου βασιλείας ἀνέγνω τὴν βίβλον, ἣν περὶ τῶν μελλόντων συμβήσεσθαι τῇ πόλει καὶ τῷ ναῷ καὶ τοῖς ὄχλοις ἦν συντεταχώς."},{"number":94,"text":"ἀκούσαντες δʼ οἱ ἡγεμόνες λαμβάνουσι παρʼ αὐτοῦ τὸ βιβλίον καὶ κελεύουσιν αὐτόν τε καὶ τὸν γραμματέα Βαροῦχον ἐκποδὼν αὑτοὺς ποιῆσαι, μή τισι δῆλοι γένωνται, τὸ δὲ βιβλίον αὐτοὶ φέροντες τῷ βασιλεῖ διδόασιν. ὁ δὲ παρόντων αὐτῷ τῶν φίλων ἐκέλευσε τὸν αὑτοῦ γραμματέα λαβόντα ἀναγνῶναι."},{"number":95,"text":"ἀκούσας δὲ τῶν ἐν τῷ βιβλίῳ καὶ ὀργισθεὶς ὁ βασιλεὺς διέρρηξέ τε καὶ βαλὼν εἰς πῦρ ἠφάνισε, ζητηθέντας δὲ τόν τε Ἱερεμίαν καὶ τὸν γραμματέα Βαροῦχον ἐκέλευσεν ἀχθῆναι πρὸς αὐτὸν κολασθησομένους. οὗτοι μὲν οὖν διαφεύγουσιν αὐτοῦ τὴν ὀργήν."},{"number":96,"text":"Μετʼ οὐ πολὺν δὲ χρόνον στρατευόμενον ἐπʼ αὐτὸν τὸν τῶν Βαβυλωνίων βασιλέα δέχεται κατὰ δέος τῶν προειρημένων ὑπὸ τοῦ προφήτου τούτου, οὐδὲν νομίζων πείσεσθαι δεινὸν μηδὲ ἀποκλείσας μηδὲ πολεμήσας,"},{"number":97,"text":"ἀπελθὼν δʼ εἰς αὐτὸν ὁ Βαβυλώνιος οὐκ ἐφύλαξε τὰς πίστεις, ἀλλὰ τοὺς ἀκμαιοτάτους καὶ κάλλει διαφέροντας τῶν Ἱεροσολυμιτῶν ἀπέκτεινε μετὰ τοῦ βασιλέως Ἰωακείμου, ὃν ἄταφον ἐκέλευσε ῥιφῆναι πρὸ τῶν τειχῶν· τὸν δὲ υἱὸν αὐτοῦ Ἰωάκειμον κατέστησε βασιλέα τῆς χώρας καὶ τῆς πόλεως."},{"number":98,"text":"τοὺς δʼ ἐν ἀξιώματι τρισχιλίους ὄντας τὸν ἀριθμὸν αὐτοῦ αἰχμαλώτους λαβὼν ἀπήγαγεν εἰς τὴν Βαβυλῶνα· ἐν δὲ τούτοις ἦν καὶ ὁ προφήτης Ἰεζεκίηλος παῖς ὤν. καὶ τέλος μὲν τοιοῦτον Ἰωάκειμον τὸν βασιλέα κατέσχε βιώσαντα μὲν ἓξ καὶ τριάκοντα ἔτη βασιλεύσαντα δὲ τούτων ἕνδεκα, ὁ δὲ διαδεξάμενος αὐτοῦ τὴν βασιλείαν Ἰωάκειμος, ἐκ μητρὸς μὲν Νοόστης ὄνομα πολίτιδος δέ, ἐβασίλευσε μῆνας τρεῖς ἡμέρας δέκα."}],"7":[{"number":99,"text":"Τὸν δὲ τῶν Βαβυλωνίων βασιλέα δόντα τὴν βασιλείαν Ἰωακείμῳ παραχρῆμα ἔλαβε δέος· ἔδεισε γάρ, μὴ μνησικακήσας αὐτῷ τῆς τοῦ πατρὸς ἀναιρέσεως ἀποστήσῃ τὴν χώραν αὐτοῦ· πέμψας τοιγαροῦν δύναμιν ἐπολιόρκει τὸν Ἰωάκειμον ἐν τοῖς Ἱεροσολύμοις."},{"number":100,"text":"ὁ δὲ φύσει χρηστὸς ὢν καὶ δίκαιος οὐκ ἠξίου τὴν πόλιν κινδυνεύουσαν διʼ αὐτὸν περιορᾶν, ἀλλʼ ἀπάρας τὴν μητέρα καὶ τοὺς συγγενεῖς παραδίδωσι τοῖς πεμφθεῖσιν ὑπὸ τοῦ Βαβυλωνίου στρατηγοῖς ὅρκους παρʼ αὐτῶν λαβὼν ὑπὲρ τοῦ μηδὲν μήτʼ αὐτοὺς παθεῖν μήτε τὴν πόλιν."},{"number":101,"text":"οἷς οὐδʼ ἐνιαυτὸν ἡ πίστις ἔμεινεν· οὐ γὰρ ἐφύλαξεν αὐτὴν ὁ τῶν Βαβυλωνίων βασιλεύς, ἀλλὰ τοῖς στρατηγοῖς ἐπέστειλεν ἅπαντας τοὺς ἐν τῇ πόλει λαβόντας αἰχμαλώτους νέους τὴν ἡλικίαν καὶ τεχνίτας δεδεμένους ἄγειν πρὸς αὑτόν, ἦσαν δὲ οὗτοι πάντες εἰς μυρίους ὀκτακοσίους τριακονταδύο, καὶ τὸν Ἰωάκειμον μετὰ τῆς μητρὸς καὶ τῶν φίλων."},{"number":102,"text":"τούτους δὴ κομισθέντας πρὸς αὑτὸν εἶχεν ἐν φυλακῇ· τὸν δὲ θεῖον τοῦ Ἰωακείμου Σαχχίαν ἀπέδειξε βασιλέα ὅρκους παρʼ αὐτοῦ λαβών, ἦ μὴν φυλάξειν αὐτῷ τὴν χώραν καὶ μηδὲν νεωτερίσειν μηδὲ τοῖς Αἰγυπτίοις εὐνοήσειν."},{"number":103,"text":"Σαχχίας δʼ ἦν ἐτῶν μὲν εἴκοσι καὶ ἑνός, ὅτε τὴν ἀρχὴν παρέλαβεν, ὁμομήτριος μὲν Ἰωακείμου τοῦ ἀδελφοῦ αὐτοῦ, τῶν δὲ δικαίων καὶ τοῦ δέοντος ὑπερόπτης· καὶ γὰρ τὴν ἡλικίαν ἦσαν ἀσεβεῖς περὶ αὐτὸν καὶ ὁ πᾶς ὄχλος ἐπʼ ἐξουσίας ὕβριζεν ἃ ἤθελεν·"},{"number":104,"text":"διὸ καὶ ὁ προφήτης Ἱερεμίας πρὸς αὐτὸν ἐλθὼν πολλάκις ἐμαρτύρατο κελεύων τὰς μὲν ἄλλας ἀσεβείας καὶ παρανομίας καταλιπεῖν, προνοεῖν δὲ τοῦ δικαίου, καὶ μήτε τοῖς ἡγεμόσι τῷ εἶναι ἐν αὐτοῖς πονηροὺς προσανέχειν μήτε τοῖς ψευδοπροφήταις ἀπατῶσιν αὐτὸν πεπιστευκέναι, ὡς οὐκέτι πολεμήσει τὴν πόλιν ὁ Βαβυλώνιος καὶ ὡς Αἰγύπτιοι στρατεύσουσιν ἐπʼ αὐτὸν καὶ νικήσουσι· ταῦτα γὰρ οὐκ ἀληθῆ λέγειν οὐδʼ οὕτως ὀφείλοντα γενέσθαι."},{"number":105,"text":"ὁ δὲ Σαχχίας ἐφʼ ὅσον μὲν ἤκουσε τοῦ προφήτου ταῦτα λέγοντος ἐπείθετο αὐτῷ καὶ συνῄδει πᾶσιν ὡς ἀληθεύουσι καὶ συμφέρον αὐτῷ πεπιστευκέναι· διέφθειρον δὲ πάλιν αὐτὸν οἱ φίλοι καὶ διῆγον ἀπὸ τῶν τοῦ προφήτου πρὸς ἅπερ ἤθελον."},{"number":106,"text":"προεφήτευσε δὲ καὶ Ἰεζεκίηλος ἐν Βαβυλῶνι τὰς μελλούσας τῷ λαῷ συμφορὰς καὶ γράψας ταῦτα ἔπεμψεν εἰς Ἱεροσόλυμα. ταῖς δὲ προφητείαις αὐτῶν Σαχχίας ἠπίστησεν ἐκ τοιαύτης αἰτίας· τὰ μὲν ἄλλα πάντα συμφωνοῦντα εἰπεῖν συνέβη, ὡς ἥ τε πόλις ἁλώσεται καὶ Σαχχίας αὐτὸς αἰχμάλωτος ἔσται, διεφώνησε δὲ Ἰεζεκίηλος εἰπὼν οὐκ ὄψεσθαι Βαβυλῶνα τὸν Σαχχίαν τοῦ Ἱερεμίου φάσκοντος αὐτῷ, ὅτι δεδεμένον αὐτὸν ὁ Βαβυλώνιος ἄξει βασιλεύς."},{"number":107,"text":"καὶ διὰ τὸ μὴ ταὐτὸν αὐτοὺς ἑκατέρους λέγειν καὶ περὶ ὧν συμφωνεῖν ἐδόκουν ὡς οὐδʼ ἐκεῖνα ἀληθῆ λέγουσι καταγνούς· καίτοι πάντʼ αὐτῷ κατὰ τὰς προφητείας ἀπήντησεν, ἅπερ εὐκαιρότερον δηλώσομεν."},{"number":108,"text":"Τὴν συμμαχίαν δὲ τὴν πρὸς τοὺς Βαβυλωνίους ἐπʼ ἔτη ὀκτὼ κατασχὼν διέλυσε τὰς πρὸς αὐτοὺς πίστεις καὶ τοῖς Αἰγυπτίοις προστίθεται καταλύσειν τοὺς Βαβυλωνίους ἐλπίσας, αἳ μετʼ ἐκείνων ἐγένοντο."},{"number":109,"text":"μαθὼν δὲ τοῦτο ὁ τῶν Βαβυλωνίων βασιλεὺς ἐστράτευσεν ἐπʼ αὐτὸν καὶ τὴν χώραν κακώσας αὐτοῦ καὶ τὰ φρούρια λαβὼν ἐπʼ αὐτὴν ἧκε τὴν τῶν Ἱεροσολυμιτῶν πόλιν πολιορκήσων αὐτήν."},{"number":110,"text":"ὁ δʼ Αἰγύπτιος ἀκούσας ἐν οἷς ἐστιν ὁ σύμμαχος αὐτοῦ Σαχχίας ἀναλαβὼν πολλὴν δύναμιν ἧκεν εἰς τὴν Ἰουδαίαν ὡς λύσων τὴν πολιορκίαν. ὁ δὲ Βαβυλώνιος ἀφίσταται τῶν Ἱεροσολύμων, ἀπαντήσας δὲ τοῖς Αἰγυπτίοις καὶ συμβαλὼν αὐτοῖς τῇ μάχῃ νικᾷ καὶ τρεψάμενος αὐτοὺς εἰς φυγὴν ἐξ ὅλης διώκει τῆς Συρίας."},{"number":111,"text":"ὡς δʼ ἀνεχώρησεν ὁ τῶν Βαβυλωνίων βασιλεὺς ἀπὸ τῶν Ἱεροσολύμων, ἐξηπάτησαν οἱ ψευδοπροφῆται τὸν Σαχχίαν λέγοντες οὔτε τὸν Βαβυλώνιον ἔτι αὐτὸν πολεμήσειν καὶ τοὺς ὁμοφύλους, οὓς ἀναστήσειεν ἐκ τῆς οἰκείας εἰς τὴν Βαβυλῶνα, μετὰ πάντων ἀνήξειν τῶν τοῦ ναοῦ σκευῶν, ὧν ἐσύλησεν ὁ βασιλεὺς ἐκ τοῦ νεώ."},{"number":112,"text":"τἀναντία δὲ τούτων καὶ ἀληθῆ προελθὼν Ἱερεμίας προεφήτευσεν, ὡς ποιοῦσι μὲν κακῶς καὶ ἐξαπατῶσι τὸν βασιλέα, παρὰ δὲ τῶν Αἰγυπτίων οὐδὲν αὐτοῖς ἐστιν ὄφελος, ἀλλὰ νικήσας αὐτοὺς ὁ Βαβυλώνιος ἐπιστρατεύσειν εἰς τὰ Ἱεροσόλυμα μέλλει, καὶ πολιορκήσει τε καὶ τῷ λιμῷ διαφθερεῖ τὸν δῆμον, καὶ τοὺς περιλειφθέντας αἰχμαλώτους ἄξει, καὶ τὰς οὐσίας διαρπάσει, καὶ τὸν ἐν τῷ ναῷ πλοῦτον ἐκφορήσας ἔτι καὶ αὐτὸν ἐμπρήσει καὶ κατασκάψει τὴν πόλιν, καὶ δουλεύσομεν αὐτῷ καὶ τοῖς ἐγγόνοις αὐτοῦ ἐπʼ ἔτη ἑβδομήκοντα."},{"number":113,"text":"παύσουσι δʼ ἡμᾶς τότε τῆς ὑπʼ αὐτοῖς δουλείας Πέρσαι τε καὶ Μῆδοι καταλύσαντες Βαβυλωνίους, ἀφʼ ὧν εἰς τήνδε ἀπολυθέντες οἰκοδομήσομεν τὸν ναὸν πάλιν καὶ τὰ Ἱεροσόλυμα καταστήσομεν."},{"number":114,"text":"ταῦτα λέγων ὁ Ἱερεμίας ὑπὸ μὲν τῶν πλειόνων ἐπιστεύετο, οἱ δὲ ἡγεμόνες καὶ οἱ ἀσεβεῖς ὡς ἐξεστηκότα τῶν φρενῶν αὐτὸν οὕτως ἐξεφαύλιζον. δόξαν δὲ αὐτῷ που καὶ εἰς τὴν πατρίδα παραγενέσθαι λεγομένην Ἀναθὼθ σταδίους δʼ ἀπέχουσαν τῶν Ἱεροσολύμων εἴκοσι, συντυχὼν κατὰ τὴν ὁδὸν τῶν ἀρχόντων τις συλλαβὼν κατέσχε συκοφαντῶν ὡς πρὸς τοὺς Βαβυλωνίους αὐτομολοῦντα."},{"number":115,"text":"ὁ δὲ ψευδῆ μὲν ἐκεῖνον ἔλεγεν αἰτίαν ἐπιφέρειν αὐτῷ, βαδίζειν δʼ αὑτὸν ἔφασκεν εἰς τὴν πατρίδα. ὁ δʼ οὐ πεισθεὶς ἀλλὰ λαβὼν αὐτὸν ἤγαγεν εἰς δίκην πρὸς τοὺς ἄρχοντας, ὑφʼ ὧν πᾶσαν αἰκίαν καὶ βασάνους ὑπομείνας ἐφυλάττετο πρὸς τιμωρίαν. καὶ χρόνον μέν τινα διῆγεν οὕτως ἀδίκως πάσχων τὰ προειρημένα."},{"number":116,"text":"Ἔτει δʼ ἐνάτῳ τῆς Σαχχίου βασιλείας καὶ ἡμέρᾳ δεκάτῃ τοῦ δεκάτου μηνὸς στρατεύει τὸ δεύτερον ὁ τῶν Βαβυλωνίων βασιλεὺς ἐπὶ τὰ Ἱεροσόλυμα καὶ προσκαθίσας αὐτῇ μῆνας ὀκτωκαίδεκα μετὰ πάσης πολιορκεῖ φιλοτιμίας. συνεπέθετο δὲ εἰς ταὐτὸ πολιορκουμένοις τοῖς Ἱεροσολύμοις δύο τὰ μέγιστα τῶν παθῶν, λιμὸς καὶ φθορὰ λοιμικὴ ἐνσκήψαντα σφοδρῶς."},{"number":117,"text":"ἐν δὲ τῇ εἱρκτῇ τυγχάνων ὁ προφήτης Ἱερεμίας οὐχ ἡσύχαζεν, ἀλλʼ ἐκεκράγει καὶ ἐκήρυσσε παραινῶν τῷ πλήθει δέξασθαι τὸν Βαβυλώνιον ἀνοίξαντας τὰς πύλας· σωθήσεσθαι γὰρ αὐτοὺς πανοικὶ τοῦτο πράξαντας, εἰ δὲ μή, διαφθαρήσεσθαι."},{"number":118,"text":"προύλεγεν δʼ ὡς εἰ μὲν ἐπιμένοι τις ἐν τῇ πόλει πάντως ἀπολεῖται θατέρῳ ἢ λιμῷ δαπανηθεὶς ἢ σιδήρῳ τῷ τῶν πολεμίων, εἰ δὲ φύγοι πρὸς τοὺς πολεμίους, διαδράσεται τὸν θάνατον."},{"number":119,"text":"οὐδὲ ἐν αὐτοῖς δὲ ὄντες τοῖς δεινοῖς ἐπίστευον οἱ ταῦτʼ ἀκούοντες τῶν ἡγεμόνων, ἀλλὰ μετʼ ὀργῆς ἀπήγγελλον ἐλθόντες πρὸς τὸν βασιλέα, καὶ κατηγοροῦντες κατῃτιῶντο κτεῖναι τὸν προφήτην ὡς μεμηνότα καὶ τὰς ψυχὰς αὐτῶν προκατακλῶντα καὶ ταῖς τῶν χειρόνων καταγγελίαις τὸ πρόθυμον ἐκλύοντα τοῦ πλήθους· ἕτοιμον γὰρ εἶναι αὐτὸ ὑπὲρ αὐτοῦ καὶ τῆς πατρίδος κινδυνεῦσαι, ὁ δὲ παρῄνει πρὸς τοὺς πολεμίους φεύγειν ἁλώσεσθαι λέγων τὴν πόλιν καὶ πάντας ἀπολεῖσθαι."},{"number":120,"text":"Ὁ δὲ βασιλεὺς αὐτὸς μὲν ὑπὸ χρηστότητος καὶ δικαιοσύνης οὐδὲν ἰδίᾳ παρωξύνθη, ἵνα δὲ μὴ τοῖς ἡγεμόσιν ἀπεχθάνηται παρὰ τοιοῦτον καιρὸν ἀντιπράττων αὐτῶν τῇ προαιρέσει, τὸν προφήτην ἐφῆκεν αὐτοῖς ποιεῖν ὅτι ἂν θέλωσιν."},{"number":121,"text":"ὡς δὲ τοῦτο ἐφέντος αὐτοῖς τοῦ βασιλέως εὐθὺς εἰς τὴν εἱρκτὴν εἰσελθόντες καὶ παραλαβόντες αὐτὸν εἴς τινα λάκκον βορβόρου πλήρη καθίμησαν, ὅπως ἰδίῳ θανάτῳ πνιγεὶς ἀποθάνῃ. ὁ δὲ πρὸ τοῦ αὐχένος ὑπὸ τοῦ πηλοῦ περισχεθεὶς ἐν τούτοις ἦν."},{"number":122,"text":"τῶν δʼ οἰκετῶν τις τοῦ βασιλέως ἐν τιμῇ τυγχάνων Αἰθίοψ τὸ γένος τὸ περὶ τὸν προφήτην πάθος ἀπήγγειλε τῷ βασιλεῖ φάσκων οὐκ ὀρθῶς ταῦτα τοὺς φίλους καὶ τοὺς ἡγεμόνας αὐτοῦ πεποιηκέναι καταποντίσαντας εἰς βόρβορον τὸν προφήτην καὶ τοῦ διὰ τῶν δεσμῶν θανάτου πικρότερον οὕτως ἐσόμενον ἐπινοήσαντας κατʼ αὐτοῦ."},{"number":123,"text":"ταῦτʼ ἀκούσας ὁ βασιλεὺς καὶ μετανοήσας ἐν τῷ παραδοῦναι τὸν προφήτην τοῖς ἡγεμόσιν ἐκέλευσε τὸν Αἰθίοπα τριάκοντα τῶν βασιλικῶν παραλαβόντα καὶ σχοίνους καὶ πᾶν ὃ πρὸς τὴν τοῦ προφήτου σωτηρίαν ἐπινοεῖν χρήσιμον μετὰ σπουδῆς ἀνελκύσαι τὸν Ἱερεμίαν. ὁ δʼ Αἰθίοψ παραλαβὼν οὓς ἐπετάγη ἀνέσπασεν ἐκ τοῦ βορβόρου τὸν προφήτην καὶ διαφῆκεν ἀφύλακτον."},{"number":124,"text":"Μεταπεμψαμένου δʼ αὐτὸν κρύφα τοῦ βασιλέως καὶ τί δύναται φράζειν αὐτῷ παρὰ τοῦ θεοῦ καὶ πρὸς τὰ παρόντα σημαίνειν ἐρομένου, ἔχειν μὲν ἔλεγεν, οὐ πιστευθήσεσθαι δʼ εἰπὼν οὐδὲ παραινέσας ἀκουσθήσεσθαι, ἀλλʼ ὡς δὴ μέγα κακόν τι εἰργασμένον ἀπολέσαι διέγνωσαν οἱ σοὶ φίλοι , φησί, καὶ ποῦ νῦν εἰσιν οἱ τὸν Βαβυλώνιον οὐκέθʼ ἡμῖν ἐπιστρατεύσειν φάσκοντες καὶ ἀπατῶντες ὑμᾶς; εὐλαβοῦμαι δὲ νῦν γε τὴν ἀλήθειαν εἰπεῖν, μή με κατακρίνῃς θανάτῳ. τοῦ δὲ βασιλέως ὅρκους αὐτῷ δόντος,"},{"number":125,"text":"ὡς οὔτε αὐτὸς αὐτὸν ἀναιρήσει οὔτε τοῖς ἡγεμόσιν ἐκδώσει, θαρσήσας τῇ δεδομένῃ πίστει συνεβούλευσεν αὐτῷ παραδοῦναι τὴν πόλιν τοῖς Βαβυλωνίοις·"},{"number":126,"text":"ταῦτα δὲ αὐτῷ τὸν θεὸν διʼ αὐτοῦ προφητεύειν ἔλεγεν, εἴ γε βούλεται σώζεσθαι καὶ τὸν ἐφεστῶτα κίνδυνον διαφυγεῖν καὶ μήτε τὴν πόλιν εἰς ἔδαφος πεσεῖν, μήτε τὸν ναὸν ἐμπρησθέντα γὰρ αὐτὸν τούτων παραίτιον ἔσεσθαι τῶν κακῶν τοῖς πολίταις καὶ αὑτῷ πανοικὶ τῆς συμφορᾶς."},{"number":127,"text":"ὁ δὲ ταῦτʼ ἀκούσας βούλεσθαι μὲν αὐτὸς ἔφη ποιεῖν ἃ παραινεῖ καὶ λέγει συνοίσειν αὐτῷ γινόμενα, δεδιέναι δὲ τοὺς αὐτομολήσαντας τῶν ὁμοφύλων πρὸς τοὺς Βαβυλωνίους, μὴ διαβληθεὶς ὑπʼ αὐτῶν τῷ βασιλεῖ κολασθῇ."},{"number":128,"text":"παρεθάρσυνε δὲ αὐτὸν ὁ προφήτης καὶ μάτην ὑπονοεῖν τὴν τιμωρίαν ἔλεγεν· οὐδενὸς γὰρ κακοῦ πειραθήσεσθαι παραδόντα τοῖς Βαβυλωνίοις οὔτʼ αὐτὸν οὔτε τὰ τέκνα οὔτε τὰς γυναῖκας, μενεῖν δὲ καὶ τὸν ναὸν ἀπαθῆ."},{"number":129,"text":"καὶ τὸν μὲν Ἱερεμίαν ταῦτʼ εἰπόντα ὁ βασιλεὺς ἀπέλυσεν προστάξας αὐτῷ πρὸς μηδένα τῶν πολιτῶν ἐξενεγκεῖν τὰ δόξαντʼ αὐτοῖς, ἀλλὰ μηδὲ τοῖς ἡγεμόσιν, εἰ μαθόντες αὐτὸν ὑπʼ αὐτοῦ μετάπεμπτον γεγονέναι πυνθάνονται τί κληθεὶς εἴποι πρὸς αὐτόν, φράζειν τι τούτων, ἀλλὰ σκήπτεσθαι πρὸς αὐτούς, ὅτι δεηθείη μὴ ἐν δεσμῷ τυγχάνειν καὶ φυλακῇ."},{"number":130,"text":"καὶ δὴ τοῦτο πρὸς αὐτοὺς ἔλεγεν· ἐπυνθάνοντο γὰρ ἐλθόντες πρὸς τὸν προφήτην, τί περὶ αὐτῶν ἀφίκοιτο πρὸς τὸν βασιλέα σκήπτεσθαι. ταῦτα μὲν οὕτως ἐλέχθη."}],"8":[{"number":131,"text":"Τῆς δὲ πολιορκίας τῶν Ἱεροσολύμων ὁ Βαβυλώνιος ἐντεταμένως σφόδρα καὶ προθύμως εἴχετο· πύργους τε γὰρ μεγάλων οἰκοδομήσας χωμάτων ἀπʼ αὐτῶν ἀνεῖργε τοὺς τοῖς τείχεσιν ἐφεστῶτας, καὶ πολλὰ περὶ τὸν κύκλον ὅλον ἤγειρε χώματα τοῖς τείχεσι τὸ ὕψος ἴσα."},{"number":132,"text":"καρτερῶς δὲ καὶ προθύμως ἔφερον οἱ ἐντὸς τὴν πολιορκίαν· ἔκαμνον γὰρ οὔτε πρὸς τὸν λιμὸν οὔτε πρὸς τὴν νόσον τὴν λοιμικήν, ἀλλὰ καίπερ ἔνδον ὑπὸ τούτων ἐλαυνόμενοι τῶν παθῶν τὰς ψυχὰς ἔρρωντο πρὸς τὸν πόλεμον, μήτε πρὸς τὰς ἐπινοίας τῶν ἐχθρῶν καὶ τὰ μηχανήματα καταπληττόμενοι, ἀλλʼ ἀντιμηχανήματα πρὸς πάντα τὰ παρʼ ἐκείνων ἀντεπινοοῦντες·"},{"number":133,"text":"ὡς εἶναι τὸν ὅλον ἀγῶνα καὶ τοῖς Βαβυλωνίοις καὶ τοῖς Ἱεροσολυμίταις τῆς ὀξύτητος καὶ συνέσεως, τῶν μὲν πλέον ἐν ταύτῃ δυνηθῆναι τὴν ἀναίρεσιν οἰομένων εἶναι τῆς πόλεως, τῶν δὲ τὴν σωτηρίαν ἐν οὐκ ἄλλῳ τιθεμένων ἢ ἐν τῷ μὴ καμεῖν μηδʼ ἀπειπεῖν ἀντεφευρίσκοντας οἷς μάταια τὰ τῶν ἐχθρῶν ἀπελεγχθήσεται μηχανήματα."},{"number":134,"text":"καὶ ταῦθʼ ὑπέμειναν ἐπὶ μῆνας ὀκτωκαίδεκα ἕως οὗ διεφθάρησαν ὑπὸ τοῦ λιμοῦ καὶ τῶν βελῶν, ἅπερ ἀπὸ τῶν πύργων εἰς αὐτοὺς ἠκόντιζον οἱ πολέμιοι."},{"number":135,"text":"Ἡιρέθη δʼ ἡ πόλις ἑνδεκάτῳ ἔτει τῆς Σαχχίου βασιλείας τοῦ τετάρτου μηνὸς τῇ ἐνάτῃ ἡμέρᾳ. εἷλον δʼ οὖν οἱ ἡγεμόνες τῶν Βαβυλωνίων, οἷς ἐπίστευσε τὴν πολιορκίαν ὁ Ναβουχοδονόσορος· αὐτὸς γὰρ ἐν Ἀραβαθᾶ διέτριβε πόλει. τὰ δὲ τῶν ἡγεμόνων ὀνόματα, εἴ τις ἐπιζητήσειε γνῶναι, οἵτινες τὰ Ἱεροσόλυμα πορθήσαντες ὑπέταξαν, ἦν Ῥεγάλσαρος, Ἀρέμαντος, Σεμέγαρος, Ναβώσαρις, Ἀχαράμψαρις."},{"number":136,"text":"ἁλούσης δὲ τῆς πόλεως περὶ μέσην νύκτα καὶ τῶν ἡγεμόνων τῶν πολεμίων εἰσελθόντων εἰς τὸ ἱερὸν γνοὺς ὁ Σαχχίας ὁ βασιλεύς, παραλαβὼν τὰς γυναῖκας καὶ τὰ τέκνα καὶ τοὺς ἡγεμόνας καὶ τοὺς φίλους φεύγει μετʼ αὐτῶν ἐκ τῆς πόλεως διὰ τῆς καρτερᾶς φάραγγος καὶ διὰ τῆς ἐρήμου."},{"number":137,"text":"φρασάντων δὲ τοῦτό τινων αὐτομόλων τοῖς Βαβυλωνίοις ὑπὸ τὸν ὄρθρον ὥρμησαν διώκειν αὐτόν, καταλαβόντες δὲ οὐκ ἄπωθεν Ἱεριχοῦντος ἐκυκλώσαντο αὐτόν· οἱ δὲ φίλοι καὶ οἱ ἡγεμόνες οἱ συμφυγόντες τῷ Σαχχίᾳ ἐπεὶ τοὺς πολεμίους ἐγγὺς ὄντας εἶδον, καταλιπόντες αὐτὸν διεσπάρησαν ἄλλος ἀλλαχοῦ καὶ σώζειν ἑαυτὸν ἕκαστος ἔγνω."},{"number":138,"text":"περιλειφθέντα τε αὐτὸν σὺν ὀλίγοις ζωγρήσαντες οἱ πολέμιοι μετὰ τῶν τέκνων καὶ τῶν γυναικῶν ἤγαγον πρὸς τὸν βασιλέα. παραγενόμενον δʼ αὐτὸν ὁ Ναβουχοδονόσαρος ἀσεβῆ καὶ παράσπονδον ἀποκαλεῖν ἤρξατο καὶ ἀμνήμονα τῶν πρόσω λόγων, οὓς ἐποιήσατο σώζειν αὐτῷ τὴν χώραν ὑποσχόμενος."},{"number":139,"text":"ὠνείδιζε δὲ καὶ ἀχαριστίαν παρʼ αὐτοῦ μὲν λαβόντι τὴν βασιλείαν, Ἰωακείμου γὰρ αὐτὴν οὖσαν ἀφελόμενον ἐκείνῳ δοῦναι, χρησαμένῳ δὲ τῇ δυνάμει κατὰ τοῦ παρασχόντος· ἀλλὰ μέγας, εἶπεν, ὁ θεός, ὃς μισήσας σου τὸν τρόπον ὑποχείριον ἡμῖν ἔθηκε."},{"number":140,"text":"χρησάμενος δὲ τούτοις πρὸς Σαχχίαν τοῖς λόγοις τοὺς υἱοὺς ἐκέλευσεν ἀνελεῖν καὶ τοὺς φίλους παραχρῆμα αὐτοῦ τε Σαχχίου καὶ τῶν ἄλλων αἰχμαλώτων βλεπόντων, ἔπειτα τοὺς ὀφθαλμοὺς ἐκκόψας τοῦ Σαχχίου δήσας ἤγαγεν εἰς Βαβυλῶνα."},{"number":141,"text":"καὶ ταῦτʼ αὐτῷ συνέβη, ἃ Ἱερεμίας τε καὶ Ἰεζεκίηλος προεφήτευσαν αὐτῷ, ὅτι συλληφθεὶς ἀχθήσεται πρὸς τὸν Βαβυλώνιον καὶ λαλήσει αὐτῷ κατὰ στόμα καὶ ὄψεται τοῖς ὀφθαλμοῖς τοὺς ὀφθαλμοὺς αὐτοῦ. καὶ ταῦτα μὲν Ἱερεμίας εἶπε, τυφλωθεὶς δὲ καὶ ἀχθεὶς εἰς Βαβυλῶνα ταύτην οὐκ εἶδε καθὼς Ἰεζεκίηλος προεῖπε."},{"number":142,"text":"Ταῦτα μὲν οὖν ἱκανῶς ἐμφανίσαι δυνάμενα τὴν τοῦ θεοῦ φύσιν τοῖς ἀγνοοῦσιν εἰρήκαμεν, ὅτι ποικίλη τέ ἐστι καὶ πολύτροπος καὶ καθʼ ὥραν ἀπαντᾷ τεταγμένως, ἅ τε δεῖ γενέσθαι προλέγει, τήν τε τῶν ἀνθρώπων ἄγνοιαν καὶ ἀπιστίαν, ὑφʼ ἧς οὐδὲν προϊδεῖν εἰάθησαν τῶν ἀποβησομένων, ἀφύλακτοι δὲ ταῖς συμφοραῖς παρεδόθησαν, ὡς ἀμήχανον αὐτοῖς εἶναι τὴν ἐξ αὐτῶν πεῖραν διαφυγεῖν."},{"number":143,"text":"Οἱ μὲν οὖν ἐκ τοῦ Δαυίδου γένους βασιλεύσαντες οὕτως κατέστρεψαν τὸν βίον, εἴκοσι μὲν καὶ εἷς γενόμενοι μέχρι τοῦ τελευταίου βασιλέως, ἔτη δὲ πάντες βασιλεύσαντες πεντακόσια καὶ δεκατέσσαρα καὶ μῆνας ἓξ καὶ ἡμέρας δέκα, ἐξ ὧν εἴκοσι τὴν ἀρχὴν κατέσχεν ὁ πρῶτος αὐτῶν βασιλεὺς Σαοῦλος οὐκ ἐκ τῆς αὐτῆς φυλῆς ὑπάρχων."},{"number":144,"text":"Ὁ δὲ Βαβυλώνιος πέμπει τὸν αὑτοῦ στρατηγὸν Ναβουζαρδάνην εἰς Ἱεροσόλυμα συλήσοντα τὸν ναόν, προστάξας ἅμα καὶ καταπρῆσαι αὐτόν τε καὶ τὰ βασίλεια τήν τε πόλιν εἰς ἔδαφος καθελεῖν καὶ τὸν λαὸν εἰς τὴν Βαβυλωνίαν μεταστῆσαι."},{"number":145,"text":"ὃς γενόμενος ἐν τοῖς Ἱεροσολύμοις ἑνδεκάτῳ ἔτει τῆς Σαχχίου βασιλείας συλᾷ τε τὸν ναὸν καὶ βαστάζει τὰ σκεύη τοῦ θεοῦ χρυσᾶ τε καὶ ἀργυρᾶ καὶ δὴ καὶ τὸν μέγαν λουτῆρα, ὃν Σολόμων ἀνέθηκεν, ἔτι γε μὴν τοὺς στύλους τοὺς χαλκοῦς καὶ τὰς κεφαλὰς αὐτῶν τάς τε χρυσᾶς τραπέζας καὶ τὰς λυχνίας."},{"number":146,"text":"βαστάσας δὴ ταῦτα ἀνῆψε τὸν ναὸν μηνὶ πέμπτῳ τῇ νουμηνίᾳ ἑνδεκάτῳ ἔτει τῆς Σαχχίου βασιλείας, ὀκτωκαιδεκάτῳ δὲ τῆς Ναβουχοδονοσόρου· ἐνέπρησε δὲ καὶ τὰ βασίλεια καὶ τὴν πόλιν κατέστρεψεν."},{"number":147,"text":"ἐνεπρήσθη δὲ ὁ ναὸς μετὰ τετρακόσια ἔτη καὶ ἑβδομήκοντα καὶ μῆνας ἓξ καὶ δέκα ἡμέρας, ἀφʼ οὗ κατεσκευάσθη· τῇ δʼ ἐξ Αἰγύπτου μεταναστάσει τοῦ λαοῦ τότε ἦν ἔτη χίλια ἑξηκονταδύο μῆνες ἓξ ἡμέραι δέκα· τῷ δὲ κατακλυσμῷ μέχρι τῆς τοῦ ναοῦ πορθήσεως χρόνος ἦν ὁ πᾶς ἐτῶν χιλίων ἐνακοσίων πεντηκονταεπτὰ μηνῶν ἓξ ἡμερῶν δέκα·"},{"number":148,"text":"ἐξ οὗ δʼ ἐγεννήθη ὁ Ἄδαμος μέχρι τῶν περὶ τὸν ναὸν συμβάντων ἔτη ἐστὶ τετρακισχίλια πεντακόσια δεκατρία μῆνες ἓξ ἡμέραι δέκα. τοσοῦτον μὲν οὖν τὸ τούτων τῶν ἐτῶν πλῆθος· ὅσα γε μὴν ἐπράχθη καθʼ ἕκαστον τῶν συμβεβηκότων δεδηλώκαμεν."},{"number":149,"text":"ὁ δὲ στρατηγὸς τοῦ Βαβυλωνίων βασιλέως κατασκάψας τὰ Ἱεροσόλυμα καὶ τὸν λαὸν μεταναστήσας ἔλαβεν αἰχμαλώτους τὸν ἀρχιερέα Σεβαῖον καὶ τὸν μετʼ αὐτὸν ἱερέα Σεφενίαν καὶ τοὺς φυλάσσοντας τὸ ἱερὸν ἡγεμόνας, τρεῖς δὲ ἦσαν οὗτοι, καὶ τὸν ἐπὶ τῶν ὁπλιτῶν εὐνοῦχον καὶ τοὺς φίλους τοῦ Σαχχίου ἑπτὰ καὶ τὸν γραμματέα αὐτοῦ καὶ ἄλλους ἡγεμόνας ἑξήκοντα, οὓς ἅπαντας μεθʼ ὧν ἐσύλησε σκευῶν ἐκόμισε πρὸς τὸν βασιλέα εἰς Σαλάβαθα πόλιν τῆς Συρίας."},{"number":150,"text":"ὁ δὲ βασιλεὺς τοῦ μὲν ἀρχιερέως καὶ τῶν ἡγεμόνων ἐκέλευσεν ἐκεῖ τὰς κεφαλὰς ἀποτεμεῖν, αὐτὸς δὲ πάντας τοὺς αἰχμαλώτους καὶ τὸν Σαχχίαν εἰς Βαβυλῶνα δέσμιον ἐπήγετο καὶ Ἰωσάδακον τὸν ἀρχιερέα ὄντα υἱὸν Σαραία τοῦ ἀρχιερέως, ὃν ἀπέκτεινεν ὁ Βαβυλώνιος ἐν Ἀριβαθᾶ πόλει τῆς Συρίας, ὡς καὶ πρότερον ἡμῖν δεδήλωται."},{"number":151,"text":"Ἐπεὶ δὲ τὸ γένος διεξήλθομεν τὸ τῶν βασιλέων καὶ τίνες ἦσαν δεδηλώκαμεν καὶ τοὺς χρόνους αὐτῶν, ἀναγκαῖον ἡγησάμην καὶ τῶν ἀρχιερέων εἰπεῖν τὰ ὀνόματα καὶ τίνες ἦσαν οἱ τὴν ἀρχιερωσύνην καταδείξαντες ἐπὶ τοῖς βασιλεῦσι."},{"number":152,"text":"πρῶτος μὲν οὖν Σάδωκος ἀρχιερεὺς ἐγένετο τοῦ ναοῦ, ὃν Σολόμων ᾠκοδόμησε· μετʼ αὐτὸν δʼ ὁ υἱὸς Ἀχιμᾶς διαδέχεται τὴν τιμὴν καὶ μετὰ Ἀχιμᾶν Ἀζαρίας, τούτου δὲ Ἰώραμος, τοῦ δὲ Ἰωράμου Ἴως, μετʼ αὐτὸν δὲ Ἀξιώραμος,"},{"number":153,"text":"τοῦ δὲ Ἀξιωράμου Φιδέας, τοῦ δὲ Φιδέα Σουδαίας, τοῦ δὲ Σουδαία Ἰουῆλος, τοῦ δὲ Ἰώθαμος, Ἰωθάμου δὲ Οὐρίας, Οὐρία δὲ Νηρίας, Νηρία δὲ Ὠδαίας, τοῦ δὲ Σαλοῦμος, Σαλούμου δὲ Ἐλκίας, Ἐλκία δʼ Ἄζαρος, τοῦ δὲ Ἰωσάδακος ὁ αἰχμαλωτισθεὶς εἰς Βαβυλῶνα. οὗτοι πάντες παῖς παρὰ πατρὸς διεδέξαντο τὴν ἀρχιερωσύνην."},{"number":154,"text":"Παραγενόμενος δʼ εἰς Βαβυλῶνα ὁ βασιλεὺς Σαχχίαν μὲν εἶχεν ἄχρις οὗ καὶ ἐτελεύτησεν ἐν εἱρκτῇ, θάψας δʼ αὐτὸν βασιλικῶς τὰ σκεύη τὰ ἐκ τοῦ Ἱεροσολύμων συληθέντα ναοῦ ἀνέθηκε τοῖς ἰδίοις θεοῖς, τὸν δὲ λαὸν κατῴκισεν ἐν τῇ Βαβυλωνίτιδι χώρᾳ, τὸν δὲ ἀρχιερέα ἀπέλυσε τῶν δεσμῶν."}],"9":[{"number":155,"text":"Ὁ δὲ στρατηγὸς Ναβουζαρδάνης αἰχμαλωτίσας τὸν τῶν Ἑβραίων λαὸν τοὺς πένητας καὶ αὐτομόλους ἐκεῖ κατέλιπεν ἀποδείξας αὐτῶν ἡγεμόνα Γαδαλίαν ὄνομʼ Ἀϊκάμου παῖδα τῶν εὖ γεγονότων ἐπιεικῆ καὶ δίκαιον, ἐπέταξε δʼ αὐτοῖς τὴν χώραν ἐργαζομένοις τῷ βασιλεῖ τελεῖν φόρον ὡρισμένον."},{"number":156,"text":"Ἱερεμίαν δὲ τὸν προφήτην λαβὼν ἐκ τῆς εἱρκτῆς ἔπειθεν εἰς Βαβυλῶνα σὺν αὐτῷ παραγενέσθαι· κεκελεῦσθαι γὰρ ὑπὸ τοῦ βασιλέως πάντʼ αὐτῷ χορηγεῖν· εἰ δὲ τοῦτο μὴ βούλεται, δηλοῦν αὐτῷ ποῦ μένειν διέγνωκεν, ἵνα τοῦτο ἐπισταλῇ τῷ βασιλεῖ."},{"number":157,"text":"ὁ δὲ προφήτης οὔθʼ ἕπεσθαι ἤθελεν οὔτʼ ἀλλαχόσε που μένειν, ἡδέως δʼ εἶχεν ἐπὶ τοῖς ἐρειπίοις τῆς πατρίδος καὶ τοῖς ταλαιπώροις αὐτῆς διαζῆσαι λειψάνοις. γνοὺς δʼ αὐτοῦ τὴν προαίρεσιν ὁ στρατηγός, τῷ Γαδαλίᾳ προστάξας, ὃν κατέλιπεν, αὐτίκα πᾶσαν αὐτοῦ ποιεῖσθαι πρόνοιαν καὶ χορηγίαν ὅσων ἂν δέηται δωρησάμενός τε αὐτὸν δωρεαῖς πολυτελέσιν ἀπέλυσεν."},{"number":158,"text":"καὶ Ἱερεμίας μὲν κατέμεινεν εἰς Δάναν ἐν πόλει τῆς χώρας Μοσφοθᾶ καλουμένῃ παρακαλέσας τὸν Ναβουζαρδάνην, ἵνʼ αὐτῷ συναπολύσῃ τὸν μαθητὴν Βαροῦχον Νήρου δὲ παῖδα ἐξ ἐπισήμου σφόδρα οἰκίας ὄντα καὶ τῇ πατρίῳ γλώττῃ διαφερόντως πεπαιδευμένον."},{"number":159,"text":"Ναβουζαρδάνης δὲ ταῦτα διαπραξάμενος ὥρμησεν εἰς Βαβυλῶνα. οἱ δὲ πολιορκουμένων Ἱεροσολύμων φυγόντες διασκεδασθέντες κατὰ τὴν χώραν, ἐπειδὴ τοὺς Βαβυλωνίους ἤκουσαν ἀνακεχωρηκότας καὶ λείψανά τινα καταλελοιπότας ἐν τῇ τῶν Ἱεροσολυμιτῶν γῇ καὶ τοὺς ταύτην ἐργασομένους, συλλεχθέντες πανταχόθεν ἧκον πρὸς τὸν Γαδαλίαν εἰς Μασαφθά."},{"number":160,"text":"ἡγεμόνες δʼ ἦσαν ἐν αὐτοῖς Ἰωάδης υἱὸς Καρίου καὶ Σερέας καὶ Ἰωαζανίας καὶ ἕτεροι πρὸς τούτοις, ἐκ δὲ τοῦ βασιλικοῦ γένους ἦν τις Ἰσμάηλος πονηρὸς ἀνὴρ καὶ δολιώτατος, ὃς πολιορκουμένων τῶν Ἱεροσολύμων ἔφυγε πρὸς τὸν Ἀμμανιτῶν βασιλέα Βααλεὶμ καὶ συνδιήγαγεν αὐτῷ τὸν χρόνον ἐκεῖνον."},{"number":161,"text":"τούτους τοίνυν γενομένους αὐτοῦ Γαδαλίας ἔπεισε μένειν αὐτίκα μηδὲν δεδιότας τοὺς Βαβυλωνίους· γεωργοῦντας γὰρ τὴν χώραν οὐδὲν πείσεσθαι δεινόν. ταῦτα ὀμνὺς αὐτοῖς διεβεβαιοῦτο καὶ προστάτην αὐτὸν ἔχειν λέγων, ὥστε εἴ τις ἐνοχλοίη τεύξεσθαι τῆς προθυμίας·"},{"number":162,"text":"καὶ συνεβούλευε κατοικεῖν εἰς ἣν ἕκαστος βούλεται πόλιν ἀποστέλλοντα μετὰ τῶν ἰδίων καὶ ἀνακτίζειν τὰ ἐδάφη καὶ κατοικεῖν· προεῖπέ τε παρασκευάζεσθαι αὐτοὺς ἕως ἔτι καιρός ἐστι σῖτον καὶ οἶνον καὶ ἔλαιον, ὅπως ἔχωσι διὰ τοῦ χειμῶνος τρέφεσθαι. ταῦτα διαλεχθεὶς πρὸς αὐτοὺς ἀπέλυσε διὰ τῆς χώρας εἰς ὃν ἕκαστος ἐβούλετο τόπον."},{"number":163,"text":"Διαδραμούσης δὲ φήμης εἰς τὰ περὶ τὴν Ἰουδαίαν ἔθνη, ὅτι τοὺς ἀπὸ τῆς φυγῆς παρʼ αὐτὸν ἐλθόντας Γαδαλίας ἐδέξατο φιλανθρώπως καὶ τὴν γῆν αὐτοῖς γεωργοῦσι κατοικεῖν ἐφῆκεν, ἐφʼ ᾧ τελεῖν φόρον τῷ Βαβυλωνίῳ, συνέδραμον αὐτοὶ πρὸς τὸν Γαδαλίαν καὶ τὴν χώραν κατῴκησαν."},{"number":164,"text":"κατανοήσαντες δὲ τὴν χώραν καὶ τὴν τοῦ Γαδαλίου χρηστότητα καὶ φιλανθρωπίαν Ἰωάννης καὶ οἱ μετʼ αὐτοῦ ἡγεμόνες ὑπερηγάπησαν αὐτὸν καὶ Βαάλιμον τὸν τῶν Ἀμμανιτῶν βασιλέα ἔλεγον πέμψαι Ἰσμάηλον ἀποκτενοῦντα αὐτὸν δόλῳ κρυφίως, ὅπως αὐτὸς ἄρχῃ τῶν Ἰσραηλιτῶν· εἶναι γὰρ αὐτὸν ἐκ τοῦ γένους τοῦ βασιλικοῦ."},{"number":165,"text":"ῥύσεσθαί γε μὴν ἔλεγον αὐτὸν τῆς ἐπιβουλῆς, ἂν αὐτοῖς ἐφῇ κτεῖναι τὸν Ἰσμάηλον, ὡς οὐδενὸς γνωσομένου· δεδιέναι γὰρ ἔφασκον, μὴ φονευθεὶς αὐτὸς ὑπʼ ἐκείνου παντελὴς ἀπώλεια γένηται τῶν ὑπολελειμμένων τῆς τῶν Ἰσραηλιτῶν ἰσχύος."},{"number":166,"text":"ὁ δʼ ἀπιστεῖν αὐτοῖς ὡμολόγει κατʼ ἀνδρὸς εὖ πεπονθότος ἐπιβουλὴν τοιαύτην ἐμφανίσασιν· οὐ γὰρ εἰκὸς εἶναι παρὰ τηλικαύτην ἐρημίαν ὧν ἔχρῃζε μὴ διαμαρτόντα οὕτως πονηρὸν εἰς τὸν εὐεργετήσαντα καὶ ἀνόσιον εὑρεθῆναι, ὡς τῷ μὲν τὸ ἀδίκημα τὸ μὴ ὑπʼ ἄλλων ἐπιβουλευόμενον σῶσαι, σπουδάζειν δὲ αὐτὸν αὐτόχειρα ζητεῖν αὐτοῦ γενέσθαι."},{"number":167,"text":"οὐ μὴν ἀλλʼ εἰ ταῦτʼ ἀληθῆ δεῖ δοκεῖν, ἄμεινον ἔφασκεν ἀποθανεῖν αὐτὸν ὑπʼ ἐκείνου μᾶλλον, ἢ καταφυγόντα πρὸς αὐτὸν ἄνθρωπον καὶ πιστεύσαντα τὴν ἰδίαν σωτηρίαν καὶ παρακαταθέμενον αὐτῷ διαφθεῖραι."},{"number":168,"text":"Καὶ ὁ μὲν Ἰωάννης καὶ οἱ σὺν αὐτῷ τῶν ἡγεμόνων μὴ δυνηθέντες πεῖσαι τὸν Γαδαλίαν ἀπῆλθον. χρόνου δὲ διελθόντος ἡμερῶν τριάκοντα παραγίνεται πρὸς Γαδαλίαν εἰς Μασφαθὰ πόλιν Ἰσμάηλος μετʼ ἀνδρῶν δέκα, οὓς λαμπρᾷ τραπέζῃ καὶ ξενίοις ὑποδεξάμενος εἰς μέθην προήχθη φιλοφρονούμενος τὸν Ἰσμάηλον καὶ τοὺς σὺν αὐτῷ."},{"number":169,"text":"θεασάμενος δʼ αὐτὸν οὕτως ἔχοντα καὶ βεβαπτισμένον εἰς ἀναισθησίαν καὶ ὕπνον ὑπὸ τῆς μέθης ὁ Ἰσμάηλος ἀναπηδήσας μετὰ τῶν δέκα φίλων ἀποσφάττει τὸν Γαδαλίαν καὶ τοὺς κατακειμένους σὺν αὐτῷ ἐν τῷ συμποσίῳ. καὶ μετὰ τὴν τούτων ἀναίρεσιν ἐξελθὼν νυκτὸς ἅπαντας φονεύει τοὺς ἐν τῇ πόλει Ἰουδαίους καὶ τοὺς ὑπὸ τῶν Βαβυλωνίων καταλειφθέντας ἐν αὐτῇ τῶν στρατιωτῶν."},{"number":170,"text":"τῇ δʼ ἐπιούσῃ μετὰ δώρων ἧκον πρὸς Γαδαλίαν τῶν ἀπὸ τῆς χώρας ὀγδοήκοντα μηδενὸς τὰ περὶ αὐτὸν ἐγνωκότος. ἰδὼν δὲ αὐτοὺς Ἰσμάηλος εἴσω τε αὐτοὺς καλεῖ ὡς πρὸς Γαδαλίαν, καὶ παρελθόντων ἀποκλείσας τὴν αὔλειον ἐφόνευσε καὶ τὰ σώματα αὐτῶν εἰς λάκκον τινὰ βαθύν, ὡς ἂν ἀφανῆ γένοιτο, κατεπόντισε."},{"number":171,"text":"διεσώθησαν δὲ τῶν ὀγδοήκοντα τούτων ἀνδρῶν οἳ μὴ πρότερον ἀναιρεθῆναι παρεκάλεσαν πρὶν ἢ τὰ κεκρυμμένα ἐν τοῖς ἀγροῖς αὐτῷ παραδῶσιν ἔπιπλά τε καὶ ἐσθῆτα καὶ σῖτον. ταῦτʼ ἀκούσας ἐφείσατο τῶν ἀνδρῶν τούτων Ἰσμάηλος·"},{"number":172,"text":"τὸν δʼ ἐν τῇ Μασφάθῃ λαὸν σὺν γυναιξὶ καὶ νηπίοις ᾐχμαλώτισεν, ἐν οἷς καὶ τοῦ βασιλέως Σαχχίου θυγατέρας, ἃς Ναβουζαρδάνης ὁ τῶν Βαβυλωνίων στρατηγὸς παρὰ Γαδαλίᾳ καταλελοίπει. ταῦτα διαπραξάμενος ἀφικνεῖται πρὸς τὸν Ἀμμανιτῶν βασιλέα."},{"number":173,"text":"Ἀκούσας δʼ ὁ Ἰωάννης καὶ οἱ σὺν αὐτῷ ἡγεμόνες τὰ ἐν τῇ Μασφαθῇ τὰ πεπραγμένα ὑπὸ Ἰσμαήλου καὶ τὸν Γαδαλίου θάνατον ἠγανάκτησαν, καὶ τοὺς ἰδίους ἕκαστος ὁπλίτας παραλαβὼν ὥρμησαν πολεμήσοντες τὸν Ἰσμάηλον καὶ καταλαμβάνουσιν αὐτὸν πρὸς τῇ πηγῇ ἐν Ἰβρῶνι."},{"number":174,"text":"οἱ δὲ αἰχμαλωτισθέντες ὑπὸ Ἰσμαήλου τὸν Ἰωάννην ἰδόντες καὶ τοὺς ἡγεμόνας εὐθύμως διετέθησαν βοήθειαν αὑτοῖς ἥκειν ὑπολαμβάνοντες, καὶ καταλιπόντες τὸν αἰχμαλωτίσαντα πρὸς Ἰωάννην ἀνεχώρησαν. Ἰσμάηλος μὲν οὖν μετʼ ἀνδρῶν ὀκτὼ φεύγει πρὸς τὸν τῶν Ἀμμανιτῶν βασιλέα."},{"number":175,"text":"ὁ δὲ Ἰωάννης παραλαβὼν οὓς ἀνέσωσεν ἐκ τῶν Ἰσμαήλου χειρῶν καὶ τοὺς εὐνούχους καὶ τὰς γυναῖκας καὶ τὰ νήπια εἴς τινα τόπον Μάνδρα λεγόμενον παραγίνεται. καὶ τὴν μὲν ἡμέραν ἐκείνην ἐπέμεινεν αὐτόθι, διεγνώκεισαν δʼ ἐκεῖθεν ἄραντες εἰς Αἴγυπτον ἐλθεῖν φοβούμενοι, μὴ κτείνωσιν αὐτοὺς οἱ Βαβυλώνιοι μείναντας ἐν τῇ χώρᾳ ὑπὲρ Γαδαλία τοῦ κατασταθέντος ὑπʼ αὐτῶν ἡγεμόνος ὀργισθέντες πεφονευμένου."},{"number":176,"text":"Ὄντων δʼ ἐπὶ ταύτης τῆς βουλῆς προσίασιν Ἱερεμίᾳ τῷ προφήτῃ Ἰωάννης ὁ τοῦ Καρίου καὶ οἱ ἡγεμόνες οἱ σὺν αὐτῷ παρακαλοῦντες δεηθῆναι τοῦ θεοῦ, ὅπως ἀμηχανοῦσιν αὐτοῖς περὶ τοῦ τί χρὴ ποιεῖν τοῦτʼ αὐτοῖς ὑποδείξῃ, ὀμόσαντες ποιήσειν ὅ τι ἂν αὐτοῖς Ἱερεμίας εἴπῃ."},{"number":177,"text":"ὑποσχομένου δὲ τοῦ προφήτου διακονήσειν αὐτοῖς πρὸς τὸν θεὸν συνέβη μετὰ δέκα ἡμέρας αὐτῷ φανέντα τὸν θεὸν εἰπεῖν δηλῶσαι Ἰωάννῃ καὶ τοῖς ἄλλοις ἡγεμόσι καὶ τῷ λαῷ παντί, ὅτι μένουσι μὲν αὐτοῖς ἐν ἐκείνῃ τῇ χώρᾳ παρέσται καὶ πρόνοιαν ἕξει καὶ τηρήσει παρὰ τῶν Βαβυλωνίων οὓς δεδίασιν ἀπαθεῖς, πορευομένους δὲ εἰς Αἴγυπτον ἀπολείψει καὶ ταὐτὰ διαθήσει ὀργισθείς, ἃ καὶ τοὺς ἀδελφοὺς αὑτῶν ἔμπροσθεν οἴδατε πεπονθότας."},{"number":178,"text":"ταῦτα εἰπὼν τῷ Ἰωάννῃ καὶ τῷ λαῷ τὸν θεὸν αὐτοῖς προλέγειν ὁ προφήτης οὐκ ἐπιστεύετο, ὡς κατὰ ἐντολὴν τὴν ἐκείνου μένειν αὐτοὺς ἐν τῇ χώρᾳ κελεύει, χαριζόμενον δὲ Βαρούχῳ τῷ ἰδίῳ μαθητῇ καταψεύδεσθαι μὲν τοῦ θεοῦ, πείθειν δὲ μένειν αὐτόθι, ὡς ἂν ὑπὸ τῶν Βαβυλωνίων διαφθαρῶσι."},{"number":179,"text":"παρακούσας οὖν ὅ τε λαὸς καὶ Ἰωάννης τῆς τοῦ θεοῦ συμβουλίας, ἣν αὐτοῖς διὰ τοῦ προφήτου παρῄνεσεν, ἀπῆρεν εἰς τὴν Αἴγυπτον ἄγων καὶ τὸν Ἱερεμίαν καὶ τὸν Βαροῦχον."},{"number":180,"text":"Γενομένων δὲ αὐτῶν ἐκεῖ σημαίνει τὸ θεῖον τῷ προφήτῃ μέλλοντα στρατεύειν ἐπὶ τοὺς Αἰγυπτίους τὸν βασιλέα τῶν Βαβυλωνίων, καὶ προειπεῖν ἐκέλευε τῷ λαῷ τήν τε ἅλωσιν τῆς Αἰγύπτου, καὶ ὅτι τοὺς μὲν αὐτῶν ἀποκτενεῖ, τοὺς δὲ αἰχμαλώτους λαβὼν εἰς Βαβυλῶνα ἄξει."},{"number":181,"text":"καὶ ταῦτα συνέβη· τῷ γὰρ πέμπτῳ τῆς Ἱεροσολύμων πορθήσεως ἔτει, ὅ ἐστι τρίτον καὶ εἰκοστὸν τῆς Ναβουχοδονοσόρου βασιλείας, στρατεύει Ναβουχοδονόσορος ἐπὶ τὴν κοίλην Συρίαν, καὶ κατασχὼν αὐτὴν ἐπολέμησε καὶ Μωαβίταις καὶ Ἀμμανίταις."},{"number":182,"text":"ποιησάμενος δὲ ὑπήκοα ταῦτα τὰ ἔθνη ἐνέβαλεν εἰς τὴν Αἴγυπτον καταστρεψόμενος αὐτήν, καὶ τὸν μὲν τότε βασιλέα κτείνει, καταστήσας δὲ ἕτερον τοὺς ἐν αὐτῇ πάλιν Ἰουδαίους αἰχμαλωτίσας ἤγαγεν εἰς Βαβυλῶνα."},{"number":183,"text":"καὶ τὸ μὲν Ἑβραίων γένος ἐν τοιούτῳ τέλει γενόμενον παρειλήφαμεν δὶς ἐλθὸν πέραν Εὐφράτου· ὑπὸ Ἀσσυρίων μὲν γὰρ ἐξέπεσεν ὁ τῶν δέκα φυλῶν λαὸς ἀπὸ Σαμαρείας βασιλεύοντος αὐτῶν Ὠσήου, ἔπειτα τῶν δύο φυλῶν ὑπὸ Ναβουχοδονοσόρου τοῦ τῶν Βαβυλωνίων βασιλέως καὶ τῶν Χαλδαίων ὃς ὑπελείφθη τῶν Ἱεροσολύμων ἁλόντων."},{"number":184,"text":"Σαλμανάσσης μὲν οὖν ἀναστήσας τοὺς Ἰσραηλίτας κατῴκισεν ἀντʼ αὐτῶν τὸ τῶν Χουθαίων ἔθνος, οἳ πρότερον ἐνδοτέρω τῆς Περσίδος καὶ τῆς Μηδίας ἦσαν, τότε μέντοι Σαμαρεῖς ἐκλήθησαν τὴν τῆς χώρας εἰς ἣν κατῳκίσθησαν προσηγορίαν ἀναλαβόντες· ὁ δὲ τῶν Βαβυλωνίων βασιλεὺς τὰς δύο φυλὰς ἐξαγαγὼν οὐδὲν ἔθνος εἰς τὴν χώραν αὐτῶν κατῴκισε καὶ διὰ τοῦτο ἔρημος ἡ Ἰουδαία πᾶσα καὶ Ἱεροσόλυμα καὶ ὁ ναὸς διέμεινεν ἔτεσιν ἑβδομήκοντα."},{"number":185,"text":"τὸν δὲ σύμπαντα χρόνον, ὃς ἀπὸ τῆς τῶν Ἰσραηλιτῶν αἰχμαλωσίας ἐπὶ τὴν τῶν δύο φυλῶν ἀνάστασιν ἐληλύθει, ἑκατὸν ἔτη καὶ τριάκοντα καὶ μῆνας ἓξ καὶ δέκα ἡμέρας συνέβη γενέσθαι."}],"10":[{"number":186,"text":"Ὁ δὲ τῶν Βαβυλωνίων βασιλεὺς Ναβουχοδονόσορος τοὺς εὐγενεστάτους λαβὼν τῶν Ἰουδαίων παῖδας καὶ τοὺς Σαχχίου τοῦ βασιλέως αὐτῶν συγγενεῖς, οἳ καὶ ταῖς ἀκμαῖς τῶν σωμάτων καὶ ταῖς εὐμορφίαις τῶν ὄψεων ἦσαν περίβλεπτοι, παιδαγωγοῖς καὶ τῇ διʼ αὐτῶν θεραπείᾳ παραδίδωσι ποιήσας τινὰς αὐτῶν ἐκτομίας·"},{"number":187,"text":"τὸ δʼ αὐτὸ καὶ τοὺς ἄλλων ἐθνῶν ὅσα κατεστρέψατο ληφθέντας ἐν ὥρᾳ τῆς ἡλικίας διαθεὶς ἐχορήγει μὲν αὐτοῖς τὰ ἀπὸ τῆς τραπέζης αὐτοῦ εἰς δίαιταν, ἐπαίδευε δὲ καὶ τὰ ἐπιχώρια καὶ τὰ τῶν Χαλδαίων ἐξεδίδασκε γράμματα· ἦσαν δὲ οὗτοι σοφίαν ἱκανοὶ περὶ ἣν ἐκέλευε διατρίβειν."},{"number":188,"text":"ἦσαν δʼ ἐν τούτοις τῶν ἐκ τοῦ Σαχχίου γένους τέσσαρες καλοί τε καὶ ἀγαθοὶ τὰς φύσεις, ὧν ὁ μὲν Δανίηλος ἐκαλεῖτο, ὁ δὲ Ἀνανίας, ὁ δὲ Μισάηλος, ὁ δὲ τέταρτος Ἀζαρίας. τούτους ὁ Βαβυλώνιος μετωνόμασε καὶ χρῆσθαι προσέταξεν ἑτέροις ὀνόμασι."},{"number":189,"text":"καὶ τὸν μὲν Δανίηλον ἐκάλουν Βαλτάσαρον, τὸν δʼ Ἀνανίαν Σεδράχην, Μισάηλον δὲ Μισάχην, τὸν δʼ Ἀζαρίαν Ἀβδεναγώ. τούτους ὁ βασιλεὺς διʼ ὑπερβολὴν εὐφυΐας καὶ σπουδῆς τῆς περὶ τὴν παίδευσιν καὶ σοφίας ἐν προκοπῇ γενομένους εἶχεν ἐν τιμῇ καὶ στέργων διετέλει."},{"number":190,"text":"Δόξαν δὲ Δανιήλῳ μετὰ τῶν συγγενῶν σκληραγωγεῖν ἑαυτὸν καὶ τῶν ἀπὸ τῆς βασιλικῆς τραπέζης ἐδεσμάτων ἀπέχεσθαι καὶ καθόλου πάντων τῶν ἐμψύχων, προσελθὼν Ἀσχάνῃ τῷ τὴν ἐπιμέλειαν αὐτῶν ἐμπεπιστευμένῳ εὐνούχῳ τὰ μὲν παρὰ τοῦ βασιλέως αὐτοῖς κομιζόμενα παρεκάλεσεν αὐτὸν ἀναλίσκειν λαμβάνοντα, παρέχειν δʼ αὐτοῖς ὄσπρια καὶ φοίνικας εἰς διατροφὴν καὶ εἴ τι τῶν ἀψύχων ἕτερον βούλοιτο· πρὸς γὰρ τὴν τοιαύτην δίαιταν αὐτοὺς κεκινῆσθαι, τῆς δʼ ἑτέρας περιφρονεῖν."},{"number":191,"text":"ὁ δʼ εἶναι μὲν ἕτοιμος ἔλεγεν ὑπηρετεῖν αὐτῶν τῇ προαιρέσει, ὑφορᾶσθαι δέ, μὴ κατάδηλοι τῷ βασιλεῖ γενηθέντες ἐκ τῆς τῶν σωμάτων ἰσχνότητος καὶ τῆς τροπῆς τῶν χαρακτήρων, συμμεταβάλλειν γὰρ αὐτοῖς ἀνάγκη τὰ σώματα καὶ τὰς χρόας ἅμα τῇ διαίτῃ, καὶ μάλιστα τῶν ἄλλων παίδων εὐπαθούντων ἐλεγχθέντες αἴτιοι κινδύνου καὶ τιμωρίας αὐτῷ καταστῶσιν."},{"number":192,"text":"ἔχοντα τοίνυν πρὸς τοῦτʼ εὐλαβῶς τὸν Ἀσχάνην πείθουσιν ἐπὶ δέκα ἡμέρας ταῦτα παρασχεῖν αὐτοῖς πείρας ἕνεκα καὶ μὴ μεταβαλούσης μὲν αὐτοῖς τῆς τῶν σωμάτων ἕξεως ἐπιμένειν τοῖς αὐτοῖς, ὡς οὐδὲν ἔτι εἰς αὐτὴν βλαβησομένων, εἰ δὲ μειωθέντας ἴδοι καὶ κάκιον τῶν ἄλλων ἔχοντας, ἐπὶ τὴν προτέραν αὐτοὺς δίαιταν ἄγειν."},{"number":193,"text":"ὡς δὲ οὐ μόνον οὐδὲν αὐτοὺς ἐλύπει τὴν τροφὴν ἐκείνην προσφερομένους, ἀλλὰ καὶ τῶν ἄλλων εὐτραφέστεροι τὰ σώματα καὶ μείζονες ἐγίνοντο, ὡς τοὺς μὲν ἐνδεεστέρους ὑπολαμβάνειν οἷς τὴν βασιλικὴν συνέβαινεν εἶναι χορηγίαν, τοὺς δὲ μετὰ τοῦ Δανιήλου δοκεῖν ἐν ἀφθονίᾳ καὶ τρυφῇ τῇ πάσῃ βιοῦν, ἔκτοτε μετʼ ἀδείας ὁ Ἀσχάνης ἃ μὲν ἀπὸ τοῦ δείπνου καθʼ ἡμέραν συνήθως ἔπεμπε τοῖς παισὶν ὁ βασιλεὺς αὐτὸς ἐλάμβανεν, ἐχορήγει δʼ αὐτοῖς τὰ προειρημένα."},{"number":194,"text":"οἱ δὲ ὡς καὶ τῶν ψυχῶν αὐτοῖς διὰ τοῦτο καθαρῶν καὶ πρὸς τὴν παιδείαν ἀκραιφνῶν γεγενημένων καὶ τῶν σωμάτων πρὸς φιλοπονίαν εὐτονωτέρων, οὔτε γὰρ ἐκείνας ἐφείλκοντο καὶ βαρείας εἶχον ὑπὸ τροφῆς ποικίλης οὔτε ταῦτα μαλακώτερα διὰ τὴν αὐτὴν αἰτίαν, πᾶσαν ἑτοίμως ἐξέμαθον παιδείαν ἥτις ἦν παρὰ τοῖς Ἑβραίοις καὶ τοῖς Χαλδαίοις. μάλιστα δὲ Δανίηλος ἱκανῶς ἤδη σοφίας ἐμπείρως ἔχων περὶ κρίσεις ὀνείρων ἐσπουδάκει, καὶ τὸ θεῖον αὐτῷ φανερὸν ἐγίνετο."},{"number":195,"text":"Μετὰ δʼ ἔτος δεύτερον τῆς Αἰγύπτου πορθήσεως ὁ βασιλεὺς Ναβουχοδονόσορος ὄναρ ἰδὼν θαυμαστόν, οὗ τὴν ἔκβασιν κατὰ τοὺς ὕπνους αὐτὸς αὐτῷ ἐδήλωσεν ὁ θεός, τούτου μὲν ἐπιλανθάνεται διαναστὰς ἐκ τῆς κοίτης, μεταπεμψάμενος δὲ τοὺς Χαλδαίους καὶ τοὺς μάγους καὶ τοὺς μάντεις, ὡς εἴη τι ὄναρ ἑωρακὼς ἔλεγεν αὐτοῖς, καὶ τὸ συμβεβηκὸς περὶ τὴν λήθην ὧν εἶδε μηνύων ἐκέλευεν αὐτοὺς λέγειν, ὅτι τε ἦν τὸ ὄναρ καὶ τί τὸ σημεῖον."},{"number":196,"text":"τῶν δὲ ἀδύνατον εἶναι λεγόντων ἀνθρώποις τοῦτο εὑρεῖν, εἰ δὲ αὐτοῖς ἐκθοῖτο τὴν ὄψιν τοῦ ἐνυπνίου φράσειν τὸ σημεῖον ὑποσχομένων, θάνατον ἠπείλησεν αὐτοῖς, εἰ μὴ τὸ ὄναρ εἴποιεν, προσέταξε τε πάντας αὐτοὺς ἀναιρεθῆναι ποιῆσαι τὸ κελευσθὲν ὁμολογήσαντας μὴ δύνασθαι."},{"number":197,"text":"Δανίηλος δʼ ἀκούσας, ὅτι προσέταξε πάντας τοὺς σοφοὺς ὁ βασιλεὺς ἀποθανεῖν, ἐν τούτοις δὲ καὶ αὐτὸν μετὰ τῶν συγγενῶν κινδυνεύειν, πρόσεισιν Ἀριόχῃ τῷ τὴν ἐπὶ τῶν σωματοφυλάκων τοῦ βασιλέως ἀρχὴν πεπιστευμένῳ."},{"number":198,"text":"δεηθεὶς δὲ παρʼ αὐτοῦ τὴν αἰτίαν μαθεῖν, διʼ ἣν ὁ βασιλεὺς πάντας εἴη προστεταχὼς ἀναιρεθῆναι τοὺς σοφοὺς καὶ Χαλδαίους καὶ μάγους, καὶ μαθὼν τὸ περὶ τὸ ἐνύπνιον καὶ ὅτι κελευσθέντες ὑπὸ τοῦ βασιλέως τοῦτʼ αὐτῷ δηλοῦν ἐπιλελησμένῳ φήσαντες μὴ δύνασθαι παρώξυναν αὐτόν, παρεκάλεσε τὸν Ἀριόχην εἰσελθόντα πρὸς τὸν βασιλέα μίαν αἰτήσασθαι νύκτα τοῖς μάγοις καὶ ταύτῃ τὴν ἀναίρεσιν ἐπισχεῖν· ἐλπίζειν γὰρ διʼ αὐτῆς δεηθεὶς τοῦ θεοῦ γνώσεσθαι τὸ ἐνύπνιον."},{"number":199,"text":"ὁ δὲ Ἀριόχης ταῦτʼ ἀπήγγειλε τῷ βασιλεῖ Δανίηλον ἀξιοῦν. καὶ ὁ μὲν κελεύει τὴν ἀναίρεσιν ἐπισχεῖν τῶν μάγων ἕως γνῷ τὴν ὑπόσχεσιν τὴν Δανιήλου· ὁ δὲ παῖς μετὰ τῶν συγγενῶν ὑποχωρήσας πρὸς ἑαυτὸν διʼ ὅλης ἱκετεύει τὸν θεὸν τῆς νυκτὸς γνωρίσαι καὶ τοὺς μάγους καὶ τοὺς Χαλδαίους, οἷς δεῖ καὶ αὐτοὺς συναπολέσθαι, ῥύσασθαι δὲ τῆς τοῦ βασιλέως ὀργῆς ἐμφανίσαντα τὴν ὄψιν αὐτῷ καὶ ποιήσαντα δήλην, ἧς ὁ βασιλεὺς ἐπελέληστο διὰ τῆς παρελθούσης νυκτὸς ἰδὼν κατὰ τοὺς ὕπνους."},{"number":200,"text":"ὁ δὲ θεὸς ἅμα τούς τε κινδυνεύοντας ἐλεήσας καὶ τὸν Δανίηλον τῆς σοφίας ἀγασάμενος τό τε ὄναρ αὐτῷ γνώριμον ἐποίησε καὶ τὴν κρίσιν, ὡς ἂν καὶ τὸ σημαινόμενον ὁ βασιλεὺς παρʼ αὐτοῦ μάθοι."},{"number":201,"text":"Δανίηλος δὲ γνοὺς παρὰ τοῦ θεοῦ ταῦτα περιχαρὴς ἀνίσταται καὶ τοῖς ἀδελφοῖς δηλώσας τοὺς μὲν ἀπεγνωκότας ἤδη τοῦ ζῆν καὶ πρὸς τῷ τεθνάναι τὴν διάνοιαν ἔχοντας εἰς εὐθυμίαν καὶ τὰς περὶ τοῦ βίου διήγειρεν ἐλπίδας,"},{"number":202,"text":"εὐχαριστήσας δὲ τῷ θεῷ μετʼ αὐτῶν ἔλεον λαβόντι τῆς ἡλικίας αὐτῶν γενομένης ἡμέρας παραγίνεται πρὸς Ἀριόχην καὶ ἄγειν αὐτὸν ἠξίου πρὸς τὸν βασιλέα· δηλῶσαι γὰρ αὐτῷ βούλεσθαι τὸ ἐνύπνιον, ὅ φησιν ἰδεῖν πρὸ τῆς παρελθούσης νυκτός."},{"number":203,"text":"Εἰσελθὼν δὲ πρὸς τὸν βασιλέα Δανίηλος παρῃτεῖτο πρῶτον μὴ σοφώτερον αὐτὸν δόξαι τῶν ἄλλων Χαλδαίων καὶ μάγων, ὅτι μηδενὸς ἐκείνων τὸ ὄναρ εὑρεῖν δυνηθέντος αὐτὸς αὐτὸ μέλλοι λέγειν· οὐ γὰρ κατʼ ἐμπειρίαν οὐδʼ ὅτι τὴν διάνοιαν αὐτῶν μᾶλλον ἐκπεπόνηται τοῦτο γίνεται, ἀλλʼ ἐλεήσας ἡμᾶς ὁ θεὸς κινδυνεύοντας ἀποθανεῖν δεηθέντι περί τε τῆς ἐμῆς ψυχῆς καὶ τῶν ὁμοεθνῶν καὶ τὸ ὄναρ καὶ τὴν κρίσιν αὐτοῦ φανερὰν ἐποίησεν."},{"number":204,"text":"οὐχ ἧττον γὰρ τῆς ἐφʼ ἡμῖν αὐτοῖς καταδικασθεῖσιν ὑπὸ σοῦ μὴ ζῆν λύπης περὶ τῆς σῆς αὐτοῦ δόξης ἐφρόντιζον ἀδίκως οὕτως ἄνδρας καὶ ταῦτα καλοὺς κἀγαθοὺς ἀποθανεῖν κελεύσαντος, οἷς οὐδὲν μὲν ἀνθρωπίνης σοφίας ἐχόμενον προσέταξας, ὃ δʼ ἦν θεοῦ τοῦτο ἀπῄτεις παρʼ αὐτῶν."},{"number":205,"text":"σοὶ τοίνυν φροντίζοντι περὶ τοῦ τίς ἄρξει τοῦ κόσμου παντὸς μετὰ σέ, κοιμηθέντι βουλόμενος δηλῶσαι πάντας ὁ θεὸς τοὺς βασιλεύσοντας ὄναρ ἔδειξε τοιοῦτον·"},{"number":206,"text":"ἔδοξας ὁρᾶν ἀνδριάντα μέγαν ἑστῶτα, οὗ τὴν μὲν κεφαλὴν συνέβαινεν εἶναι χρυσῆν, τοὺς δὲ ὤμους καὶ τοὺς βραχίονας ἀργυροῦς, τὴν δὲ γαστέρα καὶ τοὺς μηροὺς χαλκέους, κνήμας δὲ καὶ πόδας σιδηροῦς."},{"number":207,"text":"εἶτα λίθον ἐξ ὄρους ἀπορραγέντα ἐμπεσεῖν τῷ ἀνδριάντι καὶ τοῦτον καταβαλόντα συνθρύψαι καὶ μηδὲν αὐτοῦ μέρος ὁλόκληρον ἀφεῖναι, ὡς τὸν μὲν χρυσὸν καὶ τὸν ἄργυρον καὶ τὸν χαλκὸν καὶ τὸν σίδηρον ἀλεύρων λεπτότερον γενέσθαι, καὶ τὰ μὲν ἀνέμου πνεύσαντος σφοδροτέρου ὑπὸ τῆς βίας ἁρπαγέντα διασπαρῆναι, τὸν δὲ λίθον αὐξῆσαι τοσοῦτον, ὡς ἅπασαν δοκεῖν τὴν γῆν ὑπʼ αὐτοῦ πεπληρῶσθαι."},{"number":208,"text":"τὸ μὲν οὖν ὄναρ, ὅπερ εἶδες, τοῦτʼ ἔστιν, ἡ δὲ κρίσις αὐτοῦ τοῦτον ἔχει τὸν τρόπον· ἡ μὲν χρυσῆ κεφαλὴ σέ τε ἐδήλου καὶ τοὺς πρὸ σοῦ βασιλέας Βαβυλωνίους ὄντας· αἱ δὲ χεῖρες καὶ οἱ ὦμοι σημαίνουσιν ὑπὸ δύο καταλυθήσεσθαι βασιλέων τὴν ἡγεμονίαν ὑμῶν·"},{"number":209,"text":"τὴν δὲ ἐκείνων ἕτερός τις ἀπὸ τῆς δύσεως καθαιρήσει χαλκὸν ἠμφιεσμένος, καὶ ταύτην ἄλλη παύσει τὴν ἰσχὺν ὁμοία σιδήρῳ καὶ κρατήσει δὲ εἰς ἅπαντα διὰ τὴν τοῦ σιδήρου φύσιν· εἶναι γὰρ αὐτὴν στερροτέραν τῆς τοῦ χρυσοῦ καὶ τοῦ ἀργύρου καὶ τοῦ χαλκοῦ."},{"number":210,"text":"ἐδήλωσε δὲ καὶ περὶ τοῦ λίθου Δανίηλος τῷ βασιλεῖ, ἀλλʼ ἐμοὶ μὲν οὐκ ἔδοξε τοῦτο ἱστορεῖν τὰ παρελθόντα καὶ τὰ γεγενημένα συγγράφειν οὐ τὰ μέλλοντα ὀφείλοντι, εἰ δέ τις τῆς ἀκριβείας γλιχόμενος οὐ περιίσταται πολυπραγμονεῖν, ὡς καὶ περὶ τῶν ἀδήλων τί γενήσεται βούλεσθαι μαθεῖν, σπουδασάτω τὸ βιβλίον ἀναγνῶναι τὸ Δανιήλου· εὑρήσει δὲ τοῦτο ἐν τοῖς ἱεροῖς γράμμασιν."},{"number":211,"text":"Ὁ δὲ βασιλεὺς Ναβουχοδονόσαρος ἀκηκοὼς ταῦτα καὶ ἐπιγνοὺς τὸ ὄναρ ἐξεπλάγη τὴν τοῦ Δανιήλου φύσιν καὶ πεσὼν ἐπὶ πρόσωπον, ᾧ τρόπῳ τὸν θεὸν προσκυνοῦσι, τούτῳ τὸν Δανίηλον ἠσπάζετο·"},{"number":212,"text":"καὶ θύειν δὲ ὡς θεῷ προσέταξεν, οὐ μὴν ἀλλὰ καὶ τὴν προσηγορίαν αὐτῷ τοῦ ἰδίου θεοῦ θέμενος ἁπάσης ἐπίτροπον τῆς βασιλείας ἐποίησε καὶ τοὺς συγγενεῖς αὐτοῦ, οὓς ὑπὸ φθόνου καὶ βασκανίας εἰς κίνδυνον ἐμπεσεῖν συνέβη τῷ βασιλεῖ προσκρούσαντας ἐξ αἰτίας τοιαύτης·"},{"number":213,"text":"ὁ βασιλεὺς κατασκευάσας χρύσεον ἀνδριάντα πηχῶν τὸ μὲν ὕψος ἑξήκοντα τὸ πλάτος δὲ ἕξ, στήσας αὐτὸν ἐν τῷ μεγάλῳ τῆς Βαβυλῶνος πεδίῳ καὶ μέλλων καθιεροῦν αὐτὸν συνεκάλεσεν ἐξ ἁπάσης ἧς ἦρχε γῆς τοὺς πρώτους πρῶτον αὐτοῖς προστάξας, ὅταν σημαινούσης ἀκούσωσι τῆς σάλπιγγος, τότε πεσόντας προσκυνεῖν τὸν ἀνδριάντα· τοὺς δὲ μὴ ποιήσαντας ἠπείλησεν εἰς τὴν τοῦ πυρὸς ἐμβληθῆναι κάμινον."},{"number":214,"text":"πάντων οὖν μετὰ τὸ σημαινούσης ἐπακοῦσαι τῆς σάλπιγγος προσκυνούντων τὸν ἀνδριάντα τοὺς Δανιήλου συγγενεῖς οὐ ποιῆσαι τοῦτό φασι μὴ βουληθέντας παραβῆναι τοὺς πατρίους νόμους. καὶ οἱ μὲν ἐλεγχθέντες εὐθὺς εἰς τὸ πῦρ ἐμβληθέντες θείᾳ σώζονται προνοίᾳ καὶ παραδόξως διαφεύγουσι τὸν θάνατον."},{"number":215,"text":"ἀλλὰ κατὰ λογισμὸν οἶμαι τῷ μηδὲν ἀδικήσαντας εἰς αὐτὸ βληθῆναι οὐχ ἥψατο, καίειν δʼ ἀσθενὲς ἦν ἔχον ἐν ἑαυτῷ τοὺς παῖδας τοῦ θεοῦ κρείττονα τὰ σώματα αὐτῶν ὥστε μὴ δαπανηθῆναι ὑπὸ τοῦ πυρὸς παρασκευάσαντος. τοῦτο συνέστησεν αὐτοὺς τῷ βασιλεῖ ὡς δικαίους καὶ θεοφιλεῖς, διὸ μετὰ ταῦτα πάσης ἀξιούμενοι παρʼ αὐτοῦ τιμῆς διετέλουν."},{"number":216,"text":"Ὀλίγῳ δʼ ὕστερον χρόνῳ πάλιν ὁρᾷ κατὰ τοὺς ὕπνους ὁ βασιλεὺς ὄψιν ἑτέραν, ὡς ἐκπεσὼν τῆς ἀρχῆς μετὰ θηρίων ἕξει τὴν δίαιταν καὶ διαζήσας οὕτως ἐπὶ τῆς ἐρημίας ἔτεσιν ἑπτὰ αὖθις τὴν ἀρχὴν ἀπολήψεται. τοῦτο θεασάμενος τοὖναρ πάλιν τοὺς μάγους συγκαλέσας ἀνέκρινεν αὐτοὺς περὶ αὐτοῦ καὶ τί σημαίνοι λέγειν ἠξίου."},{"number":217,"text":"τῶν μὲν οὖν ἄλλων οὐθεὶς ἠδυνήθη τὴν τοῦ ἐνυπνίου διάνοιαν εὑρεῖν οὐδʼ ἐμφανίσαι τῷ βασιλεῖ, Δανίηλος δὲ μόνος καὶ τοῦτʼ ἔκρινε καὶ καθὼς οὗτος αὐτῷ προεῖπεν ἀπέβη. διατρίψας γὰρ ἐπὶ τῆς ἐρημίας τὸν προειρημένον χρόνον οὐδενὸς τολμήσαντος ἐπιθέσθαι τοῖς πράγμασι παρὰ τὴν ἑπταετίαν, δεηθεὶς τοῦ θεοῦ τὴν βασιλείαν ἀπολαβεῖν πάλιν εἰς αὐτὴν ἐπανέρχεται."},{"number":218,"text":"ἐγκαλέσῃ δέ μοι μηδεὶς οὕτως ἕκαστα τούτων ἀπαγγέλλοντι διὰ τῆς γραφῆς, ὡς ἐν τοῖς ἀρχαίοις εὑρίσκω βιβλίοις· καὶ γὰρ εὐθὺς ἐν ἀρχῇ τῆς ἱστορίας πρὸς τοὺς ἐπιζητήσοντάς τι περὶ τῶν πραγμάτων ἢ μεμψομένους ἠσφαλισάμην, μόνον τε μεταφράζειν τὰς Ἑβραίων βίβλους εἰπὼν εἰς τὴν Ἑλλάδα γλῶτταν καὶ ταῦτα δηλώσειν μήτε προστιθεὶς τοῖς πράγμασιν αὐτὸς ἰδίᾳ μήτʼ ἀφαιρῶν ὑπεισχημένος."}],"11":[{"number":219,"text":"Ὁ δὲ βασιλεὺς Ναβουχοδονόσορος ἔτη τρία καὶ τεσσαράκοντα βασιλεύσας τελευτᾷ τὸν βίον ἀνὴρ δραστήριος καὶ τῶν πρὸ αὐτοῦ βασιλέων εὐτυχέστερος γενόμενος. μέμνηται δʼ αὐτοῦ τῶν πράξεων καὶ Βηρωσὸς ἐν τῇ τρίτῃ τῶν Χαλδαϊκῶν ἱστοριῶν λέγων οὕτως·"},{"number":220,"text":"ἀκούσας δʼ ὁ πατὴρ αὐτοῦ Ναβουχοδονόσορος, ὅτι ὁ τεταγμένος σατράπης ἐν τῇ Αἰγύπτῳ καὶ τοῖς περὶ τὴν Συρίαν τὴν κοίλην καὶ τὴν Φοινίκην τόποις ἀποστάτης αὐτοῦ γέγονεν, οὐ δυνάμενος αὐτὸς κακοπαθεῖν συστήσας τῷ υἱῷ Ναβουχοδονοσόρῳ ὄντι ἐν ἡλικίᾳ μέρη τινὰ τῆς δυνάμεως ἐξέπεμψεν ἐπʼ αὐτόν."},{"number":221,"text":"συμμίξας δὲ Ναβουχοδονόσορος τῷ ἀποστάτῃ καὶ παραταξάμενος αὐτοῦ τε ἐκράτησε καὶ τὴν χώραν ἐκ ταύτης τῆς ἀρχῆς ὑπὸ τὴν αὐτοῦ βασιλείαν ἐποιήσατο. τῷ τε πατρὶ αὐτοῦ Ναβουχοδονοσόρῳ συνέβη κατʼ αὐτὸν τὸν καιρὸν ἀρρωστήσαντι ἐν τῇ Βαβυλωνίων πόλει μεταλλάξαι τὸν βίον ἔτη βασιλεύσαντα εἴκοσι καὶ ἕν."},{"number":222,"text":"αἰσθόμενος δὲ μετʼ οὐ πολὺν χρόνον τὴν τοῦ πατρὸς τελευτὴν Ναβουχοδονοσάρου καὶ καταστήσας τὰ κατὰ τὴν Αἴγυπτον πράγματα καὶ τὴν λοιπὴν χώραν καὶ τοὺς αἰχμαλώτους Ἰουδαίων τε καὶ Φοινίκων καὶ Σύρων καὶ τῶν κατʼ Αἴγυπτον ἐθνῶν συντάξας τισὶ τῶν φίλων μετὰ τῆς βαρυτάτης δυνάμεως καὶ τῆς λοιπῆς ὠφελείας ἀνακομίζειν εἰς τὴν Βαβυλωνίαν, αὐτὸς ὁρμήσας ὀλιγοστὸς διὰ τῆς ἐρήμου παραγίνεται εἰς Βαβυλῶνα."},{"number":223,"text":"παραλαβὼν δὲ τὰ πράγματα διοικούμενα ὑπὸ Χαλδαίων καὶ διατηρουμένην τὴν βασιλείαν ὑπὸ τοῦ βελτίστου αὐτῶν, κυριεύσας ὁλοκλήρου τῆς πατρικῆς ἀρχῆς τοῖς μὲν αἰχμαλώτοις παραγενομένοις συνέταξεν ἀποικίας ἐν τοῖς ἐπιτηδειοτάτοις τῆς Βαβυλωνίας τόποις ἀποδεῖξαι,"},{"number":224,"text":"αὐτὸς δʼ ἀπὸ τῶν ἐκ τοῦ πολέμου λαφύρων τό τε τοῦ Βήλου ἱερὸν καὶ τὰ λοιπὰ κοσμήσας φιλοτίμως τήν τε ὑπάρχουσαν ἐξ ἀρχῆς πόλιν καὶ ἕτερα καταχαρισάμενος καὶ ἀναγκάσας πρὸς τὸ μηκέτι δύνασθαι τοὺς πολιορκοῦντας τὸν ποταμὸν ἀναστρέψαντας ἐπὶ τὴν πόλιν κατασκευάζειν περιεβάλετο τρεῖς μὲν τῆς ἔνδον πόλεως περιβόλους, τρεῖς δʼ ἔξω τούτων δὲ τῆς ὀπτῆς πλίνθου."},{"number":225,"text":"καὶ τειχίσας ἀξιολόγως τὴν πόλιν καὶ τοὺς πυλῶνας κοσμήσας ἱεροπρεπῶς κατεσκεύασεν ἐν τοῖς πατρικοῖς βασιλείοις ἕτερα βασίλεια ἐχόμενα αὐτῶν, ὧν τὸ μὲν ἀνάστημα καὶ τὴν λοιπὴν πολυτέλειαν περισσὸν ἴσως ἂν εἴη λέγειν, πλὴν ὅσον τὰ μεγάλα καὶ ὑπερήφανα συνετελέσθη ἡμέραις πεντεκαίδεκα."},{"number":226,"text":"ἐν δὲ τοῖς βασιλείοις τούτοις ἀναλήμματα λίθινα ἀνῳκοδόμησε τὴν ὄψιν ἀποδοὺς ὁμοιοτάτην τοῖς ὄρεσι, καταφυτεύσας δένδρεσι παντοδαποῖς ἐξειργάσατο καὶ κατεσκεύασε τὸν καλούμενον κρεμαστὸν παράδεισον διὰ τὸ τὴν γυναῖκα αὐτοῦ ἐπιθυμεῖν τῆς οἰκείας διαθέσεως ὡς τεθραμμένην ἐν τοῖς κατὰ Μηδίαν τόποις."},{"number":227,"text":"καὶ Μεγασθένης δὲ ἐν τῇ τετάρτῃ τῶν Ἰνδικῶν μνημονεύει αὐτῶν διʼ ἧς ἀποφαίνειν πειρᾶται τοῦτον τὸν βασιλέα τῇ ἀνδρείᾳ καὶ τῷ μεγέθει τῶν πράξεων ὑπερβεβηκότα τὸν Ἡρακλέα· καταστρέψασθαι γὰρ αὐτόν φησι Λιβύης τὴν πολλὴν καὶ Ἰβηρίαν."},{"number":228,"text":"καὶ Διοκλῆς δʼ ἐν τῇ δευτέρᾳ τῶν Περσικῶν μνημονεύει τούτου τοῦ βασιλέως καὶ Φιλόστρατος ἐν ταῖς Ἰνδικαῖς καὶ Φοινικικαῖς ἱστορίαις, ὅτι οὗτος ὁ βασιλεὺς ἐπολιόρκησε τὴν Τύρον ἔτεσι τρισὶ καὶ δέκα βασιλεύοντος κατʼ ἐκεῖνον τὸν καιρὸν Ἰθωβάλου τῆς Τύρου. καὶ τὰ μὲν ὑπὸ πάντων ἱστορούμενα περὶ τούτου τοῦ βασιλέως ταῦτα ἦν."},{"number":229,"text":"Μετὰ δὲ τὴν Ναβουχοδονοσόρου τελευτὴν Ἀβιλμαθαδάχος ὁ παῖς αὐτοῦ τὴν βασιλείαν παραλαμβάνει, ὃς εὐθὺς τὸν τῶν Ἱεροσολύμων βασιλέα Ἰεχονίαν τῶν δεσμῶν ἀφεὶς ἐν τοῖς ἀναγκαιοτάτοις τῶν φίλων εἶχε πολλὰς αὐτῷ δωρεὰς δοὺς καὶ ποιήσας αὐτὸν ἐπὶ τῶν ἐν τῇ Βαβυλωνίᾳ βασιλέων·"},{"number":230,"text":"ὁ γὰρ πατὴρ αὐτοῦ τὴν πίστιν οὐκ ἐφύλαξεν Ἰεχονίᾳ παραδόντι μετὰ γυναικῶν καὶ τέκνων καὶ τῆς συγγενείας ὅλης ἑκουσίως αὑτὸν ὑπὲρ τῆς πατρίδος, ὡς ἂν μὴ κατασκαφείη ληφθεῖσα ὑπὸ τῆς πολιορκίας, καθὼς προειρήκαμεν."},{"number":231,"text":"τελευτήσαντος δὲ Ἀβιλμαθαδάχου μετὰ ἔτη ὀκτωκαίδεκα τῆς βασιλείας Ἠγλίσαρος ὁ παῖς αὐτοῦ τὴν ἀρχὴν παραλαμβάνει, καὶ κατασχὼν αὐτὴν ἔτη τεσσαράκοντα καταστρέφει τὸν βίον. μετὰ δʼ αὐτὸν εἰς τὸν υἱὸν αὐτοῦ Λαβοσόρδαχον ἀφικνεῖται τῆς βασιλείας ἡ διαδοχή, καὶ μῆνας ποιήσασα παρʼ αὐτῷ τοὺς πάντας ἐννέα τελευτήσαντος αὐτοῦ μεταβαίνει πρὸς Βαλτασάρην τὸν καλούμενον Ναβοάνδηλον παρὰ τοῖς Βαβυλωνίοις."},{"number":232,"text":"ἐπὶ τοῦτον στρατεύουσι Κῦρός τε ὁ Περσῶν βασιλεὺς καὶ Δαρεῖος ὁ Μήδων. καὶ πολιορκουμένων τοὺς ἐν Βαβυλῶνι θαυμάσιόν τι καὶ τεράστιον θέαμα συνέβη· κατέκειτο δειπνῶν καὶ πίνων ἐν οἴκῳ μεγάλῳ καὶ πρὸς ἑστιάσεις πεποιημένῳ βασιλικὰς μετὰ τῶν παλλακίδων καὶ τῶν φίλων."},{"number":233,"text":"δόξαν δὲ αὐτῷ κομισθῆναι κελεύει ἐκ τοῦ ἰδίου ναοῦ τὰ τοῦ θεοῦ σκεύη, ἃ συλήσας Ναβουχοδονόσορος ἐκ τῶν Ἱεροσολύμων οὐκ ἐχρῆτο μέν, εἰς δὲ τὸν αὑτοῦ ναὸν κατέθηκεν. αὐτὸς δὲ ὑπὸ θράσους προαχθείς, ὥστε αὐτοῖς χρῆσθαι, μεταξὺ πίνων καὶ βλασφημῶν τὸν θεὸν ἐκ τοῦ τείχους ὁρᾷ χεῖρα προϊοῦσαν καὶ τῷ τοίχῳ τινὰς συλλαβὰς ἐγγράφουσαν."},{"number":234,"text":"ταραχθεὶς δὲ ὑπὸ τῆς ὄψεως συνεκάλεσε τοὺς μάγους καὶ τοὺς Χαλδαίους, πᾶν τοῦτο τὸ γένος ὅσον ἦν ἐν τοῖς Βαβυλωνίοις τά τε σημεῖα καὶ τὰ ὀνείρατα κρίνειν δυνάμενον, ὡς ἂν αὐτῷ δηλώσωσι τὰ γεγραμμένα."},{"number":235,"text":"τῶν δὲ μάγων οὐδὲν εὑρίσκειν δυναμένων οὐδὲ συνιέναι λεγόντων ὑπʼ ἀγωνίας ὁ βασιλεὺς καὶ πολλῆς τῆς ἐπὶ τῷ παραδόξῳ λύπης κατὰ πᾶσαν ἐκήρυξε τὴν χώραν τῷ τὰ γράμματα καὶ τὴν ὑπʼ αὐτῶν δηλουμένην διάνοιαν σαφῆ ποιήσαντι δώσειν ὑπισχνούμενος στρεπτὸν περιαυχένιον χρύσεον καὶ πορφυρᾶν ἐσθῆτα φορεῖν, ὡς οἱ τῶν Χαλδαίων βασιλεῖς, καὶ τὸ τρίτον μέρος τῆς ἰδίας ἀρχῆς."},{"number":236,"text":"τούτου γενομένου τοῦ κηρύγματος ἔτι μᾶλλον οἱ μάγοι συνδραμόντες καὶ φιλοτιμησάμενοι πρὸς τὴν εὕρεσιν τῶν γραμμάτων οὐδὲν ἔλαττον ἠπόρησαν."},{"number":237,"text":"ἀθυμοῦντα δʼ ἐπὶ τούτῳ θεασαμένη τὸν βασιλέα ἡ μάμμη αὐτοῦ παραθαρσύνειν ἤρξατο καὶ λέγειν, ὡς ἔστι τις ἀπὸ τῆς Ἰουδαίας αἰχμάλωτος ἐκεῖθεν τὸ γένος ἀχθεὶς ὑπὸ τοῦ Ναβουχοδονοσόρου πορθήσαντος Ἱεροσόλυμα Δανίηλος ὄνομα, σοφὸς ἀνὴρ καὶ δεινὸς εὑρεῖν τὰ ἀμήχανα καὶ μόνῳ τῷ θεῷ γνώριμα, ὃς Ναβουχοδονοσόρῳ τῷ βασιλεῖ μηδενὸς ἄλλου δυνηθέντος εἰπεῖν περὶ ὧν ἔχρῃζεν εἰς φῶς ἤγαγε τὰ ζητούμενα."},{"number":238,"text":"μεταπεμψάμενον οὖν αὐτὸν ἠξίου παρʼ αὐτοῦ πυνθάνεσθαι περὶ τῶν γραμμάτων καὶ τὴν ἀμαθίαν τὴν τῶν οὐχ εὑρόντων αὐτὰ κατακρίνειν, κἂν σκυθρωπὸν ᾖ τὸ ὑπὸ τοῦ θεοῦ σημαινόμενον."},{"number":239,"text":"Ταῦτʼ ἀκούσας καλεῖ τὸν Δανίηλον ὁ Βαλτασάρης καὶ διαλεχθεὶς ὡς πύθοιτο περὶ αὐτοῦ καὶ τῆς σοφίας, ὅτι θεῖον αὐτῷ πνεῦμα συμπάρεστι καὶ μόνος ἐξευρεῖν ἱκανώτατος ἃ μὴ τοῖς ἄλλοις εἰς ἐπίνοιαν ἔρχεται, φράζειν αὐτῷ τὰ γεγραμμένα καὶ τί σημαίνει μηνύειν ἠξίου·"},{"number":240,"text":"τοῦτο γὰρ ποιήσαντι πορφύραν δώσειν ἐνδεδύσθαι καὶ χρύσεον περὶ αὐχένα στρεπτὸν καὶ τὸ τρίτον τῆς ἀρχῆς αὐτοῦ μέρος τιμὴν καὶ γέρας τῆς σοφίας, ὡς ἂν ἐξ αὐτῶν ἐπισημότατος γένοιτο τοῖς ὁρῶσι καὶ τὴν αἰτίαν ἐφʼ ᾗ τούτων ἔτυχε πυνθανομένοις."},{"number":241,"text":"Δανίηλος δὲ τὰς μὲν δωρεὰς αὐτὸν ἔχειν ἠξίου· τὸ γὰρ σοφὸν καὶ θεῖον ἀδωροδόκητον εἶναι καὶ προῖκα τοὺς δεομένους ὠφελεῖν, μηνύσειν δʼ αὐτῷ τὰ γεγραμμένα σημαίνοντα καταστροφὴν αὐτῷ τοῦ βίου, ὅτι μηδʼ οἷς ὁ πρόγονος αὐτοῦ διὰ τὰς εἰς θεὸν ὕβρεις ἐκολάσθη τούτοις ἔμαθεν εὐσεβεῖν καὶ μηδὲν ὑπὲρ τὴν ἀνθρωπίνην φύσιν μηχανᾶσθαι·"},{"number":242,"text":"ἀλλὰ καὶ Ναβουχοδονοσόρου μεταστάντος εἰς δίαιταν θηρίων ἐφʼ οἷς ἠσέβησε καὶ μετὰ πολλὰς ἱκεσίας καὶ δεήσεις ἐλεηθέντος ἐπανελθεῖν εἰς τὸν ἀνθρώπινον βίον καὶ τὴν βασιλείαν, καὶ διὰ ταῦτα τὸν θεὸν ὡς τὴν ἅπασαν ἔχοντα δύναμιν καὶ προνοούμενον τῶν ἀνθρώπων μέχρις οὗ καὶ ἐτελεύτησεν ὑμνοῦντος, λήθην αὐτὸς ἔλαβε τούτων καὶ πολλὰ μὲν ἐβλασφήμησε τὸ θεῖον, τοῖς δὲ σκεύεσιν αὐτοῦ μετὰ τῶν παλλακίδων διηκονεῖτο."},{"number":243,"text":"ταῦτα ὁρῶντα τὸν θεὸν ὀργισθῆναι αὐτῷ καὶ διὰ τῶν γεγραμμένων προκαταγγέλλειν, εἰς οἷον αὐτὸν καταστρέψαι δεῖ τέλος. ἐδήλου δὲ τὰ γράμματα τάδε· μάνη· τούτῳ δὲ ἔλεγεν Ἑλλάδι γλώσσῃ σημαίνοιτο ἂν ἀριθμός, ὥσπερ τῆς ζωῆς σου τὸν χρόνον καὶ τῆς ἀρχῆς ἠρίθμηκεν ὁ θεὸς καὶ περισσεύειν ἔτι σοι βραχὺν χρόνον."},{"number":244,"text":"θέκελ· σημαίνει τοῦτο τὸν σταθμόν· στήσας οὖν σου λέγει τὸν χρόνον τῆς βασιλείας ὁ θεὸς ἤδη καταφερομένην δηλοῖ. φαρές· καὶ τοῦτο κλάσμα δηλοῖ καθʼ Ἑλλάδα γλῶτταν· κλάσει τοιγαροῦν σου τὴν βασιλείαν καὶ Μήδοις αὐτὴν καὶ Πέρσαις διανεμεῖ."},{"number":245,"text":"Δανιήλου δὲ ταῦτα τῷ βασιλεῖ σημαίνειν φράσαντος τὰ ἐν τῷ τοίχῳ γράμματα τὸν μὲν Βαλτασάρην, οἷον εἰκὸς ἐφʼ οὕτω χαλεποῖς τοῖς δεδηλωμένοις, λύπη καὶ συμφορὰ κατέλαβεν·"},{"number":246,"text":"οὐ μὴν ὡς προφήτῃ αὐτῷ κακῶν γενομένῳ τὰς δωρεὰς ἃς ὑπέσχετο δώσειν οὐ δίδωσιν, ἀλλὰ πάσας παρέσχε, τὸ μὲν ἐφʼ οἷς δοθήσονται λογιζόμενος ἴδιον αὐτοῦ καὶ τῆς ἀνάγκης, ἀλλʼ οὐχὶ τοῦ προφητεύσαντος εἶναι, τὰ δὲ ὡμολογημένα κρίνων ἀνδρὸς ἀγαθοῦ καὶ δικαίου, κἂν ᾖ σκυθρωπὰ τὰ μέλλοντα συμβαίνειν οὕτως ἔκρινε·"},{"number":247,"text":"μετʼ οὐ πολὺν δὲ χρόνον αὐτός τε ἐλήφθη καὶ ἡ πόλις Κύρου τοῦ Περσῶν βασιλέως ἐπʼ αὐτὸν στρατεύσαντος· Βαλτάσαρος γάρ ἐστιν, ἐφʼ οὗ τὴν αἵρεσιν τῆς Βαβυλῶνος συνέβη γενέσθαι, βασιλεύσαντος αὐτοῦ ἑπτακαίδεκα ἔτη."},{"number":248,"text":"τῶν μὲν οὖν Ναβουχοδονοσόρου τοῦ βασιλέως ἐγγόνων τὸ τέλος τοιοῦτον παρειλήφαμεν γενόμενον· Δαρείῳ δὲ τῷ καταλύσαντι τὴν Βαβυλωνίων ἡγεμονίαν μετὰ Κύρου τοῦ συγγενοῦς ἔτος ἦν ἑξηκοστὸν καὶ δεύτερον, ὅτε τὴν Βαβυλῶνα εἷλεν, ὃς ἦν Ἀστυάγους υἱός, ἕτερον δὲ παρὰ τοῖς Ἕλλησιν ἐκαλεῖτο ὄνομα·"},{"number":249,"text":"ὃς καὶ Δανίηλον τὸν προφήτην λαβὼν ἤγαγεν εἰς Μηδίαν πρὸς αὑτὸν καὶ πάσης αὐτῷ τιμῆς μεταδιδοὺς εἶχε σὺν αὑτῷ· τῶν τριῶν γὰρ σατραπῶν ἦν, οὓς ἐπὶ τῶν ἑξήκοντα καὶ τριακοσίων σατραπειῶν κατέστησε· τοσούτους γὰρ ἐποίησε Δαρεῖος εἰς αὐτήν."},{"number":250,"text":"Δανίηλος τοίνυν ὢν ἐν τοιαύτῃ τιμῇ καὶ λαμπρᾷ σπουδῇ παρὰ τῷ Δαρείῳ καὶ πρὸς ἅπαντα ὑπʼ αὐτοῦ μόνος, ὡς ἂν ἔχων τὸ θεῖον πεπιστευμένος ἐν αὑτῷ, παραλαμβανόμενος ἐφθονήθη· βασκαίνουσι γὰρ οἱ μᾶλλον αὐτῶν ἑτέρους ἐν πλείονι τιμῇ παρὰ τοῖς βασιλεῦσι βλέποντες."},{"number":251,"text":"ζητούντων δʼ ἐπʼ αὐτὸν ἀφορμὴν διαβολῆς καὶ κατηγορίας τῶν ἀχθομένων ἐπʼ αὐτῷ εὐδοκιμοῦντι παρὰ τῷ Δαρείῳ παρεῖχεν αἰτίαν οὐδεμίαν· ὢν γὰρ καὶ χρημάτων ἐπάνω καὶ παντὸς λήμματος περιορῶν, αἴσχιστον αὐτῷ δοκεῖν κἂν ὑπὲρ ὧν δοθείη καλῶς πρὸς τὸ λαβεῖν, οὐδʼ ἡντιναοῦν τοῖς ζηλοτυποῦσιν αὐτὸν ἐγκλημάτων εὕρεσιν παρεῖχεν."},{"number":252,"text":"οἱ δʼ ὡς οὐδὲν εἶχον, ὃ κατειπόντες αὐτοῦ πρὸς τὸν βασιλέα ζημιώσουσιν αὐτὸν εἰς τὴν παρʼ αὐτοῦ τιμὴν αἰσχύνῃ καὶ διαβολῇ, τρόπον ἄλλον ἐζήτουν καθʼ ὃν αὐτὸν ἐκποδὼν ποιήσονται. ὁρῶντες οὖν τὸν Δανίηλον τρὶς τῆς ἡμέρας προσευχόμενον τῷ θεῷ πρόφασιν ἔγνωσαν εὑρηκέναι, διʼ ἧς ἀπολέσουσιν αὐτόν."},{"number":253,"text":"καὶ πρὸς τὸν Δαρεῖον ἐλθόντες ἀπήγγελλον αὐτῷ, ὡς τοῖς σατράπαις αὐτοῦ καὶ τοῖς ἡγεμόσι δόξειεν ἐπὶ τριάκονθʼ ἡμέρας ἀνεῖναι τὸ πλῆθος, ὅπως μήτʼ αὐτῷ τις μήτε τοῖς θεοῖς δεόμενος αὐτῶν καὶ εὐχόμενος εἴη, τὸν μέντοι γε αὐτῶν παραβάντα ταύτην τὴν γνώμην εἰς τὸν τῶν λεόντων ἔκριναν ῥῖψαι λάκκον ἀπολούμενον."},{"number":254,"text":"Ὁ δὲ βασιλεὺς οὐ συνιδὼν τὴν κακουργίαν οὐδʼ ἐπὶ τὸν Δανίηλον ταῦτα κατεσκευασμένους ὑπονοήσας ἀρέσκεσθαι τοῖς ὑπʼ αὐτῶν ἔφη δεδογμένοις, καὶ κυρώσειν τὴν προαίρεσιν αὐτῶν ἐπαγγελλόμενος προτίθησι πρόγραμμα δηλοῦν τῷ πλήθει τὰ δόξαντα τοῖς σατράπαις."},{"number":255,"text":"καὶ οἱ μὲν ἄλλοι πάντες φυλαττόμενοι τὰ προστεταγμένα μὴ παραβῆναι ἠρέμουν, Δανιήλῳ δὲ φροντὶς οὐδʼ ἡτισοῦν τούτων ἦν, ἀλλʼ ὡς ἔθος εἶχεν ἱστάμενος ηὔχετο τῷ θεῷ πάντων ὁρώντων."},{"number":256,"text":"οἱ δὲ σατράπαι τῆς ἀφορμῆς αὐτοῖς ἣν ἐσπούδαζον λαβεῖν ἐπὶ τὸν Δανίηλον παραφανείσης εὐθὺς ἧκον πρὸς τὸν βασιλέα καὶ κατηγόρουν ὡς παραβαίνοντος μόνου τοῦ Δανιήλου τὰ προστεταγμένα· μηδενὸς γὰρ τῶν ἄλλων τολμῶντος προσεύχεσθαι τοῖς θεοῖς, καὶ τοῦτʼ οὐ διʼ ἀσέβειαν, ἀλλὰ διὰ φυλακὴν καὶ διατήρησιν ὑπὸ τοῦ φθόνου·"},{"number":257,"text":"ἀπὸ γὰρ μείζονος ἧς προσεδόκων εὐνοίας τοῦτο ποιεῖν τὸν Δαρεῖον ὑπολαμβάνοντες, ὡς καὶ καταφρονήσαντι τῶν ἐκείνου προσταγμάτων συγγνώμην ἑτοίμως νέμειν, καὶ αὐτὸ τοῦτο βασκαίνοντες τῷ Δανιήλῳ, οὔτε μετεβάλλοντο πρὸς τὸ ἡμερώτερον, ῥίπτειν δʼ αὐτὸν ἠξίουν κατὰ τὸν νόμον εἰς τὸν λάκκον τῶν λεόντων."},{"number":258,"text":"ἐλπίσας δʼ ὁ Δαρεῖος, ὅτι ῥύσεται τὸ θεῖον αὐτὸν καὶ οὐδὲν μὴ πάθῃ δεινὸν ὑπὸ τῶν θηρίων, ἐκέλευσεν αὐτῷ εὐθύμως φέρειν τὰ συμβαίνοντα· καὶ βληθέντος εἰς τὸν λάκκον σφραγίσας τὸν ἐπὶ τοῦ στομίου κείμενον ἀντὶ θύρας λίθον ἀνεχώρησε, διʼ ὅλης δʼ ἄσιτος τῆς νυκτὸς καὶ ἄυπνος διῆγεν ἀγωνιῶν περὶ τοῦ Δανιήλου·"},{"number":259,"text":"μεθʼ ἡμέραν δὲ ἀναστὰς ἐπὶ τὸν λάκκον ἦλθε καὶ σωζομένην τὴν σφραγῖδα εὑρών, ᾗ σημηνάμενος τὸν λίθον κατελελοίπει, ἀνοίξας ἀνεβόησε καλῶν τὸν Δανίηλον καὶ πυνθανόμενος εἰ σώζεται. τοῦ δὲ ἐπακούσαντος τῷ βασιλεῖ καὶ μηδὲν παθεῖν εἰπόντος, ἐκέλευσεν αὐτὸν ἀνελκυσθῆναι ἐκ τοῦ λάκκου τοῦ τῶν θηρίων."},{"number":260,"text":"οἱ δὲ ἐχθροὶ θεασάμενοι τὸν Δανίηλον μηδὲν πεπονθότα δεινὸν διὰ μὲν τὸ θεῖον καὶ τὴν τούτου πρόνοιαν οὐκ ἠξίουν αὐτὸν σώζεσθαι, πεπληρωμένους δὲ τοὺς λέοντας τροφῆς μὴ ἅψασθαι μηδὲ προσελθεῖν τῷ Δανιήλῳ νομίζοντες τοῦτο ἔλεγον πρὸς τὸν βασιλέα."},{"number":261,"text":"ὁ δὲ μισήσας αὐτοὺς τῆς πονηρίας παραβληθῆναι μὲν πολλὰ κελεύει τοῖς λέουσι κρέα, κορεσθέντων δʼ αὐτῶν τοὺς ἐχθροὺς τοῦ Δανιήλου προσέταξεν εἰς τὸν λάκκον βληθῆναι, ὅπως εἰ διὰ κόρον αὐτοῖς οὐ προσήξουσιν οἱ λέοντες μάθοι."},{"number":262,"text":"σαφὲς δʼ ἐγένετο τῷ Δαρείῳ τῶν σατραπῶν παραβληθέντων τοῖς θηρίοις, ὅτι τὸ θεῖον ἔσωσε τὸν Δανίηλον· οὐδενὸς γὰρ αὐτῶν ἐφείσαντο οἱ λέοντες, ἀλλὰ πάντας διεσπάραττον ὡσανεὶ σφόδρα λιμώττοντες καὶ τροφῆς ἐνδεεῖς. ἠρέθισε δʼ αὐτοὺς οὐ τὸ πεινῆν οἶμαι μικρὸν ἔμπροσθεν ἀφθόνων κρεῶν πεπληρωμένους, ἀλλʼ ἡ τῶν ἀνθρώπων κακία, δήλη γὰρ καὶ τοῖς ἀλόγοις ζῴοις ἦν αὕτη, πρὸς τιμωρίαν ἣ γένοιτο τοῦ θεοῦ προαιρουμένου."},{"number":263,"text":"Διαφθαρέντων οὖν τῶν ἐπιβουλευσάντων Δανιήλῳ τοῦτον τὸν τρόπον ὁ βασιλεὺς Δαρεῖος καθʼ ὅλην ἔπεμψε τὴν χώραν ἐπαινῶν τὸν θεόν, ὃν Δανίηλος προσκυνεῖ, καὶ μόνον αὐτὸν εἶναι ἔλεγεν ἀληθῆ καὶ τὸ πάντων κράτος ἔχοντα· ἔσχε δὲ καὶ τὸν Δανίηλον ἐν ὑπερβαλλούσῃ τιμῇ πρῶτον αὐτὸν ἀποδείξας τῶν φίλων."},{"number":264,"text":"ὢν δὲ οὕτως ἐπίσημος καὶ λαμπρὸς ἐπὶ δόξῃ τοῦ θεοφιλὴς εἶναι Δανίηλος ᾠκοδόμησεν ἐν Ἐκβατάνοις τῆς Μηδικῆς βάριν εὐπρεπέστατόν τι κατασκεύασμα καὶ θαυμασίως πεποιημένον, ἣ μέχρι δεῦρο μὲν ἔστι καὶ σώζεται, τοῖς δʼ ὁρῶσι δοκεῖ προσφάτως κατεσκευάσθαι καὶ ἐπʼ αὐτῆς ἐκείνης ἧς ἕκαστος αὐτὴν ἡμέρας ἱστορεῖ γεγονέναι· οὕτως νεαρὸν αὐτῆς καὶ ἀκμαῖον τὸ κάλλος καὶ μηδαμοῦ γεγηρακὸς ὑπὸ τοσούτου χρόνου·"},{"number":265,"text":"πάσχει γὰρ καὶ τὰ κατασκευάσματα ταὐτὸν ἀνθρώποις καὶ πολιοῦται καὶ τὴν ἰσχὺν λυόμενα ὑπὸ τῶν ἐτῶν καὶ τὴν εὐπρέπειαν μαραινόμενα. θάπτουσι δʼ ἐν τῇ βάρει τούς τε Μήδων βασιλέας καὶ Περσῶν καὶ Πάρθων ἄχρι τοῦ δεῦρο, καὶ ὁ ταύτην πεπιστευμένος Ἰουδαῖός ἐστιν ἱερεὺς καὶ τοῦτο γίνεται μέχρι τῆς σήμερον ἡμέρας."},{"number":266,"text":"ἄξιον δὲ τἀνδρὸς τούτου καὶ ὃ μάλιστʼ ἂν θαυμάσαι τις ἀκούσας διελθεῖν· ἀπαντᾷ γὰρ αὐτῷ παραδόξως ὡς ἑνί τινι τῶν μεγίστων καὶ παρὰ τὸν τῆς ζωῆς χρόνον τιμή τε καὶ δόξα ἡ παρὰ τῶν βασιλέων καὶ τοῦ πλήθους, καὶ τελευτήσας δὲ μνήμην αἰώνιον ἔχει."},{"number":267,"text":"τὰ γὰρ βιβλία, ὅσα δὴ συγγραψάμενος καταλέλοιπεν, ἀναγινώσκεται παρʼ ἡμῖν ἔτι καὶ νῦν καὶ πεπιστεύκαμεν ἐξ αὐτῶν, ὅτι Δανίηλος ὡμίλει τῷ θεῷ· οὐ γὰρ τὰ μέλλοντα μόνον προφητεύων διετέλει, καθάπερ καὶ οἱ ἄλλοι προφῆται, ἀλλὰ καὶ καιρὸν ὥριζεν, εἰς ὃν ταῦτα ἀποβήσεται·"},{"number":268,"text":"καὶ τῶν προφητῶν τὰ χείρω προλεγόντων καὶ διὰ τοῦτο δυσχεραινομένων ὑπὸ τῶν βασιλέων καὶ τοῦ πλήθους Δανίηλος ἀγαθῶν ἐγίνετο προφήτης αὐτοῖς, ὡς ἀπὸ μὲν τῆς εὐφημίας τῶν προλεγομένων εὔνοιαν ἐπισπᾶσθαι παρὰ πάντων, ἀπὸ δὲ τοῦ τέλους αὐτῶν ἀληθείας πίστιν καὶ δόξαν ὁμοῦ θειότητος παρὰ τοῖς ὄχλοις ἀποφέρεσθαι."},{"number":269,"text":"κατέλιπε δὲ γράψας, ὅθεν ἡμῖν ἀληθὲς τὸ τῆς προφητείας αὐτοῦ ἀκριβὲς καὶ ἀπαράλλακτον ἐποίησε δῆλον· φησὶ γὰρ αὐτὸν γενόμενον ἐν Σούσοις ἐν τῇ μητροπόλει τῆς Περσίδος, ὡς ἐξῆλθεν εἰς τὸ πεδίον μετὰ ἑταίρων αὐτοῦ, σεισμοῦ καὶ κλόνου τῆς γῆς ἐξαίφνης γενομένου καταλειφθείη μόνος φευγόντων τῶν φίλων καὶ πέσοι μὲν ἐπὶ στόμα ταραχθεὶς ἐπὶ τὰς δύο χεῖρας, τινὸς δʼ ἁψαμένου αὐτοῦ καὶ μεταξὺ κελεύοντος ἀναστῆναι καὶ τὰ μέλλοντα συμβήσεσθαι τοῖς πολίταις ἰδεῖν μετὰ πολλὰς γενεάς."},{"number":270,"text":"ἀναστάντι δʼ αὐτῷ δειχθῆναι κριὸν ἐσήμαινε μέγαν, πολλὰ μὲν ἐκπεφυκότα κέρατα, τελευταῖον δʼ αὐτῶν ὑψηλότερον ἔχοντα. ἔπειτʼ ἀναβλέψαι μὲν εἰς τὴν δύσιν, θεάσασθαι δὲ τράγον ἀπʼ αὐτῆς διʼ ἀέρος φερόμενον συρράξαντα τῷ κριῷ καὶ τοῖς κέρασι ῥήξαντα δὶς καταβαλεῖν αὐτὸν ἐπὶ τὴν γῆν καὶ πατῆσαι."},{"number":271,"text":"εἶτα τὸν τράγον ἰδεῖν ἐκ τοῦ μετώπου μέγιστον ἀναφύσαντα κέρας, οὗ κλασθέντος ἀναβλαστῆσαι τέσσαρα καθʼ ἕκαστον τῶν ἀνέμων τετραμμένα. ἐξ αὐτῶν δʼ ἀνασχεῖν καὶ ἄλλο μικρότερον ἀνέγραψεν, ὃ αὐξῆσαν ἔλεγεν αὐτῷ ὁ ταῦτα ἐπιδεικνὺς θεὸς πολεμήσειν αὐτοῦ τὸ ἔθνος καὶ τὴν πόλιν ἀναιρήσειν κατὰ κράτος, καὶ συγχεεῖν τὰ περὶ τὸν ναὸν καὶ τὰς θυσίας κωλύσειν γενέσθαι ἐπὶ ἡμέρας χιλίας διακοσίας ἐνενήκοντα ἕξ."},{"number":272,"text":"ταῦτα μὲν ἰδεῖν ἐν τῷ πεδίῳ τῷ ἐν Σούσοις ὁ Δανίηλος ἔγραψε, κρῖναι δʼ αὐτὸν τὴν ὄψιν τοῦ φαντάσματος ἐδήλου τὸν θεὸν οὕτως· τὸν μὲν κριὸν βασιλείας τὰς Μήδων καὶ Περσῶν σημαίνειν ἔφασκε, τὰ δὲ κέρατα τοὺς βασιλεύειν μέλλοντας, τὸ δὲ ἔσχατον κέρας σημαίνειν τὸν ἔσχατον βασιλέα· τοῦτον γὰρ διοίσειν ἁπάντων πλούτῳ τε καὶ δόξῃ."},{"number":273,"text":"τὸν δὲ τράγον δηλοῦν, ὡς ἐκ τῶν Ἑλλήνων τις βασιλεύων ἔσται, ὃς τῷ Πέρσῃ συμβαλὼν δὶς κρατήσει τῇ μάχῃ καὶ παραλήψεται τὴν ἡγεμονίαν ἅπασαν."},{"number":274,"text":"δηλοῦσθαι δʼ ὑπὸ τοῦ μεγάλου κέρατος τοῦ ἐν τῷ μετώπῳ τοῦ τράγου τὸν πρῶτον βασιλέα καὶ τὴν τῶν τεσσάρων ἀναβλάστησιν ἐκπεσόντος ἐκείνου καὶ τὴν πρὸς τὰ τέσσαρα κλίματα τῆς γῆς αὐτῶν ἀποστροφὴν ἑκάστου τοὺς διαδόχους μετὰ τὸν θάνατον τοῦ πρώτου βασιλέως ἐμφανίζεσθαι καὶ διαμερισμὸν εἰς αὐτοὺς τῆς βασιλείας, οὔτε δὲ παῖδας αὐτοῦ τούτους ὄντας οὔτε συγγενεῖς, πολλοῖς ἔτεσιν ἄρξειν τῆς οἰκουμένης."},{"number":275,"text":"γενήσεσθαι δʼ ἐκ τούτων τινὰ βασιλέα τὸν ἐκπολεμήσοντα τό τε ἔθνος καὶ τοὺς νόμους αὐτῶν καὶ τὴν κατὰ τούτους ἀφαιρησόμενον πολιτείαν καὶ συλήσοντα τὸν ναὸν καὶ τὰς θυσίας ἐπʼ ἔτη τρία κωλύσοντα ἐπιτελεσθῆναι."},{"number":276,"text":"καὶ δὴ ταῦτα ἡμῶν συνέβη παθεῖν τῷ ἔθνει ὑπὸ Ἀντιόχου τοῦ Ἐπιφανοῦς, καθὼς εἶδεν ὁ Δανίηλος καὶ πολλοῖς ἔτεσιν ἔμπροσθεν ἀνέγραψε τὰ γενησόμενα. τὸν αὐτὸν δὲ τρόπον ὁ Δανίηλος καὶ περὶ τῆς Ῥωμαίων ἡγεμονίας ἀνέγραψε, καὶ ὅτι ὑπʼ αὐτῶν ἐρημωθήσεται."},{"number":277,"text":"ταῦτα πάντα ἐκεῖνος θεοῦ δείξαντος αὐτῷ συγγράψας κατέλειψεν· ὥστε τοὺς ἀναγινώσκοντας καὶ τὰ συμβαίνοντα σκοποῦντας θαυμάζειν ἐπὶ τῇ παρὰ θεοῦ τιμῇ τὸν Δανίηλον καὶ τοὺς Ἐπικουρείους ἐκ τούτων εὑρίσκειν πεπλανημένους,"},{"number":278,"text":"οἳ τήν τε πρόνοιαν ἐκβάλλουσι τοῦ βίου καὶ θεὸν οὐκ ἀξιοῦσιν ἐπιτροπεύειν τῶν πραγμάτων, οὐδʼ ὑπὸ τῆς μακαρίας καὶ ἀφθάρτου πρὸς διαμονὴν τῶν ὅλων οὐσίας κυβερνᾶσθαι τὰ σύμπαντα, ἄμοιρον δὲ ἡνιόχου καὶ ἀφρόντιστον τὸν κόσμον αὐτομάτως φέρεσθαι λέγουσιν."},{"number":279,"text":"ὃς εἰ τοῦτον ἀπροστάτητος ἦν τὸν τρόπον, καθάπερ καὶ τὰς ναῦς ἐρήμους κυβερνητῶν καταδυομένας ὁρῶμεν ὑπὸ πνευμάτων ἢ καὶ τὰ ἅρματα περιτρεπόμενα μὴ ἔχοντα τοὺς ἡνιοχοῦντας, συντριβεὶς ἂν ὑπὸ τῆς ἀπρονοήτου συμφορᾶς ἀπωλώλει καὶ διεφθείρετο."},{"number":280,"text":"τοῖς οὖν προειρημένοις ὑπὸ Δανιήλου δοκοῦσί μοι σφόδρα τῆς ἀληθοῦς δόξης διαμαρτάνειν οἱ τῷ θεῷ μηδεμίαν εἶναι περὶ τῶν ἀνθρωπίνων ἀποφαινόμενοι πρόνοιαν· οὐ γὰρ ἂν κατὰ τὴν ἐκείνου προφητείαν, εἰ συνέβαινεν αὐτοματισμῷ τινι τὸν κόσμον διάγειν, πάντα ἑωρῶμεν ἀποβαίνοντα."},{"number":281,"text":"ἐγὼ μὲν περὶ τούτων ὡς εὗρον καὶ ἀνέγνων οὕτως ἔγραψα· εἰ δέ τις ἄλλως δοξάζειν βουλήσεται περὶ αὐτῶν, ἀνέγκλητον ἐχέτω τὴν ἑτερογνωμοσύνην."}]},"count":281};a[11]={"book":11,"title":"Τάδε ἔνεστιν ἐν τῇ ἑνδεκάτῃ τῶν Ἰωσήπου ἱστοριῶν τῆς Ἰουδαϊκῆς ἀρχαιολογίας.","argument":{"title":"","text":"Ὡς Κῦρος ὁ Περσῶν βασιλεὺς τοὺς Ἰουδαίους ἀπολύσας ἐκ Βαβυλῶνος εἰς τὴν οἰκείαν ἐπέτρεψεν αὐτοῖς οἰκοδομῆσαι τὸν ναὸν δοὺς αὐτοῖς χρήματα.\n\nὅτι διεκώλυσαν αὐτοὺς οἱ τοῦ βασιλέως ἡγεμόνες κατασκευάσαι τὸ ἱερὸν ἐμποδὼν γενόμενοι τοῖς ἔργοις.\n\nὡς Κύρου τελευτήσαντος Καμβύσης ὁ παῖς αὐτοῦ παραλαβὼν τὴν ἡγεμονίαν ἐκ παντὸς ἀπηγόρευσε τοῖς Ἰουδαίοις οἰκοδομῆσαι τὸν ναόν.\n\nὅτι Δαρεῖος ὁ Ὑστάσπεω βασιλεύσας Περσῶν ἐτίμησεν τὸ τῶν Ἰουδαίων ἔθνος καὶ τὸν ναὸν αὐτῶν ἀνῳκοδόμησεν.\n\nὡς μετ' αὐτὸν καὶ ὁ παῖς αὐτοῦ Ξέρξης οἰκείως πρὸς τοὺς Ἰουδαίους διετέθη.\n\nὅτι βασιλεύοντος Ἀρταξέρξου Ἰουδαίων πᾶν τὸ ἔθνος ἐκινδύνευσεν.\n\nὡς Βαγώας ὁ Ἀρταξέρξου τοῦ νεωτέρου στρατηγὸς πολλὰ εἰς τοὺς Ἰουδαίους ἐξύβρισεν.\n\nὡς ὁ Μακεδόνων βασιλεὺς Ἀλέξανδρος εὐεργέτησεν αὐτοὺς κρατήσας τῆς Ἰουδαίας.\n\nπεριέχει ἡ βίβλος χρόνον ἐτῶν σμγ μηνῶν ε."},"chapters":{"1":[{"number":1,"text":"Τῷ δὲ πρώτῳ τῆς Κύρου βασιλείας ἔτει, τοῦτο δʼ ἦν ἑβδομηκοστὸν ἀφʼ ἧς ἡμέρας μεταναστῆναι τὸν λαὸν ἡμῶν ἐκ τῆς οἰκείας εἰς Βαβυλῶνα συνέπεσεν, ἠλέησεν ὁ θεὸς τὴν αἰχμαλωσίαν καὶ τὴν συμφορὰν ἐκείνων τῶν ταλαιπώρων, καὶ καθὼς προεῖπεν αὐτοῖς διὰ Ἱερεμίου τοῦ προφήτου πρὶν ἢ κατασκαφῆναι τὴν πόλιν,"},{"number":2,"text":"ὡς μετὰ τὸ δουλεῦσαι Ναβουχοδονοσόρῳ καὶ τοῖς ἐκγόνοις αὐτοῦ καὶ ταύτην ὑπομεῖναι τὴν δουλείαν ἐπὶ ἔτη ἑβδομήκοντα πάλιν αὐτοὺς εἰς τὴν πάτριον ἀποκαταστήσει γῆν καὶ τὸν ναὸν οἰκοδομήσουσι καὶ τῆς ἀρχαίας ἀπολαύσουσιν εὐδαιμονίας, ταῦτʼ αὐτοῖς παρέσχεν."},{"number":3,"text":"παρορμήσας γὰρ τὴν Κύρου ψυχὴν ἐποίησεν αὐτὸν γράψαι κατὰ πᾶσαν τὴν Ἀσίαν, ὅτι Κῦρος ὁ βασιλεὺς λέγει· ἐπεί με ὁ θεὸς ὁ μέγιστος τῆς οἰκουμένης ἀπέδειξε βασιλέα, πείθομαι τοῦτον εἶναι, ὃν τὸ τῶν Ἰσραηλιτῶν ἔθνος προσκυνεῖ."},{"number":4,"text":"καὶ γὰρ τοὐμὸν προεῖπεν ὄνομα διὰ τῶν προφητῶν, καὶ ὅτι τὸν ναὸν αὐτοῦ οἰκοδομήσω ἐν Ἱεροσολύμοις ἐν τῇ Ἰουδαίᾳ χώρᾳ."},{"number":5,"text":"Ταῦτα δʼ ἔγνω Κῦρος ἀναγινώσκων τὸ βιβλίον, ὃ τῆς αὐτοῦ προφητείας ὁ Ἡσαΐας κατέλιπεν πρὸ ἐτῶν διακοσίων καὶ δέκα· οὗτος γὰρ ἐν ἀπορρήτῳ εἶπε ταῦτα λέγειν τὸν θεόν, ὅτι βούλομαι Κῦρον ἐγὼ πολλῶν ἐθνῶν καὶ μεγάλων ἀποδείξας βασιλέα πέμψαι μου τὸν λαὸν εἰς τὴν ἰδίαν γῆν καὶ οἰκοδομῆσαί μου τὸν ναόν."},{"number":6,"text":"ταῦτα Ἡσαΐας προεφήτευσεν ἔμπροσθεν ἢ κατασκαφῆναι τὸν ναὸν ἔτεσιν ἑκατὸν καὶ τεσσαράκοντα. ταῦτʼ οὖν ἀναγνόντα τὸν Κῦρον καὶ θαυμάσαντα τὸ θεῖον ὁρμή τις ἔλαβεν καὶ φιλοτιμία ποιῆσαι τὰ γεγραμμένα, καὶ καλέσας τοὺς ἐπιφανεστάτους τῶν ἐν Βαβυλῶνι Ἰουδαίων συγχωρεῖν αὐτοῖς ἔφη βαδίζειν εἰς τὴν αὐτῶν πατρίδα καὶ ἀναστῆσαί τε τὴν πόλιν Ἱεροσόλυμα καὶ τὸν τοῦ θεοῦ ναόν·"},{"number":7,"text":"ἔσεσθαι γὰρ αὐτοῖς καὶ τοῦτον σύμμαχον αὐτόν τε γράψειν τοῖς γειτονεύουσιν ἐκείνῃ τῇ χώρᾳ τῶν ἰδίων ἡγεμόνων καὶ σατραπῶν, ἵνα συμβάλωνται χρυσὸν αὐτοῖς καὶ ἄργυρον εἰς τὴν οἰκοδομίαν τοῦ ναοῦ καὶ πρὸς τούτοις θρέμματα πρὸς τὰς θυσίας."},{"number":8,"text":"Ταῦτα Κύρου καταγγείλαντος τοῖς Ἰσραηλίταις ἐξώρμησαν οἱ τῶν δύο φυλῶν ἄρχοντες τῆς Ἰούδα καὶ Βενιαμίτιδος οἵ τε Λευῖται καὶ οἱ ἱερεῖς εἰς τὰ Ἱεροσόλυμα. πολλοὶ γὰρ κατέμειναν ἐν τῇ Βαβυλῶνι τὰ κτήματα καταλιπεῖν οὐ θέλοντες."},{"number":9,"text":"καὶ παραγενομένοις αὐτοῖς οἱ τοῦ βασιλέως φίλοι πάντες ἐβοήθουν καὶ συνεισέφερον εἰς τὴν τοῦ ναοῦ κατασκευὴν οἱ μὲν χρυσὸν οἱ δʼ ἄργυρον οἱ δὲ βοσκημάτων πλῆθος σὺν ἵπποις. καὶ τάς τε εὐχὰς ἀπεδίδοσαν τῷ θεῷ καὶ τὰς νομιζομένας κατὰ τὸ παλαιὸν θυσίας ἐπετέλουν, ὥσπερ ἀνακτιζομένης αὐτοῖς τῆς πόλεως καὶ ἀναβιούσης τῆς ἀρχαίας περὶ τὴν θρησκείαν συνηθείας."},{"number":10,"text":"ἀπέπεμψε δʼ αὐτοῖς Κῦρος καὶ τὰ σκεύη τοῦ θεοῦ, ἃ συλήσας τὸν ναὸν ὁ βασιλεὺς Ναβουχοδονόσορος εἰς τὴν Βαβυλῶνα ἐκόμισεν."},{"number":11,"text":"παρέδωκεν δὲ ταῦτα φέρειν Μιθριδάτῃ τῷ γαζοφύλακι αὐτοῦ προστάξας δοῦναι αὐτὰ Ἀβεσσάρῳ, ὅπως φυλάττῃ μέχρι τῆς οἰκοδομίας τοῦ ναοῦ, τελεσθέντος δὲ αὐτοῦ παραδῷ τοῖς ἱερεῦσιν καὶ ἄρχουσιν τοῦ πλήθους εἰς τὸν ναὸν ἀποθησομένοις."},{"number":12,"text":"πέμπει δὲ καὶ ἐπιστολὴν πρὸς τοὺς ἐν Συρίᾳ σατράπας Κῦρος τάδε λέγουσαν· βασιλεὺς Κῦρος Σισίνῃ καὶ Σαραβασάνῃ χαίρειν. Ἰουδαίων τῶν ἐν τῇ ἐμῇ χώρᾳ κατοικούντων ἐπέτρεψα τοῖς βουλομένοις εἰς τὴν ἰδίαν ἀπελθοῦσι πατρίδα τήν τε πόλιν ἀνακτίζειν καὶ τὸν ναὸν οἰκοδομῆσαι τὸν ἐν Ἱεροσολύμοις τοῦ θεοῦ ἐπὶ τοῦ αὐτοῦ τόπου, ἐφʼ οὗ καὶ πρότερον."},{"number":13,"text":"κατέπεμψα δέ μου καὶ τὸν γαζοφύλακα Μιθριδάτην καὶ Ζοροβάβηλον τὸν ἄρχοντα τῶν Ἰουδαίων, ἵνα θεμελίους βάλωνται τοῦ ναοῦ καὶ οἰκοδομήσωσιν αὐτὸν ὕψος μὲν ἑξήκοντα πηχῶν τῶν δʼ αὐτῶν καὶ τὸ εὖρος, λίθου μὲν ξεστοῦ τρεῖς ποιησάμενοι δόμους καὶ ἕνα ξύλινον ἐγχώριον, ὁμοίως δὲ καὶ θυσιαστήριον, ἐφʼ οὗ θύσουσιν τῷ θεῷ."},{"number":14,"text":"τὴν δὲ εἰς ταῦτα δαπάνην ἐκ τῶν ἐμαυτοῦ γενέσθαι βούλομαι. καὶ τὰ σκεύη δέ, ἃ ἐσύλησεν ἐκ τοῦ ναοῦ Ναβουχοδονόσορος ὁ βασιλεύς, ἔπεμψα παραδοὺς Μιθριδάτῃ τῷ γαζοφύλακι καὶ Ζοροβαβήλῳ τῷ ἄρχοντι τῶν Ἰουδαίων, ἵνα διακομίσωσιν εἰς Ἱεροσόλυμα καὶ ἀποκαταστήσωσιν εἰς τὸν ναὸν τοῦ θεοῦ."},{"number":15,"text":"ὁ δʼ ἀριθμὸς αὐτῶν ἐστιν τοσοῦτος· ψυκτῆρες χρύσεοι πεντήκοντα, ἀργύρεοι τετρακόσιοι, θηρίκλεια χρύσεα πεντήκοντα, ἀργύρεα τετρακόσια, κάδοι χρύσεοι πεντήκοντα, ἀργύρεοι πεντακόσιοι, σπονδεῖα χρύσεα τεσσαράκοντα, ἀργύρεα τριακόσια, φιάλαι χρυσαῖ τριάκοντα, ἀργύρεαι δισχίλιαι τετρακόσιαι, σκεύη τε ἄλλα μεγάλα χίλια."},{"number":16,"text":"συγχωρῶ δὲ αὐτοῖς καὶ τὴν ἐκ προγόνων εἰθισμένην τιμὴν κτηνῶν καὶ οἴνου καὶ ἐλαίου δραχμὰς εἴκοσιν μυριάδας καὶ πεντακισχιλίας πεντακοσίας καὶ εἰς σεμίδαλιν πυρῶν ἀρτάβας δισμυρίας πεντακοσίας. κελεύω δὲ τὴν τούτων χορηγίαν ἐκ τῶν Σαμαρείας γίνεσθαι φόρων."},{"number":17,"text":"ἐποίσουσι δὲ τὰ ἱερὰ ταῦτα κατὰ τοὺς Μωυσέως νόμους οἱ ἱερεῖς ἐν Ἱεροσολύμοις καὶ προσφέροντες εὔξονται τῷ θεῷ περὶ σωτηρίας τε τοῦ βασιλέως καὶ τοῦ γένους αὐτοῦ, ὅπως ἡ Περσῶν βασιλεία διαμείνῃ. τοὺς δὲ παρακούσαντας τούτων καὶ ἀκυρώσαντας ἀνασταυρωθῆναι βούλομαι καὶ τὰς οὐσίας αὐτῶν εἶναι βασιλικάς."},{"number":18,"text":"καὶ ἡ μὲν ἐπιστολὴ ταῦτα ἐδήλου· τῶν δʼ ἐκ τῆς αἰχμαλωσίας συνελθόντων εἰς Ἱεροσόλυμα μυριάδες ἦσαν τέσσαρες καὶ δισχίλιοι τετρακόσιοι ἑξήκοντα δύο."}],"2":[{"number":19,"text":"Βαλλομένων δὲ τοὺς θεμελίους τοῦ ναοῦ καὶ περὶ τὴν οἰκοδομίαν αὐτοῦ λίαν ἐσπουδακότων, τὰ πέριξ ἔθνη καὶ μάλιστα τὸ Χουθαίων, οὓς ἐκ τῆς Περσίδος καὶ Μηδικῆς ἀγαγὼν Σαλμανασσάρης ὁ τῶν Ἀσσυρίων βασιλεὺς κατῴκισεν ἐν Σαμαρείᾳ, ὅτε τὸν τῶν Ἰσραηλιτῶν λαὸν ἀνάστατον ἐποίησεν, παρεκάλουν τοὺς σατράπας καὶ τοὺς ἐπιμελουμένους ἐμποδίζειν τοὺς Ἰουδαίους πρός τε τὴν τῆς πόλεως ἀνάστασιν καὶ τὴν τοῦ ναοῦ κατασκευήν."},{"number":20,"text":"οἱ δὲ καὶ χρήμασιν διαφθαρέντες ὑπʼ αὐτῶν ἀπημπόλησαν τοῖς Χουθαίοις τὸ περὶ τοὺς Ἰουδαίους ἀμελὲς καὶ ῥᾴθυμον τῆς οἰκοδομῆς· Κύρῳ γὰρ περί τε ἄλλους ἀσχοληθέντι πολέμους ἄγνοια τούτων ἦν καὶ στρατευσαμένῳ γε ἐπὶ Μασσαγέτας εὐθὺς συνέβη τελευτῆσαι τὸν βίον."},{"number":21,"text":"Καμβύσου δὲ τοῦ Κύρου παιδὸς τὴν βασιλείαν παραλαβόντος οἱ ἐν Συρίᾳ καὶ Φοινίκῃ καὶ Ἀμμανίτιδι καὶ Μωαβίτιδι καὶ Σαμαρείᾳ γράφουσιν ἐπιστολὴν Καμβύσῃ δηλοῦσαν τάδε·"},{"number":22,"text":"δέσποτα, οἱ παῖδές σου Ῥάθυμος ὁ πάντα τὰ πραττόμενα γράφων καὶ Σεμέλιος ὁ γραμματεὺς καὶ οἱ τῆς βουλῆς τῆς ἐν Συρίᾳ καὶ Φοινίκῃ κριταί. γινώσκειν σε δεῖ, βασιλεῦ, ὅτι Ἰουδαῖοι οἱ εἰς Βαβυλῶνα ἀναχθέντες ἐληλύθασιν εἰς τὴν ἡμετέραν καὶ τήν τε πόλιν τὴν ἀποστάτιν καὶ πονηρὰν οἰκοδομοῦσιν καὶ τὰς ἀγορὰς αὐτῆς καὶ ἐπισκευάζουσιν τὰ τείχη καὶ ναὸν ἀνεγείρουσιν."},{"number":23,"text":"ἴσθι μέντοι γε τούτων γενομένων οὔτε φόρους αὐτοὺς τελεῖν ὑπομενοῦντας οὔτε δὲ ὑπακούειν ἐθελήσοντας, ἀλλὰ καὶ βασιλεῦσιν ἀντιστήσονται καὶ ἄρχειν μᾶλλον ἢ ὑπακούειν ἐθελήσουσιν."},{"number":24,"text":"ἐνεργουμένων οὖν τῶν περὶ τὸν ναὸν καὶ σπουδαζομένων καλῶς ἔχειν ἔδοξεν ἡμῖν γράψαι σοι, βασιλεῦ, καὶ μὴ περιιδεῖν, ὅπως ἐπισκέψῃ τὰ τῶν πατέρων σου βιβλία· εὑρήσεις γὰρ ἐν αὐτοῖς ἀποστάτας καὶ τῶν βασιλέων ἐχθροὺς Ἰουδαίους καὶ τὴν πόλιν αὐτῶν, ἣ διὰ τοῦτο καὶ νῦν ἠρημώθη."},{"number":25,"text":"ἔδοξε δʼ ἡμῖν καὶ τοῦτό σοι δηλῶσαι ἀγνοούμενον ἴσως, ὅτι τῆς πόλεως οὕτως συνοικισθείσης καὶ τὸν κύκλον τῶν τειχῶν ἀπολαβούσης ἀποκλείεταί σοι ἡ ὁδὸς ἡ ἐπὶ κοίλην Συρίαν καὶ Φοινίκην."},{"number":26,"text":"Ἀναγνοὺς δὲ ὁ Καμβύσης τὴν ἐπιστολὴν καὶ φύσει πονηρὸς ὢν κινεῖται πρὸς τὰ δεδηλωμένα καὶ γράφει τάδε λέγων· βασιλεὺς Καμβύσης Ῥαθύμῳ τῷ γράφοντι τὰ προσπίπτοντα καὶ Βεελζέμῳ καὶ Σεμελίῳ γραμματεῖ καὶ τοῖς λοιποῖς τοῖς συντασσομένοις καὶ οἰκοῦσιν ἐν Σαμαρείᾳ καὶ Φοινίκῃ τάδε λέγει."},{"number":27,"text":"ἀναγνοὺς τὰ πεμφθέντα παρʼ ὑμῶν γράμματα ἐκέλευσα ἐπισκέψασθαι τὰ τῶν προγόνων μου βιβλία, καὶ εὑρέθη ἡ πόλις ἐχθρὰ βασιλεῦσιν ἀεὶ γεγενημένη, καὶ στάσεις καὶ πολέμους οἱ ἐνοικοῦντες πραγματευσάμενοι, καὶ βασιλεῖς αὐτῶν ἔγνωμεν δυνατοὺς καὶ βιαίους φορολογήσαντας κοίλην Συρίαν καὶ Φοινίκην."},{"number":28,"text":"ἐγὼ τοίνυν προσέταξα μὴ συγχωρεῖν τοῖς Ἰουδαίοις οἰκοδομεῖν τὴν πόλιν, μὴ ἐπὶ πλέον αὐξηθῇ τὰ τῆς κακίας αὐτῶν, ᾗ χρώμενοι πρὸς τοὺς βασιλεῖς διατετελέκασιν."},{"number":29,"text":"τούτων ἀναγνωσθέντων τῶν γραμμάτων ὁ Ῥάθυμος καὶ Σεμέλιος ὁ γραμματεὺς καὶ οἱ τούτοις συντεταγμένοι παραχρῆμα ἐπιπηδήσαντες ἵπποις ἔσπευσαν εἰς Ἱεροσόλυμα πλῆθος ἐπαγόμενοι πολύ, καὶ διεκώλυσαν οἰκοδομεῖν τοὺς Ἰουδαίους τὴν πόλιν καὶ τὸν ναόν."},{"number":30,"text":"καὶ ταῦτα μὲν ἐπεσχέθη τὰ ἔργα μέχρι τοῦ δευτέρου ἔτους τῆς Δαρείου βασιλείας τοῦ Περσῶν ἐπʼ ἄλλα ἔτη ἐννέα· Καμβύσης γὰρ ἓξ ἔτη βασιλεύσας, καταστρεψάμενος ἐν τούτοις τὴν Αἴγυπτον ὑποστρέψας ἐτελεύτησεν ἐν Δαμασκῷ."}],"3":[{"number":31,"text":"Μετὰ δὲ τὴν τῶν μάγων ἀναίρεσιν, οἳ μετὰ τὸν Καμβύσου θάνατον τὴν Περσῶν ἀρχὴν ἐνιαυτῷ κατέσχον οἱ λεγόμενοι ἑπτὰ οἶκοι τῶν Περσῶν τὸν Ὑστάσπου παῖδα Δαρεῖον ἀπέδειξαν βασιλέα. οὗτος ἰδιώτης ὢν ηὔξατο τῷ θεῷ, εἰ γένοιτο βασιλεύς, πάντα τὰ σκεύη τοῦ θεοῦ, ὅσα ἦν ἔτι ἐν Βαβυλῶνι, πέμψειν εἰς τὸν ναὸν τὸν ἐν Ἱεροσολύμοις."},{"number":32,"text":"ἔτυχεν δὲ κατʼ ἐκεῖνον τὸν καιρὸν ἀφικόμενος πρὸς Δαρεῖον ἐξ Ἱεροσολύμων Ζοροβάβηλος, ὃς τῶν αἰχμαλώτων Ἰουδαίων ἡγεμὼν ἀπεδέδεικτο· πάλαι γὰρ ἦν αὐτῷ φιλία πρὸς τὸν βασιλέα, διʼ ἣν καὶ σωματοφυλακεῖν αὐτὸν μετʼ ἄλλων δύο κριθεὶς ἄξιος ἀπέλαυεν ἧς ἤλπισεν τιμῆς."},{"number":33,"text":"Τῷ δὲ πρώτῳ τῆς βασιλείας ἔτει Δαρεῖος ὑποδέχεται λαμπρῶς καὶ μετὰ πολλῆς παρασκευῆς τούς τε περὶ αὐτὸν καὶ τοὺς οἴκοι γεγονότας καὶ τοὺς τῶν Μήδων ἡγεμόνας καὶ σατράπας τῆς Περσίδος καὶ τοπάρχας τῆς Ἰνδικῆς ἄχρι τῆς Αἰθιοπίας καὶ τοὺς στρατηγοὺς τῶν ἑκατὸν εἰκοσιεπτὰ σατραπειῶν."},{"number":34,"text":"ἐπεὶ δὲ κατευωχηθέντες ἄχρι κόρου καὶ πλησμονῆς ἀνέλυσαν κοιμηθησόμενοι παρʼ αὐτοὺς ἕκαστοι, Δαρεῖος ὁ βασιλεὺς ἐλθὼν ἐπὶ τὴν κοίτην καὶ βραχὺ τῆς νυκτὸς ἀναπαυσάμενος ἔξυπνος γίνεται, καὶ μηκέτι κατακοιμηθῆναι δυνάμενος εἰς ὁμιλίαν τρέπεται μετὰ τῶν τριῶν σωματοφυλάκων,"},{"number":35,"text":"καὶ τῷ λόγον ἐροῦντι περὶ ὧν αὐτὸς ἀνακρίνειν μέλλει τὸν ἀληθέστερον καὶ συνετώτερον, τούτῳ γέρας δώσειν ὑπισχνεῖται νικητήριον πορφύραν ἐνδύσασθαι καὶ ἐν ἐκπώμασιν χρυσοῖς πίνειν καὶ ἐπὶ χρυσίου καθεύδειν καὶ ἅρμα χρυσοχάλινον καὶ κίδαριν βύσσινον καὶ περιαυχένιον χρύσεον, καὶ μετʼ αὐτὸν ἕξειν προεδρίαν διὰ τὴν σοφίαν καὶ συγγενής μου , ἔφη, κληθήσεται."},{"number":36,"text":"ταύτας ἐπαγγειλάμενος αὐτοῖς παρέξειν τὰς δωρεὰς ἐρωτᾷ μὲν τὸν πρῶτον, εἰ ὁ οἶνος ὑπερισχύει, τὸν δεύτερον δέ, εἰ οἱ βασιλεῖς, τὸν τρίτον δέ, εἰ αἱ γυναῖκες ἢ τούτων μᾶλλον ἡ ἀλήθεια. ταῦτα προθεὶς αὐτοῖς ζητεῖν ἡσύχασεν."},{"number":37,"text":"ὄρθρου δὲ μεταπεμψάμενος τοὺς μεγιστᾶνας καὶ σατράπας καὶ τοπάρχας τῆς Περσίδος καὶ Μηδικῆς καὶ καθίσας ἐν ᾧ χρηματίζειν εἰώθει, τῶν σωματοφυλάκων ἕκαστον ἐκέλευσεν πάντων ἀκουόντων ἀποφαίνεσθαι τὸ δοκοῦν αὐτῷ περὶ τῶν προκειμένων."},{"number":38,"text":"Καὶ ὁ πρῶτος ἤρξατο λέγειν τὴν τοῦ οἴνου δύναμιν οὕτως αὐτὴν ἐμφανίζων· ἄνδρες γὰρ εἶπεν, ἐγὼ τὴν ἰσχὺν τοῦ οἴνου τεκμαιρόμενος πάντα ὑπερβάλλουσαν εὑρίσκω τούτῳ τῷ τρόπῳ·"},{"number":39,"text":"σφάλλει γὰρ τῶν πινόντων αὐτὸν καὶ ἀπατᾷ τὴν διάνοιαν καὶ τὴν τοῦ βασιλέως τῇ τοῦ ὀρφανοῦ καὶ δεομένου κηδεμόνος ὁμοίαν τίθησιν, καὶ τὴν τοῦ δούλου διεγείρει πρὸς παρρησίαν τοῦ ἐλευθέρου, ἥ τε τοῦ πένητος ὁμοία γίνεται τῇ τοῦ πλουσίου·"},{"number":40,"text":"μεταποιεῖ γὰρ καὶ μεταγεννᾷ τὰς ψυχὰς ἐν αὐταῖς ἐγγενόμενος, καὶ τῶν μὲν ἐν συμφορᾷ καθεστηκότων σβέννυσι τὸ λυποῦν, τοὺς δὲ ἀλλότρια χρέα λαβόντας εἰς λήθην ἄγει καὶ ποιεῖ δοκεῖν αὐτοὺς ἁπάντων πλουσιωτάτους, ὡς μηδὲν μικρὸν φθέγγεσθαι, ταλάντων δὲ μεμνῆσθαι καὶ τῶν τοῖς εὐδαίμοσι προσηκόντων ὀνομάτων."},{"number":41,"text":"ἔτι γε μὴν στρατηγῶν καὶ βασιλέων ἀναισθήτους ἀπεργάζεται καὶ φίλων καὶ συνήθων ἐξαιρεῖ μνήμην· ὁπλίζει γὰρ τοὺς ἀνθρώπους καὶ κατὰ τῶν φιλτάτων καὶ δοκεῖν ποιεῖ πάντων ἀλλοτριωτάτους."},{"number":42,"text":"καὶ ὅταν νήψαντες τύχωσιν καὶ καταλίπῃ διὰ τῆς νυκτὸς αὐτοὺς ὁ οἶνος κοιμωμένους, ἀνίστανται μηθὲν ὧν ἔπραξαν παρὰ τὴν μέθην εἰδότες. τούτοις ἐγὼ τεκμαιρόμενος εὑρίσκω τὸν οἶνον ὑπερκρατοῦντα πάντων καὶ βιαιότατον."},{"number":43,"text":"Ὡς δὲ ὁ πρῶτος ἀποφηνάμενος περὶ τῆς ἰσχύος τοῦ οἴνου τὰ προειρημένα ἐπαύσατο, ὁ μετʼ αὐτὸν ἤρξατο λέγειν περὶ τῆς τοῦ βασιλέως δυνάμεως, ταύτην ἀποδεικνὺς τὴν ἰσχυροτάτην καὶ πλέον τῶν ἄλλων δυναμένην, ὅσα βίαν ἔχειν ἢ σύνεσιν δοκεῖ. τὸν δὲ τρόπον τῆς ἀποδείξεως ἐντεῦθεν ἐλάμβανεν·"},{"number":44,"text":"πάντων μὲν εἶπεν ἀνθρώπους περικρατεῖν, οἳ καὶ τὴν γῆν καταναγκάζουσιν καὶ τὴν θάλασσαν εἶναι χρησίμην αὐτοῖς πρὸς ἃ θέλουσιν, τούτων δʼ ἄρχουσιν οἱ βασιλεῖς καὶ τὴν ἐξουσίαν ἔχουσιν· οἱ δὲ τοῦ κρατίστου καὶ ἰσχυροτάτου ζῴου δεσπόζοντες ἀνυπέρβλητοι τὴν δύναμιν οὗτοι καὶ τὴν ἰσχὺν εἰκότως ἂν εἶεν."},{"number":45,"text":"ἀμέλει πολέμους ἐπιτάττοντες καὶ κινδύνους τοῖς ἀρχομένοις ἀκούονται, καὶ πέμποντες αὐτοὺς ἐπʼ ἐχθροὺς καταπειθεῖς διὰ τὴν ἰσχὺν τὴν αὐτῶν ἔχουσιν, καὶ ὄρη μὲν κατεργάζεσθαι καὶ τείχη κατασπᾶν καὶ πύργους κελεύουσιν, καὶ κτείνεσθαι δʼ οἱ κελευσθέντες καὶ κτείνειν ὑπομένουσιν, ἵνα μὴ τὰ τοῦ βασιλέως δόξωσι παραβαίνειν προστάγματα, νικήσαντες δὲ τὴν ὠφέλειαν τὴν ἐκ τοῦ πολέμου τῷ βασιλεῖ κομίζουσιν."},{"number":46,"text":"καὶ οἱ μὴ στρατευόμενοι δὲ ἀλλὰ γῆν ἐργαζόμενοι καὶ ἀροῦντες ὅταν πονήσαντες καὶ ἅπασαν τὴν τῶν ἔργων ταλαιπωρίαν ὑπομείναντες θερίσωσιν καὶ τοὺς καρποὺς συνέλωσιν, τοὺς φόρους τῷ βασιλεῖ κομίζουσιν."},{"number":47,"text":"ὃ δʼ ἂν οὗτος εἴπῃ καὶ κελεύσῃ τοῦτο ἐξ ἀνάγκης οὐδὲν ὑπερβαλομένων γίνεται. ἔτι ὁ μὲν τρυφῆς ἁπάσης καὶ ἡδονῆς ἀναπιμπλάμενος καθεύδει, φυλάσσεται δὲ ὑπὸ γρηγορούντων καὶ ὡσανεὶ δεδεμένων ὑπὸ φόβου·"},{"number":48,"text":"καταλιπεῖν γὰρ οὐδὲ εἷς τολμᾷ κοιμώμενον οὐδὲ τῶν ἰδίων ἀναχωρήσας ποιεῖσθαι πρόνοιαν, ἀλλʼ ἓν ἔργον ἡγούμενος τῶν ἀναγκαίων τὸ φυλάττειν τὸν βασιλέα τούτῳ προσμένει. πῶς οὖν οὐκ ἂν ὁ βασιλεὺς δόξειεν τὴν πάντων ἰσχὺν ὑπερβάλλειν, ᾧ τοσοῦτο πλῆθος πείθεται κελεύοντι;"},{"number":49,"text":"Σιωπήσαντος δὲ καὶ τούτου περὶ τῆς τῶν γυναικῶν καὶ τῆς ἀληθείας ὁ τρίτος Ζοροβάβηλος διδάσκειν αὐτοὺς ἤρξατο λέγων οὕτως· ἰσχυρὸς μὲν καὶ ὁ οἶνος καὶ ὁ βασιλεύς, ᾧ πάντες ὑπακούουσιν, ἀλλὰ κρείττους τὴν δύναμιν τούτων αἱ γυναῖκες·"},{"number":50,"text":"τόν τε γὰρ βασιλέα γυνὴ παρήγαγεν εἰς τὸ φῶς καὶ τοὺς φυτεύσαντας ἀμπέλους, αἳ ποιοῦσιν τὸν οἶνον, γυναῖκές εἰσιν αἱ τίκτουσαί τε καὶ τρέφουσαι, καθόλου δʼ οὐδέν ἐστιν, ὃ μὴ παρʼ αὐτῶν ἔχομεν· καὶ γὰρ τὰς ἐσθῆτας αὗται ὑφαίνουσιν ἡμῖν καὶ τὰ κατʼ οἶκον διὰ ταύτας ἐπιμελείας καὶ φυλακῆς ἀξιοῦται."},{"number":51,"text":"καὶ οὐκ ἔστιν ἡμῖν ἀποζευχθῆναι γυναικῶν, ἀλλὰ χρυσὸν πολὺν κτησάμενοι καὶ ἄργυρον καὶ ἄλλο τι τῶν πολυτελῶν καὶ σπουδῆς ἀξίων, ὅταν ἴδωμεν εὔμορφον γυναῖκα, πάντα ἐκεῖνα ἀφέντες τῷ εἴδει τῆς ὁραθείσης προσκεχήναμεν καὶ ὑπομένομεν παραχωρῆσαι τῶν ὄντων ἡμῖν, ἵνα τοῦ κάλλους ἀπολαύσωμεν καὶ μεταλάβωμεν."},{"number":52,"text":"ἐγκαταλείπομεν δὲ καὶ πατέρας καὶ μητέρας καὶ τὴν θρεψαμένην γῆν, καὶ τῶν φιλτάτων πολλάκις λήθην ἔχομεν διὰ τὰς γυναῖκας, καὶ τὰς ψυχὰς ἀφιέναι μετʼ αὐτῶν καρτεροῦμεν. οὕτως δʼ ἂν μάλιστα τὴν ἰσχὺν τῶν γυναικῶν κατανοήσαιτε·"},{"number":53,"text":"οὐχὶ πονοῦντες καὶ πᾶσαν ταλαιπωρίαν ὑπομένοντες καὶ διὰ γῆς καὶ διὰ θαλάττης, ὅταν ἡμῖν ἐκ τῶν πόνων περιγένηταί τινα, αὐτὰ φέροντες ὡς δεσποίναις ταῖς γυναιξὶν διδόαμεν;"},{"number":54,"text":"καὶ τὸν βασιλέα δὲ τὸν τοσούτων κύριον εἶδόν ποτε ὑπὸ τῆς Ῥαβεζάκου τοῦ Θεμασίου παιδὸς Ἀπάμης παλλακῆς δʼ αὐτοῦ ῥαπιζόμενον, καὶ τὸ διάδημα ἀφαιρουμένης καὶ τῇ ἰδίᾳ κεφαλῇ περιτιθείσης ἀνεχόμενον καὶ μειδιώσης μὲν μειδιῶντα ὀργιζομένης δὲ σκυθρωπάζοντα καὶ τῇ τῶν παθῶν μεταβολῇ κολακεύοντα τὴν γυναῖκα καὶ διαλλάττοντα ἐκ τοῦ σφόδρα ταπεινὸν αὑτὸν ποιεῖν, εἴ ποτε δυσχεραίνουσαν ἔβλεπεν."},{"number":55,"text":"Εἰς ἀλλήλους δὲ ἀφορώντων τῶν σατραπῶν καὶ ἡγεμόνων περὶ τῆς ἀληθείας ἤρξατο λέγειν ἀπέδειξα μέν, εἰπών, ὅσον αἱ γυναῖκες ἰσχύουσιν, ἀσθενέστεραι δʼ ὅμως καὶ αὗται καὶ ὁ βασιλεὺς τῆς ἀληθείας ὑπάρχουσιν. εἰ γάρ ἐστιν ἡ γῆ μεγίστη καὶ ὑψηλὸς ὁ οὐρανὸς καὶ ταχὺς ὁ ἥλιος, ταῦτα δὲ πάντα κινεῖται κατὰ βούλησιν τοῦ θεοῦ, ἀληθινὸς δέ ἐστιν καὶ δίκαιος οὗτος, ἀπὸ τῆς αὐτῆς αἰτίας δεῖ καὶ τὴν ἀλήθειαν ἰσχυροτάτην ἡγεῖσθαι καὶ μηδὲν πρὸς αὐτὴν τὸ ἄδικον δυνάμενον."},{"number":56,"text":"ἔτι γε μὴν τὰ μὲν ἄλλα θνητὰ καὶ ὠκύμορα εἶναι συμβέβηκεν τῶν ἰσχὺν ἐχόντων, ἀθάνατον δὲ ἡ ἀλήθεια χρῆμα καὶ ἀίδιον. παρέχει δʼ ἡμῖν οὐ κάλλος χρόνῳ μαραινόμενον οὐδὲ περιουσίαν ἀφαιρετὴν ὑπὸ τύχης, ἀλλὰ τὰ δίκαια καὶ τὰ νόμιμα, διακρίνουσα ἀπʼ αὐτῶν τὰ ἄδικα καὶ ἀπελέγχουσα."},{"number":57,"text":"Καταπαύει μὲν ὁ Ζοροβάβηλος τὸν περὶ τῆς ἀληθείας λόγον, ἐπιβοήσαντος δὲ τοῦ πλήθους ὡς ἄριστα εἰπόντος, καὶ ὅτι τὸ ἀληθὲς ἰσχὺν ἄτρεπτον καὶ ἀγήρω μόνον ἔχοι, προσέταξεν αὐτὸν ὁ βασιλεὺς αἰτήσασθαί τι πάρεξ ὧν αὐτὸς ἦν ὑπεσχημένος· δώσειν γὰρ ὄντι σοφῷ καὶ τῶν ἄλλων μᾶλλον φανέντι συνετῷ· συγκαθεσθήσῃ δέ μοι, φησίν, καὶ κεκλήσῃ συγγενὴς ἐμός."},{"number":58,"text":"ταῦτʼ εἰπόντος ὑπέμνησεν αὐτὸν τῆς εὐχῆς, ἧς ἐποιήσατο, εἰ λάβοι τὴν βασιλείαν· αὕτη δʼ ἂν εἴη οἰκοδομῆσαι μὲν Ἱεροσόλυμα, κατασκευάσαι δὲ ἐν αὐτοῖς τὸν τοῦ θεοῦ ναόν, ἀποκαταστῆσαι δὲ καὶ τὰ σκεύη, ὅσα συλήσας Ναβουχοδονόσορος εἰς Βαβυλῶνα ἐκόμισεν. καὶ τοῦτʼ , ἔφη, τοὐμὸν αἴτημά ἐστιν, ὅ μοι νῦν ἐπιτρέπεις αἰτήσασθαι κριθέντι σοφῷ καὶ συνετῷ."},{"number":59,"text":"Ἡσθεὶς ἐπὶ τούτοις ὁ βασιλεὺς ἀναστὰς κατεφίλησέν τε αὐτὸν καὶ τοῖς τοπάρχαις καὶ σατράπαις γράφει κελεύων προπέμψαι τὸν Ζοροβάβηλον καὶ τοὺς σὺν αὐτῷ μέλλοντας ἐπὶ τὴν οἰκοδομὴν ἐξιέναι τοῦ ναοῦ."},{"number":60,"text":"ἐπέστειλε δὲ καὶ τοῖς ἐν Συρίᾳ καὶ Φοινίκῃ ξύλα κέδρινα κατακομίζειν ἐκ τοῦ Λιβάνου τεμόντας εἰς Ἱεροσόλυμα, καὶ συγκατασκευάζειν αὐτῷ τὴν πόλιν, καὶ πάντας ἔγραψεν ἐλευθέρους εἶναι τοὺς εἰς τὴν Ἰουδαίαν τῶν αἰχμαλώτων ἀπελθόντας."},{"number":61,"text":"καὶ τοὺς ἐπιτρόπους τοὺς αὐτοῦ καὶ σατράπας ἐκώλυσεν ἐπιτάττειν τοῖς Ἰουδαίοις τὰς βασιλικὰς χρείας, ἀνῆκέ τε πᾶσαν ἣν ἂν κατασχεῖν δυνηθῶσιν τῆς χώρας ἀτελῆ φόρων αὐτοῖς νέμεσθαι. προσέταξε δὲ καὶ τοὺς Ἰδουμαίους καὶ Σαμαρείτας καὶ τοὺς ἐκ τῆς κοίλης Συρίας ἀφεῖναι τὰς κώμας, ἃς τῶν Ἰουδαίων κατεῖχον, καὶ προσέτι τάλαντα πεντήκοντα εἰς τὴν οἰκοδομίαν τοῦ ἱεροῦ δοθῆναι."},{"number":62,"text":"θύειν τε αὐτοῖς τὰς νενομισμένας θυσίας ἐπέτρεψε καὶ τὴν χορηγίαν ἅπασαν καὶ τὴν ἱερὰν στολήν, ᾗ θεραπεύουσι τὸν θεὸν ὅ τε ἀρχιερεὺς καὶ οἱ ἱερεῖς, ἐκ τῶν ἰδίων γίνεσθαι, καὶ τοῖς Λευίταις τὰ ὄργανα,"},{"number":63,"text":"οἷς ὑμνοῦσι τὸν θεόν, καὶ τοῖς φύλαξι τῆς πόλεως καὶ τοῦ ναοῦ προσέταξεν κλήρους γῆς δοθῆναι καὶ κατὰ ἕκαστον ἔτος ὡρισμένον τι πρὸς τὴν τοῦ βίου χρείαν ἀργύριον, πέμψαι δὲ καὶ τὰ σκεύη, καὶ πάντα, ὅσα Κῦρος πρὸ αὐτοῦ ἐβουλήθη περὶ τῆς τῶν Ἰουδαίων ἀποκαταστάσεως, ταῦτα καὶ Δαρεῖος διετάξατο."},{"number":64,"text":"Τυχὼν οὖν τούτων παρὰ τοῦ βασιλέως Ζοροβάβηλος ἐξελθὼν ἀπὸ τῶν βασιλείων καὶ ἀναβλέψας εἰς τὸν οὐρανὸν εὐχαριστεῖν ἤρξατο τῷ θεῷ τῆς σοφίας καὶ τῆς ἐπʼ αὐτῇ νίκης, ἣν Δαρείου παρόντος ἔλαβεν· οὐ γὰρ ἂν τούτων ἀξιωθῆναι μὴ σοῦ"},{"number":65,"text":", φησί, δέσποτα, τυχὼν εὐμενοῦς. ταῦτʼ οὖν περὶ τῶν παρόντων εὐχαριστήσας τῷ θεῷ καὶ πρὸς τὰ μέλλοντα δεηθεὶς αὑτὸν παρέχειν ὅμοιον, ἧκεν εἰς Βαβυλῶνα καὶ τοῖς ὁμοφύλοις εὐηγγελίσατο τὰ παρὰ τοῦ βασιλέως."},{"number":66,"text":"οἱ δὲ ἀκούσαντες εὐχαριστοῦσι μὲν τῷ θεῷ πάλιν αὐτοῖς ἀποδιδόντι τὴν πάτριον γῆν, εἰς δὲ πότον καὶ κώμους τραπέντες ἐφʼ ἡμέρας ἑπτὰ διήγαγον εὐωχούμενοι καὶ τὴν ἀνάκτησιν καὶ παλιγγενεσίαν τῆς πατρίδος ἑορτάζοντες."},{"number":67,"text":"ἔπειτα τοὺς ἀναβησομένους εἰς τὰ Ἱεροσόλυμα ἡγεμόνας ἐκ τῶν πατρίων φυλῶν σὺν γυναιξὶ καὶ τέκνοις καὶ ὑποζυγίοις ἐπελέξαντο, οἳ Δαρείου συμπέμψαντος ἕως τῶν Ἱεροσολύμων ὥδευον μετὰ χαρᾶς καὶ τρυφῆς, ψαλλόμενοι καὶ καταυλούμενοι καὶ περιψοφούμενοι τοῖς κυμβάλοις. προέπεμπε δὲ αὐτοὺς καὶ τὸ ὑπολειπόμενον τῶν Ἰουδαίων πλῆθος μετὰ παιδιᾶς."},{"number":68,"text":"Καὶ οἱ μὲν οὕτως ἀπῄεσαν ἐξ ἑκάστης πατριᾶς ἀριθμὸς ὄντες ὡρισμένος. ἐμοὶ δὲ οὐκ ἔδοξε τὰ τῶν πατριῶν καταλέγειν ὀνόματα, ἵνα μὴ τὴν τῶν ἀναγινωσκόντων διάνοιαν τῆς συναφῆς τῶν πραγμάτων ἀποσπάσας δυσπαρακολούθητον αὐτοῖς ποιήσω τὴν διήγησιν."},{"number":69,"text":"τὸ δὲ κεφάλαιον τῶν ἀπερχομένων περὶ ἔτη δώδεκα τὴν ἡλικίαν γεγονότων ἐκ τῆς Ἰούδα φυλῆς καὶ Βενιαμίτιδος ἦν μυριάδες τετρακόσιαι ἑξηκονταδύο καὶ ὀκτακισχίλιοι, Λευῖται δὲ τέσσαρες καὶ ἑβδομήκοντα, γυναικῶν δὲ ἀναμὶξ καὶ νηπίων σώματα ἦν τετρακισμύρια ἑπτακόσια τεσσαρακονταδύο."},{"number":70,"text":"πάρεξ δὲ τούτων Λευῖται μὲν ἦσαν ὑμνῳδοὶ ἑκατὸν εἰκοσιοκτώ, πυλωροὶ δὲ ἑκατὸν δέκα, δοῦλοι δὲ ἱεροὶ τριακόσιοι ἐνενηκονταδύο, ἄλλοι τε πρὸς τούτοις λέγοντες μὲν εἶναι τῶν Ἰσραηλιτῶν οὐ δυνάμενοι δὲ ἐπιδεῖξαι τὸ γένος αὐτῶν ἑξακόσιοι πεντηκονταδύο."},{"number":71,"text":"ἐξεβλήθησαν δὲ καὶ τῶν ἱερέων ἐκ τῆς τιμῆς ἠγμένοι γυναῖκας, ὧν οὔτʼ αὐτοὶ τὸ γένος εἶχον εἰπεῖν οὔτʼ ἐν ταῖς γενεαλογίαις τῶν Λευιτῶν καὶ ἱερέων εὑρέθησαν· ἦσαν δὲ ὡς πεντακόσιοι καὶ πέντε καὶ εἴκοσι."},{"number":72,"text":"τὸ δὲ τῶν θεραπόντων πλῆθος εἵπετο τοῖς ἀναβαίνουσιν εἰς Ἱεροσόλυμα ἑπτακισχιλίων τριακοσίων τριακονταεπτά, ψάλται δὲ καὶ ψάλτριαι διακόσιοι τεσσαρακονταπέντε, κάμηλοι τετρακόσιαι τριακονταπέντε, ὑποζύγια πεντακισχίλια πεντακόσια εἰκοσιπέντε."},{"number":73,"text":"ἡγεμὼν δὲ τῆς κατηριθμημένης πληθύος ἦν ὁ Σαλαθιήλου παῖς Ζοροβάβηλος ἐκ τῶν υἱῶν ὢν τῶν Δαυίδου γεγονὼς ἐκ τῆς Ἰούδα φυλῆς, καὶ Ἰησοῦς υἱὸς Ἰωσεδέκου τοῦ ἀρχιερέως. πρὸς τούτοις ὁ Μαρδοχαῖος καὶ Σερεβαῖος ἐκ τοῦ πλήθους κεκριμένοι ἄρχοντες ἦσαν, οἳ καὶ συνεβάλοντο μνᾶς μὲν χρυσίου ἑκατὸν ἀργύρου δὲ πεντακισχιλίας."},{"number":74,"text":"οὕτως μὲν οὖν οἵ τε ἱερεῖς καὶ οἱ Λευῖται καὶ μέρος τι τοῦ παντὸς λαοῦ τῶν Ἰουδαίων, ὃς ἦν ἐν τῇ Βαβυλῶνι, κατῳκίσθησαν εἰς τὰ Ἱεροσόλυμα· τὸ δὲ ἄλλο πλῆθος εἰς τὰς ἰδίας ἀνεχώρησεν πατρίδας."}],"4":[{"number":75,"text":"Ἑβδόμῳ δὲ μηνὶ τῆς ἀπὸ Βαβυλῶνος αὐτῶν ἐξόδου περιπέμψαντες ὅ τε ἀρχιερεὺς Ἰησοῦς καὶ Ζοροβάβηλος ὁ ἄρχων τοὺς ἀπὸ τῆς χώρας συνήγαγον εἰς Ἱεροσόλυμα πανδημεὶ μηδὲν προθυμίας ἀπολιπόντες,"},{"number":76,"text":"κατεσκεύασάν τε θυσιαστήριον ἐφʼ οὗ καὶ πρότερον ἦν ᾠκοδομημένον τόπου, ὅπως τὰς νομίμους ἀναφέρωσι θυσίας ἐπʼ αὐτοῦ τῷ θεῷ κατὰ τοὺς Μωυσέως νόμους. ταῦτα δὲ ποιοῦντες οὐκ ἦσαν ἐν ἡδονῇ τοῖς προσχωρίοις ἔθνεσιν πάντων αὐτοῖς ἀπεχθανομένων."},{"number":77,"text":"ἤγαγον δὲ καὶ τὴν σκηνοπηγίαν κατʼ ἐκεῖνον τὸν καιρόν, ὡς ὁ νομοθέτης περὶ αὐτῆς διετάξατο, καὶ προσφορὰς μετὰ ταῦτα καὶ τοὺς καλουμένους ἐνδελεχισμοὺς καὶ τὰς θυσίας τῶν σαββάτων καὶ πασῶν τῶν ἁγίων ἑορτῶν, οἵ τε πεποιημένοι τὰς εὐχὰς ἀπεδίδοσαν θύοντες ἀπὸ νουμηνίας τοῦ ἑβδόμου μηνός."},{"number":78,"text":"ἤρξαντο δὲ καὶ τῆς οἰκοδομίας τοῦ ναοῦ πολλὰ τοῖς τε λατόμοις καὶ τέκτοσι χρήματα δόντες καὶ τὰ πρὸς τροφὴν τῶν εἰσαγομένων, τοῖς τε Σιδωνίοις ἡδὺ καὶ κοῦφον ἦν τά τε κέδρινα κατάγουσιν ἐκ τοῦ Λιβάνου ξύλα δήσασιν αὐτὰ καὶ σχεδίαν πηξαμένοις εἰς τὸν τῆς Ἰόππης κομίζειν λιμένα· τοῦτο γὰρ πρῶτος μὲν Κῦρος ἐκέλευσεν, τότε δὲ Δαρείου κελεύσαντος ἐγίνετο."},{"number":79,"text":"Ὧν τῷ δευτέρῳ ἔτει τῆς εἰς Ἱεροσόλυμα καθόδου τῶν Ἰουδαίων μηνὶ δευτέρῳ παραγενομένων συνείχετο ἡ τοῦ ναοῦ κατασκευή· καὶ τοὺς θεμελίους ἐγείραντες τῇ νουμηνίᾳ τοῦ δευτέρου μηνὸς τοῦ δευτέρου ἔτους ἐπῳκοδόμουν, προστησάμενοι τῶν ἔργων Λευιτῶν τε τοὺς εἰκοστὸν ἔτος ἤδη γεγονότας καὶ Ἰησοῦν καὶ τοὺς υἱοὺς αὐτοῦ καὶ τοὺς ἀδελφοὺς καὶ Ζοδμοῆλον τὸν ἀδελφὸν Ἰούδα τοῦ Ἀμιναδάβου καὶ τοὺς υἱοὺς αὐτοῦ."},{"number":80,"text":"καὶ ὁ μὲν ναὸς πάσῃ χρησαμένων σπουδῇ τῶν τὴν ἐπιμέλειαν ἐγκεχειρισμένων θᾶττον ἢ προσεδόκησεν ἄν τις ἔλαβεν τέλος. ἀπαρτισθέντος δὲ τοῦ ἱεροῦ μετὰ σαλπίγγων οἱ ἱερεῖς ταῖς συνήθεσι στολαῖς κεκοσμημένοι καὶ οἱ Λευῖται καὶ οἱ Ἀσάφου παῖδες ἀναστάντες ὕμνουν τὸν θεόν, ὡς τὴν εἰς αὐτὸν εὐλογίαν Δαυίδης κατέδειξε πρῶτος."},{"number":81,"text":"οἱ δὲ ἱερεῖς καὶ Λευῖται καὶ τῶν πατριῶν οἱ πρεσβύτεροι τὸν πρότερον ναὸν ταῖς μνήμαις ἀναπολοῦντες μέγιστόν τε καὶ πολυτελέστατον, καὶ τὸν γεγενημένον ὁρῶντες ὑπὸ πτωχείας ἐνδεέστερον τοῦ πάλαι κατασκευαζόμενον, ὅσον εἶεν τῆς ἀρχαίας εὐδαιμονίας ὑποβεβηκότες καὶ τῆς ἀξίας τοῦ ναοῦ λογιζόμενοι κατήφουν, καὶ τῆς ἐπὶ τούτῳ λύπης κρατεῖν οὐ δυνάμενοι μέχρι θρήνων καὶ δακρύων προήγοντο."},{"number":82,"text":"ὁ δὲ λαὸς ἠγάπα τοῖς παροῦσιν καὶ τῷ μόνον οἰκοδομῆσαι τὸ ἱερὸν τοῦ πρότερον ὄντος οὐδένα λόγον ποιούμενος οὐδʼ ἀνάμνησιν οὐδὲ πρὸς τὴν σύγκρισιν τὴν ἐκείνου βασανίζων αὑτὸν ὡς ἐπʼ ἐλάττοσιν οἷς ὑπελάμβανεν."},{"number":83,"text":"ὑπερεφώνει δὲ τὸν τῶν σαλπίγγων ἦχον καὶ τὴν τοῦ πλήθους χαρὰν ἡ τῶν πρεσβυτέρων καὶ ἱερέων ἐφʼ οἷς ἐδόκουν ἐλαττοῦσθαι τὸν ναὸν τοῦ κατασκαφέντος οἰμωγή."},{"number":84,"text":"Τῆς δὲ βοῆς τῶν σαλπίγγων ἀκούσαντες οἱ Σαμαρεῖται, ἐτύγχανον γὰρ ἀπεχθανόμενοι τῇ τε Ἰούδα φυλῇ καὶ τῇ Βενιαμίτιδι, συνέδραμον τὴν αἰτίαν τοῦ θορύβου μαθεῖν θέλοντες. γνόντες δὲ τοὺς αἰχμαλωτισθέντας εἰς Βαβυλῶνα τῶν Ἰουδαίων ἀνακτίζοντας τὸ ἱερόν, προσίασιν τῷ Ζοροβαβήλῳ καὶ Ἰησοῦ καὶ τοῖς ἡγουμένοις τῶν πατριῶν ἀξιοῦντες αὐτοῖς ἐπιτραπῆναι συγκατασκευάσαι τὸν ναὸν καὶ κοινωνῆσαι τῆς οἰκοδομίας·"},{"number":85,"text":"σεβόμεθα γὰρ οὐκ ἔλαττον ἐκείνων τὸν θεόν, ἔφασκον, καὶ τοῦτον ὑπερευχόμεθα καὶ τῆς θρησκείας ἐσμὲν ἐπιθυμηταὶ ἐξ ἐκείνου τοῦ χρόνου, ἀφʼ οὗ Σαλμανασσάρης ὁ τῶν Ἀσσυρίων βασιλεὺς ἐκ τῆς Χουθίας ἡμᾶς μετήγαγεν καὶ Μηδίας ἐνθάδε."},{"number":86,"text":"τούτους αὐτῶν ποιησαμένων τοὺς λόγους Ζοροβάβηλος καὶ Ἰησοῦς ὁ ἀρχιερεὺς καὶ οἱ τῶν πατριῶν ἡγεμόνες τῶν Ἰσραηλιτῶν πρὸς αὐτοὺς ἔφασαν τῆς μὲν οἰκοδομίας αὐτοῖς ἀδύνατον εἶναι κοινωνεῖν, αὐτῶν προσταχθέντων κατασκευάσαι τὸν ναὸν πρότερον μὲν ὑπὸ Κύρου νῦν δὲ ὑπὸ Δαρείου·"},{"number":87,"text":"προσκυνεῖν δὲ αὐτοῖς ἐφιέναι καὶ τοῦτο μόνον εἶναι κοινόν, εἰ βούλονται, πρὸς αὐτοὺς καὶ πᾶσιν ἀνθρώποις ἀφικνουμένοις εἰς τὸ ἱερὸν σέβειν τὸν θεόν."},{"number":88,"text":"Ταῦτʼ ἀκούσαντες οἱ Χουθαῖοι, τὴν γὰρ προσηγορίαν οἱ Σαμαρεῖται ταύτην ἔχουσιν, ἠγανάκτησαν καὶ πείθουσιν τὰ ἐν Συρίᾳ ἔθνη τῶν σατραπῶν δεηθῆναι τὸν αὐτὸν τρόπον, ὅνπερ ἐπὶ Κύρου πρότερον εἶτʼ ἐπὶ Καμβύσου μετʼ αὐτόν, ἐπισχεῖν τὴν τοῦ ναοῦ κατασκευὴν καὶ σπουδάζουσιν περὶ αὐτὸν τοῖς Ἰουδαίοις ἀναβολὴν καὶ τριβὴν πραγματεύσασθαι."},{"number":89,"text":"κατὰ δὲ τὸν καιρὸν τοῦτον ἀναβάντων εἰς Ἱεροσόλυμα Σισίνου τοῦ τῆς Συρίας καὶ Φοινίκης ἐπάρχου καὶ Σαρωβαζάνου μετὰ καί τινων ἑτέρων καὶ τοὺς ἡγεμόνας τῶν Ἰουδαίων ἐρομένων, τίνος αὐτοῖς συγχωρήσαντος οὕτως οἰκοδομοῦσιν τὸν ναόν, ὡς φρούριον μᾶλλον αὐτὸν εἶναι ἢ ἱερόν, καὶ τί δήποτε τὰς στοὰς καὶ τὰ τείχη περιβεβλήκασιν τῇ πόλει σφόδρα ὀχυρά,"},{"number":90,"text":"Ζοροβάβηλος καὶ ὁ ἀρχιερεὺς Ἰησοῦς δούλους μὲν αὐτοὺς ἔφασαν εἶναι τοῦ μεγίστου θεοῦ, τὸν δὲ ναὸν τοῦτον αὐτῷ κατασκευασθέντα ὑπὸ βασιλέως αὐτῶν εὐδαίμονος καὶ πάντας ὑπερβάλλοντος ἀρετῇ πολὺν διαμεῖναι χρόνον."},{"number":91,"text":"ἐπεὶ δὲ τῶν πατέρων ἀσεβησάντων εἰς τὸν θεὸν Ναβουχοδονόσορος ὁ Βαβυλωνίων καὶ Χαλδαίων βασιλεὺς ἑλὼν τὴν πόλιν κατὰ κράτος αὐτήν τε καθεῖλεν καὶ τὸν ναὸν συλήσας ἐνέπρησεν καὶ τὸν λαὸν μετῴκισεν αἰχμάλωτον μεταγαγὼν εἰς Βαβυλῶνα,"},{"number":92,"text":"Κῦρος ὁ μετʼ αὐτὸν τῆς Βαβυλωνίας καὶ Περσίδος βασιλεὺς ἔγραψεν οἰκοδομῆσαι τὸν ναόν, καὶ πάνθʼ ὅσα μετήγαγεν ἐξ αὐτοῦ Ναβουχοδονόσορος ἀναθήματα καὶ σκεύη Ζοροβαβήλῳ παραδοὺς καὶ Μιθριδάτῃ τῷ γαζοφύλακι προσέταξεν κομίσαι εἰς Ἱεροσόλυμα καὶ πάλιν εἰς τὸν ἴδιον ἀποκατασταθῆναι ναὸν οἰκοδομηθέντα."},{"number":93,"text":"τοῦτο γὰρ ἐπέστειλεν ἐν τάχει γενέσθαι Σαβάσηρον κελεύσας ἀναβάντα εἰς Ἱεροσόλυμα τῆς οἰκοδομίας τοῦ ναοῦ ποιήσασθαι πρόνοιαν. ὃς μετὰ τὸ λαβεῖν παρὰ Κύρου γράμματα, παραγενόμενος εὐθὺς τοὺς θεμελίους κατεβάλετο, καὶ ἐξ ἐκείνου τοῦ χρόνου κατασκευαζόμενος μέχρι καὶ τοῦ δεῦρο διὰ τὴν τῶν ἐχθρῶν κακοήθειάν ἐστιν ἀτελής."},{"number":94,"text":"εἰ τοίνυν βούλεσθε καὶ δοκιμάζετε, γράψατε ταῦτα Δαρείῳ, ὅπως ἐπισκεψάμενος τὰ τῶν βασιλέων ὑπομνήματα εὕρῃ μηδὲν ἡμᾶς ὧν λέγομεν καταψευσαμένους."},{"number":95,"text":"Ταῦτʼ εἰπόντων τοῦ τε Ζοροβαβήλου καὶ τοῦ ἀρχιερέως ὁ Σισίννης καὶ οἱ σὺν αὐτῷ τὴν μὲν οἰκοδομίαν ἐπισχεῖν οὐ διέγνωσαν ἕως ἂν ταῦτα δηλωθῇ Δαρείῳ, παραχρῆμα δʼ αὐτῷ περὶ τούτων ἔγραψαν."},{"number":96,"text":"τῶν δὲ Ἰουδαίων κατεπτηχότων καὶ δεδιότων μὴ μεταδόξῃ τῷ βασιλεῖ περὶ τῆς τῶν Ἱεροσολύμων καὶ τοῦ ναοῦ κατασκευῆς, ὄντες κατὰ τὸν καιρὸν ἐκεῖνον δύο προφῆται παρʼ αὐτοῖς Ἀγγαῖος καὶ Ζαχαρίας θαρρεῖν αὐτοὺς παρώρμων καὶ μηδὲν ἐκ τῶν Περσῶν ὑφορᾶσθαι δύσκολον, ὡς τοῦ θεοῦ ταῦτα προλέγοντος. πιστεύοντες δὲ τοῖς προφήταις ἐντεταμένως εἴχοντο τῆς οἰκοδομίας μηδεμίαν ἡμέραν ἀνιέμενοι."},{"number":97,"text":"Δαρεῖος δὲ τῶν Σαμαρειτῶν αὐτῷ γραψάντων καὶ κατηγορούντων διὰ τῆς ἐπιστολῆς τῶν Ἰουδαίων, ὡς τήν τε πόλιν ὀχυροῦσι καὶ τὸν ναὸν φρουρίῳ προσεοικότα μᾶλλον ἢ ἱερῷ κατασκευάζουσιν, λεγόντων δὲ μὴ συνοίσειν αὐτῷ τὰ γινόμενα καὶ προσέτι τὰς ἐπιστολὰς ἐπιδεικνύντων τὰς Καμβύσου, διʼ ὧν ἐκώλυσεν ἐκεῖνος οἰκοδομεῖν τὸν ναόν,"},{"number":98,"text":"μαθὼν παρʼ αὐτῶν οὐκ ἀσφαλῆ τοῖς πράγμασιν αὐτοῦ τὴν τῶν Ἱεροσολύμων ἀποκατάστασιν ἔσεσθαι, ἐπεὶ καὶ τὰ παρὰ τοῦ Σισίννου καὶ τῶν σὺν αὐτῷ κομισθέντα ἀνέγνω γράμματα, προσέταξεν ἐν τοῖς βασιλικοῖς ὑπομνήμασιν ζητηθῆναι τὰ περὶ τούτων."},{"number":99,"text":"καὶ εὑρέθη ἐν Ἐκβατάνοις τῇ βάρει τῇ ἐν Μηδίᾳ βιβλίον, ἐν ᾧ τάδε ἦν ἀναγεγραμμένα· ἐν τῷ πρώτῳ τῆς βασιλείας ἔτει Κῦρος ὁ βασιλεὺς ἐκέλευσεν τὸν ναὸν οἰκοδομηθῆναι τὸν ἐν Ἱεροσολύμοις καὶ τὸ θυσιαστήριον, ὕψος μὲν πηχῶν ἑξήκοντα εὖρος δὲ τῶν αὐτῶν, διὰ δόμων λιθίνων βία τε ξεστῶν τριῶν καὶ ξυλίνου δόμου ἑνὸς ἐγχωρίου."},{"number":100,"text":"καὶ τὴν εἰς ταῦτα δαπάνην ἐκ τῶν τοῦ βασιλέως γίνεσθαι διετάξατο, καὶ τὰ σκεύη, ἃ συλήσας Ναβουχοδονόσορος εἰς Βαβυλῶνα ἐκόμισεν, ἀποδοθῆναι τοῖς Ἱεροσολυμίταις,"},{"number":101,"text":"τὴν δὲ ἐπιμέλειαν τούτων εἶναι Ἀναβασσάρου τοῦ ἐπάρχου καὶ τῆς Συρίας τε καὶ Φοινίκης ἡγεμόνος καὶ τῶν ἑταίρων αὐτοῦ, ὅπως αὐτοὶ μὲν ἀφέξονται τοῦ τόπου, τοῖς δὲ δούλοις τοῦ θεοῦ Ἰουδαίοις τε καὶ ἡγεμόσιν αὐτῶν ἐπιτρέψουσιν οἰκοδομηθῆναι τὸν ναόν."},{"number":102,"text":"καὶ συλλαβέσθαι δὲ πρὸς τὸ ἔργον διετάξατο, κἀκ τοῦ φόρου τοῦ τῆς χώρας ἧς ἐπετροπεύοντο τελεῖν τοῖς Ἰουδαίοις εἰς θυσίας λόγον ταύρους καὶ κριοὺς καὶ ἄρνας καὶ ἐρίφους καὶ σεμίδαλιν καὶ ἔλαιον καὶ οἶνον καὶ τἆλλα, ὅσα ἂν οἱ ἱερεῖς ὑπαγορεύσωσιν, εὔχωνται δὲ ὑπὲρ τῆς σωτηρίας τοῦ βασιλέως καὶ Περσῶν."},{"number":103,"text":"τοὺς δὲ παραβάντας τι τῶν ἐπεσταλμένων συλληφθέντας ἐκέλευσεν ἀνασταυρωθῆναι καὶ τὴν οὐσίαν αὐτῶν εἰς τὴν βασιλικὴν καταταγῆναι κτῆσιν. καὶ κατηύξατο πρὸς τούτοις τῷ θεῷ, ὅπως εἴ τις ἐπιχειρήσειε διακωλῦσαι τὴν οἰκοδομίαν τοῦ ναοῦ, βαλὼν αὐτὸν ὁ θεὸς ἐπίσχῃ τῆς ἀδικίας."},{"number":104,"text":"Ταῦθʼ εὑρὼν ἐν τοῖς ὑπομνήμασιν τοῖς Κύρου Δαρεῖος ἀντιγράφει τῷ Σισίννῃ καὶ τοῖς ἑταίροις αὐτοῦ τάδε λέγων· βασιλεὺς Δαρεῖος Σισίννῃ τῷ ἐπάρχῳ καὶ Σαραβαζάνῃ καὶ τοῖς ἑταίροις αὐτῶν χαίρειν. τὸ ἀντίγραφον τῆς ἐπιστολῆς ὑμῖν ἧς ἐν τοῖς ὑπομνήμασιν εὗρον τοῖς Κύρου ἀπέσταλκα καὶ βούλομαι γίνεσθαι πάντα, καθὼς ἐν αὐτῇ περιέχει. ἔρρωσθε."},{"number":105,"text":"μαθόντες οὖν ἐκ τῆς ἐπιστολῆς ὁ Σισίννης καὶ οἱ σὺν αὐτῷ τὴν τοῦ βασιλέως προαίρεσιν ταύτῃ τὰ λοιπὰ ἀκόλουθα ποιεῖν διέγνωσαν. ἐπεστάτουν οὖν τῶν ἱερῶν ἔργων συλλαμβανόμενοι τοῖς πρεσβυτέροις τῶν Ἰουδαίων καὶ τῶν γερόντων ἄρχουσιν."},{"number":106,"text":"καὶ ἠνύετο κατὰ πολλὴν σπουδὴν ἡ κατασκευὴ τοῦ ναοῦ προφητευόντων Ἀγγαίου καὶ Ζαχαρίου κατὰ πρόσταγμα τοῦ θεοῦ καὶ μετὰ βουλήσεως Κύρου τε καὶ Δαρείου τῶν βασιλέων, ᾠκοδομήθη δὲ ἐν ἔτεσιν ἑπτά."},{"number":107,"text":"τοῦ δʼ ἐνάτου τῆς Δαρείου βασιλείας ἔτους εἰκάδι καὶ τρίτῃ μηνὸς δωδεκάτου, ὃς καλεῖται παρὰ μὲν ἡμῖν Ἄδαρ παρὰ δὲ Μακεδόσιν Δύστρος, προσφέρουσιν θυσίας οἵ τε ἱερεῖς καὶ Λευῖται καὶ τὸ ἄλλο τῶν Ἰσραηλιτῶν πλῆθος ἀνανεωτικὰς τῶν πρότερον ἀγαθῶν μετὰ τὴν αἰχμαλωσίαν τοῦ τὸ ἱερὸν ἀνακαινισθὲν ἀπειληφέναι ταύρους ἑκατὸν κριοὺς διακοσίους ἄρνας τετρακοσίους χιμάρους δώδεκα κατὰ φυλήν, τοσαῦται γάρ εἰσιν αἱ τῶν Ἰσραηλιτῶν φυλαί, ὑπὲρ ὧν ἥμαρτεν ἑκάστη."},{"number":108,"text":"ἔστησάν τε κατὰ τοὺς Μωυσέως νόμους οἵ τε ἱερεῖς καὶ οἱ Λευῖται θυρωροὺς ἐφʼ ἑκάστου πυλῶνος· ᾠκοδομήκεσαν γὰρ οἱ Ἰουδαῖοι καὶ τὰς ἐν κύκλῳ τοῦ ναοῦ στοὰς τοῦ ἔνδοθεν ἱεροῦ."},{"number":109,"text":"Ἐνστάσης δὲ τῆς τῶν ἀζύμων ἑορτῆς μηνὶ τῷ πρώτῳ, κατὰ μὲν Μακεδόνας Ξανθικῷ λεγομένῳ κατὰ δὲ ἡμᾶς Νισάν, συνερρύη πᾶς ὁ λαὸς ἐκ τῶν κωμῶν εἰς τὴν πόλιν, καὶ τὴν ἑορτὴν ἤγαγον ἁγνεύοντες μετὰ γυναικῶν καὶ τέκνων τῷ πατρίῳ νόμῳ,"},{"number":110,"text":"καὶ τὴν πάσχα προσαγορευομένην θυσίαν τῇ τετράδι καὶ δεκάτῃ τοῦ αὐτοῦ μηνὸς ἐπιτελέσαντες κατευωχήθησαν ἐπὶ ἡμέρας ἑπτὰ μηδεμιᾶς φειδόμενοι πολυτελείας, ἀλλὰ καὶ τὰς ὁλοκαυτώσεις ἐπιφέροντες τῷ θεῷ καὶ χαριστηρίους θυσίας ἱερουργοῦντες ἀνθʼ ὧν αὐτοὺς ποθοῦν τὸ θεῖον πάλιν εἰς τὴν πάτριον γῆν καὶ τοὺς ἐν αὐτῇ νόμους ἤγαγεν καὶ τὴν τοῦ Περσῶν βασιλέως διάνοιαν εὐμενῆ κατέστησεν αὐτοῖς."},{"number":111,"text":"καὶ οἱ μὲν ὑπὲρ τούτων ἐπιδαψιλευόμενοι ταῖς θυσίαις καὶ τῇ περὶ τὸν θεὸν φιλοτιμίᾳ κατῴκησαν ἐν τοῖς Ἱεροσολύμοις πολιτείᾳ χρώμενοι ἀριστοκρατικῇ μετὰ ὀλιγαρχίας· οἱ γὰρ ἀρχιερεῖς προεστήκεσαν τῶν πραγμάτων ἄχρι οὗ τοὺς Ἀσαμωναίου συνέβη βασιλεύειν ἐκγόνους."},{"number":112,"text":"πρὸ μὲν γὰρ τῆς αἰχμαλωσίας καὶ τῆς ἀναστάσεως ἐβασιλεύοντο ἀπὸ Σαούλου πρῶτον ἀρξάμενοι καὶ Δαυίδου ἐπὶ ἔτη πεντακόσια τριακονταδύο μῆνας ἓξ ἡμέρας δέκα, πρὸ δὲ τῶν βασιλέων τούτων ἄρχοντες αὐτοὺς διεῖπον οἱ προσαγορευόμενοι κριταὶ καὶ μόναρχοι, καὶ τοῦτον πολιτευόμενοι τὸν τρόπον ἔτεσιν πλέον ἢ πεντακοσίοις διήγαγον μετὰ Μωυσῆν ἀποθανόντα καὶ Ἰησοῦν τὸν στρατηγόν."},{"number":113,"text":"καὶ τὰ μὲν περὶ τῶν ἀνασωθέντων ἐκ τῆς αἰχμαλωσίας Ἰουδαίων ἐν τοῖς Κύρου καὶ Δαρείου χρόνοις ἐν τούτοις ὑπῆρχεν."},{"number":114,"text":"Οἱ δὲ Σαμαρεῖς ἀπεχθῶς πρὸς αὐτοὺς καὶ βασκάνως διακείμενοι πολλὰ κακὰ τοὺς Ἰουδαίους εἰργάσαντο πλούτῳ τε πεποιθότες καὶ συγγένειαν προσποιούμενοι τὴν Περσῶν, ἐπειδήπερ ἐκεῖθεν ἦσαν."},{"number":115,"text":"ὅσα τε γὰρ ἐκελεύσθησαν ἐκ τῶν φόρων ὑπὸ τοῦ βασιλέως εἰς τὰς θυσίας τελεῖν τοῖς Ἰουδαίοις παρέχειν οὐκ ἤθελον τούς τε ἐπάρχους σπουδάζοντας αὐτοῖς πρὸς τοῦτο καὶ συνεργοῦντας εἶχον, ἄλλα τε ὅσα βλάπτειν ἢ διʼ ἑαυτῶν ἢ διʼ ἑτέρων ἠδύναντο τοὺς Ἰουδαίους οὐκ ἀπώκνουν."},{"number":116,"text":"ἔδοξεν οὖν πρεσβευσαμένοις τοῖς Ἱεροσολυμίταις πρὸς τὸν βασιλέα Δαρεῖον κατηγορῆσαι τῶν Σαμαρειτῶν, καὶ πρεσβεύουσιν Ζοροβάβηλος καὶ ἄλλοι τῶν ἀρχόντων τέσσαρες."},{"number":117,"text":"ὡς δὲ τὰ ἐγκλήματα καὶ τὰς αἰτίας, ἃς κατὰ τῶν Σαμαρέων ἐπέφερον, ἔγνω παρὰ τῶν πρέσβεων ὁ βασιλεύς, δοὺς αὐτοῖς κομίζειν ἐπιστολὴν πρὸς τοὺς ἐπάρχους τῆς Σαμαρείας καὶ τὴν βουλὴν ἀπέπεμψεν."},{"number":118,"text":"τὰ δὲ γεγραμμένα ἦν τοιάδε· βασιλεὺς Δαρεῖος Ταγανᾷ καὶ Σαμβᾷ τοῖς ἐπάρχοις καὶ Σαμαρειτῶν Σαδράκῃ καὶ Βουήδωνι καὶ τοῖς λοιποῖς συνδούλοις αὐτῶν τοῖς ἐν Σαμαρείᾳ. Ζοροβάβηλος καὶ Ἀνανίας καὶ Μαρδοχαῖος Ἰουδαίων πρεσβευταὶ ᾐτιῶντο ὑμᾶς ὡς ἐνοχλοῦντας αὐτοῖς πρὸς τὴν οἰκοδομίαν τοῦ ναοῦ καὶ μὴ χορηγοῦντας ἃ προσέταξα ὑμῖν εἰς τὰς θυσίας τελεῖν αὐτοῖς ἀναλώματα."},{"number":119,"text":"βούλομαι οὖν ὑμᾶς ἀναγνόντας τὴν ἐπιστολὴν χορηγεῖν αὐτοῖς ἐκ τοῦ βασιλικοῦ γαζοφυλακείου τῶν φόρων τῆς Σαμαρείας πάνθʼ ὅσα πρὸς θυσίας ἐστὶν αὐτοῖς χρήσιμα, καθὼς οἱ ἱερεῖς ἀξιοῦσιν, ἵνα μὴ διαλείπωσιν καθʼ ἡμέραν θύοντες μηδʼ ὑπὲρ ἐμοῦ καὶ Περσῶν εὐχόμενοι τῷ θεῷ. καὶ ἡ μὲν ἐπιστολὴ ταῦτα περιεῖχεν."}],"5":[{"number":120,"text":"Δαρείου δὲ τελευτήσαντος παραλαβὼν τὴν βασιλείαν ὁ παῖς αὐτοῦ Ξέρξης ἐκληρονόμησεν αὐτοῦ καὶ τὴν πρὸς τὸν θεὸν εὐσέβειάν τε καὶ τιμήν· ἅπαντα γὰρ ἀκολούθως τῷ πατρὶ τὰ πρὸς τὴν θρησκείαν ἐποίησεν καὶ πρὸς τοὺς Ἰουδαίους ἔσχεν φιλοτιμότατα."},{"number":121,"text":"κατʼ ἐκεῖνον δὲ τὸν καιρὸν ἀρχιερεὺς ἦν Ἰησοῦ παῖς Ἰωάκειμος ὄνομα. ὑπῆρχεν δὲ καὶ ἐν Βαβυλῶνι δίκαιος ἀνὴρ καὶ δόξης ἀπολαύων ἀγαθῆς παρὰ τῷ πλήθει πρῶτος ἱερεὺς τοῦ θεοῦ καλούμενος Ἔζδρας, ὃς τῶν Μωυσέως νόμων ἱκανῶς ἔμπειρος ὢν γίνεται φίλος τῷ βασιλεῖ Ξέρξῃ."},{"number":122,"text":"γνοὺς δὲ ἀναβῆναι εἰς τὰ Ἱεροσόλυμα καὶ ἐπαγαγέσθαι τινὰς τῶν ἐν Βαβυλῶνι τυγχανόντων Ἰουδαίων παρεκάλεσεν τὸν βασιλέα δοῦναι αὐτῷ πρὸς τοὺς σατράπας τῆς Συρίας ἐπιστολήν, ὑφʼ ἧς αὐτοῖς γνωρισθήσεται τίς εἴη."},{"number":123,"text":"ὁ δὲ βασιλεὺς γράφει πρὸς τοὺς σατράπας ἐπιστολὴν τοιάνδε· βασιλεὺς βασιλέων Ξέρξης Ἔζδρᾳ ἱερεῖ καὶ ἀναγνώστῃ τῶν τοῦ θεοῦ νόμων χαίρειν. τῆς ἐμαυτοῦ φιλανθρωπίας ἔργον εἶναι νομίσας τὸ τοὺς βουλομένους ἐκ τοῦ Ἰουδαίων ἔθνους καὶ Λευιτῶν ὄντων ἐν τῇ ἡμετέρᾳ βασιλείᾳ συναπαίρειν εἰς τὰ Ἱεροσόλυμα, τοῦτο προσέταξα, καὶ ὁ βουλόμενος ἀπίτω,"},{"number":124,"text":"καθάπερ ἔδοξέν μοι καὶ τοῖς ἑπτά μου συμβούλοις, ὅπως τὰ κατὰ τὴν Ἰουδαίαν ἐπισκέψωνται τῷ νόμῳ τοῦ θεοῦ ἀκολούθως καὶ ἀπενέγκωσι δῶρα τῷ Ἰσραηλιτῶν θεῷ, ἅπερ ηὐξάμην ἐγώ τε καὶ οἱ φίλοι·"},{"number":125,"text":"καὶ ἀργύριον καὶ χρυσίον ὅσον ἂν εὑρεθῇ ἐν τῇ χώρᾳ τῶν Βαβυλωνίων ὠνομασμένον τῷ θεῷ τοῦτο πᾶν εἰς Ἱεροσόλυμα κομισθῆναι τῷ θεῷ εἰς τὰς θυσίας, πάντα τε, ὅσα βούλει ἐξ ἀργύρου καὶ χρυσοῦ κατασκευάσαι, ποιεῖν ἐξέστω σοι μετὰ τῶν ἀδελφῶν."},{"number":126,"text":"καὶ τὰ δεδομένα σοι ἱερὰ σκεύη ἀναθήσεις καὶ ὅσων ἂν ἐπίνοιαν λάβῃς καὶ ταῦτα προσεξεργάσῃ τὴν εἰς αὐτὰ δαπάνην ποιούμενος ἐκ τοῦ βασιλικοῦ γαζοφυλακείου."},{"number":127,"text":"ἔγραψα δὲ καὶ τοῖς γαζοφύλαξιν τῆς Συρίας καὶ τῆς Φοινίκης, ἵνα τῶν ὑπὸ Ἔζδρα τοῦ ἱερέως καὶ ἀναγνώστου τῶν τοῦ θεοῦ νόμων ἐπισταλέντων ἐπιμεληθῶσιν. ὅπως δὲ μηδεμίαν ὀργὴν ἐπʼ ἐμὲ λάβῃ τὸ θεῖον ἢ τοὺς ἐμοὺς ἐκγόνους, πάντʼ ἀξιῶ καὶ μέχρι τοῦ πυροῦ κόρων ἑκατὸν ἐπιτελεῖσθαι τῷ θεῷ κατὰ τὸν νόμον."},{"number":128,"text":"καὶ ὑμῖν δὲ λέγω, ὅπως τοῖς ἱερεῦσιν καὶ Λευίταις καὶ ἱεροψάλταις καὶ θυρωροῖς καὶ ἱεροδούλοις καὶ γραμματεῦσιν τοῦ ἱεροῦ μήτε φόρους ἐπιτάξητε μήτε ἄλλο μηδὲν ἐπίβουλον ἢ φορτικὸν εἰς αὐτοὺς γένηται."},{"number":129,"text":"καὶ σὺ δέ, Ἔζδρα, κατὰ τὴν τοῦ θεοῦ σοφίαν ἀπόδειξον κριτάς, ὅπως δικάσωσιν ἐν Συρίᾳ καὶ Φοινίκῃ πάσῃ τοὺς ἐπισταμένους σου τὸν νόμον, καὶ τοῖς ἀγνοοῦσιν δὲ παρέξεις αὐτὸν μαθεῖν,"},{"number":130,"text":"ἵνα ἄν τις τῶν ὁμοεθνῶν σου παραβαίνῃ τὸν τοῦ θεοῦ νόμον ἢ τὸν βασιλικόν, ὑπόσχῃ τιμωρίαν, ὡς οὐ κατʼ ἄγνοιαν αὐτὸν παραβαίνων, ἀλλʼ ὡς ἐπιστάμενος μὲν τολμηρῶς δὲ παρακούων καὶ καταφρονῶν. κολασθήσονται δʼ ἤτοι θανάτῳ ἢ ζημίᾳ χρηματικῇ. ἔρρωσο."},{"number":131,"text":"Λαβὼν δὲ Ἔζδρας ταύτην τὴν ἐπιστολὴν ὑπερήσθη καὶ τῷ θεῷ προσκυνεῖν ἤρξατο, τῆς τοῦ βασιλέως πρὸς αὐτὸν χρηστότητος ἐκεῖνον αἴτιον ὁμολογῶν γεγενῆσθαι, καὶ διὰ τοῦτο τὴν πᾶσαν αὐτοῦ χάριν ἔλεγεν εἶναι. ἀναγνοὺς δʼ ἐν Βαβυλῶνι τὴν ἐπιστολὴν τοῖς αὐτόθι παροῦσιν Ἰουδαίοις, αὐτὴν μὲν κατέσχεν, τὸ δʼ ἀντίγραφον αὐτῆς πρὸς ἅπαντας ἔπεμψεν τοὺς ὁμοεθνεῖς τοὺς κατὰ τὴν Μηδίαν ὄντας."},{"number":132,"text":"μαθόντες δὲ οὗτοι τὴν παρὰ τοῦ βασιλέως καὶ πρὸς τὸν θεὸν εὐσέβειαν καὶ πρὸς τὸν Ἔζδραν εὔνοιαν ἅπαντες μὲν ὑπερηγάπησαν, πολλοὶ δʼ αὐτῶν καὶ τὰς κτήσεις ἀναλαβόντες ἦλθον εἰς Βαβυλῶνα ποθοῦντες τῆς εἰς τὰ Ἱεροσόλυμα καθόδου."},{"number":133,"text":"ὁ δὲ πᾶς λαὸς τῶν Ἰσραηλιτῶν κατὰ χώραν ἔμεινεν· διὸ καὶ δύο φυλὰς εἶναι συμβέβηκεν ἐπί τε τῆς Ἀσίας καὶ τῆς Εὐρώπης Ῥωμαίοις ὑπακουούσας, αἱ δὲ δέκα φυλαὶ πέραν εἰσὶν Εὐφράτου ἕως δεῦρο, μυριάδες ἄπειροι καὶ ἀριθμῷ γνωσθῆναι μὴ δυνάμεναι."},{"number":134,"text":"πρὸς δὲ Ἔζδραν ἀφικνοῦνται ἱερέων καὶ Λευιτῶν καὶ θυρωρῶν καὶ ἱεροψαλτῶν καὶ ἱεροδούλων πολλοὶ τὸν ἀριθμόν. συναγαγὼν δὲ τοὺς ἐκ τῆς αἰχμαλωσίας εἰς τὸ πέραν τοῦ Εὐφράτου καὶ τρεῖς ἐπιδιατρίψας ἐκεῖ ἡμέρας νηστείαν αὐτοῖς παρήγγειλεν, ὅπως εὐχὰς ποιήσονται τῷ θεῷ περὶ τῆς αὐτῶν σωτηρίας καὶ τοῦ μηδὲν κατὰ τὴν ὁδὸν παθεῖν ἄτοπον ἢ πρὸς τῶν πολεμίων ἤ τινος ἄλλου δυσκόλου προσπεσόντος αὐτοῖς·"},{"number":135,"text":"φθάσας γὰρ ὁ Ἔζδρας εἰπεῖν τῷ βασιλεῖ, ὅτι διασώσει αὐτοὺς ὁ θεός, οὐ κατηξίωσεν ἱππεῖς αὐτὸν αἰτῆσαι τοὺς προπέμψοντας. ποιησάμενοι δὲ τὰς εὐχάς, ἄραντες ἀπὸ τοῦ Εὐφράτου δωδεκάτῃ τοῦ πρώτου μηνὸς τοῦ ἑβδόμου ἔτους τῆς Ξέρξου βασιλείας παρεγένοντο εἰς Ἱεροσόλυμα μηνὶ πέμπτῳ τοῦ αὐτοῦ ἔτους."},{"number":136,"text":"καὶ παραχρῆμα τοῖς γαζοφύλαξιν ὁ Ἔζδρας οὖσιν ἐκ τοῦ τῶν ἱερέων γένους παρέστησεν τὰ ἱερὰ χρήματα, ἀργυρίου τάλαντα ἑξακόσια πεντήκοντα, σκεύη ἀργυρᾶ ταλάντων ἑκατόν, καὶ χρύσεα σκεύη ταλάντων εἴκοσι, καὶ χαλκᾶ σκεύη χρυσοῦ κρείττονα σταθμὸν ἔχοντα ταλάντων δώδεκα· ταῦτα γὰρ ἐδωρήσατο ὁ βασιλεὺς καὶ οἱ σύμβουλοι αὐτοῦ καὶ πάντες οἱ ἐν Βαβυλῶνι μένοντες Ἰσραηλῖται."},{"number":137,"text":"παραδοὺς δὲ ταῦτα τοῖς ἱερεῦσιν ὁ Ἔζδρας ἀπέδωκε τῷ θεῷ τὰς ἐκ τῶν ὁλοκαυτώσεων νενομισμένας γίνεσθαι θυσίας, ταύρους δώδεκα ὑπὲρ κοινῆς τοῦ λαοῦ σωτηρίας, κριοὺς ἐνενήκοντα, ἄρνας ἑβδομηκονταδύο, ἐρίφους εἰς παραίτησιν τῶν ἡμαρτημένων δεκαδύο."},{"number":138,"text":"τοῖς δὲ τοῦ βασιλέως οἰκονόμοις καὶ τοῖς ἐπάρχοις τῆς κοίλης Συρίας καὶ Φοινίκης τὰ γράμματα τοῦ βασιλέως ἀπέδωκεν. οἱ δὲ τὸ προσταχθὲν ὑπʼ αὐτοῦ ποιεῖν ἀνάγκην ἔχοντες ἐτίμησάν τε τὸ ἔθνος καὶ πρὸς πᾶσαν αὐτῷ χρείαν συνήργησαν."},{"number":139,"text":"Ταῦτα μὲν οὖν καὶ αὐτὸς ἐβουλεύσατο Ἔσδρας, προεχώρησεν δʼ αὐτῷ κρίναντος αὐτὸν ἄξιον οἶμαι τοῦ θεοῦ τῶν βουληθέντων διὰ χρηστότητα καὶ δικαιοσύνην."},{"number":140,"text":"χρόνῳ δὲ ὕστερον προσελθόντων αὐτῷ τινων κατηγορούντων, ὥς τινες τοῦ πλήθους καὶ τῶν ἱερέων καὶ Λευιτῶν παραβεβήκασι τὴν πολιτείαν καὶ λελύκασιν τοὺς πατρίους νόμους ἀλλοεθνεῖς ἠγμένοι γυναῖκας καὶ τὸ ἱερατικὸν γένος συγκεχύκασιν,"},{"number":141,"text":"δεομένων τε βοηθῆσαι τοῖς νόμοις, μὴ κοινὴν ἐπὶ πάντας ὀργὴν λαβὼν πάλιν αὐτοὺς εἰς συμφορὰς ἐμβάλῃ, διέρρηξε μὲν εὐθὺς ὑπὸ λύπης τὴν ἐσθῆτα καὶ τὴν κεφαλὴν ἐσπάρασσεν καὶ τὰ γένεια ὑβρίζων ἐπὶ τὴν γῆν τε ἑαυτὸν ἔρριψεν ἐπὶ τῷ τὴν αἰτίαν ταύτην λαβεῖν τοὺς πρώτους τοῦ λαοῦ."},{"number":142,"text":"λογιζόμενος δὲ ὅτι, ἐὰν ἐκβαλεῖν αὐτοὺς τὰς γυναῖκας καὶ τὰ ἐξ αὐτῶν προστάξῃ τέκνα, οὐκ ἀκουσθήσεται, διέμενεν ἐπὶ τῆς γῆς κείμενος. συνέτρεχον οὖν πρὸς αὐτὸν οἱ μέτριοι πάντες κλαίοντες καὶ αὐτοὶ καὶ τῆς ἐπὶ τῷ γεγενημένῳ λύπης συμμεταλαμβάνοντες."},{"number":143,"text":"ἀναστὰς δὲ ἀπὸ τῆς γῆς ὁ Ἔσδρας καὶ τὰς χεῖρας ἀνατείνας εἰς τὸν οὐρανόν, αἰσχύνεσθαι μὲν ἔλεγεν αὐτὸν ἀναβλέψαι διὰ τὰ ἡμαρτημένα τῷ λαῷ, ὃς τῆς μνήμης ἐξέβαλεν τὰ τοῖς πατράσιν ἡμῶν διὰ τὴν ἀσέβειαν αὐτῶν συμπεσόντα,"},{"number":144,"text":"παρεκάλει δὲ τὸν θεὸν σπέρμα τι καὶ λείψανον ἐκ τῆς τότε συμφορᾶς αὐτῶν καὶ αἰχμαλωσίας περισώσαντα καὶ πάλιν εἰς Ἱεροσόλυμα καὶ τὴν οἰκείαν γῆν ἀποκαταστήσαντα καὶ τοὺς Περσῶν βασιλέας ἀναγκάσαντα λαβεῖν οἶκτον αὐτῶν, καὶ συγγνωμονῆσαι τοῖς νῦν ἡμαρτημένοις, ἄξια μὲν θανάτου πεποιηκόσιν, ὂν δὲ ἐπὶ τῇ τοῦ θεοῦ χρηστότητι καὶ τοὺς τοιούτους ἀφιέναι τῆς κολάσεως."},{"number":145,"text":"Καὶ ὁ μὲν ἐπαύσατο τῶν εὐχῶν· θρηνούντων δὲ πάντων, ὅσοι πρὸς αὐτὸν σὺν γυναιξὶν καὶ τέκνοις συνῆλθον, Ἀχόνιός τις ὀνόματι πρῶτος τῶν Ἱεροσολυμιτῶν, προσελθὼν αὐτοὺς μὲν ἁμαρτεῖν ἔλεγεν ἀλλοεθνεῖς ἐνοικισαμένους γυναῖκας, ἔπειθε δʼ αὐτὸν ἐξορκίσαι πάντας ἐκβαλεῖν αὐτὰς καὶ τὰ ἐξ αὐτῶν γεγενημένα, κολασθήσεσθαι δὲ τοὺς οὐχ ὑπακούσαντας τῷ νόμῳ."},{"number":146,"text":"πεισθεὶς οὖν τούτοις ὁ Ἔζδρας ἐποίησεν ὀμόσαι τοὺς φυλάρχους τῶν ἱερέων καὶ τῶν Λευιτῶν καὶ Ἰσραηλιτῶν ἀποπέμψασθαι τὰς γυναῖκας καὶ τὰ τέκνα κατὰ τὴν Ἀχονίου συμβουλίαν."},{"number":147,"text":"λαβὼν δὲ τοὺς ὅρκους εὐθὺς ὥρμησεν ἀπὸ τοῦ ἱεροῦ εἰς τὸ παστοφόριον τὸ Ἰωάννου τοῦ Ἐλιασίβου καὶ μηδενὸς ὅλως διὰ τὴν λύπην γευσάμενος ἐκείνην τὴν ἡμέραν διήγαγεν αὐτόθι."},{"number":148,"text":"γενομένου δὲ κηρύγματος ὥστε πάντας τοὺς ἀπὸ τῆς αἰχμαλωσίας συνελθεῖν εἰς Ἱεροσόλυμα, ὡς τῶν ἐν δυσὶν ἢ τρισὶν ἡμέραις οὐκ ἀπαντησάντων ἀπαλλοτριωθησομένων τοῦ πλήθους καὶ τῆς οὐσίας αὐτῶν κατὰ τὴν τῶν πρεσβυτέρων κρίσιν ἀφιερωθησομένης, συνῆλθον ἐκ τῆς Ἰουδαϊκῆς καὶ Βενιαμίτιδος ἐν τρισὶν ἡμέραις εἰκάδι τοῦ ἐνάτου μηνός, ὃς κατὰ μὲν Ἑβραίους Ξένιος, κατὰ δὲ Μακεδόνας Ἀπελλαῖος καλεῖται."},{"number":149,"text":"καθισάντων δὲ ἐν τῷ ὑπαίθρῳ τοῦ ἱεροῦ, παρόντων ἅμα καὶ τῶν πρεσβυτέρων καὶ ὑπὸ τοῦ κρύους ἀηδῶς διακειμένων, ἀναστὰς Ἔζδρας ᾐτιᾶτο ἐκείνους λέγων παρανομῆσαι γήμαντας οὐκ ἐξ ὁμοφύλων· νῦν μέντοι γε ποιήσειν αὐτοὺς τῷ μὲν θεῷ κεχαρισμένα συμφέροντα δὲ αὐτοῖς ἀποπεμψαμένους τὰς γυναῖκας."},{"number":150,"text":"οἱ δὲ ποιήσειν μὲν τοῦτο πάντες ἐξεβόησαν, τὸ δὲ πλῆθος εἶναι πολύ, καὶ τὴν ὥραν τοῦ ἔτους χειμέριον, καὶ τὸ ἔργον οὐ μιᾶς οὐδὲ δευτέρας ἡμέρας ὑπάρχειν. ἀλλʼ οἵ τε ἡγεμόνες τούτοις καὶ οἱ συνοικοῦντες ταῖς ἀλλοφύλοις παραγενέσθωσαν λαβόντες χρόνον καὶ πρεσβυτέρους ἐξ οὗ ἂν θελήσωσιν τόπου τοὺς συνεπισκεψομένους τὸ τῶν γεγαμηκότων πλῆθος."},{"number":151,"text":"καὶ ταῦτα δόξαν αὐτοῖς ἀρξάμενοι τῇ νουμηνίᾳ τοῦ δεκάτου μηνὸς ἀναζητεῖν τοὺς συνοικοῦντας ταῖς ἀλλοεθνέσιν εὗρον ἕως τῆς τοῦ μηνὸς τοῦ ἐχομένου νουμηνίας ποιησάμενοι τὴν ἔρευναν πολλοὺς ἔκ τε τῶν Ἰησοῦ ἐκγόνων τοῦ ἀρχιερέως καὶ τῶν ἱερέων καὶ τῶν Λευιτῶν καὶ τῶν Ἰσραηλιτῶν,"},{"number":152,"text":"οἳ καὶ τὰς γυναῖκας καὶ τὰ ἐξ αὐτῶν γεγενημένα τῆς τῶν νόμων φυλακῆς ἢ τῶν πρὸς αὐτὰ φίλτρων ποιούμενοι πλείονα λόγον εὐθὺς ἐξέβαλον καὶ θυσίας ἐξευμενίζοντες τὸν θεὸν ἐπήνεγκαν κριοὺς καταθύσαντες αὐτῷ. τὰ δὲ ὀνόματα αὐτῶν λέγειν οὐκ ἔδοξεν ἡμῖν ἀναγκαῖον εἶναι."},{"number":153,"text":"τὸ μὲν οὖν ἁμάρτημα τὸ περὶ τοὺς γάμους τῶν προειρημένων οὕτως ἐπανορθώσας Ἔζδρας ἐκαθάρισεν τὴν περὶ ταῦτα συνήθειαν, ὥστʼ αὐτὴν τοῦ λοιποῦ μόνιμον εἶναι."},{"number":154,"text":"Τῷ δʼ ἑβδόμῳ μηνὶ τὴν σκηνοπηγίαν ἑορτάζοντες καὶ σχεδὸν ἅπαντος τοῦ λαοῦ συνεληλυθότος ἐπʼ αὐτήν, ἀνελθόντες εἰς τὸ ἀνειμένον τοῦ ναοῦ πρὸς τὴν πύλην τὴν ἐπὶ τὴν ἀνατολὴν ἀποβλέπουσαν ἐδεήθησαν τοῦ Ἔζδρα τοὺς νόμους αὐτοῖς ἀναγνῶναι τοὺς Μωυσέως."},{"number":155,"text":"ὁ δὲ μέσος τοῦ πλήθους σταθεὶς ἀνέγνω καὶ τοῦτʼ ἐποίησεν ἀπʼ ἀρχομένης ἡμέρας ἕως μεσημβρίας· οἱ δὲ ἀκούσαντες ἀναγινωσκομένων τῶν νόμων δίκαιοι μὲν πρὸς τὸ παρὸν καὶ τὸ μέλλον ἐδιδάσκοντο εἶναι, περὶ δὲ τῶν παρῳχημένων ἐδυσφόρουν καὶ μέχρι τοῦ δακρύειν προήχθησαν ἐνθυμούμενοι πρὸς αὑτούς, ὅτι μηδὲν ἂν τῶν πεπειραμένων κακῶν ἔπαθον, εἰ τὸν νόμον διεφύλαττον."},{"number":156,"text":"ὁ δὲ Ἔζδρας οὕτως ὁρῶν αὐτοὺς ἔχοντας ἐκέλευσεν ἀπιέναι πρὸς αὑτοὺς καὶ μὴ δακρύειν· εἶναι γὰρ ἑορτὴν καὶ μὴ δεῖν ἐν αὐτῇ κλαίειν· οὐ γὰρ ἐξεῖναι· προυτρέπετο δὲ μᾶλλον πρὸς εὐωχίαν ὁρμήσαντας ποιεῖν τὰ πρόσφορα τῇ ἑορτῇ καὶ κεχαρισμένα, καὶ τὴν μετάνοιαν καὶ λύπην τὴν ἐπὶ τοῖς ἔμπροσθεν ἐξημαρτημένοις ἀσφάλειάν τε ἕξειν καὶ φυλακὴν τοῦ μηδὲν ὅμοιον συμπεσεῖν."},{"number":157,"text":"οἱ δὲ ταῦτα Ἔζδρα παραινοῦντος ἑορτάζειν ἤρξαντο καὶ τοῦτο ποιοῦντες ἐφʼ ἡμέρας ὀκτὼ ἐν ταῖς σκηναῖς ἀνεχώρησαν εἰς τὰ οἰκεῖα μετὰ ὕμνων τοῦ θεοῦ τῆς ἐπανορθώσεως τῶν περὶ τὸ πολίτευμα παρανομηθέντων Ἔζδρᾳ χάριν εἰδότες."},{"number":158,"text":"ᾧ συνέβη μετὰ τὴν παρὰ τῷ λαῷ δόξαν γηραιῷ τελευτῆσαι τὸν βίον καὶ ταφῆναι μετὰ πολλῆς φιλοτιμίας ἐν Ἱεροσολύμοις. ὑπὸ δὲ τὸν αὐτὸν καιρὸν καὶ Ἰωακείμου τοῦ ἀρχιερέως ἀποθανόντος παῖς αὐτοῦ Ἐλεάσιβος τὴν ἀρχιερωσύνην διεδέξατο."},{"number":159,"text":"Τῶν δʼ αἰχμαλωτισθέντων τις Ἰουδαίων οἰνοχόος τοῦ βασιλέως Ξέρξου Νεεμίας ὄνομα περιπατῶν πρὸ τῆς μητροπόλεως τῶν Περσῶν Σούσων, ξένων τινῶν ἀπὸ μακρᾶς ὁδοιπορίας εἰς τὴν πόλιν εἰσιόντων ἐπακούσας ἑβραϊστὶ πρὸς ἀλλήλους ὁμιλούντων προσελθὼν αὐτοῖς ἐπυνθάνετο, πόθεν εἶεν παραγενόμενοι."},{"number":160,"text":"ἀποκριναμένων δʼ ἥκειν ἐκ τῆς Ἰουδαίας, πῶς αὐτῶν ἔχει τὸ πλῆθος καὶ ἡ μητρόπολις Ἱεροσόλυμα, πάλιν ἤρξατο πυνθάνεσθαι."},{"number":161,"text":"κακῶς δʼ ἔχειν εἰπόντων, καθῃρῆσθαι γὰρ εἰς ἔδαφος τὰ τείχη καὶ τὰ πέριξ ἔθνη πολλὰ διατιθέναι κακὰ τοὺς Ἰουδαίους, ἡμέρας μὲν κατατρεχόντων τὴν χώραν καὶ διαρπαζόντων, τῆς δὲ νυκτὸς κακῶς ἀπεργαζομένων, ὡς πολλοὺς ἐκ τῆς χώρας καὶ ἐξ αὐτῶν τῶν Ἱεροσολύμων αἰχμαλώτους ἀπῆχθαι καὶ τὰς ὁδοὺς πλήρεις εὑρίσκεσθαι καθʼ ἡμέραν νεκρῶν,"},{"number":162,"text":"ἐδάκρυσεν ὁ Νεεμίας ἐλεήσας τῆς συμφορᾶς τοὺς ὁμοφύλους, καὶ ἀναβλέψας εἰς τὸν οὐρανόν, ἄχρι τίνος, εἶπεν, ὦ δέσποτα, περιόψει ταῦτα πάσχον τὸ ἔθνος ἡμῶν οὕτως ἅρπαγμα πάντων καὶ λάφυρον γενόμενον;"},{"number":163,"text":"διατρίβοντος δʼ αὐτοῦ πρὸς τῇ πύλῃ καὶ ταῦτα ἀποδυρομένου προελθών τις ἤγγειλεν αὐτῷ μέλλειν ἤδη κατακλίνεσθαι τὸν βασιλέα. ὁ δʼ εὐθὺς ὡς εἶχεν μηδὲ ἀπολουσάμενος διακονήσων ἔσπευσεν τῷ βασιλεῖ τὴν ἐπὶ τοῦ πότου διακονίαν."},{"number":164,"text":"ὡς δὲ μετὰ τὸ δεῖπνον ὁ βασιλεὺς διεχύθη καὶ ἡδίων αὑτοῦ γενόμενος ἀπέβλεψεν εἰς τὸν Νεεμίαν, κατεσκυθρωπακότα θεασάμενος, διὰ τί κατηφὴς εἴη ἀνέκρινεν."},{"number":165,"text":"ὁ δὲ τοῦ θεοῦ δεηθεὶς χάριν τινὰ καὶ πειθὼ παρασχεῖν αὐτῷ λέγοντι, πῶς, φησίν, ὦ βασιλεῦ, δύναμαί σοι μὴ βλέπεσθαι τοιοῦτος μηδὲ τὴν ψυχὴν ἀλγεῖν, ὅπου τῆς πατρίδος μου Ἱεροσολύμων, ἐν ᾗ τάφοι καὶ μνήματα προγόνων τῶν ἐμῶν εἰσιν, ἀκούω βεβλῆσθαι κατὰ τῆς γῆς τὰ τείχη καὶ τὰς πύλας ἐμπεπρησμένας αὐτῆς; ἀλλὰ χάρισαί μοι πορευθέντι τὸ τεῖχος ἀνεγεῖραι καὶ τοῦ ἱεροῦ τὸ λεῖπον προσοικοδομῆσαι."},{"number":166,"text":"ὁ δὲ βασιλεὺς διδόναι τε τὴν δωρεὰν κατένευσεν καὶ πρὸς τοὺς σατράπας κομίσαι γράμματα, ὅπως τιμῆς τε αὐτὸν ἀξιώσωσι καὶ πᾶσαν παράσχωσιν χορηγίαν εἰς ἅπερ βούλεται. πέπαυσο δή, φησί, λυπούμενος καὶ χαίρων ἡμῖν τοῦ λοιποῦ διακόνει."},{"number":167,"text":"ὁ μὲν οὖν Νεεμίας προσκυνήσας τῷ θεῷ καὶ τῷ βασιλεῖ τῆς ὑποσχέσεως εὐχαριστήσας τὸ κατηφὲς τοῦ προσώπου καὶ συγκεχυμένον ἀπεκάθηρεν τῇ περὶ τῶν ἐπηγγελμένων ἡδονῇ. καλέσας δὲ αὐτὸν τῇ ἐπιούσῃ δίδωσιν αὐτῷ πρὸς Ἀδδαῖον ἐπιστολὴν κομίσαι τὸν τῆς Συρίας καὶ Φοινίκης καὶ Σαμαρείας ἔπαρχον, ἐν ᾗ περί τε τῆς τιμῆς τοῦ Νεεμίου καὶ χορηγίας τῆς εἰς τὴν οἰκοδομίαν ἐπεστάλκει."},{"number":168,"text":"Γενόμενος οὖν ἐν Βαβυλῶνι καὶ πολλοὺς τῶν ὁμοφύλων ἐθελοντὶ ἀκολουθοῦντας αὐτῷ παραλαβὼν ἧκεν εἰς Ἱεροσόλυμα πέμπτον καὶ εἰκοστὸν ἔτος ἤδη βασιλεύοντος Ξέρξου, καὶ δείξας τῷ θεῷ τὰς ἐπιστολὰς ἀποδίδωσιν τῷ Ἀδδαίῳ καὶ τοῖς ἄλλοις ἐπάρχοις, καὶ συγκαλέσας πάντα τὸν λαὸν εἰς Ἱεροσόλυμα στὰς ἐν μέσῳ τῷ ἱερῷ τοιούτους ἐποιήσατο πρὸς αὐτὸν τοὺς λόγους·"},{"number":169,"text":"ἄνδρες Ἰουδαῖοι, τὸν μὲν θεὸν ἴστε μνήμῃ τῶν πατέρων Ἀβράμου καὶ Ἰσάκου καὶ Ἰακώβου παραμένοντα καὶ διὰ τῆς ἐκείνων δικαιοσύνης οὐκ ἐγκαταλείποντα τὴν ὑπὲρ ὑμῶν πρόνοιαν· ἀμέλει συνήργησέν μοι παρὰ τοῦ βασιλέως λαβεῖν ἐξουσίαν, ὅπως ὑμῶν τὸ τεῖχος ἀναστήσω καὶ τὸ λείψανον τοῦ ἱεροῦ τελειώσω."},{"number":170,"text":"βούλομαι δʼ ὑμᾶς τὴν τῶν γειτονευόντων ἡμῖν ἐθνῶν δυσμένειαν σαφῶς εἰδότας, καὶ ὅτι πρὸς τὴν οἰκοδομίαν, εἰ μάθοιεν περὶ ταύτην ἡμᾶς φιλοτιμουμένους, ἐνστήσονται καὶ πολλὰ πραγματεύσονται πρὸς αὐτὴν ἡμῖν ἐμπόδια,"},{"number":171,"text":"θαρρεῖν μὲν τῷ θεῷ πρῶτον ὡς καὶ πρὸς τὴν ἐκείνων ἀπέχθειαν στησομένους, μήτε δʼ ἡμέρας μήτε νυκτὸς αὐτοὺς ἀνιέναι τῆς οἰκοδομίας, ἀλλὰ πάσῃ σπουδῇ χρωμένους συνέχειν τὸ ἔργον, ὥς γε καιρὸς ἴδιός ἐστιν."},{"number":172,"text":"ταῦτʼ εἰπὼν ἐκέλευσεν εὐθὺς τοὺς ἄρχοντας μετρῆσαι τὸ τεῖχος καὶ διανεῖμαι τὴν ἐργασίαν αὐτοῦ τῷ λαῷ κατὰ κώμας τε καὶ πόλεις κατὰ τὸ ἑκάστοις δυνατόν, ὑποσχόμενος δὲ καὶ αὐτὸς μετὰ τῶν οἰκετῶν συλλήψεσθαι πρὸς τὴν οἰκοδομίαν διέλυσε τὴν ἐκκλησίαν."},{"number":173,"text":"καὶ οἱ Ἰουδαῖοι πρὸς τὸ ἔργον παρεσκευάζοντο. ἐκλήθησαν δὲ τὸ ὄνομα ἀφʼ ἧς ἡμέρας ἐκ Βαβυλῶνος ἀνέβησαν ἐκ τῆς Ἰούδα φυλῆς, ἧς πρώτης ἐλθούσης εἰς ἐκείνους τοὺς τόπους αὐτοί τε καὶ ἡ χώρα τὴν προσηγορίαν αὐτοῖς μετέλαβον."},{"number":174,"text":"Ἀκούσαντες δὲ τὴν τῶν τειχῶν οἰκοδομὴν σπευδομένην Ἀμμανῖται καὶ Μωαβῖται καὶ Σαμαρεῖται καὶ πάντες οἱ ἐν τῇ κοίλῃ Συρίᾳ νεμόμενοι χαλεπῶς ἔφερον καὶ διετέλουν ἐπιβουλὰς αὐτοῖς συντιθέντες τὴν προαίρεσιν αὐτῶν ἐμποδίζοντες, πολλούς τε τῶν Ἰουδαίων ἀπέκτειναν καὶ αὐτὸν ἐζήτουν τὸν Νεεμίαν διαφθεῖραι μισθούμενοί τινας τῶν ἀλλοφύλων, ἵνʼ αὐτὸν ἀνέλωσιν."},{"number":175,"text":"εἰς φόβον δὲ καὶ ταραχὴν αὐτοὺς ἐνέβαλλον καὶ φήμας αὐτοῖς διέστελλον ὡς πολλῶν ἐπιστρατεύειν αὐτοῖς μελλόντων ἐθνῶν, ὑφʼ ὧν ἐκταρασσόμενοι μικροῦ τῆς οἰκοδομίας ἀπέστησαν."},{"number":176,"text":"τὸν δὲ Νεεμίαν οὐδὲν τούτων ἐξέστησεν τῆς σπουδῆς τῆς περὶ τὸ ἔργον, ἀλλὰ στῖφός τι φυλακῆς ἕνεκα τοῦ σώματος περιβαλλόμενος ἀτρύτως ὑπέμενεν, ὑπὸ τῆς περὶ τὸ ἔργον ἐπιθυμίας ἀναισθητῶν καὶ τῆς ταλαιπωρίας. οὕτως δὲ καὶ συντεταμένως καὶ προνοητικῶς αὐτοῦ τῆς σωτηρίας εἶχεν οὐχὶ φοβούμενος τὸν θάνατον, ἀλλὰ πεπεισμένος, ὅτι μετὰ τὴν αὐτοῦ τελευτὴν οὐκέτʼ αὐτοῦ τοῖς πολίταις ἀναστήσεται τὰ τείχη."},{"number":177,"text":"ἐκέλευσεν δὲ ἑξῆς τοὺς οἰκοδομοῦντας ὅπλα περιζωννυμένους ἐργάζεσθαι, καὶ ὁ μὲν οἰκοδόμος μάχαιραν εἶχεν καὶ ὁ τὴν ὕλην παρακομίζων, θυρεοὺς δʼ ἔγγιστα αὐτῶν ἐκέλευσεν κεῖσθαι καὶ σαλπιγκτὰς ἀπὸ πεντακοσίων ἔστησεν ποδῶν προστάξας, ἂν ἐπιφανῶσιν οἱ πολέμιοι, τοῦτο σημῆναι τῷ λαῷ, ἵνʼ ὁπλισάμενοι μάχωνται καὶ μὴ γυμνοῖς αὐτοῖς ἐπιπέσωσιν."},{"number":178,"text":"αὐτὸς δὲ νύκτωρ περιήρχετο τῆς πόλεως τὸν κύκλον οὐδὲν κάμνων οὔτε τοῖς ἔργοις οὔτε τῇ διαίτῃ οὔτε τοῖς ὕπνοις· οὐδενὶ γὰρ τούτων πρὸς ἡδονὴν ἀλλὰ πρὸς ἀνάγκην ἐχρῆτο."},{"number":179,"text":"καὶ ταύτην ὑπέμεινε τὴν ταλαιπωρίαν ἐπὶ ἔτη δύο καὶ μῆνας τέσσαρας· ἐν τούτῳ γὰρ τῷ χρόνῳ τοῖς Ἱεροσολύμοις ἀνῳκοδομήθη τὸ τεῖχος, ὀγδόῳ καὶ εἰκοστῷ τῆς Ξέρξου βασιλείας ἔτει μηνὶ ἐνάτῳ."},{"number":180,"text":"τέλος δὲ τῶν τειχῶν λαβόντων Νεεμίας καὶ τὸ πλῆθος ἔθυσαν τῷ θεῷ ὑπὲρ τῆς τούτων οἰκοδομίας καὶ διῆγον ἐφʼ ἡμέρας ὀκτὼ εὐωχούμενοι. τὰ μὲν οὖν ἔθνη τὰ ἐν τῇ Συρίᾳ κατῳκημένα τῆς τῶν τειχῶν οἰκοδομίας πέρας ἔχειν ἀκουσθείσης ἐδυσφόρει."},{"number":181,"text":"Νεεμίας δὲ τὴν πόλιν ὁρῶν ὀλιγανθρωπουμένην τοὺς ἱερεῖς τε καὶ Λευίτας παρεκάλεσεν τὴν χώραν ἐκλιπόντας μετελθεῖν εἰς τὴν πόλιν καὶ μένειν ἐν αὐτῇ κατασκευάσας τὰς οἰκίας αὐτοῖς ἐκ τῶν ἰδίων ἀναλωμάτων·"},{"number":182,"text":"τόν τε γεωργοῦντα λαὸν τὰς δεκάτας τῶν καρπῶν ἐκέλευσε φέρειν εἰς Ἱεροσόλυμα, ἵνα τρέφεσθαι διηνεκῶς ἔχοντες οἱ ἱερεῖς καὶ Λευῖται μὴ καταλείπωσι τὴν θρησκείαν. καὶ οἱ μὲν ἡδέως ὑπήκουσαν οἷς Νεεμίας διετάξατο, πολυανθρωποτέραν δὲ τὴν τῶν Ἱεροσολυμιτῶν πόλιν οὕτως συνέβη γενέσθαι."},{"number":183,"text":"πολλὰ δὲ καὶ ἄλλα καλὰ καὶ ἐπαίνων ἄξια φιλοτιμησάμενος ὁ Νεεμίας ἐτελεύτησεν εἰς γῆρας ἀφικόμενος. ἀνὴρ δὲ ἐγένετο χρηστὸς τὴν φύσιν καὶ δίκαιος καὶ περὶ τοὺς ὁμοεθνεῖς φιλοτιμότατος, μνημεῖον αἰώνιον αὐτῷ καταλιπὼν τὰ τῶν Ἱεροσολύμων τείχη. ταῦτα μὲν οὖν ἐπὶ Ξέρξου βασιλέως ἐγένετο."}],"6":[{"number":184,"text":"Τελευτήσαντος δὲ Ξέρξου τὴν βασιλείαν εἰς τὸν υἱὸν Κῦρον, ὃν Ἀρταξέρξην Ἕλληνες καλοῦσιν, συνέβη μεταβῆναι. τούτου τὴν Περσῶν ἔχοντος ἡγεμονίαν ἐκινδύνευσεν τὸ τῶν Ἰουδαίων ἔθνος ἅπαν σὺν γυναιξὶ καὶ τέκνοις ἀπολέσθαι. τὴν δʼ αἰτίαν μετʼ οὐ πολὺ δηλώσομεν·"},{"number":185,"text":"πρέπει γὰρ τὰ τοῦ βασιλέως διηγεῖσθαι πρῶτον, ὡς ἔγημεν Ἰουδαίαν γυναῖκα τοῦ γένους οὖσαν τοῦ βασιλικοῦ, ἣν καὶ σῶσαι τὸ ἔθνος ἡμῶν λέγουσιν."},{"number":186,"text":"παραλαβὼν γὰρ τὴν βασιλείαν ὁ Ἀρταξέρξης καὶ καταστήσας ἀπὸ Ἰνδίας ἄχρι Αἰθιοπίας τῶν σατραπειῶν ἑκατὸν καὶ εἰκοσιεπτὰ οὐσῶν ἄρχοντας, τῷ τρίτῳ τῆς βασιλείας ἔτει τούς τε φίλους καὶ τὰ Περσῶν ἔθνη καὶ τοὺς ἡγεμόνας αὐτῶν ὑποδεξάμενος ἑστιᾷ πολυτελῶς, οἷον εἰκὸς παρὰ βασιλεῖ τοῦ πλούτου παρασκευαζομένῳ τὴν ἐπίδειξιν ποιήσασθαι, ἐπὶ ἡμέρας ἑκατὸν ὀγδοήκοντα."},{"number":187,"text":"ἔπειτα τὰ ἔθνη καὶ τοὺς πρεσβευτὰς αὐτῶν ἐν Σούσοις ἐπὶ ἡμέρας κατευώχησεν ἑπτά. τὸ δὲ συμπόσιον ἦν αὐτοῖς τὸν τρόπον τοῦτον γεγενημένον· σκήνωμα πηξάμενος ἐκ χρυσέων καὶ ἀργυρέων κιόνων ὕφη λίνεα καὶ πορφύρεα κατʼ αὐτῶν διεπέτασεν, ὥστε πολλὰς μυριάδας κατακλίνεσθαι."},{"number":188,"text":"διηκονοῦντο δʼ ἐκπώμασι χρυσέοις καὶ τοῖς διὰ λίθου πολυτελοῦς εἰς τέρψιν ἅμα καὶ θέαν πεποιημένοις. προσέταττεν δὲ καὶ τοῖς διακόνοις μὴ βιάζεσθαι πίνειν τὸ ποτὸν αὐτοῖς συνεχῶς προσφέροντας, ὡς καὶ παρὰ Πέρσαις γίγνεται, ἀλλʼ ἐπιτρέπειν αὐτοῖς καὶ πρὸς ὃ βούλεται τῶν κατακειμένων ἕκαστος φιλοφρονεῖσθαι."},{"number":189,"text":"διαπέμψας δὲ καὶ κατὰ τὴν χώραν παρήγγειλεν ἀνεῖσθαι τῶν ἔργων ἀφιεμένους καὶ ἑορτάζειν ὑπὲρ τῆς βασιλείας αὐτοῦ πολλαῖς ἡμέραις."},{"number":190,"text":"ὁμοίως τε τῶν γυναικῶν ἡ βασίλισσα Ἄστη συνήγαγεν συμπόσιον ἐν τοῖς βασιλείοις, ἣν ἐπιδεῖξαι βουλόμενος τοῖς ἑστιωμένοις ὁ βασιλεὺς πέμψας ἐκέλευσεν αὐτὴν εἰς τὸ συμπόσιον ἥκειν κάλλει τὰς γυναῖκας ἁπάσας ὑπερβάλλουσαν."},{"number":191,"text":"ἡ δὲ φυλακῇ τῶν παρὰ Πέρσαις νόμων, οἳ τοῖς ἀλλοτρίοις βλέπεσθαι τὰς γυναῖκας ἀπηγορεύκασιν, οὐκ ἐπορεύετο πρὸς τὸν βασιλέα, καὶ πολλάκις τοὺς εὐνούχους ἀποστέλλοντος πρὸς αὐτὴν οὐδὲν ἧττον ἐνέμεινεν παραιτουμένη τὴν ἄφιξιν,"},{"number":192,"text":"ὡς εἰς ὀργὴν παροξυνθέντα τὸν βασιλέα λῦσαι μὲν τὸ συμπόσιον, ἀναστάντα δὲ καὶ τοὺς ἑπτὰ τῶν Περσῶν, οἳ τὴν τῶν νόμων ἐξήγησιν ἔχουσι παρʼ αὐτοῖς, καλέσαντα κατηγορεῖν τῆς γυναικὸς καὶ λέγειν, ὡς ὑβρισθείη πρὸς αὐτῆς· κληθεῖσα γὰρ ὑπʼ αὐτοῦ πολλάκις εἰς τὸ συμπόσιον ὑπήκουσεν οὐδὲ ἅπαξ."},{"number":193,"text":"προσέταξεν οὖν δηλοῦν, τίνα κατʼ αὐτῆς νόμον ὁρίζουσιν. ἑνὸς δʼ ἐξ αὐτῶν Μουχαίου ὄνομα εἰπόντος οὐκ αὐτῷ μόνῳ ταύτην γεγονέναι τὴν ὕβριν, ἀλλὰ πᾶσι Πέρσαις, οἷς κινδυνεύεται καταφρονουμένοις ὑπὸ τῶν γυναικῶν αἴσχιστα διαγεγονέναι τὸν βίον·"},{"number":194,"text":"οὐδεμία γὰρ τοῦ συνοικοῦντος ἀνδρὸς αἰδῶ ποιήσεται παράδειγμα τὴν τῆς βασιλίσσης ὑπερηφανίαν πρὸς σὲ τὸν κρατοῦντα ἁπάντων ἔχουσα. παρακελευομένου δὲ τὴν οὕτως ἐνυβρίζουσαν αὐτῷ ζημιῶσαι μεγάλην ζημίαν καὶ τοῦτο ποιήσαντα διαγγεῖλαι τοῖς ἔθνεσιν τὰ περὶ τῆς βασιλίσσης κεκυρωμένα, ἔδοξε τὴν Ἄστην ἐκβαλεῖν καὶ δοῦναι τὴν ἐκείνης τιμὴν ἑτέρᾳ γυναικί."},{"number":195,"text":"Διακείμενος δὲ πρὸς αὐτὴν ἐρωτικῶς καὶ μὴ φέρων τὴν διάζευξιν, καταλλαγῆναι μὲν αὐτῇ διὰ τὸν νόμον οὐκ ἐδύνατο, λυπούμενος δὲ ὡς ἐπʼ ἀδυνάτοις οἷς ἤθελεν διετέλει. βλέποντες δʼ αὐτὸν οὕτως ἔχοντα χαλεπῶς οἱ φίλοι συνεβούλευον τὴν μὲν τῆς γυναικὸς μνήμην καὶ τὸν ἔρωτα μηδὲν ὠφελούμενον ἐκβαλεῖν,"},{"number":196,"text":"ζητῆσαι δὲ περιπέμψαντα καθʼ ὅλην τὴν οἰκουμένην παρθένους εὐπρεπεῖς, ὧν τὴν προκριθεῖσαν ἕξειν γυναῖκα· σβέννυσθαι γὰρ τὸ πρὸς τὴν προτέραν φιλόστοργον ἑτέρας ἐπεισαγωγῇ, καὶ τὸ πρὸς ἐκείνην εὔνουν ἀποσπώμενον κατὰ μικρὸν γίνεσθαι τῆς συνούσης."},{"number":197,"text":"πεισθεὶς δὲ τῇ συμβουλίᾳ ταύτῃ προσέταξέ τισιν ἐπιλεξαμένους τὰς εὐδοκιμούσας ἐπʼ εὐμορφίᾳ τῶν ἐν τῇ βασιλείᾳ παρθένων ἀγαγεῖν πρὸς αὐτόν."},{"number":198,"text":"συναχθεισῶν δὲ πολλῶν εὑρέθη τις ἐν Βαβυλῶνι κόρη τῶν γονέων ἀμφοτέρων ὀρφανὴ παρὰ τῷ θείῳ Μαρδοχαίῳ, τοῦτο γὰρ ἦν ὄνομα αὐτῷ, τρεφομένη· οὗτος δʼ ἦν ἐκ τῆς Βενιαμίτιδος φυλῆς, τῶν δὲ πρώτων παρὰ τοῖς Ἰουδαίοις."},{"number":199,"text":"πασῶν δὲ τὴν Ἐσθῆρα συνέβαινεν, τοῦτο γὰρ ἦν αὐτῇ τοὔνομα, τῷ κάλλει διαφέρειν καὶ τὴν χάριν τοῦ προσώπου τὰς ὄψεις τῶν θεωμένων μᾶλλον ἐπάγεσθαι."},{"number":200,"text":"παραδοθεῖσα δὲ αὕτη τινὶ τῶν εὐνούχων εἰς ἐπιμέλειαν πάσης ἐτύγχανε προνοίας ἀρωμάτων ἀφθονίᾳ καὶ πολυτελείᾳ τῶν ἀλειμμάτων ὧν χρῄζει τὰ σώματα καταρδομένη, καὶ τούτων ἀπέλαυον ἐπὶ μῆνας ἓξ τετρακόσιαι τὸν ἀριθμὸν οὖσαι."},{"number":201,"text":"ὅτε δʼ ἐνόμιζεν ἀποχρώντως τῷ προειρημένῳ χρόνῳ τὴν ἐπιμέλειαν ἔχειν τὰς παρθένους καὶ τοῦ βαδίζειν αὐτὰς ἐπὶ κοίτην βασιλέως ἀξίας ἤδη γεγονέναι, καθʼ ἑκάστην ἡμέραν μίαν ἔπεμπεν τῷ βασιλεῖ συνεσομένην."},{"number":202,"text":"ὁ δὲ πλησιάζων εὐθὺς ἀπέπεμπεν πρὸς τὸν εὐνοῦχον. ἀφικομένης δὲ τῆς Ἐσθήρας πρὸς αὐτὸν ἡσθεὶς αὐτῇ καὶ πεσὼν τῆς κόρης εἰς ἔρωτα νομίμως αὐτὴν ἄγεται γυναῖκα καὶ γάμους αὐτῇ ποιεῖται δωδεκάτῳ μηνὶ ἑβδόμου ἔτους τῆς αὐτοῦ βασιλείας, Ἀδέρῳ δὲ καλουμένῳ."},{"number":203,"text":"διέπεμψε δὲ τοὺς ἀγγάρους λεγομένους εἰς πᾶν ἔθνος ἑορτάζειν τοὺς γάμους παραγγέλλων, αὐτὸς δὲ Πέρσας καὶ τοὺς Μήδους καὶ τοὺς πρώτους τῶν ἐθνῶν ἑστιᾷ ἐπὶ μῆνα ὅλον ὑπὲρ τῶν γάμων αὐτοῦ, εἰσελθούσῃ δὲ εἰς τὸ βασίλειον περιτίθησι τὸ διάδημα, καὶ συνῴκησεν οὕτως Ἐσθήρα μὴ ποιήσασα φανερὸν αὐτῷ τὸ ἔθνος, ἐξ οὗπερ εἴη τυγχάνουσα."},{"number":204,"text":"μεταβὰς δὲ ὁ θεῖος αὐτῆς ἐκ Βαβυλῶνος εἰς Σοῦσα τῆς Περσίδος αὐτόθι διῆγεν ἑκάστης ἡμέρας πρὸς τοῖς βασιλείοις διατρίβων καὶ πυνθανόμενος περὶ τῆς κόρης, τίνα διάγει τρόπον· ἔστεργεν γὰρ αὐτὴν ὡς αὑτοῦ θυγατέρα."},{"number":205,"text":"Ἔθηκε δὲ καὶ νόμον ὁ βασιλεὺς ὥστε μηδένα τῶν ἰδίων αὐτῷ προσιέναι μὴ κληθέντα, ὁπηνίκα ἐπὶ τοῦ θρόνου καθέζοιτο. περιεστήκεσαν δὲ τὸν θρόνον αὐτοῦ πελέκεις ἔχοντες ἄνθρωποι πρὸς τὸ κολάζειν τοὺς προσιόντας ἀκλήτους τῷ θρόνῳ."},{"number":206,"text":"καθῆστο μέντοι λύγον χρυσέαν ἔχων αὐτὸς ὁ βασιλεύς, ἣν ὅτε τινὰ σώζειν ἤθελεν τῶν ἀκλήτων προσιόντων ἐξέτεινεν πρὸς αὐτόν· ὁ δὲ ἁπτόμενος αὐτῆς ἀκίνδυνος ἦν. καὶ περὶ μὲν τούτων ἀρκούντως ἡμῖν δεδήλωται."},{"number":207,"text":"Χρόνῳ δʼ ὕστερον ἐπιβουλευσάντων τῷ βασιλεῖ Βαγαθώου καὶ Θεοδοσίτου Βαρνάβαζος τῶν εὐνούχων οἰκέτης τοῦ ἑτέρου τὸ γένος ὢν Ἰουδαῖος συνεὶς τὴν ἐπιβουλὴν τῷ θείῳ κατεμήνυσε τῆς γυναικὸς τοῦ βασιλέως, Μαρδοχαῖος δὲ διὰ τῆς Ἐσθήρας φανεροὺς ἐποίησε τῷ βασιλεῖ τοὺς ἐπιβουλεύοντας."},{"number":208,"text":"ταραχθεὶς δὲ ὁ βασιλεὺς τἀληθὲς ἐξεῦρεν καὶ τοὺς μὲν εὐνούχους ἀνεσταύρωσεν, τῷ δὲ Μαρδοχαίῳ τότε μὲν οὐδὲν παρέσχεν ὡς αἰτίῳ τῆς σωτηρίας γεγονότι, μόνον δὲ αὐτοῦ τὸ ὄνομα τοῖς τὰ ὑπομνήματα συγγραφομένοις ἐκέλευσε σημειώσασθαι καὶ προσμένειν αὐτὸν τοῖς βασιλείοις ὄντα φίλον ἀναγκαιότατον τῷ βασιλεῖ."},{"number":209,"text":"Ἀμάνην δὲ Ἀμαδάθου μὲν υἱὸν τὸ γένος δὲ Ἀμαληκίτην εἰσιόντα πρὸς τὸν βασιλέα προσεκύνουν οἵ τε ξένοι καὶ Πέρσαι ταύτην αὐτῷ τὴν τιμὴν παρʼ αὐτῶν Ἀρταξέρξου κελεύοντος γενέσθαι."},{"number":210,"text":"Μαρδοχαίου δὲ διὰ σοφίαν καὶ τὸν οἴκοθεν αὐτοῦ νόμον οὐ προσκυνοῦντος ἄνθρωπον, παραφυλάξας ὁ Ἀμάνης ἐπυνθάνετο, πόθεν εἴη. μαθὼν δʼ αὐτὸν ὄντα Ἰουδαῖον ἠγανάκτησεν καὶ πρὸς ἑαυτὸν εἶπεν, ὡς οἱ μὲν ἐλεύθεροι Πέρσαι προσκυνοῦσιν αὐτόν, οὗτος δὲ δοῦλος ὢν οὐκ ἀξιοῖ τοῦτο ποιεῖν."},{"number":211,"text":"καὶ τιμωρήσασθαι θελήσας τὸν Μαρδοχαῖον αὐτὸν μὲν αἰτήσασθαι πρὸς κόλασιν παρὰ τοῦ βασιλέως μικρὸν ἡγήσατο, τὸ ἔθνος δὲ αὐτοῦ διέγνω πᾶν ἀφανίσαι· καὶ γὰρ φύσει τοῖς Ἰουδαίοις ἀπηχθάνετο, ὅτι καὶ τὸ γένος τῶν Ἀμαληκιτῶν, ἐξ ὧν ἦν αὐτός, ὑπʼ αὐτῶν διέφθαρτο."},{"number":212,"text":"προσελθὼν οὖν τῷ βασιλεῖ κατηγόρει λέγων ἔθνος εἶναι πονηρόν, διεσπάρθαι δὲ τοῦτο κατὰ τῆς ὑπʼ αὐτοῦ βασιλευομένης οἰκουμένης, ἄμικτον ἀσύμφυλον οὔτε θρησκείαν τὴν αὐτὴν τοῖς ἄλλοις ἔχον οὔτε νόμοις χρώμενον ὁμοίοις, ἐχθρὸν δὲ καὶ τοῖς ἔθεσι καὶ τοῖς ἐπιτηδεύμασιν τῷ σῷ λαῷ καὶ ἅπασιν ἀνθρώποις."},{"number":213,"text":"τοῦτο τὸ ἔθνος, εἴ τινα θέλεις τοῖς ὑπηκόοις εὐεργεσίαν καταθέσθαι, κελεύσεις πρόρριζον ἀπολέσθαι μηδέ τι αὐτοῦ λείψανον καταλιπεῖν μήτʼ εἰς δουλείαν τινῶν φυλαχθέντων μήτε αἰχμαλωσίᾳ."},{"number":214,"text":"ἵνα μέντοι μὴ ζημιωθῇς τοὺς φόρους τοὺς παρʼ αὐτῶν γινομένους, ἐκ τῆς ἰδίας οὐσίας αὐτὸς ἐπηγγείλατο μυριάδας δώσειν ταλάντων ἀργυρίου τέσσαρας, ὅπου ἂν κελεύσῃ. ταῦτα δὲ τὰ χρήματα παρέχειν ἡδέως ἔλεγεν, ἵνʼ ἀπὸ τούτων εἰρηνευθῇ τῶν κακῶν ἡ βασιλεία."},{"number":215,"text":"Ταῦτα τοῦ Ἀμάνου ἀξιώσαντος ὁ βασιλεὺς καὶ τὸ ἀργύριον αὐτῷ χαρίζεται καὶ τοὺς ἀνθρώπους, ὥστε ποιεῖν αὐτοὺς ὅ τι βούλεται. τυχὼν δὲ ὧν ἐπεθύμει Ἀμάνης παραχρῆμα πέμπει διάταγμα ὡς τοῦ βασιλέως εἰς ἅπαντα τὰ ἔθνη περιέχον τοῦτον τὸν τρόπον·"},{"number":216,"text":"βασιλεὺς μέγας Ἀρταξέρξης τοῖς ἀπὸ Ἰνδικῆς ἕως τῆς Αἰθιοπίας ἑπτὰ καὶ εἴκοσι καὶ ἑκατὸν σατραπειῶν ἄρχουσι τάδε γράφει. πολλῶν ἐθνῶν ἄρξας καὶ πάσης ἧς ἐβουλήθην κρατήσας οἰκουμένης καὶ μηδὲν ὑπὸ τῆς ἐξουσίας ὑπερήφανον μηδὲ σκαιὸν εἰς τοὺς ἀρχομένους ἀναγκασθεὶς ἁμαρτεῖν, ἀλλʼ ἐπιεικῆ καὶ πρᾷον ἐμαυτὸν παρασχὼν καὶ προνοησάμενος εἰρήνης καὶ εὐνομίας αὐτοῖς, ἐζήτουν πῶς εἰς ἅπαντα τούτων ἀπολαύειν αὐτοῖς γένοιτο."},{"number":217,"text":"τοῦ δὲ διὰ σωφροσύνην καὶ δικαιοσύνην παρʼ ἐμοὶ τὴν πρώτην μοῖραν δόξης καὶ τιμῆς ἔχοντος καὶ μετʼ ἐμὲ δευτέρου διὰ πίστιν καὶ βέβαιον εὔνοιαν Ἀμάνου κηδεμονικῶς ὑποδείξαντός μοι παντάπασιν ἀνθρώποις ἀναμεμῖχθαι δυσμενὲς ἔθνος καὶ τοῖς νόμοις ἀλλόκοτον καὶ τοῖς βασιλεῦσιν ἀνυπότακτον καὶ παρηλλαγμένον τοῖς ἔθεσι καὶ τὴν μοναρχίαν μισοῦν καὶ δύσνουν τοῖς ἡμετέροις πράγμασι,"},{"number":218,"text":"κελεύω τοὺς δηλουμένους ὑπὸ τοῦ δευτέρου μου πατρὸς Ἀμάνου πάντας σὺν γυναιξὶ καὶ τέκνοις ἀπολέσαι μηδεμίαν φειδῶ ποιησαμένους, μηδʼ ἐλέῳ πλέον ἢ τοῖς ἐπεσταλμένοις πεισθέντας παρακοῦσαι τῶν γεγραμμένων."},{"number":219,"text":"καὶ τοῦτο γενέσθαι βούλομαι τῇ τετράδι καὶ δεκάτῃ τοῦ δωδεκάτου μηνὸς τοῦ ἐνεστῶτος ἔτους, ὅπως οἱ πανταχόθεν ἡμῖν πολέμιοι μιᾷ ἡμέρᾳ διαφθαρέντες τοῦ λοιποῦ μετʼ εἰρήνης ἡμῖν τὸν βίον διάγειν παρέχωσι."},{"number":220,"text":"τούτου κομισθέντος τοῦ προστάγματος εἰς τὰς πόλεις καὶ τὴν χώραν ἕτοιμοι πάντες ἐπὶ τὴν τῶν Ἰουδαίων ἀπώλειαν εἰς τὴν προειρημένην ἡμέραν ἐγίνοντο· ἐσπεύδετο δὲ τοῦτο καὶ ἐν τῇ Σούσῃ. ὁ μὲν οὖν βασιλεὺς καὶ ὁ Ἀμάνης πρὸς εὐωχίαις καὶ πότοις ἦσαν, ἐν ταραχῇ δʼ ἦν ἡ πόλις."},{"number":221,"text":"Ὁ δὲ Μαρδοχαῖος μαθὼν τὸ γινόμενον περιρρηξάμενος τὴν ἐσθῆτα καὶ σάκκον ἐνδυσάμενος καὶ καταχεάμενος σποδιὰν διὰ τῆς πόλεως ἐφέρετο βοῶν, ὅτι μηδὲν ἀδικῆσαν ἔθνος ἀναιρεῖται, καὶ τοῦτο λέγων ἕως τῶν βασιλείων ἦλθεν καὶ πρὸς αὐτοῖς ἔστη· οὐ γὰρ ἐξῆν εἰσελθεῖν αὐτῷ τοιοῦτον περικειμένῳ σχῆμα."},{"number":222,"text":"τὸ δʼ αὐτὸ καὶ πάντες ἐποίησαν οἱ ἐν ταῖς πόλεσιν Ἰουδαῖοι, ἐν αἷς τὰ περὶ τούτων προετέθη γράμματα, θρηνοῦντες καὶ τὰς κατηγγελμένας αὐτοῖς συμφορὰς ὀδυρόμενοι. ὡς δʼ ἀπήγγειλάν τινες τῇ βασιλίσσῃ τὸν Μαρδοχαῖον ἐν οὕτως οἰκτρῷ σχήματι πρὸ τῆς αὐλῆς ἑστῶτα, ταραχθεῖσα πρὸς τὴν ἀκοὴν ἐξέπεμπεν τοὺς μεταμφιάσοντας αὐτόν."},{"number":223,"text":"οὐ πεισθέντος δὲ ἀποδύσασθαι τὸν σάκκον, οὐ γὰρ ἐφʼ ᾧ τοῦτον ἀναγκασθείη λαβεῖν δεινῷ πεπαῦσθαι τοῦτο, προσκαλεσαμένη τὸν εὐνοῦχον Ἀχράθεον, καὶ γὰρ ἔτυχεν αὐτῇ παρών, ἀπέστειλεν Μαρδοχαίῳ γνωσόμενον, τίνος συμβεβηκότος αὐτῷ σκυθρωποῦ πενθεῖ καὶ τὸ σχῆμα τοῦτο περικείμενος οὐδʼ αὐτῆς παρακαλούσης ἀπέθετο."},{"number":224,"text":"ὁ δὲ Μαρδοχαῖος ἐπέδειξε τῷ εὐνούχῳ τὴν αἰτίαν τό τε γράμμα τὸ κατὰ τῶν Ἰουδαίων εἰς ἅπασαν τὴν ὑπὸ τῷ βασιλεῖ χώραν διαπεμφθὲν καὶ τὴν τῶν χρημάτων ὑπόσχεσιν, ᾗ τὴν ἀπώλειαν τοῦ ἔθνους ᾐτεῖτο παρὰ τοῦ βασιλέως Ἀμάνης."},{"number":225,"text":"δοὺς δὲ αὐτῷ καὶ τὸ ἀντίγραφον τῶν ἐν Σούσοις προτεθέντων κομίσαι τῇ Ἐσθῆρι καὶ περὶ τούτων δεηθῆναι τοῦ βασιλέως ἐνετέλλετο καὶ σωτηρίας ἕνεκεν τοῦ ἔθνους μὴ ἀδοξῆσαι λαβεῖν σχῆμα ταπεινόν, ᾧ παραιτήσεται τοὺς Ἰουδαίους κινδυνεύοντας ἀπολέσθαι· τὸν γὰρ τὴν δευτέραν ἔχοντα τῷ βασιλεῖ τιμὴν Ἀμάνην κατηγορήσαντʼ αὐτῶν παρωξυγκέναι κατʼ αὐτῶν τὸν βασιλέα."},{"number":226,"text":"ταῦτα γνοῦσα πέμπει πάλιν πρὸς Μαρδοχαῖον δηλοῦσα, ὅτι μήτε κληθείη πρὸς τοῦ βασιλέως καὶ ὁ εἰσερχόμενος πρὸς αὐτὸν ἄκλητος ἀποθνήσκει, πλὴν εἰ μή τινα σώζειν βουλόμενος προτείνειεν τὸν χρυσῆν ῥάβδον· ᾧ γὰρ τοῦτο ποιήσειεν ὁ βασιλεὺς ἀκλήτῳ προσελθόντι, οὗτος οὐκ ἀποθνήσκει μόνος, ἀλλὰ συγγνώμης τυχὼν σώζεται."},{"number":227,"text":"Μαρδοχαῖος δὲ τούτους κομίσαντος αὐτῷ τοῦ εὐνούχου παρὰ τῆς Ἐσθῆρος τοὺς λόγους ἀπαγγέλλειν ἐκέλευσεν αὐτῇ, μὴ τὴν ἰδίαν οὕτως σκοπεῖν σωτηρίαν, ἀλλὰ τὴν κοινὴν τοῦ ἔθνους· εἰ γὰρ ἀμελήσειεν τούτου νῦν, ἔσεσθαι μὲν αὐτῷ βοήθειαν παρὰ τοῦ θεοῦ πάντως, αὐτὴν δὲ καὶ τὸν πατρῷον οἶκον αὐτῆς ὑπὸ τῶν ὀλιγωρηθέντων διαφθαρήσεσθαι."},{"number":228,"text":"ἡ δὲ Ἐσθήρα ἐπέστειλεν μὲν τῷ Μαρδοχαίῳ τὸν αὐτὸν πέμψασα διάκονον εἰς Σοῦσα πορευθέντι τοὺς ἐκεῖ Ἰουδαίους εἰς ἐκκλησίαν συναγαγεῖν καὶ νηστεῦσαι πάντων ἀποσχομένους ὑπὲρ αὐτῆς ἐπὶ τρεῖς ἡμέρας, τὸ δʼ αὐτὸ ποιήσασα μετὰ τῶν θεραπαινίδων τότε προσελεύσεσθαι τῷ βασιλεῖ παρὰ τὸν νόμον ὑπισχνεῖτο, κἂν ἀποθανεῖν δέῃ τοῦτο ὑπομενεῖν."},{"number":229,"text":"Καὶ Μαρδοχαῖος μὲν κατὰ τὰς Ἐσθῆρος ἐντολὰς τόν τε λαὸν ἐποίησεν νηστεῦσαι καὶ τὸν θεὸν αὐτὸς ἱκέτευσε μηδὲ νῦν ὑπεριδεῖν αὐτοῦ τὸ ἔθνος ἀπολλύμενον, ἀλλʼ ὡς καὶ πρότερον αὐτοῦ πολλάκις προενόησεν καὶ ἁμαρτόντι συνέγνω, καὶ νῦν αὐτὸ ῥύσασθαι τῆς κατηγγελμένης ἀπωλείας·"},{"number":230,"text":"οὐδὲ γὰρ ἁμαρτόν τι κινδυνεύειν ἀκλεῶς ἀποθανεῖν, ἀλλʼ αὐτὸν γὰρ εἶναι τὴν αἰτίαν τῆς Ἀμάνου ὀργῆς, ὅτι μὴ προσεκύνησα μηδʼ ἣν σοί, δέσποτα, φησίν, τιμὴν παρεῖχον, ταύτην ἐκείνῳ παρασχεῖν ὑπέμενον, ὀργισθεὶς ταῦτα κατὰ τῶν μὴ παραβαινόντων τοὺς σοὺς νόμους ἐμηχανήσατο."},{"number":231,"text":"τὰς δʼ αὐτὰς ἠφίει καὶ τὸ πλῆθος φωνάς, παρακαλοῦν προνοῆσαι τὸν θεὸν τῆς σωτηρίας αὐτῶν καὶ τοὺς ἐν ἁπάσῃ τῇ γῇ Ἰσραηλίτας ἐξελέσθαι τῆς μελλούσης συμφορᾶς· καὶ γὰρ πρὸ ὀφθαλμῶν αὐτὴν εἶχον ἤδη καὶ προσεδόκων. ἱκέτευε δὲ καὶ Ἐσθήρα τὸν θεὸν τῷ πατρίῳ νόμῳ ῥίψασα κατὰ τῆς γῆς ἑαυτὴν καὶ πενθικὴν ἐσθῆτα περιθεμένη,"},{"number":232,"text":"καὶ τροφῇ καὶ ποτῷ καὶ τοῖς ἡδέσιν ἀποταξαμένη τρισὶν ἡμέραις ᾔτει τὸν θεὸν ἐλεηθῆναι μὲν αὐτήν, δόξαι δʼ ὀφθεῖσαν τῷ βασιλεῖ πιθανὴν μὲν τοὺς λόγους παρακαλοῦσαν τὸ δὲ εἶδος εὐπρεπεστέραν τῆς τάχιον οὖσαν,"},{"number":233,"text":"ἵνʼ ἀμφοτέροις καὶ πρὸς τὴν παραίτησιν ὀργῆς, εἴ τι παροξυνθείη πρὸς αὐτὴν ὁ βασιλεύς, χρήσαιτο καὶ πρὸς τὴν συνηγορίαν τῶν ὁμοεθνῶν ἐν τοῖς ἐσχάτοις σαλευόντων, μῖσός τε γενέσθαι τῷ βασιλεῖ πρὸς τοὺς ἐχθροὺς τῶν Ἰουδαίων καὶ τὴν ἀπώλειαν αὐτοῖς τὴν μέλλουσαν, ἐὰν ὀλιγωρηθῶσιν ὑπʼ αὐτοῦ, κατασκευάσοντας."},{"number":234,"text":"Ταῦθʼ ἱκετεύουσα τὸν θεὸν ἐπὶ τρεῖς ἡμέρας ἀποδύεται μὲν τὴν ἐσθῆτα ἐκείνην καὶ τὸ σχῆμα μεταβάλλει, κοσμησαμένη δʼ ὡς ἐχρῆν τὴν βασίλισσαν σὺν δυσὶν θεραπαίναις, ὧν ἡ μὲν ἐπερειδομένην αὐτὴν κούφως ἔφερεν, ἡ δὲ ἑπομένη τὸ βαθὺ τοῦ ἐνδύματος καὶ μέχρι τῆς γῆς κεχυμένον ἄκροις ἀπῃώρει τοῖς δακτύλοις, ἥκει πρὸς τὸν βασιλέα, μεστὴ μὲν τὸ πρόσωπον ἐρυθήματος, προσηνὲς δὲ καὶ σεμνὸν ἐπικειμένη τὸ κάλλος."},{"number":235,"text":"εἰσῄει δὲ πρὸς αὐτὸν μετὰ δέους. ὡς δὲ κατὰ πρόσωπον αὐτοῦ καθεζομένου ἐπὶ τοῦ θρόνου γίνεται τὸν βασιλικὸν περικειμένου κόσμον, οὗτος δʼ ἦν ἐκ ποικίλης μὲν ἐσθῆτος,"},{"number":236,"text":"χρυσοῦ δὲ καὶ λίθου πολυτελοῦς, φοβερώτερον καὶ διʼ αὐτὰ μᾶλλον θεασαμένη καί τι κἀκείνου προσιδόντος αὐτὴν ἀπηνέστερον καὶ διακεκαυμένῳ ὑπὸ τῆς ὀργῆς τῷ προσώπῳ, πάρεσις αὐτὴν εὐθὺς λαμβάνει καὶ τοῖς παρὰ πλευρὸν οὖσιν ἀχανὴς ἐπέπεσεν."},{"number":237,"text":"ὁ δὲ βασιλεὺς κατὰ βούλησιν οἶμαι τοῦ θεοῦ τὴν διάνοιαν μετέβαλεν καὶ δείσας περὶ τῇ γυναικί, μὴ καὶ πάθῃ τι τῶν χειρόνων ὑπὸ τοῦ φόβου,"},{"number":238,"text":"ἀνεπήδησεν ἐκ τοῦ θρόνου, καὶ ταῖς ἀγκάλαις αὐτὴν ὑπολαβὼν ἀνεκτᾶτο κατασπαζόμενός τε καὶ προσομιλῶν ἡδέως καὶ θαρρεῖν παρακαλῶν καὶ μηδὲν ὑποπτεύειν σκυθρωπόν, ὅτι πρὸς αὐτὸν ἄκλητος ἔλθοι· τὸν γὰρ νόμον τοῦτον πρὸς τοὺς ὑπηκόους κεῖσθαι, τὴν δὲ ὁμοίως αὐτῷ βασιλεύουσαν πᾶσαν ἔχειν ἄδειαν."},{"number":239,"text":"ταῦτα λέγων τὸ σκῆπτρον αὐτῆς ἐνετίθει τῇ χειρὶ καὶ τὴν ῥάβδον ἐξέτεινεν ἐπὶ τὸν αὐχένα αὐτῆς διὰ τὸν νόμον εὐλαβείας αὐτὴν ἀπολύων."},{"number":240,"text":"ἡ δʼ ὑπὸ τούτων ἀναζωπυρήσασα, δέσποτʼ, εἶπεν, οὐκ ἔχω σοι τὸ αἰφνίδιον τοῦ συμβεβηκότος μοι ῥᾳδίως εἰπεῖν· ὡς γὰρ εἶδόν σε μέγαν καὶ καλὸν καὶ φοβερόν, εὐθὺς ὑπεχώρει μου τὸ πνεῦμα καὶ κατελειπόμην ὑπὸ τῆς ψυχῆς."},{"number":241,"text":"μόλις δʼ αὐτῆς καὶ ταῦτα φθεγγομένης καὶ μετὰ ἀσθενείας αὐτόν τε ἀγωνία καὶ ταραχὴ κατελάμβανεν καὶ τὴν Ἐσθῆρʼ εὐψυχεῖν καὶ τὰ κρείττω προσδοκᾶν παρεθάρρυνεν, ὡς αὐτοῦ καὶ τὰ ἡμίση τῆς βασιλείας, εἰ δέοιτο τούτων, παραχωρήσοντος αὐτῇ."},{"number":242,"text":"ἡ δὲ Ἐσθήρα ἐφʼ ἑστίασιν αὐτὸν μετὰ Ἀμάνου τοῦ φίλου πρὸς αὐτὴν ἐλθεῖν ἠξίωσεν· παρεσκευακέναι γὰρ αὐτὴν δεῖπνον ἔλεγεν. ὡς δʼ ἐπένευσεν καὶ παρῆσαν, μεταξὺ πίνων τὴν Ἐσθῆρα ἐκέλευσε δηλοῦν αὐτῷ, τί βούλεται·"},{"number":243,"text":"μηδενὸς γὰρ ἀτυχήσειν, μηδʼ ἂν τὸ μέρος τῆς βασιλείας ἐθελήσῃ λαβεῖν. ἡ δὲ εἰς τὴν ἐπιοῦσαν ἀνεβάλλετο φράζειν αὐτῷ τὴν αὐτῆς βούλησιν, εἰ πάλιν ἔλθοι πρὸς αὐτὴν μετὰ Ἀμάνου ἐφʼ ἑστίασιν."},{"number":244,"text":"Τοῦ δὲ βασιλέως ὑποσχομένου ὁ Ἀμάνης ἐξῆλθεν περιχαρὴς ἐπὶ τῷ μόνον ἠξιῶσθαι συνδειπνεῖν τῷ βασιλεῖ παρὰ τῇ Ἐσθήρᾳ, καὶ ὅτι μηδεὶς τοσαύτης ἄλλος τυγχάνει παρὰ τοῖς βασιλεῦσι τιμῆς. ἰδὼν δʼ ἐν τῇ αὐλῇ Μαρδοχαῖον ὑπερηγανάκτησεν· οὐδὲν γὰρ αὐτῷ παρʼ αὐτοῦ θεασαμένου πρὸς τιμὴν ἐγένετο."},{"number":245,"text":"καὶ παρελθὼν πρὸς αὑτὸν τὴν γυναῖκα Γάζασαν ἐκάλεσεν καὶ τοὺς φίλους. ὧν παρόντων διηγεῖτο τὴν τιμήν, ἧς οὐ παρὰ τοῦ βασιλέως ἀπολαύοι μόνον, ἀλλὰ καὶ παρὰ τῆς βασιλίσσης· καὶ γὰρ τήμερον ὡς δειπνήσειεν παρʼ αὐτῇ μόνος σὺν τῷ βασιλεῖ, κληθείη πάλιν εἰς τὴν ἐπιοῦσαν."},{"number":246,"text":"ἔλεγέν τε μὴ ἀρέσκεσθαι Μαρδοχαῖον ὁρῶντα ἐν τῇ αὐλῇ τὸν Ἰουδαῖον. τῆς δὲ γυναικὸς αὐτοῦ Γαζάσης εἰπούσης κελεῦσαι ξύλον κοπῆναι πηχῶν ἑξήκοντα καὶ πρωὶ παρὰ τοῦ βασιλέως αἰτησάμενον ἀνασταυρῶσαι τὸν Μαρδοχαῖον, ἐπαινέσας τὴν γνώμην προσέταξεν τοῖς οἰκέταις ξύλον ἑτοιμασαμένους στῆσαι τοῦτο ἐν τῇ αὐλῇ πρὸς τιμωρίαν Μαρδοχαίῳ."},{"number":247,"text":"καὶ τοῦτο μὲν ἦν ἕτοιμον· ὁ δὲ θεὸς κατεγέλα τῆς Ἀμάνου πονηρᾶς ἐλπίδος καὶ τὸ συμβησόμενον εἰδὼς ἐτέρπετο τῷ γενησομένῳ· τοῦ γὰρ βασιλέως διὰ νυκτὸς ἐκείνης ἀφαιρεῖται τὸν ὕπνον."},{"number":248,"text":"ὁ δʼ οὐ βουλόμενος ἀργῶς ἀπολέσαι τὴν ἀγρυπνίαν, ἀλλʼ εἴς τι τῶν τῇ βασιλείᾳ διαφερόντων αὐτὴν ἀναλῶσαι, τὸν γραμματέα κομίσαντα καὶ τῶν πρὸ αὐτοῦ βασιλέων τὰ ὑπομνήματα καὶ τῶν ἰδίων πράξεων ἀναγινώσκειν αὐτῷ προσέταξεν."},{"number":249,"text":"κομίσαντος δὲ καὶ ἀναγινώσκοντος εὑρέθη τις διʼ ἀριστείαν ἔν τινι γέρας εἰληφὼς χώραν, ἧς καὶ τὸ ὄνομα ἐγέγραπτο. ἕτερον δὲ διὰ πίστιν τετυχηκότα δωρεᾶς μηνύων ἦλθεν καὶ ἐπὶ Γαβαταῖον καὶ Θεοδέστην τοὺς ἐπιβουλεύσαντας εὐνούχους τῷ βασιλεῖ, ὧν μηνυτὴς Μαρδοχαῖος ἦν γεγενημένος."},{"number":250,"text":"φράσαντος δὲ τοῦτο μόνον τοῦ γραμματέως καὶ μεταβαίνοντος εἰς ἑτέραν πρᾶξιν ἐπέσχεν ὁ βασιλεὺς πυνθανόμενος, εἰ μὴ ἔχει γέρας αὐτῷ δοθὲν ἀναγεγραμμένον. ὁ δʼ ὡς ἔφη μηδὲν εἶναι, κελεύσας ἡσυχάζειν, τίς ἡ τῆς νυκτὸς ὥρα, παρὰ τῶν ἐπὶ τούτῳ τεταγμένων ἐπυνθάνετο."},{"number":251,"text":"μαθὼν δʼ, ὡς ὄρθρος ἐστὶν ἤδη, προσέταξεν τῶν φίλων ὃν ἂν πρὸ τῆς αὐλῆς εὕρωσιν ἤδη παρόντα τοῦτον αὐτῷ δηλοῦν. ἔτυχέν τε ὥστε Ἀμάνην εὑρεθῆναι· θᾶττον γὰρ τῆς συνήθους ὥρας ἐληλύθει περὶ τοῦ Μαρδοχαίου θανάτου δεησόμενος αὐτοῦ."},{"number":252,"text":"τῶν οὖν θεραπόντων εἰπόντων, ὅτι Ἀμάνης εἴη πρὸ τῆς αὐλῆς, ἐκέλευσεν αὐτὸν εἰσκαλέσαι. εἰσελθόντος δέ φίλον, εἶπεν, εἰδὼς ἐμαυτῷ σὲ μόνον εὔνουν συμβουλεῦσαί μοι παρακαλῶ, πῶς ἂν τιμήσαιμι τινὰ στεργόμενον ὑπʼ ἐμοῦ σφόδρα τῆς ἐμαυτοῦ μεγαλοφροσύνης ἀξίως."},{"number":253,"text":"ὁ δὲ Ἀμάνης λογισάμενος, ἣν ἂν δῷ γνώμην ταύτην δώσειν ὑπὲρ αὐτοῦ, φιλεῖσθαι γὰρ ἑαυτὸν ὑπὸ τοῦ βασιλέως μόνον, ἣν ᾤετο ἀρίστην εἶναι ταύτην φανερὰν ἐποίησεν."},{"number":254,"text":"εἶπεν γάρ εἰ βούλοιο τὸν ἄνθρωπον ὃν φῂς ἀγαπᾶν δόξῃ περιβαλεῖν, ποίησον ἐφʼ ἵππου βαδίζειν τὴν αὐτὴν ἐσθῆτά σοι φοροῦντα καὶ περιαυχένιον χρυσοῦν ἔχοντα καὶ προάγοντα τῶν ἀναγκαίων φίλων ἕνα κηρύσσειν διʼ ὅλης τῆς πόλεως, ὅτι ταύτης τυγχάνει τῆς τιμῆς ὃν ἂν ὁ βασιλεὺς τιμήσῃ."},{"number":255,"text":"ὁ μὲν οὖν Ἀμάνης ταῦτα συνεβούλευσεν οἰόμενος εἰς αὐτὸν ἥξειν τοῦτο τὸ γέρας. ὁ δὲ βασιλεὺς ἡσθεὶς τῇ παραινέσει προελθών. φησίν, ἔχεις γὰρ καὶ τὸν ἵππον καὶ τὴν στολὴν καὶ τὸν στρεπτόν. ἐπιζήτησον Μαρδοχαῖον τὸν Ἰουδαῖον καὶ ταῦτα ἐκείνῳ δοὺς προάγων αὐτοῦ τὸν ἵππον, σὺ γάρ, ἔφη, μοι φίλος ἀναγκαῖος, ἴσθι διάκονος ὧν χρηστὸς σύμβουλος ἐγένου. ταῦτα δὲ αὐτῷ παρʼ ἡμῶν ἔσται σώσαντί μου τὴν ψυχήν."},{"number":256,"text":"τούτων ἀκούσας παρὰ πᾶσαν ἐλπίδα τὴν διάνοιαν συνεχύθη καὶ πληγεὶς ὑπὸ ἀμηχανίας ἔξεισιν ἄγων τὸν ἵππον καὶ τὴν πορφύραν καὶ τὸ χρυσοῦν περιαυχένιον, καὶ τὸν Μαρδοχαῖον εὑρὼν πρὸ τῆς αὐλῆς σάκκον ἐνδεδυμένον ἐκέλευσεν ἀποθέμενον ἐνδύσασθαι τὴν πορφύραν."},{"number":257,"text":"ὁ δὲ οὐκ εἰδὼς τἀληθές, ἀλλὰ χλευάζεσθαι νομίζων ὦ κάκιστε πάντων ἀνθρώπων, εἶπεν, οὕτως ἡμῶν ταῖς συμφοραῖς ἐπεγγελᾷς; πεισθεὶς δʼ, ὡς ὁ βασιλεὺς αὐτῷ γέρας τοῦτʼ εἴη δεδωκὼς ἀντὶ τῆς σωτηρίας, ἣν αὐτῷ παρέσχεν τοὺς ἐπιβουλεύσαντας εὐνούχους ἐλέγξας, ἐνδύεται τὴν πορφύραν, ἣν ὁ βασιλεὺς φορῶν ἀεὶ διετέλει, καὶ περιτίθεται τὸ περιαυχένιον,"},{"number":258,"text":"καὶ ἐπιβὰς ἐπὶ τὸν ἵππον ἐν κύκλῳ περιῄει τὴν πόλιν Ἀμάνου προάγοντος καὶ κηρύσσοντος, ὅτι τοῦτʼ ἔσται παρὰ τοῦ βασιλέως ᾧ ἂν στέρξῃ καὶ τιμῆς ἄξιον δοκιμάσῃ."},{"number":259,"text":"ἐπεὶ δʼ ἐκπεριῆλθον τὴν πόλιν, ὁ μὲν Μαρδοχαῖος εἰσῄει πρὸς τὸν βασιλέα, Ἀμάνης δʼ ὑπʼ αἰσχύνης πρὸς αὑτὸν παραγίνεται καὶ μετὰ δακρύων τῇ γυναικὶ καὶ τοῖς. φίλοις τὰ συμβεβηκότα διηγεῖτο. οἱ δʼ οὐκέτʼ ἀμύνασθαι τὸν Μαρδοχαῖον ἔλεγον δυνήσεσθαι· τὸν γὰρ θεὸν εἶναι σὺν αὐτῷ."},{"number":260,"text":"Ταῦτα δὲ τούτων ἔτι πρὸς ἀλλήλους ὁμιλούντων ἧκον οἱ τῆς Ἐσθήρας εὐνοῦχοι τὸν Ἀμάνην ἐπὶ τὸ δεῖπνον ἐπισπεύδοντες."},{"number":261,"text":"Σαβουχάδας δὲ τῶν εὐνούχων εἷς ἰδὼν τὸν σταυρὸν ἐν τῇ Ἀμάνου οἰκίᾳ πεπηγότα, ὃν ἐπὶ Μαρδοχαῖον παρεσκευάκεισαν, καὶ πυθόμενος παρά τινος τῶν οἰκετῶν, ἐπὶ τίνα τοῦτον ἦσαν ἑτοιμασάμενοι, γνούς, ὡς ἐπὶ τὸν τῆς βασιλίσσης θεῖον, τὸν γὰρ Ἀμάνην μέλλειν αὐτὸν αἰτεῖσθαι παρὰ τοῦ βασιλέως πρὸς τιμωρίαν, τότε μὲν ἡσυχίαν ἦγεν."},{"number":262,"text":"ὡς δὲ ὁ βασιλεὺς μετὰ τοῦ Ἀμάνου εὐωχηθεὶς ἠξίου τὴν βασίλισσαν λέγειν αὐτῷ, τίνος βούλεται δωρεᾶς τυχεῖν, ὡς ληψομένην οὗπερ ἂν ἐπιθυμίαν ἔχῃ, τὸν τοῦ λαοῦ κίνδυνον ἀπωδύρετο καὶ πρὸς ἀπώλειαν ἔλεγεν μετὰ τοῦ ἔθνους ἐκδεδόσθαι, διὸ καὶ ποιεῖσθαι περὶ τούτων τοὺς λόγους·"},{"number":263,"text":"οὐ γὰρ ἂν ἠνωχληκέναι αὐτῷ, εἰ πρὸς δουλείαν πικρὰν ἐκέλευσεν αὐτοὺς ἀπεμποληθῆναι· μέτριον γὰρ τοῦτο τὸ κακόν· παρεκάλει τε τούτων ἀπαλλαγῆναι."},{"number":264,"text":"ἐρωτήσαντος δὲ τοῦ βασιλέως, ὑπὸ τίνος εἴη ταῦτα γεγενημένα, κατηγόρει τὸ λοιπὸν ἤδη φανερῶς τοῦ Ἀμάνου καὶ τοῦτον ὄντα πονηρὸν ἐπʼ αὐτοὺς κατεσκευακέναι τὴν ἐπιβουλὴν ἤλεγχεν."},{"number":265,"text":"ταραχθέντος δὲ πρὸς τοῦτο τοῦ βασιλέως καὶ ἀναπηδήσαντος εἰς τοὺς κήπους ἐκ τοῦ συμποσίου, τῆς Ἐσθήρας ὁ Ἀμάνης ἤρξατο δεῖσθαι καὶ παρακαλεῖν συγγνῶναι τῶν ἡμαρτημένων· συνῆκε γὰρ αὐτὸς ἐν κακοῖς ὤν· ἐπί τε τῆς κλίνης αὐτοῦ πεσόντος καὶ τὴν βασίλισσαν παρακαλοῦντος ἐπεισελθὼν ὁ βασιλεὺς καὶ πρὸς τὴν ὄψιν μᾶλλον παροξυνθεὶς εἶπεν, ὦ κάκιστε πάντων, καὶ βιάζεσθαί μου τὴν γυναῖκα ἐπιχειρεῖς;"},{"number":266,"text":"Ἀμάνου δὲ πρὸς τοῦτο καταπλαγέντος καὶ μηδὲν ἔτι φθέγξασθαι δυνηθέντος, καὶ Σαβουζάνης ὁ εὐνοῦχος παρελθὼν κατηγόρει τοῦ Ἀμάνου, ὡς εὕροι σταυρὸν ἐπὶ τῆς οἰκίας αὐτοῦ παρεσκευασμένον ἐπὶ Μαρδοχαῖον τοῦτο γὰρ αὐτῷ πυνθανομένῳ τὸν οἰκέτην εἰπεῖν, ὅτε καλέσων αὐτὸν ἐπὶ τὸ δεῖπνον ἔλθοι πρὸς αὐτόν. εἶναι δὲ τὸν σταυρὸν ἔλεγεν ἑξήκοντα πήχεων τὸ ὕψος."},{"number":267,"text":"ὁ δὲ βασιλεὺς ἀκούσας οὐκ ἄλλῃ τιμωρίᾳ περιβάλλειν ἔκρινεν τὸν Ἀμάνην ἢ τῇ κατὰ Μαρδοχαίου νενοημένῃ, καὶ κελεύει παραχρῆμα αὐτὸν ἐξ ἐκείνου τοῦ σταυροῦ κρεμασθέντα ἀποθανεῖν."},{"number":268,"text":"ὅθεν ἐπέρχεταί μοι τὸ θεῖον θαυμάζειν καὶ τὴν σοφίαν αὐτοῦ καὶ δικαιοσύνην καταμανθάνειν, μὴ μόνον τὴν Ἀμάνου κολάσαντος πονηρίαν, ἀλλὰ καὶ τὴν κατʼ ἄλλου μεμηχανημένην τιμωρίαν ταύτην ἐκείνου ποιήσαντος εἶναι καὶ τοῖς ἄλλοις μαθεῖν οὕτως γνῶναι παρεσχηκότος, ὡς ἃ καθʼ ἑτέρου τις παρεσκεύασε ταῦτα λανθάνει καθʼ ἑαυτοῦ πρῶτον ἑτοιμασάμενος."},{"number":269,"text":"Ἀμάνης μὲν οὖν ἀμετρήτως τῇ παρὰ τοῦ βασιλέως χρώμενος τιμῇ τοῦτον διεφθάρη τὸν τρόπον, τὴν δὲ οὐσίαν αὐτοῦ ἐχαρίσατο τῇ βασιλίσσῃ. Μαρδοχαῖον δὲ προσκαλεσάμενος, καὶ γὰρ ἐδήλωσεν αὐτῷ τὴν πρὸς αὐτὸν συγγένειαν Ἐσθήρα, ὃν ἔδωκεν Ἀμάνῃ δακτύλιον τοῦτον Μαρδοχαίῳ δίδωσι."},{"number":270,"text":"δωρεῖται δὲ καὶ ἡ βασίλισσα Μαρδοχαίῳ τὴν Ἀμάνου κτῆσιν καὶ δεῖται τοῦ βασιλέως ἀπαλλάξαι τοῦ περὶ τῆς ζωῆς φόβου τὸ τῶν Ἰουδαίων ἔθνος, δηλοῦσα τὰ γραφέντα κατὰ πᾶσαν τὴν χώραν ὑπὸ Ἀμάνου τοῦ Ἀμαδάθου· τῆς γὰρ πατρίδος αὐτῇ διαφθαρείσης καὶ τῶν ὁμοφύλων ἀπολομένων οὐκ ἂν ὑπομένειν τὸν βίον."},{"number":271,"text":"ὁ δὲ βασιλεὺς ὑπέσχετο μηδὲν ἄχαρι αὐτὴν μηδʼ οἷς ἐσπούδακεν ἐναντίον ἔσεσθαι, γράφειν δὲ ἃ βούλεται προσέταξε περὶ τῶν Ἰουδαίων ἐκείνην ἐκ τοῦ βασιλέως ὀνόματος καὶ σημηναμένην αὐτοῦ τῇ σφραγῖδι πέμπειν εἰς πᾶσαν τὴν βασιλείαν· τοὺς γὰρ ἀναγνωσομένους τὰς ὑπὸ τοῦ βασιλικοῦ σημαντῆρος ἠσφαλισμένας ἐπιστολὰς οὐδὲν περὶ τῶν ἐγγεγραμμένων ἐναντιώσεσθαι."},{"number":272,"text":"μεταπεμφθέντας οὖν τοὺς βασιλικοὺς γραμματεῖς ἐκέλευσε γράφειν τοῖς ἔθνεσι περὶ τῶν Ἰουδαίων τοῖς τε οἰκονόμοις καὶ ἄρχουσιν ἀπὸ Ἰνδικῆς ἕως τῆς Αἰθιοπίας ἑκατὸν εἰκοσιεπτὰ σατραπειῶν ἡγουμένοις. τὰ δὲ γραφέντα τοῦτον ἔχει τὸν τρόπον·"},{"number":273,"text":"βασιλεὺς μέγας Ἀρταξέρξης τοῖς ἄρχουσι καὶ τὰ ἡμέτερα φρονοῦσι χαίρειν. πολλοὶ διὰ μέγεθος εὐεργεσίας καὶ τιμῆς, ἣν διʼ ὑπερβολὴν χρηστότητος τῶν παρεχόντων ἐκαρποῦντο, οὐκ εἰς τοὺς ὑποδεεστέρους μόνον ἐξυβρίζουσιν,"},{"number":274,"text":"ἀλλʼ οὐδʼ αὐτοὺς ἀδικεῖν ὤκνησαν τοὺς εὐεργετοῦντας τὸ εὐχάριστον ἐξ ἀνθρώπων ἀναιροῦντες, καὶ διʼ ἀπειροκαλίαν τῶν οὐκ ἐξ ὧν προσεδόκησαν ἀγαθῶν κόρον εἰς τοὺς αἰτίους ἀφέντες λήσεσθαι τὸ θεῖον ἐπὶ τούτοις νομίζουσι καὶ τὴν ἐξ αὐτοῦ διαφεύξεσθαι δίκην."},{"number":275,"text":"ἔνιοι δὲ ἐκ τούτων προστασίαν πραγμάτων ἐπιτραπέντες παρὰ τῶν φίλων καὶ μῖσος ἴδιον ἔχοντες πρός τινας, παραλογισάμενοι τοὺς κρατοῦντας ψευδέσιν αἰτίαις καὶ διαβολαῖς ἔπεισαν κατὰ μηδὲν ἀδικούντων ὀργὴν ἀναλαβεῖν, ὑφʼ ἧς ἐκινδύνευσαν ἀπολέσθαι."},{"number":276,"text":"τοῦτο δὲ οὐκ ἐκ τῶν ἀρχαιοτέρων οὐδʼ ἀκοῇ γνωρίμων ἡμῖν οὕτως ἰδεῖν ἔστιν ἔχον, ἀλλʼ ἐκ τῶν παρὰ τὰς ἡμετέρας ὄψεις τετολμημένων, ὡς διαβολαῖς μὲν καὶ κατηγορίαις μὴ προσέχειν ἔτι τοῦ λοιποῦ μηδʼ οἷς ἕτεροι πείθειν ἐπιχειροῦσιν, κρίνειν δʼ ὅσα τις αὐτὸς οἶδεν πεπραγμένα, καὶ κολάζειν μὲν ἂν ᾖ τοιαῦτα, χαρίζεσθαι δʼ ἂν ἑτέρως ἔχῃ, τοῖς ἔργοις αὐτοῖς ἀλλὰ μὴ τοῖς λέγουσι προστιθέμενον."},{"number":277,"text":"ὡς μὲν Ἀμάνης, Ἀμαδάθου μὲν παῖς Ἀμαληκίτης δὲ τὸ γένος, ἀλλότριος ὢν τοῦ Περσῶν αἵματος, ἐπιξενωθεὶς ἡμῖν ἀπέλαυσεν τῆς πρὸς ἅπαντας χρηστότητος ἐπὶ τοσοῦτον, ὡς πατέρα μου τὸ λοιπὸν προσαγορεύεσθαι καὶ προσκυνούμενον διατελεῖν καὶ μεθʼ ἡμᾶς τὰ δεύτερα τῆς βασιλικῆς παρὰ πάντων τιμῆς ἀποφέρεσθαι, τὴν εὐτυχίαν οὐκ ἤνεγκεν οὐδὲ σώφρονι λογισμῷ τὸ μέγεθος τῶν ἀγαθῶν ἐταμίευσεν,"},{"number":278,"text":"ἀλλὰ τῆς βασιλείας ἐπεβούλευσέ με καὶ τῆς ψυχῆς τὸν αἴτιον αὐτῷ τῆς ἐξουσίας ἀφελέσθαι, τὸν εὐεργέτην μου καὶ σωτῆρα Μαρδοχαῖον καὶ τὴν κοινωνὸν ἡμῖν τοῦ τε βίου καὶ τῆς ἀρχῆς Ἐσθῆρα κακούργως καὶ μετὰ ἀπάτης πρὸς ἀπώλειαν αἰτησάμενος· τούτῳ γάρ με τῷ τρόπῳ τῶν εὐνοούντων ἐρημώσας ἐβούλετο τὴν ἀρχὴν εἰς ἄλλους μεταβαλεῖν."},{"number":279,"text":"ἐγὼ δὲ τοὺς ὑπὸ τοῦ ἀλιτηρίου πρὸς ἀπώλειαν ἐκδοθέντας Ἰουδαίους οὐ πονηροὺς κατανοήσας, ἀλλὰ τὸν ἄριστον πολιτευομένους τρόπον καὶ τῷ θεῷ προσανέχοντας, ὃς ἐμοί τε καὶ τοῖς προγόνοις ἡμῶν τὴν βασιλείαν διεφύλαξεν, οὐ μόνον ἀπολύω τῆς ἐκ τῶν προαπεσταλμένων τιμωρίας, οἷς ποιήσετε καλῶς μὴ προσέχοντες,"},{"number":280,"text":"ἀλλὰ καὶ τιμῆς αὐτοὺς ἁπάσης τυγχάνειν βούλομαι, καὶ τὸν ταῦτα κατʼ αὐτῶν μηχανησάμενον πρὸ τῶν πυλῶν τῶν ἐν Σούσοις ἀνεσταύρωσα μετὰ τῆς γενεᾶς, τοῦ πάντα ἐφορῶντος θεοῦ ταύτην αὐτῷ τὴν δίκην ἐπιβαλόντος."},{"number":281,"text":"κελεύω δὲ ὑμᾶς τὸ ἀντίγραφον τῆς ἐπιστολῆς ἐκθέντας εἰς ἅπασαν τὴν βασιλείαν τοὺς Ἰουδαίους ἀφεῖναι τοῖς ἰδίοις νόμοις χρωμένους ζῆν μετʼ εἰρήνης καὶ βοηθεῖν αὐτοῖς, ὅπως τοὺς ἐν οἷς ἠτύχησαν καιροῖς ἀδικήσαντας αὐτοὺς ἀμύνωνται, τῇ τρισκαιδεκάτῃ τοῦ δωδεκάτου μηνός, ὅς ἐστιν Ἄδαρ, τῇ αὐτῇ ἡμέρᾳ·"},{"number":282,"text":"ταύτην γὰρ αὐτοῖς ὁ θεὸς ἀντὶ ὀλεθρίας σωτήριον πεποίηκεν. ἔστι δʼ ἀγαθὴ τοῖς εὐνοοῦσιν ἡμῖν ὑπόμνησις δὲ τῆς τῶν ἐπιβουλευσάντων κολάσεως."},{"number":283,"text":"εἰδέναι μέντοι γε βούλομαι καὶ πόλιν καὶ πᾶν ἔθνος, ἐὰν τῶν γεγραμμένων τινὸς παρακούσῃ, ὅτι καὶ πυρὶ καὶ σιδήρῳ δαπανηθήσεται. τὰ μέντοι γεγραμμένα προτεθήτω καθʼ ὅλης τῆς ἡμῖν ὑπηκόου χώρας, καὶ παρασκευαζέσθωσαν πάντως εἰς τὴν προγεγραμμένην ἡμέραν, ἵνα τοὺς ἐχθροὺς μετέλθωσιν."},{"number":284,"text":"Οἱ μὲν οὖν ἱππεῖς οἱ τὰς ἐπιστολὰς διακομίζοντες εὐθὺς ἐξορμήσαντες τὴν προκειμένην ὁδὸν ἤνυον. ὁ δὲ Μαρδοχαῖος ὡς ἀναλαβὼν τὴν βασιλικὴν στολὴν καὶ τὸν στέφανον τὸν χρυσοῦν καὶ τὸν στρεπτὸν περιθέμενος προῆλθεν, ἰδόντες αὐτὸν οὕτως τετιμημένον ὑπὸ τοῦ βασιλέως οἱ ἐν Σούσοις ὄντες Ἰουδαῖοι κοινὴν ὑπέλαβον τὴν εὐπραγίαν αὐτοῦ."},{"number":285,"text":"χαρὰ δὲ καὶ σωτήριον φέγγος ἐκτιθεμένων τῶν τοῦ βασιλέως γραμμάτων καὶ τοὺς κατὰ πόλιν τῶν Ἰουδαίων καὶ τοὺς κατὰ χώραν ἐπεῖχεν, ὡς πολλὰ καὶ τῶν ἄλλων ἐθνῶν διὰ τὸν ἐκ τῶν Ἰουδαίων φόβον περιτεμνόμενα τὴν αἰδῶ τὸ ἀκίνδυνον αὐτοῖς ἐκ τούτου πραγματεύσασθαι."},{"number":286,"text":"καὶ γὰρ τοῦ δωδεκάτου μηνὸς τῇ τρισκαιδεκάτῃ, ὃς κατὰ μὲν Ἑβραίους Ἄδαρ καλεῖται κατὰ δὲ Μακεδόνας Δύστρος, οἱ κομίσαντες τὰ τοῦ βασιλέως γράμματα ἐδήλουν, ὅπως καθʼ ἣν ἡμέραν αὐτοὶ κινδυνεύσειν ἤμελλον ἐν ταύτῃ τοὺς ἐχθροὺς ἀπολέσωσιν."},{"number":287,"text":"οἱ δὲ ἄρχοντες τῶν σατραπειῶν καὶ οἱ τύραννοι καὶ οἱ βασιλεῖς καὶ οἱ γραμματεῖς εἶχον ἐν τιμῇ τοὺς Ἰουδαίους· ὁ γὰρ ἐκ Μαρδοχαίου φόβος ἠνάγκαζεν αὐτοὺς σωφρονεῖν."},{"number":288,"text":"τοῦ δὲ γράμματος τοῦ βασιλικοῦ διὰ πάσης τῆς ὑπʼ αὐτὸν χώρας γενομένου συνέπεσεν ὥστε καὶ τοὺς ἐν Σούσοις Ἰουδαίους ἀποκτεῖναι τῶν ἐχθρῶν περὶ πεντακοσίους."},{"number":289,"text":"τοῦ δὲ βασιλέως τῶν ἀπολωλότων δηλώσαντος τὸν ἀριθμὸν Ἐσθήρᾳ καὶ περὶ τῶν ἐπὶ τῆς χώρας τί ποτʼ εἴη γεγονὸς διαποροῦντος καὶ τί πρὸς τούτοις ἔτʼ αὐτοῦ γενέσθαι βούλεται πυνθανομένου, πραχθήσεσθαι γάρ, παρεκάλεσεν ἐπιτραπῆναι τοῖς Ἰουδαίοις καὶ τὴν ἐπιοῦσαν ἡμέραν οὕτως χρήσασθαι τοῖς ὑπολειπομένοις τῶν ἐχθρῶν καὶ τοὺς δέκα τοὺς Ἀμάνου παῖδας ἀνασταυρῶσαι."},{"number":290,"text":"καὶ τοῦτο μὲν προσέταξε τοῖς Ἰουδαίοις ὁ βασιλεὺς μηδὲν ἀντιλέγειν Ἐσθῆρι δυνάμενος· οἱ δὲ πάλιν συστραφέντες τῇ τετράδι καὶ δεκάτῃ τοῦ Δύστρου μηνὸς ἀπέκτειναν τῶν ἐναντίων ὡς τριακοσίους, καὶ οὐδενὸς τῶν ἐκείνοις ὑπαρχόντων ἥψαντο κτημάτων."},{"number":291,"text":"ἀπέθανον δὲ καὶ ὑπὸ τῶν ἐν τῇ χώρᾳ καὶ ταῖς ἄλλαις πόλεσιν Ἰουδαίων τῶν ἐχθρῶν αὐτοῖς ἑπτακισμύριοι καὶ πεντακισχίλιοι. καὶ τούτους μὲν ἀπέκτειναν τῇ τρισκαιδεκάτῃ τοῦ μηνός, τὴν δὲ ἐχομένην ἑορτάσιμον ἐποίησαν."},{"number":292,"text":"ὁμοίως δὲ καὶ οἱ ἐν Σούσοις Ἰουδαῖοι τὴν τετράδα καὶ δεκάτην καὶ τὴν ἐχομένην τοῦ αὐτοῦ μηνὸς συναθροισθέντες εὐωχήθησαν. ὅθεν καὶ νῦν οἱ ἐν τῇ οἰκουμένῃ Ἰουδαῖοι πάντες τὰς ἡμέρας ταύτας ἑορτάζουσιν διαπεμπόμενοι μερίδας ἀλλήλοις."},{"number":293,"text":"ἔγραψεν δὲ Μαρδοχαῖος τοῖς ἐν τῇ Ἀρταξέρξου βασιλείᾳ ζῶσιν Ἰουδαίοις ταύτας παραφυλάσσειν τὰς ἡμέρας καὶ ἑορτὴν ἄγειν αὐτὰς καὶ τοῖς ἐκγόνοις παραδοῦναι τοῦ πρὸς πάντα διαμεῖναι τὸν χρόνον τὴν ἑορτὴν ἕνεκα καὶ μὴ λήθῃ παραπολέσθαι·"},{"number":294,"text":"μελλήσαντας γὰρ αὐτοὺς ἐν ταύταις διαφθείρεσθαι ταῖς ἡμέραις ὑπὸ Ἀμάνου δίκαια ποιήσειν, εἰ διαφυγόντες μὲν ἐν αὐταῖς τὸν κίνδυνον τοὺς δʼ ἐχθροὺς τιμωρησάμενοι παρατηρήσουσιν αὐτὰς εὐχαριστοῦντες τῷ θεῷ."},{"number":295,"text":"διὰ ταῦτα μὲν οἱ Ἰουδαῖοι τὰς προειρημένας ἡμέρας ἑορτάζουσιν προσαγορεύσαντες αὐτὰς φρουρέας. ὁ δὲ Μαρδοχαῖος μέγας τε ἦν καὶ λαμπρὸς παρὰ τῷ βασιλεῖ καὶ συνδιεῖπεν αὐτῷ τὴν ἀρχὴν ἀπολαύων ἅμα καὶ τῆς κοινωνίας τοῦ βίου τῇ βασιλίσσῃ."},{"number":296,"text":"ἦν δὲ καὶ τοῖς Ἰουδαίοις τὰ πράγματα διʼ αὐτοὺς ἀμείνω πάσης ἐλπίδος. καὶ τὰ μὲν τούτοις βασιλεύοντος Ἀρταξέρξου συμβάντα τοῦτον εἶχεν τὸν τρόπον."}],"7":[{"number":297,"text":"Ἀποθανόντος δὲ τοῦ ἀρχιερέως Ἐλεασίβου τὴν ἀρχιερωσύνην Ἰώδας ὁ παῖς αὐτοῦ διεδέξατο. τελευτήσαντος δὲ καὶ τούτου τὴν τιμὴν Ἰωάννης υἱὸς ὢν αὐτοῦ παρέλαβεν, διʼ ὃν καὶ Βαγώσης ὁ στρατηγὸς τοῦ ἄλλου Ἀρταξέρξου τὸν ναὸν ἐμίανεν καὶ φόρους ἐπέταξε τοῖς Ἰουδαίοις, πρὶν τὰς καθημερινὰς ἐπιφέρειν θυσίας ὑπὲρ ἀρνὸς ἑκάστου τελεῖν αὐτοὺς δημοσίᾳ δραχμὰς πεντήκοντα."},{"number":298,"text":"τούτου δὲ τὴν αἰτίαν τοιαύτην συνέβη γενέσθαι· ἀδελφὸς ἦν τῷ Ἰωάννῃ Ἰησοῦς· τούτῳ φίλῳ τυγχάνοντι ὁ Βαγώσης ὑπέσχετο τὴν ἀρχιερωσύνην παρέξειν."},{"number":299,"text":"ἀπὸ ταύτης οὖν τῆς πεποιθήσεως Ἰησοῦς ἐν τῷ ναῷ διενεχθεὶς τῷ Ἰωάννῃ παρώξυνεν τὸν ἀδελφὸν ὥστʼ αὐτὸν ἀνελεῖν καὶ διὰ τὴν ὀργὴν τηλικοῦτο ἀσέβημα δρᾶσαι κατʼ ἀδελφοῦ τὸν Ἰωάννην ἐν τῷ ἱερῷ ὡς δεινὸν ἦν καὶ πρότερον, ὡς μήτε παρʼ Ἕλλησιν μήτε παρὰ βαρβάροις ὠμὸν οὕτως καὶ ἀσεβὲς ἔργον γεγονέναι."},{"number":300,"text":"τὸ μέντοι θεῖον οὐκ ἠμέλησεν, ἀλλὰ καὶ ὁ λαὸς διʼ αὐτὴν τὴν αἰτίαν ἐδουλώθη καὶ ὁ ναὸς ἐμιάνθη ὑπὸ Περσῶν. Βαγώσης δὲ ὁ στρατηγὸς Ἀρταξέρξου γνούς, ὅτι Ἰωάννης ὁ ἀρχιερεὺς τῶν Ἰουδαίων τὸν ἴδιον ἀδελφὸν Ἰησοῦν ἐν τῷ ἱερῷ ἐφόνευσεν, εὐθὺς ἐπιστὰς τοῖς Ἰουδαίοις μετὰ θυμοῦ ἤρξατο λέγειν· ἐτολμήσατε ἐν τῷ ἱερῷ φόνον ἐργάσασθαι."},{"number":301,"text":"πειρωμένου δʼ αὐτοῦ εἰσελθεῖν εἰς τὸν ναὸν ἐκώλυον αὐτόν. ὁ δὲ πρὸς αὐτοὺς ἔφη· πῶς οὐκ ἐγὼ καθαρώτερός εἰμι τοῦ ἀνῃρημένου ἐν τῷ ναῷ; καὶ τούτους ποιησάμενος τοὺς λόγους εἰς τὸν ναὸν εἰσέρχεται. ταύτῃ μὲν οὖν χρησάμενος τῇ ἐπινοίᾳ Βαγώσης τοὺς Ἰουδαίους ἔτεσιν ἑπτὰ ὑπὲρ τῆς Ἰησοῦ τελευτῆς μετῆλθεν."},{"number":302,"text":"Καταστρέψαντος δὲ τοῦ Ἰωάννου τὸν βίον διαδέχεται τὴν ἀρχιερωσύνην ὁ υἱὸς αὐτοῦ Ἰαδδοῦς. ἦν δὲ καὶ τούτῳ ἀδελφὸς Μανασσῆς ὄνομα, ᾧ Σαναβαλλέτης ὁ πεμφθεὶς εἰς Σαμάρειαν ὑπὸ Δαρείου τοῦ τελευταίου βασιλέως σατράπης Χουθαῖος τὸ γένος, ἐξ ὧν καὶ οἱ Σαμαρεῖς εἰσιν,"},{"number":303,"text":"εἰδὼς λαμπρὰν οὖσαν τὴν πόλιν Ἱεροσόλυμα καὶ πολλὰ τοῖς Ἀσσυρίοις καὶ τοῖς ἐν τῇ κοίλῃ Συρίᾳ κατοικοῦσιν τοὺς ἐν αὐτῇ βασιλεῖς πράγματα παρασχόντας, ἀσμένως συνῴκισεν τὴν αὐτοῦ θυγατέρα Νικασὼ καλουμένην, οἰόμενος τὴν ἐπιγαμίαν ὅμηρον αὐτῷ γενήσεσθαι πρὸς τὴν ἀπὸ τοῦ τῶν Ἰουδαίων ἔθνους παντὸς εὔνοιαν."}],"8":[{"number":304,"text":"Κατὰ τοῦτον δὴ τὸν καιρὸν καὶ Φίλιππος ὁ Μακεδόνων βασιλεὺς ἐν Αἰγαῖς ὑπὸ Παυσανίου τοῦ Κεράστου ἐκ δὲ τοῦ τῶν Ὀρεστῶν γένους δολοφονηθεὶς ἀπέθανεν."},{"number":305,"text":"παραλαβὼν δʼ ὁ παῖς αὐτοῦ τὴν βασιλείαν Ἀλέξανδρος καὶ διαβὰς τὸν Ἑλλήσποντον, νικᾷ μὲν τοὺς Δαρείου στρατηγοὺς ἐπὶ Γρανίκῳ συμβαλὼν αὐτοῖς, ἐπελθὼν δὲ τὴν Λυδίαν καὶ τὴν Ἰωνίαν δουλωσάμενος καὶ τὴν Καρίαν ἐπιδραμὼν τοῖς ἐν Παμφυλίᾳ τόποις ἐπέβαλεν, καθὼς ἐν ἄλλοις δεδήλωται."},{"number":306,"text":"Οἱ δὲ τῶν Ἱεροσολυμιτῶν πρεσβύτεροι δεινοπαθοῦντες ἐπὶ τῷ τὸν Ἰαδδοῦ τοῦ ἀρχιερέως ἀδελφὸν ἀλλοφύλῳ συνοικοῦντα μετέχειν τῆς ἀρχιερωσύνης ἐστασίαζον πρὸς αὐτόν·"},{"number":307,"text":"ἡγοῦντο γὰρ τὸν τούτου γάμον ἐπιβάθραν τοῖς παρανομεῖν περὶ τὰς τῶν γυναικῶν συνοικήσεις βουλησομένοις γενέσθαι καὶ τῆς πρὸς τοὺς ἀλλοφύλους αὐτοῖς κοινωνίας ἀρχὴν τοῦτο ἔσεσθαι."},{"number":308,"text":"ὑπάρξαι μέντοι καὶ τῆς προτέρας αἰχμαλωσίας αὐτοῖς καὶ τῶν κακῶν αἴτιον τὸ περὶ τοὺς γάμους πλημμελῆσαί τινας καὶ ἀγαγέσθαι γυναῖκας οὐκ ἐπιχωρίας. ἐκέλευον οὖν τὸν Μανασσῆν διαζεύγνυσθαι τῆς γυναικὸς ἢ μὴ προσιέναι τῷ θυσιαστηρίῳ."},{"number":309,"text":"τοῦ δʼ ἀρχιερέως τῷ λαῷ συναγανακτοῦντος καὶ εἴργοντος τὸν ἀδελφὸν τοῦ βωμοῦ, παραγενόμενος ὁ Μανασσῆς πρὸς τὸν πενθερὸν Σαναβαλλέτην στέργειν μὲν ἔλεγεν αὐτοῦ τὴν θυγατέρα Νικασώ, τῆς μέντοι γε ἱερατικῆς τιμῆς μεγίστης οὔσης ἐν τῷ ἔθνει καὶ τῷ γένει παραμενούσης οὐ βούλεσθαι διʼ αὐτὴν στέρεσθαι."},{"number":310,"text":"τοῦ δὲ Σαναβαλλέτου μὴ μόνον τηρήσειν αὐτῷ τὴν ἱερωσύνην, ἀλλὰ καὶ τὴν ἀρχιερατικὴν παρέξειν δύναμιν καὶ τιμὴν ὑπισχνουμένου καὶ πάντων ἀποδείξειν ὧν αὐτὸς ἐπῆρχεν τόπων ἡγεμόνα βουλόμενον συνοικεῖν αὐτοῦ τῇ θυγατρί, καὶ λέγοντος οἰκοδομήσειν ναὸν ὅμοιον ὄντα τῷ ἐν τοῖς Ἱεροσολύμοις ἐπὶ τοῦ Γαριζεὶν ὄρους, ὃ τῶν κατὰ τὴν Σαμάρειαν ὀρῶν ἐστιν ὑψηλότατον,"},{"number":311,"text":"καὶ ταῦτα ποιήσειν ἐπαγγελλομένου μετὰ τῆς Δαρείου γνώμης τοῦ βασιλέως, ἐπαρθεὶς ταῖς ὑποσχέσεσιν ὁ Μανασσῆς παρέμενεν τῷ Σαναβαλλέτῃ τὴν ἀρχιερωσύνην οἰόμενος ἕξειν Δαρείου δόντος· καὶ γὰρ συνέβαινεν τὸν Σαναβαλλέτην ἤδη πρεσβύτερον εἶναι."},{"number":312,"text":"πολλῶν δὲ ἱερέων καὶ Ἰσραηλιτῶν τοιούτοις γάμοις ἐπιπεπλεγμένων κατεῖχεν οὐ μικρὰ ταραχὴ τοὺς Ἱεροσολυμίτας· ἀφίσταντο γὰρ ἅπαντες πρὸς τὸν Μανασσῆν τοῦ Σαναβαλλέτου χορηγοῦντος αὐτοῖς καὶ χρήματα καὶ χώραν εἰς γεωργίαν καὶ κατοίκησιν ἀπομερίζοντος καὶ παντὶ τρόπῳ τῷ γαμβρῷ συμφιλοκαλοῦντος."},{"number":313,"text":"Κατὰ δὲ τοῦτον τὸν καιρὸν Δαρεῖος ἀκούσας, ὅτι τὸν Ἑλλήσποντον διαβὰς Ἀλέξανδρος καὶ τοὺς σατράπας αὐτοῦ τῇ κατὰ Γράνικον μάχῃ κρατήσας προσωτέρω χωρεῖ, στρατιὰν ἱππικήν τε καὶ πεζικὴν συνήθροιζεν ἀπαντῆσαι διαγνοὺς τοῖς Μακεδόσιν πρὶν ἢ πᾶσαν αὐτοὺς ἐπιόντας καταστρέψασθαι τὴν Ἀσίαν."},{"number":314,"text":"περαιωσάμενος οὖν τὸν Εὐφράτην ποταμὸν καὶ τὸν Ταῦρον τὸ Κιλίκιον ὄρος ὑπερελθὼν ἐν Ἰσσῷ τῆς Κιλικίας τοὺς πολεμίους ὡς ἐκεῖ μαχησόμενος αὐτοῖς ἐξεδέχετο."},{"number":315,"text":"ἡσθεὶς δὲ τῇ Δαρείου καταβάσει ὁ Σαναβαλλέτης εὐθὺς ἔλεγεν τῷ Μανασσῇ τὰς ὑποσχέσεις τελέσειν, ὡς ἂν Δαρεῖος κρατήσας τῶν πολεμίων ὑποστρέψῃ· πέπειστο γὰρ οὐκ αὐτὸς μόνος ἀλλὰ καὶ πάντες οἱ ἐν τῇ Ἀσίᾳ μηδʼ εἰς χεῖρας τοῖς Πέρσαις ἥξειν τοὺς Μακεδόνας διὰ τὸ πλῆθος."},{"number":316,"text":"ἀπέβη δʼ οὐχ ὡς προσεδόκων· συμβαλὼν γὰρ ὁ βασιλεὺς τοῖς Μακεδόσιν ἡττήθη καὶ πολλὴν τῆς στρατιᾶς ἀπολέσας ληφθέντων αἰχμαλώτων αὐτοῦ τῆς μητρὸς καὶ γυναικὸς καὶ τῶν τέκνων ἔφυγεν εἰς Πέρσας."},{"number":317,"text":"Ἀλέξανδρος δʼ εἰς Συρίαν παραγενόμενος Δαμασκὸν αἱρεῖ καὶ Σιδῶνος κρατήσας ἐπολιόρκει Τύρον, ἠξίου τε ἀποστείλας γράμματα πρὸς τὸν τῶν Ἰουδαίων ἀρχιερέα συμμαχίαν τε αὐτῷ πέμπειν καὶ ἀγορὰν τῷ στρατεύματι παρασχεῖν καὶ ὅσα Δαρείῳ πρότερον ἐτέλουν δῶρα τούτῳ διδόναι τὴν Μακεδόνων φιλίαν ἑλομένους·"},{"number":318,"text":"οὐ γὰρ μετανοήσειν ἐπὶ τούτοις. τοῦ δʼ ἀρχιερέως ἀποκριναμένου τοῖς γραμματοφόροις, ὡς ὅρκους εἴη δεδωκὼς Δαρείῳ μὴ βαστάζειν ὅπλα κατʼ αὐτοῦ, καὶ τούτους ἕως ἂν ᾖ Δαρεῖος ἐν τοῖς ζῶσιν μὴ παραβήσεσθαι φήσαντος,"},{"number":319,"text":"ἀκούσας Ἀλέξανδρος παρωξύνθη, καὶ τὴν μὲν Τύρον οὐκ ἔκρινεν καταλιπεῖν ὅσον οὐδέπω μέλλουσαν αἱρεῖσθαι, παραστησάμενος δὲ ταύτην ἠπείλει στρατεύσειν ἐπὶ τὸν τῶν Ἰουδαίων ἀρχιερέα καὶ διδάξειν πάντας, πρὸς τίνας δὴ αὐτοῖς φυλακτέον τοὺς ὅρκους·"},{"number":320,"text":"ὅθεν πονικώτερον χρησάμενος τῇ πολιορκίᾳ λαμβάνει τὴν Τύρον. καταστησάμενος δὲ τὰ ἐν αὐτῇ ἐπὶ τὴν τῶν Γαζαίων πόλιν ἦλθεν καὶ τήν τε Γάζαν καὶ τὸν ἐν αὐτῇ φρούραρχον ὄνομα Βαβημάσιν ἐπολιόρκει."},{"number":321,"text":"Νομίσας δὲ καιρὸν ἐπιτήδειον ἔχειν ὁ Σαναβαλλέτης τῆς ἐπιβολῆς Δαρείου μὲν ἀπέγνω, λαβὼν δὲ ὀκτακισχιλίους τῶν ἀρχομένων ὑπʼ αὐτοῦ πρὸς Ἀλέξανδρον ἧκεν καὶ καταλαβὼν αὐτὸν ἀρχόμενον τῆς Τύρου πολιορκίας, ὧν τε αὐτὸς ἄρχει τόπων ἔλεγεν αὐτῷ παραδιδόναι τούτους καὶ δεσπότην αὐτὸν ἡδέως ἔχειν ἀντὶ Δαρείου τοῦ βασιλέως."},{"number":322,"text":"ἀσμένως δʼ αὐτὸν προσδεξαμένου θαρρῶν ἤδη περὶ τῶν προκειμένων ὁ Σαναβαλλέτης αὐτῷ λόγους προσέφερεν δηλῶν, ὡς γαμβρὸν μὲν ἔχοι Μανασσῆ τοῦ τῶν Ἰουδαίων ἀρχιερέως Ἰαδδοῦ ἀδελφόν, πολλοὺς δὲ καὶ ἄλλους αὐτῷ συμπαρόντας τῶν ὁμοεθνῶν θέλειν ἱερὸν ἐν τοῖς ὑπʼ ἐκείνῳ τόποις ἤδη κατασκευάσαι."},{"number":323,"text":"τοῦτο δʼ εἶναι καὶ τῷ βασιλεῖ συμφέρον εἰς δύο διῃρῆσθαι τὴν Ἰουδαίων δύναμιν, ἵνα μὴ ὁμογνωμονοῦν τὸ ἔθνος μηδὲ συνεστός, εἰ νεωτερίσειέν ποτε, χαλεπὸν ᾖ τοῖς βασιλεῦσιν, καθὼς καὶ πρότερον τοῖς Ἀσσυρίων ἄρξασιν ἐγένετο."},{"number":324,"text":"συγχωρήσαντος δὲ Ἀλεξάνδρου πᾶσαν εἰσενεγκάμενος σπουδὴν ᾠκοδόμησεν ὁ Σαναβαλλέτης τὸν ναὸν καὶ ἱερέα τὸν Μανασσῆ κατέστησεν, μέγιστον γέρας ἡγησάμενος τοῖς ἐκ τῆς θυγατρὸς γενησομένοις τοῦτʼ ἔσεσθαι."},{"number":325,"text":"μηνῶν δʼ ἑπτὰ τῇ Τύρου πολιορκίᾳ διεληλυθότων καὶ δύο τῇ Γάζης ὁ μὲν Σαναβαλλέτης ἀπέθανεν. Ἀλέξανδρος δʼ ἐξελὼν τὴν Γάζαν ἐπὶ τὴν τῶν Ἱεροσολυμιτῶν πόλιν ἀναβαίνειν ἐσπουδάκει."},{"number":326,"text":"ὁ δʼ ἀρχιερεὺς Ἰαδδοῦς τοῦτʼ ἀκούσας ἦν ἐν ἀγωνίᾳ καὶ δέει, πῶς ἀπαντήσει τοῖς Μακεδόσιν ἀμηχανῶν ὀργιζομένου τοῦ βασιλέως ἐπὶ τῇ πρότερον ἀπειθείᾳ. παραγγείλας οὖν ἱκεσίαν τῷ λαῷ καὶ θυσίαν τῷ θεῷ μετʼ αὐτοῦ προσφέρων ἐδεῖτο ὑπερασπίσαι τοῦ ἔθνους καὶ τῶν ἐπερχομένων κινδύνων ἀπαλλάξαι."},{"number":327,"text":"κατακοιμηθέντι δὲ μετὰ τὴν θυσίαν ἐχρημάτισεν αὐτῷ κατὰ τοὺς ὕπνους ὁ θεὸς θαρρεῖν καὶ στεφανοῦντας τὴν πόλιν ἀνοίγειν τὰς πύλας, καὶ τοὺς μὲν ἄλλους λευκαῖς ἐσθῆσιν, αὐτὸν δὲ μετὰ τῶν ἱερέων ταῖς νομίμοις στολαῖς ποιεῖσθαι τὴν ὑπάντησιν μηδὲν προσδοκῶντας πείσεσθαι δεινὸν προνοουμένου τοῦ θεοῦ."},{"number":328,"text":"διαναστὰς δὲ ἐκ τοῦ ὕπνου ἔχαιρέν τε μεγάλως αὐτὸς καὶ τὸ χρηματισθὲν αὐτῷ πᾶσι μηνύσας καὶ ποιήσας ὅσα κατὰ τοὺς ὕπνους αὐτῷ παρηγγέλη τὴν τοῦ βασιλέως παρουσίαν ἐξεδέχετο."},{"number":329,"text":"Πυθόμενος δʼ αὐτὸν οὐ πόρρω τῆς πόλεως ὄντα πρόεισι μετὰ τῶν ἱερέων καὶ τοῦ πολιτικοῦ πλήθους, ἱεροπρεπῆ καὶ διαφέρουσαν τῶν ἄλλων ἐθνῶν ποιούμενος τὴν ὑπάντησιν εἰς τόπον τινὰ Σαφειν λεγόμενον. τὸ δὲ ὄνομα τοῦτο μεταφερόμενον εἰς τὴν Ἑλληνικὴν γλῶτταν σκοπὸν σημαίνει· τά τε γὰρ Ἱεροσόλυμα καὶ τὸν ναὸν συνέβαινεν ἐκεῖθεν ἀφορᾶσθαι."},{"number":330,"text":"τῶν δὲ Φοινίκων καὶ τῶν ἀκολουθούντων Χαλδαίων ὅσα βασιλέως ὀργὴν εἰκὸς ἦν ἐπιτρέψειν αὐτοῖς τήν τε πόλιν διαρπάσειν καὶ τὸν ἀρχιερέα μετʼ αἰκίας ἀπολέσειν λογιζομένων, τὰ ἐναντία τούτων ἐγένετο."},{"number":331,"text":"ὁ γὰρ Ἀλέξανδρος ἔτι πόρρωθεν ἰδὼν τὸ μὲν πλῆθος ἐν ταῖς λευκαῖς ἐσθῆσιν, τοὺς δὲ ἱερεῖς προεστῶτας ἐν ταῖς βυσσίναις αὐτῶν, τὸν δὲ ἀρχιερέα ἐν τῇ ὑακινθίνῳ καὶ διαχρύσῳ στολῇ καὶ ἐπὶ τῆς κεφαλῆς ἔχοντα τὴν κίδαριν καὶ τὸ χρυσοῦν ἐπʼ αὐτῆς ἔλασμα, ᾧ τὸ τοῦ θεοῦ ἐγέγραπτο ὄνομα, προσελθὼν μόνος προσεκύνησεν τὸ ὄνομα καὶ τὸν ἀρχιερέα πρῶτος ἠσπάσατο."},{"number":332,"text":"τῶν δὲ Ἰουδαίων ὁμοῦ πάντων μιᾷ φωνῇ τὸν Ἀλέξανδρον ἀσπασαμένων καὶ κυκλωσαμένων αὐτόν, οἱ μὲν τῆς Συρίας βασιλεῖς καὶ οἱ λοιποὶ τοῦτο ποιήσαντος κατεπλάγησαν καὶ διεφθάρθαι τῷ βασιλεῖ τὴν διάνοιαν ὑπελάμβανον,"},{"number":333,"text":"Παρμενίωνος δὲ μόνου προσελθόντος αὐτῷ καὶ πυθομένου, τί δήποτε προσκυνούντων αὐτὸν ἁπάντων αὐτὸς προσκυνήσειεν τὸν Ἰουδαίων ἀρχιερέα; οὐ τοῦτον, εἶπεν, προσεκύνησα, τὸν δὲ θεόν, οὗ τὴν ἀρχιερωσύνην οὗτος τετίμηται·"},{"number":334,"text":"τοῦτον γὰρ καὶ κατὰ τοὺς ὕπνους εἶδον ἐν τῷ νῦν σχήματι ἐν Δίῳ τῆς Μακεδονίας τυγχάνων, καὶ πρὸς ἐμαυτὸν διασκεπτομένῳ μοι, πῶς ἂν κρατήσαιμι τῆς Ἀσίας, παρεκελεύετο μὴ μέλλειν ἀλλὰ θαρσοῦντα διαβαίνειν· αὐτὸς γὰρ ἡγήσεσθαί μου τῆς στρατιᾶς καὶ τὴν Περσῶν παραδώσειν ἀρχήν."},{"number":335,"text":"ὅθεν ἄλλον μὲν οὐδένα θεασάμενος ἐν τοιαύτῃ στολῇ, τοῦτον δὲ νῦν ἰδὼν καὶ τῆς κατὰ τοὺς ὕπνους ἀναμνησθεὶς ὄψεώς τε καὶ παρακελεύσεως, νομίζω θείᾳ πομπῇ τὴν στρατείαν πεποιημένος Δαρεῖον νικήσειν καὶ τὴν Περσῶν καταλύσειν δύναμιν καὶ πάνθʼ ὅσα κατὰ νοῦν ἐστί μοι προχωρήσειν."},{"number":336,"text":"ταῦτʼ εἰπὼν πρὸς τὸν Παρμενίωνα καὶ δεξιωσάμενος τὸν ἀρχιερέα τῶν Ἰουδαίων παραθεόντων εἰς τὴν πόλιν παραγίνεται. καὶ ἀνελθὼν ἐπὶ τὸ ἱερὸν θύει μὲν τῷ θεῷ κατὰ τὴν τοῦ ἀρχιερέως ὑφήγησιν, αὐτὸν δὲ τὸν ἀρχιερέα καὶ τοὺς ἱερεῖς ἀξιοπρεπῶς ἐτίμησεν."},{"number":337,"text":"δειχθείσης δʼ αὐτῷ τῆς Δανιήλου βίβλου, ἐν ᾗ τινα τῶν Ἑλλήνων καταλύσειν τὴν Περσῶν ἀρχὴν ἐδήλου, νομίσας αὐτὸς εἶναι ὁ σημαινόμενος τότε μὲν ἡσθεὶς ἀπέλυσε τὸ πλῆθος, τῇ δʼ ἐπιούσῃ προσκαλεσάμενος ἐκέλευσεν αὐτοὺς αἰτεῖσθαι δωρεάς, ἃς ἂν αὐτοὶ θέλωσιν."},{"number":338,"text":"τοῦ δʼ ἀρχιερέως αἰτησαμένου χρήσασθαι τοῖς πατρίοις νόμοις καὶ τὸ ἕβδομον ἔτος ἀνείσφορον εἶναι, συνεχώρησεν πάντα. παρακαλεσάντων δʼ αὐτόν, ἵνα καὶ τοὺς ἐν Βαβυλῶνι καὶ Μηδίᾳ Ἰουδαίους τοῖς ἰδίοις ἐπιτρέψῃ νόμοις χρῆσθαι, ἀσμένως ὑπέσχετο ποιήσειν ἅπερ ἀξιοῦσιν."},{"number":339,"text":"εἰπόντος δʼ αὐτοῦ πρὸς τὸ πλῆθος, εἴ τινες αὐτῷ βούλονται συστρατεύειν τοῖς πατρίοις ἔθεσιν ἐμμένοντες καὶ κατὰ ταῦτα ζῶντες, ἑτοίμως ἔχειν ἐπάγεσθαι, πολλοὶ τὴν σὺν αὐτῷ στρατείαν ἠγάπησαν."},{"number":340,"text":"Ὁ μὲν οὖν Ἀλέξανδρος ταῦτα διοικησάμενος ἐν τοῖς Ἱεροσολύμοις ἐξεστράτευσεν ἐπὶ τὰς ἐχομένας πόλεις. πάντων δʼ αὐτὸν πρὸς οὓς ἀφίκοιτο φιλοφρόνως ἐκδεχομένων, Σαμαρεῖται μητρόπολιν τότε τὴν Σίκειμαν ἔχοντες κειμένην πρὸς τῷ Γαριζεὶν ὄρει καὶ κατῳκημένην ὑπὸ τῶν ἀποστατῶν τοῦ Ἰουδαίων ἔθνους, ἰδόντες ὅτι τοὺς Ἰουδαίους Ἀλέξανδρος οὕτω λαμπρῶς τετίμηκεν ἔγνωσαν αὑτοὺς Ἰουδαίους ὁμολογεῖν."},{"number":341,"text":"εἰσὶν γὰρ οἱ Σαμαρεῖς τοιοῦτοι τὴν φύσιν, ὡς ἤδη που καὶ πρότερον δεδηλώκαμεν· ἐν μὲν ταῖς συμφοραῖς ὄντας τοὺς Ἰουδαίους ἀρνοῦνται συγγενεῖς ὁμολογοῦντες τότε τὴν ἀλήθειαν, ὅταν δέ τι λαμπρὸν περὶ αὐτοὺς ἴδωσιν ἐκ τύχης, ἐπιπηδῶσιν αὐτῶν τῇ κοινωνίᾳ προσήκειν αὐτοῖς λέγοντες καὶ ἐκ τῶν Ἰωσήπου γενεαλογοῦντες αὑτοὺς ἐκγόνων Ἐφραίμου καὶ Μανασσοῦς."},{"number":342,"text":"μετὰ λαμπρότητος οὖν καὶ πολλὴν ἐνδεικνύμενοι τὴν περὶ αὐτὸν προθυμίαν ἀπήντησαν τῷ βασιλεῖ μικροῦ δεῖν ἐγγὺς τῶν Ἱεροσολύμων. ἐπαινέσαντος δὲ αὐτοὺς Ἀλεξάνδρου οἱ Σικιμῖται προσῆλθον αὐτῷ προσπαραλαβόντες καὶ οὓς Σαναβαλλέτης πρὸς αὐτὸν στρατιώτας ἀπέστειλεν καὶ παρεκάλουν παραγενόμενον εἰς τὴν πόλιν αὐτῶν τιμῆσαι καὶ τὸ παρʼ αὐτοῖς ἱερόν."},{"number":343,"text":"ὁ δʼ ἐκεῖνο μὲν αὖθις ὑποστρέφων ἰδεῖν ὑπέσχετο πρὸς αὐτούς, ἀξιούντων δὲ ἀφεῖναι τὸν φόρον αὐτοῖς τοῦ ἑβδοματικοῦ ἔτους, οὐδὲ γὰρ αὐτοὺς ἐν αὐτῷ σπείρειν, τίνες ὄντες ταῦτα παρακαλοῦσιν ἐπυνθάνετο. τῶν δʼ εἰπόντων Ἑβραῖοι μὲν εἶναι,"},{"number":344,"text":"χρηματίζειν δʼ οἱ ἐν Σικίμοις Σιδώνιοι, πάλιν αὐτοὺς ἐπηρώτησεν, εἰ τυγχάνουσιν Ἰουδαῖοι. τῶν δʼ οὐκ εἶναι φαμένων ἀλλʼ ἔγωγε ταῦτʼ, εἶπεν, Ἰουδαίοις ἔδωκα, ὑποστρέψας μέντοι γε καὶ διδαχθεὶς ὑφʼ ὑμῶν ἀκριβέστερον ποιήσω τὰ δόξαντα. τοῖς μὲν οὖν Σικιμίταις οὕτως ἀπετάξατο."},{"number":345,"text":"τοὺς δὲ τοῦ Σαναβαλλέτου στρατιώτας ἐκέλευσεν ἕπεσθαι εἰς Αἴγυπτον· ἐκεῖ γὰρ αὐτοῖς δώσειν κλήρους γῆς· ὃ καὶ μετʼ ὀλίγον ἐποίησεν ἐν τῇ Θηβαΐδι φρουρεῖν τὴν χώραν αὐτοῖς προστάξας."},{"number":346,"text":"Τελευτήσαντος δὲ Ἀλεξάνδρου ἡ μὲν ἀρχὴ εἰς τοὺς διαδόχους ἐμερίσθη, τὸ δὲ ἐπὶ τοῦ Γαριζεὶν ὄρους ἱερὸν ἔμεινεν. εἰ δέ τις αἰτίαν ἔσχεν παρὰ τοῖς Ἱεροσολυμίταις κοινοφαγίας ἢ τῆς ἐν σαββάτοις παρανομίας ἤ τινος ἄλλου τοιούτου ἁμαρτήματος, παρὰ τοὺς Σικιμίτας ἔφευγεν λέγων ἀδίκως ἐκβεβλῆσθαι."},{"number":347,"text":"τετελευτήκει δὲ κατʼ ἐκεῖνον ἤδη τὸν καιρὸν καὶ ὁ ἀρχιερεὺς Ἰαδδοῦς καὶ τὴν ἀρχιερωσύνην Ὀνίας ὁ παῖς αὐτοῦ παρειλήφει. τὰ μὲν δὴ περὶ τοὺς Ἱεροσολυμίτας ἐν τούτοις ἐτύγχανεν ὄντα."}]},"count":347};a[12]={"book":12,"title":"Τάδε ἔνεστιν ἐν τῇ δωδεκάτῃ τῶν Ἰωσήπου ἱστοριῶν τῆς Ἰουδαϊκῆς ἀρχαιολογίας.","argument":{"title":"","text":"Ὡς Πτολεμαῖος ὁ Λάγου δόλῳ καὶ ἀπάτῃ παραλαβὼν τὰ Ἱεροσόλυμα καὶ τὴν Ἰουδαίαν πολλοὺς ἐξ αὐτῆς εἰς Αἴγυπτον μετῴκισεν.\n\nὡς ὁ υἱὸς αὐτοῦ Πτολεμαῖος ὁ κληθεὶς Φιλάδελφος τοὺς Ἰουδαίων νόμους εἰς τὴν Ἑλληνικὴν γλῶσσαν μετέβαλεν καὶ πολλοὺς αἰχμαλώτους ἀπέλυσεν Ἐλεαζάρῳ τῷ ἀρχιερεῖ αὐτῶν χαριζόμενος, καὶ ἀναθήματα πολλὰ ἀνέθηκεν τῷ θεῷ.\n\nπῶς ἐτίμησαν οἱ τῆς Ἀσίας βασιλεῖς τὸ Ἰουδαίων ἔθνος καὶ πολίτας ἐποίησαν ἐν ταῖς ὑπ' αὐτῶν κτισθείσαις πόλεσιν κατοικίσαντες.\n\nἐκ τῆς γενομένης ἀτυχίας ἐπανόρθωσις ὑπὸ Ἰωσήπου τοῦ Τωβίου ποιησαμένου φιλίαν πρὸς Πτολεμαῖον τὸν Ἐπιφανῆ.\n\nφιλία καὶ συμμαχία Λακεδαιμονίων πρὸς Ὀνίαν τὸν ἀρχιερέα τῶν Ἰουδαίων.\n\nστάσις τῶν δυνατῶν Ἰουδαίων πρὸς ἀλλήλους καὶ ὡς ἐπεκαλέσαντο Ἀντίοχον τὸν Ἐπιφανῆ.\n\nὅτι στρατευσάμενος Ἀντίοχος ἐπὶ Ἱεροσόλυμα τήν τε πόλιν παρέλαβεν καὶ τὸν ναὸν ἐσύλησεν.\n\nὡς Ἀντιόχου κωλύσαντος τοῖς πατρίοις νόμοις χρῆσθαι τοὺς Ἰουδαίους μόνος ὁ Ἀσαμωναίου παῖς Ματταθίας κατεφρόνησεν τοῦ βασιλέως καὶ τοὺς Ἀντιόχου στρατηγοὺς ἐνίκησεν.\n\nἡ Ματταθίου τελευτή, γηραιοῦ μὲν ὄντος ἤδη, παραδόντος δὲ τὴν τῶν πραγμάτων προστασίαν τοῖς παισίν.\n\nὡς ὁ υἱὸς αὐτοῦ Ἰούδας τοῖς Ἀντιόχου στρατηγοῖς μαχεσάμενος τοὺς Ἰουδαίους εἰς τὴν πάτριον ἐπανήγαγε πολιτείαν καὶ ἀρχιερεὺς ἀπεδείχθη ὑπὸ τοῦ λαοῦ.\n\nὡς ὁ Ἀντιόχου στρατηγὸς Ἀπολλώνιος εἰς τὴν Ἰουδαίαν ἐμβαλὼν ἡττηθεὶς ἀπέθανεν.\n\nἡ Σαΐωνος καὶ Γοργίου στρατεία ἐπὶ τὴν Ἰουδαίαν καὶ ἧττα καὶ διαφορὰ τοῦ στρατοῦ.\n\nὅτι στρατευσάμενος Ἰούδας ἐπὶ Ἀμμανίτας καὶ εἰς τὴν Γαλαδῖτιν ἐνίκησεν.\n\nὡς Σίμων ὁ ἀδελφὸς αὐτοῦ στρατευσάμενος ἐπὶ Τυρίους καὶ Πτολεμαεῖς ἐκράτησεν αὐτῶν.\n\nΛυσίου στρατεία τοῦ Ἀντιόχου στρατηγοῦ ἐπὶ Ἰουδαίους καὶ ἧττα.\n\nὡς Ἀντίοχος ὁ Ἐπιφανὴς ἐτελεύτησεν ἐν Πέρσαις.\n\nὡς Ἀντίοχος ὁ ἐπικληθεὶς Εὐπάτωρ στρατευσάμενος ἐπὶ Ἰουδαίους μετὰ Λυσίου καὶ νικήσας ἐπολιόρκει Ἰούδαν εἰς τὸ ἱερὸν ἐγκλείσας.\n\nὅτι πολλοῦ χρόνου τῇ πολιορκίᾳ τριβομένου φιλίαν ποιησάμενος πρὸς Ἰούδαν εὐπρεπῶς ἀνεχώρησεν ἐκ τῆς Ἰουδαίας Ἀντίοχος.\n\nὡς Βακχίδης ὁ Δημητρίου στρατηγὸς ἐπιστρατευσάμενος τοῖς Ἰουδαίοις ἄπρακτος ἀνέστρεψε πρὸς τὸν βασιλέα.\n\nὡς Νικάνωρ μετὰ τὸν Βακχίδην πεμφθεὶς στρατηγὸς ἀπώλετο σὺν τῇ στρατιᾷ αὐτοῦ.\n\nὅτι πάλιν ἐπὶ τὴν Ἰουδαίαν Βακχίδης ἐκπεμφθεὶς ἐνίκησεν.\n\nὡς Ἰούδας διεφθάρη μαχόμενος.\n\nπεριέχει ἡ βίβλος χρόνον ἐτῶν ρο."},"chapters":{"1":[{"number":1,"text":"Ἀλέξανδρος μὲν οὖν ὁ τῶν Μακεδόνων βασιλεὺς καταλύσας τὴν Περσῶν ἡγεμονίαν καὶ τὰ κατὰ τὴν Ἰουδαίαν τὸν προειρημένον καταστησάμενος τρόπον τελευτᾷ τὸν βίον."},{"number":2,"text":"μεταπεσούσης δʼ εἰς πολλοὺς τῆς ἀρχῆς Ἀντίγονος μὲν τῆς Ἀσίας ἐπικρατεῖ, Σέλευκος δὲ Βαβυλῶνος καὶ τῶν κεῖθι ἐθνῶν, Λυσίμαχός τε τὸν Ἑλλήσποντον διεῖπεν, τὴν δὲ Μακεδονίαν εἶχεν Κάσσανδρος, Πτολεμαῖος δὲ ὁ Λάγου τὴν Αἴγυπτον εἰλήφει."},{"number":3,"text":"στασιαζόντων δὲ τούτων καὶ πρὸς ἀλλήλους φιλοτιμουμένων ὑπὲρ τῆς ἰδίας ἀρχῆς πολέμους τε συνεχεῖς καὶ μακροὺς συνέβη γίγνεσθαι καὶ τὰς πόλεις κακοπαθεῖν καὶ πολλοὺς ἐν τοῖς ἀγῶσιν ἀποβάλλειν τῶν οἰκητόρων, ὡς καὶ τὴν Συρίαν ἅπασαν ὑπὸ Πτολεμαίου τοῦ Λάγου τότε Σωτῆρος χρηματίζοντος τἀναντία παθεῖν αὐτοῦ τῇ ἐπικλήσει."},{"number":4,"text":"κατέσχε δὲ οὗτος καὶ τὰ Ἱεροσόλυμα δόλῳ καὶ ἀπάτῃ χρησάμενος· ἐλθὼν γὰρ σαββάτοις εἰς τὴν πόλιν ὡς θύσων, μήτε τῶν Ἰουδαίων αὐτὸν ἀμυνομένων, οὐδὲν γὰρ ὑπενόουν πολέμιον, καὶ διὰ τὸ ἀνύποπτον καὶ τὴν ἡμέραν ἐν ἀργίᾳ καὶ ῥαθυμίᾳ τυγχανόντων, ἀπόνως ἐγκρατὴς γίγνεται τῆς πόλεως καὶ πικρῶς ἦρχεν αὐτῆς."},{"number":5,"text":"μαρτυρεῖ δὲ τῷ λόγῳ τούτῳ καὶ Ἀγαθαρχίδης ὁ Κνίδιος ὁ τὰς τῶν διαδόχων πράξεις συγγραψάμενος, ὀνειδίζων ἡμῖν δεισιδαιμονίαν ὡς διʼ αὐτὴν ἀποβαλοῦσι τὴν ἐλευθερίαν, λέγων οὕτως·"},{"number":6,"text":"ἔστιν ἔθνος Ἰουδαίων λεγόμενον, οἳ πόλιν ὀχυρὰν καὶ μεγάλην ἔχοντες Ἱεροσόλυμα ταύτην ὑπερεῖδον ὑπὸ Πτολεμαίῳ γενομένην ὅπλα λαβεῖν οὐ θελήσαντες, ἀλλὰ διὰ τὴν ἄκαιρον δεισιδαιμονίαν χαλεπὸν ὑπέμειναν ἔχειν δεσπότην."},{"number":7,"text":"Ἀγαθαρχίδης μὲν οὖν ταῦτα περὶ τοῦ ἔθνους ἡμῶν ἀπεφήνατο. ὁ δὲ Πτολεμαῖος πολλοὺς αἰχμαλώτους λαβὼν ἀπό τε τῆς ὀρεινῆς Ἰουδαίας καὶ τῶν περὶ Ἱεροσόλυμα τόπων καὶ τῆς Σαμαρείτιδος καὶ τῶν ἐν Γαριζείν, κατῴκισεν ἅπαντας εἰς Αἴγυπτον ἀγαγών."},{"number":8,"text":"ἐπεγνωκὼς δὲ τοὺς ἀπὸ τῶν Ἱεροσολύμων περί τε τὴν τῶν ὅρκων φυλακὴν καὶ τὰς πίστεις βεβαιοτάτους ὑπάρχοντας ἐξ ὧν ἀπεκρίναντο Ἀλεξάνδρῳ πρεσβευσαμένῳ πρὸς αὐτοὺς μετὰ τὸ κρατῆσαι Δαρείου τῇ μάχῃ, πολλοὺς αὐτῶν εἰς τὰ φρούρια καταλοχίσας καὶ τοῖς Μακεδόσιν ἐν Ἀλεξανδρείᾳ ποιήσας ἰσοπολίτας ὅρκους ἔλαβεν παρʼ αὐτῶν, ὅπως τοῖς ἐκγόνοις τοῦ παραθεμένου τὴν πίστιν διαφυλάξωσιν."},{"number":9,"text":"οὐκ ὀλίγοι δʼ οὐδὲ τῶν ἄλλων Ἰουδαίων εἰς τὴν Αἴγυπτον παρεγίγνοντο τῆς τε ἀρετῆς τῶν τόπων αὐτοὺς καὶ τῆς τοῦ Πτολεμαίου φιλοτιμίας προκαλουμένης."},{"number":10,"text":"στάσεις μέντοι γε τοῖς ἐκγόνοις αὐτῶν πρὸς τοὺς Σαμαρείτας τὴν πάτριον ἀγωγὴν τῶν ἐθῶν ἀποσώζειν προαιρουμένοις ἐγίγνοντο καὶ πρὸς ἀλλήλους ἐπολέμουν, τῶν μὲν Ἱεροσολυμιτῶν τὸ παρʼ αὐτοῖς ἱερὸν ἅγιον εἶναι λεγόντων καὶ τὰς θυσίας ἐκεῖ πέμπειν ἀξιούντων, τῶν δὲ Σικιμιτῶν εἰς τὸ Γαριζεὶν ὄρος κελευόντων."}],"2":[{"number":11,"text":"Βασιλεύσαντος δὲ Ἀλεξάνδρου ἔτη δώδεκα καὶ μετʼ αὐτὸν Πτολεμαίου τοῦ Σωτῆρος τεσσαράκοντα καὶ ἕν, ἔπειτα τὴν βασιλείαν τῆς Αἰγύπτου παραλαβὼν ὁ Φιλάδελφος καὶ κατασχὼν αὐτὴν ἐπʼ ἔτη ἑνὸς δέοντα τεσσαράκοντα τόν τε νόμον ἡρμήνευσε καὶ τοὺς δουλεύοντας ἐν Αἰγύπτῳ τῶν Ἱεροσολυμιτῶν ἀπέλυσε τῆς δουλείας ὄντας περὶ δώδεκα μυριάδας ἐξ αἰτίας τοιαύτης·"},{"number":12,"text":"Δημήτριος ὁ Φαληρεύς, ὃς ἦν ἐπὶ τῶν βιβλιοθηκῶν τοῦ βασιλέως, σπουδάζων εἰ δυνατὸν εἴη πάντα τὰ κατὰ τὴν οἰκουμένην συναγαγεῖν βιβλία καὶ συνωνούμενος, εἴ τι που μόνον ἀκούσειε σπουδῆς ἄξιον ὄν, τῇ τοῦ βασιλέως προαιρέσει, μάλιστα γὰρ τὰ περὶ τὴν συλλογὴν τῶν βιβλίων εἶχεν φιλοκάλως, συνηγωνίζετο."},{"number":13,"text":"ἐρομένου δʼ αὐτόν ποτε τοῦ Πτολεμαίου, πόσας ἤδη μυριάδας ἔχοι συνειλεγμένας βιβλίων, τῶν μὲν ὑπαρχόντων εἶπεν εἶναι περὶ εἴκοσι, ὀλίγου δὲ χρόνου εἰς πεντήκοντα συναθροίσειν."},{"number":14,"text":"μεμηνῦσθαι δʼ ἔλεγεν αὐτῷ πολλὰ εἶναι καὶ παρὰ Ἰουδαίοις τῶν παρʼ αὐτοῖς νομίμων συγγράμματα σπουδῆς ἄξια καὶ τῆς βασιλέως βιβλιοθήκης, ἃ τοῖς ἐκείνων χαρακτῆρσιν καὶ τῇ διαλέκτῳ γεγραμμένα πόνον αὐτοῖς οὐκ ὀλίγον παρέξειν εἰς τὴν Ἑλληνικὴν μεταβαλλόμενα γλῶτταν."},{"number":15,"text":"δοκεῖ μὲν γὰρ εἶναι τῇ ἰδιότητι τῶν Συρίων γραμμάτων ἐμφερὴς ὁ χαρακτὴρ αὐτῶν καὶ τὴν φωνὴν ὁμοίαν αὐτοῖς ἀπηχεῖν, ἰδιότροπον δὲ αὐτὴν εἶναι συμβέβηκεν. οὐδὲν οὖν ἔλεγεν κωλύειν καὶ ταῦτα μεταβαλόντα, δύνασθαι γὰρ τῆς εἰς αὐτὸ χορηγίας εὐποροῦντα, ἔχειν ἐν τῇ βιβλιοθήκῃ καὶ τὰ παρʼ ἐκείνοις."},{"number":16,"text":"δόξας οὖν ὁ βασιλεὺς ἄριστα τὸν Δημήτριον φιλοτιμουμένῳ περὶ πλῆθος αὐτῷ βιβλίων ὑποτίθεσθαι γράφει τῷ τῶν Ἰουδαίων ἀρχιερεῖ ταῦτα γίγνεσθαι."},{"number":17,"text":"Ἀρισταῖος δέ τις φίλος ὢν ἐν τοῖς μάλιστα τῷ βασιλεῖ καὶ σπουδαζόμενος ὑπʼ αὐτοῦ διὰ μετριότητα, πολλάκις μὲν καὶ πρότερον ἔγνω παρακαλέσαι τὸν βασιλέα, ὅπως ἀπολύσῃ τοὺς αἰχμαλώτους Ἰουδαίους ὅσοι κατὰ τὴν βασιλείαν ἦσαν αὐτοῦ,"},{"number":18,"text":"καιρὸν δʼ ἐπιτήδειον τοῦτον εἶναι δοκιμάσας τῆς δεήσεως πρώτοις περὶ τούτου διαλέγεται τοῖς ἄρχουσι τῶν σωματοφυλάκων Σωσιβίῳ τῷ Ταραντίνῳ καὶ Ἀνδρέᾳ, συναγωνίσασθαι περὶ ὧν ἐντυγχάνειν μέλλει τῷ βασιλεῖ παρακαλῶν αὐτούς."},{"number":19,"text":"προσλαβὼν δὲ καὶ τὴν τῶν προειρημένων γνώμην ὁ Ἀρισταῖος, προσελθὼν τῷ βασιλεῖ λόγους πρὸς αὐτὸν τοιούτους ἐποιήσατο·"},{"number":20,"text":"οὐ χρῆν ἀπατωμένους ἡμᾶς, ὦ βασιλεῦ, περιορᾶν, ἀλλὰ τἀληθὲς ἀπελέγχειν· τοὺς γὰρ τῶν Ἰουδαίων νόμους οὐ μεταγράψαι μόνον ἀλλὰ καὶ μεθερμηνεῦσαι διεγνωκότες εἰς τὸ σοὶ κεχαρισμένον, τίνι καὶ λόγῳ χρώμενοι τοῦτο πράξαιμεν ἂν πολλῶν Ἰουδαίων ἐν τῇ σῇ βασιλείᾳ δουλευόντων;"},{"number":21,"text":"οὓς τῇ σαυτοῦ μεγαλοψυχίᾳ καὶ χρηστότητι ποιῶν ἀκολούθως ἀπόλυσον τῆς ταλαιπωρίας, τὴν βασιλείαν σου διέποντος τοῦ θεμένου τοὺς νόμους αὐτοῖς θεοῦ, καθὼς ἐμοὶ πολυπραγμονήσαντι μαθεῖν ὑπῆρξεν."},{"number":22,"text":"τὸν γὰρ ἅπαντα συστησάμενον θεὸν καὶ οὗτοι καὶ ἡμεῖς σεβόμεθα Ζῆνα καλοῦντες αὐτὸν ἐτύμως ἀπὸ τοῦ πᾶσιν ἐμφύειν τὸ ζῆν τὴν ἐπίκλησιν αὐτοῦ θέντες. ὅθεν εἰς τιμὴν τοῦ θεοῦ τοὺς ἐξαίρετον τὴν εἰς αὐτὸν θρησκείαν πεποιημένους ἀπόδος τοῖς τὴν πατρίδα καὶ τὸν ἐν αὐτῇ βίον ἀπολελοιπόσιν."},{"number":23,"text":"ἴσθι μέντοι γε, ὦ βασιλεῦ, ὡς οὔτε γένει προσήκων αὐτοῖς οὔτε ὁμόφυλος ὢν ταῦτα περὶ αὐτῶν ἀξιῶ, πάντων δὲ ἀνθρώπων δημιούργημα ὄντων τοῦ θεοῦ· καὶ δὴ γιγνώσκων αὐτὸν ἡδόμενον τοῖς εὖ ποιοῦσιν ἐπὶ τοῦτο καὶ σὲ παρακαλῶ."},{"number":24,"text":"Ταῦτʼ εἰπόντος τοῦ Ἀρισταίου ἀναβλέψας εἰς αὐτὸν ὁ βασιλεὺς ἱλαρῷ καὶ γεγηθότι τῷ προσώπῳ πόσας, εἶπεν, ὑπολαμβάνεις τῶν ἀπολυθησομένων ἔσεσθαι μυριάδας; ὑποτυχόντος δὲ Ἀνδρέου, παρειστήκει γάρ, καὶ φήσαντος ὀλίγῳ πλείονας ἔσεσθαι τῶν ἕνδεκα μυριάδων ἦ μικρὰν ἄρα εἶπεν, ἡμᾶς, Ἀρισταῖε, δωρεὰν αἰτεῖς. Σωσιβίου δὲ καὶ τῶν παρόντων φησάντων,"},{"number":25,"text":"ὡς ἄξιον αὐτὸν δέοι τῆς αὐτοῦ μεγαλοψυχίας τῷ παρεσχηκότι τὴν βασιλείαν θεῷ ποιήσασθαι χαριστήριον, διαχυθεὶς ὑπʼ αὐτῶν ἐκέλευσεν, ὅταν τοῖς στρατιώταις ἀποδιδῶσιν τὸ μισθοφορικόν, καὶ ὑπὲρ ἑκάστου τῶν παρʼ αὐτοῖς αἰχμαλώτων καταβαλεῖν δραχμὰς ἑκατὸν εἴκοσι."},{"number":26,"text":"καὶ περὶ ὧν ἠξίουν προθεῖναι γράμματα ὑπέσχετο μεγαλοπρεπῶς τε ἔχοντα καὶ τὴν Ἀρισταίου προαίρεσιν βεβαιοῦντα καὶ πρὸ ταύτης τὴν τοῦ θεοῦ βούλησιν, καθʼ ἣν οὐ μόνον τοὺς ὑπὸ τοῦ πατρὸς ἀχθέντας αὐτοῦ καὶ τῆς ἐκείνου στρατιᾶς ἀπολύσειν ἔλεγεν, ἀλλὰ καὶ τοὺς προϋπάρχοντας ἐν τῇ βασιλείᾳ καὶ εἴ τινες αὖθις ἐπεισήχθησαν."},{"number":27,"text":"πλειόνων δʼ ἢ τετρακοσίων ταλάντων τῆς ἀπολυτρώσεως γενήσεσθαι φαμένων ταῦτά τε συνεχώρει καὶ τὸ ἀντίγραφον τοῦ προστάγματος εἰς δήλωσιν τῆς τοῦ βασιλέως μεγαλοφροσύνης ἔγνωσαν διαφυλάξαι."},{"number":28,"text":"ἦν δὲ τοιοῦτον· ὅσοι τῶν συστρατευσαμένων ἡμῶν τῷ πατρὶ τήν τε Συρίαν καὶ Φοινίκην ἐπέδραμον καὶ τὴν Ἰουδαίαν καταστρεψάμενοι σώματα λαβόντες αἰχμάλωτα διεκόμισαν εἴς τε τὰς πόλεις ἡμῶν καὶ τὴν χώραν καὶ ταῦτα ἀπημπόλησαν, τούς τε πρὸ αὐτῶν ὄντας ἐν τῇ ἐμῇ βασιλείᾳ καὶ εἴ τινες νῦν εἰσήχθησαν, τούτους ἀπολυέτωσαν οἱ παρʼ αὐτοῖς ἔχοντες ὑπὲρ ἑκάστου σώματος λαμβάνοντες δραχμὰς ἑκατὸν εἴκοσι, οἱ μὲν στρατιῶται μετὰ καὶ τῶν ὀψωνίων, οἱ δὲ λοιποὶ ἀπὸ τῆς βασιλικῆς τραπέζης κομιζόμενοι τὰ λύτρα."},{"number":29,"text":"νομίζω γὰρ αὐτοὺς καὶ παρὰ τὴν τοῦ πατρὸς προαίρεσιν καὶ παρὰ τὸ δέον ᾐχμαλωτίσθαι, τήν τε χώραν αὐτῶν διὰ τὴν στρατιωτικὴν αὐθάδειαν κεκακῶσθαι, καὶ διὰ τὴν εἰς Αἴγυπτον αὐτῶν μεταγωγὴν πολλὴν ὠφέλειαν ἐκ τούτου τοῖς στρατιώταις γεγονέναι."},{"number":30,"text":"τὸ δίκαιον οὖν σκοπῶν καὶ τοὺς καταδεδυναστευμένους παρὰ τὸ προσῆκον ἐλεῶν ἀπολύειν κελεύω τοὺς ἐν ταῖς οἰκετείαις ὄντας Ἰουδαίους τὸ προγεγραμμένον κομιζομένους ὑπὲρ αὐτῶν κεφάλαιον τοὺς κεκτημένους, καὶ μηδένα περὶ τούτων κακουργεῖν, ἀλλʼ ὑπακούειν τοῖς προστεταγμένοις."},{"number":31,"text":"βούλομαι δὲ τὰς ἀπογραφὰς ἀφʼ ἧς ἐξεπέμφθησαν ἐπὶ τρεῖς ἡμέρας ποιεῖσθαι πρὸς τοὺς ἐπʼ αὐτῶν ὑπάρχοντας, παραδεικνύντας εὐθὺς καὶ τὰ σώματα· τοῦτο γὰρ τοῖς ἐμαυτοῦ πράγμασιν ἡγοῦμαι συμφέρειν. προσαγγελλέτω δὲ τοὺς ἀπειθήσαντας ὁ βουλόμενος, ὧν τὰς οὐσίας εἰς τὴν βασιλικὴν κτῆσιν ἀνενεχθῆναι βούλομαι."},{"number":32,"text":"τούτου δὲ τοῦ προστάγματος ἀναγνωσθέντος τῷ βασιλεῖ καὶ τὰ μὲν ἄλλα ἔχοντος, μόνου δὲ λείποντος τοῦ περὶ τῶν πρότερον καὶ τῶν αὖθις εἰσηγμένων Ἰουδαίων μὴ διεστάλθαι, προσέθηκεν αὐτὸς μεγαλοφρόνως καὶ τὸ περὶ τούτων φιλάνθρωπον, καὶ τὴν τῶν διαφόρων δόσιν οὖσαν ἀθρόαν ἐκέλευσεν τοῖς ὑπηρέταις τῶν πραγμάτων ἀπομερίσαι καὶ τοῖς βασιλικοῖς τραπεζίταις."},{"number":33,"text":"γενομένου δὲ τούτου ταχέως ἐν ἑπτὰ ταῖς πάσαις ἡμέραις τέλος εἰλήφει τὰ δοχθέντα τῷ βασιλεῖ, τάλαντα δʼ ὑπὲρ ἑξήκοντα καὶ τετρακόσια τῶν λύτρων ἐγένετο· καὶ γὰρ ὑπὲρ τῶν νηπίων εἰσέπραττον οἱ δεσπόται τὰς εἴκοσι καὶ ἑκατὸν δραχμάς, ὡς τοῦ βασιλέως καὶ ὑπὲρ τούτων διδόναι κελεύσαντος ἐν τῷ προγράψαι ὑπὲρ ἑκάστου σώματος λαμβάνειν τὸ προειρημένον."},{"number":34,"text":"Ἐπειδὴ δὲ ταῦτʼ ἐγένετο κατὰ τὴν τοῦ βασιλέως βούλησιν μεγαλοπρεπῶς, ἐκέλευσε τὸν Δημήτριον εἰσδοῦναι καὶ τὸ περὶ τῆς τῶν Ἰουδαϊκῶν βιβλίων ἀναγραφῆς δόγμα· οὐδὲν γὰρ εἰκῆ τοῖς βασιλεῦσιν ᾠκονομεῖτο, πάντα δὲ μετὰ πολλῆς ἐπιμελείας ἐπράττετο."},{"number":35,"text":"διὸ καὶ τὸ τῆς εἰσδόσεως ἀντίγραφον καὶ τὸ τῶν ἐπιστολῶν κατατέτακται καὶ τὸ πλῆθος τῶν ἀπεσταλμένων ἀναθημάτων καὶ τὸ ἐφʼ ἑκάστου κατασκευασθέν, ὡς ἀκριβεστάτην εἶναι τὴν τοῦ τεχνίτου τοῖς ὁρῶσι μεγαλουργίαν, καὶ διὰ τὴν τῶν κατασκευασμάτων ἐξοχὴν τὸν ἑκάστου δημιουργὸν εὐθέως ποιήσειν γνώριμον. τῆς μέντοι γε εἰσδόσεως τὸ ἀντίγραφον ὑπῆρχε τοιοῦτον·"},{"number":36,"text":"βασιλεῖ μεγάλῳ παρὰ Δημητρίου. προστάξαντός σου, ὦ βασιλεῦ, περί τε τῶν ἔτι λειπόντων εἰς ἀναπλήρωσιν τῆς βιβλιοθήκης συγγραμμάτων, ὅπως συναχθῇ, καὶ περὶ τῶν διαπεπτωκότων, ὅπως τῆς δεούσης ἐπιμελείας τύχῃ, πάσῃ κεχρημένος περὶ ταῦτα σπουδῇ δηλῶ σοι τὰ τῆς Ἰουδαίων νομοθεσίας βιβλία λείπειν ἡμῖν σὺν ἑτέροις· χαρακτῆρσιν γὰρ Ἑβραϊκοῖς γεγραμμένα καὶ φωνῇ τῇ ἐθνικῇ ἐστιν ἡμῖν ἀσαφῆ."},{"number":37,"text":"συμβέβηκε δʼ αὐτὰ καὶ ἀμελέστερον ἢ ἔδει σεσημάνθαι διὰ τὸ βασιλικῆς οὐ τετυχηκέναι προνοίας. ἔστι δʼ ἀναγκαῖον εἶναι καὶ ταῦτα παρὰ σοὶ διηκριβωμένα· φιλοσοφωτέραν γὰρ καὶ ἀκέραιον τὴν νομοθεσίαν εἶναι συμβέβηκεν ὡς ἂν οὖσαν θεοῦ."},{"number":38,"text":"διὸ καὶ τοὺς ποιητὰς αὐτῆς καὶ τοὺς συγγραφεῖς τῶν ἱστοριῶν οὐκ ἐπιμνησθῆναί φησιν Ἑκαταῖος ὁ Ἀβδηρίτης οὐδὲ τῶν κατʼ αὐτὴν πολιτευσαμένων ἀνδρῶν, ὡς ἁγνῆς οὔσης καὶ μὴ δέον αὐτὴν βεβήλοις στόμασιν διασαφεῖσθαι."},{"number":39,"text":"ἐὰν οὖν σοι δοκῇ, βασιλεῦ, γράψεις τῷ τῶν Ἰουδαίων ἀρχιερεῖ, ὅπως ἀποστείλῃ τῶν πρεσβυτέρων ἓξ ἀφʼ ἑκάστης φυλῆς τοὺς ἐμπειροτάτους τῶν νόμων, παρʼ ὧν τὸ τῶν βιβλίων σαφὲς καὶ σύμφωνον ἐκμαθόντες καὶ τὸ κατὰ τὴν ἑρμηνείαν ἀκριβὲς λαβόντες τῶν πραγμάτων ἀξίως ταῦτα τῆς σῆς προαιρέσεως συναγάγωμεν."},{"number":40,"text":"Τοιαύτης οὖν τῆς εἰσδόσεως γενομένης ὁ βασιλεὺς ἐκέλευσεν τῷ ἀρχιερεῖ τῶν Ἰουδαίων Ἐλεαζάρῳ γραφῆναι περὶ τούτων ἅμα καὶ τὴν ἄφεσιν τῶν δουλευόντων παρʼ αὐτοῖς Ἰουδαίων δηλοῦντας αὐτῷ, καὶ πρὸς κατασκευὴν δὲ κρατήρων καὶ φιαλῶν καὶ σπονδείων ἔπεμψε χρυσίου μὲν ὁλκῆς τάλαντα πεντήκοντα, λίθων δὲ πολυτελῶν ἀσυλλόγιστόν τι πλῆθος."},{"number":41,"text":"προσέταξε δὲ καὶ τοὺς φύλακας τῶν κιβωτῶν, ἐν αἷς ἐτύγχανον οἱ λίθοι, τὴν ἐκλογὴν τοῖς τεχνίταις αὐτοῖς οὗπερ ἂν θελήσωσιν εἴδους ἐπιτρέπειν. διετάξατο δὲ καὶ νομίσματος εἰς θυσίας καὶ τὰς λοιπὰς χρείας πρὸς ἑκατὸν τάλαντα τῷ ἱερεῖ δοθῆναι."},{"number":42,"text":"διηγήσομαι δὲ τὰ κατασκευάσματα καὶ τὸν τρόπον τῆς δημιουργίας αὐτῶν μετὰ τὸ προεκθέσθαι τὸ ἀντίγραφον τῆς ἐπιστολῆς τῆς γραφείσης Ἐλεαζάρῳ τῷ ἀρχιερεῖ, ταύτην λαβόντι τὴν τιμὴν ἐξ αἰτίας τοιαύτης·"},{"number":43,"text":"τελευτήσαντος Ὀνίου τοῦ ἀρχιερέως ὁ παῖς αὐτοῦ Σίμων γίγνεται διάδοχος ὁ καὶ δίκαιος ἐπικληθεὶς διά τε τὸ πρὸς τὸν θεὸν εὐσεβὲς καὶ τὸ πρὸς τοὺς ὁμοφύλους εὔνουν."},{"number":44,"text":"ἀποθανόντος δὲ τούτου καὶ νήπιον υἱὸν καταλιπόντος τὸν κληθέντα Ὀνίαν ὁ ἀδελφὸς αὐτοῦ Ἐλεάζαρος, περὶ οὗ τὸν λόγον ποιούμεθα, τὴν ἀρχιερωσύνην παρέλαβεν, ᾧ γράφει Πτολεμαῖος τοῦτον τὸν τρόπον·"},{"number":45,"text":"βασιλεὺς Πτολεμαῖος Ἐλεαζάρῳ τῷ ἀρχιερεῖ χαίρειν. πολλῶν ἐν τῇ βασιλείᾳ κατῳκισμένων Ἰουδαίων, οὓς αἰχμαλωτισθέντας ὑπὸ Περσῶν ὅτʼ ἐκράτουν ὁ ἐμὸς πατὴρ ἐτίμησεν, καὶ τοὺς μὲν εἰς τὸ στρατιωτικὸν κατέταξεν ἐπὶ μείζοσιν μισθοφοραῖς, τισὶν δὲ γενομένοις ἐν Αἰγύπτῳ σὺν αὐτῷ τὰ φρούρια καὶ τὴν τούτων φυλακὴν παρέθετο, ἵνα τοῖς Αἰγυπτίοις ὦσιν φοβεροί,"},{"number":46,"text":"τὴν ἀρχὴν ἐγὼ παραλαβὼν πᾶσι μὲν φιλανθρώπως ἐχρησάμην, μάλιστα δὲ τοῖς σοῖς πολίταις, ὧν ὑπὲρ δέκα μὲν μυριάδας αἰχμαλώτων δουλευόντων ἀπέλυσα τοῖς δεσπόταις αὐτῶν ἐκ τῶν ἐμῶν λύτρα καταβαλών."},{"number":47,"text":"τοὺς δὲ ἀκμάζοντας ταῖς ἡλικίαις εἰς τὸν στρατιωτικὸν κατάλογον κατέταξα, τινὰς δὲ τῶν περὶ ἡμᾶς καὶ τὴν τῆς αὐλῆς πίστιν εἶναι δυναμένων ταύτης ἠξίωκα, νομίζων ἡδὺ τῷ θεῷ τῆς ὑπὲρ ἐμοῦ προνοίας ἀνάθημα τοῦτο καὶ μέγιστον ἀναθήσειν."},{"number":48,"text":"βουλόμενος δὲ καὶ τούτοις χαρίζεσθαι καὶ πᾶσι τοῖς κατὰ τὴν οἰκουμένην Ἰουδαίοις τὸν νόμον ὑμῶν ἔγνων μεθερμηνεῦσαι, καὶ γράμμασιν Ἑλληνικοῖς ἐκ τῶν Ἑβραϊκῶν μεταγραφέντα κεῖσθαι ἐν τῇ ἐμῇ βιβλιοθήκῃ."},{"number":49,"text":"καλῶς οὖν ποιήσεις ἐπιλεξάμενος ἄνδρας ἀγαθοὺς ἓξ ἀφʼ ἑκάστης φυλῆς ἤδη πρεσβυτέρους, οἳ καὶ διὰ τὸν χρόνον ἐμπείρως ἔχουσι τῶν νόμων καὶ δυνήσονται τὴν ἑρμηνείαν αὐτῶν ἀκριβῆ ποιήσασθαι· νομίζω γὰρ τούτων ἐπιτελεσθέντων μεγίστην δόξαν ἡμῖν περιγενήσεσθαι."},{"number":50,"text":"ἀπέσταλκα δέ σοι περὶ τούτων διαλεξομένους Ἀνδρέαν τὸν ἀρχισωματοφύλακα καὶ Ἀρισταῖον ἐμοὶ τιμιωτάτους, διʼ ὧν καὶ ἀπαρχὰς ἀναθημάτων εἰς τὸ ἱερὸν καὶ θυσιῶν καὶ τῶν ἄλλων ἀπέσταλκα τάλαντα ἀργυρίου ἑκατόν. καὶ σὺ δʼ ἡμῖν ἐπιστέλλων περὶ ὧν ἂν θέλῃς ποιήσεις κεχαρισμένα."},{"number":51,"text":"Τῆς οὖν ἐπιστολῆς τοῦ βασιλέως κομισθείσης πρὸς τὸν Ἐλεάζαρον ἀντιγράφει πρὸς αὐτὴν ὡς ἐνῆν μάλιστα φιλοτίμως. ἀρχιερεὺς Ἐλεάζαρος βασιλεῖ Πτολεμαίῳ χαίρειν. ἐρρωμένων σοῦ τε καὶ τῆς βασιλίσσης Ἀρσινόης καὶ τῶν τέκνων καλῶς ἡμῖν ἔχει πάντα."},{"number":52,"text":"τὴν δʼ ἐπιστολὴν λαβόντες μεγάλως ἥσθημεν ἐπὶ τῇ προαιρέσει σου, καὶ συναθροίσαντες τὸ πλῆθος ἀνέγνωμεν αὐτὴν ἐμφανίζοντες αὐτῷ ἣν ἔχεις πρὸς τὸν θεὸν εὐσέβειαν."},{"number":53,"text":"ἐπεδείξαμεν δʼ αὐτῷ καὶ τὰς φιάλας ἃς ἔπεμψας χρυσᾶς εἴκοσι καὶ ἀργυρᾶς τριάκοντα καὶ κρατῆρας πέντε καὶ τράπεζαν εἰς ἀνάθεσιν, ἅ τε εἰς θυσίαν καὶ εἰς ἐπισκευὴν ὧν ἂν δέηται τὸ ἱερὸν τάλαντα ἑκατόν, ἅπερ ἐκόμισαν Ἀνδρέας καὶ Ἀρισταῖος οἱ τιμιώτατοί σου τῶν φίλων, ἄνδρες ἀγαθοὶ καὶ παιδείᾳ διαφέροντες καὶ τῆς σῆς ἀρετῆς ἄξιοι."},{"number":54,"text":"ἴσθι δʼ ἡμᾶς τὸ σοὶ συμφέρον, κἂν ᾖ τι παρὰ φύσιν, ὑπομενοῦντας· ἀμείβεσθαι γὰρ ἡμᾶς δεῖ τὰς σὰς εὐεργεσίας πολυμερῶς εἰς τοὺς ἡμετέρους πολίτας κατατεθείσας."},{"number":55,"text":"εὐθὺς οὖν ὑπὲρ σοῦ καὶ τῆς ἀδελφῆς σου καὶ τέκνων καὶ φίλων προσηγάγομεν θυσίας, καὶ τὸ πλῆθος εὐχὰς ἐποιήσατο γενέσθαι σοι τὰ κατὰ νοῦν καὶ φυλαχθῆναί σου τὴν βασιλείαν ἐν εἰρήνῃ, τήν τε τοῦ νόμου μεταγραφὴν ἐπὶ συμφέροντι τῷ σῷ λαβεῖν ὃ προαιρῇ τέλος."},{"number":56,"text":"ἐπελεξάμην δὲ καὶ πρεσβυτέρους ἄνδρας ἓξ ἀπὸ φυλῆς ἑκάστης, οὓς πεπόμφαμεν ἔχοντας τὸν νόμον. ἔσται δὲ τῆς σῆς εὐσεβείας καὶ δικαιοσύνης τὸ μεταγραφέντα τὸν νόμον εἰς ἡμᾶς ἀποπέμψαι μετʼ ἀσφαλείας τῶν κομιζόντων. ἔρρωσο."},{"number":57,"text":"Ταῦτα μὲν ὁ ἀρχιερεὺς ἀντέγραψεν. ἐμοὶ δʼ οὐκ ἀναγκαῖον ἔδοξεν εἶναι τὰ ὀνόματα τῶν ἑβδομήκοντα πρεσβυτέρων, οἳ τὸν νόμον ἐκόμιζον ὑπὸ Ἐλεαζάρου πεμφθέντες, δηλοῦν· ἦν γὰρ ταῦτα ὑπογεγραμμένα ἐν τῇ ἐπιστολῇ."},{"number":58,"text":"τὴν μέντοι γε τῶν ἀναθημάτων πολυτέλειαν καὶ κατασκευήν, ἣν ἀπέστειλεν ὁ βασιλεὺς τῷ θεῷ, οὐκ ἀνεπιτήδειον ἡγησάμην διελθεῖν, ὅπως ἅπασιν ἡ τοῦ βασιλέως περὶ τὸν θεὸν φιλοτιμία φανερὰ γένηται· ἄφθονον γὰρ τὴν εἰς ταῦτα δαπάνην χορηγῶν ὁ βασιλεὺς καὶ παρὼν ἀεὶ τοῖς τεχνίταις καὶ τὰ ἔργα ἐπιβλέπων οὐδὲν ἀμελῶς οὐδὲ ῥᾳθύμως εἴα γίγνεσθαι τῶν κατασκευασμάτων."},{"number":59,"text":"ὧν ἕκαστον οἷον ἦν τὴν πολυτέλειαν διηγήσομαι, τῆς μὲν ἱστορίας ἴσως οὐκ ἀπαιτούσης τὴν ἀπαγγελίαν, τὸ δὲ τοῦ βασιλέως φιλόκαλον καὶ μεγαλόφρον οὕτω συστήσειν τοῖς ἐντευξομένοις ὑπολαμβάνων."},{"number":60,"text":"Πρῶτον δὲ τὰ περὶ τῆς τραπέζης ἐκθήσομαι. εἶχεν μὲν οὖν διʼ ἐννοίας ὁ βασιλεὺς ὑπερμεγεθέστατον τοῖς μέτροις ἀπεργάσασθαι τὸ κατασκεύασμα, προσέταξε δὲ μαθεῖν τὸ μέγεθος τῆς ἀνακειμένης ἐν τοῖς Ἱεροσολύμοις τραπέζης πόσον τέ ἐστιν καὶ εἰ δύναται τούτου μεῖζον κατασκευασθῆναι."},{"number":61,"text":"μαθὼν δὲ καὶ τὴν οὖσαν ἡλίκη τις ἦν, καὶ ὅτι αὐτῆς οὐδὲν κωλύει μείζονα γενέσθαι, φήσας καὶ πενταπλασίονα τῆς ὑπαρχούσης τῷ μεγέθει βούλεσθαι κατασκευάσαι, φοβεῖσθαι δέ, μὴ πρὸς τὰς λειτουργίας ἄχρηστος διὰ τὴν ὑπερβολὴν τοῦ μεγέθους γένηται· βούλεσθαι γὰρ οὐκ ἀνακεῖσθαι μόνον εἰς θέαν τἀναθήματα, ἀλλὰ καὶ πρὸς τὰς λειτουργίας εὔχρηστα·"},{"number":62,"text":"καὶ διὰ τοῦτο λογισάμενος σύμμετρον κατεσκευάσθαι τὴν προτέραν τράπεζαν, ἀλλʼ οὐ διὰ σπάνιν χρυσοῦ, τῷ μεγέθει μὲν οὐκ ἔγνω τὴν προϋπάρχουσαν ὑπερβαλεῖν, τῇ δὲ ποικιλίᾳ καὶ τῷ κάλλει τῆς ὕλης ἀξιολογωτέραν κατασκευάσαι."},{"number":63,"text":"δεινὸς δὲ ὢν συνιδεῖν πραγμάτων παντοδαπῶν φύσιν καὶ λαβεῖν ἐπίνοιαν ἔργων καινῶν καὶ παραδόξων καὶ ὅσα ἦν ἄγραφα τὴν εὕρεσιν αὐτὸς παρέχων διὰ τὴν σύνεσιν καὶ ὑποδεικνὺς τοῖς τεχνίταις, ἐκέλευσεν ταῦτα κατασκευάζεσθαι καὶ τὰ ἀναγεγραμμένα πρὸς τὴν ἀκρίβειαν αὐτῶν ἀποβλέποντας ὁμοίως ἐπιτελεῖν."},{"number":64,"text":"Ὑποστησάμενοι τοίνυν ποιήσασθαι τὴν τράπεζαν δύο μὲν καὶ ἡμίσους πηχῶν τὸ μῆκος, ἑνὸς δὲ τὸ εὖρος, τὸ δʼ ὕψος ἑνὸς καὶ ἡμίσους, κατεσκεύαζον ἐκ χρυσοῦ τὴν ὅλην τοῦ ἔργου καταβολὴν ποιούμενοι. τὴν μὲν οὖν στεφάνην παλαιστιαίαν εἰργάσαντο, τὰ δὲ κυμάτια στρεπτὰ τὴν ἀναγλυφὴν ἔχοντα σχοινοειδῆ τῇ τορείᾳ θαυμαστῶς ἐκ τῶν τριῶν μερῶν μεμιμημένην."},{"number":65,"text":"τριγώνων γὰρ ὄντων αὐτῶν ἑκάστη γωνία τὴν αὐτὴν τῆς ἐκτυπώσεως εἶχεν διάθεσιν, ὡς στρεφομένων αὐτῶν μίαν καὶ μὴ διάφορον τὴν ἰδέαν αὐτοῖς συμπεριφέρεσθαι. τῆς δὲ στεφάνης τὸ μὲν ὑπὸ τὴν τράπεζαν ἐκκεκλιμένον ὡραίαν εἶχεν τὴν ἀποτύπωσιν, τὸ δʼ ἔξωθεν περιηγμένον ἔτι μᾶλλον τῷ κάλλει τῆς ἐργασίας ἦν ἐκπεπονημένον, ὡς ὑπʼ ὄψιν καὶ θεωρίαν ἐρχόμενον."},{"number":66,"text":"διὸ καὶ τὴν μὲν ὑπεροχὴν ἀμφοτέρων τῶν μερῶν ὀξεῖαν συνέβαινε γίγνεσθαι, καὶ μηδεμίαν γωνίαν τριῶν οὐσῶν, ὡς προειρήκαμεν, περὶ τὴν μεταγωγὴν τῆς τραπέζης ἐλάσσονα βλέπεσθαι. ἐνδιέκειντο δὲ ταῖς σχοινίσιν τῆς τορείας λίθοι πολυτελεῖς παράλληλοι περόναις χρυσαῖς διὰ τρημάτων κατειλημμένοι."},{"number":67,"text":"τὰ δʼ ἐκ πλαγίου τῆς στεφάνης καὶ πρὸς ὄψιν ἀνατείνοντα ὠῶν ἐκ λίθου καλλίστου πεποιημένων θέσει κατακεκόσμητο ῥάβδοις τὴν ἀναγλυφὴν ἐοικότων πυκναῖς, αἳ περὶ τὸν κύκλον τῆς τραπέζης εἴληντο."},{"number":68,"text":"ὑπὸ δὲ τὴν τῶν ὠῶν διατύπωσιν στέφανον περιήγαγον οἱ τεχνῖται παντοίου καρποῦ φύσιν ἐντετορευμένον, ὡς ἀποκρέμασθαί τε βότρυς καὶ στάχυας ἀναστῆναι καὶ ῥόας ἀποκεκλεῖσθαι. τοὺς δὲ λίθους εἰς πᾶν γένος τῶν προειρημένων καρπῶν, ὡς ἑκάστου τὴν οἰκείαν ἐντετυπῶσθαι χρόαν, ἐξεργασάμενοι συνέδησαν τῷ χρυσῷ περὶ ὅλην τὴν τράπεζαν."},{"number":69,"text":"ὑπὸ δὲ τὸν στέφανον ὁμοίως ἡ τῶν ὠῶν διάθεσις πεποίητο καὶ ἡ τῆς ῥαβδώσεως ἀναγλυφή, τῆς τραπέζης ἐπʼ ἀμφότερον μέρος ἔχειν τὴν αὐτὴν τῆς ποικιλίας τῶν ἔργων καὶ γλαφυρότητος θέαν κατεσκευασμένης, ὡς καὶ τὴν τῶν ἄλλων κυμάτων θέσιν καὶ τὴν τῆς στεφάνης μηδὲ τῆς τραπέζης ἐφʼ ἕτερον μέρος ἐναλλαττομένης γίγνεσθαι διάφορον, τὴν δʼ αὐτὴν ἄχρι καὶ τῶν ποδῶν ὄψιν τῆς ἐπιτεχνήσεως διατετάσθαι."},{"number":70,"text":"ἔλασμα γὰρ χρυσοῦ τὸ πλάτος τεσσάρων δακτύλων ποιήσαντες καθʼ ὅλου τοῦ τῆς τραπέζης πλάτους εἰς τοῦτο τοὺς πόδας αὐτῆς ἐνέθεσαν, ἔπειτα περόναις καὶ κατακλεῖσιν αὐτοὺς ἐνέσφιγγον τῇ τραπέζῃ κατὰ τὴν στεφάνην, ἵνα τὴν θέαν τῆς καινουργίας καὶ πολυτελείας, ἐφʼ ᾧ τις ἂν στήσῃ τὴν τράπεζαν μέρει, παρέχωσι τὴν αὐτήν."},{"number":71,"text":"ἐπὶ δὲ τῆς τραπέζης μαίανδρον ἐξέγλυψαν λίθους αὐτῷ κατὰ μέσον ἀξιολόγους ὥσπερ ἀστέρας ποικίλης ἰδέας ἐνθέντες, τόν τε ἄνθρακα καὶ τὸν σμάραγδον ἥδιστον προσαυγάζοντας αὐτῶν ἑκάτερον τοῖς ὁρῶσιν, τῶν τε ἄλλων γενῶν ὅσοι περισπούδαστοι καὶ ζηλωτοὶ πᾶσιν διὰ τὴν πολυτέλειαν τῆς φύσεως ὑπάρχουσιν."},{"number":72,"text":"μετὰ δὲ τὸν μαίανδρον πλέγμα τι σχοινοειδὲς περιῆκτο ῥόμβῳ τὴν κατὰ μέσον ὄψιν ἐμφερές, ἐφʼ οὗ κρύσταλλός τε λίθος καὶ ἤλεκτρον ἐντετύπωτο τῇ παραλλήλῳ τῆς ἰδέας γειτνιάσει ψυχαγωγίαν θαυμαστὴν παρέχον τοῖς βλέπουσιν."},{"number":73,"text":"τῶν δὲ ποδῶν ἦσαν αἱ κεφαλίδες εἰς κρίνα μεμιμημέναι τὰς ἐκφύσεις τῶν πετάλων ὑπὸ τὴν τράπεζαν ἀνακλωμένων, εἰς ὀρθὸν δὲ τὴν βλάστησιν ἔνδοθεν παρεχόντων ὁρᾶν."},{"number":74,"text":"ἡ δὲ βάσις αὐτοῖς ἦν ἐξ ἄνθρακος λίθου παλαιστιαία πεποιημένη σχῆμα κρηπῖδος ἀποτελοῦσα, τὸ δὲ πλάτος ὀκτὼ δακτύλων ἔχουσα, καθʼ οὗ τὸ πᾶν ἔλασμα τῶν ποδῶν ἐρήρειστο."},{"number":75,"text":"ἀνέγλυψαν δὲ λεπτομερεῖ καὶ φιλοπονωτάτῃ τορείᾳ τῶν ποδῶν ἕκαστον, κισσὸν αὐτοῖς καὶ κλήματα ἀμπέλων σὺν καὶ βότρυσιν ἐκφύσαντες, ὡς εἰκάσαι μηδὲν ἀποδεῖν τῆς ἀληθείας· καὶ γὰρ πρὸς τὸ πνεῦμα διὰ λεπτότητα καὶ τὴν ἐπʼ ἄκρον αὐτῶν ἔκτασιν κινούμενα φαντασίαν τῶν κατὰ φύσιν μᾶλλον ἢ τέχνης μιμημάτων παρεῖχεν."},{"number":76,"text":"ἐκαινούργησαν δὲ ὥστε τρίπτυχον οἱονεὶ τὸ σχῆμα τῆς ὅλης κατασκευάσαι τραπέζης τῆς ἁρμονίας πρὸς ἄλληλα τῶν μερῶν οὕτω συνδεδεμένης, ὡς ἀόρατον εἶναι καὶ μηδʼ ἐπινοεῖσθαι τὰς συμβολάς. ἥμισυ δὲ πήχεως οὐκ ἔλασσον τῇ τραπέζῃ τὸ πάχος συνέβαινεν εἶναι."},{"number":77,"text":"τὸ μὲν οὖν ἀνάθημα τοῦτο κατὰ πολλὴν τοῦ βασιλέως φιλοτιμίαν τοιοῦτο τῇ τε πολυτελείᾳ τῆς ὕλης καὶ τῇ ποικιλίᾳ τῆς καλλονῆς καὶ τῇ μιμήσει τῇ κατὰ τὴν τορείαν τῶν τεχνιτῶν συνετελέσθη, σπουδάσαντος εἰ καὶ μὴ τῷ μεγέθει τῆς προανακειμένης τῷ θεῷ τραπέζης ἔμελλεν ἔσεσθαι διάφορος, τῇ μέντοι γε τέχνῃ καὶ τῇ καινουργίᾳ καὶ τῇ λαμπρότητι τῆς κατασκευῆς πολὺ κρείττονα καὶ περίβλεπτον ἀπεργάσασθαι."},{"number":78,"text":"Τῶν δὲ κρατήρων χρύσεοι μὲν ἦσαν δύο, φολιδωτὴν δʼ εἶχον ἀπὸ τῆς βάσεως μέχρι τοῦ διαζώματος τὴν τορείαν λίθων ταῖς σπείραις ποικίλων ἐνδεδεμένων."},{"number":79,"text":"εἶτα ἐπʼ αὐτῇ μαίανδρος πηχυαῖος τὸ ὕψος ἐξείργαστο κατὰ σύνθεσιν λίθων παντοίων τὴν ἰδέαν, κατʼ αὐτοῦ δὲ ῥάβδωσις ἀναγέγλυπτο, καθʼ ἧς πλέγμα ῥομβωτὸν δικτύοις ἐμφερὲς ἕως τοῦ χείλους ἀνείλκυστο·"},{"number":80,"text":"τὰ δὲ μέσα λίθων ἀσπίδια τετραδακτύλων ἀνεπλήρου τὸ κάλλος. περιεστέφετο δὲ τὰ χείλη τοῦ κρατῆρος κρίνων σμίλαξι καὶ ἀνθεμίσι καὶ βοτρύων σχοινίαις εἰς κύκλον περιηγμέναις."},{"number":81,"text":"τοὺς μὲν οὖν χρυσέους κρατῆρας δύο χωροῦντας ἑκάτερον ἀμφορέας τοῦτον κατεσκεύασαν τὸν τρόπον, οἱ δʼ ἀργύρεοι τῶν ἐσόπτρων τὴν λαμπρότητα πολὺ διαυγέστεροι γεγόνεισαν, ὡς τρανοτέρας διὰ τούτων τὰς τῶν προσφερομένων ὄψεις ὁρᾶσθαι."},{"number":82,"text":"προσκατεσκεύασε δὲ τούτοις ὁ βασιλεὺς καὶ φιάλας τριάκοντα, ὧν ὅσα χρυσὸς ἦν ἀλλὰ μὴ λίθῳ πολυτελεῖ διείληπτο, σμίλαξι κισσοῦ καὶ πετάλοις ἀμπέλων ἐσκίαστο φιλοτέχνως ἐντετορευμένων."},{"number":83,"text":"ταῦτα δʼ ἐγίγνετο μὲν καὶ διὰ τὴν ἐμπειρίαν τῶν ἐργαζομένων θαυμασίων ὄντων περὶ τὴν τέχνην, πολὺ δὲ μᾶλλον ὑπὸ τῆς τοῦ βασιλέως σπουδῆς καὶ φιλοτιμίας διαφερόντως ἀπηρτίζετο·"},{"number":84,"text":"οὐ γὰρ τῆς χορηγίας τὸ ἄφθονον καὶ μεγαλόψυχον τοῖς τεχνίταις παρεῖχεν μόνον, ἀλλὰ καὶ τὸ χρηματίζειν τοῖς δημοσίοις πράγμασιν ἀπειρηκὼς αὐτὸς τοῖς κατασκευάζουσι παρῆν καὶ τὴν ὅλην ἐργασίαν ἐπέβλεπεν. αἴτιον δʼ ἦν τοῦτο τῆς τῶν τεχνιτῶν ἐπιμελείας, οἳ πρὸς τὸν βασιλέα καὶ τὴν τούτου σπουδὴν ἀποβλέποντες φιλοπονώτερον τοῖς ἔργοις προσελιπάρουν."},{"number":85,"text":"Ταῦτα μὲν τὰ πεμφθέντα εἰς Ἱεροσόλυμα ὑπὸ Πτολεμαίου ἀναθήματα. ὁ δʼ ἀρχιερεὺς Ἐλεάζαρος ἀναθεὶς αὐτὰ καὶ τιμήσας τοὺς κομίσαντας καὶ δῶρα τῷ βασιλεῖ δοὺς κομίζειν ἀπέλυσε πρὸς τὸν βασιλέα."},{"number":86,"text":"παραγενομένων δʼ εἰς τὴν Ἀλεξάνδρειαν ἀκούσας Πτολεμαῖος τὴν παρουσίαν αὐτῶν καὶ τοὺς ἑβδομήκοντα τῶν πρεσβυτέρων ἐληλυθότας, εὐθὺς μεταπέμπεται τὸν Ἀνδρέαν καὶ τὸν Ἀρισταῖον τοὺς πρέσβεις. οἱ δʼ ἀφικόμενοι τάς τε ἐπιστολάς, ἃς ἐκόμιζον αὐτῷ παρὰ τοῦ ἀρχιερέως, ἀπέδοσαν καὶ ὅσα φράζειν ἀπὸ λόγων ὑπέθετο ταῦτα ἐδήλωσαν."},{"number":87,"text":"σπεύδων δʼ ἐντυχεῖν τοῖς ἀπὸ τῶν Ἱεροσολύμων πρεσβύταις ἥκουσιν ἐπὶ τὴν ἑρμηνείαν τῶν νόμων, τοὺς μὲν ἄλλους οὓς χρειῶν ἕνεκα παρεῖναι συνέβαινεν ἐκέλευσεν ἀπολῦσαι, παράδοξον τοῦτο ποιῶν καὶ παρὰ τὸ ἔθος·"},{"number":88,"text":"οἱ μὲν γὰρ ὑπὸ τοιούτων αἰτιῶν ἀχθέντες διὰ πέμπτης ἡμέρας αὐτῷ προσῄεσαν, οἱ δὲ πρεσβεύοντες διὰ μηνός· τότε τοίνυν ἀπολύσας ἐκείνους τοὺς πεμφθέντας ὑπὸ Ἐλεαζάρου περιέμενεν."},{"number":89,"text":"ὡς δὲ παρῆλθον μετὰ καὶ τῶν δώρων οἱ γέροντες, ἃ τῷ βασιλεῖ κομίσαι ὁ ἀρχιερεὺς αὐτοῖς ἔδωκεν, καὶ τῶν διφθερῶν, αἷς ἐγγεγραμμένους εἶχον τοὺς νόμους χρυσοῖς γράμμασιν, ἐπηρώτησεν αὐτοὺς περὶ τῶν βιβλίων."},{"number":90,"text":"ὡς δʼ ἀποκαλύψαντες τῶν ἐνειλημάτων ἐπέδειξαν αὐτῷ, θαυμάσας ὁ βασιλεὺς τῆς ἰσχνότητος τοὺς ὑμένας καὶ τῆς συμβολῆς τὸ ἀνεπίγνωστον, οὕτως γὰρ ἥρμοστο, καὶ τοῦτο ποιήσας χρόνῳ πλείονι χάριν ἔχειν εἶπεν αὐτοῖς τε ἐλθοῦσιν καὶ μείζονα τῷ πέμψαντι, πρὸ δὲ πάντων τῷ θεῷ, οὗ τοὺς νόμους εἶναι συμβέβηκεν."},{"number":91,"text":"ἐκβοησάντων δʼ ὑφʼ ἓν καὶ τῶν πρεσβυτέρων καὶ τῶν συμπαρόντων γίγνεσθαι τὰ ἀγαθὰ τῷ βασιλεῖ διʼ ὑπερβολὴν ἡδονῆς εἰς δάκρυα προύπεσεν, φύσει τῆς μεγάλης χαρᾶς πασχούσης καὶ τὰ τῶν λυπηρῶν σύμβολα."},{"number":92,"text":"κελεύσας δὲ τὰ βιβλία δοῦναι τοῖς ἐπὶ τῆς τάξεως τότε τοὺς ἄνδρας ἠσπάσατο, δίκαιον εἰπὼν εἶναι πρῶτον περὶ ὧν αὐτοὺς μετεπέμψατο ποιησάμενον τοὺς λόγους ἔπειτα κἀκείνους προσειπεῖν. τὴν μέντοι γε ἡμέραν, καθʼ ἣν ἦλθον πρὸς αὐτόν, ἐπιφανῆ ποιήσειν καὶ κατὰ πᾶν ἔτος ἐπίσημον εἰς ὅλον τὸν τῆς ζωῆς χρόνον ἐπηγγέλλετο·"},{"number":93,"text":"ἔτυχεν γὰρ ἡ αὐτὴ εἶναι τῆς παρουσίας αὐτοῖς καὶ τῆς νίκης, ἣν Ἀντίγονον ναυμαχῶν ἐνίκησεν· συνεστιαθῆναί τε ἐκέλευσεν αὐτῷ καὶ καταλύσεις προσέταξεν αὐτοῖς δοθῆναι τὰς καλλίστας πρὸς τῇ ἄκρᾳ."},{"number":94,"text":"Ὁ δὲ ἐπὶ τῆς τῶν ξένων ἀποδοχῆς τεταγμένος Νικάνωρ Δωρόθεον καλέσας, ὃς εἶχεν τὴν περὶ τούτων πρόνοιαν, ἐκέλευεν ἑτοιμάζειν ἑκάστῳ τὰ δέοντα πρὸς τὴν δίαιταν. διετέτακτο δὲ τοῦτον ὑπὸ τοῦ βασιλέως τὸν τρόπον·"},{"number":95,"text":"κατὰ γὰρ πόλιν ἑκάστην, ὅσαι τοῖς αὐτοῖς χρῶνται περὶ τὴν δίαιταν, ἦν τούτων ἐπιμελόμενος καὶ κατὰ τὸ τῶν ἀφικνουμένων πρὸς αὐτὸν ἔθος πάντʼ αὐτοῖς παρεσκευάζετο, ἵνα τῷ συνήθει τρόπῳ τῆς διαίτης εὐωχούμενοι μᾶλλον ἥδωνται καὶ πρὸς μηδὲν ὡς ἀλλοτρίως ἔχοντες δυσχεραίνωσιν. ὃ δὴ καὶ περὶ τούτους ἐγένετο Δωροθέου διὰ τὴν περὶ τὸν βίον ἀκρίβειαν ἐπὶ τούτοις καθεστῶτος."},{"number":96,"text":"συνέστρωσε δὲ πάντα διʼ αὐτοῦ τὰ πρὸς τὰς τοιαύτας ὑποδοχὰς καὶ διμερῆ τὴν κλισίαν ἐποίησεν οὑτωσὶ προστάξαντος τοῦ βασιλέως· τοὺς μὲν γὰρ ἡμίσεις ἐκέλευσεν ἀνὰ χεῖρα κατακλιθῆναι, τοὺς δὲ λοιποὺς μετὰ τὴν αὐτοῦ κλισίαν, οὐδὲν ἀπολιπὼν τῆς εἰς τοὺς ἄνδρας τιμῆς."},{"number":97,"text":"ἐπεὶ δʼ οὕτως κατεκλίθησαν ἐκέλευσε τὸν Δωρόθεον, οἷς ἔθεσι χρώμενοι διατελοῦσιν πάντες οἱ ἀπὸ τῆς Ἰουδαίας πρὸς αὐτὸν ἀφιγμένοι κατὰ ταῦτα ὑπηρετεῖν. διὸ καὶ τοὺς ἱεροκήρυκας καὶ θύτας καὶ τοὺς ἄλλους, οἳ τὰς κατευχὰς ἐποιοῦντο, παρῃτήσατο, τῶν δὲ παραγενομένων ἕνα Ἐλισαῖον ὄνομα ὄντα ἱερέα παρεκάλεσεν ὁ βασιλεὺς ποιήσασθαι κατευχάς."},{"number":98,"text":"ὁ δὲ στὰς εἰς μέσον ηὔχετο τῷ βασιλεῖ τὰ ἀγαθὰ καὶ τοῖς ἀρχομένοις ὑπʼ αὐτοῦ, εἶτα κρότος ἐξ ἁπάντων μετὰ χαρᾶς καὶ βοῆς ἤρθη καὶ παυσάμενοι πρὸς εὐωχίαν καὶ τὴν ἀπόλαυσιν τῶν παρεσκευασμένων ἐτράπησαν."},{"number":99,"text":"διαλιπὼν δʼ ὁ βασιλεὺς ἐφʼ ὅσον ἔδοξεν ἀποχρῶντα καιρὸν εἶναι φιλοσοφεῖν ἤρξατο καὶ ἕκαστον αὐτῶν λόγους ἐπηρώτα φυσικούς, καὶ πρὸς τὴν τῶν ζητουμένων θεωρίαν ἀκριβῶς ἐκείνων περὶ παντὸς οὑτινοσοῦν λέγειν αὐτοῖς προβληθείη διασαφούντων, ἡδόμενος τούτοις ἐφʼ ἡμέρας δώδεκα τὸ συμπόσιον ἐποιήσατο,"},{"number":100,"text":"ὡς τῷ βουλομένῳ τὰ κατὰ μέρος γνῶναι τῶν ἐν τῷ συμποσίῳ ζητηθέντων εἶναι μαθεῖν ἀναγνόντι τὸ Ἀρισταίου βιβλίον, ὃ συνέγραψεν διὰ ταῦτα."},{"number":101,"text":"Θαυμάζοντος δʼ αὐτοὺς οὐ μόνον τοῦ βασιλέως, ἀλλὰ καὶ Μενεδήμου τοῦ φιλοσόφου προνοίᾳ διοικεῖσθαι πάντα φήσαντος καὶ διὰ τοῦτʼ εἰκὸς καὶ τοῦ λόγου δύναμιν καὶ κάλλος εὑρῆσθαι, παύονται μὲν περὶ τούτων ἐπιζητοῦντες."},{"number":102,"text":"γεγενῆσθαι δʼ αὐτῷ τὰ μέγιστα τῶν ἀγαθῶν ὁ βασιλεὺς ἔλεγεν ἤδη παρόντων αὐτῶν· ὠφελῆσθαι γὰρ παρʼ αὐτῶν μεμαθηκότα, πῶς δεῖ βασιλεύειν· κελεύει τε αὐτοῖς ἀνὰ τρία δοθῆναι τάλαντα καὶ τοὺς ἀποκαταστήσοντας ἐπὶ τὴν κατάλυσιν."},{"number":103,"text":"διελθουσῶν δὲ τριῶν ἡμερῶν παραλαβὼν αὐτοὺς ὁ Δημήτριος καὶ διελθὼν τὸ ἑπταστάδιον χῶμα τῆς θαλάσσης πρὸς τὴν νῆσον καὶ διαβὰς πρὸς τὴν γέφυραν, προελθὼν ἐπὶ τὰ βόρεια μέρη συνέδριον ἐποιήσατο ἐν τῷ παρὰ τὴν ᾐόνα κατεσκευασμένῳ οἴκῳ πρὸς διάσκεψιν πραγμάτων ἠρεμίας καλῶς ἔχοντι."},{"number":104,"text":"ἀγαγὼν οὖν αὐτοὺς ἐκεῖ παρεκάλει πάντων, ὧν ἂν δεηθεῖεν εἰς τὴν ἑρμηνείαν τοῦ νόμου, παρόντων ἀκωλύτως ἐπιτελεῖν τὸ ἔργον. οἱ δʼ ὡς ἔνι μάλιστα φιλοτίμως καὶ φιλοπόνως ἀκριβῆ τὴν ἑρμηνείαν ποιούμενοι μέχρι μὲν ὥρας ἐνάτης πρὸς τούτῳ διετέλουν ὄντες,"},{"number":105,"text":"ἔπειτʼ ἐπὶ τὴν τοῦ σώματος ἀπηλλάττοντο θεραπείαν ἀφθόνως αὐτοῖς τῶν πρὸς τὴν δίαιταν χορηγουμένων καὶ προσέτι τοῦ Δωροθέου πολλὰ καὶ τῶν παρασκευαζομένων τῷ βασιλεῖ, προσέταξε γάρ, αὐτοῖς παρέχοντος."},{"number":106,"text":"πρωῒ δὲ πρὸς τὴν αὐλὴν παραγινόμενοι καὶ τὸν Πτολεμαῖον ἀσπαζόμενοι πάλιν ἐπὶ τὸν αὐτὸν ἀπῄεσαν τόπον καὶ τῇ θαλάσσῃ τὰς χεῖρας ἀπονιπτόμενοι καὶ καθαίροντες αὑτοὺς οὕτως ἐπὶ τὴν τῶν νόμων ἑρμηνείαν ἐτρέποντο."},{"number":107,"text":"Μεταγραφέντος δὲ τοῦ νόμου καὶ τοῦ κατὰ τὴν ἑρμηνείαν ἔργου τέλος ἐν ἡμέραις ἑβδομήκοντα καὶ δυσὶν λαβόντος, συναγαγὼν ὁ Δημήτριος τοὺς Ἰουδαίους ἅπαντας εἰς τὸν τόπον, ἔνθα καὶ μετεβλήθησαν οἱ νόμοι, παρόντων καὶ τῶν ἑρμηνέων ἀνέγνω τούτους."},{"number":108,"text":"τὸ δὲ πλῆθος ἀπεδέξατο μὲν καὶ τοὺς διασαφήσαντας πρεσβυτέρους τὸν νόμον, ἐπῄνεσεν δὲ καὶ τὸν Δημήτριον τῆς ἐπινοίας ὡς μεγάλων ἀγαθῶν αὐτοῖς εὑρετὴν γεγενημένον, παρεκάλεσάν τε δοῦναι καὶ τοῖς ἡγουμένοις αὐτῶν ἀναγνῶναι τὸν νόμον, ἠξίωσάν τε πάντες ὅ τε ἱερεὺς καὶ τῶν ἑρμηνέων οἱ πρεσβύτεροι καὶ τοῦ πολιτεύματος οἱ προεστηκότες, ἐπεὶ καλῶς τὰ τῆς ἑρμηνείας ἀπήρτισται, καὶ διαμεῖναι ταῦθʼ, ὡς ἔχοι, καὶ μὴ μετακινεῖν αὐτά."},{"number":109,"text":"ἁπάντων δʼ ἐπαινεσάντων τὴν γνώμην ἐκέλευσαν, εἴ τις ἢ περισσόν τι προσγεγραμμένον ὁρᾷ τῷ νόμῳ ἢ λεῖπον, πάλιν ἐπισκοποῦντα τοῦτο καὶ ποιοῦντα φανερὸν διορθοῦν, σωφρόνως τοῦτο πράττοντες, ἵνα τὸ κριθὲν ἅπαξ ἔχειν καλῶς εἰς ἀεὶ διαμένῃ."},{"number":110,"text":"Ἐχάρη μὲν οὖν ὁ βασιλεὺς καὶ ἐπὶ τούτῳ τὴν αὐτοῦ προαίρεσιν εἴς τι χρήσιμον ὁρῶν τετελειωμένην, μάλιστα ὡς δὲ τῶν νόμων ἀναγνωσθέντων αὐτῷ καὶ τὴν διάνοιαν καὶ τὴν σοφίαν ἐξεπλάγη τοῦ νομοθέτου καὶ πρὸς τὸν Δημήτριον ἤρξατο ποιεῖσθαι λόγους, πῶς οὕτως θαυμαστῆς οὔσης τῆς νομοθεσίας οὐδεὶς οὔτε τῶν ἱστορικῶν αὐτῆς οὔτε τῶν ποιητῶν ἐπεμνήσθη."},{"number":111,"text":"ὁ δὲ Δημήτριος μηδένα τολμῆσαι τῆς τῶν νόμων τούτων ἀναγραφῆς ἅψασθαι διὰ τὸ θείαν αὐτὴν εἶναι καὶ σεμνὴν ἔφασκεν, καὶ ὅτι βλαβεῖεν ἤδη τινὲς τούτοις ἐγχειρήσαντες ὑπὸ τοῦ θεοῦ,"},{"number":112,"text":"δηλῶν ὡς Θεόπομπός τε βουληθεὶς ἱστορῆσαί τι περὶ τούτων ἐταράχθη τὴν διάνοιαν πλείοσιν ἢ τριάκοντα ἡμέραις καὶ παρὰ τὰς ἀνέσεις ἐξιλάσκετο τὸν θεόν, ἐντεῦθεν αὐτῷ γενέσθαι τὴν παραφροσύνην ὑπονοῶν· οὐ μὴν ἀλλὰ καὶ ὄναρ εἶδεν ὅτι τοῦτʼ αὐτῷ συμβαίη περιεργαζομένῳ τὰ θεῖα καὶ ταῦτʼ ἐκφέρειν εἰς κοινοὺς ἀνθρώπους θελήσαντι·"},{"number":113,"text":"καὶ ἀποσχόμενος κατέστη τὴν διάνοιαν. ἐδήλου δὲ καὶ περὶ Θεοδέκτου τοῦ τῶν τραγῳδιῶν ποιητοῦ ἀναφέρεσθαι, ὅτι βουληθεὶς ἔν τινι δράματι τῶν ἐν τῇ ἱερᾷ βύβλῳ γεγραμμένων μνησθῆναι τὰς ὄψεις γλαυκωθείη καὶ συνιδὼν τὴν αἰτίαν ἀπαλλαγείη τοῦ πάθους ἐξευμενισάμενος τὸν θεόν."},{"number":114,"text":"Παραλαβὼν δʼ ὁ βασιλεὺς ταῦτα παρὰ τοῦ Δημητρίου, καθὼς προείρηται, προσκυνήσας αὐτοῖς ἐκέλευσε πολλὴν ποιεῖσθαι τῶν βιβλίων τὴν ἐπιμέλειαν, ἵνα διαμείνῃ ταῦτα καθαρῶς, τούς τε ἑρμηνεύσαντας παρεκάλεσεν συνεχῶς πρὸς αὐτὸν ἐκ τῆς Ἰουδαίας παραγίγνεσθαι·"},{"number":115,"text":"τοῦτο γὰρ αὐτοῖς καὶ πρὸς τιμὴν τὴν παρʼ αὐτοῦ καὶ πρὸς τὰς ἀπὸ τῶν δώρων ὠφελείας λυσιτελήσειν· νῦν μὲν γὰρ εἶναι δίκαιον αὐτοὺς ἐκπέμπειν ἔλεγεν, ἑκουσίως δὲ πρὸς αὐτὸν ἐλθόντας τεύξεσθαι πάντων, ὧν ἥ τε αὐτῶν ἐστιν σοφία δικαία τυχεῖν καὶ ἡ ἐκείνου μεγαλοφροσύνη παρασχεῖν ἱκανή."},{"number":116,"text":"τότε μὲν οὖν ἐξέπεμψεν αὐτοὺς δοὺς ἑκάστῳ στολὰς ἀρίστας τρεῖς καὶ χρυσοῦ τάλαντα δύο καὶ κυλίκιον ταλάντου καὶ τὴν τοῦ συμποσίου στρωμνήν."},{"number":117,"text":"καὶ ταῦτα μὲν ἐκείνοις ἔχειν ἐδωρήσατο. τῷ δʼ ἀρχιερεῖ Ἐλεαζάρῳ διʼ αὐτῶν ἔπεμψεν κλίνας ἀργυρόποδας δέκα καὶ τὴν ἀκόλουθον αὐτῶν ἐπισκευὴν καὶ κυλίκιον ταλάντων τριάκοντα, πρὸς τούτοις δὲ καὶ στολὰς δέκα καὶ πορφύραν καὶ στέφανον διαπρεπῆ καὶ βυσσίνης ὀθόνης ἱστοὺς ἑκατόν, ἔτι γε μὴν φιάλας καὶ τρύβλια καὶ σπονδεῖα καὶ κρατῆρας χρυσοῦς πρὸς ἀνάθεσιν δύο."},{"number":118,"text":"παρεκάλεσεν δʼ αὐτὸν καὶ διὰ τῶν ἐπιστολῶν, ὅπως εἰ τῶν ἀνδρῶν τούτων θελήσειάν τινες πρὸς αὐτὸν ἐλθεῖν ἐπιτρέψῃ, περὶ πολλοῦ ποιούμενος τὴν μετὰ τῶν ἐν παιδείᾳ τυγχανόντων συνουσίαν καὶ τὸν πλοῦτον εἰς τοὺς τοιούτους ἡδέως ἔχων κατατίθεσθαι. καὶ τὰ μὲν εἰς δόξαν καὶ τιμὴν Ἰουδαίοις τοιαῦτα παρὰ Πτολεμαίου τοῦ Φιλαδέλφου συνέβη γενέσθαι."},{"number":119,"text":"Ἔτυχον δὲ καὶ τῆς παρὰ τῶν βασιλέων τῆς Ἀσίας τιμῆς, ἐπειδὴ συνεστράτευσαν αὐτοῖς· καὶ γὰρ Σέλευκος ὁ Νικάτωρ ἐν αἷς ἔκτισεν πόλεσιν ἐν τῇ Ἀσίᾳ καὶ τῇ κάτω Συρίᾳ καὶ ἐν αὐτῇ τῇ μητροπόλει Ἀντιοχείᾳ πολιτείας αὐτοὺς ἠξίωσεν καὶ τοῖς ἐνοικισθεῖσιν ἰσοτίμους ἀπέφηνεν Μακεδόσιν καὶ Ἕλλησιν, ὡς τὴν πολιτείαν ταύτην ἔτι καὶ νῦν διαμένειν·"}],"3":[{"number":120,"text":"τεκμήριον δὲ τοῦτο· τοὺς Ἰουδαίους μὴ βουλομένους ἀλλοφύλῳ ἐλαίῳ χρῆσθαι λαμβάνειν ὡρισμένον τι παρὰ τῶν γυμνασιάρχων εἰς ἐλαίου τιμὴν ἀργύριον ἐκέλευσεν. ὃ τοῦ δήμου τῶν Ἀντιοχέων ἐν τῷ νῦν πολέμῳ λῦσαι προαιρουμένου Μουκιανὸς ἡγεμὼν ὢν τότε τῆς Συρίας ἐτήρησεν,"},{"number":121,"text":"καὶ μετὰ ταῦτα κρατήσαντος Οὐεσπασιανοῦ καὶ Τίτου τοῦ υἱοῦ αὐτοῦ τῆς οἰκουμένης δεηθέντες οἱ Ἀλεξανδρεῖς καὶ Ἀντιοχεῖς, ἵνα τὰ δίκαια τὰ τῆς πολιτείας μηκέτι μένῃ τοῖς Ἰουδαίοις, οὐκ ἐπέτυχον."},{"number":122,"text":"ἐξ οὗ τις ἂν κατανοήσειεν τὴν Ῥωμαίων ἐπιείκειαν καὶ μεγαλοφροσύνην, μάλιστα δὲ τὴν Οὐεσπασιανοῦ καὶ Τίτου, ὅτι καίτοι πολλὰ πονήσαντες ἐν τῷ πρὸς Ἰουδαίους πολέμῳ καὶ πικρῶς πρὸς αὐτοὺς ἔχοντες, ὅτι μὴ παρέδοσαν αὐτοῖς τὰ ὅπλα μέχρις δʼ ἐσχάτου πολεμοῦντες ὑπέμειναν,"},{"number":123,"text":"οὐδενὸς αὐτοὺς τῶν ὑπαρχόντων κατὰ τὴν προειρημένην πολιτείαν ἀφείλοντο· ἅμα γὰρ καὶ τῆς πρότερον ὀργῆς καὶ τῆς τῶν Ἀλεξανδρέων καὶ Ἀντιοχέων δήμων μεγίστων παρακλήσεως ἐκράτησαν,"},{"number":124,"text":"ὥστε μηδὲν μήθʼ ὑπὸ τῆς πρὸς τούτους χάριτος μήθʼ ὑπὸ τῆς πρὸς τοὺς πολεμηθέντας μισοπονηρίας ἐνδοῦναι πρὸς τὸ λῦσαί τι τῶν ἀρχαίων τοῖς Ἰουδαίοις φιλανθρώπων, ἀλλὰ τοὺς ἀνταραμένους αὐτοῖς ὅπλα καὶ χωρήσαντας διὰ μάχης δεδωκέναι τιμωρίαν φήσαντες τοὺς οὐδὲν ἐξαμαρτόντας οὐκ ἐδικαίουν ἀποστερεῖν τῶν ὑπαρχόντων."},{"number":125,"text":"Ὅμοιον δέ τι τούτῳ καὶ Μᾶρκον Ἀγρίππαν φρονήσαντα περὶ τῶν Ἰουδαίων οἴδαμεν· τῶν γὰρ Ἰώνων κινηθέντων ἐπʼ αὐτοὺς καὶ δεομένων τοῦ Ἀγρίππου, ἵνα τῆς πολιτείας, ἣν αὐτοῖς ἔδωκεν Ἀντίοχος ὁ Σελεύκου υἱωνὸς ὁ παρὰ τοῖς Ἕλλησιν Θεὸς λεγόμενος,"},{"number":126,"text":"μόνοι μετέλθωσιν, ἀξιούντων δʼ, εἰ συγγενεῖς εἰσιν αὐτοῖς Ἰουδαῖοι, σέβεσθαι τοὺς αὐτῶν θεούς, καὶ δίκης περὶ τούτων συστάσης ἐνίκησαν οἱ Ἰουδαῖοι τοῖς αὐτῶν ἔθεσι χρῆσθαι συνηγορήσαντος αὐτοῖς Νικολάου τοῦ Δαμασκηνοῦ· ὁ γὰρ Ἀγρίππας ἀπεφήνατο μηδὲν αὐτῷ καινίζειν ἐξεῖναι."},{"number":127,"text":"τὸ δʼ ἀκριβὲς εἴ τις βούλεται καταμαθεῖν, ἀναγνώτω τοῦ Νικολάου τὴν ἑκατοστὴν καὶ εἰκοστὴν καὶ τρίτην καὶ τετάρτην. περὶ μὲν οὖν τῶν ὑπʼ Ἀγρίππου κριθέντων οὐκ ἔστιν ἴσως θαυμάζειν· οὐ γὰρ ἐπολέμει τότε Ῥωμαίοις τὸ ἡμέτερον ἔθνος·"},{"number":128,"text":"Οὐεσπασιανοῦ δʼ ἄν τις καὶ Τίτου τὴν μεγαλοφροσύνην εἰκότως ἐκπλαγείη μετὰ πολέμους καὶ τηλικούτους ἀγῶνας οὓς ἔσχον πρὸς ἡμᾶς μετριοπαθησάντων. ἐπανάξω δὲ τὸν λόγον ὅθεν ἐπὶ ταῦτʼ ἐξέβην."},{"number":129,"text":"Τοὺς γὰρ Ἰουδαίους ἐπʼ Ἀντιόχου τοῦ μεγάλου βασιλεύοντος τῆς Ἀσίας ἔτυχεν αὐτούς τε πολλὰ ταλαιπωρῆσαι τῆς γῆς αὐτῶν κακουμένης καὶ τοὺς τὴν κοίλην Συρίαν νεμομένους."},{"number":130,"text":"πολεμοῦντος γὰρ αὐτοῦ πρὸς τὸν Φιλοπάτορα Πτολεμαῖον καὶ πρὸς τὸν υἱὸν αὐτοῦ Πτολεμαῖον ἐπικληθέντα δὲ Ἐπιφανῆ, κακοπαθεῖν συνέβαινεν αὐτοῖς καὶ νικῶντος καὶ πταίοντος ταὐτὰ πάσχειν, ὥστʼ οὐδὲν ἀπέλειπον χειμαζομένης νεὼς καὶ πονουμένης ὑπὸ τοῦ κλύδωνος ἑκατέρωθεν μεταξὺ τῆς εὐπραγίας τῆς Ἀντιόχου καὶ τῆς ἐπὶ θάτερον αὐτοῦ τροπῆς τῶν πραγμάτων κείμενοι."},{"number":131,"text":"νικήσας μέντοι τὸν Πτολεμαῖον ὁ Ἀντίοχος τὴν Ἰουδαίαν προσάγεται. τελευτήσαντος δὲ τοῦ Φιλοπάτορος ὁ παῖς αὐτοῦ μεγάλην ἐξέπεμψε δύναμιν καὶ στρατηγὸν Σκόπαν ἐπὶ τοὺς ἐν τῇ κοίλῃ Συρίᾳ, ὃς πολλάς τε αὐτῶν πόλεις ἔλαβεν καὶ τὸ ἡμέτερον ἔθνος· πολεμούμενον γὰρ αὐτῷ προσέθετο."},{"number":132,"text":"μετʼ οὐ πολὺ δὲ τὸν Σκόπαν Ἀντίοχος νικᾷ συμβαλὼν αὐτῷ πρὸς ταῖς πηγαῖς τοῦ Ἰορδάνου καὶ πολλὴν αὐτοῦ τῆς στρατιᾶς διέφθειρεν."},{"number":133,"text":"ὕστερον δʼ Ἀντιόχου χειρωσαμένου τὰς ἐν τῇ κοίλῃ Συρίᾳ πόλεις, ἃς ὁ Σκόπας κατεσχήκει, καὶ τὴν Σαμάρειαν, ἑκουσίως αὐτῷ προσέθεντο οἱ Ἰουδαῖοι καὶ τῇ πόλει δεξάμενοι πᾶσαν αὐτοῦ τῇ τε στρατιᾷ καὶ τοῖς ἐλέφασιν ἀφθονίαν παρέσχον καὶ τοὺς ὑπὸ Σκόπα καταλειφθέντας ἐν τῇ ἄκρᾳ τῶν Ἱεροσολύμων φρουροὺς πολιορκοῦντι προθύμως συνεμάχησαν."},{"number":134,"text":"ὁ οὖν Ἀντίοχος δίκαιον ἡγησάμενος τὴν τῶν Ἰουδαίων πρὸς αὐτὸν σπουδὴν καὶ φιλοτιμίαν ἀμείψασθαι γράφει τοῖς τε στρατηγοῖς αὐτοῦ καὶ τοῖς φίλοις μαρτυρῶν τοῖς Ἰουδαίοις ὑπὲρ ὧν εὖ πάθοι πρὸς αὐτῶν καὶ τὰς δωρεὰς ἃς ὑπὲρ τούτων διέγνω παρασχεῖν αὐτοῖς ἐμφανίζων."},{"number":135,"text":"παραθήσομαι δὲ τὰς ἐπιστολὰς τὰς τοῖς στρατηγοῖς περὶ αὐτῶν γραφείσας προδιελθών, ὡς μαρτυρεῖ τούτοις ἡμῶν τοῖς λόγοις Πολύβιος ὁ Μεγαλοπολίτης· ἐν γὰρ τῇ ἑξκαιδεκάτῃ τῶν ἱστοριῶν αὐτοῦ φησιν οὕτως· ὁ δὲ τοῦ Πτολεμαίου στρατηγὸς Σκόπας ὁρμήσας εἰς τοὺς ἄνω τόπους κατεστρέψατο ἐν τῷ χειμῶνι τὸ Ἰουδαίων ἔθνος. λέγει δὲ ἐν τῇ αὐτῇ βίβλῳ,"},{"number":136,"text":"ὡς τοῦ Σκόπα νικηθέντος ὑπʼ Ἀντιόχου τὴν μὲν Βατανέαν καὶ Σαμάρειαν καὶ Ἄβιλα καὶ Γάδαρα παρέλαβεν Ἀντίοχος, μετʼ ὀλίγον δὲ προσεχώρησαν αὐτῷ καὶ τῶν Ἰουδαίων οἱ περὶ τὸ ἱερὸν τὸ προσαγορευόμενον Ἱεροσόλυμα κατοικοῦντες, ὑπὲρ οὗ καὶ πλείω λέγειν ἔχοντες καὶ μάλιστα περὶ τῆς γενομένης περὶ τὸ ἱερὸν ἐπιφανείας, εἰς ἕτερον καιρὸν ὑπερθησόμεθα τὴν διήγησιν."},{"number":137,"text":"καὶ Πολύβιος μὲν ταῦτα ἱστόρησεν. ἡμεῖς δʼ ἐπανάξομεν τὸν λόγον ἐπὶ τὴν διήγησιν παραθέμενοι πρῶτον τὰς ἐπιστολὰς τοῦ βασιλέως Ἀντιόχου."},{"number":138,"text":"Βασιλεὺς Ἀντίοχος Πτολεμαίῳ χαίρειν.\n\nτῶν Ἰουδαίων καὶ παραυτίκα μέν, ἡνίκα τῆς χώρας ἐπέβημεν αὐτῶν, ἐπιδειξαμένων τὸ πρὸς ἡμᾶς φιλότιμον καὶ παραγενομένους δʼ εἰς τὴν πόλιν λαμπρῶς ἐκδεξαμένων καὶ μετὰ τῆς γερουσίας ἀπαντησάντων, ἄφθονον δὲ τὴν χορηγίαν τοῖς στρατιώταις καὶ τοῖς ἐλέφασι παρεσχημένων, συνεξελόντων δὲ καὶ τοὺς ἐν τῇ ἄκρᾳ φρουροὺς τῶν Αἰγυπτίων,"},{"number":139,"text":"ἠξιώσαμεν καὶ αὐτοὶ τούτων αὐτοὺς ἀμείψασθαι καὶ τὴν πόλιν αὐτῶν ἀναλαβεῖν κατεφθαρμένην ὑπὸ τῶν περὶ τοὺς πολέμους συμπεσόντων καὶ συνοικίσαι τῶν διεσπαρμένων εἰς αὐτὴν πάλιν συνελθόντων."},{"number":140,"text":"πρῶτον δʼ αὐτοῖς ἐκρίναμεν διὰ τὴν εὐσέβειαν παρασχεῖν εἰς τὰς θυσίας σύνταξιν κτηνῶν τε θυσίμων καὶ οἴνου καὶ ἐλαίου καὶ λιβάνου ἀργυρίου μυριάδας δύο καὶ σεμιδάλεως ἀρτάβας ἱερᾶς κατὰ τὸν ἐπιχώριον νόμον πυρῶν μεδίμνους χιλίους τετρακοσίους ἑξήκοντα καὶ ἁλῶν μεδίμνους τριακοσίους ἑβδομηκονταπέντε."},{"number":141,"text":"τελεῖσθαι δʼ αὐτοῖς ταῦτα βούλομαι, καθὼς ἐπέσταλκα, καὶ τὸ περὶ τὸ ἱερὸν ἀπαρτισθῆναι ἔργον τάς τε στοὰς κἂν εἴ τι ἕτερον οἰκοδομῆσαι δέοι· ἡ δὲ τῶν ξύλων ὕλη κατακομιζέσθω ἐξ αὐτῆς τε τῆς Ἰουδαίας καὶ ἐκ τῶν ἄλλων ἐθνῶν καὶ ἐκ τοῦ Λιβάνου μηδενὸς πρασσομένου τέλος. ὁμοίως δὲ καὶ τοῖς ἄλλοις, ἐν οἷς ἂν ἐπιφανεστέραν γίγνεσθαι τὴν τοῦ ἱεροῦ ἐπισκευὴν δέῃ."},{"number":142,"text":"πολιτευέσθωσαν δὲ πάντες οἱ ἐκ τοῦ ἔθνους κατὰ τοὺς πατρίους νόμους, ἀπολυέσθω δʼ ἡ γερουσία καὶ οἱ ἱερεῖς καὶ γραμματεῖς τοῦ ἱεροῦ καὶ ἱεροψάλται ὧν ὑπὲρ τῆς κεφαλῆς τελοῦσιν καὶ τοῦ στεφανιτικοῦ φόρου καὶ τοῦ περὶ τῶν ἄλλων."},{"number":143,"text":"ἵνα δὲ θᾶττον ἡ πόλις κατοικισθῇ, δίδωμι τοῖς τε νῦν κατοικοῦσιν καὶ κατελευσομένοις ἕως τοῦ Ὑπερβερεταίου μηνὸς ἀτελέσιν εἶναι μέχρι τριῶν ἐτῶν."},{"number":144,"text":"ἀπολύομεν δὲ καὶ εἰς τὸ λοιπὸν αὐτοὺς τοῦ τρίτου μέρους τῶν φόρων, ὥστε αὐτῶν ἐπανορθωθῆναι τὴν βλάβην. καὶ ὅσοι ἐκ τῆς πόλεως ἁρπαγέντες δουλεύουσιν, αὐτούς τε τούτους καὶ τοὺς ὑπʼ αὐτῶν γεννηθέντας ἐλευθέρους ἀφίεμεν καὶ τὰς οὐσίας αὐτοῖς ἀποδίδοσθαι κελεύομεν."},{"number":145,"text":"Ἡ μὲν οὖν ἐπιστολὴ ταῦτα περιεῖχεν. σεμνύνων δὲ καὶ τὸ ἱερὸν πρόγραμμα κατὰ πᾶσαν τὴν βασιλείαν ἐξέθηκεν περιέχον τάδε· μηδενὶ ἐξεῖναι ἀλλοφύλῳ εἰς τὸν περίβολον εἰσιέναι τοῦ ἱεροῦ τὸν ἀπηγορευμένον τοῖς Ἰουδαίοις, εἰ μὴ οἷς ἁγνισθεῖσίν ἐστιν ἔθιμον κατὰ τὸν πάτριον νόμον."},{"number":146,"text":"μηδʼ εἰς τὴν πόλιν εἰσφερέσθω ἵππεια κρέα μηδὲ ἡμιόνεια μηδὲ ἀγρίων ὄνων καὶ ἡμέρων παρδάλεών τε καὶ ἀλωπέκων καὶ λαγῶν καὶ καθόλου δὲ πάντων τῶν ἀπηγορευμένων ζῴων τοῖς Ἰουδαίοις· μηδὲ τὰς δορὰς εἰσφέρειν ἐξεῖναι, ἀλλὰ μηδὲ τρέφειν τι τούτων ἐν τῇ πόλει· μόνοις δὲ τοῖς προγονικοῖς θύμασιν, ἀφʼ ὧν καὶ τῷ θεῷ δεῖ καλλιερεῖν, ἐπιτετράφθαι χρῆσθαι. ὁ δέ τι τούτων παραβὰς ἀποτινύτω τοῖς ἱερεῦσιν ἀργυρίου δραχμὰς τρισχιλίας."},{"number":147,"text":"Ἔγραψε δὲ μαρτυρῶν ἡμῖν εὐσέβειάν τε καὶ πίστιν, ἡνίκα νεωτερίζοντα τὰ κατὰ τὴν Φρυγίαν ἐπύθετο καὶ Λυδίαν καθʼ ὃν ἦν καιρὸν ἐν ταῖς ἄνω σατραπείαις, κελεύων Ζεῦξιν τὸν αὐτοῦ στρατηγὸν καὶ ἐν τοῖς μάλιστα φίλον πέμψαι τινὰς τῶν ἡμετέρων ἐκ Βαβυλῶνος εἰς Φρυγίαν."},{"number":148,"text":"γράφει δʼ οὕτως· βασιλεὺς Ἀντίοχος Ζεύξιδι τῷ πατρὶ χαίρειν. εἰ ἔρρωσαι, εὖ ἂν ἔχοι, ὑγιαίνω δὲ καὶ αὐτός."},{"number":149,"text":"πυνθανόμενος τοὺς ἐν Λυδίᾳ καὶ Φρυγίᾳ νεωτερίζοντας μεγάλης ἐπιστροφῆς ἡγησάμην τοῦτό μοι δεῖσθαι, καὶ βουλευσαμένῳ μοι μετὰ τῶν φίλων, τί δεῖ ποιεῖν, ἔδοξεν εἰς τὰ φρούρια καὶ τοὺς ἀναγκαιοτάτους τόπους τῶν ἀπὸ τῆς Μεσοποταμίας καὶ Βαβυλωνίας Ἰουδαίων οἴκους δισχιλίους σὺν ἐπισκευῇ μεταγαγεῖν."},{"number":150,"text":"πέπεισμαι γὰρ εὔνους αὐτοὺς ἔσεσθαι τῶν ἡμετέρων φύλακας διὰ τὴν πρὸς τὸν θεὸν εὐσέβειαν, καὶ μαρτυρουμένους δʼ αὐτοὺς ὑπὸ τῶν προγόνων εἰς πίστιν οἶδα καὶ προθυμίαν εἰς ἃ παρακαλοῦνται· βούλομαι τοίνυν καίπερ ἐργώδους ὄντος τοῦ μεταγαγεῖν ὑποσχομένους νόμοις αὐτοὺς χρῆσθαι τοῖς ἰδίοις."},{"number":151,"text":"ὅταν δʼ αὐτοὺς ἀγάγῃς εἰς τοὺς προειρημένους τόπους, εἴς τʼ οἰκοδομίας οἰκιῶν αὐτοῖς δώσεις τόπον ἑκάστῳ καὶ χώραν εἰς γεωργίαν καὶ φυτείαν ἀμπέλων, καὶ ἀτελεῖς τῶν ἐκ τῆς γῆς καρπῶν ἀνήσεις ἐπὶ ἔτη δέκα."},{"number":152,"text":"μετρείσθωσαν δὲ καὶ ἄχρις ἂν τοὺς παρὰ τῆς γῆς καρποὺς λαμβάνωσιν σῖτον εἰς τὰς τῶν θεραπόντων διατροφάς· διδόσθω δὲ καὶ τοῖς εἰς τὰς χρείας ὑπηρετοῦσιν τὸ αὔταρκες, ἵνα τῆς παρʼ ἡμῶν τυγχάνοντες φιλανθρωπίας προθυμοτέρους παρέχωσιν αὑτοὺς περὶ τὰ ἡμέτερα."},{"number":153,"text":"πρόνοιαν δὲ ποιοῦ καὶ τοῦ ἔθνους κατὰ τὸ δυνατόν, ὅπως ὑπὸ μηδενὸς ἐνοχλῆται. περὶ μὲν οὖν τῆς Ἀντιόχου φιλίας τοῦ μεγάλου πρὸς Ἰουδαίους ταῦτα ἡμῖν ἀποχρώντως εἰρήσθω μαρτύρια."}],"4":[{"number":154,"text":"Μετὰ δὲ ταῦτα φιλίαν καὶ σπονδὰς πρὸς Πτολεμαῖον Ἀντίοχος ἐποιήσατο καὶ δίδωσιν αὐτῷ τὴν θυγατέρα Κλεοπάτραν πρὸς γάμον παραχωρήσας αὐτῷ τῆς κοίλης Συρίας καὶ Σαμαρείας καὶ Ἰουδαίας καὶ Φοινίκης φερνῆς ὀνόματι."},{"number":155,"text":"καὶ διαιρεθέντων εἰς ἀμφοτέρους τοὺς βασιλέας τῶν φόρων τὰς ἰδίας ἕκαστοι τῶν ἐπισήμων ὠνοῦντο πατρίδας φορολογεῖν καὶ συναθροίζοντες τὸ προστεταγμένον κεφάλαιον τοῖς βασιλεῦσιν ἐτέλουν."},{"number":156,"text":"ἐν τούτῳ τῷ χρόνῳ Σαμαρεῖς εὖ πράσσοντες πολλὰ τοὺς Ἰουδαίους ἐκάκωσαν τήν τε χώραν αὐτῶν τεμόντες καὶ σώματα διαρπάσαντες· ἐγένετο δὲ ταῦτα ἐπὶ ἀρχιερέως Ὀνίου."},{"number":157,"text":"τελευτήσαντος γὰρ Ἐλεαζάρου τὴν ἀρχιερωσύνην ὁ θεῖος αὐτοῦ Μανασσῆς παρέλαβεν, μεθʼ ὃν καταστρέψαντα τὸν βίον Ὀνίας τὴν τιμὴν ἐξεδέξατο Σίμωνος υἱὸς ὢν τοῦ δικαίου κληθέντος· Σίμων δʼ ἦν ἀδελφὸς Ἐλεαζάρου, καθὼς προεῖπον."},{"number":158,"text":"οὗτος ὁ Ὀνίας βραχὺς ἦν τὴν διάνοιαν καὶ χρημάτων ἥττων καὶ διὰ τοῦτο τὸν ὑπὲρ τοῦ λαοῦ φόρον, ὃν τοῖς βασιλεῦσιν οἱ πατέρες αὐτοῦ ἐτέλουν ἐκ τῶν ἰδίων, τάλαντα εἴκοσιν ἀργυρίου μὴ δούς, εἰς ὀργὴν ἐκίνησεν τὸν βασιλέα Πτολεμαῖον τὸν Εὐεργέτην, ὃς ἦν πατὴρ τοῦ Φιλοπάτορος."},{"number":159,"text":"καὶ πέμψας εἰς Ἱεροσόλυμα πρεσβευτὴν ᾐτιᾶτο τὸν Ὀνίαν ὡς οὐκ ἀποδιδόντα τοὺς φόρους καὶ ἠπείλει κληρουχήσειν αὐτῶν τὴν γῆν οὐκ ἀπολαβὼν καὶ πέμψειν τοὺς ἐνοικήσοντας στρατιώτας. ἀκούσαντες δὲ τὰ παρὰ τοῦ βασιλέως οἱ Ἰουδαῖοι συνεχύθησαν, τὸν δὲ Ὀνίαν τούτων ἐδυσώπει διὰ τὴν φιλοχρηματίαν οὐδέν."},{"number":160,"text":"Ἰώσηπος δέ τις, νέος μὲν ἔτι τὴν ἡλικίαν, ἐπὶ σεμνότητι δὲ καὶ προνοίᾳ δικαιοσύνης δόξαν ἔχων παρὰ τοῖς Ἱεροσολυμίταις, Τωβίου μὲν πατρός, ἐκ δὲ τῆς Ὀνίου τοῦ ἀρχιερέως ἀδελφῆς γεγονώς, δηλωσάσης αὐτῷ τῆς μητρὸς τὴν τοῦ πρεσβευτοῦ παρουσίαν, ἔτυχεν γὰρ αὐτὸς ἀποδημῶν εἰς Φικόλαν κώμην ἐξ ἧς ὑπῆρχεν,"},{"number":161,"text":"ἐλθὼν εἰς τὴν πόλιν ἐπέπληττε τῷ Ὀνίᾳ μὴ προνοουμένῳ τῆς ἀσφαλείας τῶν πολιτῶν, ἀλλʼ εἰς κινδύνους τὸ ἔθνος βουλομένῳ περιστῆσαι διὰ τὴν τῶν χρημάτων ἀποστέρησιν, διʼ ἃ καὶ τοῦ λαοῦ τὴν προστασίαν λαβεῖν αὐτὸν ἔλεγεν καὶ τῆς ἀρχιερατικῆς τιμῆς ἐπιτυχεῖν."},{"number":162,"text":"εἰ δʼ ἐρωτικῶς οὕτως ἔχοι τῶν χρημάτων, ὡς διʼ αὐτὰ καὶ τὴν πατρίδα κινδυνεύουσαν ἰδεῖν ὑπομεῖναι καὶ πᾶν ὁτιοῦν παθόντας αὐτοῦ τοὺς πολίτας, συνεβούλευσεν ἀπελθόντα πρὸς τὸν βασιλέα δεηθῆναι αὐτοῦ ἢ πάντων αὐτῷ παραχωρῆσαι τῶν χρημάτων ἢ μέρους."},{"number":163,"text":"τοῦ δὲ Ὀνίου μήτε ἄρχειν θέλειν ἀποκριναμένου καὶ τὴν ἀρχιερωσύνην δʼ εἰ δυνατόν ἐστιν ἑτοίμως ἔχειν ἀποθέσθαι λέγοντος μήτε ἀναβήσεσθαι πρὸς τὸν βασιλέα, μέλειν γὰρ αὐτῷ περὶ τούτων οὐδέν, εἰ πρεσβεύειν αὐτῷ συγχωρεῖ πρὸς τὸν Πτολεμαῖον ὑπὲρ τοῦ ἔθνους ἐπηρώτησεν."},{"number":164,"text":"φήσαντος δὲ ἐπιτρέπειν ἀναβὰς εἰς τὸ ἱερὸν ὁ Ἰώσηπος καὶ συγκαλέσας τὸ πλῆθος εἰς ἐκκλησίαν μηδὲν ταράσσεσθαι μηδὲ φοβεῖσθαι παρῄνει διὰ τὴν Ὀνίου τοῦ θείου περὶ αὐτῶν ἀμέλειαν, ἀλλʼ ἐν ἀδείᾳ τῶν ἀπὸ τῆς σκυθρωποτέρας ἐλπίδος τὴν διάνοιαν αὐτοὺς ἔχειν ἠξίου· πρεσβεύσειν γὰρ αὐτὸς ἐπηγγέλλετο πρὸς τὸν βασιλέα καὶ πείσειν αὐτόν, ὅτι μηδὲν ἀδικοῦσιν."},{"number":165,"text":"καὶ τὸ μὲν πλῆθος τούτων ἀκοῦσαν εὐχαριστεῖ τῷ Ἰωσήπῳ, καταβὰς δʼ αὐτὸς ἐκ τοῦ ἱεροῦ ξενίᾳ τε ὑποδέχεται τὸν παρὰ τοῦ Πτολεμαίου πεπρεσβευκότα καὶ δωρησάμενος αὐτὸν πολυτελέσι δωρεαῖς καὶ ἐπὶ πολλὰς ἑστιάσας φιλοτίμως ἡμέρας προέπεμψε πρὸς τὸν βασιλέα, φράσας αὐτῷ καὶ αὐτὸς ἀκολουθήσειν·"},{"number":166,"text":"καὶ γὰρ ἔτι μᾶλλον γεγόνει πρόθυμος πρὸς τὴν ἄφιξιν τὴν παρὰ τὸν βασιλέα τοῦ πρεσβευτοῦ προτρεψαμένου καὶ παρορμήσαντος εἰς Αἴγυπτον ἐλθεῖν καὶ πάντων ὧν ἂν δέηται παρὰ Πτολεμαίου τυχεῖν αὐτὸν ποιήσειν ὑποσχομένου· τὸ γὰρ ἐλευθέριον αὐτοῦ καὶ τὸ σεμνὸν τοῦ ἤθους λίαν ἠγάπησεν."},{"number":167,"text":"Καὶ ὁ μὲν πρεσβευτὴς ἐλθὼν εἰς Αἴγυπτον ἀπήγγειλεν τῷ βασιλεῖ τὴν τοῦ Ὀνίου ἀγνωμοσύνην καὶ περὶ τῆς τοῦ Ἰωσήπου χρηστότητος ἐδήλου, καὶ ὅτι μέλλοι πρὸς αὐτὸν ἥξειν παραιτησόμενος τῶν ἁμαρτημάτων τὸ πλῆθος· εἶναι γὰρ αὐτοῦ προστάτην· ἀμέλει τοσαύτῃ περὶ τῶν ἐγκωμίων τῶν περὶ τοῦ νεανίσκου διετέλεσε χρώμενος περιουσίᾳ, ὥστε καὶ τὸν βασιλέα καὶ τὴν γυναῖκα αὐτοῦ Κλεοπάτραν προδιέθηκεν οἰκείως ἔχειν πρὸς τὸν Ἰώσηπον οὔπω παρόντα."},{"number":168,"text":"ὁ δὲ Ἰώσηπος διαπέμψας πρὸς τοὺς φίλους εἰς Σαμάρειαν καὶ δανεισάμενος ἀργύριον καὶ τὰ πρὸς τὴν ἀποδημίαν ἑτοιμασάμενος ἐσθῆτάς τε καὶ ἐκπώματα καὶ ὑποζύγια, καὶ ταῦθʼ ὡς περὶ δισμυρίας δραχμὰς παρασκευασάμενος εἰς Ἀλεξάνδρειαν παρεγένετο."},{"number":169,"text":"ἔτυχεν δὲ κατʼ ἐκεῖνον τὸν καιρὸν πάντας ἀναβαίνειν τοὺς ἀπὸ τῶν πόλεων τῶν τῆς Συρίας καὶ Φοινίκης πρώτους καὶ τοὺς ἄρχοντας ἐπὶ τὴν τῶν τελῶν ὠνήν· κατʼ ἔτος δὲ αὐτὰ τοῖς δυνατοῖς τῶν ἐν ἑκάστῃ πόλει ἐπίπρασκεν ὁ βασιλεύς."},{"number":170,"text":"ὁρῶντες οὖν οὗτοι κατὰ τὴν ὁδὸν τὸν Ἰώσηπον ἐχλεύαζον ἐπὶ πενίᾳ καὶ λιτότητι. ὡς δʼ εἰς τὴν Ἀλεξάνδρειαν ἀφικόμενος ἐν Μέμφει τὸν Πτολεμαῖον ἤκουσεν ὄντα, ὑπαντησάμενος συνέβαλεν αὐτῷ."},{"number":171,"text":"καθεζομένου δὲ τοῦ βασιλέως ἐπʼ ὀχήματος μετὰ τῆς γυναικὸς καὶ μετὰ Ἀθηνίωνος φίλου, οὗτος δʼ ἦν ὁ πρεσβεύσας εἰς Ἱεροσόλυμα καὶ παρὰ Ἰωσήπῳ ξενισθείς, θεασάμενος αὐτὸν ὁ Ἀθηνίων εὐθὺς ἐποίει τῷ βασιλεῖ γνώριμον, τοῦτον εἶναι λέγων, περὶ οὗ παραγενόμενος ἐξ Ἱεροσολύμων ἀπήγγειλεν, ὡς ἀγαθός τε εἴη καὶ φιλότιμος νεανίσκος."},{"number":172,"text":"ὁ δὲ Πτολεμαῖος πρῶτός τε αὐτὸν ἠσπάσατο καὶ δὴ ἀναβῆναι ἐπὶ τὸ ὄχημα παρεκάλεσεν καὶ καθεσθέντος ἤρξατο περὶ τῶν Ὀνίᾳ πραττομένων ἐγκαλεῖν. ὁ δέ συγγίνωσκε, φησίν, αὐτῷ διὰ τὸ γῆρας· οὐ γὰρ λανθάνει σε πάντως, ὅτι καὶ τοὺς πρεσβύτας καὶ τὰ νήπια τὴν αὐτὴν διάνοιαν ἔχειν συμβέβηκεν. παρὰ δʼ ἡμῶν ἔσται σοι τῶν νέων ἅπαντα, ὥστε μηδὲν αἰτιᾶσθαι."},{"number":173,"text":"ἡσθεὶς δʼ ἐπὶ τῇ χάριτι καὶ τῇ εὐτραπελίᾳ τοῦ νεανίσκου μᾶλλον αὐτὸν ὡς ἤδη καὶ πεπειραμένος ἀγαπᾶν ἤρξατο, ὡς ἔν τε τοῖς βασιλείοις αὐτὸν κελεῦσαι διαιτᾶσθαι καὶ καθʼ ἡμέραν ἐπὶ τῆς ἑστιάσεως τῆς ἰδίας ἔχειν."},{"number":174,"text":"γενομένου δʼ ἐν Ἀλεξανδρείᾳ τοῦ βασιλέως ἰδόντες οἱ πρῶτοι τῆς Συρίας συγκαθεζόμενον αὐτῷ τὸν Ἰώσηπον ἀηδῶς ἔφερον."},{"number":175,"text":"Ἐνστάσης δὲ τῆς ἡμέρας, καθʼ ἣν ἔμελλεν τὰ τέλη πιπράσκεσθαι τῶν πόλεων, ἠγόραζον οἱ τοῖς ἀξιώμασιν ἐν ταῖς πατρίσιν διαφέροντες. εἰς ὀκτακισχίλια δὲ τάλαντα συναθροιζομένων τῶν τῆς κοίλης Συρίας τελῶν καὶ τῆς Φοινίκης καὶ Ἰουδαίας σὺν τῇ Σαμαρείᾳ,"},{"number":176,"text":"προσελθὼν Ἰώσηπος τοὺς μὲν ὠνουμένους διέβαλλεν ὡς συνθεμένους ὀλίγην αὐτῷ τιμὴν ὑφίστασθαι τῶν τελῶν, αὐτὸς δὲ διπλασίονα δώσειν ὑπισχνεῖτο καὶ τῶν ἁμαρτόντων εἰς τὸν οἶκον αὐτοῦ τὰς οὐσίας ἀναπέμψειν αὐτῷ· καὶ γὰρ τοῦτο τοῖς τέλεσι συνεπιπράσκετο."},{"number":177,"text":"τοῦ δὲ βασιλέως ἡδέως ἀκούσαντος καὶ ὡς αὔξοντι τὴν πρόσοδον αὐτοῦ κατακυροῦν τὴν ὠνὴν τῶν τελῶν ἐκείνῳ φήσαντος, ἐρομένου δὲ εἰ καὶ τοὺς ἐγγυησομένους αὐτὸν ἔχει, σφόδρʼ ἀστείως ἀπεκρίνατο· δώσω γὰρ εἶπεν ἀνθρώπους ἀγαθοὺς καὶ καλούς, οἷς οὐκ ἀπιστήσετε."},{"number":178,"text":"λέγειν δὲ τούτους οἵτινες εἶεν εἰπόντος, αὐτόν, εἶπεν, ὦ βασιλεῦ, σέ τε καὶ τὴν γυναῖκα τὴν σὴν ὑπὲρ ἑκατέρου μέρους ἐγγυησομένους δίδωμί σοι. γελάσας δʼ ὁ Πτολεμαῖος συνεχώρησεν αὐτῷ δίχα τῶν ὁμολογούντων ἔχειν τὰ τέλη."},{"number":179,"text":"τοῦτο σφόδρα τοὺς ἀπὸ τῶν πόλεων εἰς τὴν Αἴγυπτον ἐλθόντας ἐλύπησεν ὡς παρευδοκιμηθέντας. καὶ οἱ μὲν ἐπανῆκον εἰς τὰς ἰδίας ἕκαστοι πατρίδας μετʼ αἰσχύνης."},{"number":180,"text":"Ὁ δὲ Ἰώσηπος λαβὼν παρὰ τοῦ βασιλέως πεζῶν μὲν στρατιώτας δισχιλίους, ἠξίωσε γὰρ βοήθειάν τινα λαβεῖν, ἵνα τοὺς ἐν ταῖς πόλεσι καταφρονοῦντας ἔχῃ βιάζεσθαι, καὶ δανεισάμενος ἐν Ἀλεξανδρείᾳ παρὰ τῶν τοῦ βασιλέως φίλων τάλαντα πεντακόσια εἰς Συρίαν ἐξώρμησεν."},{"number":181,"text":"γενόμενος δὲ ἐν Ἀσκάλωνι τοὺς φόρους ἀπαιτῶν τοὺς Ἀσκαλωνίτας, ἐπεὶ μηδὲν ἐβούλοντο διδόναι, ἀλλὰ καὶ προσύβριζον αὐτόν, συλλαβὼν αὐτῶν τοὺς πρωτεύοντας ὡς εἴκοσιν ἀπέκτεινε καὶ τὰς οὐσίας αὐτῶν εἰς χίλια τάλαντα ἀθροισθείσας ἔπεμψε τῷ βασιλεῖ, δηλῶν αὐτῷ καὶ τὰ γεγενημένα."},{"number":182,"text":"θαυμάσας δʼ αὐτὸν ὁ Πτολεμαῖος τοῦ φρονήματος καὶ τῶν πεπραγμένων ἐπαινέσας ἐφίησιν αὐτῷ ποιεῖν ὅ τι βούλεται. ταῦτʼ ἀκούσαντες οἱ Σύροι κατεπλάγησαν καὶ παράδειγμα τῆς ἀπειθείας χαλεπὸν ἔχοντες τοὺς τῶν Ἀσκαλωνιτῶν ἄνδρας ἀνῃρημένους ἀνοίγοντες τὰς πύλας ἐδέχοντο προθύμως τὸν Ἰώσηπον καὶ τοὺς φόρους ἐτέλουν."},{"number":183,"text":"ἐπιχειρούντων δὲ καὶ Σκυθοπολιτῶν ὑβρίζειν αὐτὸν καὶ μὴ παρέχειν τοὺς φόρους αὐτῷ, οὓς μηδὲν ἀμφισβητοῦντες ἐτέλουν, καὶ τούτων ἀποκτείνας τοὺς πρώτους τὰς οὐσίας αὐτῶν ἀπέστειλε τῷ βασιλεῖ."},{"number":184,"text":"συναγαγὼν δὲ πολλὰ χρήματα καὶ κέρδη μεγάλα ποιήσας ἐκ τῆς ὠνῆς τῶν τελῶν, εἰς τὸ διαμεῖναι τὴν ὑπάρχουσαν αὐτῷ δύναμιν τοῖς οὖσι κατεχρήσατο, τὴν ἀφορμὴν αὐτῷ καὶ τὴν ὑπόθεσιν τῆς τότε εὐτυχίας τηρεῖν φρόνιμον ἡγούμενος ἐξ αὐτῶν ὧν αὐτὸς ἐκέκτητο·"},{"number":185,"text":"πολλὰ γὰρ ὑπὸ χεῖρα τῷ βασιλεῖ καὶ τῇ Κλεοπάτρᾳ δῶρα ἔπεμπεν καὶ τοῖς φίλοις αὐτῶν καὶ πᾶσιν τοῖς περὶ τὴν αὐλὴν δυνατοῖς ὠνούμενος διὰ τούτων τὴν εὔνοιαν τὴν παρʼ αὐτῶν."},{"number":186,"text":"Ἀπέλαυσε δὲ ταύτης τῆς εὐτυχίας ἐπὶ ἔτη εἴκοσι καὶ δύο, πατὴρ μὲν γενόμενος ἐκ μιᾶς γυναικὸς παίδων ἑπτά, ποιησάμενος δὲ καὶ ἐκ τῆς τοῦ ἀδελφοῦ Σολυμίου θυγατρὸς ἕνα Ὑρκανὸν ὄνομα."},{"number":187,"text":"γαμεῖ δὲ ταύτην ἐξ αἰτίας τοιαύτης· τἀδελφῷ ποτε συνελθὼν εἰς Ἀλεξάνδρειαν ἄγοντι καὶ τὴν θυγατέρα γάμων ὥραν ἔχουσαν, ὅπως αὐτὴν συνοικίσῃ τινὶ τῶν ἐπʼ ἀξιώματος Ἰουδαίων, καὶ δειπνῶν παρὰ τῷ βασιλεῖ, ὀρχηστρίδος εἰσελθούσης εἰς τὸ συμπόσιον εὐπρεποῦς ἐρασθεὶς τῷ ἀδελφῷ τοῦτο μηνύει παρακαλῶν αὐτόν, ἐπεὶ καὶ νόμῳ κεκώλυται παρὰ Ἰουδαίοις ἀλλοφύλῳ πλησιάζειν γυναικί, συγκρύψαντα τὸ ἁμάρτημα καὶ διάκονον ἀγαθὸν γενόμενον παρασχεῖν αὐτῷ ὥστʼ ἐκπλῆσαι τὴν ἐπιθυμίαν."},{"number":188,"text":"ὁ δὲ ἀδελφὸς ἀσμένως δεξάμενος τὴν διακονίαν, κοσμήσας τὴν αὐτοῦ θυγατέρα νυκτὸς ἤγαγε πρὸς αὐτὸν καὶ συγκατεκοίμισεν. ὁ δʼ ὑπὸ μέθης ἀγνοήσας τἀληθὲς συνέρχεται τῇ τοῦ ἀδελφοῦ θυγατρί, καὶ τούτου γενομένου πολλάκις ἤρα σφοδρότερον. ἔφη δὲ καὶ πρὸς τὸν ἀδελφόν, ὡς κινδυνεύει τῷ ζῆν ἐρῶν ὀρχηστρίδος, ἧς ἴσως οὐκ ἂν αὐτῷ παραχωρήσειν τὸν βασιλέα."},{"number":189,"text":"τοῦ δὲ ἀδελφοῦ μηδὲν ἀγωνιᾶν παρακαλοῦντος, ἀπολαύειν δʼ ἧς ἐρᾷ μετʼ ἀδείας καὶ γυναῖκα ἔχειν αὐτὴν φήσαντος καὶ τἀληθὲς αὐτῷ φανερὸν ποιήσαντος, ὡς ἕλοιτο μᾶλλον τὴν ἰδίαν ὑβρίσαι θυγατέρα ἢ περιιδεῖν ἐκεῖνον ἐν αἰσχύνῃ γενόμενον, ἐπαινέσας αὐτὸν Ἰώσηπος τῆς φιλαδελφίας συνῴκησεν αὐτοῦ τῇ θυγατρὶ καὶ παῖδα ἐξ αὐτῆς ἐγέννησεν Ὑρκανόν, ὡς προειρήκαμεν."},{"number":190,"text":"ἔτι δὲ ὢν τρισκαίδεκα ἐτῶν οὗτος ὁ παῖς νεώτερος ἐπεδείκνυτο τὴν φυσικὴν ἀνδρείαν καὶ σύνεσιν, ὡς ζηλοτυπηθῆναι δεινῶς αὐτὸν ὑπὸ τῶν ἀδελφῶν ὄντα πολὺ κρείττονα καὶ φθονηθῆναι δυνάμενον."},{"number":191,"text":"τοῦ δὲ Ἰωσήπου γνῶναι θελήσαντος, τίς αὐτῷ τῶν υἱῶν πρὸς ἀρετὴν εὖ πέφυκεν καὶ καθʼ ἕνα πέμψαντος πρὸς τοὺς παιδεύειν τότε δόξαν ἔχοντας, οἱ λοιποὶ μὲν ὑπὸ ῥᾳθυμίας καὶ τῆς πρὸς τὸ φιλεργεῖν μαλακίας ἀνόητοι καὶ ἀμαθεῖς ἐπανῆκον αὐτῷ, μετὰ δʼ ἐκείνους τὸν νεώτατον Ὑρκανόν,"},{"number":192,"text":"δοὺς αὐτῷ τριακόσια ζεύγη βοῶν, ἐξέπεμψεν ὁδὸν ἡμερῶν δύο εἰς τὴν ἐρημίαν σπεροῦντα τὴν γῆν ἀποκρύψας τοὺς ζευκτῆρας ἱμάντας."},{"number":193,"text":"ὁ δὲ γενόμενος ἐν τῷ τόπῳ καὶ τοὺς ἱμάντας οὐκ ἔχων, τῆς μὲν τῶν βοηλατῶν γνώμης κατηλόγησεν συμβουλευόντων πέμπειν πρὸς τὸν πατέρα κομιοῦντάς τινας τοὺς ἱμάντας, τὸν δὲ καιρὸν ἡγησάμενος μὴ δεῖν ἀπολλύναι περιμένοντα τοὺς ἀποσταλησομένους ἐπενόησέν τι στρατηγικὸν καὶ τῆς ἡλικίας πρεσβύτερον."},{"number":194,"text":"κατασφάξας γὰρ δέκα ζεύγη τὰ μὲν κρέα τοῖς ἐργάταις διένειμεν, τεμὼν δὲ τὰς δορὰς αὐτῶν καὶ ποιήσας ἱμάντας ἐνέδησεν τούτοις τὰ ζυγά, καὶ τοῦτον τὸν τρόπον σπείρας ἣν ὁ πατὴρ αὐτῷ προσέταξε γῆν ὑπέστρεψε πρὸς αὐτόν."},{"number":195,"text":"ἐλθόντα δʼ ὁ πατὴρ ὑπερηγάπησεν τοῦ φρονήματος, καὶ τὴν ὀξύτητα τῆς διανοίας καὶ τὸ ἐπʼ αὐτῇ τολμηρὸν ἐπαινέσας ὡς μόνον ὄντα γνήσιον ἔτι μᾶλλον ἔστεργεν ἀχθομένων ἐπὶ τούτῳ τῶν ἀδελφῶν."},{"number":196,"text":"Ὡς δʼ ἀπήγγειλέ τις αὐτῷ κατὰ τοῦτον τὸν καιρὸν υἱὸν τῷ βασιλεῖ Πτολεμαίῳ γεγενῆσθαι, καὶ πάντες οἱ πρῶτοι τῆς Συρίας καὶ τῆς ὑπηκόου χώρας ἑορτάζοντες τὴν γενέσιον ἡμέραν τοῦ παιδίου μετὰ μεγάλης παρασκευῆς εἰς τὴν Ἀλεξάνδρειαν ἐξώρμων, αὐτὸς μὲν ὑπὸ γήρως κατείχετο, τῶν δὲ υἱῶν ἀπεπειρᾶτο εἴ τις αὐτῶν ἀπελθεῖν βούλεται πρὸς τὸν βασιλέα."},{"number":197,"text":"τῶν δὲ πρεσβυτέρων παραιτησαμένων καὶ πρὸς τὰς τοιαύτας συνουσίας ἀγροικότερον ἔχειν φησάντων, τὸν δʼ ἀδελφὸν Ὑρκανὸν πέμπειν συμβουλευσάντων, ἡδέως ἀκούσας καλεῖ τὸν Ὑρκανὸν καὶ εἰ δύναται πρὸς τὸν βασιλέα βαδίσαι καὶ πρόθυμός ἐστιν ἀνέκρινεν."},{"number":198,"text":"ἐπαγγειλαμένου δὲ πορεύσεσθαι καὶ δεῖσθαι χρημάτων οὐ πολλῶν φήσαντος εἰς τὴν ὁδόν, ζήσεσθαι γὰρ ἐπιεικῶς ὥστε ἀρκέσειν αὐτῷ δραχμὰς μυρίας, ἥσθη τοῦ παιδὸς τῇ σωφροσύνῃ."},{"number":199,"text":"διαλιπὼν δὲ ὀλίγον ὁ παῖς συνεβούλευε τῷ πατρὶ δῶρα μὲν αὐτόθεν μὴ πέμπειν τῷ βασιλεῖ, δοῦναι δὲ ἐπιστολὴν πρὸς τὸν ἐν Ἀλεξανδρείᾳ οἰκονόμον, ὅπως αὐτῷ παρέχῃ πρὸς ὠνὴν ὧν ἂν εὕρῃ καλλίστων καὶ πολυτελῶν χρήματα."},{"number":200,"text":"ὁ δὲ νομίζων δέκα ταλάντων ἔσεσθαι τὴν εἰς τὰς δωρεὰς τῷ βασιλεῖ δαπάνην καὶ τὸν υἱὸν ἐπαινέσας ὡς παραινοῦντα καλῶς, γράφει τῷ οἰκονόμῳ Ἀρίονι, ὃς ἅπαντα τὰ ἐν Ἀλεξανδρείᾳ χρήματα αὐτοῦ διῴκει οὐκ ὄντα ἐλάσσω τρισχιλίων ταλάντων·"},{"number":201,"text":"ὁ γὰρ Ἰώσηπος τὰ ἀπὸ τῆς Συρίας χρήματα ἔπεμπεν εἰς Ἀλεξάνδρειαν καὶ τῆς προθεσμίας ἐνισταμένης, καθʼ ἣν ἔδει τῷ βασιλεῖ τοὺς φόρους ἀπαριθμεῖν, ἔγραφεν τῷ Ἀρίονι τοῦτο ποιεῖν."},{"number":202,"text":"πρὸς οὖν τοῦτον ἀπαιτήσας τὸν πατέρα ἐπιστολήν, λαβὼν εἰς τὴν Ἀλεξάνδρειαν ὥρμησεν. ἐξελθόντος δʼ αὐτοῦ γράφουσιν οἱ ἀδελφοὶ πᾶσι τοῖς τοῦ βασιλέως φίλοις, ἵνʼ αὐτὸν διαφθείρωσιν."},{"number":203,"text":"Ὡς δὲ παραγενόμενος εἰς τὴν Ἀλεξάνδρειαν ἀπέδωκε τῷ Ἀρίονι τὴν ἐπιστολήν, ἐπερωτήσαντος αὐτοῦ, πόσα βούλεται τάλαντα λαβεῖν, ἤλπισε δʼ αὐτὸν αἰτήσειν δέκα ἢ βραχεῖ τούτων πλέον, εἰπόντος χιλίων χρῄζειν ὀργισθεὶς ἐπέπληττεν αὐτῷ ὡς ἀσώτως ζῆν διεγνωκότι, καὶ πῶς ὁ πατὴρ αὐτοῦ συναγάγοι τὴν οὐσίαν ὡς πονῶν καὶ ταῖς ἐπιθυμίαις ἀντέχων ἐδήλου καὶ μιμητὴν αὐτὸν ἠξίου γενέσθαι τοῦ γεγεννηκότος· δώσειν δʼ οὐδὲν πλέον ταλάντων δέκα καὶ ταῦτα εἰς δωρεὰς τῷ βασιλεῖ."},{"number":204,"text":"παροξυνθεὶς δʼ ὁ παῖς εἰς δεσμὰ τὸν Ἀρίονα ἐνέβαλεν. τῆς δὲ τοῦ Ἀρίονος γυναικὸς τοῦτο δηλωσάσης τῇ Κλεοπάτρᾳ καὶ δεηθείσης, ὅπως ἐπιπλήξῃ τῷ παιδί, σφόδρα γὰρ ἦν ὁ Ἀρίων ἐν τιμῇ παρʼ αὐτῇ, φανερὸν τῷ βασιλεῖ τοῦτο ἐποίησεν ἡ Κλεοπάτρα."},{"number":205,"text":"ὁ δὲ Πτολεμαῖος πέμψας πρὸς τὸν Ὑρκανὸν θαυμάζειν ἔλεγεν, πῶς ἀποσταλεὶς πρὸς αὐτὸν ὑπὸ τοῦ πατρὸς οὔτε ὀφθείη αὐτῷ καὶ προσέτι δήσειεν τὸν οἰκονόμον·"},{"number":206,"text":"ἐλθόντα οὖν τὴν αἰτίαν αὐτῷ μηνύειν ἐκέλευσεν. τὸν δέ φασιν ἀποκρίνασθαι τῷ παρὰ τοῦ βασιλέως λέγειν αὐτῷ, ὅτι νόμος ἐστὶ παρʼ αὐτῷ κωλύων τὸν γεννηθέντα γεύσασθαι θυσιῶν, πρὶν εἰς τὸ ἱερὸν ἔλθῃ καὶ θύσῃ τῷ θεῷ· κατὰ δὴ τοῦτον τὸν λογισμὸν οὐδʼ αὐτὸς ἐλθεῖν πρὸς αὐτὸν περιμένων τὰ δῶρα κομίσαι τοῦ πατρὸς εὐεργέτῃ γεγενημένῳ."},{"number":207,"text":"τὸν δὲ δοῦλον κολάσαι παρακούσαντα ὧν προσέταξεν· διαφέρειν γὰρ οὐδὲν ἢ μικρὸν εἶναί τινα δεσπότην ἢ μέγαν· ἂν οὖν μὴ κολάζωμεν τοὺς τοιούτους, καὶ σὺ προσδόκα ὑπὸ τῶν ἀρχομένων καταφρονηθήσεσθαι. ταῦτʼ ἀκούσας ὁ Πτολεμαῖος εἰς γέλωτα ἐτράπη καὶ τὴν μεγαλοφροσύνην τοῦ παιδὸς ἐθαύμασεν."},{"number":208,"text":"Μαθὼν δὲ ὁ Ἀρίων, ὅτι τοῦτον ὁ βασιλεὺς διετέθη τὸν τρόπον καὶ μηδεμία βοήθειά ἐστιν αὐτῷ, δοὺς τὰ χίλια τάλαντα τῷ παιδὶ τῶν δεσμῶν ἀπελύθη. καὶ τρεῖς διαλιπὼν ἡμέρας ὁ Ὑρκανὸς ἠσπάσατο τοὺς βασιλέας."},{"number":209,"text":"οἱ δὲ ἀσμένως αὐτὸν εἶδον καὶ φιλοφρόνως εἱστίασαν διὰ τὴν πρὸς τὸν πατέρα τιμήν. λάθρα δὲ πρὸς τοὺς ἐμπόρους ἀπελθὼν ὠνεῖται παρʼ αὐτῶν παῖδας μὲν ἑκατὸν γράμματα ἐπισταμένους καὶ ἀκμαιοτάτους, ἑνὸς ἕκαστον ταλάντου, ἑκατὸν δὲ παρθένους τῆς αὐτῆς τιμῆς ἑκάστην."},{"number":210,"text":"κληθεὶς δʼ ἐφʼ ἑστίασιν πρὸς τὸν βασιλέα μετὰ τῶν πρώτων τῆς χώρας ὑποκατακλίνεται πάντων, καταφρονηθεὶς ὡς παῖς ἔτι τὴν ἡλικίαν ὑπὸ τῶν τοὺς τόπους κατὰ τὴν ἀξίαν διανεμόντων."},{"number":211,"text":"τῶν δὲ συγκατακειμένων πάντων τῶν μερῶν τὰ ὀστᾶ, ἀφῄρουν γὰρ αὐτοὶ τὰς σάρκας, σωρευόντων ἔμπροσθεν τοῦ Ὑρκανοῦ, ὡς πληρῶσαι τὴν παρακειμένην αὐτῷ τράπεζαν,"},{"number":212,"text":"Τρύφων ὃς ἦν τοῦ βασιλέως ἄθυρμα καὶ πρὸς τὰ σκώμματα καὶ τοὺς ἐν τοῖς πότοις γέλωτας ἀπεδέδεικτο, παρακαλεσάντων αὐτὸν τῶν κατακειμένων τῇ τραπέζῃ παρεστὼς τῷ βασιλεῖ, ὁρᾷς, εἶπεν, ὦ δέσποτα, τὰ παρακείμενα Ὑρκανῷ ὀστᾶ; ἐκ τούτου στόχασαι, ὅτι καὶ ὁ πατὴρ αὐτοῦ τὴν Συρίαν ἅπασαν περιέδυσεν ὡς οὗτος ταῦτα τῶν σαρκῶν ἐγύμνωσεν."},{"number":213,"text":"γελάσαντος δὲ πρὸς τὸν τοῦ Τρύφωνος λόγον τοῦ βασιλέως καὶ ἐρομένου τὸν Ὑρκανόν, ὅτι τοσαῦτʼ αὐτῷ παράκειται ὀστᾶ, εἰκότως, εἶπεν, ὦ δέσποτα· τοὺς μὲν γὰρ κύνας τὰ ὀστᾶ σὺν τοῖς κρέασιν κατεσθίειν, ὥσπερ οὗτοι πρὸς τοὺς κατακειμένους ἐπιβλέπων, ὅτι μηθὲν ἔμπροσθεν αὐτῶν ἔκειτο, οἱ δὲ ἄνθρωποι τὸ κρέας ἐσθίουσιν, τὰ δʼ ὀστᾶ ῥίπτουσιν, ὅπερ ἄνθρωπος ὢν κἀγὼ νῦν πεποίηκα."},{"number":214,"text":"ὁ δὲ βασιλεὺς θαυμάζει τὴν ἀπόκρισιν αὐτοῦ σοφὴν οὕτως γενομένην καὶ πάντας ἐκέλευσεν ἀνακροτῆσαι τῆς εὐτραπελίας ἀποδεχόμενος αὐτόν."},{"number":215,"text":"τῇ δʼ ἐπιούσῃ πρὸς ἕκαστον τῶν τοῦ βασιλέως φίλων πορευόμενος καὶ τῶν περὶ τὴν αὐλὴν δυνατῶν τοὺς μὲν ἠσπάζετο, παρὰ δὲ τῶν οἰκετῶν ἀπεπυνθάνετο, τί μέλλουσιν διδόναι τῷ βασιλεῖ δῶρον ἐν τῇ τοῦ παιδὸς αὐτοῦ γενεσίῳ."},{"number":216,"text":"τῶν δὲ ἀνὰ δέκα τάλαντα μέλλειν διδόναι φησάντων τοὺς μέν, τοὺς δὲ ἐν ἀξίᾳ κατὰ τὸ μέγεθος τῆς οὐσίας ἕκαστον αὐτῶν, ὑπεκρίνετο λυπεῖσθαι διὰ τὸ μὴ δύνασθαι τοιαύτην προσενεγκεῖν δωρεάν· πλέον γὰρ πέντε ταλάντων οὐκ ἔχειν. οἱ δὲ θεράποντες ταῦτʼ ἀκούσαντες ἀπήγγελλον τοῖς δεσπόταις."},{"number":217,"text":"χαιρόντων δʼ αὐτῶν ὡς καταγνωσθησομένου τοῦ Ἰωσήπου καὶ προσκρούσοντος τῷ βασιλεῖ διὰ τὴν βραχύτητα τῆς δωρεᾶς, ἐνστάσης τῆς ἡμέρας οἱ μὲν ἄλλοι προσέφερον τῷ βασιλεῖ ταλάντων οἱ λίαν μεγαλοδωρεῖσθαι νομίζοντες οὐ πλεῖον εἴκοσι, ὁ δʼ Ὑρκανὸς οὓς ὠνήσατο παῖδας ἑκατὸν καὶ παρθένους τοσαύτας ἀνὰ τάλαντον ἑκάστῳ φέρειν δοὺς προσήγαγεν τοὺς μὲν τῷ βασιλεῖ, τὰς δὲ τῇ Κλεοπάτρᾳ."},{"number":218,"text":"πάντων δὲ θαυμασάντων τὴν παρʼ ἐλπίδα τῶν δώρων πολυτέλειαν καὶ τῶν βασιλέων αὐτῶν, καὶ τοῖς φίλοις ἔτι καὶ τοῖς περὶ τὴν θεραπείαν τοῦ βασιλέως οὖσιν πολλῶν ἄξια ταλάντων δῶρα ἔδωκεν, ὡς διαφυγεῖν τὸν ἐξ αὐτῶν κίνδυνον· τούτοις γὰρ ἐγεγράφεισαν αὐτοῦ οἱ ἀδελφοὶ διαχρήσασθαι τὸν Ὑρκανόν."},{"number":219,"text":"Πτολεμαῖος δὲ τὴν μεγαλοψυχίαν ἀγασάμενος τοῦ μειρακίου προσέταξεν αὐτῷ δωρεὰν ἣν βούλεται λαμβάνειν. ὁ δʼ οὐδὲν πλέον ἠξίωσεν αὐτῷ γενέσθαι παρʼ αὐτοῦ ἢ γράψαι τῷ πατρὶ καὶ τοῖς ἀδελφοῖς περὶ αὐτοῦ."},{"number":220,"text":"τιμήσας οὖν αὐτὸν φιλοτιμότατα καὶ δωρεὰς δοὺς λαμπρὰς καὶ τῷ τε πατρὶ γράψας καὶ τοῖς ἀδελφοῖς καὶ πᾶσι τοῖς ἡγεμόσιν αὐτοῦ καὶ ἐπιτρόποις ἐξέπεμψεν."},{"number":221,"text":"ἀκούσαντες δὲ οἱ ἀδελφοὶ τούτων τετυχηκότα τὸν Ὑρκανὸν παρὰ τοῦ βασιλέως καὶ μετὰ μεγάλης ἐπανερχόμενον τιμῆς, ἐξῆλθον ὑπαντησόμενοι καὶ διαφθεροῦντες αὐτὸν καὶ τοῦ πατρὸς εἰδότος· ὀργιζόμενος γὰρ αὐτῷ ἕνεκεν τῶν εἰς τὰς δωρεὰς χρημάτων οὐκ ἐφρόντιζεν τῆς σωτηρίας αὐτοῦ. τὴν ὀργὴν μέντοι τὴν πρὸς τὸν υἱὸν ὁ Ἰώσηπος ἀπεκρύπτετο φοβούμενος τὸν βασιλέα."},{"number":222,"text":"συμβαλόντων δʼ αὐτῷ τῶν ἀδελφῶν εἰς μάχην ἄλλους τε τῶν σὺν αὐτοῖς πολλοὺς ἀπέκτεινεν καὶ δύο τῶν ἀδελφῶν, οἱ δὲ λοιποὶ διεσώθησαν εἰς Ἱεροσόλυμα πρὸς τὸν πατέρα. παραγενόμενον δʼ αὐτὸν εἰς τὴν πόλιν ἐπεὶ μηδεὶς ἐδέχετο, δείσας ἀνεχώρησεν εἰς τὴν πέραν τοῦ Ἰορδάνου ποταμοῦ κἀκεῖ διέτριβεν φορολογῶν τοὺς βαρβάρους."},{"number":223,"text":"Ἐβασίλευσεν δὲ κατʼ ἐκεῖνον τὸν καιρὸν τῆς Ἀσίας Σέλευκος ὁ Σωτὴρ ἐπικαλούμενος υἱὸς ὢν Ἀντιόχου τοῦ μεγάλου."},{"number":224,"text":"τελευτᾷ δὲ καὶ ὁ τοῦ Ὑρκανοῦ πατὴρ Ἰώσηπος ἀνὴρ ἀγαθὸς γενόμενος καὶ μεγαλόφρων, καὶ τὸν τῶν Ἰουδαίων λαὸν ἐκ πτωχείας καὶ πραγμάτων ἀσθενῶν εἰς λαμπροτέρας ἀφορμὰς τοῦ βίου καταστήσας, εἴκοσι ἔτη καὶ δύο τὰ τέλη τῆς Συρίας καὶ τῆς Φοινίκης καὶ Σαμαρείας κατασχών. ἀπέθανεν δὲ καὶ ὁ θεῖος αὐτοῦ Ὀνίας τὴν ἀρχιερωσύνην Σίμωνι τῷ παιδὶ καταλιπών."},{"number":225,"text":"Τελευτήσαντος δὲ καὶ τούτου ὁ υἱὸς αὐτοῦ διάδοχος τῆς τιμῆς Ὀνίας γίνεται, πρὸς ὃν ὁ Λακεδαιμονίων βασιλεὺς Ἄρειος πρεσβείαν τε ἔπεμψεν καὶ ἐπιστολάς, ὧν τὸ ἀντίγραφόν ἐστι τοιοῦτο· βασιλεὺς Λακεδαιμονίων Ἄρειος Ὀνίᾳ χαίρειν."},{"number":226,"text":"ἐντυχόντες γραφῇ τινι εὕρομεν, ὡς ἐξ ἑνὸς εἶεν γένους Ἰουδαῖοι καὶ Λακεδαιμόνιοι καὶ ἐκ τῆς πρὸς Ἄβραμον οἰκειότητος. δίκαιον οὖν ἐστιν ἀδελφοὺς ὑμᾶς ὄντας διαπέμπεσθαι πρὸς ἡμᾶς περὶ ὧν ἂν βούλησθε."},{"number":227,"text":"ποιήσομεν δὲ καὶ ἡμεῖς τοῦτο, καὶ τά τε ὑμέτερα ἴδια νομιοῦμεν καὶ τὰ αὑτῶν κοινὰ πρὸς ὑμᾶς ἕξομεν. Δημοτέλης ὁ φέρων τὰ γράμματα διαπέμπει τὰς ἐπιστολάς. τὰ γεγραμμένα ἐστὶν τετράγωνα· ἡ σφραγίς ἐστιν ἀετὸς δράκοντος ἐπειλημμένος."},{"number":228,"text":"Ἡ μὲν οὖν ἐπιστολὴ ἡ πεμφθεῖσα ὑπὸ τοῦ Λακεδαιμονίων βασιλέως τοῦτον περιεῖχε τὸν τρόπον. ἀποθανόντος δὲ Ἰωσήπου τὸν λαὸν συνέβη στασιάσαι διὰ τοὺς παῖδας αὐτοῦ. τῶν γὰρ πρεσβυτέρων πόλεμον ἐξενεγκαμένων πρὸς Ὑρκανόν, ὃς ἦν νεώτατος τῶν Ἰωσήπου τέκνων, διέστη τὸ πλῆθος."},{"number":229,"text":"καὶ οἱ μὲν πλείους τοῖς πρεσβυτέροις συνεμάχουν καὶ ὁ ἀρχιερεὺς Σίμων διὰ τὴν συγγένειαν· ὁ δὲ Ὑρκανὸς ἐπανελθεῖν μὲν οὐκέτι ἔγνω εἰς Ἱεροσόλυμα, προσκαθίσας δὲ τοῖς πέραν τοῦ Ἰορδάνου συνεχῶς ἐπολέμει τοὺς Ἄραβας, ὡς πολλοὺς αὐτῶν καὶ ἀποκτεῖναι καὶ λαβεῖν αἰχμαλώτους."},{"number":230,"text":"ᾠκοδόμησεν δὲ βᾶριν ἰσχυρὰν ἐκ λίθου λευκοῦ κατασκευάσας πᾶσαν μέχρι καὶ τῆς στέγης ἐγγλύψας ζῷα παμμεγεθέστατα, περιήγαγεν δʼ αὐτῇ εὔριπον μέγαν καὶ βαθύν."},{"number":231,"text":"ἐκ δὲ τῆς καταντικρὺ τοῦ ὄρους πέτρας διατεμὼν αὐτῆς τὸ προέχον σπήλαια πολλῶν σταδίων τὸ μῆκος κατεσκεύασεν. ἔπειτα οἴκους ἐν αὐτῇ τοὺς μὲν εἰς συμπόσια τοὺς δʼ εἰς ὕπνον καὶ δίαιταν ἐποίησεν, ὑδάτων δὲ διαθεόντων πλῆθος, ἃ καὶ τέρψις ἦν καὶ κόσμος τῆς αὐλῆς, εἰσήγαγεν."},{"number":232,"text":"τὰ μέντοι στόμια τῶν σπηλαίων ὥστε ἕνα διʼ αὐτῶν εἰσδῦναι καὶ μὴ πλείους βραχύτερα ἤνοιξεν· καὶ ταῦτʼ ἐπίτηδες ἀσφαλείας ἕνεκα τοῦ μὴ πολιορκηθεὶς ὑπὸ τῶν ἀδελφῶν καὶ κινδυνεῦσαι ληφθεὶς κατεσκεύασεν."},{"number":233,"text":"προσῳκοδόμησε δὲ καὶ αὐλὰς τῷ μεγέθει διαφερούσας καὶ παραδείσοις ἐκόσμησε παμμήκεσι. καὶ τοιοῦτον ἀπεργασάμενος τὸν τόπον Τύρον ὠνόμασεν. οὗτος ὁ τόπος ἐστὶ μεταξὺ τῆς Ἀραβίας καὶ τῆς Ἰουδαίας πέραν τοῦ Ἰορδάνου οὐ πόρρω τῆς Ἐσσεβωνίτιδος."},{"number":234,"text":"ἦρξε δʼ ἐκείνων τῶν μερῶν ἐπὶ ἔτη ἑπτά, πάντα τὸν χρόνον ὃν Σέλευκος τῆς Συρίας ἐβασίλευσεν. ἀποθανόντος δὲ τούτου μετʼ αὐτὸν ὁ ἀδελφὸς Ἀντίοχος ὁ κληθεὶς Ἐπιφανὴς τὴν βασιλείαν κατέσχεν."},{"number":235,"text":"τελευτᾷ δὲ καὶ Πτολεμαῖος ὁ τῆς Αἰγύπτου βασιλεὺς καὶ αὐτὸς ἐπικαλούμενος Ἐπιφανής, καταλιπὼν δύο παῖδας ἔτι βραχεῖς τὴν ἡλικίαν, ὧν ὁ μὲν πρεσβύτερος Φιλομήτωρ ἐκαλεῖτο, Φύσκων δὲ ὁ νεώτερος."},{"number":236,"text":"Ὑρκανὸς δὲ ὁρῶν μεγάλην δύναμιν ἔχοντα τὸν Ἀντίοχον καὶ δείσας, μὴ συλληφθεὶς ὑπʼ αὐτοῦ κολασθῇ διὰ τὰ πρὸς τοὺς Ἄραβας αὐτῷ πεπραγμένα, τελευτᾷ τὸν βίον αὐτόχειρ αὐτοῦ γενόμενος. τὴν δʼ οὐσίαν αὐτοῦ πᾶσαν Ἀντίοχος λαμβάνει."}],"5":[{"number":237,"text":"Ὑπὸ δὲ τὸν αὐτὸν καιρὸν ἀποθανόντος καὶ Ὀνίου τοῦ ἀρχιερέως τῷ ἀδελφῷ αὐτοῦ Ἰησοῦ τὴν ἀρχιερωσύνην Ἀντίοχος δίδωσιν· ὁ γὰρ παῖς, ὃν Ὀνίας καταλελοίπει, ἔτι νήπιος ἦν. δηλώσομεν δὲ τὰ περὶ τοῦ παιδὸς τούτου κατὰ χώραν ἕκαστα."},{"number":238,"text":"Ἰησοῦς δέ, οὗτος γὰρ ἦν ὁ τοῦ Ὀνίου ἀδελφός, τὴν ἀρχιερωσύνην ἀφῃρέθη προσοργισθέντος αὐτῷ τοῦ βασιλέως καὶ δόντος αὐτὴν τῷ νεωτάτῳ αὐτοῦ ἀδελφῷ Ὀνίᾳ τοὔνομα. Σίμωνι γὰρ οὗτοι τρεῖς ἐγένοντο παῖδες, καὶ εἰς τοὺς τρεῖς ἧκεν ἡ ἀρχιερωσύνη, καθὼς δεδηλώκαμεν."},{"number":239,"text":"ὁ μὲν οὖν Ἰησοῦς Ἰάσονα αὑτὸν μετωνόμασεν, ὁ δὲ Ὀνίας ἐκλήθη Μενέλαος. στασιάσαντος οὖν τοῦ προτέρου ἀρχιερέως Ἰησοῦ πρὸς τὸν μετὰ ταῦτα κατασταθέντα Μενέλαον καὶ τοῦ πλήθους διανεμηθέντος εἰς ἑκατέρους, ἐκ τῆς Μενελάου μοίρας οἱ Τωβίου παῖδες ἐγένοντο,"},{"number":240,"text":"τὸ δὲ πλέον τοῦ λαοῦ τῷ Ἰάσονι συνελάμβανεν, ὑφʼ οὗ καὶ πονούμενοι ὅ τε Μενέλαος καὶ οἱ παῖδες οἱ τοῦ Τωβίου πρὸς Ἀντίοχον ἀνεχώρησαν δηλοῦντες αὐτῷ, ὅτι βούλονται τοὺς πατρίους νόμους καταλιπόντες καὶ τὴν κατʼ αὐτοὺς πολιτείαν ἕπεσθαι τοῖς βασιλικοῖς καὶ τὴν Ἑλληνικὴν πολιτείαν ἔχειν."},{"number":241,"text":"παρεκάλεσαν οὖν αὐτὸν ἐπιτρέψαι αὐτοῖς οἰκοδομῆσαι γυμνάσιον ἐν Ἱεροσολύμοις. συγχωρήσαντος δὲ καὶ τὴν τῶν αἰδοίων περιτομὴν ἐπεκάλυψαν, ὡς ἂν εἶεν καὶ τὰ περὶ τὴν ἀπόδυσιν Ἕλληνες, τά τε ἄλλα πάνθʼ ὅσα ἦν αὐτοῖς πάτρια παρέντες ἐμιμοῦντο τὰ τῶν ἄλλων ἐθνῶν ἔργα."},{"number":242,"text":"Ἀντίοχος δὲ τῆς βασιλείας αὐτῷ χωρούσης κατὰ τρόπον ἐπὶ τὴν Αἴγυπτον διέγνω στρατεύσασθαι, πόθον αὐτῆς λαβὼν καὶ διὰ τὸ τῶν Πτολεμαίου παίδων καταφρονεῖν ἀσθενῶν ἔτι τυγχανόντων καὶ μηδέπω πράγματα τηλικαῦτα διέπειν δυναμένων."},{"number":243,"text":"γενόμενος οὖν μετὰ πολλῆς δυνάμεως κατὰ τὸ Πηλούσιον καὶ δόλῳ τὸν Φιλομήτορα Πτολεμαῖον ἐκπεριελθὼν καταλαμβάνει τὴν Αἴγυπτον, καὶ γενόμενος ἐν τοῖς περὶ Μέμφιν τόποις καὶ κατασχὼν ταύτην ὥρμησεν ἐπὶ τὴν Ἀλεξάνδρειαν, ὡς πολιορκίᾳ παραστησόμενος αὐτὴν καὶ τὸν ἐκεῖ βασιλεύοντα χειρωσόμενος Πτολεμαῖον."},{"number":244,"text":"ἀπεκρούσθη δʼ οὐ τῆς Ἀλεξανδρείας μόνον, ἀλλὰ καὶ τῆς ὅλης Αἰγύπτου, Ῥωμαίων αὐτῷ παραγγειλάντων ἀπέχεσθαι τῆς χώρας, καθὼς ἤδη που καὶ πρότερον ἐν ἄλλοις δεδηλώκαμεν."},{"number":245,"text":"διηγήσομαι δὲ κατὰ μέρος τὰ περὶ τοῦτον τὸν βασιλέα, ὡς τήν τε Ἰουδαίαν ἐχειρώσατο καὶ τὸν ναόν· ἐν γὰρ τῇ πρώτῃ μου πραγματείᾳ κεφαλαιωδῶς αὐτῶν ἐπιμνησθεὶς ἀναγκαῖον ἡγησάμην νῦν εἰς τὴν ἐπʼ ἀκριβὲς αὐτῶν ἐπανελθεῖν ὑφήγησιν."},{"number":246,"text":"Ὑποστρέψας ἀπὸ τῆς Αἰγύπτου διὰ τὸ παρὰ Ῥωμαίων δέος ὁ βασιλεὺς Ἀντίοχος ἐπὶ τὴν Ἱεροσολυμιτῶν πόλιν ἐξεστράτευσεν, καὶ γενόμενος ἐν αὐτῇ ἔτει ἑκατοστῷ καὶ τεσσαρακοστῷ καὶ τρίτῳ μετὰ τοὺς ἀπὸ Σελεύκου βασιλεῖς ἀμαχητὶ λαμβάνει τὴν πόλιν ἀνοιξάντων αὐτῷ τὰς πύλας ὅσοι τῆς ἐκείνου προαιρέσεως ἦσαν."},{"number":247,"text":"ἐγκρατὴς δʼ οὕτως τῶν Ἱεροσολύμων γενόμενος πολλοὺς ἀπέκτεινεν τῶν τἀναντία φρονούντων καὶ χρήματα πολλὰ συλήσας ὑπέστρεψεν εἰς Ἀντιόχειαν."},{"number":248,"text":"Συνέβη δὲ μετὰ ἔτη δύο τῷ ἑκατοστῷ καὶ τεσσαρακοστῷ καὶ πέμπτῳ ἔτει μηνὸς πέμπτῃ καὶ εἰκάδι, ὃς καλεῖται κατὰ μὲν ἡμᾶς Ἐξελέους, κατὰ δὲ Μακεδόνας Ἀπελλαῖος, ὀλυμπιάδι ἑκατοστῇ καὶ πεντηκοστῇ καὶ τρίτῃ μετὰ πολλῆς δυνάμεως ἀναβῆναι τὸν βασιλέα εἰς Ἱεροσόλυμα καὶ προσποιησάμενον εἰρήνην ἀπάτῃ περιγενέσθαι τῆς πόλεως."},{"number":249,"text":"ἐφείσατο δὲ τότε οὐδὲ τῶν εἰσδεξαμένων αὐτὸν διὰ τὸν ἐν τῷ ναῷ πλοῦτον, ἀλλʼ ὑπὸ πλεονεξίας, χρυσὸν γὰρ ἑώρα πολὺν ἐν τῷ ἱερῷ καὶ τὸν ἄλλον τῶν ἀναθημάτων κόσμον πολυτελέστατον, ἵνα συλήσῃ τοῦτον, ὑπέμεινε τὰς πρὸς ἐκείνους αὐτῷ σπονδὰς παραβῆναι."},{"number":250,"text":"περιδύσας οὖν τὸν ναόν, ὡς καὶ τὰ σκεύη τοῦ θεοῦ βαστάσαι λυχνίας χρυσᾶς καὶ βωμὸν χρύσεον καὶ τράπεζαν καὶ τὰ θυσιαστήρια, καὶ μηδὲ τῶν καταπετασμάτων ἀποσχόμενος, ἅπερ ἦν ἐκ βύσσου καὶ κόκκου πεποιημένα, κενώσας δὲ καὶ τοὺς θησαυροὺς τοὺς ἀποκρύφους καὶ μηδὲν ὅλως ὑπολιπών, εἰς μέγα τοὺς Ἰουδαίους ἐπὶ τούτοις πένθος ἐνέβαλεν."},{"number":251,"text":"καὶ γὰρ τὰς καθημερινὰς θυσίας, ἃς προσέφερον τῷ θεῷ κατὰ τὸν νόμον, ἐκώλυσεν αὐτοὺς προσφέρειν, καὶ διαρπάσας πᾶσαν τὴν πόλιν τοὺς μὲν ἀπέκτεινεν τοὺς δʼ αἰχμαλώτους γυναιξὶν ἅμα καὶ τέκνοις ἔλαβεν, ὡς τῶν ζωγρηθέντων περὶ μυρίους γενέσθαι τὸ πλῆθος."},{"number":252,"text":"ἐνέπρησε δʼ αὐτῆς τὰ κάλλιστα καὶ καταβαλὼν τὰ τείχη τὴν ἐν τῇ κάτω πόλει ᾠκοδόμησεν ἄκραν· ἦν γὰρ ὑψηλὴ καὶ ὑπερκειμένη τὸ ἱερόν· καὶ διὰ τοῦτο αὐτὴν ὀχυρώσας τείχεσιν ὑψηλοῖς καὶ πύργοις φρουρὰν Μακεδονικὴν ἐγκατέστησεν. ἔμενον δʼ οὐδὲν ἧττον ἐν τῇ ἄκρᾳ καὶ τοῦ πλήθους οἱ ἀσεβεῖς καὶ πονηροὶ τὸν τρόπον, ὑφʼ ὧν πολλὰ καὶ δεινὰ τοὺς πολίτας συνέβη παθεῖν."},{"number":253,"text":"ἐποικοδομήσας δὲ καὶ τῷ θυσιαστηρίῳ βωμὸν ὁ βασιλεὺς σύας ἐπʼ αὐτοῦ κατέσφαξε, θυσίαν οὐ νόμιμον οὐδὲ πάτριον τῇ Ἰουδαίων θρησκείᾳ ταύτην ἐπιτελῶν. ἠνάγκασε δʼ αὐτοὺς ἀφεμένους τὴν περὶ τὸν αὐτῶν θεὸν θρησκείαν τοὺς ὑπʼ αὐτοῦ νομιζομένους σέβεσθαι, οἰκοδομήσαντας δὲ ἐν ἑκάστῃ πόλει καὶ κώμῃ τεμένη αὐτῶν καὶ βωμοὺς καθιδρύσαντας θύειν ἐπʼ αὐτοῖς σῦς καθʼ ἡμέραν."},{"number":254,"text":"ἐκέλευσε δὲ καὶ μὴ περιτέμνειν αὐτοὺς τὰ τέκνα, κολάσειν ἀπειλήσας εἴ τις παρὰ ταῦτα ποιῶν εὑρεθείη. κατέστησε δὲ καὶ ἐπισκόπους, οἳ προσαναγκάσουσιν αὐτοὺς τὰ ἐπεσταλμένα ποιεῖν."},{"number":255,"text":"καὶ πολλοὶ μὲν τῶν Ἰουδαίων οἱ μὲν ἑκοντὶ οἱ δὲ καὶ διʼ εὐλάβειαν τῆς ἐπηγγελμένης τιμωρίας κατηκολούθουν οἷς ὁ βασιλεὺς διετέτακτο, οἱ δὲ δοκιμώτατοι καὶ τὰς ψυχὰς εὐγενεῖς οὐκ ἐφρόντισαν αὐτοῦ, τῶν δὲ πατρίων ἐθῶν πλείονα λόγον ἔσχον ἢ τῆς τιμωρίας, ἣν οὐ πειθομένοις ἠπείλησεν αὐτοῖς, καὶ διὰ τοῦτο κατὰ πᾶσαν ἡμέραν αἰκιζόμενοι καὶ πικρὰς βασάνους ὑπομένοντες ἀπέθνησκον."},{"number":256,"text":"καὶ γὰρ μαστιγούμενοι καὶ τὰ σώματα λυμαινόμενοι ζῶντες ἔτι καὶ ἐμπνέοντες ἀνεσταυροῦντο, τὰς δὲ γυναῖκας καὶ τοὺς παῖδας αὐτῶν, οὓς περιέτεμνον παρὰ τὴν τοῦ βασιλέως προαίρεσιν, ἀπῆγχον ἐκ τῶν τραχήλων αὐτοὺς τῶν ἀνεσταυρωμένων γονέων ἀπαρτῶντες. ἠφανίζετο δʼ εἴ που βίβλος εὑρεθείη ἱερὰ καὶ νόμος, καὶ παρʼ οἷς εὑρέθη καὶ αὐτοὶ κακοὶ κακῶς ἀπώλλυντο."},{"number":257,"text":"Ταῦτα βλέποντες οἱ Σαμαρεῖται πάσχοντας τοὺς Ἰουδαίους οὐκέθʼ ὡμολόγουν αὑτοὺς εἶναι συγγενεῖς αὐτῶν οὐδὲ τὸν ἐν Γαριζεὶν ναὸν τοῦ μεγίστου θεοῦ, τῇ φύσει ποιοῦντες ἀκόλουθα, ἣν δεδηλώκαμεν, καὶ λέγοντες αὑτοὺς Μήδων ἀποίκους καὶ Περσῶν· καὶ γάρ εἰσιν τούτων ἄποικοι."},{"number":258,"text":"πέμψαντες οὖν πρὸς τὸν Ἀντίοχον πρέσβεις καὶ ἐπιστολὴν ἐδήλουν τὰ ὑπογεγραμμένα· βασιλεῖ Ἀντιόχῳ θεῷ ἐπιφανεῖ ὑπόμνημα παρὰ τῶν ἐν Σικίμοις Σιδωνίων."},{"number":259,"text":"οἱ ἡμέτεροι πρόγονοι διά τινας αὐχμοὺς τῆς χώρας παρακολουθήσαντες ἀρχαίᾳ τινὶ δεισιδαιμονίᾳ ἔθος ἐποίησαν σέβειν τὴν παρὰ τοῖς Ἰουδαίοις λεγομένην σαββάτων ἡμέραν, ἱδρυσάμενοι δὲ ἀνώνυμον ἐν τῷ Γαριζεὶν λεγομένῳ ὄρει ἱερὸν ἔθυον ἐπʼ αὐτοῦ τὰς καθηκούσας θυσίας."},{"number":260,"text":"σοῦ δὲ τοῖς Ἰουδαίοις τῆς πονηρίας αὐτῶν ἀξίως χρησαμένου, οἱ τὰ βασιλικὰ διοικοῦντες οἰόμενοι κατὰ συγγένειαν ἡμᾶς ταὐτὰ ποιεῖν ἐκείνοις ταῖς ὁμοίαις αἰτίαις περιάπτουσιν, ὄντων ἡμῶν τὸ ἀνέκαθεν Σιδωνίων, καὶ τοῦτο φανερόν ἐστιν ἐκ τῶν πολιτικῶν ἀναγραφῶν."},{"number":261,"text":"ἀξιοῦμεν οὖν σε τὸν εὐεργέτην καὶ σωτῆρα προστάξαι Ἀπολλωνίῳ τῷ μεριδάρχῃ καὶ Νικάνορι τῷ τὰ βασιλικὰ πράττοντι μηδὲν ἡμῖν ἐνοχλεῖν προσάπτουσι τὰς τῶν Ἰουδαίων αἰτίας, ἡμῶν καὶ τῷ γένει καὶ τοῖς ἔθεσιν ἀλλοτρίων ὑπαρχόντων, προσαγορευθῆναι δὲ τὸ ἀνώνυμον ἱερὸν Διὸς Ἑλληνίου· γενομένου γὰρ τούτου παυσόμεθα μὲν ἐνοχλούμενοι, τοῖς δʼ ἔργοις μετὰ ἀδείας προσανέχοντες μείζονάς σοι ποιήσομεν τὰς προσόδους."},{"number":262,"text":"ταῦτα τῶν Σαμαρέων δεηθέντων ἀντέγραψεν αὐτοῖς ὁ βασιλεὺς τάδε· βασιλεὺς Ἀντίοχος Νικάνορι. οἱ ἐν Σικίμοις Σιδώνιοι ἐπέδωκαν τὸ κατακεχωρισμένον ὑπόμνημα."},{"number":263,"text":"ἐπεὶ οὖν συμβουλευομένοις ἡμῖν μετὰ τῶν φίλων παρέστησαν οἱ πεμφθέντες ὑπʼ αὐτῶν, ὅτι μηδὲν τοῖς τῶν Ἰουδαίων ἐγκλήμασι προσήκουσιν, ἀλλὰ τοῖς Ἑλληνικοῖς ἔθεσιν αἱροῦνται χρώμενοι ζῆν, ἀπολύομέν τε αὐτοὺς τῶν αἰτιῶν, καὶ τὸ παρʼ αὐτοῖς ἱερόν, καθάπερ ἠξιώκασι, προσαγορευθήτω Διὸς Ἑλληνίου."},{"number":264,"text":"ταῦτα δὲ καὶ Ἀπολλωνίῳ τῷ μεριδάρχῃ ἐπέστειλεν ἕκτῳ ἔτει καὶ τεσσαρακοστῷ μηνὸς Ἑκατομβαιῶνος Ὑρκανίου ὀκτωκαιδεκάτῃ."}],"6":[{"number":265,"text":"Κατὰ δὲ τὸν αὐτὸν καιρὸν ἦν τις οἰκῶν ἐν Μωδαῒ κώμῃ τῆς Ἰουδαίας, ὄνομα Ματταθίας, υἱὸς Ἰωάννου τοῦ Συμεῶνος τοῦ Ἀσαμωναίου, ἱερεὺς ἐξ ἐφημερίδος Ἰώαβος, Ἱεροσολυμίτης."},{"number":266,"text":"ἦσαν δʼ αὐτῷ υἱοὶ πέντε, Ἰωάννης ὁ καλούμενος Γάδδης καὶ Σίμων ὁ κληθεὶς Θάτις καὶ Ἰούδας ὁ καλούμενος Μακαβαῖος καὶ Ἐλεάζαρος ὁ κληθεὶς Αὐρὰν καὶ Ἰωνάθης ὁ κληθεὶς Ἀφφοῦς."},{"number":267,"text":"οὗτος οὖν ὁ Ματταθίας ἀπωδύρετο τοῖς τέκνοις τὴν κατάστασιν τῶν πραγμάτων καὶ τήν τε τῆς πόλεως διαρπαγὴν καὶ τοῦ ναοῦ τὴν σύλησιν καὶ τοῦ πλήθους τὰς συμφοράς, ἔλεγέν τε κρεῖττον αὐτοῖς εἶναι ὑπὲρ τῶν πατρίων νόμων ἀποθανεῖν ἢ ζῆν οὕτως ἀσεβῶς."},{"number":268,"text":"Ἐλθόντων δὲ εἰς τὴν Μωδαῒν κώμην τῶν ὑπὸ τοῦ βασιλέως καθεσταμένων ἐπὶ τῷ ποιεῖν ἀναγκάζειν τοὺς Ἰουδαίους ἃ διετέτακτο καὶ θύειν τοὺς ἐκεῖ κελευόντων, ὡς ὁ βασιλεὺς κελεύσειεν, διά τε τὴν δόξαν τήν τε διὰ τὰ ἄλλα καὶ διὰ τὴν εὐπαιδίαν ἀξιούντων τὸν Ματταθίαν προκατάρχειν τῶν θυσιῶν,"},{"number":269,"text":"κατακολουθήσειν γὰρ αὐτῷ καὶ τοὺς πολίτας, καὶ διὰ τοῦτο τιμηθήσεσθαι πρὸς τοῦ βασιλέως, ὁ Ματταθίας οὐκ ἔφασκεν ποιήσειν, οὐδʼ εἰ τὰ πάντα ἔθνη τοῖς Ἀντιόχου προστάγμασιν ἢ διὰ φόβον ἢ διʼ εὐαρέστησιν ὑπακούει, πεισθήσεσθαί ποτʼ αὐτὸς μετὰ τῶν τέκνων τὴν πάτριον θρησκείαν ἐγκαταλιπεῖν."},{"number":270,"text":"ὡς δὲ σιωπήσαντος αὐτοῦ προσελθών τις τῶν Ἰουδαίων ἔθυσεν εἰς μέσον καθʼ ἃ προσέταξεν Ἀντίοχος, θυμωθεὶς ὁ Ματταθίας ὥρμησεν ἐπʼ αὐτὸν μετὰ τῶν παίδων ἐχόντων κοπίδας καὶ αὐτόν τε ἐκεῖνον διέφθειρεν καὶ τὸν στρατηγὸν τοῦ βασιλέως Ἀπελλῆν, ὃς ἐπηνάγκαζεν, διεχρήσατο μετʼ ὀλίγων στρατιωτῶν,"},{"number":271,"text":"καὶ τὸν βωμὸν καθελὼν ἀνέκραγεν, εἴ τις ζηλωτής ἐστιν τῶν πατρίων ἐθῶν καὶ τῆς τοῦ θεοῦ θρησκείας, ἑπέσθω, φησίν, ἐμοί, καὶ ταῦτʼ εἰπὼν μετὰ τῶν τέκνων εἰς τὴν ἔρημον ἐξώρμησεν καταλιπὼν ἅπασαν τὴν αὐτοῦ κτῆσιν ἐν τῇ κώμῃ."},{"number":272,"text":"τὸ δʼ αὐτὸ καὶ ἄλλοι ποιήσαντες μετὰ τέκνων καὶ γυναικῶν ἔφυγον εἰς τὴν ἔρημον καὶ ἐν τοῖς σπηλαίοις διῆγον. ἀκούσαντες δὲ ταῦθʼ οἱ τοῦ βασιλέως στρατηγοὶ καὶ τὴν δύναμιν ὅσην εἶναι συνέβαινεν ἐν τῇ ἀκροπόλει τῶν Ἱεροσολύμων ἀναλαβόντες ἐδίωξαν εἰς τὴν ἔρημον τοὺς Ἰουδαίους."},{"number":273,"text":"καὶ καταλαβόντες τὸ μὲν πρῶτον αὐτοὺς ἐπεχείρουν πείθειν μετανοήσαντας αἱρεῖσθαι τὰ συμφέροντα καὶ μὴ προσάγειν αὐτοῖς ἀνάγκην, ὥστʼ αὐτοῖς χρήσασθαι πολέμου νόμῳ·"},{"number":274,"text":"μὴ προσδεχομένων δὲ τοὺς λόγους, ἀλλὰ τἀναντία φρονούντων, συμβάλλουσιν αὐτοῖς εἰς μάχην σαββάτων ἡμέρᾳ, καὶ ὡς εἶχον οὕτως ἐν τοῖς σπηλαίοις αὐτοὺς κατέφλεξαν οὐδὲ ἀμυνομένους ἀλλʼ οὐδὲ τὰς εἰσόδους ἐμφράξαντας· τοῦ δὲ ἀμύνασθαι διὰ τὴν ἡμέραν ἀπέσχοντο μηδʼ ἐν κακοῖς παραβῆναι τὴν τοῦ σαββάτου τιμὴν θελήσαντες· ἀργεῖν γὰρ ἡμῖν ἐν αὐτῇ νόμιμόν ἐστιν."},{"number":275,"text":"ἀπέθανον μὲν οὖν σὺν γυναιξὶ καὶ τέκνοις ἐμπνιγέντες τοῖς σπηλαίοις ὡσεὶ χίλιοι, πολλοὶ δὲ καὶ διασωθέντες τῷ Ματταθίᾳ προσέθεντο κἀκεῖνον ἄρχοντα ἀπέδειξαν."},{"number":276,"text":"ὁ δὲ καὶ σαββάτοις αὐτοὺς ἐδίδαξε μάχεσθαι λέγων, ὡς εἰ μὴ ποιήσουσι τοῦτο φυλαττόμενοι τὸ νόμιμον, αὐτοῖς ἔσονται πολέμιοι, τῶν μὲν ἐχθρῶν κατʼ ἐκείνην τὴν ἡμέραν αὐτοῖς προσβαλλόντων, αὐτῶν δʼ οὐκ ἀμυνομένων, κωλύσειν τε μηδὲν οὕτως ἀμαχητὶ πάντας ἀπολέσθαι."},{"number":277,"text":"ταῦτʼ εἰπὼν ἔπεισεν αὐτούς, καὶ ἄχρι δεῦρο μένει παρʼ ἡμῖν τὸ καὶ σαββάτοις, εἴ ποτε δεήσειεν, μάχεσθαι."},{"number":278,"text":"ποιήσας οὖν δύναμιν πολλὴν περὶ αὐτὸν Ματταθίας τούς τε βωμοὺς καθεῖλεν καὶ τοὺς ἐξαμαρτάνοντας ἀπέκτεινεν, ὅσους λαβεῖν ὑποχειρίους ἠδυνήθη· πολλοὶ γὰρ διʼ εὐλάβειαν διεσπάρησαν εἰς τὰ πέριξ ἔθνη· τῶν τε παίδων τοὺς οὐ περιτετμημένους ἐκέλευσε περιτέμνεσθαι τοὺς ἐπὶ τῷ κωλύειν καθεσταμένους ἐκβαλών."},{"number":279,"text":"Ἄρξας δʼ ἐνιαυτὸν καὶ καταπεσὼν εἰς νόσον προσκαλεῖται τοὺς παῖδας, καὶ περιστησάμενος αὐτοὺς ἐγὼ μέν, εἶπεν, ὦ παῖδες, ἄπειμι τὴν εἱμαρμένην πορείαν, παρατίθεμαι δʼ ὑμῖν τοὐμὸν φρόνημα καὶ παρακαλῶ μὴ γενέσθαι κακοὺς αὐτοῦ φύλακας,"},{"number":280,"text":"ἀλλὰ μεμνημένους τῆς τοῦ φύσαντος ὑμᾶς καὶ θρεψαμένου προαιρέσεως ἔθη τε σώζειν τὰ πάτρια καὶ κινδυνεύουσαν οἴχεσθαι τὴν ἀρχαίαν πολιτείαν ἀνακτᾶσθαι μὴ συμφερομένους τοῖς ἢ διὰ βούλησιν ἢ διʼ ἀνάγκην προδιδοῦσιν αὐτήν,"},{"number":281,"text":"ἀλλʼ ἀξιῶ παῖδας ὄντας ἐμοὺς ἐμμεῖναι καὶ βίας ἁπάσης καὶ ἀνάγκης ἐπάνω γενέσθαι, τὰς ψυχὰς οὕτω παρασκευασαμένους, ὥστʼ ἀποθανεῖν ὑπὲρ τῶν νόμων, ἂν δέῃ, λογιζομένους τοῦθʼ, ὅτι τὸ θεῖον τοιούτους ὑμᾶς ὁρῶν οὐχ ὑπερόψεται, τῆς δʼ ἀρετῆς ἀγασάμενον ἀποδώσει πάλιν ὑμῖν αὐτοὺς καὶ τὴν ἐλευθερίαν, ἐν ᾗ ζήσεσθε μετʼ ἀδείας τῶν ἰδίων ἀπολαύοντες ἐθῶν, ἀποκαταστήσει·"},{"number":282,"text":"θνητὰ μὲν γὰρ τὰ σώματα ἡμῶν καὶ ἐπίκηρα, τῇ δὲ τῶν ἔργων μνήμῃ τάξιν ἀθανασίας λαμβάνομεν, ἧς ἐρασθέντας ὑμᾶς βούλομαι διώκειν τὴν εὔκλειαν καὶ τὰ μέγιστα ὑφισταμένους μὴ ὀκνεῖν ὑπὲρ αὐτῶν ἀπολιπεῖν τὸν βίον."},{"number":283,"text":"μάλιστα δʼ ὑμῖν ὁμονοεῖν παραινῶ καὶ πρὸς ὅ τις ὑμῶν πέφυκεν ἀμείνων θατέρου πρὸς τοῦτʼ εἴκοντας ἀλλήλοις οἰκείαις χρῆσθαι ταῖς ἀρεταῖς. καὶ Σίμωνα μὲν τὸν ἀδελφὸν συνέσει προύχοντα πατέρα ἡγεῖσθε καὶ οἷς ἂν οὗτος συμβουλεύσῃ πείθεσθε,"},{"number":284,"text":"Μακαβαῖον δὲ τῆς στρατιᾶς διʼ ἀνδρείαν καὶ ἰσχὺν στρατηγὸν ἕξετε· τὸ γὰρ ἔθνος οὗτος ἐκδικήσει καὶ ἀμυνεῖται τοὺς πολεμίους. προσίεσθε δὲ καὶ τοὺς δικαίους καὶ θεοσεβεῖς καὶ τὴν δύναμιν αὐτῶν αὔξετε."},{"number":285,"text":"Ταῦτα διαλεχθεὶς τοῖς παισὶν καὶ τὸν θεὸν εὐξάμενος σύμμαχον αὐτοῖς γενέσθαι καὶ τῷ λαῷ τὴν ἰδίαν ἀνασῶσαι πάλιν τοῦ βίου συνήθειαν, μετʼ οὐ πολὺ τελευτᾷ, καὶ θάπτεται μὲν ἐν Μωδαῒ πένθος ἐπʼ αὐτῷ μέγα παντὸς τοῦ λαοῦ ποιησαμένου, διεδέξατο δὲ τὴν προστασίαν τῶν πραγμάτων ὁ παῖς αὐτοῦ Ἰούδας ὁ καὶ Μακκαβαῖος ἑκατοστῷ ἔτει καὶ τεσσαρακοστῷ καὶ ἕκτῳ."},{"number":286,"text":"συναραμένων δʼ αὐτῷ προθύμως τῶν ἀδελφῶν καὶ τῶν ἄλλων τούς τε πολεμίους ἐξέβαλεν ἐκ τῆς χώρας καὶ τοὺς παρανομήσαντας τῶν ὁμοφύλων εἰς τὰ πάτρια διεχρήσατο καὶ ἐκαθάρισεν ἀπὸ παντὸς μιάσματος τὴν γῆν."}],"7":[{"number":287,"text":"Ταῦτʼ ἀκούσας Ἀπολλώνιος ὁ τῆς Σαμαρείας στρατηγὸς ἀναλαβὼν τὴν δύναμιν ὥρμησεν ἐπὶ τὸν Ἰούδαν. ὁ δὲ ἀπήντησεν αὐτῷ καὶ συμβαλὼν κρατεῖ τῇ μάχῃ καὶ πολλοὺς μὲν αὐτῶν ἀπέκτεινεν, ἐν οἷς καὶ τὸν στρατηγὸν Ἀπολλώνιον, οὗ καὶ τὴν μάχαιραν, ᾗ χρῆσθαι συνέβαινεν ἐκεῖνον, σκυλεύσας αὐτὸς εἶχεν, πλείους δὲ τραυματίας ἐποίησεν καὶ πολλὴν λείαν ἐκ τοῦ στρατοπέδου λαβὼν τῶν πολεμίων ἀνεχώρησεν."},{"number":288,"text":"Σήρων δʼ ὁ τῆς κοίλης Συρίας στρατηγός, ἀκούσας ὅτι πολλοὶ προσκεχωρήκασιν τῷ Ἰούδᾳ καὶ δύναμιν ἤδη περιβέβληται πρὸς ἀγῶνας καὶ πολέμους ἀξιόλογον, ἐπʼ αὐτὸν ἔγνω στρατεύσασθαι προσήκειν ὑπολαμβάνων τοὺς εἰς τὰ τοῦ βασιλέως προστάγματα παρανομοῦντας πειρᾶσθαι κολάζειν."},{"number":289,"text":"συναγαγὼν οὖν δύναμιν ὅση παρῆν αὐτῷ, προσκαταλέξας δὲ καὶ τῶν Ἰουδαίων τοὺς φυγάδας καὶ ἀσεβεῖς ἐπὶ τὸν Ἰούδαν παρεγίγνετο· προελθὼν δὲ ἄχρι Βαιθώρων κώμης τῆς Ἰουδαίας αὐτόθι στρατοπεδεύεται."},{"number":290,"text":"ὁ δὲ Ἰούδας ἀπαντήσας αὐτῷ καὶ συμβαλεῖν προαιρούμενος, ἐπεὶ τοὺς στρατιώτας ἑώρα πρὸς τὴν μάχην διά τε τὴν ὀλιγότητα καὶ διʼ ἀσιτίαν, νενηστεύκεσαν γάρ, ὀκνοῦντας, παρεθάρσυνεν λέγων οὐκ ἐν τῷ πλήθει τὸ νικᾶν εἶναι καὶ κρατεῖν τῶν πολεμίων, ἀλλʼ ἐν τῷ πρὸς τὸ θεῖον εὐσεβεῖν."},{"number":291,"text":"καὶ τούτου σαφέστατον ἔχειν παράδειγμα τοὺς προγόνους, οἳ διὰ δικαιοσύνην καὶ τὸ περὶ τῶν ἰδίων νόμων καὶ τέκνων ἀγωνίζεσθαι πολλὰς πολλάκις ἥττησαν μυριάδας· τὸ γὰρ μηδὲν ἀδικεῖν ἰσχυρὰ δύναμις."},{"number":292,"text":"ταῦτʼ εἰπὼν πείθει τοὺς σὺν αὐτῷ καταφρονήσαντας τοῦ πλήθους τῶν ἐναντίων ὁμόσε χωρῆσαι τῷ Σήρωνι, καὶ συμβαλὼν τρέπει τοὺς Σύρους· πεσόντος γὰρ τοῦ στρατηγοῦ πάντες φεύγειν ὥρμησαν, ὡς ἐν τούτῳ τῆς σωτηρίας αὐτοῖς ἀποκειμένης. ἐπιδιώκων δʼ ἄχρι τοῦ πεδίου κτείνει τῶν πολεμίων ὡσεὶ ὀκτακοσίους· οἱ δὲ λοιποὶ διεσώθησαν εἰς τὴν παραλίαν."},{"number":293,"text":"Ταῦτα ἀκούσας ὁ βασιλεὺς Ἀντίοχος μεγάλως ὠργίσθη τοῖς γεγενημένοις, καὶ πᾶσαν τὴν οἰκείαν δύναμιν ἀθροίσας καὶ πολλοὺς ἐκ τῶν νήσων μισθοφόρους παραλαβὼν ἡτοιμάζετο περὶ τὴν ἀρχὴν τοῦ ἔαρος εἰς τὴν Ἰουδαίαν ἐμβαλεῖν."},{"number":294,"text":"ἐπεὶ δὲ τὸ στρατιωτικὸν διανείμας ἑώρα τοὺς θησαυροὺς ἐπιλείποντας καὶ χρημάτων ἔνδειαν οὖσαν, οὔτε γὰρ οἱ φόροι πάντες ἐτελοῦντο διὰ τὰς τῶν ἐθνῶν στάσεις μεγαλόψυχός τε ὢν καὶ φιλόδωρος οὐκ ἠρκεῖτο τοῖς οὖσιν, ἔγνω πρῶτον εἰς τὴν Περσίδα πορευθεὶς τοὺς φόρους τῆς χώρας συναγαγεῖν."},{"number":295,"text":"καταλιπὼν οὖν ἐπὶ τῶν πραγμάτων Λυσίαν τινὰ δόξαν ἔχοντα παρʼ αὐτῷ, καὶ τὰ μέχρι τῶν Αἰγύπτου ὅρων καὶ τῆς κάτωθεν Ἀσίας ἀπʼ Εὐφράτου διήκοντα ποταμοῦ καὶ μέρος τι τῆς δυνάμεως καὶ τῶν ἐλεφάντων,"},{"number":296,"text":"τρέφειν μὲν Ἀντίοχον τὸν υἱὸν αὐτοῦ μετὰ πάσης φροντίδος ἐνετείλατο ἕως ἂν οὗ παραγένηται, καταστρεψάμενον δὲ τὴν Ἰουδαίαν καὶ τοὺς οἰκοῦντας αὐτὴν ἐξανδραποδισάμενον ἀφανίσαι τὰ Ἱεροσόλυμα καὶ τὸ γένος αὐτῶν ἀπολέσαι."},{"number":297,"text":"καὶ ταῦτα μὲν ἐπιστείλας τῷ Λυσίᾳ ὁ βασιλεὺς Ἀντίοχος ἐξήλασεν εἰς τὴν Περσίδα τῷ ἑκατοστῷ καὶ τεσσαρακοστῷ καὶ ἑβδόμῳ ἔτει, καὶ περαιωσάμενος τὸν Εὐφράτην ἀνέβαινεν πρὸς τοὺς ἄνω σατράπας."},{"number":298,"text":"Ὁ δὲ Λυσίας ἐπιλεξάμενος Πτολεμαῖον τὸν Δορυμένους καὶ Νικάνορα καὶ Γοργίαν, ἄνδρας δυνατοὺς τῶν φίλων τῶν τοῦ βασιλέως, καὶ παραδοὺς αὐτοῖς πεζῆς μὲν δυνάμεως μυριάδας τέσσαρας, ἱππεῖς δὲ ἑπτακισχιλίους, ἐξέπεμψεν ἐπὶ τὴν Ἰουδαίαν. οἱ δὲ ἄχρις Ἐμμαοῦ πόλεως ἐλθόντες ἐπὶ τῇ πεδινῇ καταστρατοπεδεύονται."},{"number":299,"text":"προσγίγνονται δʼ αὐτοῖς σύμμαχοι ἀπό τε τῆς Συρίας καὶ τῆς πέριξ χώρας καὶ πολλοὶ τῶν πεφευγότων Ἰουδαίων, ἔτι γε μὴν καὶ τῶν ἐμπόρων τινὲς ὡς ὠνησόμενοι τοὺς αἰχμαλωτισθησομένους, πέδας μὲν κομίζοντες αἷς δήσουσιν τοὺς ληφθησομένους, ἄργυρον δὲ καὶ χρυσὸν τιμὴν αὐτῶν καταθησόμενοι."},{"number":300,"text":"τὸ δὲ στρατόπεδον καὶ τὸ πλῆθος τῶν ἐναντίων Ἰούδας κατανοήσας ἔπειθε τοὺς οἰκείους στρατιώτας θαρρεῖν καὶ παρεκελεύετο τὰς ἐλπίδας τῆς νίκης ἔχοντας ἐν τῷ θεῷ τοῦτον ἱκετεύειν τῷ πατρίῳ νόμῳ σάκκους περιθεμένους, καὶ τὸ σύνηθες αὐτῷ σχῆμα τῆς ἱκεσίας παρὰ τοὺς μεγάλους κινδύνους ἐπιδείξαντας τούτῳ δυσωπῆσαι παρασχεῖν αὐτοῖς τὸ κατὰ τῶν ἐχθρῶν κράτος."},{"number":301,"text":"διατάξας δὲ τὸν ἀρχαῖον αὐτοὺς τρόπον καὶ πάτριον κατὰ χιλιάρχους καὶ ταξιάρχους καὶ τοὺς νεογάμους ἀπολύσας καὶ τοὺς τὰς κτήσεις νεωστὶ πεποιημένους, ὅπως μὴ διὰ τὴν τούτων ἀπόλαυσιν φιλοζωοῦντες ἀτολμότερον μάχωνται, καταστὰς τοιούτοις παρώρμα λόγοις πρὸς τὸν ἀγῶνα τοὺς αὐτοῦ στρατιώτας·"},{"number":302,"text":"καιρὸς μὲν οὖν ὑμῖν οὐκ ἄλλος ἀναγκαιότερος τοῦ παρόντος, ὦ ἑταῖροι, εἰς εὐψυχίαν καὶ κινδύνων καταφρόνησιν καταλείπεται· νῦν γὰρ ἔστιν ἀνδρείως ἀγωνισαμένοις τὴν ἐλευθερίαν ἀπολαβεῖν, ἣν καὶ διʼ αὐτὴν ἅπασιν ἀγαπητὴν οὖσαν ὑμῖν ὑπὲρ ἐξουσίας τοῦ θρησκεύειν τὸ θεῖον ποθεινοτέραν εἶναι συμβέβηκεν."},{"number":303,"text":"ὡς οὖν ἐν τῷ παρόντι κειμένων ὑμῖν ταύτην τε ἀπολαβεῖν καὶ τὸν εὐδαίμονα καὶ μακάριον βίον ἀνακτήσασθαι, οὗτος δʼ ἦν ὁ κατὰ τοὺς νόμους καὶ τὴν πάτριον συνήθειαν, ἢ τὰ αἴσχιστα παθεῖν καὶ μηδὲ σπέρμα τοῦ γένους ὑμῶν ὑπολειφθῆναι κακῶν ἐν τῇ μάχῃ γενομένων,"},{"number":304,"text":"οὕτως ἀγωνίζεσθε, τὸ μὲν ἀποθανεῖν καὶ μὴ πολεμοῦσιν ὑπάρξον ἡγούμενοι, τὸ δʼ ὑπὲρ τηλικούτων ἐπάθλων, ἐλευθερίας πατρίδος νόμων εὐσεβείας, αἰώνιον τὴν εὔκλειαν κατασκευάσειν πεπιστευκότες· ἑτοιμάζεσθε τοιγαροῦν οὕτως τὰς ψυχὰς ὡς αὔριον ἅμʼ ἡμέρᾳ συμβαλοῦντες τοῖς πολεμίοις."},{"number":305,"text":"Καὶ ὁ μὲν Ἰούδας ταῦτα παραθαρσύνων τὴν στρατιὰν ἔλεξεν. τῶν δὲ πολεμίων πεμψάντων Γοργίαν μετὰ πεντακισχιλίων πεζῶν καὶ χιλίων ἱππέων, ὅπως διὰ τῆς νυκτὸς ἐπιπέσῃ τῷ Ἰούδᾳ, καὶ πρὸς τοῦτο ὁδηγοὺς ἔχοντος αὐτοῦ τινας τῶν πεφευγότων Ἰουδαίων, αἰσθόμενος ὁ τοῦ Ματταθίου παῖς ἔγνω καὶ αὐτὸς τοῖς ἐν τῇ παρεμβολῇ τῶν πολεμίων ἐπιπεσεῖν καὶ ταῦτα διῃρημένης αὐτῶν τῆς δυνάμεως."},{"number":306,"text":"καθʼ ὥραν οὖν δειπνοποιησάμενος καὶ πολλὰ πυρὰ καταλιπὼν ἐπὶ τοῦ στρατοπέδου διʼ ὅλης ὥδευε τῆς νυκτὸς ἐπὶ τοὺς ἐν Ἐμμαοῖ τῶν πολεμίων. οὐχ εὑρὼν δʼ ἐν τῷ στρατοπέδῳ τοὺς ἐχθροὺς ὁ Γοργίας, ἀλλʼ ὑπονοήσας ἀναχωρήσαντας αὐτοὺς ἐν τοῖς ὄρεσι κεκρύφθαι, πορευθεὶς ἔγνω ζητεῖν, ὅπου ποτʼ εἶεν."},{"number":307,"text":"περὶ δὲ τὸν ὄρθρον ἐπιφαίνεται τοῖς ἐν Ἐμμαοῖ πολεμίοις ὁ Ἰούδας μετὰ τρισχιλίων φαύλως ὡπλισμένων διὰ πενίαν, καὶ θεασάμενος τοὺς ἐχθροὺς ἄριστα πεφραγμένους καὶ μετʼ ἐμπειρίας πολλῆς ἐστρατοπεδευμένους, προτρεψάμενος τοὺς ἰδίους, ὡς καὶ γυμνοῖς τοῖς σώμασιν μάχεσθαι δεῖ καὶ τὸ θεῖον ἤδη που καὶ τοῖς οὕτως ἔχουσιν τὸ κατὰ τῶν πλειόνων καὶ ὡπλισμένων κράτος ἔδωκεν ἀγασάμενον αὐτοὺς τῆς εὐψυχίας, ἐκέλευσε σημῆναι τοὺς σαλπιγκτάς."},{"number":308,"text":"ἔπειτʼ ἐμπεσὼν ἀπροσδοκήτοις τοῖς πολεμίοις καὶ ἐκπλήξας αὐτῶν τὴν διάνοιαν καὶ ταράξας πολλοὺς μὲν ἀπέκτεινεν ἀνθισταμένους, τοὺς δὲ λοιποὺς διώκων ἦλθεν ἄχρι Γαζάρων καὶ τῶν πεδίων τῆς Ἰδουμαίας καὶ Ἀζώτου καὶ Ἰαμνείας· ἔπεσόν τε αὐτῶν ὡς περὶ τρισχιλίους."},{"number":309,"text":"Ἰούδας δὲ τῶν μὲν σκύλων παρεκελεύετο μὴ ἐπιθυμεῖν τοὺς αὐτοῦ στρατιώτας· ἔτι γὰρ αὐτοῖς ἀγῶνά τινα καὶ μάχην εἶναι πρὸς Γοργίαν καὶ τὴν σὺν αὐτῷ δύναμιν· κρατήσαντας δὲ καὶ τούτων τότε σκυλεύσειν ἐπʼ ἀδείας ἔλεγεν τοῦτο μόνον ἔχοντας καὶ μηδὲν ἕτερον ἐκδεχομένους."},{"number":310,"text":"ἔτι δὲ αὐτοῦ διαλεγομένου ταῦτα πρὸς τοὺς στρατιώτας ὑπερκύψαντες οἱ τοῦ Γοργίου τὴν μὲν στρατιὰν ἣν ἐν τῇ παρεμβολῇ κατέλιπον ὁρῶσιν τετραμμένην, τὸ δὲ στρατόπεδον ἐμπεπρησμένον· ὁ γὰρ καπνὸς αὐτοῖς πόρρωθεν οὖσιν τοῦ συμβεβηκότος δήλωσιν ἔφερεν."},{"number":311,"text":"ὡς οὖν ταῦθʼ οὕτως ἔχοντα ἔμαθον οἱ σὺν Γοργίᾳ καὶ τοὺς μετὰ Ἰούδου πρὸς παράταξιν ἑτοίμους κατενόησαν, καὶ αὐτοὶ δείσαντες εἰς φυγὴν ἐτράπησαν."},{"number":312,"text":"ὁ δὲ Ἰούδας ὡς ἀμαχητὶ τῶν μετὰ Γοργίου στρατιωτῶν ἡττημένων ὑποστρέψας ἀνῃρεῖτο τὰ σκῦλα, πολὺν δὲ χρυσὸν καὶ ἄργυρον καὶ πορφύραν καὶ ὑάκινθον λαβὼν εἰς τὴν οἰκείαν ὑπέστρεψε χαίρων καὶ ὑμνῶν τὸν θεὸν ἐπὶ τοῖς κατωρθωμένοις· οὐ μικρὰ γὰρ αὐτοῖς ἡ νίκη πρὸς τὴν ἐλευθερίαν συνεβάλλετο."},{"number":313,"text":"Λυσίας δὲ συγχυθεὶς ἐπὶ τῇ τῶν ἐκπεμφθέντων ἥττῃ τῷ ἐχομένῳ ἔτει μυριάδας ἀνδρῶν ἐπιλέκτων ἀθροίσας ἓξ καὶ πεντακισχιλίους λαβὼν ἱππεῖς ἐνέβαλεν εἰς τὴν Ἰουδαίαν, καὶ ἀναβὰς εἰς τὴν ὀρεινὴν ἐν Βεθσούροις κώμῃ τῆς Ἰουδαίας ἐστρατοπεδεύσατο."},{"number":314,"text":"ἀπήντησε δὲ μετὰ μυρίων Ἰούδας, καὶ τὸ πλῆθος ἰδὼν τῶν πολεμίων σύμμαχον ἐπʼ αὐτῷ γενέσθαι τὸν θεὸν εὐξάμενος, συμβαλὼν τοῖς προδρόμοις τῶν πολεμίων νικᾷ τούτους καὶ φονεύσας αὐτῶν ὡς πεντακισχιλίους τοῖς λοιποῖς ἦν ἐπίφοβος."},{"number":315,"text":"ἀμέλει κατανοήσας ὁ Λυσίας τὸ φρόνημα τῶν Ἰουδαίων, ὡς ἕτοιμοι τελευτᾶν εἰσιν, εἰ μὴ ζήσουσιν ἐλεύθεροι, καὶ δείσας αὐτῶν τὴν ἀπόγνωσιν ὡς ἰσχύν, ἀναλαβὼν τὴν λοιπὴν δύναμιν ὑπέστρεψεν εἰς Ἀντιόχειαν καὶ διέτριβεν ἐκεῖ ξενολογῶν καὶ παρασκευαζόμενος μετὰ μείζονος στρατιᾶς εἰς τὴν Ἰουδαίαν ἐμβαλεῖν."},{"number":316,"text":"Τοσαυτάκις οὖν ἡττημένων ἤδη τῶν Ἀντιόχου τοῦ βασιλέως στρατηγῶν ὁ Ἰούδας ἐκκλησιάσας ἔλεγεν μετὰ πολλὰς νίκας, ἃς ὁ θεὸς αὐτοῖς ἔδωκεν, ἀναβῆναι δεῖν εἰς Ἱεροσόλυμα καὶ τὸν ναὸν καθαρίσαι καὶ τὰς νενομισμένας θυσίας προσφέρειν."},{"number":317,"text":"ὡς δὲ παραγενόμενος μετὰ παντὸς τοῦ πλήθους εἰς Ἱεροσόλυμα τὸν ναὸν ἔρημον εὗρεν καὶ καταπεπρησμένας τὰς πύλας καὶ φυτὰ διὰ τὴν ἐρημίαν αὐτόματα ἐν τῷ ἱερῷ ἀναβεβλαστηκότα, θρηνεῖν ἤρξατο μετὰ τῶν ἰδίων ἐπὶ τῇ ὄψει τοῦ ναοῦ συγχυθείς."},{"number":318,"text":"ἐπιλεξάμενος δέ τινας τῶν αὐτοῦ στρατιωτῶν προσέταξε τούτοις ἐκπολεμῆσαι τοὺς τὴν ἄκραν φυλάττοντας, ἄχρι τὸν ναὸν αὐτὸς ἁγνίσειεν. καὶ καθάρας ἐπιμελῶς αὐτὸν εἰσεκόμισε καινὰ σκεύη, λυχνίαν τράπεζαν βωμόν, ἐκ χρυσοῦ πεποιημένα, ἀπήρτησεν δὲ καὶ τὰ ἐμπετάσματα τῶν θυρῶν καὶ τὰς θύρας αὐτὰς ἐπέθηκεν, καθελὼν δὲ καὶ τὸ θυσιαστήριον καινὸν ἐκ λίθων συμμίκτων ᾠκοδόμησεν οὐ λελαξευμένων ὑπὸ σιδήρου."},{"number":319,"text":"πέμπτῃ δὲ καὶ εἰκάδι τοῦ Ἐξελέου μηνός, ὃν οἱ Μακεδόνες Ἀπελλαῖον καλοῦσιν, ἧψάν τε φῶτα ἐπὶ τῆς λυχνίας καὶ ἐθυμίασαν ἐπὶ τοῦ βωμοῦ καὶ ἄρτους ἐπὶ τὴν τράπεζαν ἐπέθεσαν καὶ ὡλοκαύτησαν ἐπὶ τοῦ καινοῦ θυσιαστηρίου."},{"number":320,"text":"ἔτυχεν δὲ ταῦτα κατὰ τὴν αὐτὴν ἡμέραν γίνεσθαι, καθʼ ἣν καὶ μετέπεσεν αὐτῶν ἡ ἅγιος θρησκεία εἰς βέβηλον καὶ κοινὴν συνήθειαν μετὰ ἔτη τρία· τὸν γὰρ ναὸν ἐρημωθέντα ὑπὸ Ἀντιόχου διαμεῖναι τοιοῦτον ἔτεσι συνέβη τρισίν·"},{"number":321,"text":"ἔτει γὰρ πέμπτῳ καὶ τεσσαρακοστῷ καὶ ἑκατοστῷ ταῦτα περὶ τὸν ναὸν ἐγένετο, πέμπτῃ δὲ καὶ εἰκάδι τοῦ Ἀπελλαίου μηνὸς ὀλυμπιάδι ἑκατοστῇ καὶ πεντηκοστῇ καὶ τρίτῃ, ἀνενεώθη δὲ κατὰ τὴν αὐτὴν ἡμέραν πέμπτῃ καὶ εἰκοστῇ τοῦ Ἀπελλαίου μηνὸς ὀγδόῳ καὶ τεσσαρακοστῷ καὶ ἑκατοστῷ ἔτει ὀλυμπιάδι ἑκατοστῇ καὶ πεντηκοστῇ καὶ τετάρτῃ."},{"number":322,"text":"τὴν δʼ ἐρήμωσιν τοῦ ναοῦ συνέβη γενέσθαι κατὰ τὴν Δανιήλου προφητείαν πρὸ τετρακοσίων καὶ ὀκτὼ γενομένην ἐτῶν· ἐδήλωσεν γάρ, ὅτι Μακεδόνες καταλύσουσιν αὐτόν."},{"number":323,"text":"Ἑώρταζε δὲ ὁ Ἰούδας μετὰ τῶν πολιτῶν τὴν ἀνάκτησιν τῆς περὶ τὸν ναὸν θυσίας ἐφʼ ἡμέρας ὀκτὼ μηδὲν ἀπολιπὼν ἡδονῆς εἶδος, ἀλλὰ πολυτελέσι μὲν καὶ λαμπραῖς ταῖς θυσίαις κατευωχῶν αὐτούς, ὕμνοις δὲ καὶ ψαλμοῖς τὸν μὲν θεὸν τιμῶν αὐτοὺς δὲ τέρπων."},{"number":324,"text":"τοσαύτῃ δʼ ἐχρήσαντο τῇ περὶ τὴν ἀνανέωσιν τῶν ἐθῶν ἡδονῇ μετὰ χρόνον πολὺν ἀπροσδοκήτως ἐν ἐξουσίᾳ γενόμενοι τῆς θρησκείας, ὡς νόμον θεῖναι τοῖς μετʼ αὐτοὺς ἑορτάζειν τὴν ἀνάκτησιν τῶν περὶ τὸν ναὸν ἐφʼ ἡμέρας ὀκτώ."},{"number":325,"text":"καὶ ἐξ ἐκείνου μέχρι τοῦ δεῦρο τὴν ἑορτὴν ἄγομεν καλοῦντες αὐτὴν φῶτα ἐκ τοῦ παρʼ ἐλπίδας οἶμαι ταύτην ἡμῖν φανῆναι τὴν ἐξουσίαν τὴν προσηγορίαν θέμενοι τῇ ἑορτῇ."},{"number":326,"text":"τειχίσας δʼ ἐν κύκλῳ τὴν πόλιν καὶ πρὸς τὰς ἐπιδρομὰς τῶν πολεμίων πύργους οἰκοδομησάμενος ὑψηλοὺς φύλακας ἐν αὐτοῖς ἐγκατέστησεν, καὶ τὴν Βεθσούραν δὲ πόλιν ὠχύρωσεν, ὅπως ἀντὶ φρουρίου αὐτῇ πρὸς τὰς ἀπὸ τῶν πολεμίων ἀνάγκας ἔχῃ χρῆσθαι."}],"8":[{"number":327,"text":"Τούτων οὕτως γενομένων τὰ πέριξ ἔθνη πρὸς τὴν ἀναζωπύρησιν καὶ τὴν ἰσχὺν τῶν Ἰουδαίων χαλεπῶς διακείμενα πολλοὺς ἐπισυνιστάμενα διέφθειρεν ἐνέδραις καὶ ἐπιβουλαῖς αὐτῶν ἐγκρατῆ γιγνόμενα. πρὸς τούτους πολέμους συνεχεῖς ἐκφέρων ὁ Ἰούδας ἐπέχειν αὐτοὺς τῆς καταδρομῆς καὶ ὧν ἐποίουν κακῶς τοὺς Ἰουδαίους ἐπειρᾶτο."},{"number":328,"text":"καὶ τοῖς Ἠσαῦ υἱοῖς Ἰδουμαίοις ἐπιπεσὼν κατὰ τὴν Ἀκραβατηνὴν πολλοὺς αὐτῶν ἀπέκτεινεν καὶ ἐσκύλευσεν. συγκλείσας δὲ καὶ τοὺς υἱοὺς τοῦ Βαάνου λοχῶντας τοὺς Ἰουδαίους περικαθίσας ἐπολιόρκει καὶ τούς τε πύργους αὐτῶν ἐνεπίμπρα καὶ τοὺς ἄνδρας διέφθειρεν."},{"number":329,"text":"ἔπειτʼ ἐκεῖθεν ἐπὶ τοὺς Ἀμμανίτας ἐξώρμησεν δύναμιν μεγάλην καὶ πολυάνθρωπον ἔχοντας, ὧν ἡγεῖτο Τιμόθεος. χειρωσάμενος δὲ καὶ τούτους τὴν Ἰαζωρῶν ἐξαιρεῖ πόλιν, καὶ τάς τε γυναῖκας αὐτῶν καὶ τὰ τέκνα λαβὼν αἰχμαλώτους καὶ τὴν πόλιν ἐμπρήσας εἰς τὴν Ἰουδαίαν ὑπέστρεψεν."},{"number":330,"text":"μαθόντα δʼ αὐτὸν τὰ γειτονεύοντα τῶν ἐθνῶν ἀνεστροφότα συναθροίζεται εἰς τὴν Γαλαδηνὴν ἐπὶ τοὺς ἐν τοῖς ὅροις αὐτῶν Ἰουδαίους. οἱ δὲ καταφυγόντες εἰς Διάθημα τὸ φρούριον πέμψαντες πρὸς Ἰούδαν ἐδήλουν αὐτῷ, ὅτι λαβεῖν ἐσπούδακεν Τιμόθεος τὸ χωρίον, εἰς ὃ συνεπεφεύγεσαν."},{"number":331,"text":"ἀναγινωσκομένων δὲ τῶν ἐπιστολῶν τούτων κἀκ τῆς Γαλιλαίας ἄγγελοι παραγίγνονται σημαίνοντες ἐπισυνῆχθαι τοὺς ἐκ Πτολεμαΐδος καὶ Τύρου καὶ Σιδῶνος καὶ τῶν ἄλλων ἐθνῶν τῆς Γαλιλαίας."},{"number":332,"text":"Πρὸς οὖν ἀμφοτέρας τὰς τῶν ἠγγελμένων χρείας σκεψάμενος Ἰούδας ὅ τι χρὴ ποιεῖν, Σίμωνα μὲν τὸν ἀδελφὸν προσέταξεν ὡς τρισχιλίους τῶν ἐπιλέκτων λαβόντα τοῖς ἐν Γαλιλαίᾳ βοηθὸν ἐξελθεῖν Ἰουδαίοις."},{"number":333,"text":"αὐτὸς δὲ καὶ Ἰωνάθης ὁ ἕτερος ἀδελφὸς μετʼ ὀκτακισχιλίων στρατιωτῶν ὥρμησαν εἰς τὴν Γαλαδῖτιν· κατέλιπεν δʼ ἐπὶ τῶν ὑπολοίπων τῆς δυνάμεως Ἰώσηπόν τε τὸν Ζαχαρία καὶ Ἀζαρίαν προστάξας αὐτοῖς φυλάττειν ἐπιμελῶς τὴν Ἰουδαίαν καὶ συνάπτειν πόλεμον πρὸς μηδένα, ἕως ἂν αὐτὸς ἐπανέλθῃ."},{"number":334,"text":"ὁ μὲν οὖν Σίμων παραγενόμενος εἰς τὴν Γαλιλαίαν καὶ συμβαλὼν τοῖς ἐχθροῖς εἰς φυγὴν αὐτοὺς ἔτρεψεν καὶ μέχρι τῶν πυλῶν τῆς Πτολεμαΐδος διώξας ἀπέκτεινεν αὐτῶν ὡς περὶ τρισχιλίους, καὶ τά τε σκῦλα λαβὼν τῶν ἀνῃρημένων καὶ τοὺς αἰχμαλώτους Ἰουδαίους καὶ τὴν ἀποσκευὴν αὐτῶν ἐπαγόμενος εἰς τὴν οἰκείαν πάλιν ἀνέστρεψεν."},{"number":335,"text":"Ἰούδας δὲ ὁ Μακαβαῖος καὶ ὁ ἀδελφὸς αὐτοῦ Ἰωνάθης διαβάντες τὸν Ἰορδάνην ποταμὸν καὶ ὁδὸν ἀπʼ αὐτοῦ τριῶν ἀνύσαντες ἡμερῶν τοῖς Ναβαταίοις εἰρηνικῶς ὑπαντῶσιν περιτυγχάνουσιν."},{"number":336,"text":"ὧν διηγησαμένων τὰ περὶ τοὺς ἐν τῇ Γαλάτιδι, ὡς πολλοὶ κακοπαθοῦσιν αὐτῶν ἐν τοῖς φρουρίοις ἀπειλημμένοι καὶ ταῖς πόλεσιν τῆς Γαλάτιδος, καὶ παραινεσάντων αὐτῷ σπεύδειν ἐπὶ τοὺς ἀλλοφύλους καὶ ζητεῖν ἀπʼ αὐτῶν σώζειν τοὺς ὁμοεθνεῖς, πεισθεὶς ὑπέστρεψεν εἰς τὴν ἔρημον, καὶ προσπεσὼν πρώτοις τοῖς τὴν Βοσόραν κατοικοῦσιν καὶ λαβὼν αὐτὴν καταβαλὼν πᾶν τὸ ἄρρεν καὶ μάχεσθαι δυνάμενον διέφθειρεν καὶ τὴν πόλιν ὑφῆψεν."},{"number":337,"text":"ἐπιγενομένης δὲ νυκτὸς οὐδʼ οὕτως ἐπέσχεν, ἀλλʼ ὁδεύσας διʼ αὐτῆς ἐπὶ τὸ φρούριον, ἔνθα τοὺς Ἰουδαίους ἐγκεκλεῖσθαι συνέβαινεν περικαθεζομένου τὸ χωρίον Τιμοθέου μετὰ τῆς δυνάμεως, ἕωθεν ἐπʼ αὐτὸ παραγίνεται."},{"number":338,"text":"καὶ καταλαβὼν ἤδη τοῖς τείχεσι προσβεβληκότας τοὺς πολεμίους καὶ τοὺς μὲν κλίμακας, ὥστε ἀναβαίνειν ἐπʼ αὐτά, τοὺς δὲ μηχανήματα προσφέροντας, κελεύσας τὸν σαλπικτὴν σημῆναι καὶ παρορμήσας τοὺς στρατιώτας ὑπὲρ ἀδελφῶν καὶ συγγενῶν διακινδυνεῦσαι προθύμως, εἰς τρία διελὼν τὸν στρατὸν ἐπιπίπτει κατὰ νώτου τοῖς πολεμίοις."},{"number":339,"text":"οἱ δὲ περὶ τὸν Τιμόθεον αἰσθόμενοι, ὅτι Μακαβαῖος εἴη, πεῖραν ἤδη καὶ πρότερον αὐτοῦ τῆς ἀνδρείας καὶ τῆς ἐν τοῖς πολέμοις εὐτυχίας εἰληφότες φυγῇ χρῶνται· ἐφεπόμενος δὲ μετὰ τοῦ στρατεύματος ὁ Ἰούδας ἀναιρεῖ μὲν αὐτῶν ὡς ὀκτακισχιλίους,"},{"number":340,"text":"ἀπονεύσας δʼ εἰς Μελλὰ πόλιν οὕτως λεγομένην τῶν ἀλλοφύλων λαμβάνει καὶ ταύτην καὶ τοὺς μὲν ἄρρενας ἅπαντας ἀποκτείνει, τὴν δὲ πόλιν αὐτὴν ἐμπίπρησιν. ἄρας δʼ ἐκεῖθεν τήν τε Χασφομάκη καὶ Βοσὸρ καὶ πολλὰς ἄλλας πόλεις τῆς Γαλάτιδος καταστρέφεται."},{"number":341,"text":"Χρόνῳ δʼ ὕστερον οὐ πολλῷ Τιμόθεος δύναμιν μεγάλην παρασκευασάμενος καὶ συμμάχους ἄλλους τε παραλαβὼν καὶ Ἀράβων τινὰς μισθῷ πείσας αὐτῷ συστρατεύειν ἧκεν ἄγων τὴν στρατιὰν πέραν τοῦ χειμάρρου Ῥομφῶν ἄντικρυς· πόλις δʼ ἦν αὕτη·"},{"number":342,"text":"καὶ παρεκελεύετο τοὺς στρατιώτας, εἰ συμβάλοιεν εἰς μάχην τοῖς Ἰουδαίοις, προθύμως ἀγωνίζεσθαι καὶ κωλύειν αὐτοὺς διαβαίνειν τὸν χείμαρρον· διαβάντων γὰρ ἧτταν αὐτοῖς προύλεγεν."},{"number":343,"text":"Ἰούδας δʼ ἀκούσας παρεσκευάσθαι τὸν Τιμόθεον πρὸς μάχην ἀναλαβὼν ἅπασαν τὴν οἰκείαν δύναμιν ἔσπευδεν ἐπὶ τὸν πολέμιον, καὶ περαιωσάμενος τὸν χείμαρρον ἐπιπίπτει τοῖς ἐχθροῖς καὶ τοὺς μὲν αὐτῶν ὑπαντιάζοντας ἀνῄρει, τοὺς δʼ εἰς δέος ἐμβαλὼν ῥίψαντας τὰ ὅπλα φεύγειν ἠνάγκασεν."},{"number":344,"text":"καὶ τινὲς μὲν αὐτῶν διέδρασαν, οἱ δʼ εἰς τὸ καλούμενον ἐγκρανὰς τέμενος συμφυγόντες ἤλπισαν τεύξεσθαι σωτηρίας. Ἰούδας δὲ τὴν πόλιν καταλαβόμενος αὐτούς τε ἀπέκτεινεν καὶ τὸ τέμενος ἐνέπρησεν ποικίλῃ χρησάμενος ἰδέᾳ τῆς ἀπωλείας τῶν πολεμίων."},{"number":345,"text":"Ταῦτα διαπραξάμενος καὶ συναγαγὼν τοὺς ἐν τῇ Γαλάτιδι Ἰουδαίους μετὰ τέκνων καὶ γυναικῶν καὶ τῆς ὑπαρχούσης αὐτοῖς ἀποσκευῆς οἷός τε ἦν εἰς τὴν Ἰουδαίαν ἐπαναγαγεῖν."},{"number":346,"text":"ὡς δʼ ἧκεν ἐπί τινα πόλιν Ἐμφρὼν ὄνομα ἐπὶ τῆς ὁδοῦ κειμένην καὶ οὔτε ἄλλην αὐτῷ τραπομένῳ βαδίζειν δυνατὸν ἦν οὔτε ἀναστρέφειν ἤθελεν, πέμψας πρὸς τοὺς ἐν αὐτῇ παρεκάλει τὰς πύλας ἀνοίξαντας ἐπιτρέπειν αὐτῷ διὰ τῆς πόλεως ἀπελθεῖν· τάς τε γὰρ πύλας λίθοις ἐμπεφράκεσαν καὶ τὴν διέξοδον ἀπετέμοντο."},{"number":347,"text":"μὴ πειθομένων δὲ τῶν Ἐμφραίων παρορμήσας τοὺς μεθʼ ἑαυτοῦ κυκλωσάμενος ἐπολιόρκει, καὶ διʼ ἡμέρας καὶ νυκτὸς προσκαθίσας ἐξαιρεῖ τὴν πόλιν καὶ πᾶν ὅσον ἄρρεν ἦν ἐν αὐτῇ κτείνας καὶ καταπρήσας ἅπασαν αὐτὴν ὁδὸν ἔσχεν· τοσοῦτον δʼ ἦν τὸ τῶν πεφονευμένων πλῆθος, ὡς ἐπʼ αὐτῶν βαδίζειν τῶν νεκρῶν."},{"number":348,"text":"διαβάντες δὲ τὸν Ἰορδάνην ἧκον εἰς τὸ μέγα πεδίον, οὗ κεῖται κατὰ πρόσωπον πόλις Βεθσάνη καλουμένη πρὸς Ἑλλήνων Σκυθόπολις."},{"number":349,"text":"κἀκεῖθεν ὁρμηθέντες εἰς τὴν Ἰουδαίαν παρεγένοντο ψάλλοντές τε καὶ ὑμνοῦντες καὶ τὰς συνήθεις ἐν τοῖς ἐπινικίοις παιδιὰς ἄγοντες, ἔθυσάν τε χαριστηρίους ὑπέρ τε τῶν κατωρθωμένων θυσίας καὶ ὑπὲρ τῆς τοῦ στρατεύματος σωτηρίας· οὐδεὶς γὰρ ἐν τούτοις τοῖς πολέμοις τῶν Ἰουδαίων ἀπέθανεν."},{"number":350,"text":"Ἰώσηπος δὲ ὁ Ζαχαρίου καὶ Ἀζαρίας, οὓς κατέλιπεν στρατηγοὺς ὁ Ἰούδας καθʼ ὃν καιρὸν Σίμων μὲν ὑπῆρχεν ἐν τῇ Γαλιλαίᾳ πολεμῶν τοὺς ἐν τῇ Πτολεμαΐδι, αὐτὸς δὲ ὁ Ἰούδας καὶ ὁ ἀδελφὸς αὐτοῦ Ἰωνάθης ἐν τῇ Γαλάτιδι, βουληθέντες καὶ αὐτοὶ δόξαν περιποιήσασθαι στρατηγῶν τὰ πολεμικὰ γενναίων τὴν ὑπʼ αὐτοῖς δύναμιν ἀναλαβόντες ἦλθον εἰς Ἰάμνειαν."},{"number":351,"text":"Γοργίου δὲ τοῦ τῆς Ἰαμνείας στρατηγοῦ ὑπαντήσαντος συμβολῆς γενομένης δισχιλίους ἀποβάλλουσι τῆς στρατιᾶς καὶ φεύγοντες ἄχρι τῶν τῆς Ἰουδαίας ὅρων διώκονται ."},{"number":352,"text":"συνέβη δʼ αὐτοῖς τὸ πταῖσμα τοῦτο παρακούσασιν ὧν αὐτοῖς Ἰούδας ἐπέστειλεν, μὴ συμβαλεῖν εἰς μάχην μηδενὶ πρὸ τῆς ἐκείνου παρουσίας· πρὸς γὰρ τοῖς ἄλλοις αὐτοῦ στρατηγήμασιν καὶ τὸ κατὰ τοὺς περὶ τὸν Ἰώσηπον καὶ τὸν Ἀζαρίαν πταῖσμα θαυμάσειεν ἄν τις, ὃ συνῆκεν εἰ παρακινήσουσίν τι τῶν ἐπεσταλμένων αὐτοῖς ἐσόμενον."},{"number":353,"text":"ὁ δὲ Ἰούδας καὶ οἱ ἀδελφοὶ αὐτοῦ πολεμοῦντες τοὺς Ἰδουμαίους οὐκ ἀνίεσαν, ἀλλʼ ἐνέκειντο πανταχόθεν αὐτοῖς, τήν τε Χεβρῶνα πόλιν καταλαβόμενοι ὅσον ὀχυρὸν αὐτῆς καθεῖλον καὶ τοὺς πύργους ἐμπρήσαντες ἐδῄουν τὴν ἀλλόφυλον χώραν καὶ Μάρισαν πόλιν, εἴς τε Ἄζωτον ἐλθόντες καὶ λαβόντες αὐτὴν διήρπασαν. πολλὰ δὲ σκῦλα καὶ λείαν κομίζοντες εἰς τὴν Ἰουδαίαν ὑπέστρεψαν."}],"9":[{"number":354,"text":"Ὑπὸ δὲ τὸν αὐτὸν καιρὸν καὶ ὁ βασιλεὺς Ἀντίοχος τὴν ἄνω χώραν ἐπερχόμενος ἀκούει πόλιν ἐν τῇ Περσίδι πλούτῳ διαφέρουσαν Ἐλυμαΐδα τοὔνομα καὶ πολυτελὲς ἱερὸν Ἀρτέμιδος ἐν αὐτῇ καὶ παντοδαπῶν ἀναθημάτων πλῆρες εἶναι ἔτι γε μὴν ὅπλα καὶ θώρακας, ἃ καταλιπεῖν ἐπυνθάνετο τὸν υἱὸν τὸν Φιλίππου βασιλέα δὲ Μακεδόνων Ἀλέξανδρον."},{"number":355,"text":"κινηθεὶς οὖν ὑπὸ τούτων ὥρμησεν ἐπὶ τὴν Ἐλυμαΐδα καὶ προσβαλὼν αὐτὴν ἐπολιόρκει. τῶν δʼ ἐν αὐτῇ μὴ καταπλαγέντων τὴν ἔφοδον αὐτοῦ μηδὲ τὴν πολιορκίαν, ἀλλὰ καρτερῶς ἀντισχόντων ἀποκρούεται τῆς ἐλπίδος· ἀπωσάμενοι γὰρ ἀπὸ τῆς πόλεως καὶ ἐπεξελθόντες ἐδίωξαν, ὥστʼ αὐτὸν ἐλθεῖν εἰς Βαβυλῶνα φεύγοντα καὶ πολλοὺς ἀποβαλόντα τῆς στρατιᾶς."},{"number":356,"text":"λυπουμένῳ δʼ ἐπὶ τῇ διαμαρτίᾳ ταύτῃ προσαγγέλλουσίν τινες καὶ τὴν τῶν στρατηγῶν ἧτταν, οὓς πολεμήσοντας τοῖς Ἰουδαίοις καταλελοίπει, καὶ τὴν ἰσχὺν ἤδη τὴν τῶν Ἰουδαίων."},{"number":357,"text":"προσγενομένης οὖν καὶ τῆς περὶ τούτων φροντίδος τῇ προτέρᾳ συγχυθεὶς ὑπὸ ἀθυμίας εἰς νόσον κατέπεσεν, ἧς μηκυνομένης καὶ αὐξανόντων τῶν παθῶν συνείς, ὅτι μέλλοι τελευτᾶν, συγκαλεῖ τοὺς φίλους καὶ τήν τε νόσον αὐτοῖς χαλεπὴν οὖσαν ἐμήνυε καὶ ὅτι ταῦτα πάσχει κακώσας τὸ τῶν Ἰουδαίων ἔθνος παρεδήλου συλήσας τὸν ναὸν καὶ τοῦ θεοῦ καταφρονήσας, καὶ ταῦτα λέγων ἐξέπνευσεν."},{"number":358,"text":"ὥστε θαυμάζειν Πολύβιον τὸν Μεγαλοπολίτην, ὃς ἀγαθὸς ὢν ἀνὴρ ἀποθανεῖν λέγει τὸν Ἀντίοχον βουληθέντα τὸ τῆς ἐν Πέρσαις Ἀρτέμιδος ἱερὸν συλῆσαι· τὸ γὰρ μηκέτι ποιῆσαι τὸ ἔργον βουλευσάμενον οὐκ ἔστιν τιμωρίας ἄξιον."},{"number":359,"text":"εἰ δὲ διὰ τοῦτο Πολυβίῳ δοκεῖ καταστρέψαι τὸν βίον Ἀντίοχον οὕτως, πολὺ πιθανώτερον διὰ τὴν ἱεροσυλίαν τοῦ ἐν Ἱεροσολύμοις ναοῦ τελευτῆσαι τὸν βασιλέα. ἀλλὰ περὶ μὲν τούτου οὐ διαφέρομαι τὴν ὑπὸ τοῦ Μεγαλοπολίτου λεγομένην αἰτίαν ταύτην ὑφʼ ἡμῶν ἀληθῆ νομιζόντων."},{"number":360,"text":"Ὁ δʼ Ἀντίοχος πρὶν ἢ τελευτᾶν καλέσας Φίλιππον ἕνα τῶν ἑταίρων τῆς βασιλείας αὐτὸν ἐπίτροπον καθίστησιν, καὶ δοὺς αὐτῷ τὸ διάδημα καὶ τὴν στολὴν καὶ τὸν δακτύλιον Ἀντιόχῳ τῷ παιδὶ αὐτοῦ ταῦτα ἐκέλευσε κομίσαντα δοῦναι, δεηθεὶς προνοῆσαι τῆς ἀνατροφῆς αὐτοῦ καὶ τηρῆσαι τὴν βασιλείαν ἐκείνῳ."},{"number":361,"text":"ἀπέθανεν δὲ Ἀντίοχος ἐνάτῳ καὶ τεσσαρακοστῷ καὶ ἑκατοστῷ ἔτει. Λυσίας δὲ τὸν θάνατον αὐτοῦ δηλώσας τῷ πλήθει τὸν υἱὸν αὐτοῦ Ἀντίοχον, αὐτὸς γὰρ εἶχεν τὴν ἐπιμέλειαν, ἀποδείκνυσι βασιλέα καλέσας αὐτὸν Εὐπάτορα."},{"number":362,"text":"Ἐν δὲ τούτῳ τῷ καιρῷ οἱ ἐν τῇ ἄκρᾳ τῶν Ἱεροσολύμων φρουροὶ καὶ φυγάδες τῶν Ἰουδαίων πολλὰ τοὺς Ἰουδαίους εἰργάσαντο· τοὺς γὰρ ἀναβαίνοντας εἰς τὸ ἱερὸν καὶ θῦσαι βουλομένους ἐξαίφνης ἐκτρέχοντες οἱ φρουροὶ διέφθειραν· ἐπέκειτο γὰρ τῷ ἱερῷ ἡ ἄκρα."},{"number":363,"text":"τούτων οὖν συμβαινόντων αὐτοῖς Ἰούδας ἐξελεῖν διέγνω τὴν φρουράν, καὶ συναγαγὼν τὸν λαὸν ἅπαντα τοὺς ἐν τῇ ἄκρᾳ καρτερῶς ἐπολιόρκει. ἔτος ἦν τοῦτο τῆς ἀρχῆς τοῖς ἀπὸ Σελεύκου ἑκατοστὸν καὶ πεντηκοστόν. κατασκευάσας οὖν μηχανήματα καὶ χώματα ἐγείρας φιλοπόνως προσέκειτο τῇ τῆς ἄκρας αἱρέσει."},{"number":364,"text":"πολλοὶ δὲ τῶν ἐν αὐτῇ φυγάδων νύκτωρ ἐξελθόντες εἰς τὴν χώραν καί τινας τῶν ὁμοίων καὶ ἀσεβῶν συναγαγόντες ἧκον πρὸς Ἀντίοχον τὸν βασιλέα, οὐκ ἀξιοῦντες ἑαυτοὺς ὑπερορᾶσθαι δεινὰ πάσχοντας ὑπὸ τῶν ὁμοφύλων καὶ ταῦθʼ ὑπομένοντας διὰ τὸν πατέρα αὐτοῦ, τὴν μὲν πάτριον αὐτῶν καταλύσαντας θρησκείαν, ἣν δὲ προσέταξεν ταύτης ἀντιποιουμένους·"},{"number":365,"text":"κινδυνεύειν οὖν ὑπὸ Ἰούδου καὶ τῶν σὺν αὐτῷ τὴν ἀκρόπολιν αἱρεθῆναι καὶ τοὺς φρουροὺς τοὺς ὑπὸ τοῦ βασιλέως κατασταθέντας, εἰ μή τις παρʼ αὐτοῦ βοήθεια πεμφθείη."},{"number":366,"text":"ταῦτʼ ἀκούσας ὁ παῖς Ἀντίοχος ὠργίσθη καὶ τοὺς ἡγεμόνας καὶ φίλους μεταπεμψάμενος ἐκέλευσε μισθοφόρους συναγαγεῖν καὶ ἐκ τῆς βασιλείας τοὺς στρατεύσιμον ἡλικίαν ἔχοντας. καὶ συνήχθη στρατὸς πεζῶν μὲν ὡσεὶ δέκα μυριάδες, ἱππεῖς δὲ δισμύριοι, ἐλέφαντες δὲ δύο καὶ τριάκοντα."},{"number":367,"text":"Ταύτην οὖν ἀναλαβὼν τὴν δύναμιν ἐξώρμησεν ἐκ τῆς Ἀντιοχείας μετὰ Λυσίου πάσης τῆς στρατιᾶς ἔχοντος τὴν ἡγεμονίαν. καὶ παραγενόμενος εἰς τὴν Ἰδουμαίαν ἐκεῖθεν εἰς Βηθσοῦραν ἀναβαίνει πόλιν σφόδρα ἐχυρὰν καὶ δυσάλωτον καὶ περικαθίσας ἐπολιόρκει τὴν πόλιν."},{"number":368,"text":"ἰσχυρῶς δὲ ἀντεχόντων τῶν Βηθσουραίων καὶ τὴν παρασκευὴν αὐτοῦ τῶν μηχανημάτων ἐμπρησάντων, ἐπεξῆλθον γὰρ αὐτῷ, χρόνος ἐτρίβετο πολὺς περὶ τὴν πολιορκίαν."},{"number":369,"text":"Ἰούδας δὲ τὴν ἔφοδον τοῦ βασιλέως ἀκούσας ἀφίσταται μὲν τοῦ τὴν ἄκραν πολιορκεῖν, ἀπαντήσας δὲ τῷ βασιλεῖ βάλλεται στρατόπεδον ἐπὶ τῶν στενῶν ἔν τινι τόπῳ Βεθζαχαρίᾳ λεγομένῳ σταδίους ἀπέχοντι τῶν πολεμίων ἑβδομήκοντα."},{"number":370,"text":"ὁ δὲ βασιλεὺς ὁρμήσας ἀπὸ τῆς Βεθσούρας ἤγαγε τὴν δύναμιν ἐπὶ τὰ στενὰ καὶ τὸ τοῦ Ἰούδα στρατόπεδον, ἅμʼ ἡμέρᾳ δὲ πρὸς μάχην διέτασσε τὴν στρατιάν."},{"number":371,"text":"τοὺς μὲν οὖν ἐλέφαντας ἐποίησεν ἀλλήλοις ἕπεσθαι διὰ τὴν στενοχωρίαν οὐ δυναμένων αὐτῶν ἐπὶ πλάτος τετάχθαι, εἰς δὲ κύκλον ἐλέφαντος ἑκάστου συμπροῇσαν πεζοὶ μὲν χίλιοι, ἱππεῖς δὲ πεντακόσιοι· ἔφερον δὲ οἱ ἐλέφαντες πύργους τε ὑψηλοὺς καὶ τοξότας· τὴν δὲ λοιπὴν δύναμιν ἑκατέρωθεν ἐποίησεν ἀναβαίνειν ἐπὶ τὰ ὄρη φίλους αὐτῆς προτάξας."},{"number":372,"text":"κελεύσας δὲ ἀλαλάξαι τὴν στρατιὰν προσβάλλει τοῖς πολεμίοις, γυμνώσας τάς τε χρυσᾶς καὶ χαλκᾶς ἀσπίδας, ὥστε αὐγὴν ἀπʼ αὐτῶν ἀφίεσθαι λαμπράν· συνεπήχει δὲ τὰ ὄρη κεκραγότων αὐτῶν. ταῦτα ὁρῶν ὁ Ἰούδας οὐ κατεπλάγη, δεξάμενος δὲ γενναίως τοὺς πολεμίους τῶν προδρόμων περὶ ἑξακοσίους ἀναιρεῖ."},{"number":373,"text":"Ἐλεάζαρος δʼ ὁ ἀδελφὸς αὐτοῦ, ὃν Αὐρὸν ἐκάλουν, ἰδὼν τὸν ὑψηλότατον τῶν ἐλεφάντων ὡπλισμένον θώραξι βασιλικοῖς καὶ νομίζων ἐπʼ αὐτοῦ τὸν βασιλέα εἶναι παρεβάλετο σφόδρα εὐκαρδίως ἐπʼ αὐτὸν ὁρμήσας, καὶ πολλοὺς μὲν τῶν περὶ τὸν ἐλέφαντα κτείνας τοὺς ἄλλους διεσκέδασεν, ὑποδὺς δὲ ὑπὸ τὴν γαστέρα καὶ πλήξας ἀπέκτεινε τὸν ἐλέφαντα."},{"number":374,"text":"ὁ δʼ ἐπικατενεχθεὶς τῷ Ἐλεαζάρῳ διαφθείρει τὸν ἄνδρα ὑπὸ τοῦ βάρους. καὶ οὗτος μὲν εὐψύχως πολλοὺς τῶν ἐχθρῶν ἀπολέσας τῷ τρόπῳ τούτῳ τὸν βίον κατέστρεψεν."},{"number":375,"text":"Ὁ δὲ Ἰούδας ὁρῶν τὴν τῶν πολεμίων ἰσχὺν ἀνεχώρησεν εἰς Ἱεροσόλυμα καὶ πρὸς πολιορκίαν παρεσκευάζετο· Ἀντίοχος δὲ τὸ μέν τι τῆς στρατιᾶς εἰς Βεθσοῦραν ἔπεμψεν πολεμήσων αὐτήν, τῷ δὲ λοιπῷ τῆς δυνάμεως αὐτὸς ἧκεν εἰς Ἱεροσόλυμα."},{"number":376,"text":"οἱ μὲν οὖν Βεθσουρῖται τὴν ἰσχὺν καταπλαγέντες καὶ σπανίζοντα βλέποντες τὰ ἐπιτήδεια παραδιδόασιν ἑαυτοὺς ὅρκους λαβόντες ὑπὲρ τοῦ μηδὲν πείσεσθαι κακὸν ὑπὸ τοῦ βασιλέως. Ἀντίοχος δὲ λαβὼν τὴν πόλιν ἄλλο μὲν αὐτοὺς οὐδὲν διέθηκεν, μόνον δὲ γυμνοὺς ἐξέβαλεν, φρουρὰν δὲ κατέστησεν ἰδίαν ἐν τῇ πόλει."},{"number":377,"text":"πολλῷ δὲ χρόνῳ τὸ ἱερὸν πολιορκῶν τὸ ἐν Ἱεροσολύμοις προσεκαθέζετο καρτερῶς τῶν ἔνδοθεν ἀμυνομένων· πρὸς ἕκαστον γὰρ ὧν ὁ βασιλεὺς ἐπʼ αὐτοὺς ἔστησε μηχάνημα κἀκεῖνοι πάλιν ἀντεμηχανῶντο."},{"number":378,"text":"τροφὴ δʼ αὐτοὺς ἐπιλελοίπει, τοῦ μὲν ὄντος ἀπανηλωμένου καρποῦ, τῆς δὲ γῆς ἐκείνῳ τῷ ἔτει μὴ γεωργημένης, ἀλλὰ διὰ τὸ εἶναι τὸ ἕβδομον ἔτος, καθʼ ὃ νόμος ἡμῖν ἀργὴν ἐᾶν τὴν χώραν, ἀσπόρου μεμενηκυίας. πολλοὶ τοιγαροῦν τῶν πολιορκουμένων ἀπεδίδρασκον διὰ τὴν τῶν ἀναγκαίων ἀπορίαν, ὡς ὀλίγους ἐν τῷ ἱερῷ καταλειφθῆναι."},{"number":379,"text":"Καὶ τοῖς μὲν πολιορκουμένοις ἐν τῷ ἱερῷ τοιαῦτα συνέβαινεν εἶναι τὰ πράγματα. Λυσίας δὲ ὁ στρατηγὸς καὶ ὁ βασιλεύς, ἐπεὶ Φίλιππος αὐτοῖς ἀπὸ τῆς Περσίδος ἥκων ἐδηλώθη καὶ τὰ πράγματα εἰς αὐτὸν κατασκευάζειν, εἶχον μὲν ὥστε τὴν πολιορκίαν ἀφέντες ὁρμᾶν ἐπὶ τὸν Φίλιππον, οὐ μὴν τοῦτο ποιῆσαι φανερὸν τοῖς στρατιώταις καὶ τοῖς ἡγεμόσιν ἔγνωσαν,"},{"number":380,"text":"ἀλλʼ ἐκέλευσεν τὸν Λυσίαν ὁ βασιλεὺς αὐτῷ τε καὶ τοῖς ἡγεμόσιν ἐν κοινῷ διαλεχθῆναι μηδὲν μὲν τῶν περὶ Φίλιππον ἐμφανίζοντα, τὴν δὲ πολιορκίαν ὅτι χρονιωτάτη γένοιτʼ ἂν δηλοῦντα, καὶ τὴν ὀχυρότητα τοῦ χωρίου, καὶ ὅτι τὰ τῆς τροφῆς αὐτοῖς ἤδη ἐπιλείποι, καὶ ὡς πολλὰ δεῖ καταστῆσαι τῶν ἐν τῇ βασιλείᾳ πραγμάτων,"},{"number":381,"text":"καὶ ὡς δοκεῖ πολὺ κρεῖττον εἶναι σπονδὰς ποιησαμένους πρὸς τοὺς πολιορκουμένους καὶ φιλίαν πρὸς ὅλον αὐτῶν τὸ ἔθνος ἐπιτρέψαντας αὐτοῖς χρῆσθαι τοῖς πατρίοις νόμοις, ὧν ἀφαιρεθέντες νῦν ἐξεπολεμώθησαν, χωρεῖν ἐπὶ τὰ οἰκεῖα. ταῦτα τοῦ Λυσίου φήσαντος ἠρέσθη τό τε στράτευμα καὶ οἱ ἡγεμόνες τῇ γνώμῃ."},{"number":382,"text":"Καὶ πέμψας ὁ βασιλεὺς πρὸς τὸν Ἰούδαν καὶ τοὺς σὺν αὐτῷ πολιορκουμένους εἰρήνην τε ἐπηγγείλατο καὶ συγχωρεῖν τοῖς πατρίοις νόμοις χρωμένους ζῆν. οἱ δὲ ἀσμένως δεξάμενοι τοὺς λόγους λαβόντες ὅρκους τε καὶ πίστεις ἐξῆλθον ἐκ τοῦ ἱεροῦ."},{"number":383,"text":"εἰσελθὼν δὲ Ἀντίοχος εἰς αὐτὸ καὶ θεασάμενος ὀχυρὸν οὕτως τὸ χωρίον παρέβη τοὺς ὅρκους καὶ κελεύει τὴν δύναμιν παραστᾶσαν καθελεῖν τὸ τεῖχος εἰς ἔδαφος. καὶ ταῦτα ποιήσας ἀνέστρεψεν εἰς Ἀντιόχειαν ἐπαγόμενος Ὀνίαν τὸν ἀρχιερέα, ὃς καὶ Μενέλαος ἐκαλεῖτο."},{"number":384,"text":"Λυσίας γὰρ συνεβούλευσεν τῷ βασιλεῖ τὸν Μενέλαον ἀνελεῖν, εἰ βούλεται τοὺς Ἰουδαίους ἠρεμεῖν καὶ μηδὲν ἐνοχλεῖν αὐτῷ· τοῦτον γὰρ ἄρξαι τῶν κακῶν πείσαντʼ αὐτοῦ τὸν πατέρα τοὺς Ἰουδαίους ἀναγκάσαι τὴν πάτριον θρησκείαν καταλιπεῖν."},{"number":385,"text":"πέμψας οὖν τὸν Μενέλαον ὁ βασιλεὺς εἰς Βέροιαν τῆς Συρίας διέφθειρεν ἀρχιερατεύσαντα μὲν ἔτη δέκα, πονηρὸν δὲ γενόμενον καὶ ἀσεβῆ καὶ ἵνα αὐτὸς ἄρχῃ τὸ ἔθνος ἀναγκάσαντα τοὺς ἰδίους παραβῆναι νόμους. ἀρχιερεὺς δὲ ἐγένετο μετὰ τὸν Μενελάου θάνατον Ἄλκιμος ὁ καὶ Ἰάκιμος κληθείς."},{"number":386,"text":"ὁ δὲ βασιλεὺς Ἀντίοχος ὁρῶν ἤδη τὸν Φίλιππον κρατοῦντα τῶν πραγμάτων ἐπολέμει πρὸς αὐτὸν καὶ λαβὼν αὐτὸν ὑποχείριον ἀπέκτεινεν."},{"number":387,"text":"ὁ δὲ τοῦ ἀρχιερέως υἱὸς Ὀνίας, ὃν προείπομεν ἔτι παῖδα τελευτήσαντος ἀφίεσθαι τοῦ πατρός, ἰδὼν ὅτι τὸν θεῖον αὐτοῦ Μενέλαον ὁ βασιλεὺς ἀνελὼν τὴν ἀρχιερωσύνην Ἀλκίμῳ δέδωκεν οὐκ ὄντι τῆς τῶν ἀρχιερέων γενεᾶς, ἀλλʼ ὑπὸ Λυσίου πεισθεὶς μεταθεῖναι τὴν τιμὴν ἀπὸ ταύτης τῆς οἰκίας εἰς ἕτερον οἶκον, φεύγει πρὸς Πτολεμαῖον τὸν Αἰγύπτου βασιλέα."},{"number":388,"text":"καὶ τιμῆς ἀξιωθεὶς ὑπό τε αὐτοῦ καὶ τῆς γυναικὸς Κλεοπάτρας λαμβάνει τόπον ἀξιώσας ἐν τῷ νομῷ τῷ Ἡλιοπολίτῃ, ἐν ᾧ καὶ ὅμοιον τῷ ἐν Ἱεροσολύμοις ᾠκοδόμησεν ἱερόν. περὶ τούτου μὲν οὖν εὐκαιρότερον ἡμῖν ἔσται διελθεῖν."}],"10":[{"number":389,"text":"Ὑπὸ δὲ τὸν αὐτὸν καιρὸν φυγὼν Δημήτριος ἀπὸ Ῥώμης ὁ Σελεύκου υἱὸς καὶ καταλαβόμενος τῆς Συρίας Τρίπολιν περιτίθησιν μὲν ἑαυτῷ διάδημα, συναγαγὼν δέ τινας περὶ αὐτὸν μισθοφόρους εἰς τὴν βασιλείαν εἰσῆλθεν, πάντων αὐτὸν ἡδέως προσδεχομένων καὶ παραδιδόντων αὑτούς."},{"number":390,"text":"συλλαβόντες δὲ καὶ Ἀντίοχον τὸν βασιλέα καὶ Λυσίαν ζῶντας ἀνάγουσιν αὐτῷ. καὶ οὗτοι μὲν κελεύσαντος Δημητρίου παραχρῆμα διεφθάρησαν βασιλεύσαντος Ἀντιόχου ἔτη δύο, καθὼς ἤδη που καὶ ἐν ἄλλῳ δεδήλωται."},{"number":391,"text":"συστραφέντες δὲ πρὸς αὐτὸν πολλοὶ τῶν Ἰουδαίων πονηροὶ καὶ φυγάδες καὶ μετʼ αὐτῶν Ἄλκιμος ὁ ἀρχιερεύς, κατηγόρουν τοῦ ἔθνους παντὸς καὶ Ἰούδα καὶ τῶν ἀδελφῶν αὐτοῦ,"},{"number":392,"text":"λέγοντες ὡς τοὺς φίλους αὐτοῦ πάντας ἀπεκτόνασιν καὶ ὅσοι τὰ ἐκείνου φρονοῦντες καὶ περιμένοντες αὐτὸν ὑπῆρχον ἐν τῇ βασιλείᾳ τούτους ἀπολωλέκασιν αὐτούς τε τῆς οἰκείας γῆς ἐκβαλόντες ἀλλοτρίας ἐπήλυδας πεποιήκασιν, ἠξίουν τε πέμψαντα τῶν ἰδίων τινὰ φίλων γνῶναι διʼ αὐτοῦ τὰ ὑπὸ τῶν περὶ Ἰούδαν τετολμημένα."},{"number":393,"text":"Ὁ δὲ Δημήτριος παροξυνθεὶς ἐκπέμπει Βακχίδην φίλον Ἀντιόχου τοῦ Ἐπιφανοῦς βασιλέως, ἄνδρα χρηστὸν καὶ τὴν Μεσοποταμίαν ἅπασαν πεπιστευμένον, δοὺς αὐτῷ δύναμιν καὶ τὸν ἀρχιερέα παραθέμενος αὐτῷ Ἄλκιμον ἐντειλάμενος ἀποκτεῖναι Ἰούδαν καὶ τοὺς σὺν αὐτῷ."},{"number":394,"text":"ἐξορμήσας δὲ ἀπὸ τῆς Ἀντιοχείας ὁ Βακχίδης μετὰ τῆς δυνάμεως καὶ παραγενόμενος εἰς τὴν Ἰουδαίαν ἔπεμψε πρὸς τὸν Ἰούδαν καὶ τοὺς ἀδελφοὺς αὐτοῦ περὶ φιλίας καὶ εἰρήνης διαλεγόμενος· δόλῳ γὰρ αὐτὸν ἐβούλετο λαβεῖν."},{"number":395,"text":"ὁ δʼ οὐκ ἐπίστευσεν· ἑώρα γάρ, ὅτι μετὰ στρατιᾶς πάρεστιν τοσαύτης, μεθʼ ὅσης ἐπὶ πόλεμόν τις, ἀλλʼ οὐκ ἐπʼ εἰρήνην ἔρχεται. τινὲς μέντοι γε τῶν ἐκ τοῦ δήμου προσέχοντες οἷς ὁ Βακχίδης ἐπεκηρυκεύσατο καὶ νομίσαντες οὐδὲν αὐτοὺς ὑπὸ Ἀλκίμου πείσεσθαι δεινὸν ὄντος ὁμοφύλου πρὸς αὐτοὺς ἀνεχώρησαν,"},{"number":396,"text":"καὶ λαβόντες ὅρκους παρʼ ἀμφοτέρων μήτε αὐτούς τι παθεῖν μήτε τοὺς ἐκ τῆς αὐτῆς ὄντας προαιρέσεως ἐπίστευσαν αὑτοὺς ἐκείνοις. ὁ δὲ Βακχίδης ὀλιγωρήσας τῶν ὅρκων ἑξήκοντα μὲν αὐτῶν ἀπέκτεινεν, τοὺς δὲ ἄλλους, ὅσοι διενοοῦντο πρὸς αὐτὸν ἀναχωρεῖν, ἐπέστρεψεν τοῖς πρώτοις τὴν πίστιν μὴ φυλάξας."},{"number":397,"text":"ἐπεὶ δʼ ἐκ τῶν Ἱεροσολύμων ἀπελθὼν κατὰ κώμην Βηρζηθὼ λεγομένην ἐγένετο, πέμψας συλλαμβάνει πολλοὺς τῶν αὐτομολούντων καί τινας τοῦ λαοῦ καὶ πάντας ἀποκτείνας προσέταξεν τοῖς ἐν τῇ χώρᾳ πᾶσιν ὑπακούειν Ἀλκίμῳ, καὶ μετὰ στρατιᾶς τινος, ἵνʼ ἔχῃ τηρεῖν τὴν χώραν αὐτοῦ, καταλιπὼν αὐτὸν εἰς Ἀντιόχειαν πρὸς τὸν βασιλέα Δημήτριον ὑπέστρεψεν."},{"number":398,"text":"Ἄλκιμος δὲ τὴν ἀρχὴν αὐτοῦ βουλόμενος βεβαιώσασθαι καὶ συνείς, ὅτι κατασκευάσας εὔνουν τὸ πλῆθος ἀσφαλέστερον ἄρξει, χρηστοῖς ἅπαντας ὑπήγετο λόγοις καὶ πρὸς ἡδονὴν ἑκάστῳ καὶ χάριν ὁμιλῶν ταχὺ δὴ μάλα χεῖρα πολλὴν καὶ δύναμιν περιεβάλετο·"},{"number":399,"text":"τούτων δʼ ἦσαν οἱ πλείους ἐκ τῶν ἀσεβῶν καὶ πεφυγαδευμένων, οἷς ὑπηρέταις καὶ στρατιώταις χρώμενος ἐπήρχετο τὴν χώραν καὶ ὅσους ἐν αὐτῇ τὰ Ἰούδα φρονοῦντας ηὕρισκεν ἐφόνευεν."},{"number":400,"text":"ὁρῶν δὲ τὸν Ἄλκιμον ἤδη μέγαν ὁ Ἰούδας γινόμενον καὶ πολλοὺς διεφθαρκότα τῶν ἀγαθῶν καὶ ὁσίων τοῦ ἔθνους, καὶ αὐτὸς ἐπιπορευόμενος τὴν χώραν διέφθειρεν τοὺς ταὐτὰ ἐκείνῳ φρονοῦντας. βλέπων δὲ ἑαυτὸν Ἄλκιμος ἀντέχειν τῷ Ἰούδᾳ μὴ δυνάμενον, ἀλλʼ ἡττώμενον αὐτοῦ τῆς ἰσχύος, ἐπὶ τὴν παρὰ Δημητρίου τοῦ βασιλέως συμμαχίαν ἔγνω τραπέσθαι."},{"number":401,"text":"παραγενόμενος οὖν εἰς Ἀντιόχειαν παρώξυνεν αὐτὸν ἐπὶ τὸν Ἰούδαν, κατηγορῶν ὡς πολλὰ μὲν ὑπʼ αὐτοῦ πεπόνθοι κακά, πλείω δὲ γένοιτʼ ἄν, εἰ μὴ προκαταληφθείη καὶ δοίη δίκην δυνάμεως ἐπʼ αὐτὸν ἰσχυρᾶς ἀποσταλείσης."},{"number":402,"text":"Ὁ δὲ Δημήτριος τοῦτʼ ἤδη καὶ τοῖς ἰδίοις αὐτοῦ πράγμασιν ἐπισφαλὲς ἡγησάμενος εἶναι τὸ περιιδεῖν Ἰούδαν ἐν ἰσχύι τοσαύτῃ γενόμενον, ἐκπέμπει Νικάνορα τὸν εὐνούστατον αὐτῷ καὶ πιστότατον τῶν φίλων, οὗτος γάρ ἐστιν ὁ καὶ ἀπὸ τῆς Ῥωμαίων πόλεως αὐτῷ συμφυγών, καὶ δοὺς δύναμιν ὅσην ὑπέλαβεν ἀρκέσειν αὐτῷ πρὸς τὸν Ἰούδαν ἐκέλευσεν μηδεμίαν φειδὼ ποιεῖσθαι τοῦ ἔθνους."},{"number":403,"text":"ὁ δὲ Νικάνωρ παραγενόμενος εἰς Ἱεροσόλυμα πολεμεῖν μὲν εὐθὺς οὐ διέγνω τῷ Ἰούδᾳ, δόλῳ δʼ ὑποχείριον λαβεῖν κρίνας προσπέμπει λόγους εἰρηνικοὺς αὐτῷ, μηδεμίαν μὲν ἀνάγκην εἶναι φάσκων πολεμεῖν καὶ κινδυνεύειν, ὅρκους δʼ αὐτῷ διδόναι περὶ τοῦ μηδὲν πείσεσθαι δεινόν· ἥκειν γὰρ μετὰ φίλων ἐπὶ τῷ ποιῆσαι φανερὰν αὐτοῖς τὴν Δημητρίου τοῦ βασιλέως διάνοιαν, ὡς περὶ τοῦ γένους αὐτῶν φρονεῖ."},{"number":404,"text":"ταῦτα διαπρεσβευσαμένου τοῦ Νικάνορος ὁ Ἰούδας καὶ οἱ ἀδελφοὶ αὐτοῦ πεισθέντες καὶ μηδεμίαν ἀπάτην ὑποπτεύσαντες διδόασιν πίστεις αὐτῷ καὶ δέχονται τὸν Νικάνορα μετὰ τῆς δυνάμεως. ὁ δὲ ἀσπασάμενος τὸν Ἰούδαν καὶ μεταξὺ προσομιλῶν δίδωσι τοῖς οἰκείοις τι σημεῖον, ὅπως συλλάβωσι τὸν Ἰούδαν."},{"number":405,"text":"ὁ δὲ συνεὶς τὴν ἐπιβουλὴν ἐκπηδήσας πρὸς τοὺς ἰδίους συνέφυγεν. φανερᾶς δὲ τῆς προαιρέσεως αὐτοῦ καὶ τῆς ἐνέδρας ὁ Νικάνωρ γενομένης πολεμεῖν ἔκρινεν τῷ Ἰούδᾳ, καὶ συγκροτήσας καὶ παρασκευασάμενος τὰ πρὸς τὴν μάχην συμβάλλει κατά τινα κώμην Καφαρσαλαμὰ καὶ νικήσας ἀναγκάζει τὸν Ἰούδαν ἐπὶ τὴν ἐν τοῖς Ἱεροσολύμοις ἄκραν φεύγειν."},{"number":406,"text":"Ἔτι δʼ αὐτῷ κατιόντι ἀπὸ τῆς ἄκρας εἰς τὸ ἱερὸν ἀπαντήσαντες τῶν ἱερέων τινὲς καὶ πρεσβυτέρων ἠσπάζοντο καὶ τὰς θυσίας ἐπεδείκνυον, ἃς ὑπὲρ τοῦ βασιλέως ἔλεγον ἐπιφέρειν τῷ θεῷ. ὁ δὲ βλασφημήσας αὐτοὺς ἠπείλησεν, εἰ μὴ παραδοίη τὸν Ἰούδαν ὁ λαὸς αὐτῷ, καθαιρήσειν ὅταν ἐπανέλθῃ τὸν ναόν."},{"number":407,"text":"καὶ ὁ μὲν ταῦτʼ ἀπειλήσας ἐξῆλθεν ἀπὸ τῶν Ἱεροσολύμων, οἱ δʼ ἱερεῖς εἰς δάκρυα διὰ τὴν ἐπὶ τοῖς εἰρημένοις λύπην προέπεσον καὶ τὸν θεὸν ἱκέτευον ῥύσασθαι ἐκ τῶν πολεμίων αὐτούς."},{"number":408,"text":"ὁ δὲ Νικάνωρ, ὡς ἐκ τῶν Ἱεροσολύμων ἐξελθὼν ἐγένετο κατά τινα κώμην Βηθωρου λεγομένην, αὐτόθι στρατοπεδεύεται προσγενομένης αὐτῷ καὶ ἄλλης ἀπὸ Συρίας δυνάμεως· Ἰούδας δὲ ἐν Ἀδασοῖς ἑτέρᾳ κώμῃ σταδίους ἀπεχούσῃ τριάκοντα τῆς Βηθωροῦ στρατοπεδεύεται δισχιλίους στρατιώτας ἔχων."},{"number":409,"text":"τούτους παρορμήσας μὴ καταπλαγῆναι τὸ τῶν ἐναντίων πλῆθος, μηδὲ λογίζεσθαι πρὸς πόσους ἀγωνίζεσθαι μέλλουσιν, ἀλλὰ τίνες ὄντες καὶ περὶ οἵων ἐπάθλων κινδυνεύουσιν ἐνθυμουμένους εὐψύχως ὁμόσε χωρῆσαι τοῖς πολεμίοις, ἐπὶ τὴν μάχην ἐξάγει, καὶ συμβαλὼν τῷ Νικάνορι καὶ καρτερᾶς τῆς μάχης γενομένης κρατεῖ τῶν ἐναντίων καὶ πολλούς τε αὐτῶν ἀπέκτεινεν καὶ τελευταῖον αὐτὸς ὁ Νικάνωρ λαμπρῶς ἀγωνιζόμενος ἔπεσεν."},{"number":410,"text":"οὗ πεσόντος οὐδὲ τὸ στράτευμα ἔμεινεν, ἀλλὰ τὸν στρατηγὸν ἀπολέσαντες εἰς φυγὴν ἐτράπησαν ῥίψαντες τὰς πανοπλίας. ἐπιδιώκων δὲ ὁ Ἰούδας ἐφόνευσεν καὶ ταῖς σάλπιγξι ταῖς πέριξ κώμαις ἐσήμαινεν, ὅτι νικῴη τοὺς πολεμίους."},{"number":411,"text":"οἱ δʼ ἐν αὐταῖς ἀκούσαντες ἐξεπήδων ὡπλισμένοι καὶ τοῖς φεύγουσιν ὑπαντῶντες ἔκτεινον αὐτοὺς γενόμενοι κατὰ πρόσωπον, ὥστʼ ἐκ τῆς μάχης ταύτης οὐδεὶς διέφυγεν ὄντων αὐτῶν ἐννακισχιλίων."},{"number":412,"text":"τὴν δὲ νίκην συνέβη γενέσθαι ταύτην τῇ τρισκαιδεκάτῃ τοῦ μηνὸς τοῦ λεγομένου παρὰ μὲν Ἰουδαίοις Ἄδαρ κατὰ δὲ Μακεδόνας Δύστρου. ἄγουσιν δʼ ἐν τούτῳ τὰ νικητήρια κατὰ πᾶν ἔτος καὶ ἑορτὴν νομίζουσι τὴν ἡμέραν. ἐξ ἐκείνου μέντοι τοῦ χρόνου πρὸς ὀλίγον τὸ τῶν Ἰουδαίων ἔθνος τῶν πολέμων ἀναπαυσάμενον καὶ εἰρήνης ἀπολαῦον ἔπειτα εἰς ἀγῶνας πάλιν καὶ κινδύνους κατέστη."},{"number":413,"text":"Τῷ δʼ ἀρχιερεῖ τῷ Ἀλκίμῳ βουληθέντι καθελεῖν τὸ τεῖχος τοῦ ἁγίου παλαιὸν ὂν καὶ κατεσκευασμένον ὑπὸ τῶν ἀρχαίων προφητῶν, πληγή τις αἰφνίδιος ἐκ τοῦ θεοῦ προσέπεσεν, ὑφʼ ἧς ἄφωνός τε ἐπὶ τὴν γῆν κατηνέχθη καὶ βασανισθεὶς ἐπὶ συχνὰς ἡμέρας ἀπέθανεν ἀρχιερατεύσας ἔτη τέσσαρα."},{"number":414,"text":"τελευτήσαντος δὲ τούτου τὴν ἀρχιερωσύνην ὁ λαὸς τῷ Ἰούδᾳ δίδωσιν, ὃς ἀκούσας περὶ τῆς Ῥωμαίων δυνάμεως καὶ ὅτι καταπεπολεμήκασιν τήν τε Γαλατίαν καὶ τὴν Ἰβηρίαν καὶ Καρχηδόνα τῆς Λιβύης καὶ πρὸς τούτοις τὴν Ἑλλάδα κεχείρωνται καὶ τοὺς βασιλεῖς Περσέα καὶ Φίλιππον καὶ τὸν μέγαν Ἀντίοχον, ἔγνω φιλίαν ποιήσασθαι πρὸς αὐτούς."},{"number":415,"text":"πέμψας οὖν εἰς τὴν Ῥώμην τῶν αὐτοῦ φίλων Εὐπόλεμον τὸν Ἰωάννου υἱὸν καὶ Ἰάσονα τὸν Ἐλεαζάρου παρεκάλει διʼ αὐτῶν συμμάχους εἶναι καὶ φίλους, καὶ Δημητρίῳ γράψαι, ὅπως μὴ πολεμῇ τοὺς Ἰουδαίους."},{"number":416,"text":"ἐλθόντας δὲ εἰς τὴν Ῥώμην τοὺς παρὰ τοῦ Ἰούδα πρεσβευτὰς ἡ σύγκλητος δέχεται καὶ διαλεχθεῖσα περὶ ὧν ἐπέμφθησαν τὴν συμμαχίαν ἐπινεύει. ποιήσασα δὲ περὶ τούτου δόγμα τὸ μὲν ἀντίγραφον εἰς τὴν Ἰουδαίαν ἀπέστειλεν, αὐτὸ δʼ εἰς τὸ Καπετώλιον εἰς χαλκᾶς ἐγγράψαντες δέλτους ἀνέθεσαν."},{"number":417,"text":"ἦν δὲ τοιοῦτον· δόγμα συγκλήτου περὶ συμμαχίας καὶ εὐνοίας τῆς πρὸς τὸ ἔθνος τὸ Ἰουδαίων. μηδένα τῶν ὑποτεταγμένων Ῥωμαίοις πολεμεῖν τῷ Ἰουδαίων ἔθνει μηδὲ τοῖς πολεμοῦσι χορηγεῖν ἢ σῖτον ἢ πλοῖα ἢ χρήματα."},{"number":418,"text":"ἐὰν δὲ ἐπίωσί τινες Ἰουδαίοις, βοηθεῖν Ῥωμαίους αὐτοῖς κατὰ τὸ δυνατόν, καὶ πάλιν, ἂν τῇ Ῥωμαίων ἐπίωσίν τινες, Ἰουδαίους αὐτοῖς συμμαχεῖν. ἂν δέ τι πρὸς ταύτην τὴν συμμαχίαν θελήσῃ τὸ τῶν Ἰουδαίων ἔθνος ἢ προσθεῖναι ἢ ἀφελεῖν, τοῦτο κοινῇ γινέσθω γνώμῃ τοῦ δήμου τοῦ Ῥωμαίων, ὃ δʼ ἂν προστεθῇ τοῦτʼ εἶναι κύριον."},{"number":419,"text":"ἐγράφη τὸ δόγμα ὑπὸ Εὐπολέμου τοῦ Ἰωάννου παιδὸς καὶ ὑπὸ Ἰάσονος τοῦ Ἐλεαζάρου ἐπʼ ἀρχιερέως μὲν τοῦ ἔθνους Ἰούδα, στρατηγοῦ δὲ Σίμωνος τοῦ ἀδελφοῦ αὐτοῦ. καὶ τὴν μὲν πρώτην Ῥωμαίοις πρὸς Ἰουδαίους φιλίαν καὶ συμμαχίαν οὕτως συνέβη γενέσθαι."}],"11":[{"number":420,"text":"Δημήτριος δʼ ἀπαγγελθείσης αὐτῷ τῆς Νικάνορος τελευτῆς καὶ τῆς ἀπωλείας τοῦ σὺν αὐτῷ. στρατεύματος πάλιν τὸν Βακχίδην μετὰ δυνάμεως εἰς τὴν Ἰουδαίαν ἐξέπεμψεν."},{"number":421,"text":"ὃς ἐκ τῆς Ἀντιοχείας ἐξορμήσας καὶ παραγενόμενος εἰς τὴν Ἰουδαίαν ἐν Ἀρβήλοις πόλει τῆς Γαλιλαίας στρατοπεδεύεται, καὶ τοὺς ἐν τοῖς ἐκεῖ σπηλαίοις ὄντας, πολλοὶ γὰρ εἰς αὐτὰ συμπεφεύγεσαν, ἐκπολιορκήσας καὶ λαβὼν ἄρας ἐκεῖθεν ἐπὶ τὰ Ἱεροσόλυμα σπουδὴν ἐποιεῖτο."},{"number":422,"text":"μαθὼν δὲ τὸν Ἰούδαν ἔν τινι κώμῃ Ζηθῶ τοὔνομα κατεστρατοπεδευμένον ἐπʼ αὐτὸν ἠπείγετο μετὰ πεζῶν μὲν δισμυρίων, ἱππέων δὲ δισχιλίων· τῷ Ἰούδᾳ δʼ ἦσαν οἱ πάντες χίλιοι. οὗτοι τὸ Βακχίδου πλῆθος θεωρήσαντες ἔδεισαν καὶ τὴν παρεμβολὴν καταλιπόντες ἔφυγον πάντες πλὴν ὀκτακοσίων."},{"number":423,"text":"Ἰούδας δὲ καταλειφθεὶς ὑπὸ τῶν οἰκείων στρατιωτῶν καὶ τῶν πολεμίων ἐπικειμένων καὶ μηδένα καιρὸν αὐτῷ πρὸς συλλογὴν τῆς δυνάμεως ἐπιτρεπόντων οἷός τʼ ἦν μετὰ τῶν ὀκτακοσίων συμβαλεῖν τοῖς τοῦ Βακχίδου, καὶ προτρεπόμενός τε τούτους εὐψύχως ὑφίστασθαι τὸν κίνδυνον παρεκάλει χωρεῖν ἐπὶ τὴν μάχην."},{"number":424,"text":"τῶν δὲ λεγόντων, ὡς οὐκ εἰσὶ πρὸς τοσοῦτο μέγεθος στρατιᾶς ἀξιόμαχοι, συμβουλευόντων δὲ νῦν μὲν ἀναχωρεῖν καὶ σώζειν αὐτούς, αὖθις δὲ συναγαγόντας τοὺς ἰδίους τοῖς ἐχθροῖς συμβαλεῖν, μὴ τοῦτʼ, εἶπεν, ἥλιος ἐπίδοι γενόμενον, ἵνʼ ἐγὼ τὰ νῶτά μου δείξω τοῖς πολεμίοις."},{"number":425,"text":"ἀλλʼ εἰ καὶ τελευτὴν ὁ παρών μοι καιρὸς φέρει καὶ δεῖ πάντως ἀπολέσθαι μαχόμενον, στήσομαι γενναίως πᾶν ὑπομένων τὸ μέλλον ἢ τοῖς ἤδη κατωρθωμένοις καὶ τῇ περὶ αὐτῶν δόξῃ προσβαλῶ τὴν ἐκ τῆς νῦν φυγῆς ὕβριν. καὶ ὁ μὲν ταῦτα πρὸς τοὺς ὑπολειφθέντας παρακαλῶν τοῦ κινδύνου καταφρονήσαντας ὁμόσε χωρῆσαι τοῖς πολεμίοις ἔλεγεν."},{"number":426,"text":"Ὁ δὲ Βακχίδης ἐξαγαγὼν ἐκ τοῦ στρατοπέδου τὴν δύναμιν πρὸς μάχην παρετάσσετο, καὶ τοὺς μὲν ἱππεῖς ἐξ ἑκατέρων τῶν κεράτων ἔταξε, τοὺς δὲ ψιλοὺς καὶ τοξότας προέστησεν πάσης τῆς φάλαγγος, αὐτὸς δʼ ἦν ἐπὶ τοῦ δεξιοῦ."},{"number":427,"text":"οὕτως δὲ συντάξας τὴν στρατιὰν ἐπεὶ προσέμιξεν τῷ τῶν πολεμίων στρατοπέδῳ, σημῆναι τὸν σαλπικτὴν ἐκέλευσεν καὶ τὴν στρατιὰν ἀλαλάξασαν προσιέναι."},{"number":428,"text":"τὸ δʼ αὐτὸ ποιήσας ὁ Ἰούδας συμβάλλει τοῖς πολεμίοις, καὶ καρτερῶς ἀμφοτέρων ἀγωνιζομένων καὶ τῆς μάχης μέχρι δυσμῶν παρατεινομένης, ἰδὼν ὁ Ἰούδας τὸν Βακχίδην καὶ τὸ κρατερὸν τῆς στρατιᾶς ἐν τῷ δεξιῷ κέρατι τυγχάνον, παραλαβὼν τοὺς εὐψυχοτάτους ὥρμησεν ἐπʼ ἐκεῖνο τὸ μέρος τῆς τάξεως, καὶ προσβαλὼν τοῖς ἐκεῖ διέσπα αὐτῶν τὴν φάλαγγα."},{"number":429,"text":"ὠσάμενος δʼ εἰς μέσους εἰς φυγὴν ἐβιάσατο αὐτούς, καὶ διώκει μέχρι Ἐζᾶ ὄρους οὕτω λεγομένου. θεασάμενοι δὲ τὴν τροπὴν τῶν ἐν τῷ δεξιῷ κέρατι οἱ τὸ εὐώνυμον ἔχοντες ἐκυκλώσαντο τὸν Ἰούδαν διώκοντα καὶ λαμβάνουσι μέσον αὐτὸν κατόπιν γενόμενοι."},{"number":430,"text":"ὁ δὲ φυγεῖν οὐ δυνάμενος, ἀλλὰ περιεσχημένος ὑπὸ τῶν πολεμίων, στὰς ἐμάχετο μετὰ τῶν σὺν αὐτῷ. πολλοὺς δὲ κτείνας τῶν ἀντιπάλων καὶ κατάκοπος γενόμενος καὶ αὐτὸς ἔπεσεν, ἐπὶ καλοῖς μὲν πρότερον γεγενημένοις, ἐφʼ ὁμοίοις δὲ ὅτε ἀπέθνησκεν τὴν ψυχὴν ἀφείς."},{"number":431,"text":"πεσόντος δὲ Ἰούδα πρὸς μηδένα τὸ λοιπὸν ἀφορᾶν ἔχοντες οἱ σὺν αὐτῷ στρατηγοῦ δὲ τοιούτου στερηθέντες ἔφυγον."},{"number":432,"text":"λαβόντες δὲ τὸ σῶμα παρὰ τῶν πολεμίων ὑπόσπονδον Σίμων καὶ Ἰωνάθης ἀδελφοὶ τοῦ Ἰούδα, κομίσαντες εἰς τὴν Μωδεεῖν κώμην, ὅπου καὶ ὁ πατὴρ αὐτῶν τέθαπτο, κηδεύουσιν πενθήσαντος ἐπὶ συχνὰς αὐτὸν τοῦ πλήθους ἡμέρας καὶ τιμήσαντος κοινῇ τοῖς νενομισμένοις."},{"number":433,"text":"καὶ τέλος μὲν τοιοῦτον κατέσχεν Ἰούδαν, ἄνδρα γενναῖον καὶ μεγαλοπόλεμον γενόμενον καὶ τῶν τοῦ πατρὸς ἐντολῶν Ματταθίου μνήμονα καὶ πάνθʼ ὑπὲρ τῆς τῶν πολιτῶν ἐλευθερίας καὶ δρᾶσαι καὶ παθεῖν ὑποστάντα."},{"number":434,"text":"τοιοῦτος οὖν τὴν ἀρετὴν ὑπάρξας μέγιστον αὐτοῦ κλέος καὶ μνημεῖον κατέλιπεν, ἐλευθερώσας τὸ ἔθνος καὶ τῆς ὑπὸ Μακεδόσιν ἐξαρπάσας αὐτὸ δουλείας. τὴν δʼ ἀρχιερωσύνην ἔτος τρίτον κατασχὼν ἀπέθανεν."}]},"count":434};})();
